def _isolated_subproc_env(scratch_root: Path) -> Dict[str, str]:
    """
    로컬 비데몬 바이너리(forge, solc, duckdb) 실행 시 임시·홈·캐시 디렉토리를
    지정된 `scratch_root`(`audit_artifacts/` 내부)로 완벽히 격리한 클린 환경 사전을 생성한다.
    """
    tmp_d = (scratch_root / "_subproc_tmp").resolve()
    home_d = (scratch_root / "_subproc_home").resolve()
    tmp_d.mkdir(parents=True, exist_ok=True)
    home_d.mkdir(parents=True, exist_ok=True)
    sys_root = Path(sys.executable).resolve().drive or "C:"
    win_dir = f"{sys_root}\\Windows"
    sys32_dir = f"{win_dir}\\System32"
    foundry_dir = str((SCRIPT_DIR / "tools" / "foundry").resolve())
    duckdb_dir = str((SCRIPT_DIR / "tools" / "duckdb").resolve())
    toml_p = (scratch_root / "foundry.toml").resolve()
    env_dict: Dict[str, str] = {
        "SYSTEMROOT": win_dir,
        "WINDIR": win_dir,
        "SystemDrive": sys_root,
        "COMSPEC": f"{sys32_dir}\\cmd.exe",
        "PATH": os.pathsep.join([foundry_dir, duckdb_dir, sys32_dir, win_dir]),
        "PATHEXT": ".COM;.EXE;.BAT;.CMD",
        "TEMP": str(tmp_d),
        "TMP": str(tmp_d),
        "TMPDIR": str(tmp_d),
        "USERPROFILE": str(home_d),
        "HOME": str(home_d),
        "APPDATA": str(home_d),
        "LOCALAPPDATA": str(home_d),
        "XDG_CACHE_HOME": str(home_d / "xdg_cache"),
        "XDG_CONFIG_HOME": str(home_d / "xdg_config"),
        "XDG_DATA_HOME": str(home_d / "xdg_data"),
        "FOUNDRY_DIR": str(home_d / ".foundry"),
        "SVM_DATA_DIR": str(home_d / ".svm"),
        "FOUNDRY_OFFLINE": "true",
        "FOUNDRY_DISABLE_NIGHTLY_WARNING": "1",
        "RAYON_NUM_THREADS": str(_BG_SUBPROC_THREADS),
        "TOKIO_WORKER_THREADS": str(_BG_SUBPROC_THREADS),
        "ETHERSCAN_API_KEY": "",
        "NO_COLOR": "1",
        "HTTP_PROXY": "",
        "HTTPS_PROXY": "",
        "ALL_PROXY": "",
        "http_proxy": "",
        "https_proxy": "",
        "all_proxy": "",
        "NO_PROXY": "*,127.0.0.1,localhost,::1",
        "no_proxy": "*,127.0.0.1,localhost,::1",
    }
    if toml_p.is_file():
        env_dict["FOUNDRY_CONFIG"] = str(toml_p)
    return env_dict


