VERDICT_PROFIT: str = "취약점 재현 확정 (위험자산 한화 산출)"
_LEGACY_VERDICT_PROFIT: str = "한화 즉시 얼마 이익 가능"
VERDICT_SAFE: str = "안전"
VERDICT_BLOCKED: str = "미검증 차단"
VALID_VERDICTS: FrozenSet[str] = frozenset({
    VERDICT_SAFE,
    VERDICT_BLOCKED,
})
_DYNAMIC_PROFIT_VERDICT_RE = re.compile(
    r"^(?:취약점 재현 확정 \(위험자산 한화 ([1-9][0-9]{0,2}(?:,[0-9]{3})+|[1-9][0-9]{0,2})원\)"
    r"|한화 즉시 ([1-9][0-9]{0,2}(?:,[0-9]{3})+|[1-9][0-9]{0,2})원 이익 가능)$"
)


def _format_profit_verdict(net_krw: int) -> str:
    krw_int = int(net_krw)
    if krw_int <= 0:
        raise ValueError(f"Profit verdict requires positive KRW, got {net_krw!r}")
    return f"취약점 재현 확정 (위험자산 한화 {krw_int:,}원)"


def _profit_verdict_matches_krw(v: Any, net_krw: int) -> bool:
    try:
        krw_int = int(net_krw)
    except (TypeError, ValueError):
        return False
    if krw_int <= 0:
        return False
    s = str(v or "").strip()
    return s == _format_profit_verdict(krw_int) or s == f"한화 즉시 {krw_int:,}원 이익 가능"


def _is_profit_verdict(v: Any, allow_template: bool = False) -> bool:
    s = str(v or "").strip()
    if bool(_DYNAMIC_PROFIT_VERDICT_RE.match(s)):
        return True
    return bool(allow_template and s in (VERDICT_PROFIT, _LEGACY_VERDICT_PROFIT))


def _is_valid_verdict(v: Any, allow_template: bool = False) -> bool:
    s = str(v or "").strip()
    return s in VALID_VERDICTS or _is_profit_verdict(s, allow_template=allow_template)


