def _is_keyed_rpc_url(url: str) -> bool:
    u = str(url or "")
    if not u:
        return False
    if any(k in u for k in _ALL_EMBEDDED_API_KEYS):
        return True
    return bool(_URL_SECRET_QUERY_RE.search(u) or _URL_SECRET_PATH_RE.search(u))


def _redact_secrets_in_text(text: Any) -> str:
    s = str(text or "")
    if not s:
        return ""
    for k in _ALL_EMBEDDED_API_KEYS:
        if k in s:
            s = s.replace(k, "<REDACTED>")
    s = _URL_SECRET_QUERY_RE.sub(r"\1<REDACTED>", s)
    s = _URL_SECRET_PATH_RE.sub(r"\1<REDACTED>", s)
    s = _TEXT_SECRET_KV_RE.sub(r"\1<REDACTED>", s)
    return s


def _endpoint_storage_key(url: str) -> str:
    u = str(url or "").strip()
    if not u:
        return ""
    if not _is_keyed_rpc_url(u):
        return u
    kh = hashlib.sha256(u.encode("utf-8")).hexdigest()[:8]
    red = _redact_secrets_in_text(u)
    return f"{red}#k{kh}"

_ADDR_RE = re.compile(r"^0x[0-9a-fA-F]{40}$")
_ANY_ADDR_RE = re.compile(r"(?<![0-9a-fA-F])0x[0-9a-fA-F]{40}(?![0-9a-fA-F])")
_SLUG_CLEAN_RE = re.compile(r"[^a-z0-9]+")


def _norm_slug(raw: Any) -> str:
    s = str(raw or "").strip().lower()
    if not s:
        return ""
    lead = "_" if s.startswith("_") else ""
    body = _SLUG_CLEAN_RE.sub("-", s.lstrip("_")).strip("-")
    full = f"{lead}{body}" if body else lead
    if len(full) <= 64:
        return full
    h6 = hashlib.sha256(full.encode("utf-8")).hexdigest()[:6]
    prefix = full[:57].rstrip("-")
    return f"{prefix}-{h6}"


