def _hex_to_bytes(val: Any) -> bytes:
    if isinstance(val, (bytes, bytearray, memoryview)):
        return bytes(val)
    s = str(val or "").strip()
    if s.startswith(("0x", "0X")):
        s = s[2:]
    if len(s) % 2 == 1:
        s = "0" + s
    if not s:
        return b""
    try:
        return bytes.fromhex(s)
    except ValueError as exc:
        raise ABIError(f"Invalid hex data: {val!r}") from exc


def _hex_to_int(val: Any) -> int:
    if isinstance(val, int):
        return val
    s = str(val or "").strip()
    if not s or s in ("0x", "0X"):
        return 0
    try:
        return int(s, 16) if s.startswith(("0x", "0X")) else int(s, 10)
    except ValueError:
        return 0


def _hex_to_word32(val: Any) -> bytes:
    raw = _hex_to_bytes(val)
    if not raw:
        return b"\x00" * 32
    if len(raw) >= 32:
        return raw[-32:]
    return raw.rjust(32, b"\x00")


_DEC_ZERO: Decimal = Decimal("0")
_DEC_QUANT_18: Decimal = Decimal("0.000000000000000001")


def _to_dec(v: Any, default: Decimal = _DEC_ZERO) -> Decimal:
    if isinstance(v, Decimal):
        return v if v.is_finite() else default
    if v is None or isinstance(v, bool):
        return default
    if isinstance(v, int):
        return Decimal(v)
    try:
        d = Decimal(v) if isinstance(v, str) else Decimal(repr(v))
        return d if d.is_finite() else default
    except (DecimalException, ValueError, TypeError, OverflowError):
        return default


def _fmt_dec18(v: Decimal) -> str:
    with localcontext() as ctx:
        ctx.prec = 100
        q = max(_DEC_ZERO, v).quantize(_DEC_QUANT_18, rounding=ROUND_DOWN)
        return format(q, "f")


def _append_unique(items: List[Any], seen: Set[Any], val: Any) -> None:
    if val not in seen:
        seen.add(val)
        items.append(val)


def _split_top_level_csv(
    inner: str,
    *,
    open_chars: str = "([",
    close_chars: str = ")]",
    strict: bool = True,
) -> List[str]:
    if strict and not inner.strip():
        return []
    parts: List[str] = []
    depth = 0
    cur: List[str] = []
    for ch in inner:
        if ch in open_chars:
            depth += 1
            cur.append(ch)
        elif ch in close_chars:
            depth = (depth - 1) if strict else max(0, depth - 1)
            cur.append(ch)
        elif ch == "," and depth == 0:
            parts.append("".join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    if strict:
        if depth != 0:
            raise ABIError(f"Unbalanced ABI tuple: {inner}")
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
    elif cur:
        parts.append("".join(cur).strip())
    return parts


def _abi_tuple_elems(t: str) -> Optional[List[str]]:
    if t.startswith("(") and t.endswith(")"):
        return _split_top_level_csv(t[1:-1])
    return None


def _abi_is_dynamic(typ: str) -> bool:
    t = typ.strip()
    if t in ("bytes", "string") or t.endswith("[]"):
        return True
    if t.endswith("]"):
        lb = t.rfind("[")
        return _abi_is_dynamic(t[:lb])
    elems = _abi_tuple_elems(t)
    if elems is not None:
        return any(_abi_is_dynamic(sub) for sub in elems)
    return False


def _abi_static_word_size(typ: str) -> int:
    t = typ.strip()
    if _abi_is_dynamic(t):
        raise ABIError(f"Dynamic type has no fixed word size: {t}")
    if t.endswith("]"):
        lb = t.rfind("[")
        n = int(t[lb + 1:-1])
        return n * _abi_static_word_size(t[:lb])
    elems = _abi_tuple_elems(t)
    if elems is not None:
        return sum(_abi_static_word_size(sub) for sub in elems)
    return 32


def _abi_encode_seq(types: Sequence[str], values: Sequence[Any]) -> bytes:
    if len(types) != len(values):
        raise ABIError(f"ABI length mismatch: {len(types)} vs {len(values)}")
    head_slots: List[Optional[bytes]] = []
    tails: List[bytes] = []
    head_total = 0
    for t, v in zip(types, values):
        ts = t.strip()
        if _abi_is_dynamic(ts):
            head_slots.append(None)
            tails.append(_abi_encode_one(ts, v))
            head_total += 32
        else:
            enc = _abi_encode_one(ts, v)
            head_slots.append(enc)
            tails.append(b"")
            head_total += len(enc)
    out = bytearray()
    cur_off = head_total
    for h, tail in zip(head_slots, tails):
        if h is not None:
            out.extend(h)
        else:
            out.extend(cur_off.to_bytes(32, "big"))
            cur_off += len(tail)
    for h, tail in zip(head_slots, tails):
        if h is None:
            out.extend(tail)
    return bytes(out)


def _validate_abi_int_bits(raw_bits: Optional[str], kind: str, *, val: Any = None) -> int:
    bits = int(raw_bits or 256)
    if isinstance(val, bool) or bits < 8 or bits > 256 or (bits % 8) != 0:
        raise ABIError(f"Invalid {kind} type/bit width: {bits}")
    return bits


def _append_bounded_unique(dst: List[str], seen: Set[str], item: str, limit: int) -> bool:
    seen.add(item)
    dst.append(item)
    return len(dst) >= limit


def _parallel_map_list(
    fn: Callable[[Any], Any],
    items: Sequence[Any],
    *,
    max_workers: int,
    parallel: bool,
) -> List[Any]:
    if parallel and len(items) >= 2:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(max_workers, len(items))) as ex_p:
            return list(ex_p.map(fn, items))
    return [fn(it) for it in items]


def _parallel_map_merge_dicts(
    fn: Callable[[Any], Mapping[Any, Any]],
    items: Sequence[Any],
    *,
    max_workers: int,
    parallel: bool,
) -> Dict[Any, Any]:
    merged: Dict[Any, Any] = {}
    for part in _parallel_map_list(fn, items, max_workers=max_workers, parallel=parallel):
        merged.update(part)
    return merged


def _build_duckdb_hex_in_expr(
    col_sql: str,
    hex_vals: Sequence[str],
    is_blob: bool,
    *,
    fallback_typeof: bool = False,
) -> Tuple[str, str]:
    if is_blob:
        in_sql = ", ".join(f"unhex({_sql_quote_str(h)})" for h in hex_vals)
        return f"lower(hex({col_sql}))", f"{col_sql} IN ({in_sql})"
    norm_expr = (
        f"lower(CASE WHEN typeof({col_sql}) = 'BLOB' THEN hex({col_sql}) "
        f"ELSE replace(CAST({col_sql} AS VARCHAR), '0x', '') END)"
        if fallback_typeof
        else f"lower(replace(CAST({col_sql} AS VARCHAR), '0x', ''))"
    )
    in_sql = ", ".join(_sql_quote_str(h) for h in hex_vals)
    return norm_expr, f"{norm_expr} IN ({in_sql})"


_ABI_UINT_RE: re.Pattern[str] = re.compile(r"uint(\d*)")
_ABI_INT_RE: re.Pattern[str] = re.compile(r"int(\d*)")
_ABI_BYTES_N_RE: re.Pattern[str] = re.compile(r"bytes(\d+)")
_ABI_SELECTOR_RE: re.Pattern[str] = re.compile(r"0x[0-9a-fA-F]{8}")


def _abi_encode_one(typ: str, val: Any) -> bytes:
    t = typ.strip()
    if t == "address":
        b = _hex_to_bytes(val)
        if len(b) != 20:
            raise ABIError(f"Bad address value: {val!r}")
        return b.rjust(32, b"\x00")
    if t == "bool":
        if not isinstance(val, bool) and val not in (0, 1):
            raise ABIError(f"Bad bool value: {val!r}")
        return (1 if bool(val) else 0).to_bytes(32, "big")
    m = _ABI_UINT_RE.fullmatch(t)
    if m:
        bits = _validate_abi_int_bits(m.group(1), "uint", val=val)
        iv = int(val)
        if iv < 0 or iv >= (1 << bits):
            raise ABIError(f"uint{bits} out of range: {iv}")
        return iv.to_bytes(32, "big")
    m = _ABI_INT_RE.fullmatch(t)
    if m:
        bits = _validate_abi_int_bits(m.group(1), "int", val=val)
        iv = int(val)
        lo, hi = -(1 << (bits - 1)), (1 << (bits - 1)) - 1
        if iv < lo or iv > hi:
            raise ABIError(f"int{bits} out of range: {iv}")
        return (iv % _TWO256).to_bytes(32, "big")
    m = _ABI_BYTES_N_RE.fullmatch(t)
    if m:
        sz = int(m.group(1))
        if sz < 1 or sz > 32:
            raise ABIError(f"Bad fixed bytes size: {t}")
        b = _hex_to_bytes(val)
        if len(b) != sz:
            raise ABIError(f"Expected {sz} bytes, got {len(b)}")
        return b.ljust(32, b"\x00")
    if t in ("bytes", "string"):
        b = _hex_to_bytes(val) if t == "bytes" else (val.encode("utf-8") if isinstance(val, str) else bytes(val))
        pad = (-len(b)) % 32
        return len(b).to_bytes(32, "big") + b + (b"\x00" * pad)
    if t.endswith("]"):
        base, dim = _split_abi_array_suffix(t)
        if not isinstance(val, (list, tuple)):
            raise ABIError(f"Expected sequence for {t}")
        if dim != "":
            expected = int(dim)
            if len(val) != expected:
                raise ABIError(f"Static array length mismatch: {len(val)} != {expected}")
            return _abi_encode_seq([base] * expected, list(val))
        return len(val).to_bytes(32, "big") + _abi_encode_seq([base] * len(val), list(val))
    if t.startswith("(") and t.endswith(")"):
        subs = _split_top_level_csv(t[1:-1])
        if not isinstance(val, (list, tuple)):
            raise ABIError(f"Expected tuple/list for {t}")
        return _abi_encode_seq(subs, list(val))
    raise ABIError(f"Unsupported ABI type: {t}")


def _split_abi_array_suffix(t: str) -> Tuple[str, str]:
    lb = t.rfind("[")
    return t[:lb], t[lb + 1 : -1]


def abi_encode(types: Sequence[str], values: Sequence[Any]) -> bytes:
    return _abi_encode_seq(types, values)


def encode_calldata(sig_or_sel: str, types: Sequence[str], values: Sequence[Any]) -> str:
    s = sig_or_sel.strip()
    sel = s if _ABI_SELECTOR_RE.fullmatch(s) else _selector(s)
    return sel.lower() + abi_encode(types, values).hex()


_ABI_MAX_DEPTH: int = 32
_ABI_MAX_TOTAL_ELEMS: int = 131_072
_ABI_MAX_TOTAL_BYTES: int = 4 * 1024 * 1024


def _abi_decode_seq(
    types: Sequence[str],
    buf: memoryview,
    base_off: int,
    *,
    _depth: int = 0,
    _budget: Optional[List[int]] = None,
) -> Tuple[Any, ...]:
    if _depth > _ABI_MAX_DEPTH:
        raise ABIError("ABI decode recursion depth exceeded")
    bgt = _budget if _budget is not None else [0, 0]
    res: List[Any] = []
    cursor = base_off
    for t in types:
        bgt[0] += 1
        if bgt[0] > _ABI_MAX_TOTAL_ELEMS:
            raise ABIError("ABI decode element budget exceeded")
        ts = t.strip()
        if _abi_is_dynamic(ts):
            if cursor + 32 > len(buf):
                raise ABIError("ABI decode offset out of bounds")
            rel = int.from_bytes(buf[cursor:cursor + 32], "big")
            if rel < 0 or base_off + rel > len(buf):
                raise ABIError("ABI decode dynamic offset out of bounds")
            cursor += 32
            res.append(_abi_decode_one(ts, buf, base_off + rel, _depth=_depth + 1, _budget=bgt))
        else:
            sz = _abi_static_word_size(ts)
            if cursor + sz > len(buf):
                raise ABIError("ABI decode static word out of bounds")
            res.append(_abi_decode_one(ts, buf, cursor, _depth=_depth + 1, _budget=bgt))
            cursor += sz
    return tuple(res)


def _abi_decode_one(
    typ: str,
    buf: memoryview,
    off: int,
    *,
    _depth: int = 0,
    _budget: Optional[List[int]] = None,
) -> Any:
    if _depth > _ABI_MAX_DEPTH:
        raise ABIError("ABI decode recursion depth exceeded")
    bgt = _budget if _budget is not None else [0, 0]
    t = typ.strip()
    if t == "address":
        if off + 32 > len(buf):
            raise ABIError("ABI address truncated")
        if bytes(buf[off:off + 12]) != b"\x00" * 12:
            raise ABIError("ABI address dirty upper 12 bytes")
        return _checksum("0x" + bytes(buf[off + 12:off + 32]).hex())
    if t == "bool":
        if off + 32 > len(buf):
            raise ABIError("ABI bool truncated")
        v = int.from_bytes(buf[off:off + 32], "big")
        if v not in (0, 1):
            raise ABIError(f"ABI bool dirty upper bits: {v}")
        return v == 1
    m = _ABI_UINT_RE.fullmatch(t)
    if m:
        if off + 32 > len(buf):
            raise ABIError("ABI uint truncated")
        bits = _validate_abi_int_bits(m.group(1), "uint")
        v = int.from_bytes(buf[off:off + 32], "big")
        if bits < 256 and v >= (1 << bits):
            raise ABIError(f"uint{bits} decode dirty upper bits")
        return v
    m = _ABI_INT_RE.fullmatch(t)
    if m:
        if off + 32 > len(buf):
            raise ABIError("ABI int truncated")
        bits = _validate_abi_int_bits(m.group(1), "int")
        v = int.from_bytes(buf[off:off + 32], "big")
        if v >= (1 << 255):
            v -= _TWO256
        mask_lo, mask_hi = -(1 << (bits - 1)), (1 << (bits - 1)) - 1
        if v < mask_lo or v > mask_hi:
            raise ABIError(f"int{bits} decode overflow")
        return v
    m = _ABI_BYTES_N_RE.fullmatch(t)
    if m:
        sz = int(m.group(1))
        if sz < 1 or sz > 32:
            raise ABIError(f"Invalid bytesN size: {sz}")
        if off + 32 > len(buf):
            raise ABIError("ABI bytesN truncated")
        if sz < 32 and bytes(buf[off + sz:off + 32]) != b"\x00" * (32 - sz):
            raise ABIError(f"ABI bytes{sz} dirty trailing bytes")
        return bytes(buf[off:off + sz])
    if t == "bytes":
        if off + 32 > len(buf):
            raise ABIError("ABI bytes length truncated")
        ln = int.from_bytes(buf[off:off + 32], "big")
        if off + 32 + ln > len(buf):
            raise ABIError("ABI bytes payload truncated")
        bgt[1] += ln
        if bgt[1] > _ABI_MAX_TOTAL_BYTES:
            raise ABIError("ABI decode byte budget exceeded")
        return bytes(buf[off + 32:off + 32 + ln])
    if t == "string":
        raw = _abi_decode_one("bytes", buf, off, _depth=_depth + 1, _budget=bgt)
        return raw.decode("utf-8", errors="replace")
    if t.endswith("]"):
        base, dim = _split_abi_array_suffix(t)
        if dim != "":
            try:
                cnt = int(dim)
            except ValueError as exc:
                raise ABIError(f"Invalid ABI static array dim: {dim}") from exc
            if cnt < 0 or cnt > 65536:
                raise ABIError(f"ABI static array length absurd: {cnt}")
            return list(_abi_decode_seq([base] * cnt, buf, off, _depth=_depth + 1, _budget=bgt))
        if off + 32 > len(buf):
            raise ABIError("ABI array length truncated")
        cnt = int.from_bytes(buf[off:off + 32], "big")
        if cnt > 65536:
            raise ABIError(f"ABI array length absurd: {cnt}")
        return list(_abi_decode_seq([base] * cnt, buf, off + 32, _depth=_depth + 1, _budget=bgt))
    if t.startswith("(") and t.endswith(")"):
        subs = _split_top_level_csv(t[1:-1])
        return _abi_decode_seq(subs, buf, off, _depth=_depth + 1, _budget=bgt)
    raise ABIError(f"Unsupported ABI decode type: {t}")


def abi_decode(types: Sequence[str], data: Any) -> Tuple[Any, ...]:
    if isinstance(data, str):
        hs = data.strip()
        if hs.startswith(("0x", "0X")):
            hs = hs[2:]
        if len(hs) % 2 != 0:
            raise ABIError("ABI hex payload has odd length")
        try:
            raw = bytes.fromhex(hs) if hs else b""
        except ValueError as exc:
            raise ABIError(f"Invalid ABI hex payload: {exc}") from exc
    else:
        raw = _hex_to_bytes(data)
    return _abi_decode_seq(types, memoryview(raw), 0, _depth=0, _budget=[0, 0])


# ── 크로스플랫폼 파일 락 · 부트 ID · 좀비 락 회수 · 원자적 JSON 입출력 ──
@contextlib.contextmanager
def _exclusive_file_lock(lock_path: Path, timeout_sec: float = 300.0) -> Iterator[None]:
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    fh = open(lock_path, "a+b")
    deadline = time.monotonic() + max(0.5, timeout_sec)
    locked = False
    try:
        if _msvcrt is not None and os.fstat(fh.fileno()).st_size == 0:
            try:
                fh.seek(0)
                fh.write(b"\x00")
                fh.flush()
            except OSError:
                pass
        while True:
            try:
                if _msvcrt is not None:
                    fh.seek(0)
                    _msvcrt.locking(fh.fileno(), _msvcrt.LK_NBLCK, 1)
                elif _fcntl is not None:
                    _fcntl.flock(fh.fileno(), _fcntl.LOCK_EX | _fcntl.LOCK_NB)
                locked = True
                break
            except OSError:
                if time.monotonic() >= deadline:
                    raise TimeoutError(f"Lock timeout on {lock_path}")
                time.sleep(0.025)
        yield
    finally:
        if locked:
            try:
                if _msvcrt is not None:
                    fh.seek(0)
                    _msvcrt.locking(fh.fileno(), _msvcrt.LK_UNLCK, 1)
                elif _fcntl is not None:
                    _fcntl.flock(fh.fileno(), _fcntl.LOCK_UN)
            except OSError:
                pass
        try:
            fh.close()
        except OSError:
            pass


def _host_boot_id() -> str:
    if os.name == "nt":
        try:
            k32 = ctypes.windll.kernel32
            k32.GetTickCount64.restype = ctypes.c_ulonglong
            tick_ms = int(k32.GetTickCount64())
            boot_epoch = int(round((time.time() - (tick_ms / 1000.0)) / 60.0))
            return f"win-{boot_epoch}"
        except Exception:
            return "win-unknown"
    proc_btime = Path("/proc/stat")
    if proc_btime.is_file():
        try:
            for line in proc_btime.read_text(encoding="utf-8", errors="ignore").splitlines():
                if line.startswith("btime "):
                    return f"linux-{line.split()[1]}"
        except OSError:
            pass
    return "posix-generic"


def _is_pid_alive(pid: int) -> bool:
    """병렬 터미널 세션의 프로세스(PID) 생존 여부를 OS 커널 핸들로 즉시 확인 (64비트 핸들 안전)."""
    if pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name == "nt":
        try:
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            STILL_ACTIVE = 259
            ERROR_ACCESS_DENIED = 5
            k32 = ctypes.windll.kernel32
            k32.OpenProcess.argtypes = [ctypes.c_ulong, ctypes.c_int, ctypes.c_ulong]
            k32.OpenProcess.restype = ctypes.c_void_p
            k32.GetExitCodeProcess.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_ulong)]
            k32.GetExitCodeProcess.restype = ctypes.c_int
            k32.CloseHandle.argtypes = [ctypes.c_void_p]
            k32.CloseHandle.restype = ctypes.c_int
            k32.GetLastError.restype = ctypes.c_ulong
            h_proc = k32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, int(pid))
            if not h_proc:
                return int(k32.GetLastError()) == ERROR_ACCESS_DENIED
            try:
                exit_code = ctypes.c_ulong(0)
                if k32.GetExitCodeProcess(h_proc, ctypes.byref(exit_code)):
                    return int(exit_code.value) == STILL_ACTIVE
                return False
            finally:
                k32.CloseHandle(h_proc)
        except Exception:
            return False
    try:
        os.kill(int(pid), 0)
        return True
    except PermissionError:
        return True
    except OSError:
        return False


def _attach_win32_kill_on_close_job(proc_handle: int) -> Optional[int]:
    if os.name != "nt" or not proc_handle:
        return None
    try:
        class _JobBasicLimit(ctypes.Structure):
            _fields_ = [
                ("PerProcessUserTimeLimit", ctypes.c_int64),
                ("PerJobUserTimeLimit", ctypes.c_int64),
                ("LimitFlags", ctypes.c_uint32),
                ("MinimumWorkingSetSize", ctypes.c_size_t),
                ("MaximumWorkingSetSize", ctypes.c_size_t),
                ("ActiveProcessLimit", ctypes.c_uint32),
                ("Affinity", ctypes.c_size_t),
                ("PriorityClass", ctypes.c_uint32),
                ("SchedulingClass", ctypes.c_uint32),
            ]

        class _IoCounters(ctypes.Structure):
            _fields_ = [
                ("ReadOperationCount", ctypes.c_uint64),
                ("WriteOperationCount", ctypes.c_uint64),
                ("OtherOperationCount", ctypes.c_uint64),
                ("ReadTransferCount", ctypes.c_uint64),
                ("WriteTransferCount", ctypes.c_uint64),
                ("OtherTransferCount", ctypes.c_uint64),
            ]

        class _JobExtendedLimit(ctypes.Structure):
            _fields_ = [
                ("BasicLimitInformation", _JobBasicLimit),
                ("IoInfo", _IoCounters),
                ("ProcessMemoryLimit", ctypes.c_size_t),
                ("JobMemoryLimit", ctypes.c_size_t),
                ("PeakProcessMemoryUsed", ctypes.c_size_t),
                ("PeakJobMemoryUsed", ctypes.c_size_t),
            ]

        k32 = ctypes.windll.kernel32
        k32.CreateJobObjectW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p]
        k32.CreateJobObjectW.restype = ctypes.c_void_p
        k32.SetInformationJobObject.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_uint32]
        k32.SetInformationJobObject.restype = ctypes.c_int
        k32.AssignProcessToJobObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        k32.AssignProcessToJobObject.restype = ctypes.c_int
        k32.CloseHandle.argtypes = [ctypes.c_void_p]
        k32.CloseHandle.restype = ctypes.c_int
        h_job = k32.CreateJobObjectW(None, None)
        if not h_job:
            return None
        info = _JobExtendedLimit()
        info.BasicLimitInformation.LimitFlags = 0x2000
        if not k32.SetInformationJobObject(h_job, 9, ctypes.byref(info), ctypes.sizeof(info)):
            k32.CloseHandle(h_job)
            return None
        if not k32.AssignProcessToJobObject(h_job, ctypes.c_void_p(int(proc_handle))):
            k32.CloseHandle(h_job)
            return None
        return int(h_job)
    except Exception:
        return None


def _close_win32_handle(handle_val: Optional[int]) -> None:
    if handle_val and os.name == "nt":
        try:
            k32 = ctypes.windll.kernel32
            k32.CloseHandle.argtypes = [ctypes.c_void_p]
            k32.CloseHandle.restype = ctypes.c_int
            k32.CloseHandle(ctypes.c_void_p(int(handle_val)))
        except _OS_CLEANUP_EXC:
            pass


def _run_subproc_tree_safe(
    cmd: List[str],
    *,
    cwd: str,
    env: Dict[str, str],
    timeout_sec: float,
    decode_text: bool = False,
    input_bytes: Optional[bytes] = None,
) -> subprocess.CompletedProcess[Any]:
    eff_timeout = max(1.0, float(timeout_sec))
    _popen_kw: Dict[str, Any] = {}
    if os.name == "nt":
        _popen_kw["creationflags"] = int(getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        env=env,
        stdin=(subprocess.PIPE if input_bytes is not None else subprocess.DEVNULL),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        **_popen_kw,
    )
    h_job = _attach_win32_kill_on_close_job(int(getattr(proc, "_handle", 0) or 0))
    try:
        out_b, err_b = proc.communicate(input=input_bytes, timeout=eff_timeout)
    except subprocess.TimeoutExpired as exc_to:
        _close_win32_handle(h_job)
        h_job = None
        try:
            proc.kill()
        except OSError:
            pass
        try:
            proc.communicate(timeout=2.0)
        except Exception:
            for pipe_s in (proc.stdout, proc.stderr):
                if pipe_s is not None:
                    try:
                        pipe_s.close()
                    except OSError:
                        pass
        raise subprocess.TimeoutExpired(cmd, eff_timeout) from exc_to
    finally:
        _close_win32_handle(h_job)
    if decode_text:
        return subprocess.CompletedProcess(
            cmd,
            proc.returncode,
            (out_b or b"").decode("utf-8", errors="replace"),
            (err_b or b"").decode("utf-8", errors="replace"),
        )
    return subprocess.CompletedProcess(cmd, proc.returncode, out_b or b"", err_b or b"")


def _list_protocol_subdirs(root_dir: Path) -> List[Path]:
    if not root_dir.is_dir():
        return []
    out_dirs: List[Path] = []
    try:
        with os.scandir(root_dir) as it_sc:
            for ent in it_sc:
                if not ent.name.startswith("_") and ent.is_dir(follow_symlinks=False):
                    out_dirs.append(Path(ent.path))
    except OSError:
        return []
    out_dirs.sort(key=lambda p: p.name)
    return out_dirs


def _read_json(path: Path, default: Any = None) -> Any:
    try:
        if not path.is_file():
            return default
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _json_default(obj: Any) -> Any:
    if isinstance(obj, Decimal):
        return format(obj, "f")
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _write_json_atomic(path: Path, data: Any, *, compact: bool = False) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = (
        json.dumps(data, ensure_ascii=False, separators=(",", ":"), sort_keys=True, default=_json_default)
        if compact
        else json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True, default=_json_default)
    ).encode("utf-8")
    tmp = path.with_name(f".{path.name}.tmp.{os.getpid()}.{threading.get_ident()}")
    tmp.write_bytes(payload)
    backoff = 0.015
    for attempt in range(8):
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            if attempt == 7:
                try:
                    tmp.unlink(missing_ok=True)
                except OSError:
                    pass
                raise
            time.sleep(backoff)
            backoff *= 1.8


# ── 공유 SQLite 캐시 (`audit_artifacts/_cache/engine_cache.sqlite`) ──
class SQLiteStore:
    _DDL: str = """
    PRAGMA auto_vacuum = INCREMENTAL;
    PRAGMA journal_mode = WAL;
    PRAGMA synchronous = NORMAL;
    PRAGMA busy_timeout = 30000;
    PRAGMA temp_store = MEMORY;
    PRAGMA cache_size = -65536;
    PRAGMA mmap_size = 268435456;
    CREATE TABLE IF NOT EXISTS engine_meta (
        meta_key        TEXT PRIMARY KEY,
        meta_val        TEXT NOT NULL,
        updated_at      REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS rpc_endpoints (
        chain_id        INTEGER NOT NULL,
        url             TEXT NOT NULL,
        is_archive      INTEGER NOT NULL DEFAULT 0,
        is_keyed        INTEGER NOT NULL DEFAULT 0,
        batch_cap       INTEGER NOT NULL DEFAULT 25,
        rtt_ms          REAL NOT NULL DEFAULT 999.0,
        cool_until      REAL NOT NULL DEFAULT 0.0,
        demote_until    REAL NOT NULL DEFAULT 0.0,
        quarantined     INTEGER NOT NULL DEFAULT 0,
        last_ok_at      REAL NOT NULL DEFAULT 0.0,
        PRIMARY KEY (chain_id, url)
    );
    CREATE TABLE IF NOT EXISTS pinned_rpc_cache (
        chain_id        INTEGER NOT NULL,
        block_num       INTEGER NOT NULL,
        method          TEXT NOT NULL,
        params_sha256   TEXT NOT NULL,
        result_json     TEXT NOT NULL,
        created_at      REAL NOT NULL,
        PRIMARY KEY (chain_id, block_num, method, params_sha256)
    );
    CREATE TABLE IF NOT EXISTS contract_code (
        chain_id        INTEGER NOT NULL,
        address         TEXT NOT NULL,
        audit_block     INTEGER NOT NULL,
        code_hash       TEXT NOT NULL,
        skeleton_hash   TEXT NOT NULL,
        opcode_4grams   TEXT NOT NULL,
        raw_code_hex    TEXT NOT NULL,
        proxy_kind      TEXT NOT NULL DEFAULT 'none',
        impl_addrs_json TEXT NOT NULL DEFAULT '[]',
        eip6780_active  INTEGER NOT NULL DEFAULT 1,
        PRIMARY KEY (chain_id, address, audit_block)
    );
    CREATE INDEX IF NOT EXISTS idx_skeleton_hash ON contract_code(skeleton_hash);
    CREATE INDEX IF NOT EXISTS idx_code_hash ON contract_code(code_hash);
    CREATE INDEX IF NOT EXISTS idx_contract_code_chain ON contract_code(chain_id, audit_block DESC);
    CREATE INDEX IF NOT EXISTS idx_contract_code_address ON contract_code(address, audit_block DESC);
    CREATE INDEX IF NOT EXISTS idx_contract_code_proxy_impl ON contract_code(chain_id, audit_block DESC, address, proxy_kind, impl_addrs_json) WHERE impl_addrs_json IS NOT NULL AND impl_addrs_json != '' AND impl_addrs_json != '[]';
    CREATE TABLE IF NOT EXISTS verified_sources (
        chain_id        INTEGER NOT NULL,
        address         TEXT NOT NULL,
        provider        TEXT NOT NULL,
        verified        INTEGER NOT NULL,
        contract_name   TEXT NOT NULL DEFAULT '',
        abi_json        TEXT NOT NULL DEFAULT '[]',
        sources_json    TEXT NOT NULL DEFAULT '{}',
        fetched_at      REAL NOT NULL,
        PRIMARY KEY (chain_id, address)
    );
    CREATE TABLE IF NOT EXISTS token_valuation (
        chain_id                INTEGER NOT NULL,
        token_addr              TEXT NOT NULL,
        audit_block             INTEGER NOT NULL,
        symbol                  TEXT NOT NULL,
        decimals                INTEGER NOT NULL,
        is_valid_erc20          INTEGER NOT NULL,
        price_usd               REAL NOT NULL,
        dex_exit_depth_usd      REAL NOT NULL,
        price_usd_dec           TEXT NOT NULL DEFAULT '',
        dex_exit_depth_usd_dec  TEXT NOT NULL DEFAULT '',
        price_source            TEXT NOT NULL,
        PRIMARY KEY (chain_id, token_addr, audit_block)
    );
    CREATE TABLE IF NOT EXISTS price_cache (
        price_key       TEXT PRIMARY KEY,
        price_val       REAL NOT NULL,
        price_val_dec   TEXT NOT NULL DEFAULT '',
        source          TEXT NOT NULL,
        fetched_at      REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS proven_vaults (
        chain_id        INTEGER NOT NULL,
        vault_addr      TEXT NOT NULL,
        slug            TEXT NOT NULL,
        net_krw         INTEGER NOT NULL DEFAULT 0,
        net_krw_exact   TEXT NOT NULL DEFAULT '0',
        fully_exhausted INTEGER NOT NULL DEFAULT 1,
        proven_at       REAL NOT NULL,
        PRIMARY KEY (chain_id, vault_addr)
    );
    CREATE TABLE IF NOT EXISTS proto_meta (
        slug            TEXT PRIMARY KEY,
        meta_json       TEXT NOT NULL DEFAULT '{}',
        updated_at      REAL NOT NULL DEFAULT 0.0
    );
    CREATE TABLE IF NOT EXISTS audit_queue (
        slug                TEXT PRIMARY KEY,
        priority            INTEGER NOT NULL DEFAULT 1,
        mode                TEXT NOT NULL DEFAULT 'A',
        chain               TEXT NOT NULL,
        tvl_usd             REAL NOT NULL DEFAULT 0.0,
        tvl_usd_dec         TEXT NOT NULL DEFAULT '0',
        sort_rank           REAL NOT NULL DEFAULT 0.0,
        sort_rank_dec       TEXT NOT NULL DEFAULT '0',
        addresses_json      TEXT NOT NULL DEFAULT '[]',
        principle_summary   TEXT NOT NULL DEFAULT '',
        needs_agent         INTEGER NOT NULL DEFAULT 0,
        status              TEXT NOT NULL DEFAULT 'pending',
        claim_boot_id       TEXT NOT NULL DEFAULT '',
        session_id          TEXT NOT NULL DEFAULT '',
        claimed_at          REAL NOT NULL DEFAULT 0.0,
        verdict             TEXT NOT NULL DEFAULT '',
        net_krw             INTEGER NOT NULL DEFAULT 0,
        net_krw_exact       TEXT NOT NULL DEFAULT '0',
        updated_at          REAL NOT NULL DEFAULT 0.0
    );
    CREATE INDEX IF NOT EXISTS idx_audit_queue_claim ON audit_queue(status, priority, sort_rank DESC, tvl_usd DESC);
    CREATE INDEX IF NOT EXISTS idx_audit_queue_pending_fast ON audit_queue(status, session_id, priority, sort_rank DESC, tvl_usd DESC, slug);
    CREATE INDEX IF NOT EXISTS idx_audit_queue_pending_mode_fast ON audit_queue(status, session_id, mode, priority, sort_rank DESC, tvl_usd DESC, slug);
    CREATE INDEX IF NOT EXISTS idx_audit_queue_session_status ON audit_queue(session_id, status, priority, sort_rank DESC, tvl_usd DESC);
    CREATE INDEX IF NOT EXISTS idx_audit_queue_recovered ON audit_queue(priority, sort_rank DESC, tvl_usd DESC, slug) WHERE status='pending' AND session_id='' AND claim_boot_id='RECOVERED';
    CREATE TABLE IF NOT EXISTS audit_sessions (
        session_id          TEXT PRIMARY KEY,
        active_slug         TEXT NOT NULL DEFAULT '',
        profit_slug         TEXT NOT NULL DEFAULT '',
        profit_verdict      TEXT NOT NULL DEFAULT '',
        profit_krw          INTEGER NOT NULL DEFAULT 0,
        profit_krw_exact    TEXT NOT NULL DEFAULT '0',
        completed_slugs     TEXT NOT NULL DEFAULT '[]',
        status              TEXT NOT NULL DEFAULT 'active',
        heartbeat_at        REAL NOT NULL DEFAULT 0.0,
        created_at          REAL NOT NULL DEFAULT 0.0
    );
    """

    def __init__(self, db_path: Optional[Path] = None) -> None:
        self.db_path = SQLITE_DB_PATH if db_path is None else db_path
        self._is_memory = str(self.db_path) == ":memory:"
        if not self._is_memory:
            self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._write_tx_depth: int = 0
        self._last_claimed_mode: str = ""
        self._read_conns_lock = threading.Lock()
        self._read_conns: Dict[int, Tuple[threading.Thread, sqlite3.Connection, threading.RLock, List[bool]]] = {}
        self._tls = threading.local()
        self._gen: int = 0
        self._closed = False
        self._conn = sqlite3.connect(str(self.db_path), timeout=30.0, check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        with self._lock:
            self._run_with_busy_retry(lambda: self._conn.executescript(self._DDL))
        with self._write_tx():
            for alter_sql in (
            "ALTER TABLE audit_queue ADD COLUMN mode TEXT NOT NULL DEFAULT 'A'",
            "ALTER TABLE audit_queue ADD COLUMN principle_summary TEXT NOT NULL DEFAULT ''",
            "ALTER TABLE audit_queue ADD COLUMN needs_agent INTEGER NOT NULL DEFAULT 0",
            "ALTER TABLE audit_queue ADD COLUMN sort_rank REAL NOT NULL DEFAULT 0.0",
            "ALTER TABLE audit_queue ADD COLUMN tvl_usd_dec TEXT NOT NULL DEFAULT '0'",
            "ALTER TABLE audit_queue ADD COLUMN sort_rank_dec TEXT NOT NULL DEFAULT '0'",
            "ALTER TABLE audit_queue ADD COLUMN net_krw_exact TEXT NOT NULL DEFAULT '0'",
            "ALTER TABLE audit_queue ADD COLUMN session_id TEXT NOT NULL DEFAULT ''",
            "ALTER TABLE proven_vaults ADD COLUMN fully_exhausted INTEGER NOT NULL DEFAULT 1",
            "ALTER TABLE proven_vaults ADD COLUMN net_krw_exact TEXT NOT NULL DEFAULT '0'",
            "ALTER TABLE audit_sessions ADD COLUMN profit_krw_exact TEXT NOT NULL DEFAULT '0'",
            "ALTER TABLE price_cache ADD COLUMN price_val_dec TEXT NOT NULL DEFAULT ''",
            "ALTER TABLE token_valuation ADD COLUMN price_usd_dec TEXT NOT NULL DEFAULT ''",
            "ALTER TABLE token_valuation ADD COLUMN dex_exit_depth_usd_dec TEXT NOT NULL DEFAULT ''",
            ):
                try:
                    self._conn.execute(alter_sql)
                except sqlite3.OperationalError:
                    pass
            try:
                prio_migrated = self._conn.execute(
                    "SELECT meta_val FROM engine_meta WHERE meta_key='roi_prio_v2'"
                ).fetchone()
                if prio_migrated is None:
                    q_cnt_row = self._conn.execute("SELECT COUNT(*) FROM audit_queue").fetchone()
                    if q_cnt_row and int(q_cnt_row[0] or 0) > 0:
                        _open_st = "('pending','awaiting_addresses','awaiting_poc','awaiting_verdict','claimed')"
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=0 WHERE mode='B' AND (slug LIKE 'modeb-match-%' OR slug LIKE 'modeb-clone-%') AND sort_rank>=2000000 AND status IN {_open_st}"
                        )
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=2 WHERE mode='B' AND (slug LIKE 'modeb-match-%' OR slug LIKE 'modeb-clone-%') AND sort_rank<2000000 AND status IN {_open_st}"
                        )
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=3 WHERE mode='B' AND slug NOT LIKE 'modeb-match-%' AND slug NOT LIKE 'modeb-clone-%' AND status IN {_open_st}"
                        )
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=1 WHERE mode='A' AND slug NOT LIKE 'live-%' AND tvl_usd<=30000000 AND status IN {_open_st}"
                        )
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=2 WHERE mode='A' AND slug NOT LIKE 'live-%' AND tvl_usd>30000000 AND tvl_usd<=500000000 AND status IN {_open_st}"
                        )
                        self._conn.execute(
                            f"UPDATE audit_queue SET priority=4 WHERE mode='A' AND slug NOT LIKE 'live-%' AND tvl_usd>500000000 AND status IN {_open_st}"
                        )
                    self._conn.execute(
                        "INSERT OR REPLACE INTO engine_meta(meta_key, meta_val, updated_at) VALUES('roi_prio_v2', '1', ?)",
                        (time.time(),),
                    )
            except sqlite3.OperationalError:
                pass
        self._maybe_prune_oversized()

    @staticmethod
    def _run_with_busy_retry(op: Callable[[], Any]) -> None:
        for attempt in range(100):
            try:
                op()
                return
            except sqlite3.OperationalError as exc:
                if attempt == 99 or not any(k in str(exc).lower() for k in ("locked", "busy")):
                    raise
                time.sleep(min(5.0, 0.05 * (attempt + 1)))

    @contextlib.contextmanager
    def _write_tx(self, *, immediate: bool = True) -> Iterator[sqlite3.Connection]:
        """Serialize SQLite multi-statement write transactions with nested savepoint support."""
        with self._lock:
            if self._closed:
                raise sqlite3.ProgrammingError("Cannot operate on a closed database.")
            depth = self._write_tx_depth
            self._write_tx_depth = depth + 1
            sp_name = f"sp_tx_{depth}" if depth > 0 else ""
            try:
                if depth == 0:
                    if immediate and not self._conn.in_transaction:
                        self._run_with_busy_retry(lambda: self._conn.execute("BEGIN IMMEDIATE"))
                else:
                    self._conn.execute(f"SAVEPOINT {sp_name}")
                try:
                    yield self._conn
                except BaseException:
                    if depth == 0:
                        if self._conn.in_transaction:
                            self._conn.rollback()
                    else:
                        try:
                            self._conn.execute(f"ROLLBACK TO SAVEPOINT {sp_name}")
                            self._conn.execute(f"RELEASE SAVEPOINT {sp_name}")
                        except sqlite3.Error:
                            pass
                    raise
                else:
                    if depth == 0:
                        if self._conn.in_transaction:
                            self._run_with_busy_retry(self._conn.commit)
                    else:
                        self._conn.execute(f"RELEASE SAVEPOINT {sp_name}")
            finally:
                self._write_tx_depth = depth

    def _open_readonly_conn(self) -> sqlite3.Connection:
        rc = sqlite3.connect(str(self.db_path), timeout=30.0, check_same_thread=False)
        rc.row_factory = sqlite3.Row
        rc.execute("PRAGMA busy_timeout = 30000")
        rc.execute("PRAGMA temp_store = MEMORY")
        rc.execute("PRAGMA query_only = ON")
        return rc

    @contextlib.contextmanager
    def _read_conn(self) -> Iterator[sqlite3.Connection]:
        cur_th = threading.current_thread()
        if self._is_memory or cur_th is threading.main_thread():
            with self._lock:
                if not self._closed:
                    yield self._conn
                    return
            if self._is_memory:
                raise sqlite3.ProgrammingError("Cannot operate on a closed in-memory database.")
            tmp_main = self._open_readonly_conn()
            try:
                yield tmp_main
            finally:
                try:
                    tmp_main.close()
                except sqlite3.Error:
                    pass
            return
        tls_rec = getattr(self._tls, "rec", None)
        if tls_rec is None or tls_rec[3] != self._gen or tls_rec[2][0]:
            dead_entries: List[Tuple[sqlite3.Connection, threading.RLock, List[bool]]] = []
            closed_now = False
            with self._read_conns_lock:
                if self._closed:
                    closed_now = True
                else:
                    for tid_k, (th_k, c_k, lk_k, cb_k) in list(self._read_conns.items()):
                        if th_k is not cur_th and not th_k.is_alive():
                            dead_entries.append((c_k, lk_k, cb_k))
                            self._read_conns.pop(tid_k, None)
                    rc_new = self._open_readonly_conn()
                    lk_new = threading.RLock()
                    cb_new = [False]
                    self._read_conns[id(cur_th)] = (cur_th, rc_new, lk_new, cb_new)
                    tls_rec = (rc_new, lk_new, cb_new, self._gen)
                    self._tls.rec = tls_rec
            for dc, dlk, dcb in dead_entries:
                with dlk:
                    if not dcb[0]:
                        dcb[0] = True
                        try:
                            dc.close()
                        except sqlite3.Error:
                            pass
            if closed_now:
                tmp_rc = self._open_readonly_conn()
                try:
                    yield tmp_rc
                finally:
                    try:
                        tmp_rc.close()
                    except sqlite3.Error:
                        pass
                return
        rc_use, lk_use, cb_use, _ = tls_rec
        with lk_use:
            if not cb_use[0]:
                yield rc_use
                return
        tmp_fb = self._open_readonly_conn()
        try:
            yield tmp_fb
        finally:
            try:
                tmp_fb.close()
            except sqlite3.Error:
                pass

    def _try_write_cache(self, fn: Callable[[sqlite3.Connection], Any]) -> None:
        """Execute a best-effort cache write while ignoring graceful shutdown close races."""
        with self._lock:
            if self._closed:
                return
            try:
                with self._write_tx():
                    fn(self._conn)
            except sqlite3.ProgrammingError as exc:
                if "closed database" not in str(exc).lower():
                    raise

    def close(self) -> None:
        with self._read_conns_lock:
            self._closed = True
            self._gen += 1
            entries = list(self._read_conns.values())
            self._read_conns.clear()
            self._tls.__dict__.clear()
        for _, rc_c, lk_c, cb_c in entries:
            with lk_c:
                if not cb_c[0]:
                    cb_c[0] = True
                    try:
                        rc_c.close()
                    except sqlite3.Error:
                        pass
        with self._lock:
            self._closed = True
            try:
                self._conn.close()
            except sqlite3.Error:
                pass

    def get_engine_meta(self, key: str, default: str = "") -> str:
        with self._read_conn() as rc:
            row = rc.execute("SELECT meta_val FROM engine_meta WHERE meta_key=?", (str(key),)).fetchone()
        return str(row["meta_val"]) if row is not None else default

    def put_engine_meta(self, key: str, val: Any) -> None:
        with self._write_tx():
            self._conn.execute(
                "INSERT OR REPLACE INTO engine_meta(meta_key, meta_val, updated_at) VALUES(?,?,?)",
                (str(key), str(val), time.time()),
            )

    def _maybe_prune_oversized(self) -> None:
        try:
            if self._is_memory or not self.db_path.is_file() or self.db_path.stat().st_size <= MAX_SQLITE_BYTES:
                return
            now = time.time()
            last_prune = 0.0
            try:
                last_prune = float(self.get_engine_meta("last_sqlite_prune_at", "0") or 0.0)
            except (sqlite3.Error, ValueError, TypeError):
                last_prune = 0.0
            if (now - last_prune) < 300.0:
                return
            with self._read_conn() as rc:
                pc_i = int((rc.execute("PRAGMA page_count").fetchone() or [0])[0] or 0)
                fc_i = int((rc.execute("PRAGMA freelist_count").fetchone() or [0])[0] or 0)
                ps_i = int((rc.execute("PRAGMA page_size").fetchone() or [4096])[0] or 4096)
                av_i = int((rc.execute("PRAGMA auto_vacuum").fetchone() or [0])[0] or 0)
                pin_cnt = int((rc.execute("SELECT COUNT(*) FROM pinned_rpc_cache").fetchone() or [0])[0] or 0)
                cc_cnt = int((rc.execute("SELECT COUNT(*) FROM contract_code").fetchone() or [0])[0] or 0)
            active_bytes = max(0, pc_i - fc_i) * max(512, ps_i)
            prune_pin_excess = max(0, pin_cnt - 50_000)
            prune_cc = active_bytes > (MAX_SQLITE_BYTES * 2) and cc_cnt > 60_000
            if prune_pin_excess <= 0 and not prune_cc and av_i != 2:
                with self._write_tx():
                    self._conn.execute(
                        "INSERT OR REPLACE INTO engine_meta(meta_key, meta_val, updated_at) VALUES('last_sqlite_prune_at', ?, ?)",
                        (f"{now:.3f}", now),
                    )
                return
            protected_addrs: Set[str] = set()
            if prune_cc:
                with self._read_conn() as rc:
                    mb_rows = rc.execute("SELECT addresses_json FROM audit_queue WHERE mode='B'").fetchall()
                for mr in mb_rows:
                    try:
                        for raw_a in json.loads(mr["addresses_json"] or "[]"):
                            na = _norm_addr(raw_a)
                            if na:
                                protected_addrs.add(na)
                    except (json.JSONDecodeError, ValueError, TypeError):
                        pass
            with self._write_tx():
                self._conn.execute(
                    "INSERT OR REPLACE INTO engine_meta(meta_key, meta_val, updated_at) VALUES('last_sqlite_prune_at', ?, ?)",
                    (f"{now:.3f}", now),
                )
                # Keep newest 50k pinned_rpc_cache entries (and never evict active-session rows <2h old) so freelist-only DBs retain 100% cache hits.
                if prune_pin_excess > 0:
                    self._conn.execute(
                        "DELETE FROM pinned_rpc_cache WHERE rowid IN ("
                        "SELECT rowid FROM pinned_rpc_cache WHERE created_at < ? ORDER BY rowid ASC LIMIT ?"
                        ")",
                        (now - 7200.0, min(50_000, prune_pin_excess)),
                    )
                if prune_cc:
                    cand_rows = self._conn.execute(
                        "SELECT rowid, address FROM contract_code WHERE audit_block > 0 ORDER BY rowid ASC LIMIT 10000"
                    ).fetchall()
                    del_ids = [int(r["rowid"]) for r in cand_rows if str(r["address"]) not in protected_addrs][:5000]
                    for off_d in range(0, len(del_ids), 500):
                        chunk_d = del_ids[off_d : off_d + 500]
                        qm_d = ",".join("?" for _ in chunk_d)
                        self._conn.execute(f"DELETE FROM contract_code WHERE rowid IN ({qm_d})", chunk_d)
            with self._lock:
                if av_i == 2:
                    try:
                        self._conn.execute("PRAGMA incremental_vacuum(2000)")
                    except sqlite3.Error:
                        pass
                try:
                    self._conn.execute("PRAGMA wal_checkpoint(PASSIVE)")
                except sqlite3.Error:
                    pass
        except (sqlite3.Error, OSError):
            pass

    def load_rpc_endpoints(self) -> List[Dict[str, Any]]:
        with self._read_conn() as rc:
            rows = rc.execute("SELECT * FROM rpc_endpoints").fetchall()
        return [dict(r) for r in rows]

    def save_rpc_endpoint(
        self,
        chain_id: int,
        url: str,
        batch_cap: int = 25,
        rtt_ms: float = 999.0,
        cool_until: float = 0.0,
        demote_until: float = 0.0,
        quarantined: bool = False,
        last_ok_at: float = 0.0,
    ) -> None:
        if not url:
            return
        cid_i = int(chain_id)
        url_s = _endpoint_storage_key(str(url))
        is_keyed_i = 1 if _is_keyed_rpc_url(str(url)) else 0
        self._try_write_cache(
            lambda conn: conn.execute(
                """
                INSERT OR REPLACE INTO rpc_endpoints(
                    chain_id, url, is_archive, is_keyed, batch_cap, rtt_ms, cool_until, demote_until, quarantined, last_ok_at
                ) VALUES(
                    ?, ?,
                    COALESCE((SELECT is_archive FROM rpc_endpoints WHERE chain_id=? AND url=?), 0),
                    MAX(COALESCE((SELECT is_keyed FROM rpc_endpoints WHERE chain_id=? AND url=?), 0), ?),
                    ?, ?, ?, ?, ?, ?
                )
                """,
                (
                    cid_i,
                    url_s,
                    cid_i,
                    url_s,
                    cid_i,
                    url_s,
                    is_keyed_i,
                    int(batch_cap),
                    float(rtt_ms),
                    float(cool_until),
                    float(demote_until),
                    1 if quarantined else 0,
                    float(last_ok_at),
                ),
            )
        )

    def get_pinned_rpc(self, chain_id: int, block_num: int, method: str, params_sha: str) -> Tuple[bool, Any]:
        with self._read_conn() as rc:
            row = rc.execute(
                "SELECT result_json FROM pinned_rpc_cache WHERE chain_id=? AND block_num=? AND method=? AND params_sha256=?",
                (chain_id, block_num, method, params_sha),
            ).fetchone()
        if row is None:
            return False, None
        return True, json.loads(row["result_json"])

    def get_pinned_rpc_batch(
        self,
        chain_id: int,
        block_num: int,
        keys: Sequence[Tuple[str, str]],
    ) -> Dict[Tuple[str, str], Any]:
        if block_num <= 0 or not keys:
            return {}
        by_method: Dict[str, List[str]] = {}
        seen_by_method: Dict[str, Set[str]] = {}
        for raw_m, raw_p in keys:
            m_s = str(raw_m)
            p_s = str(raw_p)
            seen_s = seen_by_method.setdefault(m_s, set())
            if p_s not in seen_s:
                seen_s.add(p_s)
                by_method.setdefault(m_s, []).append(p_s)
        out: Dict[Tuple[str, str], Any] = {}
        cid_i = int(chain_id)
        blk_i = int(block_num)
        with self._read_conn() as rc:
            for m_s, shas in by_method.items():
                for start in range(0, len(shas), 200):
                    chunk = shas[start : start + 200]
                    q_marks = ",".join("?" for _ in chunk)
                    rows = rc.execute(
                        f"SELECT params_sha256, result_json FROM pinned_rpc_cache "
                        f"WHERE chain_id=? AND block_num=? AND method=? AND params_sha256 IN ({q_marks})",
                        [cid_i, blk_i, m_s, *chunk],
                    ).fetchall()
                    for r in rows:
                        out[(m_s, str(r["params_sha256"]))] = json.loads(r["result_json"])
        return out

    def put_pinned_rpc(self, chain_id: int, block_num: int, method: str, params_sha: str, result: Any) -> None:
        if block_num <= 0:
            return
        self.put_pinned_rpc_batch(chain_id, block_num, [(method, params_sha, result)])

    def put_pinned_rpc_batch(
        self,
        chain_id: int,
        block_num: int,
        entries: Sequence[Tuple[str, str, Any]],
    ) -> None:
        if block_num <= 0 or not entries:
            return
        now = time.time()
        params: List[Tuple[int, int, str, str, str, float]] = []
        for method, params_sha, result in entries:
            dumped = json.dumps(result, ensure_ascii=True)
            if len(dumped) > 262_144:
                continue
            params.append((chain_id, block_num, method, params_sha, dumped, now))
        if not params:
            return
        self._try_write_cache(
            lambda conn: conn.executemany(
                "INSERT OR REPLACE INTO pinned_rpc_cache(chain_id, block_num, method, params_sha256, result_json, created_at) VALUES(?,?,?,?,?,?)",
                params,
            )
        )

    def get_verified_source(self, chain_id: int, address: str) -> Optional[Dict[str, Any]]:
        addr = _norm_addr(address)
        with self._read_conn() as rc:
            row = rc.execute(
                "SELECT * FROM verified_sources WHERE chain_id=? AND address=?",
                (chain_id, addr),
            ).fetchone()
        if row is None:
            return None
        if int(row["verified"]) == 0 and (time.time() - float(row["fetched_at"])) > SOURCES_UNVERIFIED_TTL_SEC:
            return None
        return {
            "provider": str(row["provider"]),
            "verified": bool(row["verified"]),
            "contract_name": str(row["contract_name"]),
            "abi": json.loads(row["abi_json"] or "[]"),
            "sources": json.loads(row["sources_json"] or "{}"),
        }

    def put_verified_source(
        self,
        chain_id: int,
        address: str,
        provider: str,
        verified: bool,
        contract_name: str,
        abi: Any,
        sources: Any,
    ) -> None:
        addr = _norm_addr(address)
        if not addr:
            return
        self._try_write_cache(
            lambda conn: conn.execute(
                "INSERT OR REPLACE INTO verified_sources(chain_id, address, provider, verified, contract_name, abi_json, sources_json, fetched_at) VALUES(?,?,?,?,?,?,?,?)",
                (
                    chain_id,
                    addr,
                    provider,
                    1 if verified else 0,
                    contract_name,
                    json.dumps(abi or [], ensure_ascii=False),
                    json.dumps(sources or {}, ensure_ascii=False),
                    time.time(),
                ),
            )
        )

    def get_contract_code(self, chain_id: int, address: str, audit_block: int) -> Optional[Dict[str, Any]]:
        addr = _norm_addr(address)
        with self._read_conn() as rc:
            row = rc.execute(
                "SELECT * FROM contract_code WHERE chain_id=? AND address=? AND audit_block=?",
                (chain_id, addr, audit_block),
            ).fetchone()
        if row is None:
            return None
        return dict(row)

    def put_contract_code_batch(
        self,
        rows: Sequence[Tuple[int, str, int, str, str, str, str, str, List[str], bool]],
    ) -> None:
        if not rows:
            return
        params: List[Tuple[Any, ...]] = []
        for chain_id, address, audit_block, code_hash, skeleton_hash, opcode_4grams, raw_code_hex, proxy_kind, impl_addrs, eip6780_active in rows:
            addr = _norm_addr(address)
            if not addr:
                continue
            params.append(
                (
                    chain_id,
                    addr,
                    audit_block,
                    code_hash,
                    skeleton_hash,
                    opcode_4grams,
                    raw_code_hex,
                    proxy_kind,
                    json.dumps(impl_addrs or [], ensure_ascii=True),
                    1 if eip6780_active else 0,
                )
            )
        if not params:
            return
        self._try_write_cache(
            lambda conn: conn.executemany(
                "INSERT OR REPLACE INTO contract_code(chain_id, address, audit_block, code_hash, skeleton_hash, opcode_4grams, raw_code_hex, proxy_kind, impl_addrs_json, eip6780_active) VALUES(?,?,?,?,?,?,?,?,?,?)",
                params,
            )
        )

    def _latest_contract_code_rows(
        self,
        cols_sql: str,
        chain_id: Optional[int] = None,
        extra_where: str = "",
        order_latest: bool = True,
    ) -> List[Tuple[Any, ...]]:
        where_parts: List[str] = []
        params: List[Any] = []
        if chain_id is not None and int(chain_id) > 0:
            where_parts.append("chain_id=?")
            params.append(int(chain_id))
        if extra_where:
            where_parts.append(f"({extra_where})")
        where_sql = f" WHERE {' AND '.join(where_parts)}" if where_parts else ""
        plain_cols = cols_sql.strip()
        # cols_sql가 순서 키(audit_block/rowid)를 직접 포함하면 윈도우 바깥 쿼리의 이름 해석이 모호해지므로 legacy로 폴백한다.
        if "audit_block" not in plain_cols and "rowid" not in plain_cols:
            order_sql = " ORDER BY audit_block DESC, rowid DESC" if order_latest else ""
            inner = (
                f"SELECT chain_id, address, audit_block, rowid, {plain_cols}, "
                f"ROW_NUMBER() OVER (PARTITION BY chain_id, address ORDER BY audit_block DESC, rowid DESC) AS _rn "
                f"FROM contract_code{where_sql}"
            )
            outer = f"SELECT chain_id, address, {plain_cols} FROM ({inner}) WHERE _rn = 1{order_sql}"
            try:
                with self._read_conn() as rc:
                    cur = rc.cursor()
                    cur.row_factory = None
                    return cur.execute(outer, tuple(params)).fetchall()
            except sqlite3.Error:
                pass  # 구형 SQLite(윈도우 함수 없음)에서는 아래 legacy 루프로 폴백한다.
        with self._read_conn() as rc:
            cur = rc.cursor()
            cur.row_factory = None
            rows = cur.execute(
                f"SELECT chain_id, address, {cols_sql} FROM contract_code{where_sql} ORDER BY audit_block DESC, rowid DESC",
                tuple(params),
            ).fetchall()
        deduped: List[Tuple[Any, ...]] = []
        seen: Set[Tuple[int, str]] = set()
        for r in rows:
            key = (int(r[0]), str(r[1]))
            if key not in seen:
                seen.add(key)
                deduped.append(r)
        return deduped

    def find_by_skeleton_or_grams(
        self,
        skeleton_hash: str,
        seed_grams: Union[Set[str], Sequence[str], str],
        min_containment: Union[Decimal, int, str] = Decimal("0.55"),
        chain_id: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        seed_set: Set[str] = (
            set(filter(None, seed_grams.split(",")))
            if isinstance(seed_grams, str)
            else {str(x) for x in (seed_grams or ()) if x}
        )
        if not skeleton_hash and not seed_set:
            return out
        min_c_dec = _to_dec(min_containment, Decimal("0.55"))
        n_seed = len(seed_set)
        min_bp = max(0, int((min_c_dec * Decimal(10000)).to_integral_value(rounding=ROUND_HALF_EVEN)))
        min_hits = ((min_bp * n_seed) + 9999) // 10000 if n_seed else 0
        inter_fn = seed_set.intersection
        gram_hits_cache: Dict[str, int] = {}
        gram_match_indices: List[Tuple[int, int, str]] = []
        for cid, addr, code_hash, sk_hash, raw_g in self._latest_contract_code_rows(
            "code_hash, skeleton_hash, opcode_4grams", chain_id, order_latest=False
        ):
            if skeleton_hash and (sk_hash == skeleton_hash or code_hash == skeleton_hash):
                out.append({"chain_id": int(cid), "address": str(addr), "score": Decimal("1"), "similarity": Decimal("1"), "match_type": "skeleton"})
                continue
            if n_seed and raw_g:
                inter_cnt = gram_hits_cache.get(raw_g)
                if inter_cnt is None:
                    inter_cnt = len(inter_fn(raw_g.split(",")))
                    gram_hits_cache[raw_g] = inter_cnt
                if inter_cnt >= min_hits:
                    sc_v = (Decimal(inter_cnt) / Decimal(n_seed)).quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN)
                    if sc_v >= min_c_dec:
                        gram_match_indices.append((len(out), int(cid), str(addr)))
                        out.append(
                            {
                                "chain_id": int(cid),
                                "address": str(addr),
                                "score": sc_v,
                                "similarity": sc_v,
                                "match_type": "4gram",
                                "raw_code_hex": "",
                            }
                        )
        if gram_match_indices:
            with self._read_conn() as rc:
                for out_i, m_cid, m_addr in gram_match_indices:
                    r_hex = rc.execute(
                        "SELECT raw_code_hex FROM contract_code WHERE chain_id=? AND address=? ORDER BY audit_block DESC, rowid DESC LIMIT 1",
                        (m_cid, m_addr),
                    ).fetchone()
                    if r_hex is not None:
                        out[out_i]["raw_code_hex"] = str(r_hex["raw_code_hex"] or "")
        out.sort(key=lambda x: (-x["score"], x["chain_id"], x["address"]))
        return out

    def find_proxies_by_impl(
        self,
        impl_addrs: Sequence[str],
        chain_id: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        targets = {na for a in impl_addrs if (na := _norm_addr(a))}
        if not targets:
            return []
        out: List[Dict[str, Any]] = []
        for cid, addr, proxy_kind, impl_json in self._latest_contract_code_rows(
            "proxy_kind, impl_addrs_json",
            chain_id,
            extra_where="impl_addrs_json IS NOT NULL AND impl_addrs_json != '' AND impl_addrs_json != '[]'",
        ):
            try:
                impls = [_norm_addr(x) for x in json.loads(impl_json or "[]")]
            except _PARSE_DATA_EXC:
                impls = []
            if any(x in targets for x in impls):
                out.append({
                    "chain_id": int(cid),
                    "address": str(addr),
                    "proxy_kind": str(proxy_kind),
                    "impl_addrs": [x for x in impls if x],
                })
        return out

    @staticmethod
    def _coerce_krw_int(val: Any) -> Tuple[int, str]:
        d_val = _to_dec(val)
        krw_i = max(0, int(d_val.to_integral_value(rounding=ROUND_DOWN))) if d_val > _DEC_ZERO else 0
        return min(krw_i, 1 << 62), str(krw_i)

    @staticmethod
    def _read_krw_int(exact_val: Any, legacy_val: Any = 0) -> int:
        if exact_val not in (None, "", "0"):
            d_ex = _to_dec(exact_val)
            if d_ex > _DEC_ZERO:
                return int(d_ex.to_integral_value(rounding=ROUND_DOWN))
        d_leg = _to_dec(legacy_val)
        return max(0, int(d_leg.to_integral_value(rounding=ROUND_DOWN))) if d_leg > _DEC_ZERO else 0

    def get_token_meta(self, chain_id: int, token_addr: str, audit_block: int) -> Optional[Dict[str, Any]]:
        addr = _norm_addr(token_addr)
        if not addr:
            return None
        with self._read_conn() as rc:
            row = rc.execute(
                "SELECT * FROM token_valuation WHERE chain_id=? AND token_addr=? AND audit_block=?",
                (chain_id, addr, audit_block),
            ).fetchone()
        return dict(row) if row is not None else None

    def put_token_meta_batch(
        self,
        rows: Sequence[Tuple[int, str, int, str, int, bool, Union[Decimal, int, str], Union[Decimal, int, str], str]],
    ) -> None:
        if not rows:
            return
        params: List[Tuple[Any, ...]] = []
        for chain_id, token_addr, audit_block, symbol, decimals, is_valid_erc20, price_usd, dex_exit_depth_usd, price_source in rows:
            addr = _norm_addr(token_addr)
            if not addr:
                continue
            p_dec = _to_dec(price_usd)
            dep_dec = _to_dec(dex_exit_depth_usd)
            p_dec_s = format(p_dec, "f")
            dep_dec_s = format(dep_dec, "f")
            params.append(
                (
                    chain_id,
                    addr,
                    audit_block,
                    str(symbol),
                    int(decimals),
                    1 if is_valid_erc20 else 0,
                    p_dec_s,
                    dep_dec_s,
                    p_dec_s,
                    dep_dec_s,
                    str(price_source),
                )
            )
        if not params:
            return
        self._try_write_cache(
            lambda conn: conn.executemany(
                "INSERT OR REPLACE INTO token_valuation(chain_id, token_addr, audit_block, symbol, decimals, is_valid_erc20, price_usd, dex_exit_depth_usd, price_usd_dec, dex_exit_depth_usd_dec, price_source) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                params,
            )
        )

    def get_price_dec(self, price_key: str, max_age_sec: int = 3600) -> Optional[Tuple[Decimal, str]]:
        with self._read_conn() as rc:
            row = rc.execute(
                "SELECT price_val, price_val_dec, source, fetched_at FROM price_cache WHERE price_key=?",
                (price_key,),
            ).fetchone()
        if row is None:
            return None
        if (_to_dec(int(time.time())) - _to_dec(row["fetched_at"])) > _to_dec(max_age_sec):
            return None
        raw_dec = row["price_val_dec"] if row["price_val_dec"] not in (None, "") else row["price_val"]
        return _to_dec(raw_dec), str(row["source"])

    def put_price(self, price_key: str, price_val: Union[Decimal, int, str], source: str) -> None:
        pv_dec = _to_dec(price_val)
        pv_str = format(pv_dec, "f")
        self._try_write_cache(
            lambda conn: conn.execute(
                "INSERT OR REPLACE INTO price_cache(price_key, price_val, price_val_dec, source, fetched_at) VALUES(?,?,?,?,?)",
                (price_key, pv_str, pv_str, source, int(time.time())),
            )
        )

    def get_proto_meta(self, slug: str) -> Dict[str, Any]:
        ns = _norm_slug(slug)
        base = _strip_chain_suffix_slug(ns)
        with self._read_conn() as rc:
            for k in (ns, str(slug), base):
                row = rc.execute("SELECT meta_json FROM proto_meta WHERE slug=?", (k,)).fetchone()
                if row is not None and row["meta_json"]:
                    try:
                        parsed = json.loads(row["meta_json"])
                        if isinstance(parsed, dict) and parsed:
                            return parsed
                    except _PARSE_DATA_EXC:
                        pass
        return {}

    def put_proto_meta_batch(self, items: Sequence[Tuple[str, Dict[str, Any]]]) -> None:
        if not items:
            return
        now = time.time()
        params: List[Tuple[str, str, float]] = []
        for slug, meta_dict in items:
            ns = _norm_slug(slug)
            if not ns or not isinstance(meta_dict, dict):
                continue
            params.append(
                (
                    ns,
                    json.dumps(
                        meta_dict,
                        ensure_ascii=False,
                        default=lambda o: format(o, "f") if isinstance(o, Decimal) else str(o),
                    ),
                    now,
                )
            )
        if not params:
            return
        with self._write_tx():
            self._conn.executemany(
                "INSERT OR REPLACE INTO proto_meta(slug, meta_json, updated_at) VALUES(?,?,?)",
                params,
            )

    @staticmethod
    def _coerce_chain_id(chain_id: Union[int, str]) -> int:
        return int(chain_id) if isinstance(chain_id, int) or str(chain_id).isdigit() else int(CHAIN_IDS.get(_norm_chain(str(chain_id)), 0))

    def is_vault_proven(
        self,
        chain_id: Union[int, str],
        vault_addr: str,
        require_exhausted: bool = False,
    ) -> bool:
        addr = _norm_addr(vault_addr)
        if not addr:
            return False
        cid = self._coerce_chain_id(chain_id)
        with self._read_conn() as rc:
            if require_exhausted:
                row = rc.execute(
                    "SELECT 1 FROM proven_vaults WHERE chain_id=? AND vault_addr=? AND fully_exhausted=1",
                    (cid, addr),
                ).fetchone()
            else:
                row = rc.execute(
                    "SELECT 1 FROM proven_vaults WHERE chain_id=? AND vault_addr=?",
                    (cid, addr),
                ).fetchone()
        return row is not None

    _PROVEN_VAULTS_UPSERT_SQL = """
    INSERT INTO proven_vaults(chain_id, vault_addr, slug, net_krw, net_krw_exact, fully_exhausted, proven_at)
    VALUES(?,?,?,?,?,?,?)
    ON CONFLICT(chain_id, vault_addr) DO UPDATE SET
        fully_exhausted = MAX(proven_vaults.fully_exhausted, excluded.fully_exhausted),
        slug = CASE
            WHEN excluded.fully_exhausted > proven_vaults.fully_exhausted
                 OR (excluded.fully_exhausted = proven_vaults.fully_exhausted AND excluded.net_krw >= proven_vaults.net_krw)
            THEN excluded.slug ELSE proven_vaults.slug END,
        net_krw_exact = CASE
            WHEN excluded.fully_exhausted > proven_vaults.fully_exhausted
                 OR (excluded.fully_exhausted = proven_vaults.fully_exhausted AND excluded.net_krw >= proven_vaults.net_krw)
            THEN excluded.net_krw_exact ELSE proven_vaults.net_krw_exact END,
        net_krw = CASE
            WHEN excluded.fully_exhausted > proven_vaults.fully_exhausted
                 OR (excluded.fully_exhausted = proven_vaults.fully_exhausted AND excluded.net_krw >= proven_vaults.net_krw)
            THEN excluded.net_krw ELSE proven_vaults.net_krw END,
        proven_at = excluded.proven_at
    """

    def mark_vault_proven(
        self,
        chain_id: Union[int, str],
        vault_addr: str,
        slug: str,
        net_krw: Union[int, Decimal] = 0,
        fully_exhausted: bool = True,
    ) -> None:
        addr = _norm_addr(vault_addr)
        if not addr:
            return
        cid = self._coerce_chain_id(chain_id)
        krw_sql_i, krw_exact_s = self._coerce_krw_int(net_krw)
        with self._write_tx():
            self._conn.execute(
                self._PROVEN_VAULTS_UPSERT_SQL,
                (cid, addr, _norm_slug(slug), krw_sql_i, krw_exact_s, 1 if fully_exhausted else 0, time.time()),
            )

    def upsert_queue_items_batch(
        self,
        items: Sequence[Tuple[Any, ...]],
    ) -> int:
        if not items:
            return 0
        now = time.time()
        inserted = 0
        slug_list = list(dict.fromkeys(ns for it in items if (ns := _norm_slug(it[0]))))
        if not slug_list:
            return 0
        with self._write_tx():
            existing_rows: List[Any] = []
            for off_sq in range(0, len(slug_list), 200):
                chunk_sq = slug_list[off_sq : off_sq + 200]
                q_marks = ",".join("?" for _ in chunk_sq)
                existing_rows.extend(
                    self._conn.execute(
                        f"SELECT slug, priority, tvl_usd, tvl_usd_dec, sort_rank, sort_rank_dec, status, addresses_json, principle_summary FROM audit_queue WHERE slug IN ({q_marks})",
                        chunk_sq,
                    ).fetchall()
                )
            existing_map = {str(r["slug"]): dict(r) for r in existing_rows}
            insert_params: List[Tuple[Any, ...]] = []
            update_params: List[Tuple[Any, ...]] = []
            for raw_item in items:
                raw_slug = raw_item[0]
                priority = raw_item[1]
                chain = raw_item[2]
                tvl_d = _to_dec(raw_item[3] if raw_item[3] is not None else 0)
                addresses = raw_item[4]
                mode = raw_item[5]
                principle_summary = raw_item[6]
                rank_d = _to_dec(raw_item[7]) if len(raw_item) >= 8 and raw_item[7] is not None else tvl_d
                slug = _norm_slug(raw_slug)
                if not slug:
                    continue
                normed = list(dict.fromkeys(filter(None, (_norm_addr(a) for a in addresses))))
                addr_json = json.dumps(normed, ensure_ascii=True)
                row = existing_map.get(slug)
                if row is None:
                    tvl_s = format(tvl_d, "f")
                    rank_s = format(rank_d, "f")
                    insert_params.append(
                        (slug, int(priority), str(mode or "A"), chain, tvl_s, tvl_s, rank_s, rank_s, addr_json, str(principle_summary or ""), now)
                    )
                    existing_map[slug] = {
                        "slug": slug,
                        "priority": int(priority),
                        "tvl_usd": tvl_d,
                        "tvl_usd_dec": tvl_s,
                        "sort_rank": rank_d,
                        "sort_rank_dec": rank_s,
                        "status": "pending",
                        "addresses_json": addr_json,
                        "principle_summary": str(principle_summary or ""),
                    }
                    inserted += 1
                else:
                    prev_tvl_d = _to_dec(row.get("tvl_usd_dec") if row.get("tvl_usd_dec") not in (None, "", "0") else row.get("tvl_usd", 0))
                    prev_rank_d = _to_dec(row.get("sort_rank_dec") if row.get("sort_rank_dec") not in (None, "", "0") else row.get("sort_rank", 0))
                    if str(row["status"]) == "pending" and (
                        normed
                        or principle_summary
                        or int(priority) < int(row.get("priority", 1))
                        or tvl_d > prev_tvl_d
                        or rank_d > prev_rank_d
                    ):
                        prev_addrs = json.loads(row["addresses_json"] or "[]")
                        merged = list(dict.fromkeys([*prev_addrs, *normed]))
                        ps = str(principle_summary or row["principle_summary"] or "")
                        merged_json = json.dumps(merged, ensure_ascii=True)
                        new_prio = min(int(priority), int(row.get("priority", 1)))
                        new_tvl_d = max(tvl_d, prev_tvl_d)
                        new_rank_d = max(rank_d, prev_rank_d)
                        new_tvl_s = format(new_tvl_d, "f")
                        new_rank_s = format(new_rank_d, "f")
                        update_params.append(
                            (new_prio, new_tvl_s, new_tvl_s, new_rank_s, new_rank_s, merged_json, ps, now, slug)
                        )
                        existing_map[slug] = {
                            "slug": slug,
                            "priority": new_prio,
                            "tvl_usd": new_tvl_d,
                            "tvl_usd_dec": new_tvl_s,
                            "sort_rank": new_rank_d,
                            "sort_rank_dec": new_rank_s,
                            "status": "pending",
                            "addresses_json": merged_json,
                            "principle_summary": ps,
                        }
            if insert_params:
                self._conn.executemany(
                    "INSERT OR IGNORE INTO audit_queue(slug, priority, mode, chain, tvl_usd, tvl_usd_dec, sort_rank, sort_rank_dec, addresses_json, principle_summary, needs_agent, status, updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,'pending',?)",
                    insert_params,
                )
            if update_params:
                self._conn.executemany(
                    "UPDATE audit_queue SET priority=?, tvl_usd=?, tvl_usd_dec=?, sort_rank=?, sort_rank_dec=?, addresses_json=?, principle_summary=?, updated_at=? WHERE slug=?",
                    update_params,
                )
        return inserted

    @staticmethod
    def _row_to_queue_dict(r: sqlite3.Row, *, was_recovered: Optional[bool] = None) -> Dict[str, Any]:
        rk = r.keys()
        tvl_d = _to_dec(r["tvl_usd_dec"] if ("tvl_usd_dec" in rk and r["tvl_usd_dec"] not in (None, "", "0")) else r["tvl_usd"])
        rank_raw = r["sort_rank_dec"] if ("sort_rank_dec" in rk and r["sort_rank_dec"] not in (None, "", "0")) else (r["sort_rank"] if "sort_rank" in rk else r["tvl_usd"])
        rank_d = _to_dec(rank_raw)
        d: Dict[str, Any] = {
            "slug": str(r["slug"]),
            "priority": int(r["priority"]),
            "mode": str(r["mode"] or "A"),
            "chain": str(r["chain"]),
            "tvl_usd": tvl_d,
            "tvl_usd_dec": format(tvl_d, "f"),
            "sort_rank": rank_d,
            "sort_rank_dec": format(rank_d, "f"),
            "addresses": json.loads(r["addresses_json"] or "[]"),
            "principle_summary": str(r["principle_summary"] or ""),
            "status": str(r["status"]),
            "session_id": str(r["session_id"] or "") if "session_id" in rk else "",
            "needs_agent": bool(r["needs_agent"]),
        }
        if was_recovered is not None:
            d["was_recovered"] = was_recovered
        return d

    @classmethod
    def _row_to_session_dict(cls, r: sqlite3.Row) -> Dict[str, Any]:
        rk = r.keys()
        p_krw_i = cls._read_krw_int(r["profit_krw_exact"] if "profit_krw_exact" in rk else "", r["profit_krw"])
        return {
            "session_id": str(r["session_id"]),
            "active_slug": str(r["active_slug"] or ""),
            "profit_slug": str(r["profit_slug"] or ""),
            "profit_verdict": str(r["profit_verdict"] or ""),
            "profit_krw": p_krw_i,
            "profit_krw_exact": str(p_krw_i),
            "completed_slugs": json.loads(r["completed_slugs"] or "[]"),
            "status": str(r["status"] or "active"),
            "heartbeat_at": float(r["heartbeat_at"] or 0.0),
            "created_at": float(r["created_at"] or 0.0),
        }

    def ensure_session(self, session_id: Optional[str] = None) -> Dict[str, Any]:
        now = time.time()
        sid = str(session_id or "").strip().lower()
        with self._write_tx():
            if not sid:
                for _ in range(16):
                    cand = f"ses-{os.urandom(5).hex()}"
                    if self._conn.execute("SELECT 1 FROM audit_sessions WHERE session_id=?", (cand,)).fetchone() is None:
                        sid = cand
                        break
                self._conn.execute(
                    "INSERT INTO audit_sessions(session_id, active_slug, profit_slug, profit_verdict, profit_krw, profit_krw_exact, completed_slugs, status, heartbeat_at, created_at) VALUES(?,'','','',0,'0','[]','active',?,?)",
                    (sid, now, now),
                )
                _bl_names = _capture_clean_root_baseline(SCRIPT_DIR)
                self._conn.execute(
                    "INSERT OR IGNORE INTO engine_meta(meta_key, meta_val, updated_at) VALUES(?, ?, ?)",
                    (f"fs_baseline_root:{sid}", json.dumps(_bl_names, ensure_ascii=False), now),
                )
            else:
                row = self._conn.execute("SELECT * FROM audit_sessions WHERE session_id=?", (sid,)).fetchone()
                if row is None:
                    self._conn.execute(
                        "INSERT INTO audit_sessions(session_id, active_slug, profit_slug, profit_verdict, profit_krw, profit_krw_exact, completed_slugs, status, heartbeat_at, created_at) VALUES(?,'','','',0,'0','[]','active',?,?)",
                        (sid, now, now),
                    )
                    _bl_names = _capture_clean_root_baseline(SCRIPT_DIR)
                    self._conn.execute(
                        "INSERT OR IGNORE INTO engine_meta(meta_key, meta_val, updated_at) VALUES(?, ?, ?)",
                        (f"fs_baseline_root:{sid}", json.dumps(_bl_names, ensure_ascii=False), now),
                    )
                else:
                    self._conn.execute("UPDATE audit_sessions SET heartbeat_at=? WHERE session_id=?", (now, sid))
            out_row = self._conn.execute("SELECT * FROM audit_sessions WHERE session_id=?", (sid,)).fetchone()
        return self._row_to_session_dict(out_row)

    def get_session(self, session_id: str) -> Optional[Dict[str, Any]]:
        sid = str(session_id or "").strip().lower()
        if not sid:
            return None
        with self._read_conn() as rc:
            row = rc.execute("SELECT * FROM audit_sessions WHERE session_id=?", (sid,)).fetchone()
        return self._row_to_session_dict(row) if row is not None else None

    def set_session_status(self, session_id: str, status: str, active_slug: Optional[str] = None) -> None:
        sid = str(session_id or "").strip().lower()
        if not sid:
            return
        now = time.time()
        with self._write_tx():
            if active_slug is None:
                self._conn.execute("UPDATE audit_sessions SET status=?, heartbeat_at=? WHERE session_id=?", (str(status), now, sid))
            else:
                self._conn.execute(
                    "UPDATE audit_sessions SET status=?, active_slug=?, heartbeat_at=? WHERE session_id=?",
                    (str(status), _norm_slug(active_slug) if active_slug else "", now, sid),
                )

    def claim_batch_for_session(
        self,
        session_id: str,
        boot_id: str,
        limit: int = 4,
        max_priority: Optional[int] = None,
        exclude_slugs: Sequence[str] = (),
        prefer_slugs: Sequence[str] = (),
    ) -> List[Dict[str, Any]]:
        """단일 세션 내부 병렬 스윕을 위해 최대 `limit`개 대기 대상을 O(log N) 인덱스 경로 + Mode A/B 기아방지 공정 인터리빙으로 원자적 일괄 클레임한다."""
        sid = str(session_id or "").strip().lower()
        lim = max(1, int(limit))
        now = time.time()
        max_p = int(max_priority) if max_priority is not None else None
        out_items: List[Dict[str, Any]] = []
        seen_slugs: Set[str] = {_norm_slug(str(s)) for s in exclude_slugs if _norm_slug(str(s))}
        clean_prefer = [ns for s in prefer_slugs if (ns := _norm_slug(str(s))) and ns not in seen_slugs]
        with self._write_tx():
            s_row = self._conn.execute("SELECT * FROM audit_sessions WHERE session_id=?", (sid,)).fetchone()
            if s_row is not None and str(s_row["profit_slug"] or ""):
                return []
            cur_act = _norm_slug(str(s_row["active_slug"] or "")) if s_row is not None else ""
            if cur_act and cur_act not in seen_slugs:
                q_cur = self._conn.execute("SELECT * FROM audit_queue WHERE slug=?", (cur_act,)).fetchone()
                q_sid = str(q_cur["session_id"] or "").strip().lower() if q_cur is not None else ""
                q_status = str(q_cur["status"] or "") if q_cur is not None else ""
                q_boot = str(q_cur["claim_boot_id"] or "") if q_cur is not None else ""
                q_prio_ok = (max_p is None) or (q_cur is not None and int(q_cur["priority"]) <= max_p)
                foreign_claimed = bool(
                    (q_sid and q_sid != sid)
                    or (not q_sid and q_status == "claimed" and q_boot not in (boot_id, "RECOVERED"))
                )
                if q_cur is not None and q_status in ("pending", "claimed") and not foreign_claimed and q_prio_ok:
                    q_item_d = self._row_to_queue_dict(q_cur, was_recovered=False)
                    if q_status == "pending" or (q_status == "claimed" and q_boot == "RECOVERED" and (not q_sid or q_sid == sid)):
                        self._conn.execute(
                            "UPDATE audit_queue SET status='claimed', claim_boot_id=?, session_id=?, claimed_at=?, updated_at=? WHERE slug=?",
                            (boot_id, sid, now, now, cur_act),
                        )
                        q_item_d["status"] = "claimed"
                        q_item_d["session_id"] = sid
                        q_item_d["claim_boot_id"] = boot_id
                    out_items.append(q_item_d)
                    seen_slugs.add(cur_act)
                elif q_cur is None or q_status in ("done", "awaiting_addresses", "awaiting_poc", "awaiting_verdict") or foreign_claimed:
                    self._conn.execute("UPDATE audit_sessions SET active_slug='', heartbeat_at=? WHERE session_id=?", (now, sid))

            rem = lim - len(out_items)
            newly_claimed_slugs: List[str] = []
            prio_clause = " AND priority<=?" if max_p is not None else ""

            def _accept_row(r_in: sqlite3.Row, *, was_rec: bool) -> None:
                sl_in = str(r_in["slug"])
                seen_slugs.add(sl_in)
                newly_claimed_slugs.append(sl_in)
                d_in = self._row_to_queue_dict(r_in, was_recovered=was_rec)
                d_in["status"] = "claimed"
                d_in["session_id"] = sid
                d_in["claim_boot_id"] = boot_id
                out_items.append(d_in)
                self._last_claimed_mode = "B" if str(d_in.get("mode") or "A").upper() == "B" else "A"

            if rem > 0 and clean_prefer:
                for p_sl in clean_prefer:
                    if len(out_items) >= lim:
                        break
                    if p_sl in seen_slugs:
                        continue
                    p_params: Tuple[Any, ...] = (p_sl, sid, max_p) if max_p is not None else (p_sl, sid)
                    r_p = self._conn.execute(
                        f"SELECT * FROM audit_queue WHERE slug=? AND status='pending' AND (session_id='' OR session_id=?){prio_clause}",
                        p_params,
                    ).fetchone()
                    if r_p is None:
                        continue
                    _accept_row(r_p, was_rec=False)
                rem = lim - len(out_items)
            if rem > 0:
                fetch_lim = rem + len(seen_slugs)
                if sid:
                    q_sql_s = (
                        f"SELECT * FROM audit_queue WHERE status='pending' AND session_id=?{prio_clause} "
                        "ORDER BY priority ASC, CASE WHEN claim_boot_id='RECOVERED' THEN 0 ELSE 1 END ASC, "
                        "sort_rank DESC, tvl_usd DESC, slug ASC LIMIT ?"
                    )
                    q_params_s: Tuple[Any, ...] = (sid, max_p, fetch_lim) if max_p is not None else (sid, fetch_lim)
                    for r in self._conn.execute(q_sql_s, q_params_s).fetchall():
                        if len(out_items) >= lim:
                            break
                        sl = str(r["slug"])
                        if sl in seen_slugs:
                            continue
                        _accept_row(r, was_rec=(str(r["claim_boot_id"] or "") == "RECOVERED"))

                # Unassigned pending pool: priority-strict (RECOVERED tie-break within same priority) + Mode A/B fair-share + heavy Mode-B cap
                if len(out_items) < lim:
                    rem_pool = lim - len(out_items)
                    pool_lim = rem_pool + len(seen_slugs) + 12
                    mode_rows: Dict[str, List[sqlite3.Row]] = {}
                    for m_k in ("A", "B"):
                        m_params: Tuple[Any, ...] = (m_k, max_p, pool_lim) if max_p is not None else (m_k, pool_lim)
                        raw_m = self._conn.execute(
                            f"SELECT * FROM audit_queue WHERE status='pending' AND session_id='' AND mode=?{prio_clause} "
                            "ORDER BY priority ASC, CASE WHEN claim_boot_id='RECOVERED' THEN 0 ELSE 1 END ASC, "
                            "sort_rank DESC, tvl_usd DESC, slug ASC LIMIT ?",
                            m_params,
                        ).fetchall()
                        mode_rows[m_k] = [r for r in raw_m if str(r["slug"]) not in seen_slugs]
                    in_flight_modes: Dict[str, int] = {"A": 0, "B": 0}
                    heavy_modeb_inflight = 0

                    def _is_heavy_primary_modeb(mode_s: str, slug_s: str) -> bool:
                        return str(mode_s or "").upper() == "B" and not str(slug_s or "").startswith(
                            ("modeb-match-", "modeb-clone-")
                        )

                    if sid:
                        for cr_m in self._conn.execute(
                            "SELECT mode, slug FROM audit_queue WHERE status='claimed' AND session_id=?",
                            (sid,),
                        ).fetchall():
                            mk_c = "B" if str(cr_m["mode"] or "A").upper() == "B" else "A"
                            in_flight_modes[mk_c] += 1
                            if _is_heavy_primary_modeb(mk_c, str(cr_m["slug"] or "")):
                                heavy_modeb_inflight += 1
                    for it_o in out_items:
                        mk_o = "B" if str(it_o.get("mode") or "A").upper() == "B" else "A"
                        in_flight_modes[mk_o] += 1
                        if _is_heavy_primary_modeb(mk_o, str(it_o.get("slug") or "")):
                            heavy_modeb_inflight += 1
                    idx_m = {"A": 0, "B": 0}
                    heavy_mb_cap = 2
                    deferred_heavy_b: List[sqlite3.Row] = []
                    while len(out_items) < lim:
                        ra = mode_rows["A"][idx_m["A"]] if idx_m["A"] < len(mode_rows["A"]) else None
                        rb = None
                        while idx_m["B"] < len(mode_rows["B"]):
                            cand_b = mode_rows["B"][idx_m["B"]]
                            if heavy_modeb_inflight >= heavy_mb_cap and _is_heavy_primary_modeb("B", str(cand_b["slug"])):
                                deferred_heavy_b.append(cand_b)
                                idx_m["B"] += 1
                                continue
                            rb = cand_b
                            break
                        if ra is None and rb is None:
                            if deferred_heavy_b:
                                rb = deferred_heavy_b.pop(0)
                                pick_m = "B"
                                chosen_r = rb
                                if str(chosen_r["slug"]) not in seen_slugs:
                                    _accept_row(chosen_r, was_rec=(str(chosen_r["claim_boot_id"] or "") == "RECOVERED"))
                                    in_flight_modes["B"] += 1
                                    heavy_modeb_inflight += 1
                                continue
                            break
                        if ra is None:
                            pick_m = "B"
                        elif rb is None:
                            pick_m = "A"
                        else:
                            pa, pb = int(ra["priority"]), int(rb["priority"])
                            if pa == pb:
                                if in_flight_modes["A"] < in_flight_modes["B"]:
                                    pick_m = "A"
                                elif in_flight_modes["B"] < in_flight_modes["A"]:
                                    pick_m = "B"
                                elif self._last_claimed_mode == "A":
                                    pick_m = "B"
                                elif self._last_claimed_mode == "B":
                                    pick_m = "A"
                                else:
                                    sa = _to_dec(ra["sort_rank_dec"] or ra["sort_rank"] or 0)
                                    sb = _to_dec(rb["sort_rank_dec"] or rb["sort_rank"] or 0)
                                    pick_m = "B" if sb >= sa else "A"
                            elif abs(pa - pb) == 1:
                                hi_m, lo_m = ("A", "B") if pa < pb else ("B", "A")
                                # Guarantee starvation-free minimum share (~25%+) for adjacent priority tier
                                if in_flight_modes[hi_m] >= 2 and (in_flight_modes[lo_m] + 1) * 3 <= (in_flight_modes[hi_m] + 1):
                                    pick_m = lo_m
                                else:
                                    pick_m = hi_m
                            else:
                                pick_m = "A" if pa < pb else "B"
                        chosen_r = mode_rows[pick_m][idx_m[pick_m]]
                        idx_m[pick_m] += 1
                        if str(chosen_r["slug"]) in seen_slugs:
                            continue
                        _accept_row(chosen_r, was_rec=(str(chosen_r["claim_boot_id"] or "") == "RECOVERED"))
                        in_flight_modes[pick_m] += 1
                        if _is_heavy_primary_modeb(pick_m, str(chosen_r["slug"])):
                            heavy_modeb_inflight += 1

            if newly_claimed_slugs:
                q_marks = ",".join("?" for _ in newly_claimed_slugs)
                self._conn.execute(
                    f"UPDATE audit_queue SET status='claimed', claim_boot_id=?, session_id=?, claimed_at=?, updated_at=? WHERE slug IN ({q_marks})",
                    (boot_id, sid, now, now, *newly_claimed_slugs),
                )

            if out_items:
                self._conn.execute(
                    "UPDATE audit_sessions SET active_slug=?, heartbeat_at=? WHERE session_id=?",
                    (str(out_items[0]["slug"]), now, sid),
                )
        return out_items

    def release_claimed_to_pending(self, slugs: Sequence[str], session_id: str) -> int:
        """병렬 배치 중 조기 수익 확정·시간 예산 양보로 미완료된 `claimed` 항목을 단일 배치 UPDATE로 즉시 `pending` 반환하고 `active_slug` 점유를 해제한다."""
        sid = str(session_id or "").strip().lower()
        clean = list(dict.fromkeys(ns for s in slugs if (ns := _norm_slug(str(s)))))
        if not sid or not clean:
            return 0
        now = time.time()
        released = 0
        with self._write_tx():
            for off in range(0, len(clean), 200):
                chunk = clean[off : off + 200]
                q_marks = ",".join("?" for _ in chunk)
                cur = self._conn.execute(
                    f"UPDATE audit_queue SET status='pending', claim_boot_id='', session_id='', claimed_at=0, updated_at=? "
                    f"WHERE status='claimed' AND session_id=? AND slug IN ({q_marks})",
                    (now, sid, *chunk),
                )
                released += int(cur.rowcount or 0)
                self._conn.execute(
                    f"UPDATE audit_sessions SET active_slug='', heartbeat_at=? WHERE session_id=? AND active_slug IN ({q_marks})",
                    (now, sid, *chunk),
                )
        return released

    def count_agent_pending_items(self, session_id: Optional[str] = None) -> int:
        sid = str(session_id or "").strip().lower()
        with self._read_conn() as rc:
            if sid:
                row = rc.execute(
                    "SELECT COUNT(*) FROM audit_queue WHERE session_id=? AND status IN ('awaiting_addresses', 'awaiting_poc', 'awaiting_verdict')",
                    (sid,),
                ).fetchone()
            else:
                row = rc.execute(
                    "SELECT COUNT(*) FROM audit_queue WHERE status IN ('awaiting_addresses', 'awaiting_poc', 'awaiting_verdict')"
                ).fetchone()
        return int(row[0] or 0) if row is not None else 0

    def list_agent_pending_items(self, session_id: Optional[str] = None) -> List[Dict[str, Any]]:
        sid = str(session_id or "").strip().lower()
        with self._read_conn() as rc:
            if sid:
                rows = rc.execute(
                    "SELECT * FROM audit_queue WHERE session_id=? AND status IN ('awaiting_addresses', 'awaiting_poc', 'awaiting_verdict') ORDER BY priority ASC, sort_rank DESC, tvl_usd DESC, slug ASC",
                    (sid,),
                ).fetchall()
            else:
                rows = rc.execute(
                    "SELECT * FROM audit_queue WHERE status IN ('awaiting_addresses', 'awaiting_poc', 'awaiting_verdict') ORDER BY priority ASC, sort_rank DESC, tvl_usd DESC, slug ASC"
                ).fetchall()
        return [self._row_to_queue_dict(r) for r in rows]

    def list_done_slugs(self) -> Set[str]:
        with self._read_conn() as rc:
            rows = rc.execute("SELECT slug FROM audit_queue WHERE status = 'done'").fetchall()
        return {ns for r in rows if r and r[0] and (ns := _norm_slug(str(r[0])))}

    def get_queue_status(self, slug: str) -> str:
        norm_s = _norm_slug(slug)
        if not norm_s:
            return ""
        with self._read_conn() as rc:
            row = rc.execute("SELECT status FROM audit_queue WHERE slug=?", (norm_s,)).fetchone()
        return str(row["status"] or "") if row is not None else ""

    def list_mode_b_primary_items(self) -> List[Dict[str, Any]]:
        """Mode B 원천 사건 시드(파생 매치·클론 제외) 전체 목록 조회."""
        with self._read_conn() as rc:
            rows = rc.execute(
                "SELECT * FROM audit_queue WHERE mode='B' AND slug NOT LIKE 'modeb-match-%' AND slug NOT LIKE 'modeb-clone-%' ORDER BY sort_rank DESC, slug ASC"
            ).fetchall()
        return [self._row_to_queue_dict(r) for r in rows]

    def list_existing_slugs(self, slugs: Sequence[str]) -> Set[str]:
        clean_s = list(dict.fromkeys(ns for s in slugs if (ns := _norm_slug(s))))
        if not clean_s:
            return set()
        found: Set[str] = set()
        with self._read_conn() as rc:
            for off in range(0, len(clean_s), 200):
                chunk = clean_s[off : off + 200]
                qm = ",".join("?" for _ in chunk)
                rows = rc.execute(f"SELECT slug FROM audit_queue WHERE slug IN ({qm})", chunk).fetchall()
                for r in rows:
                    found.add(str(r[0]))
        return found

    def set_queue_agent_state(self, slug: str, status: str, session_id: str = "") -> None:
        now = time.time()
        norm_s = _norm_slug(slug)
        sid = str(session_id or "").strip().lower()
        with self._write_tx():
            if sid:
                self._conn.execute(
                    "UPDATE audit_queue SET status=?, session_id=?, needs_agent=1, updated_at=? WHERE slug=?",
                    (str(status), sid, now, norm_s),
                )
                self._conn.execute(
                    "UPDATE audit_sessions SET active_slug=?, heartbeat_at=? WHERE session_id=?",
                    (norm_s, now, sid),
                )
            else:
                self._conn.execute(
                    "UPDATE audit_queue SET status=?, needs_agent=1, updated_at=? WHERE slug=?",
                    (str(status), now, norm_s),
                )

    def release_other_session_delegations(self, session_id: str, keep_slug: str = "") -> int:
        """세션이 수익 확정(profit_slug)으로 종료할 때, 타 위임 대기 건의 session_id 점유를 해제해 전역/타 세션이 이어받도록 반환한다."""
        sid = str(session_id or "").strip().lower()
        if not sid:
            return 0
        keep_n = _norm_slug(keep_slug) if keep_slug else ""
        now = time.time()
        with self._write_tx():
            if keep_n:
                cur = self._conn.execute(
                    "UPDATE audit_queue SET session_id='', updated_at=? "
                    "WHERE session_id=? AND slug!=? AND status IN ('awaiting_addresses','awaiting_poc','awaiting_verdict')",
                    (now, sid, keep_n),
                )
            else:
                cur = self._conn.execute(
                    "UPDATE audit_queue SET session_id='', updated_at=? "
                    "WHERE session_id=? AND status IN ('awaiting_addresses','awaiting_poc','awaiting_verdict')",
                    (now, sid),
                )
            return int(cur.rowcount or 0)

    def requeue_with_addresses(
        self,
        slug: str,
        addresses: Sequence[str],
        chain: str = "",
        tvl_usd: Union[Decimal, int, str] = 0,
        mode: str = "",
    ) -> None:
        now = time.time()
        norm_s = _norm_slug(slug)
        normed = list(dict.fromkeys(filter(None, (_norm_addr(a) for a in addresses))))
        explicit_chain = _norm_chain(chain)
        explicit_mode = mode.strip().upper() if mode.strip().upper() in ("A", "B") else ""
        tvl_in_d = _to_dec(tvl_usd)
        with self._write_tx():
            row = self._conn.execute(
                "SELECT addresses_json, chain, tvl_usd, tvl_usd_dec, mode, priority, session_id FROM audit_queue WHERE slug=?",
                (norm_s,),
            ).fetchone()
            had_prev = False
            if row is None:
                eff_mode = explicit_mode or ("B" if norm_s.startswith(("modeb-", "case-")) else "A")
                eff_prio = 3 if eff_mode == "B" else 1
                eff_chain = explicit_chain or "ethereum"
                tvl_s = format(tvl_in_d, "f")
                self._conn.execute(
                    "INSERT INTO audit_queue(slug, priority, mode, chain, tvl_usd, tvl_usd_dec, addresses_json, principle_summary, needs_agent, status, claim_boot_id, session_id, claimed_at, updated_at) VALUES(?,?,?,?,?,?,?,'',0,'pending','RECOVERED','',0,?)",
                    (norm_s, eff_prio, eff_mode, eff_chain, tvl_s, tvl_s, json.dumps(normed, ensure_ascii=True), now),
                )
            else:
                prev = json.loads(row["addresses_json"] or "[]")
                had_prev = bool(prev)
                merged = list(dict.fromkeys([*normed, *prev]))
                prev_mode = str(row["mode"] or "").strip().upper()
                eff_mode = explicit_mode or (prev_mode if prev_mode in ("A", "B") else ("B" if norm_s.startswith(("modeb-", "case-")) else "A"))
                eff_prio = int(row["priority"]) if (not explicit_mode and row["priority"] is not None) else (3 if eff_mode == "B" else 1)
                eff_chain = explicit_chain or _norm_chain(str(row["chain"] or "")) or "ethereum"
                prev_tvl_d = _to_dec(row["tvl_usd_dec"] if row["tvl_usd_dec"] not in (None, "", "0") else (row["tvl_usd"] or 0))
                eff_tvl_d = max(tvl_in_d, prev_tvl_d)
                eff_tvl_s = format(eff_tvl_d, "f")
                old_sid = str(row["session_id"] or "").strip().lower()
                self._conn.execute(
                    "UPDATE audit_queue SET priority=?, mode=?, chain=?, tvl_usd=?, tvl_usd_dec=?, addresses_json=?, status='pending', needs_agent=0, claim_boot_id='RECOVERED', session_id='', claimed_at=0, verdict='', net_krw=0, net_krw_exact='0', updated_at=? WHERE slug=?",
                    (eff_prio, eff_mode, eff_chain, eff_tvl_s, eff_tvl_s, json.dumps(merged, ensure_ascii=True), now, norm_s),
                )
                if old_sid:
                    self._conn.execute("UPDATE audit_sessions SET active_slug='' WHERE session_id=? AND active_slug=?", (old_sid, norm_s))
            if normed:
                pm_row = self._conn.execute("SELECT meta_json FROM proto_meta WHERE slug=?", (norm_s,)).fetchone()
                pm_dict: Dict[str, Any] = {}
                if pm_row is not None and pm_row["meta_json"]:
                    try:
                        parsed_pm = json.loads(pm_row["meta_json"])
                        if isinstance(parsed_pm, dict):
                            pm_dict = parsed_pm
                    except (json.JSONDecodeError, ValueError, TypeError):
                        pm_dict = {}
                pm_dict["agent_addresses_recovered"] = True
                if eff_mode == "B" and not had_prev:
                    pm_dict["mode_b_zero_seed_recovered"] = True
                self._conn.execute(
                    "INSERT OR REPLACE INTO proto_meta(slug, meta_json, updated_at) VALUES(?,?,?)",
                    (norm_s, json.dumps(pm_dict, ensure_ascii=False), now),
                )

    def recover_zombie_claims(self, current_boot_id: str, active_session_id: str = "", lease_ttl_sec: float = 1800.0) -> int:
        """
        다중 병렬 세션 보호형 좀비 클레임·고아 임대 회수 + 중단 대상 최우선 배정('RECOVERED'):
        - 실행 중 죽은 PID 또는 CLAIM_TTL_SEC 만료 'claimed' 항목 회수.
        - 장시간(lease_ttl_sec) 하트비트 갱신이 끊긴 방치 세션의 'awaiting_poc'/'awaiting_verdict' 임대 회수.
        - 활성 세션의 작업 중 항목은 절대 침범·선점하지 않음.
        """
        now = time.time()
        cutoff = now - CLAIM_TTL_SEC
        lease_cutoff = now - max(60.0, float(lease_ttl_sec))
        cur_host = str(current_boot_id).split(":pid=", 1)[0]
        act_sid = str(active_session_id or "").strip().lower()
        zombies: List[Tuple[str, str]] = []
        stale_leases: List[Tuple[str, str]] = []
        with self._write_tx():
            rows = self._conn.execute(
                "SELECT slug, claim_boot_id, session_id, claimed_at FROM audit_queue WHERE status='claimed'"
            ).fetchall()
            for r in rows:
                slug = str(r["slug"])
                c_boot = str(r["claim_boot_id"] or "")
                r_sid = str(r["session_id"] or "")
                c_at = float(r["claimed_at"] or 0.0)
                if ":pid=" in c_boot:
                    r_host, pid_part = c_boot.split(":pid=", 1)
                    try:
                        owner_pid = int(pid_part)
                    except ValueError:
                        owner_pid = -1
                    same_boot = (r_host == cur_host)
                    if not same_boot and r_host.startswith("win-") and cur_host.startswith("win-"):
                        try:
                            same_boot = abs(int(r_host[4:]) - int(cur_host[4:])) <= 1
                        except ValueError:
                            same_boot = False
                    owner_alive = bool(same_boot and _is_pid_alive(owner_pid))
                    if owner_alive and (owner_pid == os.getpid() or (act_sid and r_sid.lower() == act_sid)):
                        continue
                    if not owner_alive:
                        zombies.append((slug, r_sid))
                        continue
                    if c_at < cutoff:
                        zombies.append((slug, r_sid))
                else:
                    if act_sid and r_sid.lower() == act_sid and c_boot == str(current_boot_id):
                        continue
                    if c_at < cutoff or c_boot != str(current_boot_id):
                        zombies.append((slug, r_sid))

            wait_rows = self._conn.execute(
                "SELECT q.slug, q.status, q.session_id, q.updated_at, "
                "COALESCE(s.heartbeat_at, q.updated_at) AS hb, "
                "s.session_id AS s_exists, COALESCE(s.active_slug, '') AS s_active "
                "FROM audit_queue q LEFT JOIN audit_sessions s ON q.session_id = s.session_id "
                "WHERE q.status IN ('pending', 'awaiting_addresses', 'awaiting_poc', 'awaiting_verdict') AND q.session_id != ''"
            ).fetchall()
            for wr in wait_rows:
                w_slug = str(wr["slug"])
                w_status = str(wr["status"] or "")
                w_sid = str(wr["session_id"] or "")
                if w_sid == act_sid:
                    continue
                orphan_pending = (w_status == "pending") and (wr["s_exists"] is None or str(wr["s_active"] or "") != w_slug)
                if orphan_pending or max(float(wr["updated_at"] or 0.0), float(wr["hb"] or 0.0)) < lease_cutoff:
                    stale_leases.append((w_slug, w_sid))

            for z_slug, z_sid in zombies:
                self._conn.execute(
                    "UPDATE audit_queue SET status='pending', claim_boot_id='RECOVERED', session_id='', claimed_at=0 WHERE slug=? AND status='claimed'",
                    (z_slug,),
                )
                if z_sid:
                    self._conn.execute("UPDATE audit_sessions SET active_slug='' WHERE session_id=? AND active_slug=?", (z_sid, z_slug))
            for s_slug, s_sid in stale_leases:
                self._conn.execute(
                    "UPDATE audit_queue SET session_id='', claim_boot_id='RECOVERED' WHERE slug=? AND session_id=?",
                    (s_slug, s_sid),
                )
                self._conn.execute("UPDATE audit_sessions SET active_slug='' WHERE session_id=? AND active_slug=?", (s_sid, s_slug))
        return len(zombies) + len(stale_leases)

    def bind_orphan_agent_item_to_session(self, session_id: str) -> Optional[str]:
        """하트비트 만료로 회수된 무소유('session_id == \"\"') 에이전트 대기 항목이 있으면 새 세션에 즉시 승계."""
        sid = str(session_id or "").strip().lower()
        if not sid:
            return None
        now = time.time()
        with self._write_tx():
            s_row = self._conn.execute("SELECT active_slug, profit_slug FROM audit_sessions WHERE session_id=?", (sid,)).fetchone()
            if s_row is None or str(s_row["active_slug"] or "") or str(s_row["profit_slug"] or ""):
                return None
            r = self._conn.execute(
                "SELECT slug FROM audit_queue WHERE status IN ('awaiting_addresses', 'awaiting_poc', 'awaiting_verdict') AND session_id='' "
                "ORDER BY priority ASC, sort_rank DESC, tvl_usd DESC, slug ASC LIMIT 1"
            ).fetchone()
            if r is None:
                return None
            slug = str(r["slug"])
            self._conn.execute("UPDATE audit_queue SET session_id=?, updated_at=? WHERE slug=?", (sid, now, slug))
            self._conn.execute("UPDATE audit_sessions SET active_slug=?, heartbeat_at=? WHERE session_id=?", (slug, now, sid))
        pdir_b = ARTIFACT_ROOT / _norm_slug(slug)
        resume_cmd_b = f"{CLI_INVOKE_PREFIX} run {sid}"
        req_files_b: List[Path] = [pdir_b / "address_request.json"]
        poc_dir_b = pdir_b / "poc_requests"
        if poc_dir_b.is_dir():
            req_files_b.extend(sorted(poc_dir_b.glob("poc_request_*.json")))
        for req_f_b in req_files_b:
            if req_f_b.is_file():
                r_doc_b = _read_json(req_f_b, default=None)
                if isinstance(r_doc_b, dict):
                    r_doc_b["session_id"] = sid
                    iso_b = r_doc_b.get("isolated_commands")
                    if isinstance(iso_b, dict):
                        iso_b["resume_engine"] = resume_cmd_b
                        pv_cmd_b = str(iso_b.get("preverify_forge_test") or "")
                        m_cid_b = _POC_REQ_CID_FILE_RE.match(req_f_b.name)
                        if m_cid_b:
                            cid_b = int(m_cid_b.group(1))
                            sol_b = pdir_b / "forge" / "test" / f"test_{cid_b}.t.sol"
                            _upgrade_unedited_legacy_skeleton_file(sol_b, req_doc=r_doc_b)
                            ws_env_b = pdir_b / "forge" / "_isolated_env.json"
                            if pv_cmd_b and "_run_preverify_forge_cli" not in pv_cmd_b and ws_env_b.is_file():
                                idx_fb = pv_cmd_b.find(f'"{FORGE_BIN}"')
                                if idx_fb >= 0:
                                    iso_b["preverify_forge_test"] = _wrap_preverify_forge_cmd(
                                        ws_env_b, req_f_b, pv_cmd_b[idx_fb:]
                                    )
                    _refresh_pending_request_doc(r_doc_b)
                    _write_json_atomic(req_f_b, r_doc_b, compact=True)
        # `process_agent_submissions`는 checkpoint/result의 session_id를 DB보다 우선하므로, 승계 후에도 옛(사망) 세션 ID가 남으면
        # 소유권·profit_slug가 죽은 세션으로 되돌아간다. 두 파일의 소유 세션을 새 세션으로 동기화한다.
        for own_f_b in (pdir_b / "checkpoint.json", pdir_b / "result.json"):
            if own_f_b.is_file():
                own_doc_b = _read_json(own_f_b, default=None)
                if isinstance(own_doc_b, dict) and str(own_doc_b.get("session_id") or "").strip().lower() != sid:
                    own_doc_b["session_id"] = sid
                    _write_json_atomic(own_f_b, own_doc_b, compact=True)
        return slug

    def complete_queue_items_batch(
        self,
        items: Sequence[Tuple[str, str, Union[int, Decimal]]],
    ) -> int:
        if not items:
            return 0
        now = time.time()
        norm_items: List[Tuple[str, str, int, str, int, bool]] = []
        for raw_slug, verdict, net_krw in items:
            norm_s = _norm_slug(raw_slug)
            if not norm_s:
                continue
            krw_sql_i, krw_exact_s = self._coerce_krw_int(net_krw)
            norm_items.append((norm_s, str(verdict), krw_sql_i, krw_exact_s, int(krw_exact_s), _is_profit_verdict(verdict)))
        if not norm_items:
            return 0
        unique_slugs = list(dict.fromkeys(it[0] for it in norm_items))
        with self._write_tx():
            owner_by_slug: Dict[str, str] = {}
            for off in range(0, len(unique_slugs), 200):
                chunk = unique_slugs[off : off + 200]
                qm = ",".join("?" for _ in chunk)
                for qr in self._conn.execute(f"SELECT slug, session_id FROM audit_queue WHERE slug IN ({qm})", chunk):
                    owner_by_slug[str(qr["slug"])] = str(qr["session_id"] or "")
            self._conn.executemany(
                "UPDATE audit_queue SET status='done', needs_agent=0, verdict=?, net_krw=?, net_krw_exact=?, updated_at=? WHERE slug=?",
                [(v, ksi, kes, now, ns) for ns, v, ksi, kes, _, _ in norm_items],
            )
            slug_set = set(unique_slugs)
            owner_sids = {sid for sid in owner_by_slug.values() if sid}
            sess_by_id: Dict[str, Dict[str, Any]] = {}
            sids_by_active: Dict[str, List[str]] = {}
            for sr in self._conn.execute(
                "SELECT session_id, active_slug, completed_slugs, profit_slug, profit_verdict, profit_krw, profit_krw_exact, status FROM audit_sessions"
            ):
                sid = str(sr["session_id"])
                act_s = str(sr["active_slug"] or "")
                if sid in owner_sids or act_s in slug_set:
                    comp_l = list(dict.fromkeys(json.loads(sr["completed_slugs"] or "[]")))
                    sess_by_id[sid] = {
                        "active_slug": act_s,
                        "completed": comp_l,
                        "completed_set": set(comp_l),
                        "profit_slug": str(sr["profit_slug"] or ""),
                        "profit_verdict": str(sr["profit_verdict"] or ""),
                        "profit_krw_sql": int(sr["profit_krw"] or 0),
                        "profit_krw_exact": str(sr["profit_krw_exact"] or "0"),
                        "profit_krw_full": self._read_krw_int(sr["profit_krw_exact"], sr["profit_krw"]),
                        "status": str(sr["status"] or "active"),
                        "prof_updated": False,
                        "dirty": False,
                    }
                    if act_s:
                        sids_by_active.setdefault(act_s, []).append(sid)
            for ns, verdict, krw_sql_i, krw_exact_s, krw_full_i, is_prof in norm_items:
                target_sids: List[str] = []
                o_sid = owner_by_slug.get(ns, "")
                if o_sid and o_sid in sess_by_id:
                    target_sids.append(o_sid)
                for a_sid in sids_by_active.get(ns, ()):
                    if a_sid != o_sid and a_sid in sess_by_id:
                        target_sids.append(a_sid)
                for sid in target_sids:
                    sd = sess_by_id[sid]
                    if ns not in sd["completed_set"]:
                        sd["completed_set"].add(ns)
                        sd["completed"].append(ns)
                    if sd["active_slug"] == ns:
                        sd["active_slug"] = ""
                    if is_prof and (not sd["profit_slug"] or krw_full_i > sd["profit_krw_full"]):
                        sd["profit_slug"] = ns
                        sd["profit_verdict"] = verdict
                        sd["profit_krw_sql"] = krw_sql_i
                        sd["profit_krw_exact"] = krw_exact_s
                        sd["profit_krw_full"] = krw_full_i
                        sd["status"] = "profit_ready"
                        sd["active_slug"] = ""
                        sd["prof_updated"] = True
                    sd["dirty"] = True
            prof_updates: List[Tuple[Any, ...]] = []
            norm_updates: List[Tuple[Any, ...]] = []
            for sid, sd in sess_by_id.items():
                if not sd["dirty"]:
                    continue
                comp_json = json.dumps(sd["completed"], ensure_ascii=True)
                if sd["prof_updated"]:
                    prof_updates.append((sd["profit_slug"], sd["profit_verdict"], sd["profit_krw_sql"], sd["profit_krw_exact"], comp_json, now, sid))
                else:
                    norm_updates.append((sd["active_slug"], comp_json, now, sid))
            if prof_updates:
                self._conn.executemany(
                    "UPDATE audit_sessions SET active_slug='', profit_slug=?, profit_verdict=?, profit_krw=?, profit_krw_exact=?, completed_slugs=?, status='profit_ready', heartbeat_at=? WHERE session_id=?",
                    prof_updates,
                )
            if norm_updates:
                self._conn.executemany(
                    "UPDATE audit_sessions SET active_slug=?, completed_slugs=?, heartbeat_at=? WHERE session_id=?",
                    norm_updates,
                )
        return len(norm_items)

    def complete_queue_item(self, slug: str, verdict: str, net_krw: Union[int, Decimal] = 0) -> None:
        self.complete_queue_items_batch([(slug, verdict, net_krw)])

    def queue_counts(self) -> Dict[str, int]:
        counts = {"pending": 0, "claimed": 0, "awaiting_addresses": 0, "awaiting_poc": 0, "awaiting_verdict": 0, "done": 0}
        with self._read_conn() as rc:
            rows = rc.execute("SELECT status, COUNT(*) AS cnt FROM audit_queue GROUP BY status").fetchall()
        for r in rows:
            st = str(r["status"])
            counts[st] = int(r["cnt"])
        return counts

    def queue_mode_breakdown(self) -> Dict[str, Dict[str, int]]:
        base_template = lambda: {
            "total": 0,
            "done": 0,
            "pending": 0,
            "claimed": 0,
            "awaiting_addresses": 0,
            "awaiting_poc": 0,
            "awaiting_verdict": 0,
            "profit": 0,
            "safe": 0,
            "blocked": 0,
        }
        out: Dict[str, Dict[str, int]] = {"A": base_template(), "B": base_template()}
        with self._read_conn() as rc:
            rows = rc.execute("SELECT mode, status, verdict, COUNT(*) AS cnt FROM audit_queue GROUP BY mode, status, verdict").fetchall()
        for r in rows:
            m = "B" if str(r["mode"] or "A").upper() == "B" else "A"
            st = str(r["status"] or "pending")
            vd = str(r["verdict"] or "")
            cnt = int(r["cnt"] or 0)
            bucket = out[m]
            bucket["total"] += cnt
            if st in bucket:
                bucket[st] += cnt
            if st == "done":
                if _is_profit_verdict(vd):
                    bucket["profit"] += cnt
                elif vd == VERDICT_SAFE:
                    bucket["safe"] += cnt
                elif vd == VERDICT_BLOCKED:
                    bucket["blocked"] += cnt
        return out


ARTIFACT_ROOT: Path = AUDIT_ROOT
LOCK_FILE_PATH: Path = QUEUE_LOCK_PATH
HOST_BOOT_ID: str = _host_boot_id()
BOOT_ID: str = f"{HOST_BOOT_ID}:pid={os.getpid()}"


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            chunk = fh.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()

