def _strip_chain_suffix_slug(slug: str) -> str:
    ns = _norm_slug(slug)
    if "-" not in ns:
        return ns
    for multi_suf in (
        "-arbitrum-nova", "-polygon-zkevm", "-zklink-nova", "-astar-zkevm",
        "-oasis-emerald", "-cronos-zkevm", "-swell-chain", "-world-chain",
        "-bnb-chain", "-polygon-pos", "-avalanche-c-chain", "-gnosis-chain",
    ):
        if ns.endswith(multi_suf) and len(ns) > len(multi_suf):
            return ns[: -len(multi_suf)]
    head, tail = ns.rsplit("-", 1)
    if head and tail not in _AMBIGUOUS_PROTOCOL_SUFFIX_WORDS and (tail in CHAIN_IDS or tail in CHAIN_ALIASES):
        return head
    return ns

