def _rpc_quorum_provider_key(url: str) -> str:
    """RPC 엔드포인트 URL을 운영자 등록 도메인(`eTLD+1`)으로 정규화하여 동일 운영자의 별칭 서브도메인 중복 정족수를 차단한다."""
    parsed = urllib.parse.urlparse(str(url or ""))
    netloc = parsed.netloc.lower() or str(url or "").lower()
    host = (parsed.hostname or "").lower().strip(".")
    if not host or host == "localhost" or ":" in host or all(ch.isdigit() or ch == "." for ch in host):
        return netloc
    parts = [p for p in host.split(".") if p]
    if len(parts) >= 3 and len(parts[-1]) == 2 and parts[-2] in ("co", "com", "net", "org", "gov", "ac", "edu"):
        return ".".join(parts[-3:])
    if len(parts) >= 2:
        return ".".join(parts[-2:])
    return host

