_HTTP_AUTH_CODE_RE: re.Pattern[str] = re.compile(r"(?:http\s+|status[\s:=]+|\bcode[\s:=]+)(?:401|403)\b|\b(?:401|403)\s*(?::|unauthorized|forbidden)", re.IGNORECASE)
