_HTTP_SHRINK_CODE_RE: re.Pattern[str] = re.compile(r"(?:http\s+|status[\s:=]+|\bcode[\s:=]+)413\b|\b413\s*(?::|payload|request entity)", re.IGNORECASE)
_HTTP_DEAD_CODE_RE: re.Pattern[str] = re.compile(r"(?:http\s+|status[\s:=]+|\bcode[\s:=]+)(?:404|410)\b|\b(?:404|410)\s*(?::|not found|gone)", re.IGNORECASE)

