@functools.lru_cache(maxsize=4096)
def _norm_chain_cached(s: str) -> str:
    raw = _SLUG_CLEAN_RE.sub("", s.lower())
    if not raw:
        return ""
    if raw.isdigit():
        cid = int(raw)
        if cid in CHAIN_BY_ID:
            return CHAIN_BY_ID[cid]
    mapped = CHAIN_ALIASES.get(raw, raw)
    if mapped in CHAIN_IDS:
        return mapped
    for extra_k, extra_v in (
        ("eth", "ethereum"),
        ("ethereummainnet", "ethereum"),
        ("mainnet", "ethereum"),
        ("arb", "arbitrum"),
        ("arbitrumone", "arbitrum"),
        ("op", "optimism"),
        ("bnb", "bsc"),
        ("binance", "bsc"),
        ("binancesmartchain", "bsc"),
        ("matic", "polygon"),
        ("ftm", "fantom"),
        ("era", "zksync"),
    ):
        if raw == extra_k:
            return extra_v
    return mapped


def _norm_chain(name: Any) -> str:
    if not name:
        return ""
    if isinstance(name, str):
        return _norm_chain_cached(name)
    return _norm_chain_cached(str(name))


def _usable_chain(name: Any) -> bool:
    c = _norm_chain(name)
    if not c or any(kw in c for kw in TESTNET_KWS):
        return False
    if c in NON_EVM_CHAINS:
        return False
    return c in CHAIN_IDS


def _default_batch_cap_for_url(url: str) -> int:
    try:
        host = (urllib.parse.urlparse(url).hostname or "").lower()
    except Exception:
        host = ""
    for suffix, cap in _BATCH_CAP_BY_HOST:
        if host.endswith(suffix):
            return cap
    return 100


def _read_body_deadlined(resp: Any, timeout_sec: float, max_bytes: int = 16 * 1024 * 1024) -> bytes:
    deadline = time.monotonic() + max(1.0, float(timeout_sec))
    chunks: List[bytes] = []
    total = 0
    while True:
        if time.monotonic() > deadline:
            raise TimeoutError("HTTP response body read exceeded wall-clock deadline")
        chunk = resp.read(65536)
        if not chunk:
            break
        chunks.append(chunk)
        total += len(chunk)
        if total > max_bytes:
            raise OverflowError(f"HTTP response exceeded {max_bytes} bytes")
    return b"".join(chunks)


def _text_has_any_marker(text: Any, markers: Sequence[str]) -> bool:
    tl = str(text or "").lower()
    return any(m in tl for m in markers)


def _is_auth_denied_rpc_error(exc_or_err: Any) -> bool:
    txt = str(exc_or_err or "")
    if "CHEATCODE" in txt or "FORBIDDEN_" in txt:
        return False
    return bool(_text_has_any_marker(txt, _AUTH_DENIED_MARKERS) or _HTTP_AUTH_CODE_RE.search(txt))


def _classify_rpc_error(exc_or_err: Any) -> str:
    txt = str(exc_or_err or "").lower()
    if ("reorg" in txt or "block reverted" in txt) and "execution reverted" not in txt:
        return "gap"
    if any(m in txt for m in _REVERT_ERR_MARKERS):
        return "revert"
    if "wrong_chain" in txt or "chainid mismatch" in txt:
        return "wrong_chain"
    if isinstance(exc_or_err, _DeterministicHTTPClientError) and getattr(exc_or_err, "status", 0) in (401, 403, 404, 410):
        return "auth_dead"
    if (
        (any(m in txt for m in _DEAD_ENDPOINT_MARKERS) or _HTTP_AUTH_CODE_RE.search(txt) or _HTTP_DEAD_CODE_RE.search(txt))
        and "header not found" not in txt
        and "block not found" not in txt
        and "transaction not found" not in txt
        and "receipt not found" not in txt
        and "method not found" not in txt
        and "missing trie node" not in txt
    ):
        return "auth_dead"
    if any(m in txt for m in _QUOTA_ERR_MARKERS) or _HTTP_QUOTA_CODE_RE.search(txt):
        return "quota"
    if any(m in txt for m in _LOG_RANGE_ERR_MARKERS):
        return "range_limit"
    if any(m in txt for m in _SHRINK_ERR_MARKERS) or _HTTP_SHRINK_CODE_RE.search(txt):
        return "shrink"
    if isinstance(exc_or_err, TimeoutError) or any(m in txt for m in _TIMEOUT_ERR_MARKERS):
        return "timeout"
    return "gap"


class _DeterministicHTTPClientError(RuntimeError):
    def __init__(self, status: int, body_preview: str = "") -> None:
        super().__init__(f"HTTP {status}: {body_preview}".rstrip(": "))
        self.status = status


class RPCRouter:
    """스레드 로컬 Keep-Alive 커넥션 풀 + 적응형 배치 + 체인 ID 검증 + TTL 격리 복구 + 다중 엔드포인트 쿼럼 헤드."""

    _QUARANTINE_TTL_SEC: float = 3600.0

    def __init__(self, store: Optional[SQLiteStore] = None, session_id: str = "") -> None:
        self.store = store
        self.session_id: str = str(session_id or "").strip().lower()
        self._session_salt: int = (
            (int(hashlib.sha256(self.session_id.encode("utf-8")).hexdigest()[:8], 16) | 1)
            if self.session_id
            else 0
        )
        self._tls = threading.local()
        self._lock = threading.RLock()
        self._batch_caps: Dict[str, int] = {}
        self._rtt_ms: Dict[str, float] = {}
        self._cool_until: Dict[str, float] = {}
        self._demote_until: Dict[str, float] = {}
        self._quarantine_until: Dict[Tuple[int, str], float] = {}
        self._auth_fail_streak: Dict[Tuple[int, str], int] = {}
        self._last_persisted_at: Dict[str, float] = {}
        self._last_shared_sync_at: float = 0.0
        self._verified_chain_urls: Set[Tuple[int, str]] = set()
        self._no_multicall_chains: Set[str] = set()
        self._live_log_max_span_by_chain: Dict[str, int] = {}
        self._mc3_cache: Dict[Tuple[str, int, bytes], List[Tuple[bool, bytes]]] = {}
        self._bm_cursor: int = 0
        self._ssl_ctx = ssl.create_default_context()
        self._sync_shared_endpoints_if_due(force=True)

    def _sync_shared_endpoints_if_due(self, force: bool = False) -> None:
        if self.store is None:
            return
        mono_now = time.monotonic()
        with self._lock:
            if not force and (mono_now - self._last_shared_sync_at) < 2.0:
                return
            self._last_shared_sync_at = mono_now
        try:
            now = time.time()
            rows = self.store.load_rpc_endpoints()
            with self._lock:
                for row in rows:
                    u = _endpoint_storage_key(str(row.get("url") or ""))
                    rcid = int(row.get("chain_id") or 0)
                    if not u:
                        continue
                    du = float(row.get("demote_until") or 0.0)
                    if int(row.get("quarantined") or 0) == 1:
                        if du > now and rcid > 0:
                            self._quarantine_until[(rcid, u)] = max(self._quarantine_until.get((rcid, u), 0.0), du)
                    elif du > now:
                        self._demote_until[u] = max(self._demote_until.get(u, 0.0), du)
                    bcap = int(row.get("batch_cap") or 0)
                    if bcap > 0 and u not in self._batch_caps:
                        def_cap = _default_batch_cap_for_url(u)
                        if du <= now and bcap < min(12, def_cap) and _is_live_real_router(self):
                            bcap = min(def_cap, 25)
                        self._batch_caps[u] = bcap
                    rtt = float(row.get("rtt_ms") or 0.0)
                    if 0.0 < rtt < 60000.0 and u not in self._rtt_ms:
                        self._rtt_ms[u] = rtt
                    cu = float(row.get("cool_until") or 0.0)
                    if cu > now:
                        self._cool_until[u] = max(self._cool_until.get(u, 0.0), cu)
        except _RECOVERABLE_IO_EXC:
            pass

    def _get_conn_pool(self) -> Dict[Tuple[str, str, int], http.client.HTTPConnection]:
        pool = getattr(self._tls, "conn_pool", None)
        if pool is None:
            pool = {}
            self._tls.conn_pool = pool
        return pool

    @staticmethod
    def _parse_http_endpoint(url: str) -> Tuple[str, str, int, str]:
        parsed = urllib.parse.urlparse(url)
        scheme = (parsed.scheme or "https").lower()
        host = parsed.hostname or ""
        port = parsed.port or (443 if scheme == "https" else 80)
        path = parsed.path or "/"
        if parsed.query:
            path = f"{path}?{parsed.query}"
        return scheme, host, port, path

    def _pooled_http_exchange(
        self,
        scheme: str,
        host: str,
        port: int,
        method: str,
        path: str,
        headers: Dict[str, str],
        timeout: float,
        body: Optional[bytes] = None,
    ) -> Tuple[int, bytes]:
        key = (scheme, host, port)
        pool = self._get_conn_pool()
        for attempt in range(2):
            conn = pool.get(key)
            try:
                if conn is None:
                    conn = (
                        http.client.HTTPSConnection(host, port, timeout=timeout, context=self._ssl_ctx)
                        if scheme == "https"
                        else http.client.HTTPConnection(host, port, timeout=timeout)
                    )
                    pool[key] = conn
                conn.timeout = timeout
                if getattr(conn, "sock", None) is not None:
                    conn.sock.settimeout(timeout)
                conn.request(method, path, body=body, headers=headers)
                resp = conn.getresponse()
                raw = _read_body_deadlined(resp, timeout)
                return int(resp.status), raw
            except Exception:
                pool.pop(key, None)
                try:
                    if conn is not None:
                        conn.close()
                except _OS_CLEANUP_EXC:
                    pass
                if attempt == 1:
                    raise
        raise RuntimeError("Unreachable HTTP pool exit")

    def _pooled_post(self, url: str, body: bytes, timeout: float) -> bytes:
        scheme, host, port, path = self._parse_http_endpoint(url)
        if not host:
            raise ValueError(f"Invalid RPC URL: {_redact_secrets_in_text(url)}")
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Connection": "keep-alive",
            "User-Agent": "defi-audit-engine/1.0",
        }
        if host.endswith("blockmachine.io") and BLOCKMACHINE_API_KEYS:
            with self._lock:
                bm_key = BLOCKMACHINE_API_KEYS[self._bm_cursor % len(BLOCKMACHINE_API_KEYS)]
                self._bm_cursor += 1
            if bm_key:
                headers["x-api-key"] = bm_key
        status, raw = self._pooled_http_exchange(scheme, host, port, "POST", path, headers, timeout, body=body)
        if status >= 400:
            raise RuntimeError(f"HTTP {status}: {_redact_secrets_in_text(raw[:200].decode('utf-8', errors='replace'))}")
        return raw

    def http_get_json(self, url: str, timeout: float = 15.0, extra_headers: Optional[Dict[str, str]] = None) -> Any:
        hdrs = {
            "Accept": "application/json",
            "Connection": "keep-alive",
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) DefiAudit/1.0",
        }
        if extra_headers:
            hdrs.update(extra_headers)
        scheme, host, port, path = self._parse_http_endpoint(url)
        if host and scheme in ("http", "https"):
            pooled_status: Optional[int] = None
            pooled_raw: bytes = b""
            try:
                pooled_status, pooled_raw = self._pooled_http_exchange(scheme, host, port, "GET", path, hdrs, timeout)
            except Exception:
                pooled_status = None
            if pooled_status is not None and not (300 <= pooled_status < 400):
                if pooled_status in (400, 404, 410):
                    raise _DeterministicHTTPClientError(pooled_status)
                if pooled_status >= 400:
                    raise RuntimeError(f"HTTP {pooled_status}")
                try:
                    return json.loads(pooled_raw.decode("utf-8", errors="replace"))
                except _PARSE_DATA_EXC:
                    pass
        req = urllib.request.Request(url, headers={k: v for k, v in hdrs.items() if k != "Connection"})
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = _read_body_deadlined(resp, timeout)
                return json.loads(raw.decode("utf-8", errors="replace"))
        except urllib.error.HTTPError as exc:
            if exc.code in (400, 404, 410):
                raise _DeterministicHTTPClientError(exc.code) from exc
            raise

    def candidate_urls(self, chain: str, need_archive: bool = False, for_forge: bool = False) -> List[str]:
        c = _norm_chain(chain)
        if c not in CHAIN_IDS:
            return []
        cid = CHAIN_IDS[c]
        base_urls = list(CHAIN_RPCS.get(c, []))
        arch_urls = list(KEYLESS_ARCHIVE_RPCS.get(c, []))
        bslug = _BM_SLUGS.get(c)
        if bslug and not for_forge:
            bm_url = f"https://rpc-{bslug}.blockmachine.io"
            if bm_url not in base_urls:
                base_urls.append(bm_url)
        keyed_urls: List[str] = []
        c_hash = int(hashlib.sha256(c.encode("utf-8")).hexdigest(), 16)

        def _append_rotated_keyed_urls(keys: Sequence[str], url_tmpl: str) -> None:
            if not keys:
                return
            start_i = c_hash % len(keys)
            for idx in range(len(keys)):
                kv = keys[(start_i + idx) % len(keys)]
                if kv:
                    keyed_urls.append(url_tmpl.format(key=kv))

        aslug = _ANKR_SLUGS.get(c)
        if aslug:
            _append_rotated_keyed_urls(ANKR_API_KEYS, f"https://rpc.ankr.com/{aslug}/{{key}}")
        nrslug = _NODEREAL_SLUGS.get(c)
        if nrslug:
            _append_rotated_keyed_urls(NODEREAL_API_KEYS, f"https://{nrslug}.nodereal.io/v1/{{key}}")
        for u in list(base_urls):
            if u.endswith("/v1/rpc/public") and "blockreq.com" in u:
                stem = u[:-len("/v1/rpc/public")]
                for bk in BLOCKREQ_API_KEYS:
                    if bk:
                        keyed_urls.append(f"{stem}/v1/rpc/{bk}")
        arch_set = set(arch_urls) | set(keyed_urls)
        if need_archive:
            # Fork PoC needs reliable archive at pinned block: keyed ANKR/BlockReq/Nodereal before keyless.
            # Exclude blockreq.com /v1/rpc/public (recent-1024-blocks only) when real archive/keyed endpoints exist.
            arch_base = [
                u for u in base_urls if not ("blockreq.com" in u and u.endswith("/v1/rpc/public"))
            ] or list(base_urls)
            ordered = list(
                dict.fromkeys((keyed_urls + arch_urls + arch_base) if for_forge else (arch_urls + keyed_urls + arch_base))
            )
        else:
            ordered = list(dict.fromkeys(base_urls + keyed_urls))
        if not ordered:
            return []
        self._sync_shared_endpoints_if_due(force=False)
        now = time.time()
        with self._lock:
            active: List[str] = []
            demoted: List[str] = []
            cooled: List[str] = []
            quarantined_pool: List[str] = []
            for u in ordered:
                uk = _endpoint_storage_key(u)
                qu = self._quarantine_until.get((cid, uk), 0.0)
                if qu > now:
                    quarantined_pool.append(u)
                    continue
                if qu > 0.0:
                    self._quarantine_until.pop((cid, uk), None)
                if self._cool_until.get(uk, 0.0) > now:
                    cooled.append(u)
                    continue
                if self._demote_until.get(uk, 0.0) > now:
                    demoted.append(u)
                else:
                    active.append(u)
            sort_fn = (
                (lambda u: (0 if u in arch_set else 1, self._rtt_ms.get(_endpoint_storage_key(u), 500.0)))
                if need_archive
                else (lambda u: self._rtt_ms.get(_endpoint_storage_key(u), 500.0))
            )
            active.sort(key=sort_fn)
            if self._session_salt and len(active) > 1:
                lead_arch = active[0] in arch_set if need_archive else True
                lead_rtt = self._rtt_ms.get(_endpoint_storage_key(active[0]), 500.0)
                top_k = 0
                for u_cand in active[:5]:
                    if need_archive and (u_cand in arch_set) != lead_arch:
                        break
                    if self._rtt_ms.get(_endpoint_storage_key(u_cand), 500.0) > lead_rtt + 150.0:
                        break
                    top_k += 1
                if top_k > 1:
                    rot_off = (self._session_salt + cid) % top_k
                    if rot_off:
                        active[:top_k] = active[rot_off:top_k] + active[:rot_off]
            demoted.sort(key=sort_fn)
            primary = active + demoted
            if primary:
                return primary
            if cooled:
                cooled.sort(key=lambda u: self._cool_until.get(_endpoint_storage_key(u), 0.0))
                return cooled
            return quarantined_pool

    def _verify_endpoint_chain_id(self, url: str, expected_cid: int, timeout: float = 6.0) -> bool:
        if expected_cid <= 0:
            return True
        uk = _endpoint_storage_key(url)
        with self._lock:
            if (expected_cid, uk) in self._verified_chain_urls:
                return True
        try:
            t0 = time.perf_counter()
            raw = self._pooled_post(
                url,
                b'{"jsonrpc":"2.0","id":1,"method":"eth_chainId","params":[]}',
                timeout=min(5.0, timeout),
            )
            doc = json.loads(raw.decode("utf-8", errors="replace"))
            res = doc.get("result") if isinstance(doc, dict) else None
            if isinstance(res, str) and res.startswith("0x"):
                got_cid = int(res, 16)
                if got_cid != expected_cid:
                    self._record_failure(url, "wrong_chain", cid=expected_cid)
                    return False
                with self._lock:
                    self._verified_chain_urls.add((expected_cid, uk))
                self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=expected_cid)
                return True
            self._record_failure(url, "gap", cid=expected_cid)
            return False
        except Exception as exc:
            kind_v = "auth_dead" if _is_auth_denied_rpc_error(exc) else _classify_rpc_error(exc)
            self._record_failure(url, kind_v, cid=expected_cid)
            return False

    def batch_cap_for(self, url: str) -> int:
        uk = _endpoint_storage_key(url)
        with self._lock:
            if uk not in self._batch_caps:
                self._batch_caps[uk] = _default_batch_cap_for_url(url)
            return self._batch_caps[uk]

    def _persist_endpoint_if_due(self, url: str, cid: int, force: bool = False) -> None:
        if self.store is None or cid <= 0:
            return
        now = time.time()
        uk = _endpoint_storage_key(url)
        with self._lock:
            if not force and (now - self._last_persisted_at.get(uk, 0.0)) < 60.0:
                return
            self._last_persisted_at[uk] = now
            bcap = self._batch_caps.get(uk, _default_batch_cap_for_url(url))
            rtt = self._rtt_ms.get(uk, 500.0)
            cu = self._cool_until.get(uk, 0.0)
            qu = self._quarantine_until.get((cid, uk), 0.0)
            quar = qu > now
            du = qu if quar else self._demote_until.get(uk, 0.0)
        try:
            self.store.save_rpc_endpoint(cid, url, batch_cap=bcap, rtt_ms=rtt, cool_until=cu, demote_until=du, quarantined=quar, last_ok_at=now if not quar else 0.0)
        except _RECOVERABLE_IO_EXC:
            pass

    def _record_success(self, url: str, elapsed_ms: float, cid: int = 0) -> None:
        uk = _endpoint_storage_key(url)
        with self._lock:
            prev = self._rtt_ms.get(uk)
            self._rtt_ms[uk] = elapsed_ms if prev is None else (0.7 * prev + 0.3 * elapsed_ms)
            if cid > 0:
                self._quarantine_until.pop((cid, uk), None)
                self._auth_fail_streak.pop((cid, uk), None)
        if cid > 0:
            self._persist_endpoint_if_due(url, cid, force=False)

    def _record_failure(self, url: str, kind: str, cid: int = 0) -> None:
        now = time.time()
        force_save = False
        uk = _endpoint_storage_key(url)
        with self._lock:
            if kind == "auth_dead":
                is_keyed_u = _is_keyed_rpc_url(url)
                streak_n = self._auth_fail_streak.get((cid, uk), 0) + 1
                self._auth_fail_streak[(cid, uk)] = streak_n
                if is_keyed_u or streak_n >= 2:
                    if cid > 0:
                        self._quarantine_until[(cid, uk)] = now + self._QUARANTINE_TTL_SEC
                    self._demote_until[uk] = now + self._QUARANTINE_TTL_SEC
                    self._cool_until[uk] = now + self._QUARANTINE_TTL_SEC
                else:
                    # Single transient 403/WAF burst on keyless public RPC: short cool+demote instead of 1h quarantine
                    self._demote_until[uk] = now + 300.0
                    self._cool_until[uk] = now + 45.0
                force_save = True
            elif kind == "wrong_chain" and cid > 0:
                self._quarantine_until[(cid, uk)] = now + self._QUARANTINE_TTL_SEC
                force_save = True
            elif kind == "quota":
                self._demote_until[uk] = now + 1800.0
                self._cool_until[uk] = now + 60.0
                force_save = True
            elif kind == "timeout":
                self._demote_until[uk] = now + 600.0
                self._cool_until[uk] = now + 60.0
                force_save = True
            elif kind == "shrink":
                cur = self._batch_caps.get(uk, _default_batch_cap_for_url(url))
                self._batch_caps[uk] = max(1, cur // 2)
                force_save = True
            elif kind == "gap":
                self._cool_until[uk] = now + 20.0
                force_save = True
        if cid > 0:
            self._persist_endpoint_if_due(url, cid, force=force_save)

    def get_quorum_head_block(self, chain: str, timeout: float = 8.0) -> Tuple[int, int]:
        """
        최소 2개 이상의 독립 호스트 RPC 엔드포인트 병렬 `eth_getBlockByNumber("latest", false)` / `eth_blockNumber` 쿼럼 조회:
        - 호스트(`netloc`) 기준 중복 제거로 동일 사업자 복수 URL의 단일 장애점 위장 방지.
        - 아카이브 노드 지연과 분리해 실제 체인 최신 팁(`b_tip = max`) 및 아카이브 합의 헤드(`b_head`) 산출.
        - 반환 `(b_tip, b_head)`는 이상치(median ± max(2048, median // 500)) 배제 후 교차 검증.
        """
        c = _norm_chain(chain)
        if type(self).call is not RPCRouter.call or "call" in self.__dict__:
            raw_bn = self.call(c, "eth_blockNumber", [], timeout=timeout)
            bn = int(str(raw_bn), 16) if isinstance(raw_bn, str) and str(raw_bn).startswith("0x") else int(raw_bn or 0)
            if bn <= 0:
                raise RuntimeError(f"Invalid blockNumber on {c}: {raw_bn!r}")
            return bn, bn
        cid = CHAIN_IDS.get(c, 0)
        arch_urls = self.candidate_urls(c, need_archive=True)
        live_urls = self.candidate_urls(c, need_archive=False)
        arch_url_set = set(KEYLESS_ARCHIVE_RPCS.get(c, ())) | {u for u in arch_urls if _is_keyed_rpc_url(u)}
        merged_cands = list(dict.fromkeys([*arch_urls, *live_urls]))
        urls: List[str] = []
        seen_providers: Set[str] = set()
        for u in merged_cands:
            prov_k = _rpc_quorum_provider_key(u)
            if prov_k in seen_providers:
                continue
            seen_providers.add(prov_k)
            urls.append(u)
            if len(urls) >= 5:
                break
        if len(urls) < 2 and len(merged_cands) >= 2:
            seen_netlocs = {urllib.parse.urlparse(u).netloc.lower() or u.lower() for u in urls}
            for u in merged_cands:
                nl_k = urllib.parse.urlparse(u).netloc.lower() or u.lower()
                if nl_k in seen_netlocs:
                    continue
                seen_netlocs.add(nl_k)
                urls.append(u)
                if len(urls) >= 2:
                    break
        if not urls:
            raise RuntimeError(f"No RPC endpoints for chain {c}")

        def _probe_one(u: str) -> Tuple[int, int, bool]:
            is_arch = u in arch_url_set
            uk_p = _endpoint_storage_key(u)

            def _extract_probe_blk(blk_obj: Any, t_start: float) -> Optional[Tuple[int, int, bool]]:
                if not isinstance(blk_obj, dict):
                    return None
                num_s = str(blk_obj.get("number") or "")
                ts_s = str(blk_obj.get("timestamp") or "")
                bn_v = int(num_s, 16) if num_s.startswith("0x") else int(num_s or 0)
                ts_v = int(ts_s, 16) if ts_s.startswith("0x") else int(ts_s or 0)
                if bn_v > 0:
                    self._record_success(u, (time.perf_counter() - t_start) * 1000.0, cid=cid)
                    return bn_v, max(0, ts_v), is_arch
                return None

            with self._lock:
                cid_already_ok = (cid <= 0) or ((cid, uk_p) in self._verified_chain_urls)
            if not cid_already_ok:
                # Single-RTT cold probe: batch eth_chainId + eth_getBlockByNumber("latest", false)
                t_b = time.perf_counter()
                try:
                    raw_b = self._pooled_post(
                        u,
                        b'[{"jsonrpc":"2.0","id":1,"method":"eth_chainId","params":[]},'
                        b'{"jsonrpc":"2.0","id":2,"method":"eth_getBlockByNumber","params":["latest",false]}]',
                        timeout=min(5.0, timeout),
                    )
                    dec_b = json.loads(raw_b.decode("utf-8", errors="replace"))
                    if isinstance(dec_b, list):
                        by_id_b = {it.get("id"): it for it in dec_b if isinstance(it, dict)}
                        cid_res = (by_id_b.get(1) or {}).get("result")
                        if isinstance(cid_res, str) and cid_res.startswith("0x"):
                            got_c = int(cid_res, 16)
                            if got_c != cid:
                                self._record_failure(u, "wrong_chain", cid=cid)
                                return 0, 0, is_arch
                            with self._lock:
                                self._verified_chain_urls.add((cid, uk_p))
                            cid_already_ok = True
                            got_b = _extract_probe_blk((by_id_b.get(2) or {}).get("result"), t_b)
                            if got_b is not None:
                                return got_b
                except Exception as _b_exc:
                    if _is_auth_denied_rpc_error(_b_exc):
                        self._record_failure(u, "auth_dead", cid=cid)
                        return 0, 0, is_arch
                    _b_msg = str(_b_exc).lower()
                    if any(tok in _b_msg for tok in ("429", "timed out", "timeout", "refused", "getaddrinfo", "reset")):
                        self._record_failure(u, _classify_rpc_error(_b_exc), cid=cid)
                        return 0, 0, is_arch
            if not cid_already_ok and not self._verify_endpoint_chain_id(u, cid, timeout=min(5.0, timeout)):
                return 0, 0, is_arch
            t0 = time.perf_counter()
            try:
                raw_blk = self._pooled_post(
                    u,
                    b'{"jsonrpc":"2.0","id":1,"method":"eth_getBlockByNumber","params":["latest",false]}',
                    timeout=min(4.0, timeout),
                )
                doc_blk = json.loads(raw_blk.decode("utf-8", errors="replace"))
                got_blk = _extract_probe_blk(doc_blk.get("result") if isinstance(doc_blk, dict) else None, t0)
                if got_blk is not None:
                    return got_blk
            except Exception as _blk_exc:
                _emsg = str(_blk_exc).lower()
                if any(tok in _emsg for tok in ("403", "429", "401", "timed out", "timeout", "refused", "getaddrinfo", "reset")):
                    return 0, 0, is_arch
            t1 = time.perf_counter()
            raw = self._pooled_post(
                u,
                b'{"jsonrpc":"2.0","id":1,"method":"eth_blockNumber","params":[]}',
                timeout=min(4.0, timeout),
            )
            doc = json.loads(raw.decode("utf-8", errors="replace"))
            res = doc.get("result") if isinstance(doc, dict) else None
            if isinstance(res, str) and res.startswith("0x"):
                bn_val = int(res, 16)
                if bn_val > 0:
                    self._record_success(u, (time.perf_counter() - t1) * 1000.0, cid=cid)
                    return bn_val, 0, is_arch
            return 0, 0, is_arch

        samples: List[Tuple[int, int, bool]] = []
        if len(urls) == 1:
            try:
                s0 = _probe_one(urls[0])
                if s0[0] > 0:
                    samples.append(s0)
            except _RECOVERABLE_IO_EXC:
                pass
        else:
            with concurrent.futures.ThreadPoolExecutor(max_workers=len(urls)) as ex:
                futs = [ex.submit(_probe_one, u) for u in urls]
                for fut in futs:
                    try:
                        sv = fut.result(timeout=timeout + 1.0)
                        if sv[0] > 0:
                            samples.append(sv)
                    except _RECOVERABLE_IO_EXC:
                        pass
        if not samples:
            raw_fb = self.call(c, "eth_blockNumber", [], timeout=timeout)
            fb_bn = int(str(raw_fb), 16) if isinstance(raw_fb, str) and str(raw_fb).startswith("0x") else int(raw_fb or 0)
            if fb_bn <= 0 or len(urls) >= 2:
                raise RuntimeError(f"eth_blockNumber quorum failed on {c} (distinct hosts={len(urls)}, samples=0)")
            return fb_bn, fb_bn
        if len(urls) >= 2 and len(samples) < 2:
            raise RuntimeError(f"Insufficient RPC quorum agreement on {c}: only {len(samples)}/{len(urls)} hosts responded")
        med_bn = samples[0][0]
        if len(samples) >= 2:
            sorted_samples = sorted(samples, key=lambda x: x[0])
            med_bn = sorted_samples[(len(sorted_samples) - 1) // 2][0]
            band = max(256, min(2048, med_bn // 100_000))
            filtered = [s for s in samples if abs(s[0] - med_bn) <= band]
            if len(urls) >= 2 and len(filtered) < 2:
                raise RuntimeError(f"Insufficient RPC quorum agreement on {c}: only {len(filtered)}/{len(urls)} hosts within quorum band (median={med_bn}, band={band})")
            if filtered:
                samples = filtered
        tip_win = max(64, int(MAX_AUDIT_BLOCK_LAG) * 4)
        tip_cands = samples
        if len(samples) >= 3:
            corroborated = [
                s
                for s in samples
                if sum(1 for o in samples if abs(o[0] - s[0]) <= int(MAX_AUDIT_BLOCK_LAG) * 2) >= 2
            ]
            if corroborated:
                tip_cands = corroborated
            else:
                tight_med = [s for s in samples if abs(s[0] - med_bn) <= tip_win]
                if tight_med:
                    tip_cands = tight_med
            tip_bn, tip_ts, _ = max(tip_cands, key=lambda x: x[0])
        elif len(samples) == 2:
            s_lo, s_hi = sorted(samples, key=lambda x: x[0])
            if (s_hi[0] - s_lo[0]) > tip_win:
                raise RuntimeError(
                    f"Two-host RPC quorum split on {c}: {s_lo[0]} vs {s_hi[0]} (diff>{tip_win})"
                )
            if (s_hi[0] - s_lo[0]) <= int(MAX_AUDIT_BLOCK_LAG) * 2:
                tip_bn, tip_ts, _ = s_hi
            else:
                # Guard against 1-host ahead spoofing when only 2 hosts responded
                tip_bn, tip_ts, _ = s_lo
        else:
            tip_bn, tip_ts, _ = samples[0]
        fresh: List[int] = []
        arch_fresh: List[int] = []
        for h_bn, h_ts, is_arch in samples:
            lag_blk = tip_bn - h_bn
            is_f = (0 <= lag_blk <= MAX_AUDIT_BLOCK_LAG) or (
                0 <= lag_blk <= tip_win
                and tip_ts > 0
                and h_ts > 0
                and 0 <= (tip_ts - h_ts) <= 12
            )
            if is_f:
                fresh.append(h_bn)
                if is_arch:
                    arch_fresh.append(h_bn)
        b_head = max(arch_fresh) if arch_fresh else (min(fresh) if fresh else tip_bn)
        return tip_bn, b_head

    _UNPINNED_BLOCK_TAGS: FrozenSet[str] = frozenset({"latest", "pending", "safe", "finalized"})
    _NON_DETERMINISTIC_RPC_METHODS: FrozenSet[str] = frozenset(
        {"eth_blockNumber", "eth_gasPrice", "eth_maxPriorityFeePerGas", "eth_feeHistory", "eth_chainId", "net_version"}
    )

    @classmethod
    def _is_cacheable_pinned_rpc(cls, method: str, params: Sequence[Any], block_pin: Optional[int]) -> bool:
        if block_pin is None or int(block_pin) <= 0:
            return False
        if str(method or "") in cls._NON_DETERMINISTIC_RPC_METHODS:
            return False
        for p in params:
            if isinstance(p, str) and p.strip().lower() in cls._UNPINNED_BLOCK_TAGS:
                return False
            if isinstance(p, dict):
                for bk in ("fromBlock", "toBlock", "blockNumber"):
                    bv = p.get(bk)
                    if isinstance(bv, str) and bv.strip().lower() in cls._UNPINNED_BLOCK_TAGS:
                        return False
        return True

    def call(
        self,
        chain: str,
        method: str,
        params: List[Any],
        block_pin: Optional[int] = None,
        need_archive: bool = False,
        timeout: float = 12.0,
    ) -> Any:
        c = _norm_chain(chain)
        cid = CHAIN_IDS.get(c, 0)
        params_sha = ""
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_call_error = None
        can_cache = self.store is not None and self._is_cacheable_pinned_rpc(method, params, block_pin)
        if can_cache and self.store is not None and block_pin is not None:
            params_sha = hashlib.sha256(
                json.dumps(params, sort_keys=True, ensure_ascii=True).encode("utf-8")
            ).hexdigest()
            hit, cached_val = self.store.get_pinned_rpc(cid, int(block_pin), method, params_sha)
            if hit:
                return cached_val
        urls = self.candidate_urls(c, need_archive=need_archive or (block_pin is not None and block_pin > 0))
        payload = json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}).encode("utf-8")
        last_err = "no_candidate_rpc"
        range_limit_hits = 0
        for url in urls:
            if method != "eth_chainId" and not self._verify_endpoint_chain_id(url, cid, timeout=timeout):
                last_err = f"endpoint_unverified on {_redact_secrets_in_text(url)}"
                continue
            t0 = time.perf_counter()
            try:
                raw = self._pooled_post(url, payload, timeout=timeout)
                doc = json.loads(raw.decode("utf-8", errors="replace"))
            except Exception as exc:
                kind = _classify_rpc_error(exc)
                if kind == "range_limit" or (method == "eth_getLogs" and kind == "shrink"):
                    last_err = _redact_secrets_in_text(exc)
                    range_limit_hits += 1
                    if range_limit_hits >= 2:
                        break
                    continue
                self._record_failure(url, kind, cid=cid)
                last_err = _redact_secrets_in_text(exc)
                continue
            if not isinstance(doc, dict):
                self._record_failure(url, "gap", cid=cid)
                continue
            err = doc.get("error")
            if err is not None:
                kind = _classify_rpc_error(err)
                if kind == "revert":
                    if tls is not None:
                        tls.last_call_error = err
                    return None
                if kind == "range_limit" or (method == "eth_getLogs" and kind == "shrink"):
                    last_err = _redact_secrets_in_text(err)
                    range_limit_hits += 1
                    if range_limit_hits >= 2:
                        break
                    continue
                if kind != "shrink":
                    self._record_failure(url, kind, cid=cid)
                last_err = _redact_secrets_in_text(err)
                continue
            res = doc.get("result")
            self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=cid)
            if can_cache and self.store is not None and block_pin is not None and res is not None:
                self.store.put_pinned_rpc(cid, int(block_pin), method, params_sha, res)
            return res
        raise RuntimeError(f"RPC call failed on {c}.{method}: {_redact_secrets_in_text(last_err)}")

    def last_batch_transport_failures(self) -> int:
        tls = getattr(self, "_tls", None)
        return int(getattr(tls, "last_batch_transport_failures", 0) or 0)

    def last_multicall_transport_failed(self) -> bool:
        tls = getattr(self, "_tls", None)
        return bool(getattr(tls, "last_multicall_transport_failed", False))

    def get_last_batch_errors(self) -> Dict[int, Any]:
        tls = getattr(self, "_tls", None)
        errs = getattr(tls, "last_batch_errors", None)
        return dict(errs) if isinstance(errs, dict) else {}

    def _set_tls_batch_failures(
        self,
        failed_indices: Set[int],
        batch_errors: Optional[Dict[int, Any]] = None,
    ) -> None:
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_batch_transport_failures = len(failed_indices)
            tls.last_batch_failed_indices = frozenset(failed_indices)
            tls.last_batch_errors = dict(batch_errors) if batch_errors else {}

    def batch_call(
        self,
        chain: str,
        calls: Sequence[Tuple[str, List[Any]]],
        block_pin: Optional[int] = None,
        need_archive: bool = False,
        timeout: float = 15.0,
        raise_on_all_failed: bool = False,
    ) -> List[Any]:
        if not calls:
            self._set_tls_batch_failures(set())
            return []
        c = _norm_chain(chain)
        cid = CHAIN_IDS.get(c, 0)
        results: List[Any] = [None] * len(calls)
        missing_indices: List[int] = []
        param_hashes: Dict[int, str] = {}
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_call_error = None
        if self.store is not None and block_pin is not None and block_pin > 0:
            lookup_keys: List[Tuple[str, str]] = []
            cacheable_idxs: Set[int] = set()
            for idx, (m, p) in enumerate(calls):
                if self._is_cacheable_pinned_rpc(m, p, block_pin):
                    psha = hashlib.sha256(
                        json.dumps(p, sort_keys=True, ensure_ascii=True).encode("utf-8")
                    ).hexdigest()
                    param_hashes[idx] = psha
                    lookup_keys.append((m, psha))
                    cacheable_idxs.add(idx)
            cached_map = self.store.get_pinned_rpc_batch(cid, int(block_pin), lookup_keys) if lookup_keys else {}
            for idx, (m, _) in enumerate(calls):
                if idx in cacheable_idxs:
                    k = (m, param_hashes[idx])
                    if k in cached_map:
                        results[idx] = cached_map[k]
                        continue
                missing_indices.append(idx)
        else:
            missing_indices = list(range(len(calls)))
        if not missing_indices:
            self._set_tls_batch_failures(set())
            return results
        failed_indices: Set[int] = set()
        batch_errors: Dict[int, Any] = {}

        def _capture_null_tls_err(idx_err: int) -> None:
            if results[idx_err] is None:
                l_err_c = getattr(getattr(self, "_tls", None), "last_call_error", None)
                if l_err_c is not None:
                    batch_errors[idx_err] = l_err_c

        if type(self).call is not RPCRouter.call or "call" in self.__dict__:
            ok_any = False
            last_exc: Optional[Exception] = None
            for idx in missing_indices:
                m_i, p_i = calls[idx]
                try:
                    results[idx] = self.call(c, m_i, p_i, block_pin=block_pin, need_archive=need_archive, timeout=timeout)
                    ok_any = True
                    _capture_null_tls_err(idx)
                except Exception as exc:
                    last_exc = exc
                    results[idx] = None
                    batch_errors[idx] = exc
                    if _classify_rpc_error(exc) != "revert":
                        failed_indices.add(idx)
            self._set_tls_batch_failures(failed_indices, batch_errors)
            if raise_on_all_failed and not ok_any and last_exc is not None:
                raise RuntimeError(f"All RPC calls failed on {c}: {last_exc}") from last_exc
            return results
        urls = self.candidate_urls(c, need_archive=need_archive or (block_pin is not None and block_pin > 0))
        if len(missing_indices) >= 4 and len(urls) > 1 and _is_live_real_router(self):
            urls = sorted(
                urls,
                key=lambda u: 0 if self.batch_cap_for(u) >= 20 else (1 if self.batch_cap_for(u) >= 8 else 2),
            )
        if not urls:
            failed_indices.update(missing_indices)
            self._set_tls_batch_failures(failed_indices, batch_errors)
            if raise_on_all_failed:
                raise RuntimeError(f"No candidate RPC URLs for {c}")
            return results
        pending: List[int] = list(missing_indices)
        url_idx = 0
        ok_rpc_count = 0
        last_transport_err = "batch_call_exhausted"
        while pending:
            url = urls[url_idx % len(urls)]
            if not self._verify_endpoint_chain_id(url, cid, timeout=timeout):
                url_idx += 1
                if url_idx >= len(urls) * 2:
                    failed_indices.update(pending)
                    break
                continue
            cap = max(1, self.batch_cap_for(url))
            chunk_idxs = pending[:cap]

            def _run_single_fallback(idx_s: int) -> None:
                nonlocal ok_rpc_count, last_transport_err
                m_s, p_s = calls[idx_s]
                try:
                    results[idx_s] = self.call(c, m_s, p_s, block_pin=block_pin, need_archive=need_archive, timeout=timeout)
                    ok_rpc_count += 1
                    _capture_null_tls_err(idx_s)
                except Exception as exc_s:
                    last_transport_err = str(exc_s)
                    results[idx_s] = None
                    batch_errors[idx_s] = exc_s
                    if _classify_rpc_error(exc_s) != "revert":
                        failed_indices.add(idx_s)

            if cap == 1:
                _run_single_fallback(chunk_idxs[0])
                del pending[:1]
                # RPC 극대화: 고정 대기 제거(Quota 스로틀은 _record_failure의 demote/cool 백오프로만 처리)
                continue
            req_list = [
                {"jsonrpc": "2.0", "id": k, "method": calls[i][0], "params": calls[i][1]}
                for k, i in enumerate(chunk_idxs)
            ]
            t0 = time.perf_counter()
            cur_unresolved = list(chunk_idxs)
            try:
                raw = self._pooled_post(url, json.dumps(req_list).encode("utf-8"), timeout=timeout)
                decoded = json.loads(raw.decode("utf-8", errors="replace"))
                if not isinstance(decoded, list):
                    raise RuntimeError("Batch response not a JSON list")
                by_id: Dict[int, Dict[str, Any]] = {}
                first_unmatched_err: Optional[Any] = None
                for item in decoded:
                    if not isinstance(item, dict):
                        continue
                    raw_id = item.get("id")
                    if isinstance(raw_id, bool) or raw_id is None:
                        if first_unmatched_err is None and "error" in item:
                            first_unmatched_err = item.get("error")
                        continue
                    try:
                        item_id = int(raw_id)
                    except (TypeError, ValueError):
                        if first_unmatched_err is None and "error" in item:
                            first_unmatched_err = item.get("error")
                        continue
                    if item_id >= 0:
                        by_id[item_id] = item
                non_revert_err: Optional[Any] = None
                unresolved_in_chunk: List[int] = []
                to_cache_batch: List[Tuple[str, str, Any]] = []
                for k, orig_i in enumerate(chunk_idxs):
                    item = by_id.get(k)
                    if item is None:
                        if non_revert_err is None:
                            non_revert_err = first_unmatched_err if first_unmatched_err is not None else "missing_batch_item"
                        unresolved_in_chunk.append(orig_i)
                    elif item.get("error") is not None:
                        kind = _classify_rpc_error(item.get("error"))
                        if kind != "revert":
                            if non_revert_err is None:
                                non_revert_err = item.get("error")
                            unresolved_in_chunk.append(orig_i)
                        else:
                            results[orig_i] = None
                            batch_errors[orig_i] = item.get("error")
                    else:
                        val = item.get("result")
                        results[orig_i] = val
                        if (
                            self.store is not None
                            and block_pin is not None
                            and block_pin > 0
                            and val is not None
                            and orig_i in param_hashes
                        ):
                            to_cache_batch.append((calls[orig_i][0], param_hashes[orig_i], val))
                if to_cache_batch and self.store is not None and block_pin is not None and block_pin > 0:
                    self.store.put_pinned_rpc_batch(cid, int(block_pin), to_cache_batch)
                cur_unresolved = unresolved_in_chunk
                if non_revert_err is not None:
                    ok_rpc_count += len(chunk_idxs) - len(unresolved_in_chunk)
                    raise RuntimeError(_redact_secrets_in_text(non_revert_err))
                self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=cid)
                if len(chunk_idxs) >= cap and cap > 1:
                    def_cap_ok = _default_batch_cap_for_url(url)
                    if cap < def_cap_ok:
                        uk_b = _endpoint_storage_key(url)
                        with self._lock:
                            cur_c = self._batch_caps.get(uk_b, cap)
                            if cur_c < def_cap_ok:
                                self._batch_caps[uk_b] = min(def_cap_ok, max(cur_c + 4, int(cur_c * 1.5)))
                ok_rpc_count += len(chunk_idxs)
                del pending[:len(chunk_idxs)]
                # RPC 극대화: 고정 대기 제거(Quota 스로틀은 _record_failure의 demote/cool 백오프로만 처리)
            except Exception as exc:
                last_transport_err = _redact_secrets_in_text(exc)
                kind = _classify_rpc_error(exc)
                self._record_failure(url, kind, cid=cid)
                if len(cur_unresolved) < len(chunk_idxs):
                    pending = cur_unresolved + pending[len(chunk_idxs):]
                url_idx += 1
                if url_idx >= len(urls) * 2:
                    for orig_i in cur_unresolved:
                        _run_single_fallback(orig_i)
                    del pending[:len(cur_unresolved)]
        self._set_tls_batch_failures(failed_indices, batch_errors)
        if raise_on_all_failed and ok_rpc_count == 0:
            raise RuntimeError(f"All batch RPC calls failed on {c}: {_redact_secrets_in_text(last_transport_err)}")
        return results

    def _batch_eth_call_fallback(self, c: str, sub_calls: Sequence[Tuple[str, bytes]], btag: str, block_pin: int) -> List[Tuple[bool, bytes]]:
        rpc_batch = [
            ("eth_call", [{"to": _checksum(target), "data": "0x" + bytes(cdata).hex()}, btag])
            for target, cdata in sub_calls
        ]
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_fallback_transport_failed = False
        try:
            raw_res = self.batch_call(c, rpc_batch, block_pin=block_pin, need_archive=True)
        except Exception:
            if tls is not None:
                tls.last_fallback_transport_failed = True
            return [(False, b"") for _ in sub_calls]
        if tls is not None:
            if self.last_batch_transport_failures() > 0 or len(raw_res) < len(sub_calls):
                tls.last_fallback_transport_failed = True
        fb_out: List[Tuple[bool, bytes]] = []
        for r in raw_res:
            if isinstance(r, str) and r.startswith("0x") and len(r) >= 2:
                try:
                    fb_out.append((True, _hex_to_bytes(r)))
                    continue
                except _PARSE_DATA_EXC:
                    pass
            fb_out.append((False, b""))
        return fb_out

    def multicall3(
        self,
        chain: str,
        calls: Sequence[Tuple[str, bytes]],
        block_pin: int,
        chunk_size: int = 256,
    ) -> List[Tuple[bool, bytes]]:
        """Multicall3.aggregate3 패스 호출 (대용량 청크 병렬 실행 + 실패 청크 1회 이분할 + 불량 노드 폴백)."""
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_multicall_transport_failed = False
        if not calls:
            return []
        c = _norm_chain(chain)
        btag = hex(int(block_pin)) if block_pin > 0 else "latest"
        can_cache_mc3 = (
            int(block_pin or 0) > 0
            and type(self).call is RPCRouter.call
            and "call" not in self.__dict__
            and _is_live_real_router(self)
        )
        mc3_key: Optional[Tuple[str, int, bytes]] = None
        if can_cache_mc3:
            h_mc = hashlib.sha256()
            for t_c, cd_c in calls:
                h_mc.update(_norm_addr(t_c).encode("ascii", errors="ignore"))
                h_mc.update(b":")
                h_mc.update(bytes(cd_c))
                h_mc.update(b"|")
            mc3_key = (c, int(block_pin), h_mc.digest())
            with self._lock:
                cached_mc = self._mc3_cache.get(mc3_key)
            if cached_mc is not None and len(cached_mc) == len(calls):
                return list(cached_mc)
        def _cache_mc3_if_ok(res_vals: List[Tuple[bool, bytes]], failed_flag: bool) -> None:
            if mc3_key is not None and not failed_flag and len(res_vals) == len(calls):
                with self._lock:
                    if len(self._mc3_cache) >= 2048:
                        self._mc3_cache.clear()
                    self._mc3_cache[mc3_key] = list(res_vals)

        with self._lock:
            no_mc_chain = c in self._no_multicall_chains
        if no_mc_chain:
            fb_res = self._batch_eth_call_fallback(c, calls, btag, block_pin)
            fb_failed = bool(getattr(tls, "last_fallback_transport_failed", False)) if tls is not None else False
            if tls is not None:
                tls.last_multicall_transport_failed = fb_failed
            _cache_mc3_if_ok(fb_res, fb_failed)
            return fb_res

        def _fallback_sub(sub_calls: Sequence[Tuple[str, bytes]]) -> Tuple[List[Tuple[bool, bytes]], bool]:
            res_fb = self._batch_eth_call_fallback(c, sub_calls, btag, block_pin)
            t_loc = getattr(self, "_tls", None)
            return res_fb, bool(t_loc is not None and getattr(t_loc, "last_fallback_transport_failed", False))

        def _run_mc3_sub(sub: Sequence[Tuple[str, bytes]], allow_bisect: bool = True) -> Tuple[List[Tuple[bool, bytes]], bool]:
            with self._lock:
                no_mc_sub = c in self._no_multicall_chains
            if no_mc_sub:
                return _fallback_sub(sub)
            tuples = [(_checksum(target), True, bytes(cdata)) for target, cdata in sub]
            calldata_hex = encode_calldata(AGG3_SEL, ["(address,bool,bytes)[]"], [tuples])
            try:
                raw_hex = self.call(
                    c,
                    "eth_call",
                    [{"to": MULTICALL3_ADDR, "data": calldata_hex}, btag],
                    block_pin=block_pin,
                    need_archive=True,
                )
            except Exception:
                raw_hex = None
            if not raw_hex or str(raw_hex) in ("0x", "0X"):
                if allow_bisect and len(sub) > 64:
                    mid_s = len(sub) // 2
                    l_res, l_fail = _run_mc3_sub(sub[:mid_s], allow_bisect=False)
                    r_res, r_fail = _run_mc3_sub(sub[mid_s:], allow_bisect=False)
                    return l_res + r_res, (l_fail or r_fail)
                mc_absent_at_pin = False
                try:
                    mc_code = self.call(c, "eth_getCode", [MULTICALL3_ADDR, btag], block_pin=block_pin)
                    mc_absent_at_pin = isinstance(mc_code, str) and mc_code.lower() in ("0x", "")
                except Exception:
                    mc_absent_at_pin = False
                if mc_absent_at_pin:
                    if int(block_pin or 0) <= 0:
                        with self._lock:
                            self._no_multicall_chains.add(c)
                    else:
                        mc_absent_latest = False
                        try:
                            mc_latest = self.call(c, "eth_getCode", [MULTICALL3_ADDR, "latest"], block_pin=None)
                            mc_absent_latest = isinstance(mc_latest, str) and mc_latest.lower() in ("0x", "")
                        except Exception:
                            mc_absent_latest = False
                        if mc_absent_latest:
                            with self._lock:
                                self._no_multicall_chains.add(c)
                return _fallback_sub(sub)
            try:
                decoded = abi_decode(["(bool,bytes)[]"], raw_hex)[0]
                if len(decoded) != len(sub):
                    return _fallback_sub(sub)
                return [(bool(ok_flag), bytes(ret_bytes)) for ok_flag, ret_bytes in decoded], False
            except Exception:
                return _fallback_sub(sub)

        chunks = [calls[i : i + chunk_size] for i in range(0, len(calls), chunk_size)]
        out: List[Tuple[bool, bytes]] = []
        any_transport_failed = False
        batch_parts = _map_chunks_live(self, _run_mc3_sub, chunks, max_workers=16)
        for sub_out, sub_fail in batch_parts:
            out.extend(sub_out)
            if sub_fail:
                any_transport_failed = True
        if tls is not None:
            tls.last_multicall_transport_failed = any_transport_failed
        _cache_mc3_if_ok(out, any_transport_failed)
        return out


