def _to_bp(val: Union[int, Decimal, str]) -> int:
    if isinstance(val, int) and not isinstance(val, bool):
        return max(0, min(10000, val * 10000))
    return max(0, min(10000, int((_to_dec(val) * Decimal("10000")).to_integral_value(rounding=ROUND_HALF_EVEN))))


def _bp_to_dec(bp: int) -> Decimal:
    return (Decimal(max(0, min(10000, int(bp)))) / Decimal("10000")).quantize(Decimal("0.0001"))

def _sql_quote_str(val: str) -> str:
    return "'" + str(val).replace("'", "''") + "'"


_SOURCIFY_META_LOCK = threading.Lock()
