_SORTED_EVM_EXPLORER_DOMAINS: Tuple[Tuple[str, str], ...] = tuple(
    sorted(_EVM_EXPLORER_DOMAIN_MAP.items(), key=lambda kv: -len(kv[0]))
)


def _extract_evm_explorer_chains(raw_text: str) -> List[str]:
    rem = raw_text.lower()
    matched: List[str] = []
    for dom, ch_slug in _SORTED_EVM_EXPLORER_DOMAINS:
        if dom in rem:
            rem = rem.replace(dom, " ")
            if _usable_chain(ch_slug):
                matched.append(ch_slug)
    return list(dict.fromkeys(matched))


def _extract_pure_non_evm_chains(raw_text: str) -> List[str]:
    low = raw_text.lower()
    out = list(
        dict.fromkeys(
            kw for pat, kw in _PURE_NON_EVM_PATTERNS if pat.search(low) and not _usable_chain(_norm_chain(kw))
        )
    )
    return out or ["non_evm"]


_CORPUS_PARTITION_CACHE_LOCK = threading.Lock()
_CORPUS_PARTITION_CACHE: Dict[Tuple[str, int, int], Dict[str, Any]] = {}


def _parse_corpus_md_partition(md_path: Optional[Path] = None) -> Dict[str, Any]:
    """
    `컨트랙트.md` 전 구간 무누락 파티션 파서 (`total_headers == len(evm_cases) + len(pure_non_evm_cases)`):
    - 복합 날짜 태그(`07/01 & 07/13`, `01/10~12`, `01/10-12` 등) 및 유니코드 대시 구분자 전수 매칭.
    - 제목의 모든 소괄호·대괄호 그룹 및 본문 탐색기 도메인을 스캔하여 EVM 체인(`Hedera EVM`, `Core Network`, `zkLink Nova` 등)을 정확히 추출.
    - 대상 프로토콜의 보조 컨트랙트(helper)는 시드로 보존하고, 문맥상 외부 비대상 행위자·모조 토큰 라벨만 시드에서 제외하되 `related_map`에 보존.
    - 온체인 `0x` 시드 주소가 본문에 미기재된 EVM 사례도 절대 버리지 않고 `seed_addresses={}`인 `evm_cases`로 보존하여
      Mode B 큐에 등록 및 0-시드 주소 탐색 위임(`0시드 무검사 통과 금지`)을 수행한다.
    """
    eff_md = INCIDENT_CORPUS_PATH if md_path is None else md_path
    if not eff_md.is_file():
        return {"total_headers": 0, "evm_cases": [], "pure_non_evm_cases": [], "corpus_sha256": ""}
    try:
        st_md = eff_md.stat()
        cache_k = (str(eff_md.resolve()), int(st_md.st_size), int(st_md.st_mtime_ns))
    except OSError:
        cache_k = None
    if cache_k is not None:
        with _CORPUS_PARTITION_CACHE_LOCK:
            hit_c = _CORPUS_PARTITION_CACHE.get(cache_k)
            if hit_c is not None:
                return {
                    "total_headers": hit_c["total_headers"],
                    "evm_cases": list(hit_c["evm_cases"]),
                    "pure_non_evm_cases": list(hit_c["pure_non_evm_cases"]),
                    "corpus_sha256": hit_c["corpus_sha256"],
                }
    text = eff_md.read_text(encoding="utf-8", errors="replace")
    matches = list(_CORPUS_HEADER_RE.finditer(text))
    evm_cases: List[HistoricalCaseSeed] = []
    pure_non_evm_cases: List[HistoricalCaseSeed] = []
    used_slugs: Set[str] = set()

    for idx, m in enumerate(matches):
        date_tag = m.group(1).strip()
        raw_title = m.group(2).strip()
        start_pos = m.end()
        end_pos = matches[idx + 1].start() if (idx + 1) < len(matches) else len(text)
        body = text[start_pos:end_pos]

        chains_found: List[str] = []
        seen_chains: Set[str] = set()
        non_evm_in_parens = False
        all_parens, _ = _extract_balanced_parens(raw_title)
        all_brackets = _BRACKET_GROUP_RE.findall(raw_title)
        for p_txt in [*all_parens, *all_brackets]:
            for resolved_c in _resolve_corpus_chains_from_text(p_txt):
                _append_unique(chains_found, seen_chains, resolved_c)
            for part in _CHAIN_LIST_SPLIT_RE.split(p_txt):
                cand = part.strip().lower()
                if cand and not cand.isdigit():
                    cand_norm = _norm_chain(cand)
                    nc = _CORPUS_CHAIN_MAP.get(cand) or (cand_norm if cand_norm in CHAIN_IDS or cand in CHAIN_ALIASES else "")
                    if nc and _usable_chain(nc):
                        _append_unique(chains_found, seen_chains, nc)
            if _has_pure_non_evm_kw(p_txt):
                non_evm_in_parens = True
        if not chains_found:
            body_exp_chains = _extract_evm_explorer_chains(body)
            if body_exp_chains:
                chains_found.extend(body_exp_chains)

        prin_m = _CORPUS_PRINCIPLE_RE.search(body)
        principle = _WS_COLLAPSE_RE.sub(" ", prin_m.group(1).strip()) if prin_m else ""
        sec_m = _CORPUS_TARGET_SEC_RE.search(body)
        target_sec = sec_m.group(1) if sec_m else body
        idents = sorted(set(_CORPUS_BACKTICK_IDENT_RE.findall(body)))

        seed_map: Dict[str, List[str]] = {}
        seed_seen: Dict[str, Set[str]] = {}
        related_map: Dict[str, List[str]] = {}
        related_seen: Dict[str, Set[str]] = {}

        def _map_add(dst: Dict[str, List[str]], dst_seen: Dict[str, Set[str]], ch_k: str, addr_v: str) -> None:
            if addr_v:
                _append_unique(dst.setdefault(ch_k, []), dst_seen.setdefault(ch_k, set()), addr_v)

        eff_default_chains = list(chains_found) if chains_found else ["ethereum"]

        def _record_related_addrs_from_text(src_txt: str, target_chains: Sequence[str]) -> None:
            for ea in _ANY_ADDR_RE.findall(src_txt):
                if _is_non_precompile_addr(ea):
                    na_r = _norm_addr(ea)
                    for ec in target_chains:
                        _map_add(related_map, related_seen, ec, na_r)

        for raw_line in target_sec.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            label_prefix = _LABEL_PREFIX_SPLIT_RE.split(line, maxsplit=1)[0].lower()
            line_exp_chains = _extract_evm_explorer_chains(line)
            if _is_contextual_external_actor_label(label_prefix):
                excl_chains = line_exp_chains or _resolve_corpus_chains_from_text(line) or eff_default_chains
                _record_related_addrs_from_text(line, excl_chains)
                continue
            paren_groups, outside_paren = _extract_balanced_parens(line)
            paren_chains: List[str] = []
            seen_paren: Set[str] = set()
            paren_has_excluded_actor_only = False
            secondary_addrs: List[str] = []
            for sub_p in paren_groups:
                sub_addrs = [
                    _norm_addr(a)
                    for a in _ANY_ADDR_RE.findall(sub_p)
                    if _is_non_precompile_addr(a)
                ]
                cand_p_chains: List[str] = []
                seen_cand_p: Set[str] = set()
                if "," in sub_p:
                    comma_segs = [s.strip() for s in sub_p.split(",") if s.strip()]
                    tail_chains = _resolve_corpus_chains_from_text(comma_segs[-1]) if comma_segs else []
                    if tail_chains:
                        for prev_seg in comma_segs[:-1]:
                            if _is_pure_chain_segment(prev_seg):
                                for pc in _resolve_corpus_chains_from_text(prev_seg):
                                    _append_unique(cand_p_chains, seen_cand_p, pc)
                        for pc in tail_chains:
                            _append_unique(cand_p_chains, seen_cand_p, pc)
                if not cand_p_chains:
                    cand_p_chains = _resolve_corpus_chains_from_text(sub_p)
                for pc in cand_p_chains:
                    _append_unique(paren_chains, seen_paren, pc)
                if _is_contextual_external_actor_label(sub_p):
                    if not sub_addrs:
                        paren_has_excluded_actor_only = True
                    else:
                        eff_sub_chains = cand_p_chains or line_exp_chains or eff_default_chains
                        for ea in sub_addrs:
                            for ec in eff_sub_chains:
                                _map_add(related_map, related_seen, ec, ea)
                    continue
                secondary_addrs.extend(sub_addrs)
            if paren_has_excluded_actor_only:
                eff_out_chains = paren_chains or line_exp_chains or eff_default_chains
                _record_related_addrs_from_text(outside_paren, eff_out_chains)
                continue
            line_chains = (
                line_exp_chains
                or paren_chains
                or _resolve_corpus_chains_from_label(label_prefix)
                or eff_default_chains
            )
            primary_addrs = [a for a in _ANY_ADDR_RE.findall(outside_paren) if _is_non_precompile_addr(a)]
            if not primary_addrs and secondary_addrs:
                primary_addrs = list(secondary_addrs)
                secondary_addrs = []
            for tc in line_chains:
                for pa in primary_addrs:
                    _map_add(seed_map, seed_seen, tc, _norm_addr(pa))
                for sa in secondary_addrs:
                    na = _norm_addr(sa)
                    _map_add(related_map, related_seen, tc, na)
                    _map_add(seed_map, seed_seen, tc, na)

        seed_map = {k: v for k, v in seed_map.items() if v}
        any_body_evm_addr = any(
            _is_non_precompile_addr(a)
            for a in _ANY_ADDR_RE.findall(body)
        )
        is_pure_non_evm = bool(
            not seed_map
            and not chains_found
            and not any_body_evm_addr
            and non_evm_in_parens
        )

        date_compact = _NON_DIGIT_RE.sub("", date_tag)[:8] or f"{idx:03d}"
        base_slug = _norm_slug(f"case-{date_compact}-{raw_title}")
        slug = base_slug
        if slug in used_slugs:
            slug = _norm_slug(f"{base_slug[:54]}-{idx}")
        used_slugs.add(slug)

        if is_pure_non_evm:
            final_chains = _extract_pure_non_evm_chains(f"{raw_title} {target_sec}")
            tx_hashes: List[str] = []
            block_numbers: List[int] = []
        else:
            final_chains = list(seed_map.keys()) if seed_map else (list(chains_found) if chains_found else ["ethereum"])
            tx_hashes = list(dict.fromkeys(h.lower() for h in _ANY_TX_HASH_RE.findall(body)))
            block_numbers = list(
                dict.fromkeys(int(b.replace(",", "")) for b in _ANY_BLOCK_CLUE_RE.findall(body))
            )
        case_obj = HistoricalCaseSeed(
            slug=slug,
            title=f"{date_tag} — {raw_title}",
            date_tag=date_tag,
            chains=final_chains,
            principle_summary=principle[:600],
            key_identifiers=idents,
            seed_addresses=seed_map,
            related_seeds=related_map,
            tx_hashes=tx_hashes,
            block_numbers=block_numbers,
            is_pure_non_evm=is_pure_non_evm,
        )
        if is_pure_non_evm:
            pure_non_evm_cases.append(case_obj)
        else:
            evm_cases.append(case_obj)

    res_part = {
        "total_headers": len(matches),
        "evm_cases": evm_cases,
        "pure_non_evm_cases": pure_non_evm_cases,
        "corpus_sha256": _sha256_file(eff_md),
    }
    if cache_k is not None:
        with _CORPUS_PARTITION_CACHE_LOCK:
            if len(_CORPUS_PARTITION_CACHE) >= 8:
                _CORPUS_PARTITION_CACHE.clear()
            _CORPUS_PARTITION_CACHE[cache_k] = {
                "total_headers": res_part["total_headers"],
                "evm_cases": list(evm_cases),
                "pure_non_evm_cases": list(pure_non_evm_cases),
                "corpus_sha256": res_part["corpus_sha256"],
            }
    return res_part


def _mark_rpc_incomplete_flag(
    flag_out: Optional[List[bool]],
    lock: Optional[threading.Lock] = None,
) -> None:
    if flag_out is None:
        return
    if lock is not None:
        with lock:
            if flag_out:
                flag_out[0] = True
            else:
                flag_out.append(True)
    elif flag_out:
        flag_out[0] = True
    else:
        flag_out.append(True)


def _harvest_logs_bisect(
    router: RPCRouter,
    chain: str,
    seeds: Sequence[str],
    from_block: int,
    to_block: int,
    max_depth: int = 5,
    *,
    rpc_incomplete_out: Optional[List[bool]] = None,
    _err_lock: Optional[threading.Lock] = None,
) -> Set[str]:
    if not seeds or from_block > to_block or max_depth < 0:
        return set()
    addr_list = [_checksum(a) for a in list(seeds)[:16] if _norm_addr(a)]
    if not addr_list:
        return set()
    c_lb = _norm_chain(chain)
    is_real_lb = _is_live_real_router(router)
    span_cur = int(to_block) - int(from_block)
    if is_real_lb and max_depth >= 1 and span_cur > 0:
        sp_map = getattr(router, "_live_log_max_span_by_chain", None)
        known_sp = int(sp_map.get(c_lb, 0) or 0) if isinstance(sp_map, dict) else 0
        if known_sp > 0 and span_cur > known_sp:
            # Partition directly into <=4 bounded parallel subranges matching the learned chain span (0 wasted failing probes)
            n_parts = min(4, max(2, (span_cur + known_sp) // known_sp))
            step_p = (span_cur + n_parts) // n_parts
            sub_ranges: List[Tuple[int, int]] = []
            cur_f = int(from_block)
            while cur_f <= int(to_block):
                cur_t = min(int(to_block), cur_f + step_p - 1)
                sub_ranges.append((cur_f, cur_t))
                cur_f = cur_t + 1
            err_lk_p = _err_lock or threading.Lock()
            with concurrent.futures.ThreadPoolExecutor(max_workers=len(sub_ranges)) as ex_sp:
                futs_sp = [
                    ex_sp.submit(
                        _harvest_logs_bisect,
                        router, chain, seeds, sf_b, st_b, max(0, max_depth - 1),
                        rpc_incomplete_out=rpc_incomplete_out, _err_lock=err_lk_p,
                    )
                    for sf_b, st_b in sub_ranges
                ]
                out_sp: Set[str] = set()
                for f_sp in futs_sp:
                    out_sp |= f_sp.result()
                return out_sp
    try:
        logs = router.call(
            chain,
            "eth_getLogs",
            [{
                "fromBlock": hex(from_block),
                "toBlock": hex(to_block),
                "address": addr_list,
            }],
            block_pin=(int(to_block) if int(to_block) > 0 else None),
            timeout=10.0,
        )
        out: Set[str] = set()
        xfer_by_emitter: Dict[str, Set[str]] = {}
        _xfer_topics = {TRANSFER_TOPIC0.lower(), APPROVAL_TOPIC0.lower()}
        for lg in logs if isinstance(logs, list) else []:
            if not isinstance(lg, dict):
                continue
            lg_topics = lg.get("topics") or []
            t0_low = str(lg_topics[0]).lower() if lg_topics else ""
            is_xfer_ev = t0_low in _xfer_topics
            em_addr = _norm_addr(str(lg.get("address") or ""))
            for t in lg_topics[1:] if is_xfer_ev else lg_topics:
                if isinstance(t, str) and len(t) == 66 and t[:26] == "0x000000000000000000000000":
                    cand = _norm_addr("0x" + t[26:])
                    if _is_non_precompile_addr(cand):
                        if is_xfer_ev and em_addr:
                            xfer_by_emitter.setdefault(em_addr, set()).add(cand)
                        else:
                            out.add(cand)
        for _em_a, _cset in xfer_by_emitter.items():
            # Widely-traded ERC-20s emitting Transfer/Approval to >12 distinct counterparties pollute unrelated clusters;
            # small/protocol-specific tokens (<=12 counterparties) keep 100% of Transfer counterparties.
            if len(_cset) <= 12:
                out.update(_cset)
        return out
    except Exception as exc_lb:
        if is_real_lb and span_cur >= 2000 and _classify_rpc_error(exc_lb) == "range_limit":
            sp_map_e = getattr(router, "_live_log_max_span_by_chain", None)
            if isinstance(sp_map_e, dict):
                half_sp = max(1000, span_cur // 2)
                with router._lock:
                    prev_sp = int(sp_map_e.get(c_lb, 0) or 0)
                    if prev_sp <= 0 or half_sp < prev_sp:
                        sp_map_e[c_lb] = half_sp
        if from_block >= to_block or max_depth == 0:
            _mark_rpc_incomplete_flag(rpc_incomplete_out, _err_lock)
            return set()
        mid = (from_block + to_block) // 2
        err_lk = _err_lock or threading.Lock()
        if max_depth >= 1 and is_real_lb:
            with concurrent.futures.ThreadPoolExecutor(max_workers=2) as ex_lb:
                fut_l = ex_lb.submit(
                    _harvest_logs_bisect,
                    router,
                    chain,
                    seeds,
                    from_block,
                    mid,
                    max_depth - 1,
                    rpc_incomplete_out=rpc_incomplete_out,
                    _err_lock=err_lk,
                )
                fut_r = ex_lb.submit(
                    _harvest_logs_bisect,
                    router,
                    chain,
                    seeds,
                    mid + 1,
                    to_block,
                    max_depth - 1,
                    rpc_incomplete_out=rpc_incomplete_out,
                    _err_lock=err_lk,
                )
                return fut_l.result() | fut_r.result()
        left = _harvest_logs_bisect(
            router, chain, seeds, from_block, mid, max_depth - 1, rpc_incomplete_out=rpc_incomplete_out, _err_lock=err_lk
        )
        right = _harvest_logs_bisect(
            router, chain, seeds, mid + 1, to_block, max_depth - 1, rpc_incomplete_out=rpc_incomplete_out, _err_lock=err_lk
        )
        return left | right


def _harvest_token_logs_bisect(
    router: RPCRouter,
    chain: str,
    holders: Sequence[str],
    from_block: int,
    to_block: int,
    max_depth: int = 3,
    out_spenders: Optional[Set[str]] = None,
    *,
    out_approval_triples: Optional[Set[Tuple[str, str, str]]] = None,
    rpc_incomplete_out: Optional[List[bool]] = None,
    _filter_indices: Tuple[int, ...] = (0, 1, 2),
    _spenders_lock: Optional[threading.Lock] = None,
) -> Tuple[Set[str], Set[str]]:
    """Transfer/Approval 이벤트로부터 프로토콜 금고가 보유하거나 승인받은/부여한 커스텀 ERC-20 및 오너·스펜더 주소 수집."""
    tokens: Set[str] = set()
    owners: Set[str] = set()
    if not holders or from_block > to_block or max_depth < 0 or not _filter_indices:
        return tokens, owners
    holder_set = {nh for h in list(holders)[:12] if (nh := _norm_addr(h))}
    padded = ["0x" + ("0" * 24) + nh[2:] for h in list(holders)[:12] if (nh := _norm_addr(h))]
    if not padded:
        return tokens, owners
    all_filters: Tuple[List[Any], ...] = (
        [[TRANSFER_TOPIC0, APPROVAL_TOPIC0], None, padded],
        [TRANSFER_TOPIC0, padded],
        [APPROVAL_TOPIC0, padded],
    )
    sp_lock = _spenders_lock or threading.Lock()
    is_live = _is_live_real_router(router)

    def _run_filter(f_idx: int) -> Tuple[int, bool, Set[str], Set[str], Set[str], Set[Tuple[str, str, str]]]:
        f_toks: Set[str] = set()
        f_owns: Set[str] = set()
        f_sps: Set[str] = set()
        f_trips: Set[Tuple[str, str, str]] = set()
        try:
            logs = router.call(
                chain,
                "eth_getLogs",
                [{
                    "fromBlock": hex(from_block),
                    "toBlock": hex(to_block),
                    "topics": all_filters[f_idx],
                }],
                block_pin=(int(to_block) if int(to_block) > 0 else None),
                timeout=8.0,
            )
            for lg in logs if isinstance(logs, list) else []:
                if not isinstance(lg, dict):
                    continue
                em = _norm_addr(lg.get("address"))
                if _is_non_precompile_addr(em):
                    f_toks.add(em)
                t_list = lg.get("topics") or []
                if len(t_list) >= 3 and str(t_list[0]).lower() == APPROVAL_TOPIC0.lower():
                    t1 = str(t_list[1] or "")
                    t2 = str(t_list[2] or "")
                    ow = _norm_addr("0x" + t1[26:]) if len(t1) == 66 else ""
                    sp = _norm_addr("0x" + t2[26:]) if len(t2) == 66 else ""
                    if _is_non_precompile_addr(ow):
                        f_owns.add(ow)
                        if out_approval_triples is not None and _is_non_precompile_addr(sp) and _is_non_precompile_addr(em):
                            f_trips.add((ow, sp, em))
                    if out_spenders is not None and _is_non_precompile_addr(sp) and sp not in holder_set:
                        f_sps.add(sp)
            return f_idx, True, f_toks, f_owns, f_sps, f_trips
        except Exception:
            return f_idx, False, f_toks, f_owns, f_sps, f_trips

    if is_live and len(_filter_indices) >= 2:
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(_filter_indices)) as ex_tf:
            filter_results = list(ex_tf.map(_run_filter, _filter_indices))
    else:
        filter_results = [_run_filter(fi) for fi in _filter_indices]

    failed_filters: List[int] = []
    collected_spenders: Set[str] = set()
    collected_triples: Set[Tuple[str, str, str]] = set()
    for f_idx, ok_f, f_toks, f_owns, f_sps, f_trips in filter_results:
        if ok_f:
            tokens |= f_toks
            owners |= f_owns
            collected_spenders |= f_sps
            collected_triples |= f_trips
        else:
            failed_filters.append(f_idx)
    if (out_spenders is not None and collected_spenders) or (out_approval_triples is not None and collected_triples):
        with sp_lock:
            if out_spenders is not None and collected_spenders:
                out_spenders |= collected_spenders
            if out_approval_triples is not None and collected_triples:
                out_approval_triples |= collected_triples

    if failed_filters and from_block < to_block and max_depth > 0:
        mid = (from_block + to_block) // 2
        fail_tup = tuple(failed_filters)
        if is_live:
            with concurrent.futures.ThreadPoolExecutor(max_workers=2) as ex_tb:
                fut_l = ex_tb.submit(
                    _harvest_token_logs_bisect,
                    router, chain, holders, from_block, mid, max_depth - 1, out_spenders,
                    out_approval_triples=out_approval_triples, rpc_incomplete_out=rpc_incomplete_out,
                    _filter_indices=fail_tup, _spenders_lock=sp_lock,
                )
                fut_r = ex_tb.submit(
                    _harvest_token_logs_bisect,
                    router, chain, holders, mid + 1, to_block, max_depth - 1, out_spenders,
                    out_approval_triples=out_approval_triples, rpc_incomplete_out=rpc_incomplete_out,
                    _filter_indices=fail_tup, _spenders_lock=sp_lock,
                )
                lt_l, lo_l = fut_l.result()
                lt_r, lo_r = fut_r.result()
        else:
            lt_l, lo_l = _harvest_token_logs_bisect(
                router, chain, holders, from_block, mid, max_depth - 1, out_spenders=out_spenders,
                out_approval_triples=out_approval_triples, rpc_incomplete_out=rpc_incomplete_out,
                _filter_indices=fail_tup, _spenders_lock=sp_lock,
            )
            lt_r, lo_r = _harvest_token_logs_bisect(
                router, chain, holders, mid + 1, to_block, max_depth - 1, out_spenders=out_spenders,
                out_approval_triples=out_approval_triples, rpc_incomplete_out=rpc_incomplete_out,
                _filter_indices=fail_tup, _spenders_lock=sp_lock,
            )
        tokens |= lt_l | lt_r
        owners |= lo_l | lo_r
    elif failed_filters:
        _mark_rpc_incomplete_flag(rpc_incomplete_out, sp_lock)
    return tokens, owners


ROLE_GRANTED_TOPIC0: str = "0x" + _keccak256(b"RoleGranted(bytes32,address,address)").hex()
OWNERSHIP_TRANSFERRED_TOPIC0: str = "0x" + _keccak256(b"OwnershipTransferred(address,address)").hex()
HAS_ROLE_SEL: str = _selector("hasRole(bytes32,address)")
OWNER_VIEW_SEL: str = _selector("owner()")


def _harvest_inbound_trust_and_approvals(
    router: RPCRouter,
    chain: str,
    targets: Sequence[str],
    to_block: int,
    is_live_rpc: bool = False,
    *,
    out_approval_triples: Optional[Set[Tuple[str, str, str]]] = None,
    rpc_incomplete_out: Optional[List[bool]] = None,
    _err_lock: Optional[threading.Lock] = None,
) -> Tuple[Set[str], Set[str], Set[str]]:
    """
    분리형 아키텍처(0xRouter / 0xStrategy / 0xOperator <- 외부 0xVault 승인·권한 부여) 역추적:
    - 넓은 적응형 블록 창에서 topics[2] == pad32(target)인 RoleGranted / OwnershipTransferred / Approval 로그를 일괄 조회한다.
    - RoleGranted 및 OwnershipTransferred 후보는 감사 기준 블록(to_block)에서 hasRole(role, target) 및 owner() == target 온체인 실측으로 해지 여부를 검증한다.
    - 반환값: (verified_privilege_vaults, approval_grantors, approval_tokens)
    """
    verified_vaults: Set[str] = set()
    approval_grantors: Set[str] = set()
    approval_tokens: Set[str] = set()
    if not targets or to_block <= 1:
        return verified_vaults, approval_grantors, approval_tokens
    c = _norm_chain(chain)
    norm_targets = [nt for t in list(targets)[:12] if (nt := _norm_addr(t))]
    if not norm_targets:
        return verified_vaults, approval_grantors, approval_tokens
    padded = ["0x" + ("0" * 24) + nt[2:] for nt in norm_targets]
    spans: Tuple[int, ...] = (1_000_000, 250_000, 50_000, 10_000, 3_000) if is_live_rpc else (500_000, 50_000, 3_000)
    is_real_r = is_live_rpc and _is_live_real_router(router)
    if is_real_r:
        span_map = getattr(router, "_live_log_max_span_by_chain", None)
        if isinstance(span_map, dict):
            cached_sp = int(span_map.get(c, 0) or 0)
            if cached_sp > 0:
                spans = tuple(sp for sp in spans if sp <= cached_sp) or spans
    logs_found: List[Any] = []
    seen_from: Set[int] = set()
    any_span_ok = False
    had_span_exc = False
    for sp in spans:
        f_blk = max(1, int(to_block) - sp)
        if f_blk in seen_from:
            continue
        seen_from.add(f_blk)
        try:
            res_l = router.call(
                c,
                "eth_getLogs",
                [{
                    "fromBlock": hex(f_blk),
                    "toBlock": hex(int(to_block)),
                    "topics": [[ROLE_GRANTED_TOPIC0, OWNERSHIP_TRANSFERRED_TOPIC0, APPROVAL_TOPIC0], None, padded],
                }],
                block_pin=(int(to_block) if int(to_block) > 0 else None),
                timeout=8.0,
            )
            if isinstance(res_l, list):
                any_span_ok = True
                logs_found = res_l
                if is_real_r and isinstance(getattr(router, "_live_log_max_span_by_chain", None), dict):
                    with router._lock:
                        router._live_log_max_span_by_chain[c] = sp
                break
        except Exception:
            had_span_exc = True
            continue
    if not any_span_ok and had_span_exc:
        _mark_rpc_incomplete_flag(rpc_incomplete_out, _err_lock)
    role_cands: List[Tuple[str, bytes, str]] = []
    seen_roles: Set[Tuple[str, bytes, str]] = set()
    owner_cands: List[Tuple[str, str]] = []
    seen_owners: Set[Tuple[str, str]] = set()
    for lg in logs_found:
        if not isinstance(lg, dict):
            continue
        em = _norm_addr(lg.get("address"))
        t_list = lg.get("topics") or []
        if not _is_non_precompile_addr(em) or len(t_list) < 3:
            continue
        t0 = str(t_list[0] or "").lower()
        t1 = str(t_list[1] or "")
        t2 = str(t_list[2] or "")
        acct = _norm_addr("0x" + t2[26:]) if len(t2) == 66 else ""
        if not acct:
            continue
        if t0 == APPROVAL_TOPIC0.lower():
            approval_tokens.add(em)
            ow = _norm_addr("0x" + t1[26:]) if len(t1) == 66 else ""
            if _is_non_precompile_addr(ow):
                approval_grantors.add(ow)
                if out_approval_triples is not None and _is_non_precompile_addr(acct):
                    out_approval_triples.add((ow, acct, em))
        elif t0 == ROLE_GRANTED_TOPIC0.lower() and len(t1) == 66:
            try:
                role_b = bytes.fromhex(t1[2:])
                rk = (em, role_b, acct)
                if rk not in seen_roles:
                    seen_roles.add(rk)
                    role_cands.append(rk)
            except _PARSE_DATA_EXC:
                pass
        elif t0 == OWNERSHIP_TRANSFERRED_TOPIC0.lower():
            ok_key = (em, acct)
            if ok_key not in seen_owners:
                seen_owners.add(ok_key)
                owner_cands.append(ok_key)
    verify_calls: List[Tuple[str, bytes]] = []
    verify_meta: List[Tuple[str, str, str]] = []
    has_role_b = bytes.fromhex(HAS_ROLE_SEL[2:])
    owner_b = bytes.fromhex(OWNER_VIEW_SEL[2:])
    for v_em, role_b, acct in role_cands[:32]:
        verify_calls.append((v_em, has_role_b + role_b + abi_encode(["address"], [acct])))
        verify_meta.append(("role", v_em, acct))
    for v_em, acct in owner_cands[:32]:
        verify_calls.append((v_em, owner_b))
        verify_meta.append(("owner", v_em, acct))
    if verify_calls:
        try:
            v_out = router.multicall3(c, verify_calls, block_pin=to_block)
            v_tls = getattr(router, "_tls", None)
            if (
                len(v_out) < len(verify_calls)
                or (v_tls is not None and bool(getattr(v_tls, "last_multicall_transport_failed", False)))
            ):
                _mark_rpc_incomplete_flag(rpc_incomplete_out, _err_lock)
            for (vk, v_em, acct), (v_ok, v_ret) in zip(verify_meta, v_out):
                if not v_ok or len(v_ret) < 32:
                    continue
                if vk == "role" and int.from_bytes(v_ret[:32], "big") != 0:
                    verified_vaults.add(v_em)
                elif vk == "owner" and _norm_addr("0x" + v_ret[12:32].hex()) == acct:
                    verified_vaults.add(v_em)
        except _RECOVERABLE_IO_EXC:
            _mark_rpc_incomplete_flag(rpc_incomplete_out, _err_lock)
    return verified_vaults, approval_grantors, approval_tokens


_CHAIN_MIN_PRIORITY_TIP_WEI: Dict[str, int] = {
    "polygon": 25_000_000_000,
    "bsc": 50_000_000,
}
_CHAIN_MIN_GAS_PRICE_WEI: Dict[str, int] = {
    "polygon": 25_000_000_000,
    "bsc": 50_000_000,
    "arbitrum": 10_000_000,
    "avalanche": 1_000_000,
}
_SYSTEM_DEPOSIT_TX_TYPES: FrozenSet[int] = frozenset({0x7E, 0x64, 0x65, 0x66, 0x68, 0x6A})


def fetch_gas_price_wei(router: RPCRouter, chain: str, block_pin: int = 0) -> int:
    """
    감사·최신 블록 기준 실측 유효 가스 단가(wei) 산출:
    - 프로토콜 최소 유효 가스단가(`max(baseFee + min_tip, min_gas_price)`) 미달 및 무가스 시스템/디포짓 트랜잭션을 제외한 검증 블록 대표 유효 가스단가
    - 적격 트랜잭션 부재 시 직전 적격 블록 실측치·실시간 호가(`eth_gasPrice`)·프로토콜 최소 유효 가스단가 중 최댓값 반환
    """
    c = _norm_chain(chain)
    btag = hex(int(block_pin)) if block_pin > 0 else "latest"
    min_tip = _CHAIN_MIN_PRIORITY_TIP_WEI.get(c, 0)
    min_gp = _CHAIN_MIN_GAS_PRICE_WEI.get(c, 0)
    need_arch = bool(block_pin > 0)

    def _call_gp_rpc(method_nm: str, params_l: List[Any]) -> Any:
        try:
            return router.call(
                c, method_nm, params_l, block_pin=block_pin, need_archive=need_arch, timeout=6
            )
        except TypeError:
            try:
                return router.call(c, method_nm, params_l, block_pin=block_pin)
            except TypeError:
                return router.call(c, method_nm, params_l)

    target_base_fee = 0
    fh_bf_blocks: List[int] = []
    fh_rw_blocks: List[int] = []
    try:
        fh = _call_gp_rpc("eth_feeHistory", [5, btag, [50]])
        if isinstance(fh, dict):
            bf_raw = fh.get("baseFeePerGas") or []
            rw_raw = fh.get("reward") or []
            if isinstance(bf_raw, list):
                fh_bf_blocks = [
                    int(s, 16) if isinstance(s, str) and s.startswith("0x") else 0
                    for s in bf_raw
                ]
                if len(fh_bf_blocks) >= 2:
                    target_base_fee = max(target_base_fee, fh_bf_blocks[-2])
                elif fh_bf_blocks:
                    target_base_fee = max(target_base_fee, fh_bf_blocks[0])
                if block_pin <= 0 and fh_bf_blocks:
                    target_base_fee = max(target_base_fee, fh_bf_blocks[-1])
            if isinstance(rw_raw, list):
                fh_rw_blocks = [
                    int(rw[0], 16)
                    if (isinstance(rw, list) and rw and isinstance(rw[0], str) and rw[0].startswith("0x"))
                    else 0
                    for rw in rw_raw
                ]
    except (OSError, TimeoutError, ValueError, TypeError, KeyError, RuntimeError):
        pass

    try:
        blk_hdr = _call_gp_rpc("eth_getBlockByNumber", [btag, False])
        if isinstance(blk_hdr, dict):
            bf_hex = blk_hdr.get("baseFeePerGas")
            if isinstance(bf_hex, str) and bf_hex.startswith("0x"):
                bf_val = int(bf_hex, 16)
                if bf_val > 0:
                    target_base_fee = max(target_base_fee, bf_val)
    except (OSError, TimeoutError, ValueError, TypeError, KeyError, RuntimeError):
        pass

    proto_min_wei = max(
        (target_base_fee + min_tip) if (target_base_fee > 0 or min_tip > 0) else 0,
        min_gp,
    )
    block_rep_wei = 0
    prev_eligible_wei = 0

    if fh_rw_blocks:
        n_rw = len(fh_rw_blocks)
        for idx_rw, rw_v in enumerate(fh_rw_blocks):
            bf_i = fh_bf_blocks[idx_rw] if idx_rw < len(fh_bf_blocks) else target_base_fee
            if rw_v > 0 and rw_v >= min_tip:
                eff_i = max(bf_i + rw_v, target_base_fee + rw_v, proto_min_wei)
                if idx_rw == n_rw - 1:
                    block_rep_wei = max(block_rep_wei, eff_i)
                else:
                    prev_eligible_wei = max(prev_eligible_wei, eff_i)

    if block_rep_wei == 0:
        try:
            blk_full = _call_gp_rpc("eth_getBlockByNumber", [btag, True])
            if isinstance(blk_full, dict):
                bf_f = blk_full.get("baseFeePerGas")
                if isinstance(bf_f, str) and bf_f.startswith("0x"):
                    bf_fv = int(bf_f, 16)
                    if bf_fv > 0:
                        target_base_fee = max(target_base_fee, bf_fv)
                        proto_min_wei = max(target_base_fee + min_tip, min_gp)
                raw_txs = blk_full.get("transactions")
                if isinstance(raw_txs, list) and any(isinstance(tx_it, dict) for tx_it in raw_txs):
                    eligible_gps: List[int] = []
                    for tx_it in raw_txs:
                        if not isinstance(tx_it, dict):
                            continue
                        tx_tp = _hex_to_int(tx_it.get("type")) if tx_it.get("type") is not None else 0
                        if tx_tp in _SYSTEM_DEPOSIT_TX_TYPES:
                            continue
                        if tx_it.get("maxFeePerGas") is not None:
                            max_f = _hex_to_int(tx_it.get("maxFeePerGas"))
                            max_p = _hex_to_int(tx_it.get("maxPriorityFeePerGas"))
                            if max_f <= 0 or max_f < target_base_fee or max_p < min_tip:
                                continue
                            eff_tx = min(max_f, target_base_fee + max_p) if target_base_fee > 0 else max_f
                        else:
                            gp_t = _hex_to_int(tx_it.get("gasPrice"))
                            if gp_t <= 0 or (target_base_fee > 0 and gp_t < target_base_fee + min_tip):
                                continue
                            eff_tx = gp_t
                        if eff_tx > 0 and eff_tx >= proto_min_wei:
                            eligible_gps.append(eff_tx)
                    if eligible_gps:
                        eligible_gps.sort()
                        block_rep_wei = max(proto_min_wei, eligible_gps[len(eligible_gps) // 2])
        except (OSError, TimeoutError, ValueError, TypeError, KeyError, RuntimeError):
            pass

    if block_pin > 0 and block_rep_wei > 0:
        return max(block_rep_wei, proto_min_wei)

    live_quote_wei = 0
    try:
        gp = _call_gp_rpc("eth_gasPrice", [])
        if isinstance(gp, str) and gp.startswith("0x"):
            v = int(gp, 16)
            if v > 0:
                live_quote_wei = v
    except (OSError, TimeoutError, ValueError, TypeError, KeyError, RuntimeError):
        pass

    floor_wei = max(block_rep_wei, prev_eligible_wei, live_quote_wei, proto_min_wei)
    if floor_wei > 0:
        return floor_wei
    return 2_000_000_000 if c == "ethereum" else 100_000_000


