def _decode_abi_word_array(data: bytes, offset: int) -> List[bytes]:
    if offset < 0 or offset + 32 > len(data):
        return []
    n_items = int.from_bytes(data[offset : offset + 32], "big")
    if n_items <= 0 or n_items > 2048 or offset + 32 + n_items * 32 > len(data):
        return []
    base = offset + 32
    return [data[base + i * 32 : base + (i + 1) * 32] for i in range(n_items)]


def _fetch_balancer_v3_pools_cached(
    router: RPCRouter,
    chain: str,
    block_pin: int,
) -> List[Tuple[str, Tuple[str, ...], Tuple[int, ...], int]]:
    """Balancer v3 공식 팩토리(`getPools`) 및 싱글톤 Vault(`getPoolTokenInfo`)로 블록별 풀 토큰·잔고·수수료 목록을 캐시 실측한다."""
    c_key = (_norm_chain(chain), int(block_pin))
    with _BALANCER_V3_POOL_CACHE_LOCK:
        cached = _BALANCER_V3_POOL_CACHE.get(c_key)
    if cached is not None:
        return list(cached)
    out: List[Tuple[str, Tuple[str, ...], Tuple[int, ...], int]] = []
    rpc_ok = True
    try:
        fac_calls = [(fac, bytes.fromhex(BALANCER_V3_GET_POOLS_SEL[2:])) for fac in _BALANCER_V3_FACTORIES]
        fac_res = router.multicall3(c_key[0], fac_calls, block_pin=block_pin)
        b3_tls = getattr(router, "_tls", None)
        if not fac_res or (b3_tls is not None and bool(getattr(b3_tls, "last_multicall_transport_failed", False))):
            rpc_ok = False
        pool_addrs: List[str] = []
        seen_p: Set[str] = set()
        for ok_f, ret_f in fac_res:
            if not ok_f or len(ret_f) < 64:
                continue
            off_a = int.from_bytes(ret_f[:32], "big")
            for w_p in _decode_abi_word_array(ret_f, off_a):
                pa = _norm_addr("0x" + w_p[12:32].hex())
                if pa and _is_non_precompile_addr(pa) and pa not in seen_p:
                    seen_p.add(pa)
                    pool_addrs.append(pa)
                    if len(pool_addrs) >= 64:
                        break
            if len(pool_addrs) >= 64:
                break
        if pool_addrs:
            vault_n = _norm_addr(BALANCER_V3_VAULT)
            info_calls: List[Tuple[str, bytes]] = []
            for pa in pool_addrs:
                pa_arg = abi_encode(["address"], [pa])
                info_calls.append((vault_n, bytes.fromhex(BALANCER_V3_GET_POOL_TOKEN_INFO_SEL[2:]) + pa_arg))
                info_calls.append((vault_n, bytes.fromhex(BALANCER_V3_GET_SWAP_FEE_SEL[2:]) + pa_arg))
            info_res = router.multicall3(c_key[0], info_calls, block_pin=block_pin)
            if b3_tls is not None and bool(getattr(b3_tls, "last_multicall_transport_failed", False)):
                rpc_ok = False
            for i_p, pa in enumerate(pool_addrs):
                bi = i_p * 2
                if bi + 1 >= len(info_res):
                    break
                ok_ti, ret_ti = info_res[bi]
                if not ok_ti or len(ret_ti) < 128:
                    continue
                off_toks = int.from_bytes(ret_ti[0:32], "big")
                off_bals = int.from_bytes(ret_ti[64:96], "big")
                tok_ws = _decode_abi_word_array(ret_ti, off_toks)
                bal_ws = _decode_abi_word_array(ret_ti, off_bals)
                if not tok_ws or len(tok_ws) != len(bal_ws):
                    continue
                toks_t = tuple(_norm_addr("0x" + w[12:32].hex()) for w in tok_ws)
                bals_t = tuple(int.from_bytes(w, "big") for w in bal_ws)
                fee_b = 30
                ok_sf, ret_sf = info_res[bi + 1]
                if ok_sf and len(ret_sf) >= 32:
                    raw_sf = int.from_bytes(ret_sf[:32], "big")
                    if 0 < raw_sf <= 10 ** 17:
                        fee_b = max(1, min(1000, (raw_sf * 10000 + (10 ** 18 - 1)) // (10 ** 18)))
                out.append((pa, toks_t, bals_t, fee_b))
    except Exception:
        rpc_ok = False
    if not rpc_ok:
        b3_tls_fin = getattr(router, "_tls", None)
        if b3_tls_fin is not None:
            b3_tls_fin.last_multicall_transport_failed = True
    if rpc_ok:
        with _BALANCER_V3_POOL_CACHE_LOCK:
            if len(_BALANCER_V3_POOL_CACHE) >= 16:
                _BALANCER_V3_POOL_CACHE.clear()
            _BALANCER_V3_POOL_CACHE[c_key] = list(out)
    return out
CURVE_FEE_SEL: str = _selector("fee()")
ERC4626_ASSET_SEL: str = _selector("asset()")
ERC4626_CONVERT_TO_ASSETS_SEL: str = _selector("convertToAssets(uint256)")
ERC4626_PREVIEW_REDEEM_SEL: str = _selector("previewRedeem(uint256)")
ERC4626_REDEEM_SEL: str = _selector("redeem(uint256,address,address)")
AAVE_UNDERLYING_SEL: str = _selector("UNDERLYING_ASSET_ADDRESS()")
AAVE_POOL_SEL: str = _selector("POOL()")
AAVE_WITHDRAW_SEL: str = _selector("withdraw(address,uint256,address)")
COMPOUND_UNDERLYING_SEL: str = _selector("underlying()")
COMPOUND_EXCHANGE_RATE_STORED_SEL: str = _selector("exchangeRateStored()")
COMPOUND_GET_CASH_SEL: str = _selector("getCash()")
COMPOUND_REDEEM_SEL: str = _selector("redeem(uint256)")
COMPOUND_REDEEM_UNDERLYING_SEL: str = _selector("redeemUnderlying(uint256)")


def _with_decimal_prec_100(fn: Callable[..., Any]) -> Callable[..., Any]:
    @functools.wraps(fn)
    def _wrapped(*args: Any, **kwargs: Any) -> Any:
        with localcontext() as _dec_ctx:
            _dec_ctx.prec = 100
            return fn(*args, **kwargs)

    return _wrapped


@functools.lru_cache(maxsize=512)
def _norm_addr_tuple_cached(raw_items: Tuple[str, ...]) -> Tuple[str, ...]:
    return tuple(dict.fromkeys(na for x in raw_items if (na := _norm_addr(x))))


@functools.lru_cache(maxsize=512)
def _norm_addr_frozenset_cached(raw_items: Tuple[str, ...]) -> FrozenSet[str]:
    return frozenset(_norm_addr_tuple_cached(raw_items))


def _lookup_chain_addr_tuple(table: Mapping[str, Sequence[str]], chain: str) -> Tuple[str, ...]:
    return _norm_addr_tuple_cached(tuple(table.get(_norm_chain(chain), ())))


def _norm_chain_stables(chain: str) -> Tuple[str, ...]:
    return _lookup_chain_addr_tuple(CHAIN_STABLES, chain)


def _norm_chain_stables_set(chain: str) -> FrozenSet[str]:
    return _norm_addr_frozenset_cached(_norm_chain_stables(chain))


def _norm_chain_bluechips_set(chain: str) -> FrozenSet[str]:
    return _norm_addr_frozenset_cached(_lookup_chain_addr_tuple(CHAIN_BLUECHIPS, chain))


def _decode_clamped_dec(r_entry: Tuple[bool, bytes], default_dec: int = 18) -> int:
    raw_d = int.from_bytes(r_entry[1][:32], "big") if (r_entry[0] and len(r_entry[1]) >= 32) else default_dec
    return max(0, min(77, raw_d))


@_with_decimal_prec_100
def probe_dex_exit_liquidity(
    router: RPCRouter,
    chain: str,
    token_addr: str,
    raw_amount: int,
    decimals: int,
    unit_price_usd: Union[Decimal, int, str],
    native_usd: Union[Decimal, int, str],
    block_pin: int,
    quote_prices_usd: Optional[Mapping[str, Union[Decimal, int, str]]] = None,
    unbacked_supply_mint: bool = False,
    _redeem_depth: int = 0,
) -> Dict[str, Any]:
    """
    DEX 환금성 및 AMM 슬리피지·스왑 수수료 단일 배치 실측:
    - 네이티브 및 체인 표준 Wrapped Native는 1:1 무손실 환금
    - 상위 스테이블코인은 온체인 WNATIVE 풀 스팟 가격 교차검증(>15% 괴리 시 Fail-Open) 및 5~30bps 스왑 수수료·슬리피지 반영
    - LP 토큰은 getReserves/totalSupply/token0/token1 및 실측 decimals·단가로 환금 한도 산출
    - 일반 ERC-20 및 무담보 발행량 증가분(unbacked_supply_mint)은 온체인 V2/V3 풀 리저브로만 환금 한도를 산출(가공 심도 부여 금지)
    """
    c = _norm_chain(chain)
    tok = _norm_addr(token_addr)
    dec = max(0, min(77, int(18 if decimals is None else decimals)))
    eff_unit_price_dec = max(_DEC_ZERO, _to_dec(unit_price_usd))
    nat_usd_dec = max(_DEC_ZERO, _to_dec(native_usd))
    nominal_units_dec = (Decimal(int(raw_amount)) / (Decimal(10) ** dec)) if raw_amount > 0 else _DEC_ZERO
    nominal_usd_dec = nominal_units_dec * eff_unit_price_dec
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    stables = list(_norm_chain_stables(c))
    stables_set = _norm_chain_stables_set(c)
    tier1_stables = set(stables[:4])
    q_price_cache: Dict[str, Decimal] = {}
    q_price_lock = threading.Lock()
    for k_qp, v_qp in (quote_prices_usd or {}).items():
        nk_qp = _norm_addr(k_qp)
        dv_qp = _to_dec(v_qp)
        if nk_qp and dv_qp > _DEC_ZERO:
            q_price_cache[nk_qp] = dv_qp

    def _quote_usd_dec(qt_addr: str) -> Decimal:
        q_norm = _norm_addr(qt_addr)
        if not q_norm:
            return _DEC_ZERO
        if wnative and q_norm == wnative:
            return nat_usd_dec
        with q_price_lock:
            cached_q = q_price_cache.get(q_norm)
        if cached_q is not None:
            return cached_q
        if block_pin > 0:
            st_ref = getattr(router, "store", None)
            p_live_d, _ = _fetch_token_price_usd_dec(
                st_ref,
                c,
                q_norm,
                router=router,
                block_pin=block_pin,
                allow_offline_fixture=False,
                _allow_live_xcheck=False,
            )
            val_dec = max(_DEC_ZERO, p_live_d)
            with q_price_lock:
                q_price_cache[q_norm] = val_dec
            return val_dec
        return Decimal("1") if q_norm in stables_set else _DEC_ZERO

    def _v3_tok_in_quote_dec(r_s0: Tuple[bool, bytes], r_t0: Tuple[bool, bytes], qt_a: str, qt_dec: int) -> Decimal:
        if not (r_s0[0] and len(r_s0[1]) >= 32 and r_t0[0] and len(r_t0[1]) >= 32):
            return _DEC_ZERO
        sqrt_p_x96 = int.from_bytes(r_s0[1][:32], "big")
        t0_addr = _norm_addr("0x" + r_t0[1][12:32].hex())
        if sqrt_p_x96 <= 0 or t0_addr not in (tok, qt_a):
            return _DEC_ZERO
        ratio_dec = (Decimal(sqrt_p_x96) / Decimal(1 << 96)) ** 2
        if ratio_dec <= _DEC_ZERO:
            return _DEC_ZERO
        scale_dec = Decimal(10) ** (dec - qt_dec)
        return (ratio_dec if t0_addr == tok else (Decimal("1") / ratio_dec)) * scale_dec

    def _zero_slip_liq_out(exit_ok: bool, depth_dec: Decimal) -> Dict[str, Any]:
        return {
            "exit_liquid": exit_ok,
            "realizable_usd": nominal_usd_dec,
            "realizable_usd_dec": format(nominal_usd_dec, "f"),
            "nominal_usd": nominal_usd_dec,
            "nominal_usd_dec": format(nominal_usd_dec, "f"),
            "effective_unit_price": eff_unit_price_dec,
            "effective_unit_price_dec": format(eff_unit_price_dec, "f"),
            "swap_fee_bps": 0,
            "slippage_bps": 0,
            "dex_depth_usd": depth_dec,
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }

    dex_rpc_incomplete: List[bool] = [False]
    dex_rpc_lock = threading.Lock()

    def _mark_dex_rpc_incomplete() -> None:
        with dex_rpc_lock:
            dex_rpc_incomplete[0] = True

    def _mc3_checked(mc_calls: Sequence[Tuple[str, bytes]]) -> List[Tuple[bool, bytes]]:
        mc_out = router.multicall3(c, mc_calls, block_pin=block_pin)
        r_tls = getattr(router, "_tls", None)
        if r_tls is not None and bool(getattr(r_tls, "last_multicall_transport_failed", False)):
            _mark_dex_rpc_incomplete()
        return mc_out

    def _illiquid_dex_out(*, price_diverged: bool = False, paused: bool = False) -> Dict[str, Any]:
        out_il: Dict[str, Any] = {
            "exit_liquid": False,
            "realizable_usd": _DEC_ZERO,
            "swap_fee_bps": 30,
            "slippage_bps": 10000,
            "dex_depth_usd": _DEC_ZERO,
        }
        if price_diverged:
            out_il["price_diverged"] = True
        if paused:
            out_il["paused"] = True
        if dex_rpc_incomplete[0]:
            out_il["rpc_incomplete"] = True
        return out_il

    def _append_pool_balance_calls(
        calls_out: List[Tuple[str, bytes]], pool_qt_pairs: Iterable[Tuple[str, str]]
    ) -> None:
        for p_a, q_a in pool_qt_pairs:
            bal_raw = bytes.fromhex(encode_calldata(BALANCE_OF_SEL, ["address"], [p_a])[2:])
            calls_out.append((q_a, bal_raw))
            calls_out.append((tok, bal_raw))

    if token_addr == "native" or (wnative and tok == wnative and not unbacked_supply_mint):
        return _zero_slip_liq_out(
            nominal_usd_dec > _DEC_ZERO or raw_amount > 0,
            max(nominal_usd_dec, Decimal("10000000")),
        )
    if not tok:
        return _illiquid_dex_out()

    peg_confirmed = False
    if tok in stables and not unbacked_supply_mint:
        if eff_unit_price_dec <= _DEC_ZERO:
            return _illiquid_dex_out()
        if block_pin > 0:
            v2_facs = _UNIV2_FACTORIES.get(c, [])[:2]
            v3_facs = _UNIV3_FACTORIES.get(c, [])[:1]
            peg_depth_floor = Decimal("10000")

            def _probe_peg_quotes(quote_specs: Sequence[Tuple[str, Decimal]]) -> Tuple[bool, Optional[Decimal]]:
                valid_specs = [
                    (qt_a, qt_u) for qt_a, qt_u in quote_specs if qt_a and qt_a != tok and qt_u > _DEC_ZERO
                ]
                if not valid_specs:
                    return False, None
                peg_queries: List[Tuple[str, bytes]] = []
                peg_meta_q: List[Tuple[bool, str, Decimal]] = []
                for qt_a, qt_u in valid_specs:
                    for fac in v2_facs:
                        cd_h = encode_calldata(V2_GET_PAIR_SEL, ["address", "address"], [tok, qt_a])
                        peg_queries.append((fac, bytes.fromhex(cd_h[2:])))
                        peg_meta_q.append((False, qt_a, qt_u))
                    for fac3 in v3_facs:
                        for v3_f, _ in _V3_FEE_TIERS:
                            cd3_h = encode_calldata(V3_GET_POOL_SEL, ["address", "address", "uint24"], [tok, qt_a, v3_f])
                            peg_queries.append((fac3, bytes.fromhex(cd3_h[2:])))
                            peg_meta_q.append((True, qt_a, qt_u))
                if not peg_queries:
                    return False, None
                peg_res = _mc3_checked(peg_queries)
                peg_pools: List[Tuple[str, bool, str, Decimal]] = []
                seen_peg_pa: Set[str] = set()
                for idx_pq, (ok_pp, ret_pp) in enumerate(peg_res):
                    if ok_pp and len(ret_pp) >= 32:
                        pa = _norm_addr("0x" + ret_pp[12:32].hex())
                        if pa and int(pa, 16) > 0 and pa not in seen_peg_pa:
                            seen_peg_pa.add(pa)
                            is_v3_p, qt_a_p, qt_u_p = peg_meta_q[idx_pq]
                            peg_pools.append((pa, is_v3_p, qt_a_p, qt_u_p))
                if not peg_pools:
                    return False, None
                uniq_qts = list(dict.fromkeys(qt_a_p for _, _, qt_a_p, _ in peg_pools))
                p_rcalls: List[Tuple[str, bytes]] = [
                    (qt_a_p, bytes.fromhex(DECIMALS_SEL[2:])) for qt_a_p in uniq_qts
                ]
                dec_off = len(uniq_qts)
                _append_pool_balance_calls(p_rcalls, ((pa, qt_a_p) for pa, _, qt_a_p, _ in peg_pools))
                v3_peg_idxs: List[Tuple[int, str, str, Decimal]] = [
                    (idx_pp, pa, qt_a_p, qt_u_p)
                    for idx_pp, (pa, is_v3_p, qt_a_p, qt_u_p) in enumerate(peg_pools)
                    if is_v3_p
                ]
                for _, pa, _, _ in v3_peg_idxs:
                    p_rcalls.append((pa, bytes.fromhex(V3_SLOT0_SEL[2:])))
                    p_rcalls.append((pa, bytes.fromhex(V2_TOKEN0_SEL[2:])))
                    p_rcalls.append((pa, bytes.fromhex(V3_LIQUIDITY_SEL[2:])))
                pr_out = _mc3_checked(p_rcalls)
                qt_dec_map: Dict[str, int] = {
                    qt_a_p: _decode_clamped_dec(pr_out[qi] if qi < len(pr_out) else (False, b""))
                    for qi, qt_a_p in enumerate(uniq_qts)
                }
                v3_peg_spot_usd: Dict[int, Decimal] = {}
                v3_peg_zero_liq: Set[int] = set()
                v3_peg_off = dec_off + len(peg_pools) * 2
                for k_vp, (idx_pp, _, qt_a_p, qt_u_p) in enumerate(v3_peg_idxs):
                    si_p = v3_peg_off + k_vp * 3
                    if si_p + 2 >= len(pr_out):
                        break
                    r_peg_liq = pr_out[si_p + 2]
                    if r_peg_liq[0] and len(r_peg_liq[1]) >= 32 and int.from_bytes(r_peg_liq[1][:32], "big") == 0:
                        v3_peg_zero_liq.add(idx_pp)
                        continue
                    tok_in_q_dec = _v3_tok_in_quote_dec(
                        pr_out[si_p], pr_out[si_p + 1], qt_a_p, qt_dec_map.get(qt_a_p, 18)
                    )
                    if tok_in_q_dec > _DEC_ZERO:
                        v3_peg_spot_usd[idx_pp] = tok_in_q_dec * qt_u_p
                best_peg_depth_dec = _DEC_ZERO
                best_peg_spot_dec = _DEC_ZERO
                for idx_pp, (_, is_v3_p, qt_a_p, qt_u_p) in enumerate(peg_pools):
                    bi = dec_off + idx_pp * 2
                    if bi + 1 >= len(pr_out):
                        break
                    rw_b, rt_b = pr_out[bi], pr_out[bi + 1]
                    if not (rw_b[0] and len(rw_b[1]) >= 32 and rt_b[0] and len(rt_b[1]) >= 32):
                        continue
                    w_raw = int.from_bytes(rw_b[1][:32], "big")
                    t_raw = int.from_bytes(rt_b[1][:32], "big")
                    qt_dec_p = qt_dec_map.get(qt_a_p, 18)
                    w_usd_dec = (Decimal(w_raw) / (Decimal(10) ** qt_dec_p)) * qt_u_p
                    t_units_pool_dec = Decimal(t_raw) / (Decimal(10) ** dec)
                    if is_v3_p:
                        if idx_pp in v3_peg_zero_liq:
                            continue
                        s_v3_dec = v3_peg_spot_usd.get(idx_pp, _DEC_ZERO)
                        t_usd_side_dec = t_units_pool_dec * s_v3_dec if s_v3_dec > _DEC_ZERO else _DEC_ZERO
                        cand_depth_dec = w_usd_dec + (
                            t_usd_side_dec if s_v3_dec > _DEC_ZERO else (t_units_pool_dec * eff_unit_price_dec)
                        )
                        if (
                            w_usd_dec > _DEC_ZERO
                            and t_raw > 0
                            and s_v3_dec > _DEC_ZERO
                            and min(w_usd_dec, t_usd_side_dec) >= Decimal("100")
                            and cand_depth_dec >= peg_depth_floor
                            and cand_depth_dec > best_peg_depth_dec
                        ):
                            best_peg_depth_dec = cand_depth_dec
                            best_peg_spot_dec = s_v3_dec
                    else:
                        cand_depth_dec = w_usd_dec * Decimal("2")
                        if (
                            w_usd_dec >= peg_depth_floor
                            and t_units_pool_dec > _DEC_ZERO
                            and cand_depth_dec > best_peg_depth_dec
                        ):
                            best_peg_depth_dec = cand_depth_dec
                            best_peg_spot_dec = w_usd_dec / t_units_pool_dec
                if best_peg_depth_dec >= peg_depth_floor and best_peg_spot_dec > _DEC_ZERO:
                    p_hi_dec = max(eff_unit_price_dec, best_peg_spot_dec)
                    p_lo_dec = min(eff_unit_price_dec, best_peg_spot_dec)
                    if p_hi_dec > _DEC_ZERO and ((p_hi_dec - p_lo_dec) / p_hi_dec) > Decimal("0.15"):
                        return True, None
                    return False, p_lo_dec
                return False, None

            peg_div = False
            peg_price_lo: Optional[Decimal] = None
            if nat_usd_dec > _DEC_ZERO and wnative:
                peg_div, peg_price_lo = _probe_peg_quotes([(wnative, nat_usd_dec)])
            if not peg_div and peg_price_lo is None:
                peer_stables = [s for s in stables[:4] if s and s != tok][:3]
                if peer_stables:
                    peer_specs: List[Tuple[str, Decimal]] = []
                    for ps in peer_stables:
                        ps_usd = _quote_usd_dec(ps)
                        if ps_usd <= _DEC_ZERO and ps in tier1_stables and not _is_live_real_router(router):
                            ps_usd = Decimal("1")
                        if ps_usd > _DEC_ZERO:
                            peer_specs.append((ps, ps_usd))
                    if peer_specs:
                        peg_div, peg_price_lo = _probe_peg_quotes(peer_specs)
            if peg_div:
                return _illiquid_dex_out(price_diverged=True)
            if peg_price_lo is not None and peg_price_lo > _DEC_ZERO:
                peg_confirmed = True
                eff_unit_price_dec = peg_price_lo
                nominal_usd_dec = nominal_units_dec * eff_unit_price_dec

    calls: List[Tuple[str, bytes]] = [
        (tok, bytes.fromhex(TOTAL_SUPPLY_SEL[2:])),
        (tok, bytes.fromhex(V2_RESERVES_SEL[2:])),
        (tok, bytes.fromhex(V2_TOKEN0_SEL[2:])),
        (tok, bytes.fromhex(V2_TOKEN1_SEL[2:])),
        (tok, bytes.fromhex(PAUSED_SEL[2:])),
    ]
    res = _mc3_checked(calls) if block_pin > 0 else []
    if len(res) >= 5 and res[4][0] and len(res[4][1]) >= 32 and int.from_bytes(res[4][1][:32], "big") != 0:
        return _illiquid_dex_out(paused=True)

    live_router_chk = _is_live_real_router(router) and block_pin > 0
    if (not live_router_chk or peg_confirmed) and not unbacked_supply_mint and tok in tier1_stables and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("5000000") if c in ("ethereum", "arbitrum", "base", "bsc", "optimism", "polygon") else Decimal("500000")
        if nominal_usd_dec <= depth_dec:
            return _zero_slip_liq_out(
                nominal_usd_dec > _DEC_ZERO,
                depth_dec,
            )

    if not live_router_chk and not unbacked_supply_mint and tok in stables[:6] and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("5000000") if c in ("ethereum", "arbitrum", "base", "bsc", "optimism", "polygon") else Decimal("500000")
        eff_nom_dec = min(nominal_usd_dec, depth_dec)
        slip_bps = min(2500, max(5, int((nominal_usd_dec / max(Decimal("1"), depth_dec)) * Decimal("500"))))
        fee_bps = 5 if nominal_usd_dec < depth_dec else 30
        realizable_dec = eff_nom_dec * (Decimal(max(0, 10000 - (fee_bps + slip_bps))) / Decimal("10000"))
        return {
            "exit_liquid": realizable_dec > _DEC_ZERO,
            "realizable_usd": realizable_dec,
            "realizable_usd_dec": format(realizable_dec, "f"),
            "nominal_usd": nominal_usd_dec,
            "nominal_usd_dec": format(nominal_usd_dec, "f"),
            "swap_fee_bps": fee_bps,
            "slippage_bps": slip_bps,
            "dex_depth_usd": depth_dec,
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }
    total_supply = 0
    if len(res) >= 1 and res[0][0] and len(res[0][1]) >= 32:
        total_supply = int.from_bytes(res[0][1][:32], "big")
    if not unbacked_supply_mint and len(res) >= 4 and res[1][0] and len(res[1][1]) >= 64 and res[2][0] and res[3][0]:
        try:
            r0 = int.from_bytes(res[1][1][0:32], "big")
            r1 = int.from_bytes(res[1][1][32:64], "big")
            t0 = _norm_addr("0x" + res[2][1][12:32].hex())
            t1 = _norm_addr("0x" + res[3][1][12:32].hex())
            liq_usd_dec = _DEC_ZERO
            lp_qt = ""
            lp_other = ""
            tok_lp_arg = abi_encode(["address"], [tok])

            def _clamp_lp_reserve(qt_tok_a: str, rep_amt: int, def_dec: int) -> Tuple[int, int]:
                if block_pin <= 0:
                    return rep_amt, def_dec
                lp_q_calls: List[Tuple[str, bytes]] = [
                    (qt_tok_a, bytes.fromhex(DECIMALS_SEL[2:])),
                    (qt_tok_a, bytes.fromhex(BALANCE_OF_SEL[2:]) + tok_lp_arg),
                ]
                lp_q_res = _mc3_checked(lp_q_calls)
                dec_lp_q = _decode_clamped_dec(lp_q_res[0] if lp_q_res else (False, b""), def_dec)
                if len(lp_q_res) >= 2 and lp_q_res[1][0] and len(lp_q_res[1][1]) >= 32:
                    eff_lp_amt = min(rep_amt, int.from_bytes(lp_q_res[1][1][:32], "big"))
                elif _is_live_real_router(router):
                    eff_lp_amt = 0
                else:
                    eff_lp_amt = rep_amt
                return eff_lp_amt, dec_lp_q

            if wnative and (t0 == wnative or t1 == wnative):
                w_res_amt, w_dec_lp = _clamp_lp_reserve(wnative, r0 if t0 == wnative else r1, 18)
                lp_qt = wnative
                lp_other = t1 if t0 == wnative else t0
                liq_usd_dec = (Decimal(w_res_amt) / (Decimal(10) ** w_dec_lp)) * nat_usd_dec * Decimal("2")
            elif t0 in stables_set or t1 in stables_set:
                st_tok = t0 if t0 in stables_set else t1
                raw_st_res = r0 if t0 in stables_set else r1
                st_q_dec = _quote_usd_dec(st_tok)
                lp_qt = st_tok
                lp_other = t1 if st_tok == t0 else t0
                if st_q_dec > _DEC_ZERO:
                    st_res_amt, s_dec = _clamp_lp_reserve(st_tok, raw_st_res, 6 if raw_st_res < 10 ** 15 else 18)
                    liq_usd_dec = (Decimal(st_res_amt) / (Decimal(10) ** s_dec)) * st_q_dec * Decimal("2")
            elif t0 in _norm_chain_bluechips_set(c) or t1 in _norm_chain_bluechips_set(c):
                bc_set_lp = _norm_chain_bluechips_set(c)
                bc_tok = t0 if t0 in bc_set_lp else t1
                raw_bc_res = r0 if bc_tok == t0 else r1
                bc_q_dec = _quote_usd_dec(bc_tok)
                if bc_q_dec > _DEC_ZERO:
                    lp_qt = bc_tok
                    lp_other = t1 if bc_tok == t0 else t0
                    bc_res_amt, b_dec = _clamp_lp_reserve(bc_tok, raw_bc_res, 18)
                    liq_usd_dec = (Decimal(bc_res_amt) / (Decimal(10) ** b_dec)) * bc_q_dec * Decimal("2")
            if lp_qt and lp_other and liq_usd_dec > _DEC_ZERO:
                oth_q_dec = _quote_usd_dec(lp_other)
                if oth_q_dec > _DEC_ZERO:
                    oth_res_amt, o_dec = _clamp_lp_reserve(lp_other, r0 if lp_other == t0 else r1, 18)
                    oth_usd_total = (Decimal(oth_res_amt) / (Decimal(10) ** o_dec)) * oth_q_dec
                    liq_usd_dec = min(liq_usd_dec, (liq_usd_dec / Decimal("2")) + oth_usd_total)
            if total_supply > 0 and liq_usd_dec >= PROFIT_FLOOR_DEC and lp_qt:
                share_dec = min(Decimal("1"), Decimal(raw_amount) / Decimal(total_supply))
                lp_usd_dec = liq_usd_dec * share_dec
                realizable_lp_dec = lp_usd_dec * Decimal("0.994")
                lp_out: Dict[str, Any] = {
                    "exit_liquid": realizable_lp_dec > _DEC_ZERO,
                    "realizable_usd": realizable_lp_dec,
                    "realizable_usd_dec": format(realizable_lp_dec, "f"),
                    "nominal_usd": lp_usd_dec,
                    "nominal_usd_dec": format(lp_usd_dec, "f"),
                    "swap_fee_bps": 30,
                    "slippage_bps": 30,
                    "dex_depth_usd": liq_usd_dec,
                    "dex_depth_usd_dec": format(liq_usd_dec, "f"),
                    "best_pool_address": _checksum(tok),
                    "best_quote_token": _checksum(lp_qt),
                    "best_dex_kind": "lp_token",
                }
                if lp_other and lp_other not in (tok, lp_qt):
                    lp_out["best_other_token"] = _checksum(lp_other)
                if dex_rpc_incomplete[0]:
                    lp_out["rpc_incomplete"] = True
                return lp_out
        except _RECOVERABLE_IO_EXC:
            _mark_dex_rpc_incomplete()

    if block_pin <= 0 and not unbacked_supply_mint and tok in stables_set and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("250000")
        slip_bps = min(3000, max(15, int((nominal_usd_dec / depth_dec) * Decimal("1000"))))
        capped_nom_dec = min(nominal_usd_dec, depth_dec)
        realizable_st_dec = capped_nom_dec * (Decimal(max(0, 10000 - (30 + slip_bps))) / Decimal("10000"))
        return {
            "exit_liquid": realizable_st_dec > _DEC_ZERO,
            "realizable_usd": realizable_st_dec,
            "realizable_usd_dec": format(realizable_st_dec, "f"),
            "nominal_usd": capped_nom_dec,
            "nominal_usd_dec": format(capped_nom_dec, "f"),
            "swap_fee_bps": 30,
            "slippage_bps": slip_bps,
            "dex_depth_usd": depth_dec,
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }

    # 일반 ERC-20: V2/Solidly/V3/Algebra + Uniswap V4 + Balancer V3 + Curve MetaRegistry 4축 병렬 온체인 실측
    bluechips = sorted(_norm_chain_bluechips_set(c))
    quote_tokens = list(dict.fromkeys(q for q in ([wnative] + list(stables) + bluechips) if q and q != tok))
    v2_factories = _UNIV2_FACTORIES.get(c, [])
    solidly_factories = _SOLIDLY_FACTORIES.get(c, [])
    v3_factories = _UNIV3_FACTORIES.get(c, [])
    alg_factories = _ALGEBRA_FACTORIES.get(c, [])
    v4_pms = UNISWAP_V4_POOL_MANAGERS.get(c, ())
    has_v23_factories = bool(v2_factories or solidly_factories or v3_factories or alg_factories)
    has_v4_axis = bool(v4_pms and raw_amount > 0)
    has_bal3_axis = bool(c in _BALANCER_V3_CHAINS and raw_amount > 0)
    has_curve_axis = bool(c in _CURVE_METAREGISTRY_CHAINS and raw_amount > 0)
    if block_pin > 0 and (has_v23_factories or has_v4_axis or has_bal3_axis or has_curve_axis) and quote_tokens:
        best_realizable_dec = _DEC_ZERO
        best_pq_dec = _DEC_ZERO
        best_out_nom_dec = nominal_usd_dec
        best_fee_bps = 30
        best_pool_addr = ""
        best_quote_addr = ""
        best_dex_kind = ""
        best_v3_fee = 0
        best_v4_tick_spacing = 0
        best_curve_i, best_curve_j, best_curve_underlying, best_solidly_stable = 0, 0, False, False

        def _consider_best_exit_route(
            cand_real: Decimal,
            cand_pq: Decimal,
            cand_out_nom: Decimal,
            cand_fee_bps: int,
            cand_pool: str,
            cand_quote: str,
            cand_kind: str,
            *,
            v3_fee: int = 0,
            v4_ts: int = 0,
            curve_i: int = 0,
            curve_j: int = 0,
            curve_und: bool = False,
            solidly_st: bool = False,
        ) -> None:
            nonlocal best_realizable_dec, best_pq_dec, best_out_nom_dec, best_fee_bps
            nonlocal best_pool_addr, best_quote_addr, best_dex_kind, best_v3_fee, best_v4_tick_spacing
            nonlocal best_curve_i, best_curve_j, best_curve_underlying, best_solidly_stable
            if (cand_real, cand_pq) > (best_realizable_dec, best_pq_dec):
                best_realizable_dec = cand_real
                best_pq_dec = cand_pq
                best_out_nom_dec = cand_out_nom
                best_fee_bps = int(cand_fee_bps)
                best_pool_addr = cand_pool
                best_quote_addr = cand_quote
                best_dex_kind = cand_kind
                best_v3_fee = int(v3_fee)
                best_v4_tick_spacing = int(v4_ts)
                best_curve_i = int(curve_i)
                best_curve_j = int(curve_j)
                best_curve_underlying = bool(curve_und)
                best_solidly_stable = bool(solidly_st)

        def _probe_v23_axis() -> Tuple[List[Tuple[Tuple[Any, ...], Dict[str, Any]]], Dict[str, Tuple[Decimal, Decimal]]]:
            routes_out: List[Tuple[Tuple[Any, ...], Dict[str, Any]]] = []
            cons_out: Dict[str, Tuple[Decimal, Decimal]] = {}
            pool_queries: List[Tuple[str, bytes]] = []
            pool_meta: List[Tuple[str, int, str, int, str]] = []

            def _append_pair_factory_queries(factories: Sequence[str], sel_hex: str, dex_kind: str) -> None:
                for fac_item in factories[:2]:
                    for qt_item in quote_tokens:
                        cd_p = encode_calldata(sel_hex, ["address", "address"], [tok, qt_item])
                        pool_queries.append((fac_item, bytes.fromhex(cd_p[2:])))
                        pool_meta.append((qt_item, 30, dex_kind, 0, ""))

            _append_pair_factory_queries(v2_factories, V2_GET_PAIR_SEL, "v2")
            for fac_s in solidly_factories[:2]:
                for qt in quote_tokens:
                    for is_stable, s_fee, s_kind in ((False, 30, "solidly_v"), (True, 5, "solidly_s")):
                        for s_sel in (SOLIDLY_GET_POOL_SEL, SOLIDLY_GET_PAIR_SEL):
                            cds_hex = encode_calldata(s_sel, ["address", "address", "bool"], [tok, qt, is_stable])
                            pool_queries.append((fac_s, bytes.fromhex(cds_hex[2:])))
                            pool_meta.append((qt, s_fee, s_kind, 0, ""))
            for fac3 in v3_factories[:2]:
                q2_addr = _UNIV3_QUOTERS_V2.get((c, _norm_addr(fac3)), "")
                for qt in quote_tokens:
                    for v3_fee, fee_b in _V3_FEE_TIERS:
                        cd3_hex = encode_calldata(V3_GET_POOL_SEL, ["address", "address", "uint24"], [tok, qt, v3_fee])
                        pool_queries.append((fac3, bytes.fromhex(cd3_hex[2:])))
                        pool_meta.append((qt, fee_b, "v3", v3_fee, q2_addr))
            _append_pair_factory_queries(alg_factories, ALGEBRA_POOL_SEL, "algebra")
            try:
                p_res = _mc3_checked(pool_queries)
            except _RECOVERABLE_IO_EXC:
                _mark_dex_rpc_incomplete()
                return routes_out, cons_out
            discovered_pools: List[Tuple[str, str, int, str, int, str]] = []
            seen_pools: Set[str] = set()
            for idx_p, (ok_p, ret_p) in enumerate(p_res):
                if not ok_p or len(ret_p) < 32:
                    continue
                pool_addr = _norm_addr("0x" + ret_p[12:32].hex())
                if not pool_addr or int(pool_addr, 16) == 0 or pool_addr in seen_pools:
                    continue
                seen_pools.add(pool_addr)
                qt_addr, fee_b, dex_kind, v3_fee_raw, q2_addr = pool_meta[idx_p]
                discovered_pools.append((pool_addr, qt_addr, fee_b, dex_kind, v3_fee_raw, q2_addr))
            if not discovered_pools:
                return routes_out, cons_out
            uniq_qts_d: List[str] = list(dict.fromkeys(qt_addr for _, qt_addr, *_ in discovered_pools))
            reserve_calls: List[Tuple[str, bytes]] = [
                (qt_u, bytes.fromhex(DECIMALS_SEL[2:])) for qt_u in uniq_qts_d
            ]
            _append_pool_balance_calls(reserve_calls, ((pa_d, qt_d) for pa_d, qt_d, _, _, _, _ in discovered_pools))
            v3_indices: List[Tuple[int, str, str, str]] = [
                (idx_d, pool_addr, qt_addr, dk)
                for idx_d, (pool_addr, qt_addr, _, dk, _, _) in enumerate(discovered_pools)
                if dk in ("v3", "algebra")
            ]
            for _, pool_addr, _, dk in v3_indices:
                state_sel = ALGEBRA_GLOBAL_STATE_SEL if dk == "algebra" else V3_SLOT0_SEL
                reserve_calls.append((pool_addr, bytes.fromhex(state_sel[2:])))
                reserve_calls.append((pool_addr, bytes.fromhex(V2_TOKEN0_SEL[2:])))
                reserve_calls.append((pool_addr, bytes.fromhex(V3_LIQUIDITY_SEL[2:])))
            solidly_indices: List[Tuple[int, str, str]] = (
                [
                    (idx_d, pool_addr, qt_addr)
                    for idx_d, (pool_addr, qt_addr, _, dk, _, _) in enumerate(discovered_pools)
                    if dk.startswith("solidly")
                ]
                if raw_amount > 0
                else []
            )
            amt_out_cd = (
                bytes.fromhex(encode_calldata(SOLIDLY_AMOUNT_OUT_SEL, ["uint256", "address"], [raw_amount, tok])[2:])
                if solidly_indices
                else b""
            )
            for _, pool_addr, _ in solidly_indices:
                reserve_calls.append((pool_addr, amt_out_cd))
            try:
                r_batch = _mc3_checked(reserve_calls)
            except _RECOVERABLE_IO_EXC:
                _mark_dex_rpc_incomplete()
                return routes_out, cons_out
            bal_offset = len(uniq_qts_d)
            q_dec_map_d: Dict[str, int] = {
                qt_u: _decode_clamped_dec(r_batch[i_qu] if i_qu < len(r_batch) else (False, b""))
                for i_qu, qt_u in enumerate(uniq_qts_d)
            }
            q_dec_by_idx: List[int] = [
                q_dec_map_d.get(qt_addr, 18) for _, qt_addr, *_ in discovered_pools
            ]
            v3_spot_by_idx: Dict[int, Decimal] = {}
            v3_active_q_units_by_idx: Dict[int, Decimal] = {}
            v3_zero_liq: Set[int] = set()
            alg_fee_by_idx: Dict[int, int] = {}
            v3_offset = bal_offset + len(discovered_pools) * 2
            for k_v3, (idx_d, _, qt_addr, dk) in enumerate(v3_indices):
                si = v3_offset + k_v3 * 3
                if si + 2 >= len(r_batch):
                    break
                if r_batch[si + 2][0] and len(r_batch[si + 2][1]) >= 32:
                    liq_val = int.from_bytes(r_batch[si + 2][1][:32], "big")
                    if liq_val == 0:
                        v3_zero_liq.add(idx_d)
                        continue
                else:
                    liq_val = 0
                if dk == "algebra" and r_batch[si][0] and len(r_batch[si][1]) >= 96:
                    raw_alg_fee = int.from_bytes(r_batch[si][1][64:96], "big")
                    if 0 < raw_alg_fee <= 100_000:
                        alg_fee_by_idx[idx_d] = max(1, raw_alg_fee // 100)
                tok_in_qt_dec = _v3_tok_in_quote_dec(r_batch[si], r_batch[si + 1], qt_addr, q_dec_by_idx[idx_d])
                if tok_in_qt_dec > _DEC_ZERO:
                    v3_spot_by_idx[idx_d] = tok_in_qt_dec
                    if liq_val > 0 and r_batch[si][0] and len(r_batch[si][1]) >= 32 and r_batch[si + 1][0] and len(r_batch[si + 1][1]) >= 32:
                        sqrt_p_x96 = int.from_bytes(r_batch[si][1][:32], "big")
                        t0_addr = _norm_addr("0x" + r_batch[si + 1][1][12:32].hex())
                        if sqrt_p_x96 > 0 and t0_addr in (tok, qt_addr):
                            sp_dec = Decimal(sqrt_p_x96) / Decimal(1 << 96)
                            if sp_dec > _DEC_ZERO:
                                active_q_raw_dec = (
                                    (Decimal(liq_val) / sp_dec) if qt_addr == t0_addr else (Decimal(liq_val) * sp_dec)
                                )
                                v3_active_q_units_by_idx[idx_d] = active_q_raw_dec / (Decimal(10) ** q_dec_by_idx[idx_d])
            solidly_out_by_idx: Dict[int, int] = {}
            sol_offset = v3_offset + len(v3_indices) * 3
            for k_sl, (idx_d, _, _) in enumerate(solidly_indices):
                oi = sol_offset + k_sl
                if oi < len(r_batch) and r_batch[oi][0] and len(r_batch[oi][1]) >= 32:
                    solidly_out_by_idx[idx_d] = int.from_bytes(r_batch[oi][1][:32], "big")

            v3_quoted_out_by_idx: Dict[int, int] = {}
            if raw_amount > 0:
                v3_quoter_jobs: List[Tuple[int, Tuple[str, bytes]]] = []
                for idx_d, (_, qt_addr, _, dk, v3_fee_raw, q2_addr) in enumerate(discovered_pools):
                    if dk != "v3" or v3_fee_raw <= 0 or not q2_addr:
                        continue
                    if idx_d in v3_zero_liq or v3_spot_by_idx.get(idx_d, _DEC_ZERO) <= _DEC_ZERO:
                        continue
                    base_i = bal_offset + idx_d * 2
                    if base_i >= len(r_batch) or not (r_batch[base_i][0] and len(r_batch[base_i][1]) >= 32):
                        continue
                    q_price_pre = _quote_usd_dec(qt_addr)
                    if q_price_pre <= _DEC_ZERO:
                        continue
                    q_bal_pre = int.from_bytes(r_batch[base_i][1][:32], "big")
                    pq_pre_dec = (Decimal(q_bal_pre) / (Decimal(10) ** q_dec_by_idx[idx_d])) * q_price_pre
                    if idx_d in v3_active_q_units_by_idx:
                        pq_pre_dec = min(pq_pre_dec, v3_active_q_units_by_idx[idx_d] * q_price_pre)
                    if (pq_pre_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                        continue
                    cd_qv2 = encode_calldata(
                        QUOTER_V2_EXACT_IN_SINGLE_SEL,
                        ["address", "address", "uint256", "uint24", "uint160"],
                        [tok, qt_addr, raw_amount, v3_fee_raw, 0],
                    )
                    v3_quoter_jobs.append((idx_d, (q2_addr, bytes.fromhex(cd_qv2[2:]))))
                v3_chunks = [v3_quoter_jobs[k_c : k_c + 2] for k_c in range(0, len(v3_quoter_jobs), 2)]

                def _run_v3_quoter_chunk(chunk_jobs: List[Tuple[int, Tuple[str, bytes]]]) -> Dict[int, int]:
                    loc_q: Dict[int, int] = {}
                    try:
                        q_res = _mc3_checked([job_call for _, job_call in chunk_jobs])
                        for (idx_d, _), (ok_q, ret_q) in zip(chunk_jobs, q_res):
                            if ok_q and len(ret_q) >= 32:
                                loc_q[idx_d] = int.from_bytes(ret_q[:32], "big")
                    except _RECOVERABLE_IO_EXC:
                        _mark_dex_rpc_incomplete()
                    return loc_q

                if len(v3_chunks) >= 2 and _is_live_real_router(router):
                    v3_quoted_out_by_idx.update(
                        _parallel_map_merge_dicts(_run_v3_quoter_chunk, v3_chunks, max_workers=min(6, len(v3_chunks)), parallel=True)
                    )
                else:
                    for chunk_jobs in v3_chunks:
                        v3_quoted_out_by_idx.update(_run_v3_quoter_chunk(chunk_jobs))

            for idx_d, (pool_addr, qt_addr, fee_b, dex_k, v3_fee_raw, _) in enumerate(discovered_pools):
                if idx_d in v3_zero_liq or (dex_k in ("v3", "algebra") and v3_spot_by_idx.get(idx_d, _DEC_ZERO) <= _DEC_ZERO):
                    continue
                eff_fee_b = alg_fee_by_idx.get(idx_d, fee_b)
                base_i = bal_offset + idx_d * 2
                if base_i + 1 >= len(r_batch):
                    break
                r_qb, r_tb = r_batch[base_i], r_batch[base_i + 1]
                if not (r_qb[0] and len(r_qb[1]) >= 32):
                    continue
                q_bal = int.from_bytes(r_qb[1][:32], "big")
                q_dec = q_dec_by_idx[idx_d]
                t_bal = int.from_bytes(r_tb[1][:32], "big") if (r_tb[0] and len(r_tb[1]) >= 32) else 0
                q_price_dec = _quote_usd_dec(qt_addr)
                if q_price_dec <= _DEC_ZERO:
                    continue
                pool_quote_dec = (Decimal(q_bal) / (Decimal(10) ** q_dec)) * q_price_dec
                if idx_d in v3_active_q_units_by_idx and idx_d not in v3_quoted_out_by_idx:
                    pool_quote_dec = min(pool_quote_dec, v3_active_q_units_by_idx[idx_d] * q_price_dec)
                if (pool_quote_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                    continue
                fee_mult_dec = Decimal(max(0, 10000 - int(eff_fee_b))) / Decimal("10000")
                eff_nom_dec = nominal_usd_dec
                v3_unit_dec = v3_spot_by_idx.get(idx_d, _DEC_ZERO) * q_price_dec
                _pool_imp_u = (
                    v3_unit_dec
                    if v3_unit_dec > _DEC_ZERO
                    else (
                        (pool_quote_dec / (Decimal(t_bal) / (Decimal(10) ** dec)))
                        if t_bal > 0
                        else _DEC_ZERO
                    )
                )
                if _pool_imp_u > _DEC_ZERO and (pool_quote_dec * Decimal("2")) >= Decimal("200"):
                    _prev_c = cons_out.get(qt_addr)
                    _c_dep = pool_quote_dec * Decimal("2")
                    if _prev_c is None or _c_dep > _prev_c[0]:
                        cons_out[qt_addr] = (_c_dep, _pool_imp_u)
                if v3_unit_dec > _DEC_ZERO and nominal_units_dec > _DEC_ZERO:
                    v3_nom_dec = nominal_units_dec * v3_unit_dec
                    eff_nom_dec = min(eff_nom_dec, v3_nom_dec) if eff_nom_dec > _DEC_ZERO else v3_nom_dec
                elif eff_nom_dec <= _DEC_ZERO and t_bal > 0 and raw_amount > 0:
                    eff_nom_dec = (Decimal(raw_amount) / Decimal(t_bal)) * pool_quote_dec
                quoted_raw_amt = solidly_out_by_idx.get(idx_d) if idx_d in solidly_out_by_idx else v3_quoted_out_by_idx.get(idx_d)
                if quoted_raw_amt is not None:
                    q_out_dec = (Decimal(quoted_raw_amt) / (Decimal(10) ** q_dec)) * q_price_dec
                    cand_real_dec = min(pool_quote_dec, q_out_dec)
                    if eff_nom_dec > _DEC_ZERO:
                        cand_real_dec = min(cand_real_dec, eff_nom_dec * fee_mult_dec)
                elif v3_unit_dec > _DEC_ZERO and nominal_units_dec > _DEC_ZERO:
                    num_v3 = pool_quote_dec * eff_nom_dec * fee_mult_dec
                    den_v3 = pool_quote_dec + max(Decimal("1e-18"), eff_nom_dec * fee_mult_dec)
                    cand_real_dec = min(pool_quote_dec, num_v3 / den_v3)
                elif t_bal > 0 and raw_amount > 0:
                    rm_dec = Decimal(raw_amount) * fee_mult_dec
                    cand_real_dec = (pool_quote_dec * rm_dec) / (Decimal(t_bal) + rm_dec)
                    if eff_nom_dec > _DEC_ZERO:
                        cand_real_dec = min(cand_real_dec, eff_nom_dec * fee_mult_dec)
                elif not unbacked_supply_mint:
                    cand_real_dec = ((pool_quote_dec * eff_nom_dec) / (pool_quote_dec + max(Decimal("1e-18"), eff_nom_dec))) * fee_mult_dec
                    if eff_nom_dec > _DEC_ZERO:
                        cand_real_dec = min(cand_real_dec, eff_nom_dec * fee_mult_dec)
                else:
                    cand_real_dec = _DEC_ZERO
                routes_out.append(
                    (
                        (cand_real_dec, pool_quote_dec, max(eff_nom_dec, cand_real_dec), eff_fee_b, pool_addr, qt_addr, dex_k),
                        {"v3_fee": (int(v3_fee_raw) if dex_k == "v3" else 0), "solidly_st": (dex_k == "solidly_s")},
                    )
                )
            return routes_out, cons_out

        def _probe_v4_axis() -> List[Tuple[Tuple[Any, ...], Dict[str, Any]]]:
            routes_v4: List[Tuple[Tuple[Any, ...], Dict[str, Any]]] = []
            try:
                pm_addr = _norm_addr(v4_pms[0])
                v4_qts = list(dict.fromkeys(quote_tokens[:3]))
                if pm_addr and v4_qts:
                    v4_calls: List[Tuple[str, bytes]] = [(qt_u, bytes.fromhex(DECIMALS_SEL[2:])) for qt_u in v4_qts]
                    pm_bal_cd = bytes.fromhex(encode_calldata(BALANCE_OF_SEL, ["address"], [pm_addr])[2:])
                    for qt_u in v4_qts:
                        v4_calls.append((qt_u, pm_bal_cd))
                    v4_calls.append((tok, pm_bal_cd))
                    v4_slot_meta: List[Tuple[str, str, int, int, int]] = []
                    for qt_u in v4_qts:
                        c0_v4, c1_v4 = (tok, qt_u) if int(tok, 16) < int(qt_u, 16) else (qt_u, tok)
                        for v4_fee, v4_ts, v4_bps in _UNIV4_FEE_TICK_TIERS:
                            pid_b = _keccak256(
                                abi_encode(
                                    ["address", "address", "uint24", "int24", "address"],
                                    [c0_v4, c1_v4, v4_fee, v4_ts, ZERO_ADDRESS],
                                )
                            )
                            st_slot_i = int.from_bytes(_keccak256(pid_b + _UNIV4_POOLS_SLOT.to_bytes(32, "big")), "big")
                            lq_slot_i = (st_slot_i + _UNIV4_LIQUIDITY_OFFSET) & _UINT256_MAX
                            v4_calls.append((pm_addr, bytes.fromhex(UNIV4_EXTSLOAD_SEL[2:]) + st_slot_i.to_bytes(32, "big")))
                            v4_calls.append((pm_addr, bytes.fromhex(UNIV4_EXTSLOAD_SEL[2:]) + lq_slot_i.to_bytes(32, "big")))
                            v4_slot_meta.append((qt_u, c0_v4, v4_fee, v4_ts, v4_bps))
                    v4_res = _mc3_checked(v4_calls)
                    n_vq = len(v4_qts)
                    v4_q_dec: Dict[str, int] = {
                        qt_u: _decode_clamped_dec(v4_res[qi] if qi < len(v4_res) else (False, b""))
                        for qi, qt_u in enumerate(v4_qts)
                    }
                    v4_pm_qbal: Dict[str, int] = {
                        qt_u: (
                            int.from_bytes(v4_res[n_vq + qi][1][:32], "big")
                            if (n_vq + qi < len(v4_res) and v4_res[n_vq + qi][0] and len(v4_res[n_vq + qi][1]) >= 32)
                            else 0
                        )
                        for qi, qt_u in enumerate(v4_qts)
                    }
                    v4_pm_tbal = (
                        int.from_bytes(v4_res[n_vq * 2][1][:32], "big")
                        if (n_vq * 2 < len(v4_res) and v4_res[n_vq * 2][0] and len(v4_res[n_vq * 2][1]) >= 32)
                        else 0
                    )
                    v4_off = n_vq * 2 + 1
                    for k_v4, (qt_u, c0_v4, v4_fee, v4_ts, v4_bps) in enumerate(v4_slot_meta):
                        si_v4 = v4_off + k_v4 * 2
                        if si_v4 + 1 >= len(v4_res) or v4_pm_tbal <= 0:
                            break
                        ok_s0, b_s0 = v4_res[si_v4]
                        ok_lq, b_lq = v4_res[si_v4 + 1]
                        if not (ok_s0 and len(b_s0) >= 32 and ok_lq and len(b_lq) >= 32):
                            continue
                        sqrt_p_v4 = int.from_bytes(b_s0[:32], "big") & _ADDR_MASK_160
                        liq_v4 = int.from_bytes(b_lq[:32], "big") & ((1 << 128) - 1)
                        if sqrt_p_v4 <= 0 or liq_v4 <= 0:
                            continue
                        qp_v4 = _quote_usd_dec(qt_u)
                        if qp_v4 <= _DEC_ZERO:
                            continue
                        qd_v4 = v4_q_dec.get(qt_u, 18)
                        sp_v4 = Decimal(sqrt_p_v4) / Decimal(1 << 96)
                        if sp_v4 <= _DEC_ZERO:
                            continue
                        active_q_raw = (Decimal(liq_v4) / sp_v4) if qt_u == c0_v4 else (Decimal(liq_v4) * sp_v4)
                        pm_q_units = Decimal(v4_pm_qbal.get(qt_u, 0)) / (Decimal(10) ** qd_v4)
                        pq_v4_dec = min(active_q_raw / (Decimal(10) ** qd_v4), pm_q_units) * qp_v4
                        if (pq_v4_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                            continue
                        ratio_v4 = sp_v4 * sp_v4
                        tok_in_q_v4 = (ratio_v4 if c0_v4 == tok else (Decimal("1") / ratio_v4)) * (Decimal(10) ** (dec - qd_v4))
                        v4_unit_dec = tok_in_q_v4 * qp_v4
                        if v4_unit_dec <= _DEC_ZERO:
                            continue
                        v4_fee_mult = Decimal(max(0, 10000 - v4_bps)) / Decimal("10000")
                        v4_nom = nominal_units_dec * v4_unit_dec
                        eff_v4_nom = min(nominal_usd_dec, v4_nom) if nominal_usd_dec > _DEC_ZERO else v4_nom
                        cand_v4_dec = min(
                            pq_v4_dec,
                            (pq_v4_dec * eff_v4_nom * v4_fee_mult) / (pq_v4_dec + max(Decimal("1e-18"), eff_v4_nom * v4_fee_mult)),
                        )
                        routes_v4.append(
                            (
                                (cand_v4_dec, pq_v4_dec, max(eff_v4_nom, cand_v4_dec), v4_bps, pm_addr, qt_u, "v4"),
                                {"v3_fee": v4_fee, "v4_ts": v4_ts},
                            )
                        )
            except _RECOVERABLE_IO_EXC:
                _mark_dex_rpc_incomplete()
            return routes_v4

        def _probe_bal3_axis() -> List[Tuple[Tuple[Any, ...], Dict[str, Any]]]:
            routes_b3: List[Tuple[Tuple[Any, ...], Dict[str, Any]]] = []
            try:
                b3_pools = _fetch_balancer_v3_pools_cached(router, c, block_pin)
                b3_ax_tls = getattr(router, "_tls", None)
                if b3_ax_tls is not None and bool(getattr(b3_ax_tls, "last_multicall_transport_failed", False)):
                    _mark_dex_rpc_incomplete()
                qt_set_b3 = set(quote_tokens)
                matched_b3: List[Tuple[str, str, int, int, int]] = []
                for b3_pa, b3_toks, b3_bals, b3_fee in b3_pools:
                    if tok not in b3_toks:
                        continue
                    t_idx_b3 = b3_toks.index(tok)
                    t_bal_b3 = b3_bals[t_idx_b3]
                    if t_bal_b3 <= 0:
                        continue
                    for q_idx_b3, q_cand_b3 in enumerate(b3_toks):
                        if q_cand_b3 in qt_set_b3 and q_cand_b3 != tok and b3_bals[q_idx_b3] > 0:
                            matched_b3.append((b3_pa, q_cand_b3, t_bal_b3, b3_bals[q_idx_b3], b3_fee))
                if matched_b3:
                    b3_qts_u = list(dict.fromkeys(m[1] for m in matched_b3))
                    b3_dec_res = _mc3_checked([(q_u, bytes.fromhex(DECIMALS_SEL[2:])) for q_u in b3_qts_u])
                    b3_q_dec = {
                        q_u: _decode_clamped_dec(b3_dec_res[qi] if qi < len(b3_dec_res) else (False, b""))
                        for qi, q_u in enumerate(b3_qts_u)
                    }
                    for b3_pa, q_b3, t_bal_b3, q_bal_b3, b3_fee in matched_b3:
                        qp_b3 = _quote_usd_dec(q_b3)
                        if qp_b3 <= _DEC_ZERO:
                            continue
                        qd_b3 = b3_q_dec.get(q_b3, 18)
                        pq_b3_dec = (Decimal(q_bal_b3) / (Decimal(10) ** qd_b3)) * qp_b3
                        if (pq_b3_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                            continue
                        b3_fee_mult = Decimal(max(0, 10000 - b3_fee)) / Decimal("10000")
                        rm_b3 = Decimal(raw_amount) * b3_fee_mult
                        cand_b3_dec = min(pq_b3_dec, (pq_b3_dec * rm_b3) / (Decimal(t_bal_b3) + rm_b3))
                        eff_b3_nom = nominal_usd_dec if nominal_usd_dec > _DEC_ZERO else ((Decimal(raw_amount) / Decimal(t_bal_b3)) * pq_b3_dec)
                        if eff_b3_nom > _DEC_ZERO:
                            cand_b3_dec = min(cand_b3_dec, eff_b3_nom * b3_fee_mult)
                        routes_b3.append(
                            (
                                (cand_b3_dec, pq_b3_dec, max(eff_b3_nom, cand_b3_dec), b3_fee, b3_pa, q_b3, "balancer_v3"),
                                {},
                            )
                        )
            except _RECOVERABLE_IO_EXC:
                _mark_dex_rpc_incomplete()
            return routes_b3

        def _probe_curve_axis() -> List[Tuple[Tuple[Any, ...], Dict[str, Any]]]:
            routes_crv: List[Tuple[Tuple[Any, ...], Dict[str, Any]]] = []
            try:
                crv_reg = CURVE_ETH_METAREGISTRY if c == "ethereum" else ""
                if not crv_reg:
                    cd_ga = encode_calldata(CURVE_GET_ADDRESS_SEL, ["uint256"], [7])
                    ga_res = _mc3_checked([(CURVE_ADDRESS_PROVIDER, bytes.fromhex(cd_ga[2:]))])
                    if ga_res and ga_res[0][0] and len(ga_res[0][1]) >= 32:
                        cand_reg = _norm_addr("0x" + ga_res[0][1][12:32].hex())
                        if _is_non_precompile_addr(cand_reg):
                            crv_reg = cand_reg
                if crv_reg:
                    crv_find_calls: List[Tuple[str, bytes]] = []
                    crv_find_qts: List[str] = []
                    for qt in quote_tokens:
                        for p_idx in (0, 1):
                            cd_fp = encode_calldata(CURVE_FIND_POOL_SEL, ["address", "address", "uint256"], [tok, qt, p_idx])
                            crv_find_calls.append((crv_reg, bytes.fromhex(cd_fp[2:])))
                            crv_find_qts.append(qt)
                    crv_fp_res = _mc3_checked(crv_find_calls)
                    crv_pools: List[Tuple[str, str]] = []
                    crv_seen: Set[str] = set()
                    for qt, (ok_fp, ret_fp) in zip(crv_find_qts, crv_fp_res):
                        if not ok_fp or len(ret_fp) < 32:
                            continue
                        c_pool = _norm_addr("0x" + ret_fp[12:32].hex())
                        if c_pool and int(c_pool, 16) != 0 and c_pool not in crv_seen:
                            crv_seen.add(c_pool)
                            crv_pools.append((c_pool, qt))
                    if crv_pools:
                        crv_uniq_qts: List[str] = list(dict.fromkeys(qt for _, qt in crv_pools))
                        crv_info_calls: List[Tuple[str, bytes]] = [
                            (qt_u, bytes.fromhex(DECIMALS_SEL[2:])) for qt_u in crv_uniq_qts
                        ]
                        for c_pool, qt in crv_pools:
                            cd_idx = encode_calldata(CURVE_GET_COIN_INDICES_SEL, ["address", "address", "address"], [c_pool, tok, qt])
                            cd_bal = encode_calldata(CURVE_GET_BALANCES_SEL, ["address"], [c_pool])
                            cd_ubal = encode_calldata(CURVE_GET_UNDERLYING_BALANCES_SEL, ["address"], [c_pool])
                            crv_info_calls.append((crv_reg, bytes.fromhex(cd_idx[2:])))
                            crv_info_calls.append((crv_reg, bytes.fromhex(cd_bal[2:])))
                            crv_info_calls.append((crv_reg, bytes.fromhex(cd_ubal[2:])))
                            crv_info_calls.append((c_pool, bytes.fromhex(CURVE_FEE_SEL[2:])))
                        crv_info_res = _mc3_checked(crv_info_calls)
                        crv_q_dec_map: Dict[str, int] = {
                            qt_u: _decode_clamped_dec(crv_info_res[i_cq] if i_cq < len(crv_info_res) else (False, b""))
                            for i_cq, qt_u in enumerate(crv_uniq_qts)
                        }
                        crv_base_off = len(crv_uniq_qts)
                        crv_dy_jobs: List[Tuple[str, str, Decimal, int, int, int, bool, int, Tuple[str, bytes], Tuple[str, bytes]]] = []
                        for k_cp, (c_pool, qt) in enumerate(crv_pools):
                            bi = crv_base_off + k_cp * 4
                            if bi + 3 >= len(crv_info_res):
                                break
                            ok_ci, ret_ci = crv_info_res[bi]
                            if not ok_ci or len(ret_ci) < 96:
                                continue
                            ci = int.from_bytes(ret_ci[:32], "big", signed=True)
                            cj = int.from_bytes(ret_ci[32:64], "big", signed=True)
                            is_und = int.from_bytes(ret_ci[64:96], "big") != 0
                            if not (0 <= ci < 8 and 0 <= cj < 8 and ci != cj):
                                continue
                            q_dec_c = crv_q_dec_map.get(qt, 18)
                            q_price_c = _quote_usd_dec(qt)
                            if q_price_c <= _DEC_ZERO:
                                continue
                            bal_row = crv_info_res[bi + (2 if is_und else 1)]
                            if not bal_row[0] or len(bal_row[1]) < 256:
                                continue
                            q_bal_c = int.from_bytes(bal_row[1][cj * 32 : (cj + 1) * 32], "big")
                            if q_bal_c <= 0:
                                continue
                            pq_crv_dec = (Decimal(q_bal_c) / (Decimal(10) ** q_dec_c)) * q_price_c
                            if (pq_crv_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                                continue
                            crv_fee_bps = 4
                            ok_cf, ret_cf = crv_info_res[bi + 3]
                            if ok_cf and len(ret_cf) >= 32:
                                raw_crv_fee = int.from_bytes(ret_cf[:32], "big")
                                if 0 < raw_crv_fee <= 5_000_000_000:
                                    crv_fee_bps = max(1, (raw_crv_fee + 999_999) // 1_000_000)
                            dy_sel = CURVE_GET_DY_UNDERLYING_SEL if is_und else CURVE_GET_DY_SEL
                            dy_sel_v2 = CURVE_V2_GET_DY_UNDERLYING_SEL if is_und else CURVE_V2_GET_DY_SEL
                            cd_dy = encode_calldata(dy_sel, ["int128", "int128", "uint256"], [ci, cj, raw_amount])
                            cd_dy_v2 = encode_calldata(dy_sel_v2, ["uint256", "uint256", "uint256"], [ci, cj, raw_amount])
                            crv_dy_jobs.append(
                                (
                                    c_pool,
                                    qt,
                                    pq_crv_dec,
                                    q_dec_c,
                                    ci,
                                    cj,
                                    is_und,
                                    crv_fee_bps,
                                    (c_pool, bytes.fromhex(cd_dy[2:])),
                                    (c_pool, bytes.fromhex(cd_dy_v2[2:])),
                                )
                            )
                        if crv_dy_jobs:
                            crv_dy_flat: List[Tuple[str, bytes]] = []
                            for *_, j_c1, j_c2 in crv_dy_jobs:
                                crv_dy_flat.append(j_c1)
                                crv_dy_flat.append(j_c2)
                            crv_dy_res = _mc3_checked(crv_dy_flat)
                            for idx_cdy, (c_pool, qt, pq_crv_dec, q_dec_c, ci_c, cj_c, is_und_c, crv_fee_b, _, _) in enumerate(
                                crv_dy_jobs
                            ):
                                dy_raw = 0
                                for res_slot in (idx_cdy * 2, idx_cdy * 2 + 1):
                                    if res_slot < len(crv_dy_res):
                                        ok_dy, ret_dy = crv_dy_res[res_slot]
                                        if ok_dy and len(ret_dy) >= 32:
                                            cand_dy = int.from_bytes(ret_dy[:32], "big")
                                            if cand_dy > 0:
                                                dy_raw = cand_dy
                                                break
                                if dy_raw <= 0:
                                    continue
                                crv_fee_mult_dec = Decimal(max(0, 10000 - int(crv_fee_b))) / Decimal("10000")
                                q_price_c = _quote_usd_dec(qt)
                                cand_crv_dec = min(pq_crv_dec, (Decimal(dy_raw) / (Decimal(10) ** q_dec_c)) * q_price_c)
                                if nominal_usd_dec > _DEC_ZERO:
                                    cand_crv_dec = min(cand_crv_dec, nominal_usd_dec * crv_fee_mult_dec)
                                cand_crv_nom = (
                                    max(nominal_usd_dec, cand_crv_dec)
                                    if nominal_usd_dec > _DEC_ZERO
                                    else (
                                        (cand_crv_dec / crv_fee_mult_dec)
                                        if crv_fee_mult_dec > _DEC_ZERO
                                        else cand_crv_dec
                                    )
                                )
                                routes_crv.append(
                                    (
                                        (cand_crv_dec, pq_crv_dec, cand_crv_nom, int(crv_fee_b), c_pool, qt, "curve"),
                                        {"curve_i": int(ci_c), "curve_j": int(cj_c), "curve_und": bool(is_und_c)},
                                    )
                                )
            except _RECOVERABLE_IO_EXC:
                _mark_dex_rpc_incomplete()
            return routes_crv

        is_live_dex = _is_live_real_router(router)
        consensus_by_quote: Dict[str, Tuple[Decimal, Decimal]] = {}
        eager_deep_axes = (c == "ethereum") or (not has_v23_factories)
        wave1_jobs: List[Tuple[str, Callable[[], Any]]] = []
        if has_v23_factories:
            wave1_jobs.append(("v23", _probe_v23_axis))
        if has_v4_axis:
            wave1_jobs.append(("v4", _probe_v4_axis))
        if eager_deep_axes and has_bal3_axis:
            wave1_jobs.append(("bal3", _probe_bal3_axis))
        if eager_deep_axes and has_curve_axis:
            wave1_jobs.append(("curve", _probe_curve_axis))

        def _run_axis_wave(jobs: Sequence[Tuple[str, Callable[[], Any]]]) -> Dict[str, Any]:
            if len(jobs) >= 2 and is_live_dex:
                with concurrent.futures.ThreadPoolExecutor(max_workers=min(4, len(jobs))) as ex_dx:
                    futs_dx = [(k_j, ex_dx.submit(fn_j)) for k_j, fn_j in jobs]
                    return {k_j: f_j.result() for k_j, f_j in futs_dx}
            return {k_j: fn_j() for k_j, fn_j in jobs}

        w1_res = _run_axis_wave(wave1_jobs)
        if "v23" in w1_res:
            v23_routes, consensus_by_quote = w1_res["v23"]
            for r_args, r_kw in v23_routes:
                _consider_best_exit_route(*r_args, **r_kw)
        for ax_k in ("v4", "bal3", "curve"):
            if ax_k in w1_res:
                for r_args, r_kw in w1_res[ax_k]:
                    _consider_best_exit_route(*r_args, **r_kw)

        if not eager_deep_axes and (best_pq_dec * Decimal("2")) < Decimal("50000"):
            wave2_jobs: List[Tuple[str, Callable[[], Any]]] = []
            if has_bal3_axis:
                wave2_jobs.append(("bal3", _probe_bal3_axis))
            if has_curve_axis:
                wave2_jobs.append(("curve", _probe_curve_axis))
            if wave2_jobs:
                w2_res = _run_axis_wave(wave2_jobs)
                for ax_k in ("bal3", "curve"):
                    if ax_k in w2_res:
                        for r_args, r_kw in w2_res[ax_k]:
                            _consider_best_exit_route(*r_args, **r_kw)

        if (best_pq_dec * Decimal("2")) >= PROFIT_FLOOR_DEC and best_pool_addr:
                realizable_dec = best_realizable_dec
                slip_bps = min(
                    9900,
                    max(
                        best_fee_bps,
                        int((Decimal("1") - (realizable_dec / max(Decimal("1e-18"), best_out_nom_dec))) * Decimal("10000")),
                    ),
                )
                depth_pool_dec = best_pq_dec * Decimal("2")
                cons_cnt = 0
                cons_depth_dec = _DEC_ZERO
                cons_unit_dec = _DEC_ZERO
                _cbq_items = sorted(
                    consensus_by_quote.values(),
                    key=lambda x: x[1],
                )
                if len(_cbq_items) >= 3:
                    best_cluster: List[Tuple[Decimal, Decimal]] = []
                    for _ci in range(len(_cbq_items)):
                        _lo_p = _cbq_items[_ci][1]
                        _cl = [
                            it for it in _cbq_items[_ci:]
                            if it[1] > _DEC_ZERO and (it[1] - _lo_p) / it[1] <= Decimal("0.03")
                        ]
                        if len(_cl) > len(best_cluster) or (
                            len(_cl) == len(best_cluster)
                            and sum((x[0] for x in _cl), _DEC_ZERO) > sum((x[0] for x in best_cluster), _DEC_ZERO)
                        ):
                            best_cluster = _cl
                    if len(best_cluster) >= 3:
                        cons_cnt = len(best_cluster)
                        cons_depth_dec = sum((x[0] for x in best_cluster), _DEC_ZERO)
                        if cons_depth_dec > _DEC_ZERO:
                            cons_unit_dec = (
                                sum((x[0] * x[1] for x in best_cluster), _DEC_ZERO) / cons_depth_dec
                            )
                return {
                    "exit_liquid": realizable_dec > _DEC_ZERO,
                    "realizable_usd": realizable_dec,
                    "realizable_usd_dec": format(realizable_dec, "f"),
                    "nominal_usd": best_out_nom_dec,
                    "nominal_usd_dec": format(best_out_nom_dec, "f"),
                    "swap_fee_bps": best_fee_bps,
                    "slippage_bps": slip_bps,
                    "dex_depth_usd": depth_pool_dec,
                    "dex_depth_usd_dec": format(depth_pool_dec, "f"),
                    "consensus_pools_count": cons_cnt,
                    "consensus_depth_usd_dec": format(cons_depth_dec, "f"),
                    "consensus_unit_price_dec": format(cons_unit_dec, "f"),
                    "best_pool_address": _checksum(best_pool_addr),
                    "best_quote_token": _checksum(best_quote_addr),
                    "best_dex_kind": best_dex_kind,
                    "v3_fee": best_v3_fee,
                    "v4_tick_spacing": best_v4_tick_spacing,
                    "curve_i": best_curve_i,
                    "curve_j": best_curve_j,
                    "curve_underlying": best_curve_underlying,
                    "solidly_stable": best_solidly_stable,
                    "rpc_incomplete": bool(dex_rpc_incomplete[0]),
                }

    # 직접 DEX 풀이 부재하거나 심도 미달인 영수증·파생 예치 토큰(ERC-4626 / Aave aToken / Compound cToken)의 온체인 즉시 상환 준비금 실측
    if block_pin > 0 and not unbacked_supply_mint and raw_amount > 0 and _redeem_depth < 1:
        try:
            clamped_in = min(int(raw_amount), (1 << 256) - 1)
            wrap_probe_calls: List[Tuple[str, bytes]] = [
                (tok, bytes.fromhex(ERC4626_ASSET_SEL[2:])),
                (tok, bytes.fromhex(ERC4626_CONVERT_TO_ASSETS_SEL[2:]) + clamped_in.to_bytes(32, "big")),
                (tok, bytes.fromhex(AAVE_UNDERLYING_SEL[2:])),
                (tok, bytes.fromhex(AAVE_POOL_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_UNDERLYING_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_EXCHANGE_RATE_STORED_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_GET_CASH_SEL[2:])),
                (tok, bytes.fromhex(ERC4626_PREVIEW_REDEEM_SEL[2:]) + clamped_in.to_bytes(32, "big")),
                (tok, bytes.fromhex(PAUSED_SEL[2:])),
            ]
            w_res = _mc3_checked(wrap_probe_calls)
            tok_wrap_paused = (
                len(w_res) >= 9
                and w_res[8][0]
                and len(w_res[8][1]) >= 32
                and int.from_bytes(w_res[8][1][:32], "big") != 0
            )
            if len(w_res) >= 7 and not tok_wrap_paused:
                def _res_addr(idx_w: int) -> str:
                    ok_w, b_w = w_res[idx_w]
                    if not ok_w or len(b_w) < 32 or any(b_w[:12]):
                        return ""
                    ca_w = _norm_addr("0x" + b_w[12:32].hex())
                    return ca_w if (_is_non_precompile_addr(ca_w) and ca_w != tok) else ""

                def _res_uint(idx_w: int) -> int:
                    ok_w, b_w = w_res[idx_w]
                    return int.from_bytes(b_w[:32], "big") if (ok_w and len(b_w) >= 32) else 0

                w_kind = ""
                u_addr = ""
                u_converted_raw = 0
                aave_pool_addr = ""
                comp_cash_raw = 0
                u_4626 = _res_addr(0)
                conv_4626 = _res_uint(1)
                prev_4626_ok = len(w_res) >= 8 and w_res[7][0] and len(w_res[7][1]) >= 32
                prev_4626 = int.from_bytes(w_res[7][1][:32], "big") if prev_4626_ok else 0
                u_aave = _res_addr(2)
                u_comp = _res_addr(4)
                ex_comp = _res_uint(5)
                cash_comp = _res_uint(6)
                if u_4626 and conv_4626 > 0:
                    eff_4626 = min(conv_4626, prev_4626) if prev_4626_ok else conv_4626
                    if eff_4626 > 0:
                        w_kind = "erc4626"
                        u_addr = u_4626
                        u_converted_raw = eff_4626
                elif u_aave:
                    w_kind = "atoken"
                    u_addr = u_aave
                    u_converted_raw = int(raw_amount)
                    aave_pool_addr = _res_addr(3)
                elif u_comp and ex_comp > 0 and cash_comp > 0:
                    w_kind = "ctoken"
                    u_addr = u_comp
                    u_converted_raw = (int(raw_amount) * ex_comp) // (10 ** 18)
                    comp_cash_raw = cash_comp

                if w_kind and u_addr and u_converted_raw > 0:
                    tok_pad32 = abi_encode(["address"], [tok])
                    u_pad32 = abi_encode(["address"], [u_addr])
                    u_v_calls: List[Tuple[str, bytes]] = [
                        (u_addr, bytes.fromhex(PAUSED_SEL[2:])),
                        (u_addr, bytes.fromhex(DECIMALS_SEL[2:])),
                        (u_addr, bytes.fromhex(BALANCE_OF_SEL[2:]) + tok_pad32),
                    ]
                    if w_kind == "atoken" and aave_pool_addr and aave_pool_addr not in (tok, u_addr):
                        u_v_calls.append((u_addr, bytes.fromhex(BALANCE_OF_SEL[2:]) + abi_encode(["address"], [aave_pool_addr])))
                        u_v_calls.append((aave_pool_addr, bytes.fromhex(_selector("getReserveData(address)")[2:]) + u_pad32))
                        u_v_calls.append((aave_pool_addr, bytes.fromhex(_selector("getReserveAToken(address)")[2:]) + u_pad32))
                    u_v_res = _mc3_checked(u_v_calls)
                    u_paused = len(u_v_res) >= 1 and u_v_res[0][0] and len(u_v_res[0][1]) >= 32 and int.from_bytes(u_v_res[0][1][:32], "big") != 0
                    if not u_paused and len(u_v_res) >= 3:
                        u_dec = _decode_clamped_dec(u_v_res[1], 18)
                        u_bal_tok = int.from_bytes(u_v_res[2][1][:32], "big") if (u_v_res[2][0] and len(u_v_res[2][1]) >= 32) else 0
                        u_bal_pool = (
                            int.from_bytes(u_v_res[3][1][:32], "big")
                            if (len(u_v_res) >= 4 and u_v_res[3][0] and len(u_v_res[3][1]) >= 32)
                            else 0
                        )
                        if w_kind == "erc4626":
                            avail_u_raw = u_bal_tok
                        elif w_kind == "atoken":
                            if u_bal_tok > 0:
                                avail_u_raw = u_bal_tok
                            elif u_bal_pool > 0:
                                pool_atoken_ok = False
                                if len(u_v_res) >= 5 and u_v_res[4][0] and len(u_v_res[4][1]) >= 256:
                                    rd_b = u_v_res[4][1]
                                    for w_off in (224, 256):
                                        if len(rd_b) >= w_off + 32 and rd_b[w_off : w_off + 32] == tok_pad32:
                                            pool_atoken_ok = True
                                            break
                                if not pool_atoken_ok and len(u_v_res) >= 6 and u_v_res[5][0] and len(u_v_res[5][1]) >= 32:
                                    if u_v_res[5][1][:32] == tok_pad32:
                                        pool_atoken_ok = True
                                avail_u_raw = u_bal_pool if pool_atoken_ok else 0
                            else:
                                avail_u_raw = 0
                        else:
                            avail_u_raw = min(comp_cash_raw, u_bal_tok) if u_bal_tok > 0 else 0
                        redeem_raw = min(u_converted_raw, avail_u_raw)
                        if redeem_raw > 0 and avail_u_raw > 0:
                            u_p_dec = _quote_usd_dec(u_addr)
                            u_liq = probe_dex_exit_liquidity(
                                router,
                                c,
                                u_addr,
                                redeem_raw,
                                u_dec,
                                u_p_dec,
                                nat_usd_dec,
                                block_pin,
                                quote_prices_usd=q_price_cache,
                                unbacked_supply_mint=False,
                                _redeem_depth=_redeem_depth + 1,
                            )
                            u_real_dec = _to_dec(u_liq.get("realizable_usd_dec") or u_liq.get("realizable_usd") or 0)
                            u_depth_dec = _to_dec(u_liq.get("dex_depth_usd_dec") or u_liq.get("dex_depth_usd") or 0)
                            redeem_units_dec = Decimal(redeem_raw) / (Decimal(10) ** u_dec)
                            avail_units_dec = Decimal(avail_u_raw) / (Decimal(10) ** u_dec)
                            eff_u_unit_dec = u_p_dec if u_p_dec > _DEC_ZERO else (
                                (u_real_dec / redeem_units_dec) if redeem_units_dec > _DEC_ZERO else _DEC_ZERO
                            )
                            reserve_depth_dec = avail_units_dec * eff_u_unit_dec
                            eff_depth_dec = min(u_depth_dec, reserve_depth_dec) if u_depth_dec > _DEC_ZERO else reserve_depth_dec
                            if u_liq.get("exit_liquid") and u_real_dec > _DEC_ZERO and eff_depth_dec >= PROFIT_FLOOR_DEC:
                                out_redeem = dict(u_liq)
                                out_redeem["dex_depth_usd"] = eff_depth_dec
                                out_redeem["dex_depth_usd_dec"] = format(eff_depth_dec, "f")
                                out_redeem["best_pool_address"] = _checksum(tok)
                                out_redeem["best_quote_token"] = _checksum(u_addr)
                                out_redeem["best_dex_kind"] = f"redeem_{w_kind}"
                                out_redeem["redeem_target"] = (
                                    _checksum(aave_pool_addr)
                                    if (w_kind == "atoken" and aave_pool_addr)
                                    else ("" if w_kind == "atoken" else _checksum(tok))
                                )
                                if u_liq.get("best_pool_address") and u_liq.get("best_quote_token"):
                                    out_redeem["underlying_exit"] = {
                                        "pool": str(u_liq.get("best_pool_address") or ""),
                                        "quote_token": str(u_liq.get("best_quote_token") or ""),
                                        "dex_kind": str(u_liq.get("best_dex_kind") or ""),
                                        "v3_fee": int(u_liq.get("v3_fee") or 0),
                                        "v4_tick_spacing": int(u_liq.get("v4_tick_spacing") or 0),
                                        "curve_i": int(u_liq.get("curve_i") or 0),
                                        "curve_j": int(u_liq.get("curve_j") or 0),
                                        "curve_underlying": bool(u_liq.get("curve_underlying")),
                                        "solidly_stable": bool(u_liq.get("solidly_stable")),
                                    }
                                out_redeem["v3_fee"] = 0
                                out_redeem["curve_i"] = 0
                                out_redeem["curve_j"] = 0
                                out_redeem["curve_underlying"] = False
                                out_redeem["solidly_stable"] = False
                                out_redeem["rpc_incomplete"] = bool(dex_rpc_incomplete[0] or u_liq.get("rpc_incomplete"))
                                return out_redeem
        except _RECOVERABLE_IO_EXC:
            _mark_dex_rpc_incomplete()

    # 온체인 블록이 고정된 상태(block_pin > 0) 또는 무담보 공급 증가분에서 DEX 풀이 전무한 토큰에 가공 유동성을 부여하지 않음
    if block_pin > 0 or unbacked_supply_mint or total_supply <= 0 or eff_unit_price_dec <= _DEC_ZERO or nominal_usd_dec < PROFIT_FLOOR_DEC:
        return _illiquid_dex_out()
    supply_share_dec = min(Decimal("1"), Decimal(raw_amount) / Decimal(max(1, total_supply)))
    if supply_share_dec > Decimal("0.25"):
        return _illiquid_dex_out()
    slip_bps = min(5000, max(50, int(supply_share_dec * Decimal("10000"))))
    realizable_fb_dec = nominal_usd_dec * (Decimal(max(0, 10000 - (30 + slip_bps))) / Decimal("10000"))
    return {
        "exit_liquid": realizable_fb_dec >= PROFIT_FLOOR_DEC,
        "realizable_usd": realizable_fb_dec,
        "realizable_usd_dec": format(realizable_fb_dec, "f"),
        "nominal_usd": nominal_usd_dec,
        "nominal_usd_dec": format(nominal_usd_dec, "f"),
        "swap_fee_bps": 30,
        "slippage_bps": slip_bps,
        "dex_depth_usd": nominal_usd_dec,
        "dex_depth_usd_dec": format(nominal_usd_dec, "f"),
    }


_FLASH_PROVIDER_RANK: Dict[str, int] = {
    "morpho_blue": 0,
    "balancer_v2": 1,
    "balancer_v3": 2,
    "uniswap_v4": 3,
    "erc3156": 4,
    "aave_v3": 5,
    "dex_flash_v3": 6,
    "dex_flash_algebra": 7,
    "dex_flash_solidly_s": 8,
    "dex_flash_v2": 9,
    "dex_flash_solidly_v": 10,
}
_STAGE4_FLASH_MODE: Dict[str, int] = {
    "balancer_v2": 1,
    "morpho_blue": 2,
    "aave_v3": 3,
    "erc3156": 4,
    "uniswap_v4": 5,
    "balancer_v3": 6,
    "dex_flash_v3": 7,
    "dex_flash_algebra": 7,
    "dex_flash_v2": 8,
}
_STAGE4_FLASH_MODES: FrozenSet[int] = frozenset(_STAGE4_FLASH_MODE.values())


def optimize_flash_split_for_capital(
    candidates: Sequence[Mapping[str, Any]],
    required_raw: int,
) -> Dict[str, Any]:
    """
    다중 출처 분할 차입 최적화기: 단일 공급자 상한 초과 시
    수수료 최하·상한 최대 순서로 탐욕 분할해 최소 총 수수료를 산출한다(정수 연산 전용, `float` 0건).
    반환: `{sufficient, total_borrowable_raw, total_fee_raw, total_fee_bps, plan}`.
    `plan` 각 원소는 `{provider, vault, amount_raw(str), fee_bps, fee_raw(str)}`이다.
    """
    req = max(0, int(required_raw or 0))
    avail: List[Dict[str, Any]] = []
    for cand in candidates or ():
        if not isinstance(cand, Mapping):
            continue
        try:
            cap = int(cand.get("max_borrowable_raw") or 0)
        except (TypeError, ValueError):
            cap = 0
        if cap <= 0:
            continue
        try:
            fee_bps = int(cand.get("fee_bps") or 0)
        except (TypeError, ValueError):
            fee_bps = 0
        avail.append(
            {
                "provider": str(cand.get("provider") or ""),
                "vault": _checksum(str(cand.get("vault") or "")) if _norm_addr(str(cand.get("vault") or "")) else str(cand.get("vault") or ""),
                "cap": cap,
                "fee_bps": max(0, fee_bps),
            }
        )
    avail.sort(key=lambda c: (int(c["fee_bps"]), _FLASH_PROVIDER_RANK.get(str(c["provider"]), 99), -int(c["cap"]), str(c["vault"])))
    total_cap = sum(int(c["cap"]) for c in avail)
    plan: List[Dict[str, Any]] = []
    total_fee_raw = 0
    remaining = req
    if req <= 0:
        return {
            "sufficient": True,
            "total_borrowable_raw": str(total_cap),
            "total_fee_raw": "0",
            "total_fee_bps": 0,
            "plan": [],
        }
    for cand in avail:
        if remaining <= 0:
            break
        take = min(int(cand["cap"]), remaining)
        fee_raw = (take * int(cand["fee_bps"]) + 9999) // 10000
        total_fee_raw += fee_raw
        plan.append(
            {
                "provider": str(cand["provider"]),
                "vault": str(cand["vault"]),
                "amount_raw": str(take),
                "fee_bps": int(cand["fee_bps"]),
                "fee_raw": str(fee_raw),
            }
        )
        remaining -= take
    sufficient = remaining <= 0
    total_fee_bps = int((total_fee_raw * 10000) // req) if (sufficient and req > 0) else 0
    return {
        "sufficient": sufficient,
        "total_borrowable_raw": str(total_cap),
        "total_fee_raw": str(total_fee_raw),
        "total_fee_bps": total_fee_bps,
        "plan": plan,
    }


def _decode_abi_u256_word(raw_b: bytes, word_idx: int = 0) -> int:
    off = word_idx * 32
    if len(raw_b) < off + 32:
        return 0
    return int.from_bytes(raw_b[off : off + 32], "big")


def _decode_abi_addr_word(raw_b: bytes, word_idx: int = 0) -> str:
    off = word_idx * 32
    if len(raw_b) < off + 32:
        return ""
    word = raw_b[off : off + 32]
    if word[:12] != b"\x00" * 12:
        return ""
    addr_hex = "0x" + word[12:].hex()
    return addr_hex if addr_hex != "0x0000000000000000000000000000000000000000" else ""


@_with_decimal_prec_100
def discover_optimal_flash_sources_for_tokens(
    router: Optional[RPCRouter],
    chain: str,
    block_pin: int,
    token_addrs: Sequence[str],
    *,
    candidate_vaults: Sequence[str] = (),
    exit_routes: Optional[Mapping[str, Any]] = None,
    decimals_map: Optional[Mapping[str, int]] = None,
    prices_map: Optional[Mapping[str, Union[Decimal, int, str]]] = None,
    token_symbols: Optional[Mapping[str, str]] = None,
) -> Dict[str, Any]:
    """
    필요한 코인(`token_addrs` + 체인 기준 자산)별 플래시론 공급자·실제 블록 유동성·실측 수수료(bps)를
    단일 배치 `multicall3`로 온체인 동적 실측해 최적 공급자를 정렬하고,
    온체인 유동성 미충족 토큰·미등록 체인 여부에 따라 에이전트 동적 웹검색 필요 플래그를 산출한다.
    """
    c = _norm_chain(chain)
    alias_excl = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset()) | {
        "0x0000000000000000000000000000000000000000"
    }
    target_tokens: List[str] = []
    seen_tt: Set[str] = set()
    for raw_t in token_addrs:
        nt = _norm_addr(raw_t)
        if nt and nt not in alias_excl and nt not in seen_tt and _append_bounded_unique(target_tokens, seen_tt, nt, 6):
            break

    probe_tokens: List[str] = list(target_tokens)
    seen_pt: Set[str] = set(target_tokens)
    for bench_raw in [WRAPPED_NATIVE_BY_CHAIN.get(c, ""), *CHAIN_STABLES.get(c, ())[:3]]:
        nb = _norm_addr(bench_raw)
        if nb and nb not in alias_excl and nb not in seen_pt and len(probe_tokens) < 6:
            seen_pt.add(nb)
            probe_tokens.append(nb)

    base_providers: List[Dict[str, Any]] = []
    seen_vp: Set[Tuple[str, str]] = set()
    for fp in FLASH_PROVIDERS.get(c, ()):
        if not isinstance(fp, dict):
            continue
        pv = str(fp.get("provider") or "").strip().lower()
        vn = _norm_addr(fp.get("vault") or "")
        if pv and vn and (pv, vn) not in seen_vp:
            seen_vp.add((pv, vn))
            base_providers.append(
                {
                    "provider": pv,
                    "vault": _checksum(vn),
                    "vault_norm": vn,
                    "fee_bps": int(fp.get("fee_bps") or 0),
                    "configured_for_chain": True,
                }
            )
    for u_pv, u_addr in (
        ("morpho_blue", MORPHO_BLUE_MAINNET),
        ("balancer_v2", BALANCER_V2_VAULT),
        ("balancer_v3", BALANCER_V3_VAULT),
    ):
        vn = _norm_addr(u_addr)
        if vn and (u_pv, vn) not in seen_vp:
            seen_vp.add((u_pv, vn))
            base_providers.append(
                {
                    "provider": u_pv,
                    "vault": _checksum(vn),
                    "vault_norm": vn,
                    "fee_bps": 0,
                    "configured_for_chain": (c in FLASH_PROVIDERS),
                }
            )
    for v4_mgr in UNISWAP_V4_POOL_MANAGERS.get(c, ()):
        vn_v4 = _norm_addr(v4_mgr)
        if vn_v4 and ("uniswap_v4", vn_v4) not in seen_vp:
            seen_vp.add(("uniswap_v4", vn_v4))
            base_providers.append(
                {
                    "provider": "uniswap_v4",
                    "vault": _checksum(vn_v4),
                    "vault_norm": vn_v4,
                    "fee_bps": 0,
                    "configured_for_chain": False,
                }
            )

    dex_venues_by_tok: Dict[str, List[Dict[str, Any]]] = {}
    if isinstance(exit_routes, Mapping):
        for raw_tk, ent in exit_routes.items():
            if not isinstance(ent, dict) or bool(ent.get("paused")):
                continue
            tk_n = _norm_addr(raw_tk)
            if not tk_n or tk_n in alias_excl:
                continue
            for step_ent in (ent, ent.get("underlying_exit") if isinstance(ent.get("underlying_exit"), dict) else None):
                if not isinstance(step_ent, dict):
                    continue
                dk = str(step_ent.get("dex_kind") or "").strip().lower()
                pl = _norm_addr(step_ent.get("pool") or "")
                if not pl or dk not in ("v2", "solidly_v", "solidly_s", "v3", "algebra"):
                    continue
                if dk in ("v3", "algebra"):
                    v3_f = int(step_ent.get("v3_fee") or 0)
                    f_bps = max(1, v3_f // 100) if v3_f > 0 else 30
                elif dk == "solidly_s":
                    f_bps = 2
                else:
                    f_bps = 30
                pv_k = f"dex_flash_{dk}"
                qt_n = _norm_addr(step_ent.get("quote_token") or "")
                for pair_tok in (tk_n, qt_n):
                    if pair_tok and pair_tok in seen_pt:
                        dex_venues_by_tok.setdefault(pair_tok, []).append(
                            {
                                "provider": pv_k,
                                "vault": _checksum(pl),
                                "vault_norm": pl,
                                "fee_bps": f_bps,
                                "configured_for_chain": False,
                            }
                        )

    known_venue_norms = {b["vault_norm"] for b in base_providers}
    erc3156_cands: List[str] = []
    for raw_v in candidate_vaults:
        nv = _norm_addr(raw_v)
        if nv and nv not in known_venue_norms and nv not in seen_pt:
            if nv not in erc3156_cands:
                erc3156_cands.append(nv)
        if len(erc3156_cands) >= 4:
            break

    has_live_rpc = (
        router is not None
        and block_pin > 0
        and bool(probe_tokens)
        and bool(router.candidate_urls(c, need_archive=True))
    )
    probed_onchain = False
    bal_map: Dict[Tuple[str, str, str], int] = {}
    fee_override: Dict[Tuple[str, str], int] = {}
    aave_atokens: Dict[Tuple[str, str], str] = {}
    erc3156_max: Dict[Tuple[str, str], int] = {}
    erc3156_fee: Dict[Tuple[str, str], int] = {}

    if has_live_rpc and router is not None:
        sel_prem = _selector("FLASHLOAN_PREMIUM_TOTAL()")
        sel_atok = _selector("getReserveAToken(address)")
        sel_rdata = _selector("getReserveData(address)")
        sel_bal_col = _selector("getProtocolFeesCollector()")
        sel_bal_fee = _selector("getFlashLoanFeePercentage()")
        sel_3156_max = _selector("maxFlashLoan(address)")
        sel_3156_fee = _selector("flashFee(address,uint256)")

        mc_reqs1: List[Tuple[str, bytes]] = []
        mc_tags1: List[Tuple[Any, ...]] = []
        bal_col_addr = ""

        def _push_mc(
            reqs: List[Tuple[str, bytes]],
            tags: List[Tuple[Any, ...]],
            tgt: str,
            cd_hex: str,
            tag: Tuple[Any, ...],
        ) -> None:
            cd_b = _hex_to_bytes(cd_hex)
            if cd_b:
                reqs.append((tgt, cd_b))
                tags.append(tag)

        for bp in base_providers:
            pv = bp["provider"]
            vchk = bp["vault"]
            vn = bp["vault_norm"]
            if pv == "aave_v3":
                _push_mc(mc_reqs1, mc_tags1, vchk, sel_prem, ("aave_prem", vn))
                for tok_n in probe_tokens:
                    tchk = _checksum(tok_n)
                    _push_mc(mc_reqs1, mc_tags1, vchk, encode_calldata(sel_atok, ["address"], [tchk]), ("aave_atok", vn, tok_n))
                    _push_mc(mc_reqs1, mc_tags1, vchk, encode_calldata(sel_rdata, ["address"], [tchk]), ("aave_rdata", vn, tok_n))
            else:
                if pv == "balancer_v2" and vn == _norm_addr(BALANCER_V2_VAULT):
                    _push_mc(mc_reqs1, mc_tags1, vchk, sel_bal_col, ("bal_col", vn))
                for tok_n in probe_tokens:
                    _push_mc(
                        mc_reqs1,
                        mc_tags1,
                        _checksum(tok_n),
                        encode_calldata(BALANCE_OF_SEL, ["address"], [vchk]),
                        ("erc20_bal", pv, vn, tok_n),
                    )

        for tok_n, dvs in dex_venues_by_tok.items():
            seen_dp: Set[str] = set()
            for dv in dvs:
                if dv["vault_norm"] in seen_dp:
                    continue
                seen_dp.add(dv["vault_norm"])
                _push_mc(
                    mc_reqs1,
                    mc_tags1,
                    _checksum(tok_n),
                    encode_calldata(BALANCE_OF_SEL, ["address"], [dv["vault"]]),
                    ("erc20_bal", dv["provider"], dv["vault_norm"], tok_n),
                )

        for cv in erc3156_cands:
            cv_chk = _checksum(cv)
            for tok_n in probe_tokens[:4]:
                _push_mc(
                    mc_reqs1,
                    mc_tags1,
                    cv_chk,
                    encode_calldata(sel_3156_max, ["address"], [_checksum(tok_n)]),
                    ("3156_max", cv, tok_n),
                )

        if mc_reqs1:
            mc_res1 = router.multicall3(c, mc_reqs1, block_pin=block_pin)
            if len(mc_res1) == len(mc_reqs1):
                probed_onchain = True
                for tag, (ok_r, ret_b) in zip(mc_tags1, mc_res1):
                    if not ok_r or not ret_b:
                        continue
                    kind_t = tag[0]
                    if kind_t == "aave_prem" and len(ret_b) >= 32:
                        prem = _decode_abi_u256_word(ret_b, 0)
                        if 0 <= prem <= 1000:
                            fee_override[("aave_v3", tag[1])] = prem
                    elif kind_t == "bal_col" and len(ret_b) >= 32:
                        col_a = _decode_abi_addr_word(ret_b, 0)
                        if col_a:
                            bal_col_addr = col_a
                    elif kind_t == "aave_atok":
                        at_a = _decode_abi_addr_word(ret_b, 0)
                        if at_a:
                            aave_atokens[(tag[1], tag[2])] = at_a
                    elif kind_t == "aave_rdata" and len(ret_b) >= 12 * 32:
                        at_a = _decode_abi_addr_word(ret_b, 8)
                        if at_a and (tag[1], tag[2]) not in aave_atokens:
                            aave_atokens[(tag[1], tag[2])] = at_a
                    elif kind_t == "erc20_bal" and len(ret_b) >= 32:
                        bal_v = _decode_abi_u256_word(ret_b, 0)
                        if bal_v > 0:
                            bal_map[(tag[1], tag[2], tag[3])] = bal_v
                    elif kind_t == "3156_max" and len(ret_b) >= 32:
                        mx_v = _decode_abi_u256_word(ret_b, 0)
                        if 0 < mx_v < (_UINT256_MAX // 2):
                            erc3156_max[(tag[1], tag[2])] = mx_v

                mc_reqs2: List[Tuple[str, bytes]] = []
                mc_tags2: List[Tuple[Any, ...]] = []
                if bal_col_addr:
                    _push_mc(mc_reqs2, mc_tags2, _checksum(bal_col_addr), sel_bal_fee, ("bal_fee", _norm_addr(BALANCER_V2_VAULT)))
                for (a_pool, tok_n), at_addr in sorted(aave_atokens.items()):
                    _push_mc(
                        mc_reqs2,
                        mc_tags2,
                        _checksum(tok_n),
                        encode_calldata(BALANCE_OF_SEL, ["address"], [_checksum(at_addr)]),
                        ("aave_bal", a_pool, tok_n),
                    )
                for (cv, tok_n), mx_v in sorted(erc3156_max.items()):
                    t_dec = max(0, min(18, int((decimals_map or {}).get(tok_n, 18))))
                    sample_amt = min(mx_v, 10 ** t_dec)
                    if sample_amt > 0:
                        _push_mc(
                            mc_reqs2,
                            mc_tags2,
                            _checksum(cv),
                            encode_calldata(sel_3156_fee, ["address", "uint256"], [_checksum(tok_n), sample_amt]),
                            ("3156_fee", cv, tok_n, sample_amt),
                        )

                if mc_reqs2:
                    mc_res2 = router.multicall3(c, mc_reqs2, block_pin=block_pin)
                    if len(mc_res2) == len(mc_reqs2):
                        for tag2, (ok2, ret2) in zip(mc_tags2, mc_res2):
                            if not ok2 or len(ret2) < 32:
                                continue
                            k2 = tag2[0]
                            if k2 == "bal_fee":
                                pct18 = _decode_abi_u256_word(ret2, 0)
                                fee_override[("balancer_v2", tag2[1])] = int((pct18 * 10000) // (10**18))
                            elif k2 == "aave_bal":
                                bal_v2 = _decode_abi_u256_word(ret2, 0)
                                if bal_v2 > 0:
                                    bal_map[("aave_v3", tag2[1], tag2[2])] = bal_v2
                            elif k2 == "3156_fee":
                                fee_v = _decode_abi_u256_word(ret2, 0)
                                samp_a = max(1, int(tag2[3]))
                                erc3156_fee[(tag2[1], tag2[2])] = int(((fee_v * 10000) + samp_a - 1) // samp_a)

    by_token: Dict[str, Dict[str, Any]] = {}
    unfunded_tokens: List[str] = []
    agg_best_by_venue: Dict[Tuple[str, str], Dict[str, Any]] = {}

    for tok_n in probe_tokens:
        tchk = _checksum(tok_n)
        t_dec = max(0, min(77, int((decimals_map or {}).get(tok_n, 18))))
        t_price_d = _to_dec((prices_map or {}).get(tok_n, 0))
        cands_t: List[Dict[str, Any]] = []
        seen_t_vp: Set[Tuple[str, str]] = set()

        def _add_cand(ent_src: Dict[str, Any], raw_amt: int, a_tok: str = "") -> None:
            pv = ent_src["provider"]
            vn = ent_src["vault_norm"]
            if (pv, vn) in seen_t_vp:
                return
            seen_t_vp.add((pv, vn))
            eff_fee = int(fee_override.get((pv, vn), ent_src.get("fee_bps", 0)))
            configured_flag = bool(ent_src.get("configured_for_chain", False))
            if raw_amt <= 0 and not configured_flag and pv in ("morpho_blue", "balancer_v2", "balancer_v3", "uniswap_v4"):
                return
            b_usd_d = (
                (Decimal(raw_amt) / (Decimal(10) ** t_dec)) * t_price_d
                if (raw_amt > 0 and t_price_d > _DEC_ZERO)
                else _DEC_ZERO
            )
            rec: Dict[str, Any] = {
                "provider": pv,
                "vault": ent_src["vault"],
                "fee_bps": eff_fee,
                "max_borrowable_raw": str(raw_amt) if raw_amt > 0 else "0",
                "stage4_mode": int(_STAGE4_FLASH_MODE.get(pv, 0)),
                "configured_for_chain": configured_flag,
            }
            if b_usd_d > _DEC_ZERO:
                rec["max_borrowable_usd"] = format(b_usd_d.quantize(Decimal("0.01"), rounding=ROUND_DOWN), "f")
            if a_tok:
                rec["reserve_atoken"] = _checksum(a_tok)
            rec["_sort_key"] = (
                0 if raw_amt > 0 else (1 if (configured_flag and not probed_onchain) else 2),
                eff_fee,
                -b_usd_d,
                -raw_amt,
                _FLASH_PROVIDER_RANK.get(pv, 99),
                vn,
            )
            cands_t.append(rec)

        for bp in base_providers:
            vn = bp["vault_norm"]
            pv = bp["provider"]
            raw_b = int(bal_map.get((pv, vn, tok_n), 0))
            _add_cand(bp, raw_b, a_tok=aave_atokens.get((vn, tok_n), "") if pv == "aave_v3" else "")
        for dv in dex_venues_by_tok.get(tok_n, ()):
            raw_b = int(bal_map.get((dv["provider"], dv["vault_norm"], tok_n), 0))
            _add_cand(dv, raw_b)
        for (cv, tk_3156), mx_v in erc3156_max.items():
            if tk_3156 == tok_n and mx_v > 0:
                _add_cand(
                    {
                        "provider": "erc3156",
                        "vault": _checksum(cv),
                        "vault_norm": cv,
                        "fee_bps": int(erc3156_fee.get((cv, tok_n), 0)),
                        "configured_for_chain": False,
                    },
                    int(mx_v),
                )

        cands_t.sort(key=lambda r: r["_sort_key"])
        clean_cands: List[Dict[str, Any]] = []
        for rc in cands_t:
            rc_clean = {k: v for k, v in rc.items() if k != "_sort_key"}
            clean_cands.append(rc_clean)
            ak = (rc_clean["provider"], _norm_addr(rc_clean["vault"]))
            prev_v = agg_best_by_venue.get(ak)
            if prev_v is None or rc["_sort_key"] < prev_v["_sort_key"]:
                agg_best_by_venue[ak] = {**rc_clean, "_sort_key": rc["_sort_key"]}

        funded_any = any(int(item.get("max_borrowable_raw") or 0) > 0 for item in clean_cands)
        if tok_n in seen_tt and (not funded_any) and (probed_onchain or c not in FLASH_PROVIDERS):
            unfunded_tokens.append(tchk)

        sym = str((token_symbols or {}).get(tok_n) or (token_symbols or {}).get(tchk) or "").strip()
        tok_doc: Dict[str, Any] = {
            "token": tchk,
            "is_target_token": tok_n in seen_tt,
            "best": clean_cands[0] if clean_cands else None,
            "candidates": clean_cands[:6],
        }
        if sym:
            tok_doc["symbol"] = sym
        by_token[tchk] = tok_doc

    ranked_options = [
        {k: v for k, v in item.items() if k != "_sort_key"}
        for item in sorted(agg_best_by_venue.values(), key=lambda x: x["_sort_key"])
    ]
    flash_search_needed = bool(c not in FLASH_PROVIDERS or unfunded_tokens)
    optimal_split_by_token: Dict[str, Any] = {}
    for t_chk_split, tok_doc_split in by_token.items():
        cands_split = list((tok_doc_split.get("candidates") or []) if isinstance(tok_doc_split, Mapping) else [])
        total_cap_split = 0
        for _cand_split in cands_split:
            if isinstance(_cand_split, Mapping):
                try:
                    total_cap_split += int(_cand_split.get("max_borrowable_raw") or 0)
                except (TypeError, ValueError):
                    pass
        optimal_split_by_token[t_chk_split] = optimize_flash_split_for_capital(
            cands_split, total_cap_split
        )
    return {
        "chain": c,
        "block_pin": int(block_pin),
        "probed_onchain": probed_onchain,
        "by_token": by_token,
        "ranked_options": ranked_options,
        "optimal_split_by_token": optimal_split_by_token,
        "unfunded_tokens": unfunded_tokens,
        "flash_search_needed": flash_search_needed,
    }


def _build_dynamic_flash_web_queries(
    chain: str,
    flash_plan: Optional[Mapping[str, Any]],
    fallback_tokens: Sequence[str] = (),
) -> List[str]:
    """온체인 플래시론 미등록 체인 또는 유동성 미충족 토큰에 한해 런타임 에이전트용 토큰별 동적 플래시론 웹 검색 쿼리를 생성한다."""
    if not isinstance(flash_plan, Mapping) or not bool(flash_plan.get("flash_search_needed")):
        return []
    c = _norm_chain(chain)
    queries: List[str] = []
    unfunded = [str(x).strip() for x in (flash_plan.get("unfunded_tokens") or ()) if str(x).strip()]
    by_tok = flash_plan.get("by_token") if isinstance(flash_plan.get("by_token"), Mapping) else {}
    target_list = unfunded or [_checksum(t) for t in fallback_tokens if _norm_addr(t)]
    for t_addr in target_list[:2]:
        t_info = by_tok.get(t_addr) if isinstance(by_tok, Mapping) else None
        t_sym = str((t_info or {}).get("symbol") or "").strip() if isinstance(t_info, Mapping) else ""
        tok_lbl = f"{t_sym} {t_addr}" if t_sym else t_addr
        queries.append(f'"{c}" "{tok_lbl}" flash loan provider vault pool address')
    if c not in FLASH_PROVIDERS:
        queries.append(f'"{c}" flash loan balancer morpho euler aave v3 spark deployed address')
    return list(dict.fromkeys(queries))


_TRIVIAL_APPROVAL_PRESCREEN_SELS: FrozenSet[str] = frozenset(
    {
        "0x095ea7b3",  # approve(address,uint256)
        "0x39509351",  # increaseAllowance(address,uint256)
        "0xa457c2d7",  # decreaseAllowance(address,uint256)
        "0xd505accf",  # permit(...)
    }
)


def _is_trivial_approval_slice(sl: CausalSlice) -> bool:
    return (
        bool(sl.legs)
        and not sl.preencoded_calldata_hex
        and not sl.flash_loan_hint
        and all(str(s).lower() in _TRIVIAL_APPROVAL_PRESCREEN_SELS for s in sl.legs)
    )


def _pick_flash_provider_for_token(
    flash_plan: Optional[Mapping[str, Any]],
    tok_addr: str,
    *,
    exclude_vault: str = "",
) -> Optional[Dict[str, Any]]:
    if not isinstance(flash_plan, Mapping):
        return None
    by_tok = flash_plan.get("by_token")
    if not isinstance(by_tok, Mapping) or not by_tok:
        return None
    t_norm = _norm_addr(tok_addr)
    if not t_norm:
        return None
    t_chk = _checksum(t_norm)
    entry = by_tok.get(t_chk) or by_tok.get(t_norm)
    if not isinstance(entry, Mapping):
        for k_t, v_t in by_tok.items():
            if _norm_addr(str(k_t)) == t_norm and isinstance(v_t, Mapping):
                entry = v_t
                t_chk = _checksum(t_norm)
                break
    if not isinstance(entry, Mapping):
        return None
    excl_n = _norm_addr(exclude_vault)
    raw_cands: List[Mapping[str, Any]] = []
    if isinstance(entry.get("best"), Mapping):
        raw_cands.append(entry["best"])
    for cc in entry.get("candidates") or ():
        if isinstance(cc, Mapping):
            raw_cands.append(cc)
    for fee_cap in (9, 30):
        for cand in raw_cands:
            mode = int(cand.get("stage4_mode") or 0)
            cap = int(cand.get("max_borrowable_raw") or 0)
            fee_bps = int(cand.get("fee_bps") if cand.get("fee_bps") is not None else 999)
            v_norm = _norm_addr(str(cand.get("vault") or ""))
            if not v_norm or (excl_n and v_norm == excl_n):
                continue
            if mode in _STAGE4_FLASH_MODES and cap > 0 and fee_bps <= fee_cap:
                out = dict(cand)
                out["token"] = t_chk
                out["_entry"] = entry
                return out
    return None


def _build_stage4_flash_wrapped_slices(
    slices: Sequence[CausalSlice],
    flash_plan: Optional[Mapping[str, Any]],
    token_addrs: Sequence[str],
    decimals_map: Optional[Mapping[str, int]] = None,
    *,
    exit_routes: Optional[Mapping[str, Mapping[str, Any]]] = None,
    chain: str = "",
    max_slices: int = 6,
    max_amm_slices: int = 3,
) -> List[CausalSlice]:
    """온체인에서 실물 유동성이 확인된 저수수료(<= 9 bps) 플래시론 공급자(단일·다중 분할)를 Stage-4 자본·AMM 보존 검증 슬라이스로 결합한다."""
    if not slices or not isinstance(flash_plan, Mapping):
        return []
    by_tok = flash_plan.get("by_token")
    if not isinstance(by_tok, Mapping) or not by_tok:
        return []
    chosen_tok = ""
    chosen_best: Optional[Dict[str, Any]] = None
    ordered_toks = [_checksum(t) for t in token_addrs if _norm_addr(t)]
    for t_chk in [*ordered_toks, *[k for k in by_tok if k not in ordered_toks]]:
        picked = _pick_flash_provider_for_token(flash_plan, t_chk)
        if picked is not None:
            chosen_tok = str(picked["token"])
            chosen_best = picked
            break
    if not chosen_tok or chosen_best is None:
        return []

    cap_raw = int(chosen_best.get("max_borrowable_raw") or 0)
    t_dec = max(0, min(18, int((decimals_map or {}).get(_norm_addr(chosen_tok), 18))))
    split_plan_doc: Optional[Dict[str, Any]] = None
    split_legs_s4: List[Dict[str, Any]] = []
    split_total_cap = cap_raw
    try:
        _chosen_entry = chosen_best.get("_entry")
        _chosen_cands = list(_chosen_entry.get("candidates") or []) if isinstance(_chosen_entry, Mapping) else []
        _stage4_cands = [
            _cc
            for _cc in _chosen_cands
            if isinstance(_cc, Mapping)
            and int(_cc.get("stage4_mode") or 0) in _STAGE4_FLASH_MODES
            and int(_cc.get("fee_bps") or 0) <= 9
        ]
        if _stage4_cands:
            _total_stage4_cap = sum(int(_cc.get("max_borrowable_raw") or 0) for _cc in _stage4_cands)
            if _total_stage4_cap > cap_raw:
                split_total_cap = _total_stage4_cap
                split_plan_doc = optimize_flash_split_for_capital(_stage4_cands, _total_stage4_cap)
                _vault_mode_map = {
                    _norm_addr(str(_cc.get("vault") or "")): int(_cc.get("stage4_mode") or 0)
                    for _cc in _stage4_cands
                }
                for _sleg in ((split_plan_doc or {}).get("plan") or (split_plan_doc or {}).get("legs") or ()):
                    _sv = _norm_addr(str(_sleg.get("vault") or ""))
                    _sm = _vault_mode_map.get(_sv, 0)
                    _sa = int(_sleg.get("amount_raw") or 0)
                    if _sv and _sm in _STAGE4_FLASH_MODES and _sa > 0:
                        split_legs_s4.append({"mode": _sm, "vault": _checksum(_sv), "amount_raw": str(_sa)})
                if len(split_legs_s4) < 2 or split_legs_s4[0]["vault"] == split_legs_s4[1]["vault"]:
                    split_legs_s4 = []
    except Exception:
        split_plan_doc = None
        split_legs_s4 = []
    eff_cap_raw = max(cap_raw, split_total_cap)
    raw_ws = [
        10 ** t_dec,
        100 * (10 ** t_dec),
        cap_raw // 100,
        cap_raw // 10,
        cap_raw // 4,
        cap_raw // 2,
        cap_raw,
        eff_cap_raw // 2,
        eff_cap_raw,
    ]
    witness_ws = _dedup_bounded_positive_ints(raw_ws, eff_cap_raw, 6) or [cap_raw]

    pri_cands: List[CausalSlice] = [
        sl for sl in slices[:28] if sl.slice_id.startswith("ch_flash_capital_") and sl.legs
    ]
    sec_cands: List[CausalSlice] = [
        sl
        for sl in slices[:28]
        if sl not in pri_cands
        and sl.legs
        and not sl.slice_id.endswith("_fail_open_fallback")
        and not _is_trivial_approval_slice(sl)
        and (sl.channel in ("CH_STORAGE", "CH_BALANCE", "CH_MIDFRAME") or (sl.prescreen_diagnostics or {}).get("status") == "active")
    ]
    if not pri_cands and not sec_cands:
        sec_cands = [
            sl for sl in slices[:12] if sl.legs and not sl.slice_id.endswith("_fail_open_fallback")
        ]
    hint_doc = {
        "mode": int(chosen_best["stage4_mode"]),
        "vault": str(chosen_best["vault"]),
        "token": chosen_tok,
        "fee_bps": int(chosen_best.get("fee_bps") or 0),
        "max_borrowable_raw": str(cap_raw),
        "total_borrowable_raw": str(split_total_cap),
        "split_plan": dict(split_plan_doc) if split_plan_doc is not None else {},
        "split_legs": split_legs_s4[:2],
    }
    wrapped: List[CausalSlice] = []
    for cand in [*pri_cands, *sec_cands]:
        wrapped.append(
            dataclasses.replace(
                cand,
                slice_id=f"{cand.slice_id}_flash",
                needs_agent_synthesis=False,
                witness_candidates=list(witness_ws),
                flash_loan_hint=dict(hint_doc),
            )
        )
        if len(wrapped) >= max_slices:
            break

    # Direct-Donation / Push-Balance Flash-Loan Probe (1-leg: push->call; multi-leg: leg0->push->leg1..N)
    _don_cand = next(
        (c_d for c_d in [*pri_cands, *sec_cands] if c_d.channel == "CH_BALANCE" and not _is_trivial_approval_slice(c_d)),
        next((c_d for c_d in [*pri_cands, *sec_cands] if not _is_trivial_approval_slice(c_d)), None),
    )
    if _don_cand is not None and cap_raw > 1:
        _don_ws = _dedup_bounded_positive_ints([10 ** t_dec, 100 * (10 ** t_dec), cap_raw // 4], cap_raw, 3) or [cap_raw]
        wrapped.append(
            dataclasses.replace(
                _don_cand,
                slice_id=f"{_don_cand.slice_id}_flash_donate",
                needs_agent_synthesis=False,
                witness_candidates=list(_don_ws),
                flash_loan_hint={**hint_doc, "donate": True},
            )
        )

    # Native ETH Flash-Unwrap Probe (flash WETH -> withdraw() -> payable msg.value leg -> deposit() -> repay)
    _wn_target = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(_norm_chain(chain), "")) if chain else ""
    _wn_prov = _pick_flash_provider_for_token(flash_plan, _wn_target) if _wn_target else None
    if _wn_prov is None and _norm_addr(chosen_tok) in _ALL_WRAPPED_NATIVE_LOWER:
        _wn_prov = chosen_best
    if _wn_prov is not None:
        _eth_cap = int(_wn_prov.get("max_borrowable_raw") or 0)
        _eth_cand = next(
            (
                c_e
                for c_e in [*pri_cands, *sec_cands]
                if not _is_trivial_approval_slice(c_e)
                and (
                    c_e.channel in ("CH_MIDFRAME", "CH_BALANCE")
                    or bool((c_e.prescreen_diagnostics or {}).get("multicall_msg_value_reuse_risk"))
                )
            ),
            next((c_e for c_e in [*pri_cands, *sec_cands] if not _is_trivial_approval_slice(c_e)), None),
        )
        if _eth_cand is not None and _eth_cap > 0:
            _eth_tok = str(_wn_prov["token"])
            _eth_ws = _dedup_bounded_positive_ints([10 ** 18, 10 * (10 ** 18), _eth_cap // 4], _eth_cap, 3) or [_eth_cap]
            wrapped.append(
                dataclasses.replace(
                    _eth_cand,
                    slice_id=f"{_eth_cand.slice_id}_flash_eth",
                    needs_agent_synthesis=False,
                    witness_candidates=list(_eth_ws),
                    flash_loan_hint={
                        "mode": int(_wn_prov["stage4_mode"]),
                        "vault": str(_wn_prov["vault"]),
                        "token": _eth_tok,
                        "fee_bps": int(_wn_prov.get("fee_bps") or 0),
                        "max_borrowable_raw": str(_eth_cap),
                        "total_borrowable_raw": str(_eth_cap),
                        "split_plan": {},
                        "eth_unwrap": True,
                    },
                )
            )

    # Multi-Asset Dual-Token Flash Probe (simultaneously borrow 2 distinct funded tokens in 1 atomic tx)
    chosen_tok_n = _norm_addr(chosen_tok)
    chosen_best2: Optional[Dict[str, Any]] = None
    for t2_chk in [*ordered_toks, *[k for k in by_tok if k not in ordered_toks]]:
        if _norm_addr(t2_chk) == chosen_tok_n:
            continue
        p2 = _pick_flash_provider_for_token(flash_plan, t2_chk)
        if p2 is not None and int(p2.get("max_borrowable_raw") or 0) > 0:
            chosen_best2 = p2
            break
    if chosen_best2 is not None:
        _dual_cand = next(
            (c_du for c_du in [*pri_cands, *sec_cands] if not _is_trivial_approval_slice(c_du)),
            None,
        )
        if _dual_cand is not None:
            _t2_chk = str(chosen_best2["token"])
            _t2_dec = max(0, min(18, int((decimals_map or {}).get(_norm_addr(_t2_chk), 18))))
            _cap2 = int(chosen_best2.get("max_borrowable_raw") or 0)
            _amt2 = min(_cap2, max(10 ** _t2_dec, _cap2 // 4, 100 * (10 ** _t2_dec)))
            _dual_ws = _dedup_bounded_positive_ints([10 ** t_dec, 100 * (10 ** t_dec), cap_raw // 4], cap_raw, 3) or [cap_raw]
            wrapped.append(
                dataclasses.replace(
                    _dual_cand,
                    slice_id=f"{_dual_cand.slice_id}_flash_dual",
                    needs_agent_synthesis=False,
                    witness_candidates=list(_dual_ws),
                    flash_loan_hint={
                        **hint_doc,
                        "split_legs": [],
                        "dual_leg": {
                            "mode": int(chosen_best2["stage4_mode"]),
                            "vault": str(chosen_best2["vault"]),
                            "token": _t2_chk,
                            "amount_raw": str(_amt2),
                        },
                    },
                )
            )

    # 3-Step AMM Reserve-Perturbation Invariance Probe (flash -> V2/Solidly/V3/Algebra/V4/BalV3/Curve swap -> target -> reverse swap -> repay)
    if max_amm_slices > 0 and isinstance(exit_routes, Mapping) and exit_routes:
        best_amm: Optional[Tuple[Decimal, str, int, str, Dict[str, Any], Dict[str, Any], bool]] = None
        _kind_map = {
            "v2": 1,
            "solidly": 2,
            "solidly_v": 2,
            "solidly_s": 2,
            "v3": 3,
            "algebra": 3,
            "v4": 4,
            "balancer_v3": 5,
            "curve": 6,
            "curve_v2": 6,
            "curve_ng": 6,
        }
        for tok_k, r_meta in exit_routes.items():
            if not isinstance(r_meta, Mapping) or bool(r_meta.get("paused")):
                continue
            dk_s = str(r_meta.get("dex_kind") or r_meta.get("best_dex_kind") or "").lower()
            dk_i = _kind_map.get(dk_s, 0)
            p_addr = _norm_addr(str(r_meta.get("pool") or r_meta.get("best_pool_address") or ""))
            q_tok = _norm_addr(str(r_meta.get("quote_token") or r_meta.get("best_quote_token") or ""))
            b_tok = _norm_addr(str(tok_k))
            if not (dk_i and p_addr and q_tok and b_tok and q_tok != b_tok):
                continue
            depth_d = _to_dec(r_meta.get("dex_depth_usd_dec") or r_meta.get("dex_depth_usd") or 0)
            for loan_cand, other_cand in ((q_tok, b_tok), (b_tok, q_tok)):
                prov_amm = _pick_flash_provider_for_token(flash_plan, loan_cand, exclude_vault=p_addr)
                if prov_amm is None:
                    continue
                if best_amm is None or depth_d > best_amm[0]:
                    best_amm = (depth_d, _checksum(p_addr), dk_i, _checksum(other_cand), prov_amm, dict(r_meta), loan_cand == q_tok)
                break
        if best_amm is not None:
            _, amm_pool_chk, amm_kind_i, amm_other_chk, amm_prov, amm_rmeta, amm_rev_dir = best_amm
            amm_cap = int(amm_prov.get("max_borrowable_raw") or 0)
            amm_tok_chk = str(amm_prov["token"])
            amm_dec = max(0, min(18, int((decimals_map or {}).get(_norm_addr(amm_tok_chk), 18))))
            amm_ws = _dedup_bounded_positive_ints(
                [10 * (10 ** amm_dec), 100 * (10 ** amm_dec), amm_cap // 4], amm_cap, 3
            ) or [amm_cap]
            raw_ci = int(amm_rmeta.get("curve_i") or 0)
            raw_cj = int(amm_rmeta.get("curve_j") if amm_rmeta.get("curve_j") is not None else (1 if raw_ci == 0 else 0))
            amm_hint = {
                "mode": int(amm_prov["stage4_mode"]),
                "vault": str(amm_prov["vault"]),
                "token": amm_tok_chk,
                "fee_bps": int(amm_prov.get("fee_bps") or 0),
                "max_borrowable_raw": str(amm_cap),
                "total_borrowable_raw": str(amm_cap),
                "split_plan": {},
                "amm_pair": {
                    "pool": amm_pool_chk,
                    "kind": amm_kind_i,
                    "quote_token": amm_other_chk,
                    "v3_fee": int(amm_rmeta.get("v3_fee") or 3000),
                    "v4_tick_spacing": int(amm_rmeta.get("v4_tick_spacing") or 60),
                    "v4_hooks": _checksum(_norm_addr(amm_rmeta.get("v4_hooks") or "") or ZERO_ADDRESS),
                    "bal_v3_vault": _checksum(_norm_addr(amm_rmeta.get("bal_v3_vault") or "") or _norm_addr(BALANCER_V3_VAULT)),
                    "curve_i": raw_cj if amm_rev_dir else raw_ci,
                    "curve_j": raw_ci if amm_rev_dir else raw_cj,
                    "curve_underlying": bool(amm_rmeta.get("curve_underlying")),
                },
            }
            amm_added = 0
            for cand in [*pri_cands, *sec_cands]:
                if _is_trivial_approval_slice(cand):
                    continue
                wrapped.append(
                    dataclasses.replace(
                        cand,
                        slice_id=f"{cand.slice_id}_flash_amm",
                        needs_agent_synthesis=False,
                        witness_candidates=list(amm_ws),
                        flash_loan_hint=dict(amm_hint),
                    )
                )
                amm_added += 1
                if amm_added >= max_amm_slices:
                    break
    return wrapped

# ═════════════════════════════════════════════════════════════════════════════
# §4. 현행 EVM 오프코드 스펙 · 6단 프록시/Diamond/EIP-7702 해석기 · E1 보존 표면 폐포
# ═════════════════════════════════════════════════════════════════════════════

# (opcode -> (mnemonic, pop_count, push_count, imm_bytes))
OPCODE_SPEC: Dict[int, Tuple[str, int, int, int]] = {
    0x00: ("STOP", 0, 0, 0),
    0x01: ("ADD", 2, 1, 0),
    0x02: ("MUL", 2, 1, 0),
    0x03: ("SUB", 2, 1, 0),
    0x04: ("DIV", 2, 1, 0),
    0x05: ("SDIV", 2, 1, 0),
    0x06: ("MOD", 2, 1, 0),
    0x07: ("SMOD", 2, 1, 0),
    0x08: ("ADDMOD", 3, 1, 0),
    0x09: ("MULMOD", 3, 1, 0),
    0x0A: ("EXP", 2, 1, 0),
    0x0B: ("SIGNEXTEND", 2, 1, 0),
    0x10: ("LT", 2, 1, 0),
    0x11: ("GT", 2, 1, 0),
    0x12: ("SLT", 2, 1, 0),
    0x13: ("SGT", 2, 1, 0),
    0x14: ("EQ", 2, 1, 0),
    0x15: ("ISZERO", 1, 1, 0),
    0x16: ("AND", 2, 1, 0),
    0x17: ("OR", 2, 1, 0),
    0x18: ("XOR", 2, 1, 0),
    0x19: ("NOT", 1, 1, 0),
    0x1A: ("BYTE", 2, 1, 0),
    0x1B: ("SHL", 2, 1, 0),
    0x1C: ("SHR", 2, 1, 0),
    0x1D: ("SAR", 2, 1, 0),
    0x1E: ("CLZ", 1, 1, 0),          # Fusaka EIP-7939 Count Leading Zeros
    0x20: ("KECCAK256", 2, 1, 0),
    0x30: ("ADDRESS", 0, 1, 0),
    0x31: ("BALANCE", 1, 1, 0),
    0x32: ("ORIGIN", 0, 1, 0),
    0x33: ("CALLER", 0, 1, 0),
    0x34: ("CALLVALUE", 0, 1, 0),
    0x35: ("CALLDATALOAD", 1, 1, 0),
    0x36: ("CALLDATASIZE", 0, 1, 0),
    0x37: ("CALLDATACOPY", 3, 0, 0),
    0x38: ("CODESIZE", 0, 1, 0),
    0x39: ("CODECOPY", 3, 0, 0),
    0x3A: ("GASPRICE", 0, 1, 0),
    0x3B: ("EXTCODESIZE", 1, 1, 0),
    0x3C: ("EXTCODECOPY", 4, 0, 0),
    0x3D: ("RETURNDATASIZE", 0, 1, 0),
    0x3E: ("RETURNDATACOPY", 3, 0, 0),
    0x3F: ("EXTCODEHASH", 1, 1, 0),
    0x40: ("BLOCKHASH", 1, 1, 0),
    0x41: ("COINBASE", 0, 1, 0),
    0x42: ("TIMESTAMP", 0, 1, 0),
    0x43: ("NUMBER", 0, 1, 0),
    0x44: ("PREVRANDAO", 0, 1, 0),
    0x45: ("GASLIMIT", 0, 1, 0),
    0x46: ("CHAINID", 0, 1, 0),
    0x47: ("SELFBALANCE", 0, 1, 0),
    0x48: ("BASEFEE", 0, 1, 0),
    0x49: ("BLOBHASH", 1, 1, 0),     # Cancun EIP-4844
    0x4A: ("BLOBBASEFEE", 0, 1, 0),  # Cancun EIP-7516
    0x4B: ("SLOTNUM", 0, 1, 0),      # Glamsterdam EIP-7843 reserve
    0x50: ("POP", 1, 0, 0),
    0x51: ("MLOAD", 1, 1, 0),
    0x52: ("MSTORE", 2, 0, 0),
    0x53: ("MSTORE8", 2, 0, 0),
    0x54: ("SLOAD", 1, 1, 0),
    0x55: ("SSTORE", 2, 0, 0),
    0x56: ("JUMP", 1, 0, 0),
    0x57: ("JUMPI", 2, 0, 0),
    0x58: ("PC", 0, 1, 0),
    0x59: ("MSIZE", 0, 1, 0),
    0x5A: ("GAS", 0, 1, 0),
    0x5B: ("JUMPDEST", 0, 0, 0),
    0x5C: ("TLOAD", 1, 1, 0),        # Cancun EIP-1153 Transient Load
    0x5D: ("TSTORE", 2, 0, 0),       # Cancun EIP-1153 Transient Store
    0x5E: ("MCOPY", 3, 0, 0),        # Cancun EIP-5656 Memory Copy
    0x5F: ("PUSH0", 0, 1, 0),        # Shanghai EIP-3855
    0xE6: ("DUPN", 0, 1, 1),         # Glamsterdam EIP-8024
    0xE7: ("SWAPN", 0, 0, 1),        # Glamsterdam EIP-8024
    0xE8: ("EXCHANGE", 0, 0, 1),     # Glamsterdam EIP-8024
    0xF0: ("CREATE", 3, 1, 0),
    0xF1: ("CALL", 7, 1, 0),
    0xF2: ("CALLCODE", 7, 1, 0),
    0xF3: ("RETURN", 2, 0, 0),
    0xF4: ("DELEGATECALL", 6, 1, 0),
    0xF5: ("CREATE2", 4, 1, 0),
    0xFA: ("STATICCALL", 6, 1, 0),
    0xFD: ("REVERT", 2, 0, 0),
    0xFE: ("INVALID", 0, 0, 0),
    0xFF: ("SELFDESTRUCT", 1, 0, 0),
}

for _w in range(1, 33):
    OPCODE_SPEC[0x5F + _w] = (f"PUSH{_w}", 0, 1, _w)
for _d in range(1, 17):
    OPCODE_SPEC[0x7F + _d] = (f"DUP{_d}", _d, _d + 1, 0)
    OPCODE_SPEC[0x8F + _d] = (f"SWAP{_d}", _d + 1, _d + 1, 0)
for _lg in range(0, 5):
    OPCODE_SPEC[0xA0 + _lg] = (f"LOG{_lg}", 2 + _lg, 0, 0)


def _effective_opcode_spec(clean_code: bytes, pc: int) -> Optional[Tuple[str, int, int, int]]:
    op = clean_code[pc]
    spec = OPCODE_SPEC.get(op)
    if spec is None:
        return None
    if op in (0xE6, 0xE7, 0xE8):
        if pc + 1 >= len(clean_code):
            return None
        nxt = clean_code[pc + 1]
        if op in (0xE6, 0xE7):
            if 0x5B <= nxt <= 0x7F:
                return None
        elif 0x52 <= nxt <= 0x7F:
            return None
    return spec


@functools.lru_cache(maxsize=2048)
def _disassemble_cached(code: bytes) -> Tuple[Tuple[int, str, bytes], ...]:
    clean_code = _strip_cbor_bytes(code)
    out: List[Tuple[int, str, bytes]] = []
    pc = 0
    n = len(clean_code)
    while pc < n:
        op = clean_code[pc]
        spec = _effective_opcode_spec(clean_code, pc)
        if spec is None:
            out.append((pc, f"OP_{op:02x}", b""))
            pc += 1
        else:
            name, _pop, _push, imm_w = spec
            imm = clean_code[pc + 1:pc + 1 + imm_w] if imm_w > 0 else b""
            out.append((pc, name, imm))
            pc += 1 + imm_w
    return tuple(out)


def _disassemble(code: Any) -> List[Tuple[int, str, bytes]]:
    raw = _hex_to_bytes(code) if not isinstance(code, (bytes, bytearray)) else bytes(code)
    return list(_disassemble_cached(raw))


@functools.lru_cache(maxsize=2048)
def _extract_opcode_bytes_cached(clean_raw: bytes) -> bytes:
    if not clean_raw:
        return b""
    sk = bytearray()
    pc = 0
    n = len(clean_raw)
    while pc < n:
        sk.append(clean_raw[pc])
        pc += 1 + _fast_opcode_imm_width(clean_raw, pc, n)
    return bytes(sk)


def _extract_opcode_bytes(code: Any) -> bytes:
    raw = _strip_cbor_bytes(_hex_to_bytes(code) if not isinstance(code, (bytes, bytearray)) else bytes(code))
    return _extract_opcode_bytes_cached(raw) if raw else b""


def _skeleton_hash(code: Any) -> str:
    ops = _extract_opcode_bytes(code)
    return _keccak256_hex(ops) if ops else ""


def _opcode_4grams(code: Any, cap: int = 512) -> Set[str]:
    ops = _extract_opcode_bytes(code)
    if not ops:
        return set()
    if len(ops) < 4:
        return {ops.hex()}
    raw_grams = {ops[i : i + 4] for i in range(len(ops) - 3)}
    if len(raw_grams) <= cap:
        return {g.hex() for g in raw_grams}
    # Deterministic Bottom-k MinHash sketch via CRC32 (eliminates 0x00.. lexicographical truncation bias)
    ranked = sorted(raw_grams, key=lambda g: (zlib.crc32(g), g))
    return {g.hex() for g in ranked[:cap]}


# ── 6단 프록시 · EIP-7702 · EIP-1167(Solady PUSH0·CWIA·ERC-3448 불변인자 포함) · Slot-0 Safe · Diamond 해석기 ──
_EIP1167_PREFIXES: Tuple[bytes, ...] = (
    bytes.fromhex("363d3d373d3d3d363d73"),
    bytes.fromhex("3d3d3d3d363d3d37363d73"),
    bytes.fromhex("363d3d373d3d363d73"),
    bytes.fromhex("365f5f375f5f365f73"),
    bytes.fromhex("5f5f365f5f37365f73"),
)


def _eip1167_impl(code: Any) -> str:
    raw = _hex_to_bytes(code)
    for pref in _EIP1167_PREFIXES:
        if len(raw) >= len(pref) + 20 + 9 and raw.startswith(pref):
            tail_window = raw[len(pref) + 20 : len(pref) + 40]
            if b"\x5a\xf4" in tail_window:  # GAS DELEGATECALL (표준·PUSH0·CWIA·ERC-3448 불변인자 클론 전수 포착)
                addr = _norm_addr("0x" + raw[len(pref) : len(pref) + 20].hex())
                if addr and int(addr, 16) > 0:
                    return addr
    # Vyper create_minimal_proxy_to 및 wighawag/Solady ClonesWithImmutableArgs(CWIA) / ERC-3448 MetaProxy 무상태 DELEGATECALL 스텁 해석
    if 32 <= len(raw) <= 8192:
        stub_limit = min(len(raw), 256)
        pc = 0
        stub_insns: List[Tuple[str, bytes]] = []
        dcall_idx = -1
        ret_after_dcall = False
        forbidden_stub_ops = {
            "SLOAD", "SSTORE", "TLOAD", "TSTORE",
            "CALL", "STATICCALL", "CALLCODE",
            "CREATE", "CREATE2", "SELFDESTRUCT", "EQ",
        }
        valid_stub = True
        while pc < stub_limit:
            spec = _effective_opcode_spec(raw, pc)
            if spec is None:
                valid_stub = False
                break
            nm, _pop, _push, imm_w = spec
            if pc + 1 + imm_w > len(raw):
                valid_stub = False
                break
            if nm in forbidden_stub_ops:
                valid_stub = False
                break
            imm = raw[pc + 1 : pc + 1 + imm_w] if imm_w > 0 else b""
            stub_insns.append((nm, imm))
            pc += 1 + imm_w
            if nm == "DELEGATECALL" and dcall_idx < 0:
                dcall_idx = len(stub_insns) - 1
            elif nm == "RETURN" and dcall_idx >= 0:
                ret_after_dcall = True
                break
        if valid_stub and dcall_idx > 0 and ret_after_dcall:
            p20_hits = [
                (i, pad_imm)
                for i, (nm, imm) in enumerate(stub_insns[:dcall_idx])
                if nm in ("PUSH16", "PUSH17", "PUSH18", "PUSH19", "PUSH20")
                and 16 <= len(imm) <= 20
                and not all(b == 0xFF for b in imm)
                and _is_non_precompile_addr("0x" + (pad_imm := imm.rjust(20, b"\x00")).hex())
            ]
            if len(p20_hits) == 1 and 0 < (dcall_idx - p20_hits[0][0]) <= 12:
                addr = _norm_addr("0x" + p20_hits[0][1].hex())
                if addr:
                    return addr
    return ""


def _eip7702_delegate(code: Any) -> str:
    raw = _hex_to_bytes(code)
    if len(raw) == 23 and raw[:3] == b"\xef\x01\x00":
        addr = _norm_addr("0x" + raw[3:23].hex())
        if addr and int(addr, 16) > 0:
            return addr
    return ""


def _slot0_safe_proxy_shape(code: Any, dis: Optional[Sequence[Tuple[int, str, bytes]]] = None) -> bool:
    raw = _hex_to_bytes(code)
    # 2,048B 대형 컨트랙트 오염 가드 + Safe 프록시 상한(<=512B)
    if len(raw) == 0 or len(raw) > 512:
        return False
    insns = list(dis) if dis is not None else _disassemble(raw)
    if not any(name == "DELEGATECALL" for _, name, _ in insns):
        return False
    for i in range(len(insns) - 1):
        _, n0, imm0 = insns[i]
        _, n1, _ = insns[i + 1]
        if n1 == "SLOAD" and (n0 == "PUSH0" or (n0.startswith("PUSH") and int.from_bytes(imm0 or b"\x00", "big") == 0)):
            return True
    return False


LOUPE_FACET_ADDRS_SEL: str = _selector("facetAddresses()")


def _decode_checked_facet_entries(raw_ret: Any, abi_type: str, tuple_head: bool) -> Tuple[List[str], bool]:
    b = _hex_to_bytes(raw_ret)
    if len(b) < 64:
        return [], bool(len(b) > 0)
    try:
        decoded = abi_decode([abi_type], b)[0]
        addrs: List[str] = []
        seen_addrs: Set[str] = set()
        had_invalid = False
        for item in decoded:
            na = _norm_addr(item[0] if tuple_head else item)
            if _is_non_precompile_addr(na):
                _append_unique(addrs, seen_addrs, na)
            else:
                had_invalid = True
        return addrs, had_invalid
    except Exception:
        return [], True


def _decode_diamond_facets_checked(raw_ret: Any) -> Tuple[List[str], bool]:
    return _decode_checked_facet_entries(raw_ret, "(address,bytes4[])[]", tuple_head=True)


def _decode_diamond_facet_addresses_checked(raw_ret: Any) -> Tuple[List[str], bool]:
    return _decode_checked_facet_entries(raw_ret, "address[]", tuple_head=False)


def _decode_diamond_facets(raw_ret: Any) -> List[str]:
    return _decode_diamond_facets_checked(raw_ret)[0]


def _extract_constant_storage_slots(dis: Sequence[Tuple[int, str, bytes]]) -> Tuple[Set[int], Set[int]]:
    reads: Set[int] = set()
    writes: Set[int] = set()
    for i in range(len(dis) - 1):
        _, n0, imm0 = dis[i]
        _, n1, _ = dis[i + 1]
        if n1 in ("SLOAD", "SSTORE"):
            if n0 == "PUSH0":
                slot_val = 0
            elif n0.startswith("PUSH"):
                slot_val = int.from_bytes(imm0, "big")
            else:
                continue
            if n1 == "SLOAD":
                reads.add(slot_val)
            else:
                writes.add(slot_val)
    return reads, writes


def _detect_storage_slot_collision(
    proxy_dis: Sequence[Tuple[int, str, bytes]],
    impl_dis: Sequence[Tuple[int, str, bytes]],
    *,
    exclude_slot0: bool = False,
) -> Set[int]:
    pr_r, pr_w = _extract_constant_storage_slots(proxy_dis)
    im_r, im_w = _extract_constant_storage_slots(impl_dis)
    excluded = (STANDARD_PROXY_SLOTS | {0}) if exclude_slot0 else STANDARD_PROXY_SLOTS
    proxy_all = (pr_r | pr_w) - excluded
    impl_all = (im_r | im_w) - excluded
    return proxy_all & impl_all


def _push20_constants(dis: Union[Sequence[Tuple[int, str, bytes]], bytes, bytearray, str]) -> List[str]:
    dis_seq = _disassemble(dis) if isinstance(dis, (bytes, bytearray, str)) else dis
    out: Set[str] = set()
    for _, name, imm in dis_seq:
        if name == "PUSH20" and len(imm) == 20:
            v = int.from_bytes(imm, "big")
            cand_a = "0x" + imm.hex().lower()
            if _is_non_precompile_addr(cand_a) and v < ((1 << 160) - 0x1000):
                out.add(cand_a)
    return sorted(out)


@dataclasses.dataclass
class ProxyResolution:
    address: str
    proxy_kind: str
    impl_addresses: List[str]
    admin_address: str
    raw_code_hex: str
    effective_code_hex: str
    skeleton_hash: str
    slot_collisions: List[int]
    impl_codes_hex: Dict[str, str] = dataclasses.field(default_factory=dict)
    unresolved_delegation: bool = False
    beacon_address: str = ""


def _res_facet_codes_hex(res: ProxyResolution) -> List[str]:
    if res.impl_codes_hex:
        return list(res.impl_codes_hex.values())
    return [res.effective_code_hex] if res.effective_code_hex else []


def _collect_hint_probe_blocks(
    hint_blocks: Optional[Sequence[int]],
    hi_block: int,
    *,
    pre_first: bool = False,
) -> Tuple[List[int], List[int]]:
    probe_blocks: List[int] = []
    seen_pb: Set[int] = set()
    valid_hints: List[int] = []
    for raw_hb in (hint_blocks or ()):
        try:
            hb = int(raw_hb)
        except (TypeError, ValueError):
            continue
        if 1 <= hb <= hi_block:
            valid_hints.append(hb)
            pair = (max(1, hb - 1), hb) if pre_first else (hb, max(1, hb - 1))
            for cand_h in pair:
                _append_unique(probe_blocks, seen_pb, cand_h)
    return probe_blocks, valid_hints


def _extract_mode_b_hint_blocks(
    router: Optional[RPCRouter],
    chain: str,
    meta_doc: Optional[Dict[str, Any]],
    hi_block: int = 0,
) -> List[int]:
    """메타데이터의 block_numbers 및 tx_hashes 영수증에서 과거 시점 탐색용 블록 단서(hi_block 이하)를 수집."""
    out: List[int] = []
    seen: Set[int] = set()
    if not isinstance(meta_doc, dict):
        return out
    for raw_bn in (meta_doc.get("block_numbers") or [])[:8]:
        try:
            bn_i = int(raw_bn)
        except (TypeError, ValueError):
            bn_i = 0
        if bn_i >= 1 and (hi_block <= 0 or bn_i <= hi_block):
            for cand_hb in (bn_i, max(1, bn_i - 1)):
                _append_unique(out, seen, cand_hb)
    if router is None:
        return out
    valid_txhs = [
        txh
        for txh in (meta_doc.get("tx_hashes") or [])[:4]
        if isinstance(txh, str) and txh.startswith("0x") and len(txh) == 66
    ]
    if valid_txhs:
        rcpts: List[Any] = []
        batch_fn = getattr(router, "batch_call", None)
        if len(valid_txhs) >= 2 and callable(batch_fn):
            try:
                rcpts = list(
                    batch_fn(
                        chain,
                        [("eth_getTransactionReceipt", [th]) for th in valid_txhs],
                        timeout=5.0,
                    )
                    or ()
                )
            except Exception:
                rcpts = []
        if not rcpts:
            for txh in valid_txhs:
                try:
                    rcpts.append(router.call(chain, "eth_getTransactionReceipt", [txh], timeout=5.0))
                except Exception:
                    rcpts.append(None)
        for rcpt in rcpts:
            if isinstance(rcpt, dict) and isinstance(rcpt.get("blockNumber"), str):
                r_bn = _hex_to_int(rcpt.get("blockNumber"))
                if r_bn >= 1 and (hi_block <= 0 or r_bn <= hi_block):
                    for cand_hb in (max(1, r_bn - 1), r_bn):
                        _append_unique(out, seen, cand_hb)
    return out


_PURE_PROXY_ADMIN_SELECTORS: FrozenSet[str] = frozenset({
    "3659cfe6",  # upgradeTo(address)
    "4f1ef286",  # upgradeToAndCall(address,bytes)
    "f851a440",  # admin()
    "5c60da1b",  # implementation()
    "8f283970",  # changeAdmin(address)
    "52d1902d",  # proxiableUUID()
    "452a9320",  # masterCopy() / implementation()
    "a619486e",  # masterCopy() (SafeProxy)
    "da35c664",  # beacon()
    "be121429",  # setBeacon(address,bytes)
})


def _is_pure_proxy_shell_bytecode(code_b: bytes) -> bool:
    """
    원천 시드 바이트코드가 고유 프로토콜 비즈니스 로직 없는 순수 범용 프록시 껍데기
    (EIP-1167, EIP-7702, OpenZeppelin ERC1967Proxy / TransparentUpgradeableProxy / BeaconProxy, SafeProxy 등)인지 판별:
    - 구현체 바이트코드가 확보된 경우 이 범용 껍데기를 `seed_variants`에서 배제하여 수백만 무관 프록시 오탐 오염을 원천 차단한다.
    """
    if not code_b:
        return False
    if _eip1167_impl(code_b) or _eip7702_delegate(code_b):
        return True
    clean_b = _strip_cbor_bytes(code_b)
    if len(clean_b) == 0 or len(clean_b) > 2400:
        return False
    dis = _disassemble(clean_b)
    if not any(nm == "DELEGATECALL" for _, nm, _ in dis):
        return False
    if any(nm in ("CALL", "CREATE", "CREATE2", "SELFDESTRUCT") for _, nm, _ in dis):
        return False
    n_d = len(dis)
    for idx_d, (_, nm, imm) in enumerate(dis):
        if nm == "PUSH4" and len(imm) == 4 and imm not in (
            b"\x00\x00\x00\x00",
            b"\xff\xff\xff\xff",
            b"\x4e\x48\x7b\x71",
            b"\x08\xc3\x79\xa0",
        ):
            if any(dis[j][1] in ("EQ", "SUB", "XOR", "GT", "LT") for j in range(idx_d + 1, min(n_d, idx_d + 4))):
                if imm.hex().lower() not in _PURE_PROXY_ADMIN_SELECTORS:
                    return False
    return True


def _is_delegatecall_or_thin_proxy(code_b: bytes) -> bool:
    """로컬 바이트코드가 얇은 프록시 셸(<768B)이거나 DELEGATECALL 옵코드를 포함하는지 판별."""
    if not code_b:
        return False
    clean_b = _strip_cbor_bytes(code_b)
    if len(clean_b) < 768:
        return True
    return any(nm == "DELEGATECALL" for _, nm, _ in _disassemble(clean_b))


def _recover_historical_bytecode_bisect(
    router: RPCRouter,
    chain: str,
    address: str,
    hi_block: int,
    hint_blocks: Optional[Sequence[int]] = None,
) -> bytes:
    """
    Mode B 전용 과거 바이트코드 역추적기:
    - 현재 블록(hi_block)에서 SELFDESTRUCT 또는 빈 코드로 초기화된 과거 사건 시드 주소에 대해
      사건 블록 단서(hint_blocks) 우선 프로브 + 지수 백오프 프로브(최대 12회 아카이브 eth_getCode)로 파괴 직전 런타임 바이트코드를 복원한다.
    """
    addr = _norm_addr(address)
    if not addr or hi_block <= 1:
        return b""
    c = _norm_chain(chain)
    probe_blocks, _ = _collect_hint_probe_blocks(hint_blocks, hi_block)
    seen_pb: Set[int] = set(probe_blocks)
    for fine_step in (250, 1_500):
        if fine_step < hi_block:
            _append_unique(probe_blocks, seen_pb, max(1, hi_block - fine_step))
    step = 10_000
    while step < hi_block:
        _append_unique(probe_blocks, seen_pb, max(1, hi_block - step))
        step *= 8
    for frac in (hi_block * 3 // 4, hi_block // 2, hi_block // 4):
        if 1 <= frac < hi_block:
            _append_unique(probe_blocks, seen_pb, frac)
    if probe_blocks:
        cs_addr = _checksum(addr)
        try:
            b_res = router.batch_call(
                c,
                [("eth_getCode", [cs_addr, hex(int(pb))]) for pb in probe_blocks],
                block_pin=hi_block,
                need_archive=True,
            )
            for rhex in b_res or ():
                cb = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
                if len(cb) > 0:
                    return cb
        except Exception:
            for pb in probe_blocks:
                try:
                    rhex = router.call(c, "eth_getCode", [cs_addr, hex(int(pb))], block_pin=pb, need_archive=True, timeout=6.0)
                    cb = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
                    if len(cb) > 0:
                        return cb
                except Exception:
                    continue
    return b""


def _recover_historical_proxy_impl_bytecodes(
    router: RPCRouter,
    chain: str,
    address: str,
    hi_block: int,
    hint_blocks: Optional[Sequence[int]] = None,
) -> List[bytes]:
    """
    Mode B 전용 프록시 과거 구현체(Implementation) 바이트코드 역추적기:
    - 사후 업그레이드(패치)된 프록시 시드에 대해 사건 블록 단서(hint_blocks) 및 과거 블록 스냅샷의
      EIP-1967(impl/beacon/Upgraded 로그) / EIP-1822 / ZeppelinOS / Safe slot0 슬롯 및
      EIP-7702 위임 코드를 아카이브 배치 프로빙하여 패치 이전 구현체 바이트코드까지 함께 복원한다.
    """
    addr = _norm_addr(address)
    if not addr or hi_block <= 1:
        return []
    c = _norm_chain(chain)
    init_probe_blocks, valid_hints = _collect_hint_probe_blocks(hint_blocks, hi_block, pre_first=True)
    probe_blocks: deque[int] = deque(init_probe_blocks)
    seen_pb: Set[int] = set(init_probe_blocks)
    for step in (5_000, 40_000, 320_000, hi_block // 2):
        if 1 <= hi_block - step < hi_block:
            cand_pb = max(1, hi_block - step)
            if cand_pb not in seen_pb:
                seen_pb.add(cand_pb)
                probe_blocks.append(cand_pb)
    seen_impls: Set[str] = set()
    out_codes: List[bytes] = []
    direct_slots = (EIP1967_SLOTS["impl"], EIP1822_SLOT, ZOS_SLOTS["impl"])
    beacon_slot = EIP1967_SLOTS["beacon"]
    zero_slot = "0x" + ("00" * 32)
    chk_addr = _checksum(addr)

    upgrade_t0s = [
        EIP1967_UPGRADED_TOPIC0,
        BEACON_UPGRADED_TOPIC0,
        DIAMOND_CUT_TOPIC0,
    ]
    log_windows: List[Tuple[int, int]] = [
        (max(1, hb_log - 2_000), min(hi_block, hb_log + 200)) for hb_log in valid_hints
    ]
    if not log_windows:
        log_windows.append((max(1, hi_block - 50_000), hi_block))

    def _fetch_upgrade_logs_win(win_pair: Tuple[int, int]) -> Tuple[int, List[Any]]:
        w_from, w_to = win_pair
        try:
            res_l = router.call(
                c,
                "eth_getLogs",
                [
                    {
                        "address": chk_addr,
                        "fromBlock": hex(w_from),
                        "toBlock": hex(w_to),
                        "topics": [upgrade_t0s],
                    }
                ],
                block_pin=w_to,
                need_archive=True,
                timeout=5.0,
            )
            return w_to, (res_l if isinstance(res_l, list) else [])
        except Exception:
            return w_to, []

    log_code_queries: List[Tuple[str, int]] = []
    diamond_t0 = DIAMOND_CUT_TOPIC0.lower()
    for w_to, logs in _map_chunks_live(router, _fetch_upgrade_logs_win, log_windows, max_workers=6):
        for lg in logs:
            if not isinstance(lg, dict):
                continue
            log_b = _hex_to_int(lg.get("blockNumber"))
            if 1 < log_b <= hi_block:
                pre_b = log_b - 1
                if pre_b not in seen_pb:
                    seen_pb.add(pre_b)
                    probe_blocks.appendleft(pre_b)
            tops = lg.get("topics") or []
            log_cands: List[str] = []
            if tops and str(tops[0]).lower() == diamond_t0:
                try:
                    d_cuts, d_init, _ = abi_decode(
                        ["(address,uint8,bytes4[])[]", "address", "bytes"],
                        _hex_to_bytes(lg.get("data")),
                    )
                    for f_item in d_cuts or []:
                        if isinstance(f_item, (list, tuple)) and f_item:
                            fa = _norm_addr(f_item[0])
                            if _is_non_precompile_addr(fa):
                                log_cands.append(fa)
                    init_a = _norm_addr(d_init)
                    if _is_non_precompile_addr(init_a):
                        log_cands.append(init_a)
                except _PARSE_DATA_EXC:
                    pass
            cand_u = _extract_word32_address(tops[1]) if len(tops) >= 2 else _extract_word32_address(lg.get("data"))
            if cand_u:
                log_cands.append(cand_u)
            q_blk = log_b if (1 <= log_b <= hi_block) else w_to
            for cu_item in dict.fromkeys(log_cands):
                if cu_item and cu_item not in seen_impls:
                    seen_impls.add(cu_item)
                    log_code_queries.append((cu_item, q_blk))

    if log_code_queries:
        try:
            lq_res = router.batch_call(
                c,
                [("eth_getCode", [_checksum(cu_i), hex(qb_i)]) for cu_i, qb_i in log_code_queries],
                block_pin=hi_block,
                need_archive=True,
            )
            for rhex_u in lq_res or ():
                cb_u = _hex_to_bytes(rhex_u) if isinstance(rhex_u, str) else b""
                if len(cb_u) >= 16:
                    out_codes.append(cb_u)
        except _RECOVERABLE_IO_EXC:
            pass

    def _probe_hist_block(pb: int) -> Tuple[int, List[str]]:
        btag = hex(int(pb))
        cand_impls: List[str] = []
        try:
            batch_reqs: List[Tuple[str, Any]] = [
                ("eth_getStorageAt", [chk_addr, sl, btag]) for sl in (*direct_slots, beacon_slot, zero_slot)
            ]
            batch_reqs.append(("eth_getCode", [chk_addr, btag]))
            res_list = router.batch_call(c, batch_reqs, block_pin=pb, need_archive=True)
            if not isinstance(res_list, list) or len(res_list) < 6:
                return pb, cand_impls
            proxy_hist_code = _hex_to_bytes(res_list[5]) if isinstance(res_list[5], str) else b""
            for raw_s in res_list[:3]:
                ia = _extract_word32_address(raw_s)
                if ia:
                    cand_impls.append(ia)
            beacon_a = _extract_word32_address(res_list[3])
            has_dc_hist = bool(proxy_hist_code and any(nm == "DELEGATECALL" for _, nm, _ in _disassemble(proxy_hist_code)))
            eth_call_reqs: List[Tuple[str, Any]] = []
            eth_call_tags: List[str] = []
            if beacon_a:
                eth_call_reqs.append(("eth_call", [{"to": _checksum(beacon_a), "data": "0x5c60da1b"}, btag]))
                eth_call_tags.append("beacon")
            if has_dc_hist:
                eth_call_reqs.append(("eth_call", [{"to": chk_addr, "data": LOUPE_FACETS_SEL}, btag]))
                eth_call_tags.append("loupe_facets")
                eth_call_reqs.append(("eth_call", [{"to": chk_addr, "data": LOUPE_FACET_ADDRS_SEL}, btag]))
                eth_call_tags.append("loupe_addrs")
            if eth_call_reqs:
                try:
                    ec_res = router.batch_call(c, eth_call_reqs, block_pin=pb, need_archive=True)
                    for tag_ec, val_ec in zip(eth_call_tags, ec_res or ()):
                        if tag_ec == "beacon":
                            b_ia = _extract_word32_address(val_ec)
                            if b_ia:
                                cand_impls.append(b_ia)
                        elif tag_ec == "loupe_facets":
                            cand_impls.extend(_decode_diamond_facets(val_ec))
                        elif tag_ec == "loupe_addrs":
                            cand_impls.extend(_decode_diamond_facet_addresses_checked(val_ec)[0])
                except _RECOVERABLE_IO_EXC:
                    pass
            if _slot0_safe_proxy_shape(proxy_hist_code):
                s0_a = _extract_word32_address(res_list[4])
                if s0_a:
                    cand_impls.append(s0_a)
            d1167 = _eip1167_impl(proxy_hist_code)
            if _is_non_precompile_addr(d1167):
                cand_impls.append(d1167)
            d7702 = _eip7702_delegate(proxy_hist_code)
            if _is_non_precompile_addr(d7702):
                cand_impls.append(d7702)
        except _RECOVERABLE_IO_EXC:
            pass
        return pb, cand_impls

    hist_code_queries: List[Tuple[str, int]] = []
    for pb_i, cand_impls in _map_chunks_live(router, _probe_hist_block, list(probe_blocks), max_workers=6):
        for ia in dict.fromkeys(cand_impls):
            if ia not in seen_impls:
                seen_impls.add(ia)
                hist_code_queries.append((ia, pb_i))
    if hist_code_queries:
        try:
            code_res = router.batch_call(
                c,
                [("eth_getCode", [_checksum(ia), hex(int(pb_i))]) for ia, pb_i in hist_code_queries],
                block_pin=hi_block,
                need_archive=True,
            )
            for rhex in code_res or ():
                cb = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
                if len(cb) >= 16:
                    out_codes.append(cb)
        except _RECOVERABLE_IO_EXC:
            pass
    return out_codes


def _extract_word32_address(raw_val: Any) -> str:
    if isinstance(raw_val, str):
        try:
            word_b = _hex_to_word32(raw_val)
        except Exception:
            return ""
    elif isinstance(raw_val, (bytes, bytearray)) and len(raw_val) == 32:
        word_b = bytes(raw_val)
    else:
        return ""
    if word_b[:12] != b"\x00" * 12:
        return ""
    cand = _norm_addr("0x" + word_b[12:32].hex())
    return cand if _is_non_precompile_addr(cand) else ""


def _extract_addr_candidates_from_word_or_array(rdata: bytes) -> List[str]:
    """ABI 32바이트 단일 address, 동적 address[], 또는 소형 정적 튜플에서 유효 EVM 주소를 중복 없이 추출."""
    if not rdata or len(rdata) < 32:
        return []
    if len(rdata) == 32:
        cand = _extract_word32_address(rdata)
        return [cand] if cand else []
    out: List[str] = []
    seen: Set[str] = set()
    if len(rdata) >= 96 and int.from_bytes(rdata[0:32], "big") == 32:
        cnt = int.from_bytes(rdata[32:64], "big")
        if 1 <= cnt <= 32 and 64 + cnt * 32 <= len(rdata):
            for idx_el in range(cnt):
                cand = _extract_word32_address(rdata[64 + idx_el * 32 : 96 + idx_el * 32])
                if cand and cand not in seen:
                    seen.add(cand)
                    out.append(cand)
            if out:
                return out
    if len(rdata) <= 160 and len(rdata) % 32 == 0:
        for off_w in range(0, len(rdata), 32):
            cand = _extract_word32_address(rdata[off_w : off_w + 32])
            if cand and cand not in seen:
                seen.add(cand)
                out.append(cand)
    return out


_IMMUTABLE_CODE_CACHE: Dict[
    Tuple[int, str],
    Tuple[int, bytes, List[Tuple[int, str, bytes]], bool, Optional[Tuple[str, str]]],
] = {}
_IMMUTABLE_CODE_CACHE_LOCK = threading.Lock()


def _classify_immutable_code_entry(
    raw_c: bytes,
) -> Tuple[List[Tuple[int, str, bytes]], bool, Optional[Tuple[str, str]], bool]:
    dis_a = _disassemble(raw_c) if raw_c else []
    if not raw_c:
        return dis_a, False, None, False
    d7702 = _eip7702_delegate(raw_c)
    if d7702:
        return dis_a, False, ("eip7702", d7702), False
    d1167 = _eip1167_impl(raw_c)
    if d1167:
        return dis_a, False, ("eip1167", d1167), True
    has_dc_cc = False
    has_sd = False
    for _, nm, _ in dis_a:
        if nm in ("DELEGATECALL", "CALLCODE"):
            has_dc_cc = True
        elif nm == "SELFDESTRUCT":
            has_sd = True
    is_imm = len(raw_c) > 23 and (not has_sd)
    return dis_a, has_dc_cc, None, is_imm


def _resolve_proxy_and_delegates(
    router: RPCRouter,
    chain: str,
    addrs: Union[str, Sequence[str]],
    block_pin: int,
    raise_on_rpc_failure: bool = False,
) -> Dict[str, ProxyResolution]:
    addr_iter: Sequence[str] = [addrs] if isinstance(addrs, str) else addrs
    norm_list = sorted({na for a in addr_iter if (na := _norm_addr(a))})
    if not norm_list:
        return {}
    btag = hex(int(block_pin)) if block_pin > 0 else "latest"
    cid_rp = CHAIN_IDS.get(_norm_chain(chain), 0)
    use_imm_cache = bool(block_pin > 0 and cid_rp > 0 and _is_live_real_router(router))
    code_map: Dict[str, bytes] = {}
    dis_cache: Dict[str, List[Tuple[int, str, bytes]]] = {}
    static_proxy_map: Dict[str, Tuple[str, str]] = {}
    has_dc_map: Dict[str, bool] = {}
    rpc_need_addrs: List[str] = []

    if use_imm_cache:
        ram_misses: List[str] = []
        with _IMMUTABLE_CODE_CACHE_LOCK:
            for a in norm_list:
                hit_ic = _IMMUTABLE_CODE_CACHE.get((cid_rp, a))
                if hit_ic is not None and hit_ic[0] <= block_pin:
                    _, raw_c_h, dis_h, hdc_h, sp_h = hit_ic
                    code_map[a] = raw_c_h
                    dis_cache[a] = dis_h
                    has_dc_map[a] = hdc_h
                    if sp_h is not None:
                        static_proxy_map[a] = sp_h
                else:
                    ram_misses.append(a)
        db_hits: Set[str] = set()
        r_store_rp = getattr(router, "store", None)
        if ram_misses and r_store_rp is not None:
            try:
                for chunk_i in range(0, len(ram_misses), 200):
                    sub_a = ram_misses[chunk_i : chunk_i + 200]
                    ph = ",".join("?" * len(sub_a))
                    with r_store_rp._read_conn() as rc_ic:
                        rows_ic = rc_ic.execute(
                            f"SELECT c.address, MIN(c.audit_block), c.raw_code_hex FROM contract_code c "
                            f"WHERE c.chain_id=? AND c.audit_block>0 AND c.audit_block<=? AND c.address IN ({ph}) "
                            f"AND c.proxy_kind IN ('none', 'implementation') AND c.impl_addrs_json IN ('', '[]') "
                            f"AND length(c.raw_code_hex)>48 "
                            f"AND NOT EXISTS ("
                            f"SELECT 1 FROM contract_code p "
                            f"WHERE p.chain_id=c.chain_id AND p.address=c.address "
                            f"AND p.proxy_kind NOT IN ('none', 'implementation')"
                            f") "
                            f"GROUP BY c.address",
                            [cid_rp, int(block_pin), *sub_a],
                        ).fetchall()
                    for row_ic in rows_ic:
                        a_ic = _norm_addr(str(row_ic[0] or ""))
                        blk_ic = int(row_ic[1] or 0)
                        raw_c_ic = _hex_to_bytes(str(row_ic[2] or ""))
                        if not a_ic or blk_ic <= 0 or len(raw_c_ic) <= 23:
                            continue
                        dis_ic, hdc_ic, sp_ic, is_imm_ic = _classify_immutable_code_entry(raw_c_ic)
                        if not is_imm_ic or hdc_ic:
                            continue
                        code_map[a_ic] = raw_c_ic
                        dis_cache[a_ic] = dis_ic
                        has_dc_map[a_ic] = hdc_ic
                        if sp_ic is not None:
                            static_proxy_map[a_ic] = sp_ic
                        db_hits.add(a_ic)
                        _put_immutable_code_cache(cid_rp, a_ic, blk_ic, raw_c_ic, dis_ic, hdc_ic, sp_ic)
            except _RECOVERABLE_IO_EXC:
                pass
        rpc_need_addrs = [a for a in ram_misses if a not in db_hits]
    else:
        rpc_need_addrs = list(norm_list)

    code_rpc_failed: Set[str] = set()
    if rpc_need_addrs:
        code_calls = [("eth_getCode", [_checksum(a), btag]) for a in rpc_need_addrs]
        code_res = router.batch_call(
            chain,
            code_calls,
            block_pin=block_pin,
            need_archive=True,
            raise_on_all_failed=raise_on_rpc_failure,
        )
        failed_idxs = [
            idx_a for idx_a in range(len(rpc_need_addrs))
            if not (idx_a < len(code_res) and isinstance(code_res[idx_a], str))
        ]
        retry_map: Dict[int, Any] = {}
        if failed_idxs:
            def _retry_get_code(idx_r: int) -> Tuple[int, Any]:
                try:
                    return idx_r, router.call(
                        chain,
                        "eth_getCode",
                        [_checksum(rpc_need_addrs[idx_r]), btag],
                        block_pin=block_pin,
                        need_archive=True,
                    )
                except Exception:
                    return idx_r, None

            for idx_r, val_r in _map_chunks_live(router, _retry_get_code, failed_idxs, max_workers=12):
                retry_map[idx_r] = val_r
        for idx_a, a in enumerate(rpc_need_addrs):
            raw_hex = code_res[idx_a] if idx_a < len(code_res) else None
            if not isinstance(raw_hex, str):
                raw_hex = retry_map.get(idx_a)
            if raise_on_rpc_failure and not isinstance(raw_hex, str):
                raise RuntimeError(f"RPC eth_getCode failed for {a} on {chain}")
            if isinstance(raw_hex, str):
                raw_c_f = _hex_to_bytes(raw_hex)
                code_map[a] = raw_c_f
                dis_f, hdc_f, sp_f, is_imm_f = _classify_immutable_code_entry(raw_c_f)
                dis_cache[a] = dis_f
                has_dc_map[a] = hdc_f
                if sp_f is not None:
                    static_proxy_map[a] = sp_f
                if use_imm_cache and is_imm_f:
                    _put_immutable_code_cache(cid_rp, a, block_pin, raw_c_f, dis_f, hdc_f, sp_f)
            else:
                code_rpc_failed.add(a)
                code_map[a] = b""
                dis_cache[a] = []
                has_dc_map[a] = False

    # 바이트코드 사전 분해: DELEGATECALL/CALLCODE 미보유 또는 정적 EIP-7702/1167은 불필요한 7슬롯 RPC 조회 생략 (무손실)
    slot_keys = [
        ("impl_1967", EIP1967_SLOTS["impl"]),
        ("beacon_1967", EIP1967_SLOTS["beacon"]),
        ("admin_1967", EIP1967_SLOTS["admin"]),
        ("impl_1822", EIP1822_SLOT),
        ("impl_zos", ZOS_SLOTS["impl"]),
        ("admin_zos", ZOS_SLOTS["admin"]),
        ("slot0", "0x0"),
    ]
    storage_calls: List[Tuple[str, List[Any]]] = []
    storage_index: List[Tuple[str, str]] = []
    for a in norm_list:
        if not code_map.get(a, b"") or a in static_proxy_map or not has_dc_map.get(a, False):
            continue
        for sk_name, sk_hex in slot_keys:
            storage_calls.append(("eth_getStorageAt", [_checksum(a), sk_hex, btag]))
            storage_index.append((a, sk_name))
    storage_res = router.batch_call(chain, storage_calls, block_pin=block_pin, need_archive=True) if storage_calls else []
    slot_vals: Dict[str, Dict[str, str]] = {a: {} for a in norm_list}
    slot_rpc_failed: Set[str] = set()
    if len(storage_res) < len(storage_index):
        for a, _ in storage_index[len(storage_res) :]:
            slot_rpc_failed.add(a)
    for (a, sk_name), sval in zip(storage_index, storage_res):
        if not isinstance(sval, str) or not sval.startswith("0x"):
            slot_rpc_failed.add(a)
            continue
        cand = _extract_word32_address(sval)
        if cand and cand != a:
            slot_vals[a][sk_name] = cand

    out: Dict[str, ProxyResolution] = {}
    extra_impl_to_fetch: Set[str] = set()
    prelim: Dict[str, Tuple[str, List[str], str]] = {}

    # 1차 슬롯/바이트코드 기반 판정 + Beacon/Diamond/커스텀 게터 프록시 단일 배치 프로브 수집
    probe_mc_calls: List[Tuple[str, bytes]] = []
    probe_mc_meta: List[Tuple[str, str]] = []
    pending_beacon: Set[str] = set()
    has_unresolved_hop_or_beacon: Set[str] = set()

    for a in norm_list:
        raw_code = code_map.get(a, b"")
        dis = dis_cache.get(a, [])
        p_kind = "none"
        impls: List[str] = []
        sv = slot_vals.get(a, {})
        admin = sv.get("admin_1967") or sv.get("admin_zos") or ""

        sp_hit = static_proxy_map.get(a)
        if sp_hit is not None:
            p_kind, sp_impl = sp_hit
            impls = [sp_impl]
        else:
            for k in ("impl_1967", "impl_1822", "impl_zos"):
                if sv.get(k):
                    p_kind = k
                    impls = [sv[k]]
                    break
            if not impls and sv.get("beacon_1967"):
                pending_beacon.add(a)
                probe_mc_calls.append((sv["beacon_1967"], bytes.fromhex(IMPL_GETTER_SEL[2:])))
                probe_mc_meta.append((a, "beacon_1967"))
            if not impls and sv.get("slot0") and _slot0_safe_proxy_shape(raw_code, dis):
                p_kind = "slot0_safe"
                impls = [sv["slot0"]]
            if not impls and any(nm == "DELEGATECALL" for _, nm, _ in dis):
                probe_mc_calls.append((a, bytes.fromhex(LOUPE_FACETS_SEL[2:])))
                probe_mc_meta.append((a, "diamond_2535"))
                probe_mc_calls.append((a, bytes.fromhex(LOUPE_FACET_ADDRS_SEL[2:])))
                probe_mc_meta.append((a, "diamond_2535_addrs"))
                for g_kind, g_sel in (
                    ("getter_impl", IMPL_GETTER_SEL),
                    ("getter_master_copy", MASTER_COPY_SEL),
                    ("getter_comptroller", COMPTROLLER_IMPL_SEL),
                ):
                    probe_mc_calls.append((a, bytes.fromhex(g_sel[2:])))
                    probe_mc_meta.append((a, g_kind))

        prelim[a] = (p_kind, impls, admin)

    if probe_mc_calls:
        probe_res = router.multicall3(chain, probe_mc_calls, block_pin=block_pin)
        probe_tls = getattr(router, "_tls", None)
        if len(probe_res) < len(probe_mc_calls) or (
            probe_tls is not None and bool(getattr(probe_tls, "last_multicall_transport_failed", False))
        ):
            for a_pm, _ in probe_mc_meta:
                has_unresolved_hop_or_beacon.add(a_pm)
        for (a, probe_kind), (ok_p, ret_p) in zip(probe_mc_meta, probe_res):
            if not ok_p or not ret_p:
                continue
            cur_kind, cur_impls, cur_admin = prelim[a]
            if probe_kind in ("diamond_2535", "diamond_2535_addrs"):
                if cur_impls and cur_kind != "diamond_2535":
                    continue
                if probe_kind == "diamond_2535":
                    facets, bad_fac = _decode_diamond_facets_checked(ret_p)
                else:
                    facets, bad_fac = _decode_diamond_facet_addresses_checked(ret_p)
                if bad_fac:
                    has_unresolved_hop_or_beacon.add(a)
                if facets:
                    merged_f = list(dict.fromkeys([*cur_impls, *facets]))
                    prelim[a] = ("diamond_2535", merged_f, cur_admin)
                continue
            if cur_impls:
                continue
            if len(ret_p) >= 32 and ret_p[:12] == b"\x00" * 12:
                g_impl = _norm_addr("0x" + ret_p[12:32].hex())
                if _is_non_precompile_addr(g_impl) and g_impl != a:
                    prelim[a] = (probe_kind, [g_impl], cur_admin)

    for b_addr in sorted(pending_beacon):
        if not prelim[b_addr][1]:
            has_unresolved_hop_or_beacon.add(b_addr)

    for a, (_pk, im_list, _adm) in prelim.items():
        for im in im_list:
            if im not in code_map:
                extra_impl_to_fetch.add(im)

    # 최대 8홉 위임 체인(EIP-7702 -> EIP-1167 등) 바이트코드 일괄 수집 (불변 캐시 우선 재사용)
    for _hop in range(8):
        if not extra_impl_to_fetch:
            break
        extra_list_all = sorted(extra_impl_to_fetch)
        extra_impl_to_fetch = set()
        extra_list: List[str] = []
        if use_imm_cache:
            with _IMMUTABLE_CODE_CACHE_LOCK:
                for x_c in extra_list_all:
                    hit_ex = _IMMUTABLE_CODE_CACHE.get((cid_rp, x_c))
                    if hit_ex is not None and hit_ex[0] <= block_pin:
                        cbytes_h = hit_ex[1]
                        code_map[x_c] = cbytes_h
                        next_hop_h = _eip7702_delegate(cbytes_h) or _eip1167_impl(cbytes_h)
                        if next_hop_h and next_hop_h not in code_map:
                            extra_impl_to_fetch.add(next_hop_h)
                    else:
                        extra_list.append(x_c)
        else:
            extra_list = extra_list_all
        if not extra_list:
            continue
        extra_res = router.batch_call(
            chain,
            [("eth_getCode", [_checksum(x), btag]) for x in extra_list],
            block_pin=block_pin,
            need_archive=True,
        )
        if len(extra_res) < len(extra_list):
            for x_miss in extra_list[len(extra_res) :]:
                code_rpc_failed.add(x_miss)
                code_map[x_miss] = b""
        for x, rhex in zip(extra_list, extra_res):
            if not isinstance(rhex, str):
                code_rpc_failed.add(x)
            cbytes = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
            code_map[x] = cbytes
            if use_imm_cache and len(cbytes) > 23:
                dis_ex, hdc_ex, sp_ex, is_imm_ex = _classify_immutable_code_entry(cbytes)
                if is_imm_ex:
                    _put_immutable_code_cache(cid_rp, x, block_pin, cbytes, dis_ex, hdc_ex, sp_ex)
            next_hop = _eip7702_delegate(cbytes) or _eip1167_impl(cbytes)
            if next_hop and next_hop not in code_map:
                extra_impl_to_fetch.add(next_hop)

    cid = CHAIN_IDS.get(_norm_chain(chain), 0)
    eip6780 = _probe_cancun_eip6780(router, chain, block_pin)
    code_rows_to_put: List[Tuple[int, str, int, str, str, str, str, str, List[str], bool]] = []

    for a in norm_list:
        raw_code = code_map.get(a, b"")
        p_kind, impls, admin = prelim[a]
        resolved_impls: List[str] = []
        seen_res_impls: Set[str] = set()
        for im in impls:
            cur = im
            seen_hops: Set[str] = {a}
            hop_broken = False
            for _ in range(8):
                if cur in seen_hops:
                    hop_broken = True
                    break
                seen_hops.add(cur)
                cb = code_map.get(cur, b"")
                if len(cb) == 0:
                    hop_broken = True
                    break
                nh = _eip7702_delegate(cb) or _eip1167_impl(cb)
                if nh:
                    if nh in seen_hops:
                        hop_broken = True
                        break
                    if len(code_map.get(nh, b"")) > 0 or p_kind == "eip7702":
                        cur = nh
                    else:
                        hop_broken = True
                        break
                else:
                    break
            else:
                cb_tail = code_map.get(cur, b"")
                if _eip7702_delegate(cb_tail) or _eip1167_impl(cb_tail):
                    hop_broken = True
            if hop_broken:
                has_unresolved_hop_or_beacon.add(a)
            if len(code_map.get(cur, b"")) > 0 or p_kind == "eip7702":
                _append_unique(resolved_impls, seen_res_impls, cur)

        proxy_dis = dis_cache.get(a) or []
        unresolved_deleg = bool(
            a in has_unresolved_hop_or_beacon
            or a in code_rpc_failed
            or a in slot_rpc_failed
            or any(im in code_rpc_failed for im in [*impls, *resolved_impls])
            or (
                bool(impls)
                and (not resolved_impls or any(len(code_map.get(im, b"")) == 0 for im in impls))
            )
        )
        if p_kind != "none" and not resolved_impls:
            p_kind = "none"

        impl_codes_hex: Dict[str, str] = {}
        collisions_set: Set[int] = set()
        raw_hex = "0x" + raw_code.hex() if raw_code else "0x"
        r_store = getattr(router, "store", None)
        # 비최소 프록시(Transparent/UUPS/Unitroller/Custom)의 자체 디스패처·관리자 함수도 누락 없이 감사 대상에 포함
        if resolved_impls and p_kind not in ("none", "eip1167", "eip7702") and len(raw_code) > 45:
            impl_codes_hex[a] = raw_hex
        for im in resolved_impls:
            ibytes = code_map.get(im, b"")
            if ibytes:
                ihex = "0x" + ibytes.hex()
                impl_codes_hex[im] = ihex
                if proxy_dis and im != a:
                    collisions_set |= _detect_storage_slot_collision(
                        proxy_dis,
                        _disassemble(ibytes),
                        exclude_slot0=(p_kind in ("slot0_safe", "getter_master_copy")),
                    )
                if r_store is not None and im != a:
                    code_rows_to_put.append((
                        cid,
                        im,
                        block_pin,
                        _keccak256_hex(ibytes),
                        _skeleton_hash(ibytes),
                        ",".join(sorted(_opcode_4grams(ibytes, cap=128))),
                        ihex,
                        "implementation",
                        [],
                        eip6780,
                    ))

        if p_kind == "eip7702":
            eff_bytes = code_map.get(resolved_impls[0], b"") if resolved_impls else b""
        else:
            eff_bytes = code_map[resolved_impls[0]] if resolved_impls else raw_code
        eff_hex = "0x" + eff_bytes.hex() if eff_bytes else "0x"
        if not impl_codes_hex and eff_bytes:
            impl_codes_hex[a] = eff_hex
        skel = _skeleton_hash(eff_bytes)
        grams = ",".join(sorted(_opcode_4grams(eff_bytes, cap=128)))
        if r_store is not None:
            code_rows_to_put.append((
                cid,
                a,
                block_pin,
                _keccak256_hex(eff_bytes),
                skel,
                grams,
                eff_hex,
                p_kind,
                resolved_impls,
                eip6780,
            ))
        beacon_addr = slot_vals.get(a, {}).get("beacon_1967") or ""
        out[a] = ProxyResolution(
            address=a,
            proxy_kind=p_kind,
            impl_addresses=resolved_impls,
            admin_address=admin,
            raw_code_hex=raw_hex,
            effective_code_hex=eff_hex,
            skeleton_hash=skel,
            slot_collisions=sorted(collisions_set),
            impl_codes_hex=impl_codes_hex,
            unresolved_delegation=unresolved_deleg,
            beacon_address=beacon_addr,
        )

    r_store_fin = getattr(router, "store", None)
    if r_store_fin is not None and code_rows_to_put:
        r_store_fin.put_contract_code_batch(code_rows_to_put)
    return out


def _probe_cancun_eip6780(router: RPCRouter, chain: str, block_pin: int) -> bool:
    """Cancun EIP-6780 활성화 여부 확인: 표준 Cancun 체인은 즉시 True, 기타 체인은 블록 헤더 Cancun 필드 프로브."""
    c = _norm_chain(chain)
    if c in (
        "ethereum", "arbitrum", "base", "optimism", "polygon", "bsc", "avalanche",
        "gnosis", "sonic", "unichain", "berachain", "monad", "megaeth", "hyperevm",
        "worldchain", "ink", "scroll", "linea", "zksync", "mantle", "blast", "mode",
    ):
        return True
    if block_pin <= 0:
        return True
    try:
        blk = router.call(c, "eth_getBlockByNumber", [hex(int(block_pin)), False], block_pin=block_pin, timeout=5.0)
        if isinstance(blk, dict):
            return any(k in blk for k in ("excessBlobGas", "blobGasUsed", "parentBeaconBlockRoot", "withdrawalsRoot"))
    except _RECOVERABLE_IO_EXC:
        pass
    return False

# ═══════════════════════════════════════════════════════════════════════════
# §4-B. 개념 기반 다중 홉 연결 가치 폐포 (Connected Value Reachability Closure)
#       ※ 핵심 원칙: 잔고 $0 컨트랙트(라우터/어댑터/컨트롤러/전략/헬퍼)가 외부 진입점이고
#          연결된 금고/풀/알로원스/동적 외부 CALL을 통해 이익이 창출되는 구조를 절대 잔고 필터로 탈락시키지 않음!
# ═══════════════════════════════════════════════════════════════════════════


def _put_immutable_code_cache(
    cid_rp: int,
    addr_k: str,
    block_pin: int,
    raw_c: bytes,
    dis_c: List[Tuple[int, str, bytes]],
    hdc_c: bool,
    sp_c: Optional[Tuple[str, str]],
) -> None:
    with _IMMUTABLE_CODE_CACHE_LOCK:
        if len(_IMMUTABLE_CODE_CACHE) >= 4096:
            _IMMUTABLE_CODE_CACHE.clear()
        _IMMUTABLE_CODE_CACHE[(cid_rp, addr_k)] = (int(block_pin), raw_c, dis_c, hdc_c, sp_c)


@dataclass
class VaultExposure:
    address: str
    native_wei: int = 0
    native_usd: Decimal = _DEC_ZERO
    token_balances: Dict[str, int] = field(default_factory=dict)
    token_usd: Dict[str, Decimal] = field(default_factory=dict)
    allowance_usd: Decimal = _DEC_ZERO
    total_usd: Decimal = _DEC_ZERO
    allowance_usd_dec: str = "0"
    total_usd_dec: str = "0"
    native_usd_dec: str = "0"
    token_usd_dec: Dict[str, str] = field(default_factory=dict)


def _ve_native_dec(ve: VaultExposure) -> Decimal:
    return _to_dec(ve.native_usd_dec if ve.native_usd_dec not in ("", "0") else ve.native_usd)


def _ve_allow_dec(ve: VaultExposure) -> Decimal:
    return _to_dec(ve.allowance_usd_dec if ve.allowance_usd_dec not in ("", "0") else ve.allowance_usd)


def _ve_total_dec(ve: VaultExposure) -> Decimal:
    return _to_dec(ve.total_usd_dec if ve.total_usd_dec not in ("", "0") else ve.total_usd)


@dataclass
class TrustClosureResult:
    chain: str
    block_pin: int
    seed_addresses: List[str]
    all_addresses: List[str]
    resolutions: Dict[str, ProxyResolution]
    vault_exposures: Dict[str, VaultExposure]
    max_extractable_usd: Decimal
    min_gas_usd: Decimal
    early_exit_safe: bool
    early_exit_reason: str
    token_decimals: Dict[str, int] = field(default_factory=dict)
    token_prices_usd: Dict[str, Decimal] = field(default_factory=dict)
    has_dynamic_external_reachability: bool = False
    approved_owners: List[str] = field(default_factory=list)
    max_extractable_usd_dec: str = "0"
    min_gas_usd_dec: str = "0.01"
    realizable_extractable_usd: Decimal = _DEC_ZERO
    realizable_extractable_usd_dec: str = "0"
    verified_exit_pools: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    has_unpriced_token_exposure: bool = False
    rpc_balance_incomplete: bool = False
    closure_truncated: bool = False
    token_prices_usd_dec: Dict[str, str] = field(default_factory=dict)


def _closure_prices_lookup(closure: TrustClosureResult) -> Dict[str, Decimal]:
    out: Dict[str, Decimal] = {
        str(k): _to_dec(v) for k, v in (closure.token_prices_usd or {}).items()
    }
    for k, v_s in (closure.token_prices_usd_dec or {}).items():
        if v_s not in (None, ""):
            out[str(k)] = _to_dec(v_s)
    return out


