_B32_SKIP_NOISE: FrozenSet[bytes] = frozenset(
    bytes.fromhex(h.removeprefix("0x").zfill(64))
    for h in (
        "0" * 64,
        "f" * 64,
        "ff" * 20,
        "ddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef",  # ERC20 Transfer
        "8c5be1e5ebec7d5bd14f71427d1e84f3dd0314c0f7b2291e5b200ac8c7c3b925",  # ERC20 Approval
        "360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc",  # EIP-1967 impl
        "b53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103",  # EIP-1967 admin
        "a3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50",  # EIP-1967 beacon
    )
)
_SRC_B32_CAST_RE: re.Pattern[str] = re.compile(
    r"bytes32\s*\(\s*bytes(\d{1,2})\s*\(\s*(?:hex\"([0-9a-fA-F]+)\"|0x([0-9a-fA-F]+))\s*\)\s*\)"
)
_SRC_B32_KECCAK_RE: re.Pattern[str] = re.compile(
    r"keccak256\s*\(\s*(?:abi\.encodePacked\s*\(\s*)?\"([^\x00-\x1f\"\\]{1,64})\"\s*\)?\s*\)"
)
_SRC_B32_CONST_RE: re.Pattern[str] = re.compile(
    r"bytes32(?:\s+(?:public|internal|private))?\s+(?:constant|immutable)\s+\w+\s*=\s*(?:0x([0-9a-fA-F]{1,64})|\"([^\x00-\x1f\"\\]{1,32})\")"
)


def _extract_bytes32_keys_from_dis(dis: Sequence[Tuple[int, str, bytes]], *, cap: int = 24) -> List[bytes]:
    """디스어셈블리에서 `PUSH32` 상수 및 Solidity 좌측정렬 `PUSHk + PUSH1 shift + SHL`(`bytes32(bytesN(...))`) 매핑 키를 추출."""
    out: List[bytes] = []
    seen: Set[bytes] = set()
    n = len(dis)

    def _add_k32(b32: bytes) -> None:
        if len(b32) != 32 or b32 in seen or b32 in _B32_SKIP_NOISE:
            return
        iv = int.from_bytes(b32, "big")
        # Skip tiny integers/masks and power-of-two bitmasks (2^k or 2^k - 1)
        if iv < 0x10000 or (iv & (iv - 1)) == 0 or ((iv + 1) & iv) == 0:
            return
        seen.add(b32)
        out.append(b32)

    for idx, (_, nm, imm) in enumerate(dis):
        if len(out) >= cap:
            break
        if nm == "PUSH32" and len(imm) == 32:
            _add_k32(imm)
        elif nm.startswith("PUSH") and 1 <= len(imm) <= 16:
            k_len = len(imm)
            # Solidity encodes bytes32(bytesN(val)) as PUSHn val; PUSH1 (256-8*n); SHL (or PUSH1 shift; PUSHn val; SHL)
            if idx + 2 < n and dis[idx + 2][1] == "SHL" and dis[idx + 1][1] == "PUSH1" and len(dis[idx + 1][2]) == 1:
                sh = dis[idx + 1][2][0]
                if 128 <= sh <= 248 and (sh % 8) == 0 and (sh + k_len * 8) <= 256:
                    val = int.from_bytes(imm, "big") << sh
                    if 0 < val < (1 << 256):
                        _add_k32(val.to_bytes(32, "big"))
            elif idx >= 1 and idx + 1 < n and dis[idx + 1][1] == "SHL" and dis[idx - 1][1] == "PUSH1" and len(dis[idx - 1][2]) == 1:
                sh = dis[idx - 1][2][0]
                if 128 <= sh <= 248 and (sh % 8) == 0 and (sh + k_len * 8) <= 256:
                    val = int.from_bytes(imm, "big") << sh
                    if 0 < val < (1 << 256):
                        _add_k32(val.to_bytes(32, "big"))
    return out


def _extract_bytes32_keys_from_sources(sources_map: Mapping[str, Any], *, cap: int = 24) -> List[bytes]:
    """검증 소스에서 `bytes32(bytesN(...))`, `keccak256("...")`, `bytes32 constant` 매핑 키를 추출."""
    out: List[bytes] = []
    seen: Set[bytes] = set()

    def _add_k32(b32: bytes) -> None:
        if len(b32) == 32 and b32 not in seen and b32 not in _B32_SKIP_NOISE and len(out) < cap:
            seen.add(b32)
            out.append(b32)

    for src_val in (sources_map or {}).values():
        txt = str(src_val or "")
        if not txt or len(out) >= cap:
            continue
        for m_c in _SRC_B32_CAST_RE.finditer(txt):
            hx = (m_c.group(2) or m_c.group(3) or "").strip()
            try:
                nb = max(1, min(32, int(m_c.group(1))))
                raw_b = bytes.fromhex(hx.zfill(nb * 2))[:nb]
                _add_k32(raw_b.ljust(32, b"\x00"))
            except ValueError:
                pass
        for m_k in _SRC_B32_KECCAK_RE.finditer(txt):
            _add_k32(_keccak256(m_k.group(1).encode("utf-8")))
        for m_v in _SRC_B32_CONST_RE.finditer(txt):
            hx_v, str_v = m_v.group(1), m_v.group(2)
            if hx_v:
                try:
                    raw_h = bytes.fromhex(hx_v.zfill(64)) if len(hx_v) >= 63 else bytes.fromhex(hx_v.ljust(64, "0"))
                    _add_k32(raw_h[:32])
                except ValueError:
                    pass
            elif str_v:
                _add_k32(str_v.encode("utf-8")[:32].ljust(32, b"\x00"))
    return out
