def _extract_push_selectors_and_addrs(dis: List[Tuple[int, str, bytes]]) -> Tuple[List[str], List[str]]:
    """디스어셈블리에서 PUSH1..PUSH4 셀렉터 및 PUSH20 상수 주소 추출."""
    sels: Set[str] = set()
    n = len(dis)
    has_shr_e0 = any(
        nm in ("SHR", "DIV")
        and any(
            dis[k][1].startswith("PUSH") and int.from_bytes(dis[k][2] or b"\x00", "big") in (0xE0, 1 << 224)
            for k in range(max(0, idx - 4), idx)
        )
        for idx, (_, nm, _) in enumerate(dis)
    )
    for idx, (_, nm, imm) in enumerate(dis):
        if nm == "PUSH4" and len(imm) == 4:
            sh = "0x" + imm.hex()
            if sh not in ("0x00000000", "0xffffffff"):
                if any(dis[j][1] in ("EQ", "SUB", "XOR", "GT", "LT", "SLT", "SGT") for j in range(idx + 1, min(n, idx + 8))):
                    sels.add(sh)
        elif has_shr_e0 and nm in ("PUSH1", "PUSH2", "PUSH3") and 1 <= len(imm) <= 3:
            if any(dis[j][1] == "EQ" for j in range(idx + 1, min(n, idx + 6))) and any(
                dis[j][1] == "JUMPI" for j in range(idx + 1, min(n, idx + 10))
            ):
                sh = "0x" + imm.rjust(4, b"\x00").hex()
                if sh != "0x00000000":
                    sels.add(sh)
    addrs = [a for a in _push20_constants(dis) if a != "0xffffffffffffffffffffffffffffffffffffffff"]
    return sorted(sels), addrs


def _has_dynamic_or_external_call_capability(dis: Sequence[Tuple[int, str, bytes]]) -> bool:
    """컨트랙트가 외부 CALL / DELEGATECALL / CREATE / SSTORE / TSTORE를 통해 연결된 금고나 상태를 조작할 수 있는지 판별."""
    for _, nm, _ in dis:
        if nm in ("CALL", "DELEGATECALL", "CALLCODE", "CREATE", "CREATE2", "SELFDESTRUCT", "SSTORE", "TSTORE"):
            return True
    return False


def _expand_address_graph_conceptually(
    router: RPCRouter,
    chain: str,
    seeds: List[str],
    resolutions: Dict[str, ProxyResolution],
    block_pin: int,
    max_nodes: int = 72,
    max_hops: int = 3,
    *,
    rpc_incomplete_out: Optional[List[bool]] = None,
    hop0_inbound_out: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """
    다중 홉(2~3홉) 연결 가치 그래프 확장:
    - 잔고 없는 라우터/헬퍼/컨트롤러에서 출발하더라도 PUSH20 상수, OZ Upgradeable __gap 포함 스토리지 슬롯,
      표준/인덱싱 연결 게터 + 바이트코드/Sourcify 검증 ABI 0-인자 주소 게터 + 동일 배포자 형제 컨트랙트,
      최근 이벤트 로그를 최대 max_hops 단계까지 재귀 확장하여 실제 잔고가 담긴 연결 금고/풀을 폐포에 편입한다.
    - 단, 시드에 명시되지 않은 체인 공용 인프라 싱글톤/DEX 라우터/Permit2는 금고 폐포 확장 대상에서 제외하여
      공용 인프라 잔고로 인한 E1 임계치 오염 및 이중 계상을 원천 차단한다.
    """
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    seed_set: Set[str] = {ns for s in seeds if (ns := _norm_addr(s))}
    excluded_infra: Set[str] = _infra_addresses_for_chain(c) - seed_set
    known: Set[str] = set(seed_set)
    frontier: Set[str] = set(known)
    is_live_rpc = _is_live_real_router(router)
    collected_b32_keys: List[bytes] = []
    seen_b32_keys: Set[bytes] = set()
    discovered_b32_getters: List[Tuple[str, bytes]] = []
    seen_b32_getters: Set[Tuple[str, bytes]] = set()
    probed_b32_pairs: Set[Tuple[str, bytes, bytes]] = set()
    cid_exp = CHAIN_IDS.get(c, 0)
    r_store_exp = getattr(router, "store", None) if router is not None else None
    exp_rpc_lk = threading.Lock()

    def _mark_exp_rpc_incomplete() -> None:
        _mark_rpc_incomplete_flag(rpc_incomplete_out, exp_rpc_lk)

    def _record_b32_key(k32: bytes) -> None:
        if len(k32) == 32 and k32 not in seen_b32_keys and len(collected_b32_keys) < 48:
            seen_b32_keys.add(k32)
            collected_b32_keys.append(k32)

    def _record_b32_getter(g_addr: str, sel_b: bytes) -> None:
        if g_addr and len(sel_b) == 4 and (g_addr, sel_b) not in seen_b32_getters and len(discovered_b32_getters) < 64:
            seen_b32_getters.add((g_addr, sel_b))
            discovered_b32_getters.append((g_addr, sel_b))

    for hop in range(max(1, int(max_hops))):
        if not frontier or len(known) >= max_nodes:
            break
        discovered: Set[str] = set()
        gov_cands: Set[str] = set()
        slot_calls: List[Tuple[str, List[Any]]] = []
        mc_calls: List[Tuple[str, bytes]] = []
        sourcify_getters_by_addr: Dict[str, List[str]] = {}
        sourcify_b32_getters_by_addr: Dict[str, List[str]] = {}
        sorted_frontier = sorted(frontier)
        frontier_has_ext_call = False

        def _record_discovered(cand_a: str) -> None:
            if cand_a and cand_a not in known and cand_a not in excluded_infra and len(discovered) < max_nodes * 2:
                discovered.add(cand_a)

        need_sf_hints = bool(hop == 0 and SOURCIFY_PARQUET_DIR.is_dir() and cid_exp > 0)

        def _fetch_sf_hints() -> Dict[str, Any]:
            try:
                if _query_local_sourcify_deployment_hints is _ORIG_QUERY_LOCAL_SOURCIFY_HINTS_FN:
                    return _query_local_sourcify_deployment_hints(cid_exp, sorted_frontier, include_bytecodes=False)
                return _query_local_sourcify_deployment_hints(cid_exp, sorted_frontier)
            except Exception:
                return {}

        seen_calls_by_addr: Dict[str, Set[bytes]] = {}
        _code_ana_cache: Dict[str, Tuple[bool, bool, List[str], List[str], List[bytes]]] = {}
        _dense_frontier_slots: Tuple[int, ...] = (
            tuple(range(0, 32))
            + tuple(range(50, 58))
            + tuple(range(100, 108))
            + tuple(range(150, 158))
            + tuple(range(200, 208))
            + tuple(range(250, 256))
            + tuple(range(301, 306))
        )
        _use_dense_slots = bool(is_live_rpc and len(sorted_frontier) > 16)

        for addr in sorted_frontier:
            res = resolutions.get(addr)
            if not res:
                continue
            for gov_a in (getattr(res, "admin_address", ""), getattr(res, "beacon_address", "")):
                ng = _norm_addr(gov_a)
                if ng and ng not in known and ng not in excluded_infra:
                    gov_cands.add(ng)
            code_hex_list = _res_facet_codes_hex(res)
            seen_calls_for_addr = seen_calls_by_addr.setdefault(addr, set())

            def _queue_addr_call(call_b: bytes) -> None:
                if call_b and call_b not in seen_calls_for_addr:
                    seen_calls_for_addr.add(call_b)
                    mc_calls.append((addr, call_b))

            if res.proxy_kind == "eip7702":
                frontier_has_ext_call = True
            has_any_code = False
            has_sload_op = res.proxy_kind != "none"
            for chx in code_hex_list:
                chx_k = str(chx or "").lower()
                cached_ana = _code_ana_cache.get(chx_k)
                if cached_ana is None:
                    eff_bytes = _hex_to_bytes(chx_k)
                    if not eff_bytes:
                        continue
                    dis = _disassemble(eff_bytes)
                    loc_ext = _has_dynamic_or_external_call_capability(dis)
                    loc_sload = any(nm == "SLOAD" for _, nm, _ in dis)
                    sels_l, push_addrs_l = _extract_push_selectors_and_addrs(dis)
                    b32_l = _extract_bytes32_keys_from_dis(dis, cap=24)
                    cached_ana = (loc_ext, loc_sload, sels_l, push_addrs_l, b32_l)
                    _code_ana_cache[chx_k] = cached_ana
                has_any_code = True
                loc_ext, loc_sload, sels, push_addrs, b32_keys_c = cached_ana
                if loc_ext:
                    frontier_has_ext_call = True
                if loc_sload:
                    has_sload_op = True
                for pa in push_addrs:
                    _record_discovered(pa)
                for k32_c in b32_keys_c:
                    _record_b32_key(k32_c)
                for sel in sels:
                    sel_b = _hex_to_bytes(sel)
                    if sel_b in _COMMON_BYTES32_ADDR_GETTER_SELS:
                        _record_b32_getter(addr, sel_b)
                    if sel.removeprefix("0x").lower() in _COMMON_BOILERPLATE_SELECTORS:
                        continue
                    _queue_addr_call(sel_b)
            if not has_any_code and res.proxy_kind == "none":
                continue

            if r_store_exp is not None and cid_exp > 0:
                for sc_a in (addr, *(res.impl_addresses or ())[:2]):
                    na_sc = _norm_addr(sc_a)
                    if not na_sc:
                        continue
                    try:
                        v_sc = r_store_exp.get_verified_source(cid_exp, na_sc)
                    except Exception:
                        v_sc = None
                    if isinstance(v_sc, dict) and v_sc.get("verified"):
                        for k32_s in _extract_bytes32_keys_from_sources(v_sc.get("sources") or {}, cap=24):
                            _record_b32_key(k32_s)
                        for b32_sb in _abi_bytes32_addr_getters(v_sc.get("abi") or ()):
                            _record_b32_getter(addr, b32_sb)
            for gs in _COMMON_CONNECTED_GETTER_SELS:
                _queue_addr_call(gs)
            if hop == 0:
                for igs in _INDEXED_CONNECTED_GETTER_CALLS:
                    _queue_addr_call(igs)
            if not has_sload_op:
                continue
            slot_indices: Sequence[int] = (
                (_dense_frontier_slots if _use_dense_slots else _CONNECTED_STORAGE_PROBE_SLOTS)
                if hop == 0
                else range(16)
            )
            for slot_idx in slot_indices:
                slot_calls.append(("eth_getStorageAt", [_checksum(addr), hex(slot_idx), btag]))

        # Pass 2: Probe discovered bytes32->address mapping getters (e.g. Registry._contracts(bytes32)) with collected protocol keys
        if discovered_b32_getters and collected_b32_keys:
            b32_added = 0
            for g_addr, g_sel in discovered_b32_getters:
                if b32_added >= 96:
                    break
                for k32 in collected_b32_keys:
                    if b32_added >= 96:
                        break
                    pair_k = (g_addr, g_sel, k32)
                    if pair_k not in probed_b32_pairs:
                        probed_b32_pairs.add(pair_k)
                        mc_calls.append((g_addr, g_sel + k32))
                        b32_added += 1

        def _fetch_slot_vals() -> List[Any]:
            sc_chunks = [slot_calls[idx_sc : idx_sc + 96] for idx_sc in range(0, len(slot_calls), 96)]

            def _run_sc_chunk(ch: List[Tuple[str, List[Any]]]) -> List[Any]:
                part_s = router.batch_call(c, ch, block_pin=block_pin, need_archive=True)
                if (
                    len(part_s) < len(ch)
                    or any(v_s is None for v_s in part_s)
                    or (isinstance(router, RPCRouter) and router.last_batch_transport_failures() > 0)
                ):
                    _mark_exp_rpc_incomplete()
                return part_s

            if is_live_rpc and len(sc_chunks) >= 2:
                out_s: List[Any] = []
                with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, len(sc_chunks))) as ex_sc:
                    for part_s in ex_sc.map(_run_sc_chunk, sc_chunks):
                        out_s.extend(part_s)
                return out_s
            out_s = []
            for ch in sc_chunks:
                out_s.extend(_run_sc_chunk(ch))
            return out_s

        def _fetch_mc_vals() -> List[Tuple[bool, bytes]]:
            mc_chunks = [mc_calls[idx_mc : idx_mc + 96] for idx_mc in range(0, len(mc_calls), 96)]

            def _run_mc_chunk(ch: List[Tuple[str, bytes]]) -> List[Tuple[bool, bytes]]:
                part_m = router.multicall3(c, ch, block_pin=block_pin)
                m_tls = getattr(router, "_tls", None)
                if len(part_m) < len(ch) or (m_tls is not None and bool(getattr(m_tls, "last_multicall_transport_failed", False))):
                    _mark_exp_rpc_incomplete()
                return part_m

            if is_live_rpc and len(mc_chunks) >= 2:
                out_m: List[Tuple[bool, bytes]] = []
                with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, len(mc_chunks))) as ex_mc:
                    for part_m in ex_mc.map(_run_mc_chunk, mc_chunks):
                        out_m.extend(part_m)
                return out_m
            out_m = []
            for ch in mc_chunks:
                out_m.extend(_run_mc_chunk(ch))
            return out_m

        def _fetch_out_logs() -> Set[str]:
            try:
                log_lookback = (50_000 if hop == 0 else 25_000) if is_live_rpc else 2_000
                log_depth = (3 if hop == 0 else 2) if is_live_rpc else 2
                return _harvest_logs_bisect(
                    router,
                    c,
                    sorted_frontier,
                    max(1, block_pin - log_lookback),
                    block_pin,
                    max_depth=log_depth,
                    rpc_incomplete_out=rpc_incomplete_out,
                    _err_lock=exp_rpc_lk,
                )
            except Exception:
                _mark_exp_rpc_incomplete()
                return set()

        def _fetch_inb_logs() -> Tuple[Set[str], Set[str]]:
            try:
                inb_trips_h0: Set[Tuple[str, str, str]] = set()
                inb_vaults, inb_grantors, inb_toks = _harvest_inbound_trust_and_approvals(
                    router,
                    c,
                    sorted_frontier,
                    block_pin,
                    is_live_rpc=is_live_rpc,
                    out_approval_triples=inb_trips_h0,
                    rpc_incomplete_out=rpc_incomplete_out,
                    _err_lock=exp_rpc_lk,
                )
                if hop0_inbound_out is not None and hop == 0:
                    hop0_inbound_out["targets"] = tuple(sorted_frontier)
                    hop0_inbound_out["grantors"] = inb_grantors
                    hop0_inbound_out["tokens"] = inb_toks
                    hop0_inbound_out["triples"] = inb_trips_h0
                return inb_vaults, inb_grantors
            except Exception:
                _mark_exp_rpc_incomplete()
                return set(), set()

        need_out_logs = block_pin > 100 and (hop == 0 or (hop == 1 and len(sorted_frontier) <= 8))
        need_inb_logs = hop == 0 and block_pin > 100 and frontier_has_ext_call
        if is_live_rpc and (int(bool(slot_calls)) + int(bool(mc_calls)) + int(need_out_logs) + int(need_inb_logs) + int(need_sf_hints)) >= 2:
            with concurrent.futures.ThreadPoolExecutor(max_workers=5) as ex_fg:
                fut_s = ex_fg.submit(_fetch_slot_vals) if slot_calls else None
                fut_m = ex_fg.submit(_fetch_mc_vals) if mc_calls else None
                fut_ol = ex_fg.submit(_fetch_out_logs) if need_out_logs else None
                fut_il = ex_fg.submit(_fetch_inb_logs) if need_inb_logs else None
                fut_sf = ex_fg.submit(_fetch_sf_hints) if need_sf_hints else None
                s_all = fut_s.result() if fut_s is not None else []
                mc_res = fut_m.result() if fut_m is not None else []
                out_log_addrs = fut_ol.result() if fut_ol is not None else set()
                inb_vault_addrs, inb_grantor_addrs = fut_il.result() if fut_il is not None else (set(), set())
                s_hints = fut_sf.result() if fut_sf is not None else {}
        else:
            s_all = _fetch_slot_vals() if slot_calls else []
            mc_res = _fetch_mc_vals() if mc_calls else []
            out_log_addrs = _fetch_out_logs() if need_out_logs else set()
            inb_vault_addrs, inb_grantor_addrs = _fetch_inb_logs() if need_inb_logs else (set(), set())
            s_hints = _fetch_sf_hints() if need_sf_hints else {}

        if isinstance(s_hints, dict) and s_hints:
            for ea_list in (s_hints.get("embedded_addresses") or {}).values():
                for ea in ea_list:
                    _record_discovered(ea)
            for sa in s_hints.get("sibling_contracts") or ():
                _record_discovered(sa)
            sourcify_getters_by_addr = dict(s_hints.get("abi_zero_arg_getters") or {})
            sourcify_b32_getters_by_addr = dict(s_hints.get("abi_bytes32_addr_getters") or {})
            sf_delta_calls: List[Tuple[str, bytes]] = []
            for addr_sf in sorted_frontier:
                seen_sf = seen_calls_by_addr.setdefault(addr_sf, set())
                for g_hex in sourcify_getters_by_addr.get(addr_sf, ()):
                    gb = _hex_to_bytes(g_hex)
                    if gb and gb not in seen_sf:
                        seen_sf.add(gb)
                        sf_delta_calls.append((addr_sf, gb))
                for b32_g_hex in sourcify_b32_getters_by_addr.get(addr_sf, ()):
                    b32_b = _hex_to_bytes(b32_g_hex)
                    if b32_b:
                        _record_b32_getter(addr_sf, b32_b)
                        for k32 in collected_b32_keys:
                            pair_k = (addr_sf, b32_b, k32)
                            if pair_k not in probed_b32_pairs and len(sf_delta_calls) < 96:
                                probed_b32_pairs.add(pair_k)
                                sf_delta_calls.append((addr_sf, b32_b + k32))
            if sf_delta_calls:
                sf_mc_res = router.multicall3(c, sf_delta_calls, block_pin=block_pin)
                if len(sf_mc_res) < len(sf_delta_calls):
                    _mark_exp_rpc_incomplete()
                mc_res.extend(sf_mc_res)

        for sval in s_all:
            _record_discovered(_extract_word32_address(sval) or "")
        for ok, rdata in mc_res:
            if not ok or len(rdata) < 32:
                continue
            for cand in _extract_addr_candidates_from_word_or_array(rdata):
                _record_discovered(cand)
        for cand_l in (*sorted(out_log_addrs), *sorted(inb_vault_addrs), *sorted(gov_cands)):
            _record_discovered(cand_l)
        # Keep only contract grantors in graph expansion; pure EOA approval grantors are tracked separately in approval_owners
        for cand_g in sorted(inb_grantor_addrs):
            if cand_g in inb_vault_addrs:
                _record_discovered(cand_g)

        new_cands = sorted(
            discovered - known - excluded_infra,
            key=lambda a: (1 if int(a, 16) < (1 << 80) else 0, a),
        )[: max(1, max_nodes - len(known))]
        if not new_cands:
            break
        try:
            new_res = _resolve_proxy_and_delegates(router, c, new_cands, block_pin)
        except Exception:
            _mark_exp_rpc_incomplete()
            break
        if len(new_res) < len(new_cands):
            _mark_exp_rpc_incomplete()
        next_frontier: Set[str] = set()
        for x, pr in new_res.items():
            if pr.unresolved_delegation:
                _mark_exp_rpc_incomplete()
            has_code_or_7702 = len(_hex_to_bytes(pr.effective_code_hex)) > 0 or pr.proxy_kind == "eip7702"
            if has_code_or_7702:
                resolutions[x] = pr
                if x not in excluded_infra:
                    known.add(x)
                    next_frontier.add(x)
        frontier = next_frontier

    return sorted(known)[:max_nodes]


