@_with_decimal_prec_100
def _probe_chainlink_usd_price(
    router: RPCRouter,
    chain: str,
    feed_addr: str,
    block_pin: int,
    block_timestamp: int = 0,
) -> Decimal:
    """기준 블록(block_pin)에서 Chainlink AggregatorV3 latestRoundData() 5-워드 무결성(updatedAt > 0, answeredInRound >= roundId, heartbeat 신선도) 및 decimals()를 온체인 실측."""
    if block_pin <= 0 or not feed_addr:
        return _DEC_ZERO
    c = _norm_chain(chain)
    try:
        res = router.multicall3(
            c,
            [
                (feed_addr, bytes.fromhex("feaf968c")),
                (feed_addr, bytes.fromhex(DECIMALS_SEL[2:])),
            ],
            block_pin=block_pin,
        )
        if len(res) == 2 and res[0][0] and len(res[0][1]) >= 64:
            raw_r = res[0][1]
            if len(raw_r) >= 160:
                round_id = int.from_bytes(raw_r[0:32], "big")
                updated_at = int.from_bytes(raw_r[96:128], "big")
                answered_in_round = int.from_bytes(raw_r[128:160], "big")
                if updated_at == 0 or (round_id > 0 and answered_in_round < round_id):
                    return _DEC_ZERO
                if block_timestamp > 0 and updated_at > 0:
                    if (block_timestamp - updated_at) > 86400 * 2 or updated_at > block_timestamp + 3600:
                        return _DEC_ZERO
            answer = int.from_bytes(raw_r[32:64], "big", signed=True)
            dec = int.from_bytes(res[1][1][:32], "big") if (res[1][0] and len(res[1][1]) >= 32) else 8
            if answer > 0 and 0 <= dec <= 18:
                return Decimal(answer) / (Decimal(10) ** dec)
    except _RECOVERABLE_IO_EXC:
        pass
    return _DEC_ZERO


def _fetch_block_timestamp(
    router: Optional[Any],
    chain: str,
    block_num: int,
    *,
    need_archive: bool = True,
    timeout: Optional[float] = None,
) -> int:
    if router is None or block_num <= 0:
        return 0
    c = _norm_chain(chain)
    call_kw: Dict[str, Any] = {"block_pin": int(block_num), "need_archive": need_archive}
    if timeout is not None:
        call_kw["timeout"] = timeout
    try:
        try:
            blk_obj = router.call(c, "eth_getBlockByNumber", [hex(int(block_num)), False], **call_kw)
        except TypeError:
            blk_obj = router.call(c, "eth_getBlockByNumber", [hex(int(block_num)), False])
        if isinstance(blk_obj, dict):
            return max(0, _hex_to_int(blk_obj.get("timestamp")))
    except _RECOVERABLE_IO_EXC:
        pass
    return 0


def _is_live_real_router(router: Optional[Any]) -> bool:
    """모의(mock) 테스트 라우터가 아닌 실제 라이브 `RPCRouter` 인스턴스인지 판별."""
    return bool(
        router is not None
        and isinstance(router, RPCRouter)
        and type(router).call is RPCRouter.call
        and type(router).http_get_json is RPCRouter.http_get_json
        and type(router).multicall3 is RPCRouter.multicall3
        and "call" not in getattr(router, "__dict__", {})
        and "http_get_json" not in getattr(router, "__dict__", {})
        and "multicall3" not in getattr(router, "__dict__", {})
    )


_LIVE_PROGRESS_LOCK = threading.Lock()
_LIVE_PROGRESS_STATE: Dict[str, Dict[str, Any]] = {}
_LIVE_PROGRESS_TLS = threading.local()


def _emit_progress(
    stage: str,
    *,
    slug: str = "",
    chain: str = "",
    block_pin: int = 0,
    session_id: str = "",
    detail: str = "",
    router: Optional[Any] = None,
    extra: Optional[Mapping[str, Any]] = None,
) -> None:
    """실행 중 stdout JSON 계약을 깨지 않고 stderr 실시간 스트리밍 + 원자적 세션 진행 스냅샷을 갱신한다."""
    if router is not None and not _is_live_real_router(router):
        return
    try:
        if slug:
            _LIVE_PROGRESS_TLS.slug = str(slug)
        ts = time.strftime("%H:%M:%S")
        sid_tag = str(session_id or "default").strip() or "default"
        loc = f"{chain}@{int(block_pin)}" if chain and int(block_pin or 0) > 0 else (chain or "-")
        slug_tag = slug or "-"
        msg = f"[{ts}] [LIVE] {sid_tag} | {stage} | {slug_tag} ({loc})"
        if detail:
            msg = f"{msg} | {detail}"
        with _LIVE_PROGRESS_LOCK:
            print(msg, file=sys.stderr, flush=True)
            safe_sid = _norm_slug(sid_tag) or "default"
            prev = dict(_LIVE_PROGRESS_STATE.get(safe_sid) or {})
            snap: Dict[str, Any] = {
                **prev,
                "session_id": sid_tag,
                "updated_at": round(time.time(), 3),
                "updated_local": ts,
                "stage": stage,
                "slug": slug,
                "chain": chain,
                "block_pin": int(block_pin or 0),
                "detail": detail,
            }
            if extra:
                for k_e, v_e in extra.items():
                    snap[str(k_e)] = v_e
            _LIVE_PROGRESS_STATE[safe_sid] = snap
            if ARTIFACT_ROOT.exists():
                _write_json_atomic(ARTIFACT_ROOT / f"_live_progress_{safe_sid}.json", snap, compact=True)
    except _OS_CLEANUP_EXC:
        pass


@_with_decimal_prec_100
def _estimate_native_price_interval_dec(
    chain: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
) -> Tuple[Decimal, Decimal]:
    """체인 네이티브 토큰 기준 블록(block_pin) 온체인 오라클 + coins.llama.fi(historical/current) 고정밀 Decimal 교차 시세 구간 [P_min, P_max] 조회 (>15% 괴리 시 (0, 0) Fail-Open)."""
    c = _norm_chain(chain)
    live_real_ctx = bool(_is_live_real_router(router) and block_pin > 0 and not allow_offline_fixture)
    cache_key = f"native_usd:{c}:{int(block_pin)}" if block_pin > 0 else f"native_usd:{c}"
    cache_max_key = f"native_usd_max:{c}:{int(block_pin)}" if block_pin > 0 else f"native_usd_max:{c}"
    r_store = getattr(router, "store", None) if router is not None else None
    if r_store is not None:
        cached = r_store.get_price_dec(cache_key, max_age_sec=1800)
        if cached is not None and cached[0] > _DEC_ZERO:
            src_lo = str(cached[1] or "")
            if (not live_real_ctx) or (not src_lo.startswith("fixture:") and "xcheck" in src_lo):
                cached_hi = r_store.get_price_dec(cache_max_key, max_age_sec=1800)
                p_lo_d = cached[0]
                hi_valid = (
                    cached_hi is not None
                    and cached_hi[0] >= p_lo_d
                    and (
                        (not live_real_ctx)
                        or (not str(cached_hi[1] or "").startswith("fixture:") and "xcheck" in str(cached_hi[1] or ""))
                    )
                )
                p_hi_d = cached_hi[0] if (hi_valid and cached_hi is not None) else p_lo_d
                return p_lo_d, p_hi_d
    blk_ts = _fetch_block_timestamp(router, c, block_pin)
    cl_d = _DEC_ZERO
    if router is not None and block_pin > 0 and c in _CHAINLINK_NATIVE_USD_FEEDS:
        cl_d = _probe_chainlink_usd_price(
            router, c, _CHAINLINK_NATIVE_USD_FEEDS[c], block_pin, block_timestamp=blk_ts
        )
    def _query_llama_key_dec(lk: str) -> Decimal:
        if router is None or not lk:
            return _DEC_ZERO
        val_d = _DEC_ZERO
        try:
            if blk_ts > 1_500_000_000:
                doc_l = router.http_get_json(f"https://coins.llama.fi/prices/historical/{blk_ts}/{lk}", timeout=5)
                val_d = _to_dec(((doc_l.get("coins") or {}).get(lk) or {}).get("price") or 0)
            if val_d <= _DEC_ZERO:
                doc_l = router.http_get_json(f"https://coins.llama.fi/prices/current/{lk}", timeout=5)
                val_d = _to_dec(((doc_l.get("coins") or {}).get(lk) or {}).get("price") or 0)
        except Exception:
            val_d = _DEC_ZERO
        return val_d

    def _store_price_pair(lo_d: Decimal, hi_d: Decimal, lo_src: str, hi_src: str) -> Tuple[Decimal, Decimal]:
        if r_store is not None:
            r_store.put_price(cache_key, lo_d, lo_src)
            r_store.put_price(cache_max_key, hi_d, hi_src)
        return lo_d, hi_d

    def _try_xcheck(a_d: Decimal, b_d: Decimal, lo_src: str, hi_src: str) -> Optional[Tuple[Decimal, Decimal]]:
        lo_d, hi_d = (a_d, b_d) if a_d <= b_d else (b_d, a_d)
        if hi_d > _DEC_ZERO and (hi_d - lo_d) / hi_d <= Decimal("0.15"):
            return _store_price_pair(lo_d, hi_d, lo_src, hi_src)
        return None

    cg_key = _COINGECKO_NATIVE_IDS.get(c) or ("coingecko:ethereum" if c in NATIVE_ETH_CHAINS else "")
    llama_d = _query_llama_key_dec(cg_key)
    if cl_d > _DEC_ZERO and llama_d > _DEC_ZERO:
        xc_cl = _try_xcheck(cl_d, llama_d, "onchain:chainlink_llama_xcheck", "onchain:chainlink_llama_xcheck_max")
        return xc_cl if xc_cl is not None else (_DEC_ZERO, _DEC_ZERO)
    if live_real_ctx:
        wnative_c = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
        if cl_d > _DEC_ZERO or llama_d > _DEC_ZERO or wnative_c:
            stables_list = list(_norm_chain_stables(c))[:5]
            bluechips_list = [b for b in sorted(_norm_chain_bluechips_set(c)) if b != wnative_c][:3]
            dex_nat_p_d = _DEC_ZERO
            wn_llama_d = _DEC_ZERO
            wn_lk = f"{_llama_chain_prefix(c)}:{wnative_c}" if wnative_c else ""
            if cl_d <= _DEC_ZERO and llama_d <= _DEC_ZERO and wn_lk:
                wn_llama_d = _query_llama_key_dec(wn_lk)
            if wnative_c and (stables_list or bluechips_list) and (cl_d > _DEC_ZERO or llama_d > _DEC_ZERO or wn_llama_d > _DEC_ZERO):
                try:
                    wn_dec = 18
                    dec_res = router.multicall3(
                        c, [(wnative_c, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin
                    )
                    if dec_res:
                        wn_dec = _decode_clamped_dec(dec_res[0], default_dec=18)
                    stable_quote_prices: Dict[str, Decimal] = {}
                    q_probe_items = [(s, True) for s in stables_list] + [(b, False) for b in bluechips_list]

                    def _fetch_one_q_price(q_pair: Tuple[str, bool]) -> Optional[Tuple[str, Decimal]]:
                        q_a, is_st_q = q_pair
                        q_p_d, q_src = _fetch_token_price_usd_dec(
                            r_store,
                            c,
                            q_a,
                            router=router,
                            block_pin=block_pin,
                            allow_offline_fixture=False,
                            _allow_live_xcheck=False,
                        )
                        if not str(q_src or "").startswith("fixture:") and (
                            (is_st_q and Decimal("0.85") <= q_p_d <= Decimal("1.15"))
                            or (not is_st_q and q_p_d > _DEC_ZERO)
                        ):
                            return (q_a, q_p_d)
                        if is_st_q and q_p_d <= _DEC_ZERO:
                            q_ll_st = _query_llama_key_dec(f"{_llama_chain_prefix(c)}:{q_a}")
                            if Decimal("0.97") <= q_ll_st <= Decimal("1.03"):
                                return (q_a, q_ll_st)
                        return None

                    for q_res_p in _parallel_map_list(
                        _fetch_one_q_price, q_probe_items, max_workers=6, parallel=live_real_ctx
                    ):
                        if q_res_p is not None:
                            stable_quote_prices[q_res_p[0]] = q_res_p[1]
                    if stable_quote_prices:
                        ref_p_probe = cl_d if cl_d > _DEC_ZERO else (llama_d if llama_d > _DEC_ZERO else wn_llama_d)
                        nat_probe_amt = (
                            max(
                                1,
                                min(
                                    10 ** (wn_dec + 9),
                                    int((Decimal("10") / ref_p_probe) * (Decimal(10) ** wn_dec)),
                                ),
                            )
                            if ref_p_probe > _DEC_ZERO
                            else (10 ** wn_dec)
                        )
                        dq_nat = probe_dex_exit_liquidity(
                            router,
                            c,
                            wnative_c,
                            nat_probe_amt,
                            wn_dec,
                            _DEC_ZERO,
                            _DEC_ZERO,
                            block_pin,
                            quote_prices_usd=stable_quote_prices,
                            unbacked_supply_mint=True,
                        )
                        dex_depth_d = _to_dec(
                            dq_nat.get("dex_depth_usd_dec") or dq_nat.get("dex_depth_usd") or 0
                        )
                        cons_cnt_n = int(dq_nat.get("consensus_pools_count") or 0)
                        cons_depth_d = _to_dec(dq_nat.get("consensus_depth_usd_dec") or 0)
                        cons_unit_d = _to_dec(dq_nat.get("consensus_unit_price_dec") or 0)
                        _dex_depth_ok = dex_depth_d >= Decimal("10000") or (
                            cons_cnt_n >= 3 and cons_depth_d >= Decimal("3000") and cons_unit_d > _DEC_ZERO
                        )
                        if (
                            dq_nat.get("exit_liquid")
                            and not bool(dq_nat.get("price_diverged"))
                            and _dex_depth_ok
                        ):
                            eff_u_d = _to_dec(
                                dq_nat.get("effective_unit_price_dec")
                                or dq_nat.get("effective_unit_price")
                                or 0
                            )
                            if dex_depth_d < Decimal("10000") and cons_unit_d > _DEC_ZERO:
                                dex_nat_p_d = cons_unit_d
                            elif eff_u_d > _DEC_ZERO:
                                dex_nat_p_d = eff_u_d
                            else:
                                real_u_d = _to_dec(
                                    dq_nat.get("realizable_usd_dec")
                                    or dq_nat.get("realizable_usd")
                                    or 0
                                )
                                dex_nat_p_d = (
                                    (real_u_d * (Decimal(10) ** wn_dec) / Decimal(nat_probe_amt))
                                    if (real_u_d > _DEC_ZERO and nat_probe_amt > 0)
                                    else _DEC_ZERO
                                )
                except Exception:
                    dex_nat_p_d = _DEC_ZERO
            if dex_nat_p_d > _DEC_ZERO:
                ref_p_d = cl_d if cl_d > _DEC_ZERO else (llama_d if llama_d > _DEC_ZERO else wn_llama_d)
                xc_dx = _try_xcheck(ref_p_d, dex_nat_p_d, "onchain:native_dex_xcheck", "onchain:native_dex_xcheck_max")
                if xc_dx is not None:
                    return xc_dx
                # Fallback cross-check when coingecko:<chain> is stale: compare deep on-chain DEX vs live DefiLlama wrapped-native feed
                if cl_d <= _DEC_ZERO and wn_lk and wn_llama_d <= _DEC_ZERO:
                    wn_p1 = _query_llama_key_dec(wn_lk)
                    if wn_p1 > _DEC_ZERO:
                        xc_wn = _try_xcheck(wn_p1, dex_nat_p_d, "onchain:native_wnative_dex_xcheck", "onchain:native_wnative_dex_xcheck_max")
                        if xc_wn is not None:
                            return xc_wn
        # Canonical 1:1 bridged L1 native asset cross-check (ETH L2s, BTC L2s, opBNB) against live L1 Chainlink feed
        if router is not None and cl_d <= _DEC_ZERO and llama_d > _DEC_ZERO:
            l1_feed: Optional[Tuple[str, str]] = None
            if c in NATIVE_ETH_CHAINS and c != "ethereum":
                l1_feed = ("ethereum", _CHAINLINK_NATIVE_USD_FEEDS["ethereum"])
            elif c in _BTC_NATIVE_CHAINS:
                l1_feed = ("ethereum", "0xf4030086522a5beea4988f8ca5b36dbc97bee88c")
            elif c == "opbnb":
                l1_feed = ("bsc", _CHAINLINK_NATIVE_USD_FEEDS["bsc"])
            if l1_feed is not None:
                try:
                    l1_ch, l1_fd = l1_feed
                    l1_bh = router.call(l1_ch, "eth_blockNumber", [])
                    l1_bn = _hex_to_int(l1_bh)
                    if l1_bn > 0:
                        l1_ts = _fetch_block_timestamp(router, l1_ch, l1_bn, need_archive=False)
                        l1_cl_d = _probe_chainlink_usd_price(router, l1_ch, l1_fd, l1_bn, block_timestamp=l1_ts)
                        if l1_cl_d > _DEC_ZERO:
                            xc_l1 = _try_xcheck(l1_cl_d, llama_d, "onchain:l1_chainlink_llama_xcheck", "onchain:l1_chainlink_llama_xcheck_max")
                            if xc_l1 is not None:
                                return xc_l1
                except _RECOVERABLE_IO_EXC:
                    pass
        return _DEC_ZERO, _DEC_ZERO
    if cl_d > _DEC_ZERO:
        return _store_price_pair(cl_d, cl_d, "onchain:chainlink_feed", "onchain:chainlink_feed")
    if llama_d > _DEC_ZERO:
        return _store_price_pair(llama_d, llama_d, "llama_native", "llama_native")
    if allow_offline_fixture or router is None or block_pin <= 0:
        fb_val_d = Decimal("1")
        if c in _BTC_NATIVE_CHAINS:
            fb_val_d = Decimal("85000")
        elif c in NATIVE_ETH_CHAINS or c in (
            "ethereum", "arbitrum", "optimism", "base", "linea", "scroll", "zksync",
            "blast", "mode", "taiko", "unichain", "ink", "worldchain", "megaeth", "bob",
        ):
            fb_val_d = Decimal("3000")
        elif c in ("bsc", "opbnb"):
            fb_val_d = Decimal("600")
        elif c == "avalanche":
            fb_val_d = Decimal("30")
        elif c in ("polygon",):
            fb_val_d = Decimal("0.5")
        elif c in ("gnosis", "xdai"):
            fb_val_d = Decimal("1")
        return fb_val_d, fb_val_d
    return _DEC_ZERO, _DEC_ZERO


def _estimate_native_price_dec(
    chain: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
) -> Decimal:
    """체인 네이티브 토큰 기준 블록(block_pin) 온체인 오라클 + coins.llama.fi 교차 시세 하한(P_min) 조회."""
    p_min_d, _ = _estimate_native_price_interval_dec(
        chain, router=router, block_pin=block_pin, allow_offline_fixture=allow_offline_fixture
    )
    return p_min_d


def _parallel_dex_liquidity_probes(
    router: RPCRouter,
    chain: str,
    block_pin: int,
    native_usd: Decimal,
    quote_prices_usd: Mapping[str, Decimal],
    specs: Sequence[Tuple[str, int, int, Decimal]],
    *,
    default_on_error: Optional[Dict[str, Any]] = None,
) -> Dict[str, Optional[Dict[str, Any]]]:
    if not specs:
        return {}

    def _run_one(item_spec: Tuple[str, int, int, Decimal]) -> Tuple[str, Optional[Dict[str, Any]]]:
        t_k, amt_k, dec_k, unit_p_k = item_spec
        try:
            return t_k, probe_dex_exit_liquidity(
                router,
                chain,
                t_k,
                amt_k,
                dec_k,
                unit_p_k,
                native_usd,
                block_pin,
                quote_prices_usd=quote_prices_usd,
            )
        except Exception:
            return t_k, (dict(default_on_error) if default_on_error is not None else None)

    out_map: Dict[str, Optional[Dict[str, Any]]] = {}
    if len(specs) >= 2 and _is_live_real_router(router):
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(24, len(specs))) as ex_dp:
            for t_k, dq_res in ex_dp.map(_run_one, specs):
                out_map[t_k] = dq_res
    else:
        for sp in specs:
            t_k, dq_res = _run_one(sp)
            out_map[t_k] = dq_res
    return out_map


@_with_decimal_prec_100
def _resolve_token_metadata_batch(
    router: RPCRouter,
    chain: str,
    tokens: Sequence[str],
    block_pin: int,
    native_price_usd: Union[Decimal, int, str],
    upper_prices_out: Optional[Dict[str, Decimal]] = None,
    native_price_max_usd: Optional[Union[Decimal, int, str]] = None,
    *,
    prices_dec_out: Optional[Dict[str, Decimal]] = None,
    upper_prices_dec_out: Optional[Dict[str, Decimal]] = None,
    skip_dex_probe: bool = False,
    rpc_incomplete_out: Optional[List[bool]] = None,
) -> Tuple[Dict[str, int], Dict[str, Decimal]]:
    """
    토큰별 decimals(), symbol() 단일 Multicall3 배치 조회 + coins.llama.fi 배치 시세 조회 + 온체인 DEX 호가 교차 검증:
    - 0-decimal ~ 77-decimal ERC-20 (`0 <= val <= 77`) 전 범위 정밀 수용 (`10 ** dec` 단위 실측).
    - 라이브 블록(`block_pin > 0`)에서 하드코딩 상수 단가($1, $3,000, $85,000) 부여를 금지하고 미확정 시 0.0으로 유지하여 Fail-Open 보장.
    - 온체인 DEX 현물과 외부 시세 간 괴리율 `> 15%` 발생 시 0.0(Fail-Open)으로 강등하며, 이익 계산용 하한(`min`)과 E1 노출 상한(`max`)을 이원화 기록.
    """
    c = _norm_chain(chain)
    cid = CHAIN_IDS.get(c, 0)
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    stables = _norm_chain_stables_set(c)
    bluechips = _norm_chain_bluechips_set(c)
    nat_lo_d = _to_dec(native_price_usd)
    eff_native_hi_d = (
        _to_dec(native_price_max_usd)
        if (native_price_max_usd is not None and _to_dec(native_price_max_usd) >= nat_lo_d)
        else nat_lo_d
    )
    decimals_map: Dict[str, int] = {}
    price_map: Dict[str, Decimal] = {}
    to_query: List[str] = []
    r_store = getattr(router, "store", None)

    for t in tokens:
        tn = _norm_addr(t)
        if not tn or tn in decimals_map or tn in alias_set:
            continue
        if r_store is not None and block_pin > 0:
            cached = r_store.get_token_meta(cid, tn, block_pin)
            c_p_d = (
                _to_dec(cached.get("price_usd_dec") if cached.get("price_usd_dec") not in (None, "") else cached.get("price_usd"))
                if cached is not None
                else _DEC_ZERO
            )
            if (
                cached is not None
                and int(cached.get("is_valid_erc20", 0)) == 1
                and c_p_d > _DEC_ZERO
            ):
                decimals_map[tn] = int(cached["decimals"])
                price_map[tn] = c_p_d
                if prices_dec_out is not None:
                    prices_dec_out[tn] = c_p_d
                if upper_prices_out is not None or upper_prices_dec_out is not None:
                    cached_max = r_store.get_price_dec(f"TOKEN_MAX:{cid}:{tn}:{block_pin}", max_age_sec=86400)
                    c_p_hi_d = cached_max[0] if (cached_max is not None and cached_max[0] > _DEC_ZERO) else c_p_d
                    hi_d = eff_native_hi_d if (tn == wnative and eff_native_hi_d > _DEC_ZERO and c_p_d > _DEC_ZERO) else max(c_p_d, c_p_hi_d)
                    if upper_prices_out is not None:
                        upper_prices_out[tn] = hi_d
                    if upper_prices_dec_out is not None:
                        upper_prices_dec_out[tn] = hi_d
                continue
        to_query.append(tn)

    if to_query:
        dec_bytes = bytes.fromhex(DECIMALS_SEL[2:])
        sym_bytes = bytes.fromhex(SYMBOL_SEL[2:])
        calls: List[Tuple[str, bytes]] = []
        for tn in to_query:
            calls.append((tn, dec_bytes))
            calls.append((tn, sym_bytes))
        mc_meta_failed = False
        res: List[Tuple[bool, bytes]] = []
        if block_pin > 0:
            try:
                res = router.multicall3(c, calls, block_pin=block_pin)
                m_tls = getattr(router, "_tls", None)
                if len(res) < len(calls) or (
                    m_tls is not None and bool(getattr(m_tls, "last_multicall_transport_failed", False))
                ):
                    mc_meta_failed = True
            except Exception:
                mc_meta_failed = True
                res = []
        if mc_meta_failed:
            _mark_rpc_incomplete_flag(rpc_incomplete_out)

        parsed_tokens: List[Tuple[str, int, str, bool]] = []
        llama_batch_addrs: List[str] = []
        for idx, tn in enumerate(to_query):
            d_ok, d_raw = res[2 * idx] if (2 * idx) < len(res) else (False, b"")
            s_ok, s_raw = res[2 * idx + 1] if (2 * idx + 1) < len(res) else (False, b"")
            dec = 18
            is_erc20 = False
            if d_ok and len(d_raw) >= 32:
                val = int.from_bytes(d_raw[:32], "big")
                if 0 <= val <= 77:
                    dec = val
                    is_erc20 = True
            sym = ""
            if s_ok and len(s_raw) >= 32:
                try:
                    sym = str(abi_decode(["string"], s_raw)[0]).strip()
                except Exception:
                    sym = s_raw[:32].rstrip(b"\x00").decode("utf-8", errors="ignore").strip()
            parsed_tokens.append((tn, dec, sym, is_erc20))
            if tn != wnative and (is_erc20 or tn in stables or tn in bluechips):
                llama_batch_addrs.append(tn)

        llama_prices_dec: Dict[str, Decimal] = {}
        if llama_batch_addrs and block_pin > 0 and not (skip_dex_probe and _is_live_real_router(router)):
            l_pref = _llama_chain_prefix(c)
            blk_ts_meta = _fetch_block_timestamp(router, c, block_pin)
            lb_chunks = [llama_batch_addrs[off_lb : off_lb + 50] for off_lb in range(0, len(llama_batch_addrs), 50)]

            def _fetch_llama_chunk(lb_chunk: List[str]) -> Dict[str, Decimal]:
                loc_p: Dict[str, Decimal] = {}
                joined_keys = ",".join(f"{l_pref}:{tn}" for tn in lb_chunk)
                batch_urls = (
                    (
                        f"https://coins.llama.fi/prices/historical/{blk_ts_meta}/{joined_keys}",
                        f"https://coins.llama.fi/prices/current/{joined_keys}",
                    )
                    if blk_ts_meta > 1_500_000_000
                    else (f"https://coins.llama.fi/prices/current/{joined_keys}",)
                )
                for b_url in batch_urls:
                    missing_tn = [tn for tn in lb_chunk if tn not in loc_p]
                    if not missing_tn:
                        break
                    try:
                        doc = router.http_get_json(b_url, timeout=5.0)
                        coins_obj = doc.get("coins") if isinstance(doc, dict) else {}
                        if isinstance(coins_obj, dict):
                            for tn in missing_tn:
                                p_val_d = _to_dec((coins_obj.get(f"{l_pref}:{tn}") or coins_obj.get(f"{c}:{tn}") or {}).get("price") or 0)
                                if p_val_d > _DEC_ZERO:
                                    loc_p[tn] = p_val_d
                    except _RECOVERABLE_IO_EXC:
                        pass
                return loc_p

            llama_prices_dec.update(
                _parallel_map_merge_dicts(
                    _fetch_llama_chunk, lb_chunks, max_workers=8, parallel=_is_live_real_router(router)
                )
            )

        probe_nat_d = nat_lo_d if nat_lo_d > _DEC_ZERO else eff_native_hi_d
        dex_probe_inputs: Dict[str, Tuple[int, Decimal, int]] = {}
        if not skip_dex_probe and block_pin > 0 and probe_nat_d > _DEC_ZERO:
            for tn, dec, _sym, is_erc20 in parsed_tokens:
                if tn == wnative:
                    continue
                if (tn in llama_prices_dec or eff_native_hi_d > _DEC_ZERO) and (
                    is_erc20 or tn in stables or tn in bluechips
                ):
                    ext_p_d = llama_prices_dec.get(tn, _DEC_ZERO)
                    if ext_p_d > _DEC_ZERO:
                        target_raw = int((Decimal("1") / ext_p_d) * (Decimal(10) ** dec))
                        probe_amt = max(1, min(10 ** min(dec + 12, 36), target_raw))
                    else:
                        probe_amt = max(1, (10 ** dec) // 100 if dec >= 2 else (10 ** dec))
                    dex_probe_inputs[tn] = (dec, ext_p_d, probe_amt)

        dex_probe_results = (
            _parallel_dex_liquidity_probes(
                router,
                c,
                block_pin,
                probe_nat_d,
                llama_prices_dec,
                [(t_k, amt_k, dec_k, ext_k) for t_k, (dec_k, ext_k, amt_k) in dex_probe_inputs.items()],
            )
            if dex_probe_inputs
            else {}
        )

        meta_rows: List[Tuple[int, str, int, str, int, bool, Decimal, Decimal, str]] = []
        for tn, dec, sym, is_erc20 in parsed_tokens:
            u_price_d = _DEC_ZERO
            u_price_hi_d = _DEC_ZERO
            if tn == wnative:
                u_price_d = nat_lo_d if nat_lo_d > _DEC_ZERO else _DEC_ZERO
                u_price_hi_d = eff_native_hi_d if eff_native_hi_d > _DEC_ZERO else u_price_d
            elif block_pin > 0 and (tn in llama_prices_dec or (eff_native_hi_d > _DEC_ZERO and (is_erc20 or tn in stables or tn in bluechips))):
                ext_p_d = llama_prices_dec.get(tn, _DEC_ZERO)
                dex_p_d = _DEC_ZERO
                dex_p_hi_d = _DEC_ZERO
                dex_depth_d = _DEC_ZERO
                dex_div = False
                if tn in dex_probe_inputs:
                    _, _, probe_amt = dex_probe_inputs[tn]
                    dex_q = dex_probe_results.get(tn)
                    if isinstance(dex_q, dict):
                        if bool(dex_q.get("price_diverged")):
                            dex_div = True
                        elif dex_q.get("exit_liquid"):
                            dex_real_d = _to_dec(
                                dex_q["realizable_usd_dec"]
                                if "realizable_usd_dec" in dex_q
                                else dex_q.get("realizable_usd")
                            )
                            dex_depth_d = _to_dec(
                                dex_q["dex_depth_usd_dec"]
                                if "dex_depth_usd_dec" in dex_q
                                else dex_q.get("dex_depth_usd")
                            )
                            if dex_real_d > _DEC_ZERO:
                                dex_unit_d = dex_real_d * (Decimal(10 ** dec) / Decimal(probe_amt))
                                dex_p_d = dex_unit_d
                                _dq_quote_raw = str(dex_q.get("best_quote_token") or "").strip().lower()
                                _dq_quote_n = _norm_addr(_dq_quote_raw) or _dq_quote_raw
                                # 네이티브 시세 상한 보정은 네이티브(WNATIVE) 견적 풀에만 적용한다(USDC 견적 풀을 ETH 상한비로 재팽창 금지).
                                dex_p_hi_d = (
                                    dex_unit_d * (eff_native_hi_d / probe_nat_d)
                                    if (eff_native_hi_d > probe_nat_d > _DEC_ZERO and _dq_quote_n in (wnative, "native"))
                                    else dex_p_d
                                )
                if dex_div:
                    u_price_d = _DEC_ZERO
                    u_price_hi_d = _DEC_ZERO
                elif ext_p_d > _DEC_ZERO and dex_p_d > _DEC_ZERO:
                    p_hi_d = max(ext_p_d, dex_p_d)
                    p_lo_d = min(ext_p_d, dex_p_d)
                    if p_hi_d > _DEC_ZERO and (p_hi_d - p_lo_d) / p_hi_d > Decimal("0.15"):
                        u_price_d = _DEC_ZERO
                        u_price_hi_d = _DEC_ZERO
                    else:
                        u_price_d = p_lo_d
                        u_price_hi_d = max(ext_p_d, dex_p_hi_d)
                elif ext_p_d <= _DEC_ZERO and dex_p_d > _DEC_ZERO and dex_depth_d >= PROFIT_FLOOR_DEC:
                    u_price_d = dex_p_d
                    u_price_hi_d = max(dex_p_d, dex_p_hi_d)
                elif tn in stables and not _is_live_real_router(router) and (ext_p_d > _DEC_ZERO or dex_p_d > _DEC_ZERO):
                    u_price_d = ext_p_d if ext_p_d > _DEC_ZERO else dex_p_d
                    u_price_hi_d = max(ext_p_d, dex_p_hi_d) if (ext_p_d > _DEC_ZERO and dex_p_hi_d > _DEC_ZERO) else u_price_d
            elif block_pin <= 0:
                if tn in stables:
                    u_price_d = Decimal("1")
                elif tn in bluechips:
                    u_price_d = Decimal("85000") if dec == 8 else Decimal("3000")
                u_price_hi_d = u_price_d
            is_valid_tok_meta = bool(
                is_erc20
                or (tn in stables)
                or (tn in bluechips)
                or (tn == wnative)
                or (u_price_d > _DEC_ZERO)
                or (block_pin <= 0 and not _is_live_real_router(router))
            )
            if is_valid_tok_meta:
                if is_erc20 or block_pin <= 0:
                    decimals_map[tn] = dec
                price_map[tn] = u_price_d
                if prices_dec_out is not None:
                    prices_dec_out[tn] = u_price_d
                if upper_prices_out is not None:
                    upper_prices_out[tn] = u_price_hi_d
                if upper_prices_dec_out is not None:
                    upper_prices_dec_out[tn] = u_price_hi_d
            if r_store is not None and block_pin > 0 and is_erc20:
                if is_valid_tok_meta and u_price_hi_d > _DEC_ZERO:
                    r_store.put_price(f"TOKEN_MAX:{cid}:{tn}:{block_pin}", u_price_hi_d, "onchain_meta_max")
                if is_valid_tok_meta and u_price_d > _DEC_ZERO:
                    meta_rows.append((
                        cid,
                        tn,
                        block_pin,
                        sym or "ERC20",
                        dec,
                        True,
                        u_price_d,
                        Decimal("100000"),
                        "onchain_meta",
                    ))
        if r_store is not None and meta_rows:
            r_store.put_token_meta_batch(meta_rows)

    return decimals_map, price_map


@_with_decimal_prec_100
def build_backward_trust_closure(
    router: RPCRouter,
    chain: str,
    seed_addresses: List[str],
    block_pin: int,
    protocol_tvl_hint_usd: Union[Decimal, int, str] = _DEC_ZERO,
    initial_resolutions: Optional[Mapping[str, ProxyResolution]] = None,
    *,
    slug: str = "",
    cancel_event: Optional[threading.Event] = None,
) -> TrustClosureResult:
    """
    다중 홉 연결 가치 도달 가능성 폐포(Connected Value Reachability Closure):
    - 외부 진입 컨트랙트 자체의 잔고가 $0이더라도 연결된 금고/풀/토큰 알로원스/동적 외부 CALL이 존재하면
      절대 E1에서 조기 종료(drop)하지 않고 E2 -> E3 -> Stage 4 Foundry 다중 금고 보존 법칙 검증으로 전달한다!
    - RPC 전면 장애 시 빈 바이트코드(안전)로 오판하지 않도록 예외를 상위로 전파하여 `미검증 차단` 처리한다.
    """
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    clean_seeds = sorted({nx for x in seed_addresses if (nx := _norm_addr(x))})
    _live_sid = getattr(router, "session_id", "") or ""
    _live_slug = str(slug or getattr(_LIVE_PROGRESS_TLS, "slug", "") or (clean_seeds[0] if clean_seeds else ""))
    if not clean_seeds:
        return TrustClosureResult(
            chain=c,
            block_pin=block_pin,
            seed_addresses=[],
            all_addresses=[],
            resolutions={},
            vault_exposures={},
            max_extractable_usd=_DEC_ZERO,
            min_gas_usd=Decimal("0.01"),
            early_exit_safe=True,
            early_exit_reason="E1_NO_VALID_SEED_ADDRESS",
        )

    clean_seed_set_r = set(clean_seeds)
    resolutions: Dict[str, ProxyResolution] = {}
    if initial_resolutions:
        for k_ir, v_ir in initial_resolutions.items():
            nk_ir = _norm_addr(k_ir)
            if (
                nk_ir
                and nk_ir in clean_seed_set_r
                and isinstance(v_ir, ProxyResolution)
                and not bool(getattr(v_ir, "unresolved_delegation", False))
            ):
                resolutions[nk_ir] = v_ir
    missing_res_seeds = [a for a in clean_seeds if a not in resolutions]
    if missing_res_seeds:
        resolutions.update(
            _resolve_proxy_and_delegates(
                router,
                c,
                missing_res_seeds,
                block_pin,
                raise_on_rpc_failure=(block_pin > 0),
            )
        )
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("audit_cancelled")
    exp_rpc_incomplete: List[bool] = [False]
    hop0_inb_cache: Dict[str, Any] = {}
    expanded = _expand_address_graph_conceptually(
        router,
        c,
        clean_seeds,
        resolutions,
        block_pin,
        max_nodes=64,
        max_hops=2,
        rpc_incomplete_out=exp_rpc_incomplete,
        hop0_inbound_out=hop0_inb_cache,
    )
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("audit_cancelled")
    new_addrs = [x for x in expanded if x not in resolutions]
    if new_addrs:
        resolutions.update(_resolve_proxy_and_delegates(router, c, new_addrs, block_pin))
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("audit_cancelled")
    def _emit_s2(stage_name: str, detail_txt: str) -> None:
        if _is_live_real_router(router) and _live_sid:
            _emit_progress(
                stage_name,
                slug=_live_slug,
                chain=c,
                block_pin=block_pin,
                session_id=_live_sid,
                detail=detail_txt,
                router=router,
            )

    _emit_s2("S2_GRAPH_DONE", f"addrs={len(resolutions)} new={len(new_addrs)}")

    all_addrs = sorted(resolutions.keys())
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    raw_stables = [x for x in CHAIN_STABLES.get(c, []) if _norm_addr(x) not in alias_set]
    bluechips = [x for x in CHAIN_BLUECHIPS.get(c, []) if _norm_addr(x) not in alias_set]
    wnative = WRAPPED_NATIVE_BY_CHAIN.get(c, "")
    stables = (
        [wnative, *raw_stables]
        if (wnative and _norm_addr(wnative) not in alias_set and wnative not in raw_stables)
        else raw_stables
    )

    seed_erc20_cands: List[str] = []
    for s_a in clean_seeds:
        r_s = resolutions.get(s_a)
        if r_s is None:
            continue
        s_codes = _res_facet_codes_hex(r_s)
        if any(any(sel_k in str(chx).lower() for sel_k in (BALANCE_OF_SEL[2:], TOTAL_SUPPLY_SEL[2:], DECIMALS_SEL[2:])) for chx in s_codes):
            seed_erc20_cands.append(s_a)

    clean_seed_set: Set[str] = set(clean_seeds)
    all_addr_set: Set[str] = set(all_addrs)
    candidate_tokens: List[str] = [
        t_a
        for t_a in dict.fromkeys([*seed_erc20_cands, *stables, *bluechips, *[a for a in all_addrs if a not in clean_seed_set]])
        if _norm_addr(t_a) not in alias_set
    ]
    cand_tok_set: Set[str] = set(candidate_tokens)
    static_tok_extras: List[str] = []

    def _add_static_tok_extra(raw_a: str) -> None:
        na_x = _norm_addr(raw_a)
        if (
            _is_non_precompile_addr(na_x)
            and na_x not in all_addr_set
            and na_x not in alias_set
            and na_x != "0xffffffffffffffffffffffffffffffffffffffff"
        ):
            static_tok_extras.append(na_x)

    for a_st in all_addrs:
        r_st = resolutions.get(a_st)
        if r_st is None:
            continue
        for chx_st in _res_facet_codes_hex(r_st):
            eb_st = _hex_to_bytes(chx_st)
            if eb_st:
                for p_st in _push20_constants(_disassemble(eb_st)):
                    _add_static_tok_extra(p_st)
    if _has_sourcify_corpus_files(SOURCIFY_PARQUET_DIR):
        cid_bt = CHAIN_IDS.get(c, 0)
        if cid_bt > 0:
            r_store_bt = getattr(router, "store", None)
            live_bt_r = _is_live_real_router(router)
            for s_v in clean_seeds[:4]:
                try:
                    sf_v: Optional[Dict[str, Any]] = None
                    if live_bt_r:
                        with _VERIFIED_SRC_MEM_LOCK:
                            _mhit_bt = _VERIFIED_SRC_MEM_CACHE.get((cid_bt, s_v))
                        if _mhit_bt is not None and (bool(_mhit_bt[1].get("verified")) or (time.time() - _mhit_bt[0]) <= SOURCES_UNVERIFIED_TTL_SEC):
                            sf_v = _mhit_bt[1]
                    if sf_v is None and r_store_bt is not None:
                        sf_v = r_store_bt.get_verified_source(cid_bt, s_v)
                        if sf_v is not None and live_bt_r:
                            with _VERIFIED_SRC_MEM_LOCK:
                                _VERIFIED_SRC_MEM_CACHE[(cid_bt, s_v)] = (time.time(), sf_v)
                    if sf_v is None:
                        sf_v = _query_local_sourcify_verified(cid_bt, s_v)
                        if isinstance(sf_v, dict) and sf_v.get("verified"):
                            if r_store_bt is not None:
                                r_store_bt.put_verified_source(
                                    cid_bt, s_v, str(sf_v.get("provider") or "sourcify_v2_local"),
                                    True, str(sf_v.get("contract_name") or "Contract"),
                                    sf_v.get("abi") or [], sf_v.get("sources") or {},
                                )
                            if live_bt_r:
                                with _VERIFIED_SRC_MEM_LOCK:
                                    _VERIFIED_SRC_MEM_CACHE[(cid_bt, s_v)] = (time.time(), sf_v)
                    if isinstance(sf_v, dict) and isinstance(sf_v.get("sources"), dict):
                        for src_txt in sf_v["sources"].values():
                            for m_ad in _ANY_ADDR_RE.findall(str(src_txt or "")):
                                _add_static_tok_extra(m_ad)
                except _RECOVERABLE_IO_EXC:
                    pass
    for st_ex in dict.fromkeys(static_tok_extras):
        if len(candidate_tokens) >= 96:
            break
        _append_unique(candidate_tokens, cand_tok_set, st_ex)

    approval_owners: Set[str] = set(all_addrs)
    ext_approval_spenders: Set[str] = set()
    observed_approval_triples: Set[Tuple[str, str, str]] = set()
    log_tokens_set: Set[str] = set()
    log_harvest_failed = False
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("audit_cancelled")
    if block_pin > 100:
        try:
            is_live_rpc_bt = _is_live_real_router(router)
            tok_lookback = 25_000 if is_live_rpc_bt else 3_000
            recent_from = max(1, block_pin - tok_lookback)
            dormant_span = 120_000 if is_live_rpc_bt else 500_000
            dormant_from = max(1, block_pin - dormant_span)
            need_dormant = recent_from > 2 and dormant_from < recent_from
            spenders_rec: Set[str] = set()
            spenders_dorm: Set[str] = set()
            trips_rec: Set[Tuple[str, str, str]] = set()
            trips_dorm: Set[Tuple[str, str, str]] = set()
            trips_inb: Set[Tuple[str, str, str]] = set()
            log_rpc_incomplete: List[bool] = [False]
            log_err_lk = threading.Lock()
            reuse_hop0_inb = bool(
                hop0_inb_cache.get("targets")
                and tuple(all_addrs) == hop0_inb_cache.get("targets")
            )
            if is_live_rpc_bt:
                with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex_lh:
                    fut_rec = ex_lh.submit(
                        _harvest_token_logs_bisect,
                        router, c, all_addrs, recent_from, block_pin, 2, spenders_rec,
                        out_approval_triples=trips_rec,
                        rpc_incomplete_out=log_rpc_incomplete,
                        _spenders_lock=log_err_lk,
                    )
                    fut_dorm = (
                        ex_lh.submit(
                            _harvest_token_logs_bisect,
                            router, c, all_addrs, dormant_from, recent_from - 1, 0, spenders_dorm,
                            out_approval_triples=trips_dorm,
                            rpc_incomplete_out=log_rpc_incomplete,
                            _spenders_lock=log_err_lk,
                        )
                        if need_dormant
                        else None
                    )
                    fut_inb = (
                        None
                        if reuse_hop0_inb
                        else ex_lh.submit(
                            _harvest_inbound_trust_and_approvals,
                            router, c, all_addrs, block_pin, True,
                            out_approval_triples=trips_inb,
                            rpc_incomplete_out=log_rpc_incomplete,
                            _err_lock=log_err_lk,
                        )
                    )
                    log_tokens, log_owners = fut_rec.result()
                    if fut_dorm is not None:
                        d_tokens, d_owners = fut_dorm.result()
                        log_tokens |= d_tokens
                        log_owners |= d_owners
                    if reuse_hop0_inb:
                        inb_grantors_bt = set(hop0_inb_cache.get("grantors") or ())
                        inb_toks_bt = set(hop0_inb_cache.get("tokens") or ())
                        trips_inb |= set(hop0_inb_cache.get("triples") or ())
                    else:
                        _, inb_grantors_bt, inb_toks_bt = fut_inb.result()
            else:
                log_tokens, log_owners = _harvest_token_logs_bisect(
                    router, c, all_addrs, recent_from, block_pin, max_depth=2, out_spenders=spenders_rec,
                    out_approval_triples=trips_rec,
                    rpc_incomplete_out=log_rpc_incomplete,
                    _spenders_lock=log_err_lk,
                )
                if need_dormant:
                    d_tokens, d_owners = _harvest_token_logs_bisect(
                        router, c, all_addrs, dormant_from, recent_from - 1, max_depth=1, out_spenders=spenders_dorm,
                        out_approval_triples=trips_dorm,
                        rpc_incomplete_out=log_rpc_incomplete,
                        _spenders_lock=log_err_lk,
                    )
                    log_tokens |= d_tokens
                    log_owners |= d_owners
                if reuse_hop0_inb:
                    inb_grantors_bt = set(hop0_inb_cache.get("grantors") or ())
                    inb_toks_bt = set(hop0_inb_cache.get("tokens") or ())
                    trips_inb |= set(hop0_inb_cache.get("triples") or ())
                else:
                    _, inb_grantors_bt, inb_toks_bt = _harvest_inbound_trust_and_approvals(
                        router, c, all_addrs, block_pin, is_live_rpc=False,
                        out_approval_triples=trips_inb,
                        rpc_incomplete_out=log_rpc_incomplete,
                        _err_lock=log_err_lk,
                    )
            if log_rpc_incomplete[0]:
                log_harvest_failed = True
            ext_approval_spenders |= spenders_rec | spenders_dorm
            observed_approval_triples |= trips_rec | trips_dorm | trips_inb
            log_tokens |= inb_toks_bt
            log_owners |= inb_grantors_bt
            for lt in sorted(log_tokens):
                n_lt = _norm_addr(lt)
                if n_lt and n_lt not in alias_set:
                    log_tokens_set.add(n_lt)
                    _append_unique(candidate_tokens, cand_tok_set, lt)
            approval_owners |= log_owners
            if len(candidate_tokens) > 400:
                candidate_tokens = candidate_tokens[:400]
                cand_tok_set = set(candidate_tokens)
        except Exception:
            log_harvest_failed = True

    closure_truncated = bool(len(expanded) >= 64)

    bal_res = router.batch_call(
        c,
        [("eth_getBalance", [_checksum(a), btag]) for a in all_addrs],
        block_pin=block_pin,
        need_archive=True,
    )
    _emit_s2("S2_LOGS_BALS_DONE", f"cand_toks={len(candidate_tokens)} log_toks={len(log_tokens_set)}")
    np_min_dec_raw, np_max_dec_raw = _estimate_native_price_interval_dec(c, router=router, block_pin=block_pin)
    np_min_dec = max(_DEC_ZERO, np_min_dec_raw)
    np_max_dec = max(_DEC_ZERO, np_max_dec_raw)
    exposures: Dict[str, VaultExposure] = {a: VaultExposure(address=a) for a in all_addrs}
    native_dec_map: Dict[str, Decimal] = {}
    tok_dec_map: Dict[str, Dict[str, Decimal]] = {a: {} for a in all_addrs}
    allow_dec_map: Dict[str, Decimal] = {a: _DEC_ZERO for a in all_addrs}
    has_unpriced_native_exposure = False
    rpc_balance_incomplete = bool(
        exp_rpc_incomplete[0]
        or log_harvest_failed
        or (
            block_pin > 0
            and (
                len(bal_res) < len(all_addrs)
                or any(b is None for b in bal_res)
                or (isinstance(router, RPCRouter) and router.last_batch_transport_failures() > 0)
            )
        )
    )
    wei_18_dec = Decimal(10) ** 18
    for a, bhex in zip(all_addrs, bal_res):
        if block_pin > 0 and (not isinstance(bhex, str) or not bhex.startswith("0x") or len(bhex) <= 2):
            rpc_balance_incomplete = True
            w = 0
        else:
            try:
                w = int(str(bhex), 16) if isinstance(bhex, str) and bhex.startswith("0x") and len(bhex) > 2 else 0
            except Exception:
                if block_pin > 0:
                    rpc_balance_incomplete = True
                w = 0
        exposures[a].native_wei = w
        n_d = (Decimal(w) / wei_18_dec) * np_max_dec
        native_dec_map[a] = n_d
        exposures[a].native_usd = n_d
        exposures[a].native_usd_dec = format(n_d, "f")
        if w > 0 and np_max_dec <= _DEC_ZERO:
            has_unpriced_native_exposure = True

    _is_live_lazy_s2 = bool(block_pin > 0 and _is_live_real_router(router))
    price_max_map: Dict[str, Decimal] = {}
    price_dec_map: Dict[str, Decimal] = {}
    price_max_dec_map: Dict[str, Decimal] = {}
    meta_rpc_incomplete: List[bool] = [False]
    dec_map, price_map = _resolve_token_metadata_batch(
        router,
        c,
        candidate_tokens,
        block_pin,
        np_min_dec,
        upper_prices_out=price_max_map,
        native_price_max_usd=np_max_dec,
        prices_dec_out=price_dec_map,
        upper_prices_dec_out=price_max_dec_map,
        skip_dex_probe=_is_live_lazy_s2,
        rpc_incomplete_out=meta_rpc_incomplete,
    )
    if meta_rpc_incomplete[0]:
        rpc_balance_incomplete = True
    eff_price_dec_map: Dict[str, Decimal] = {
        **{k: _to_dec(v) for k, v in price_map.items()},
        **price_dec_map,
    }
    bal_sel = bytes.fromhex(BALANCE_OF_SEL[2:])
    allow_sel = bytes.fromhex(ALLOWANCE_SEL[2:])

    bal_queries: List[Tuple[str, bytes]] = []
    bal_meta: List[Tuple[str, str, str]] = []
    _seed_set_bc: Set[str] = set(clean_seeds)
    _seed_erc20_set_bc: Set[str] = set(seed_erc20_cands)
    _wn_bc = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    _self_skip_canon: Set[str] = (
        set(_norm_chain_stables_set(c))
        | set(_norm_chain_bluechips_set(c))
        | set(_infra_addresses_for_chain(c))
        | ({_wn_bc} if _wn_bc else set())
    )
    probe_tokens: List[str] = (
        list(candidate_tokens)
        if meta_rpc_incomplete[0]
        else (
            [
                t_p
                for t_p in candidate_tokens
                if (nt_p := _norm_addr(t_p))
                and (
                    nt_p in dec_map
                    or nt_p in price_map
                    or nt_p in _self_skip_canon
                    or nt_p in log_tokens_set
                    or nt_p in _seed_erc20_set_bc
                )
            ]
            or list(candidate_tokens)
        )
    )
    for a in all_addrs:
        a_padded = abi_encode(["address"], [a])
        for tok in probe_tokens:
            t_norm = _norm_addr(tok)
            if t_norm and (t_norm != a or a in _seed_set_bc or t_norm not in _self_skip_canon):
                bal_queries.append((t_norm, bal_sel + a_padded))
                bal_meta.append(("bal", a, t_norm))

    ext_owner_tokens: Dict[str, Set[str]] = {}
    ext_owner_spenders_by_tok: Dict[Tuple[str, str], Set[str]] = {}
    for _t_ow, _t_sp, _t_em in observed_approval_triples:
        if _t_ow not in all_addr_set and _t_sp in all_addr_set:
            ext_owner_tokens.setdefault(_t_ow, set()).add(_t_em)
            ext_owner_spenders_by_tok.setdefault((_t_ow, _t_em), set()).add(_t_sp)

    norm_probe_toks: List[str] = [tn for tok in probe_tokens if (tn := _norm_addr(tok))]
    norm_probe_tok_set: Set[str] = set(norm_probe_toks)
    owner_list = sorted(approval_owners)
    for ow in owner_list:
        if ow not in all_addr_set:
            ow_padded = abi_encode(["address"], [ow])
            ow_toks = sorted(ext_owner_tokens[ow] & norm_probe_tok_set) if ow in ext_owner_tokens else norm_probe_toks
            for t_norm in ow_toks:
                bal_queries.append((t_norm, bal_sel + ow_padded))
                bal_meta.append(("ow_bal", ow, t_norm))

    ext_sp_list = sorted(s for s in ext_approval_spenders if s not in all_addr_set)[:24]

    def _build_allow_queries(pos_pairs: Optional[Set[Tuple[str, str]]]) -> Tuple[List[Tuple[str, bytes]], List[Tuple[str, str, str]]]:
        aq: List[Tuple[str, bytes]] = []
        am: List[Tuple[str, str, str]] = []
        pair_cd_cache: Dict[Tuple[str, str], bytes] = {}

        def _allow_cd(owner_a: str, spender_a: str) -> bytes:
            k_cd = (owner_a, spender_a)
            cd_v = pair_cd_cache.get(k_cd)
            if cd_v is None:
                cd_v = allow_sel + abi_encode(["address", "address"], [owner_a, spender_a])
                pair_cd_cache[k_cd] = cd_v
            return cd_v

        # 연결된 금고(all_addrs 포함) 및 외부 오너가 프로토콜 컨트랙트(spender)에 부여한 allowance 전수 조사
        for ow in owner_list:
            ow_is_ext_exact = ow not in all_addr_set and ow in ext_owner_tokens
            ow_toks_a = sorted(ext_owner_tokens[ow] & norm_probe_tok_set) if ow_is_ext_exact else norm_probe_toks
            for t_norm in ow_toks_a:
                if pos_pairs is not None and (ow, t_norm) not in pos_pairs:
                    continue
                sp_iter: Sequence[str] = (
                    sorted(ext_owner_spenders_by_tok.get((ow, t_norm), ()))
                    if ow_is_ext_exact
                    else all_addrs
                )
                for spender in sp_iter:
                    if spender == ow:
                        continue
                    aq.append((t_norm, _allow_cd(ow, spender)))
                    am.append((f"allow:{spender}", ow, t_norm))
                    if spender != PERMIT2_ADDR and len(aq) < 2048:
                        p2_cd = bytes.fromhex(
                            encode_calldata(PERMIT2_ALLOWANCE_SEL, ["address", "address", "address"], [ow, t_norm, spender])[2:]
                        )
                        aq.append((PERMIT2_ADDR, p2_cd))
                        am.append((f"p2_allow:{spender}", ow, t_norm))
        for v_addr in all_addrs:
            for t_norm in norm_probe_toks:
                if pos_pairs is not None and (v_addr, t_norm) not in pos_pairs:
                    continue
                for ext_sp in ext_sp_list:
                    aq.append((t_norm, _allow_cd(v_addr, ext_sp)))
                    am.append((f"ext_allow:{ext_sp}", v_addr, t_norm))
        return aq, am

    def _exec_mc_queries(q_list: List[Tuple[str, bytes]]) -> List[Tuple[bool, bytes]]:
        nonlocal rpc_balance_incomplete
        if not q_list:
            return []
        _mc_chunk_sz = 256
        _mc_chunks = [q_list[i : i + _mc_chunk_sz] for i in range(0, len(q_list), _mc_chunk_sz)]
        q_out: List[Tuple[bool, bytes]] = []
        if len(_mc_chunks) >= 2 and _is_live_real_router(router):
            def _run_chunk(_ch: List[Tuple[str, bytes]]) -> Tuple[List[Tuple[bool, bytes]], bool]:
                res_c = router.multicall3(c, _ch, block_pin=block_pin, chunk_size=_mc_chunk_sz)
                t_fail = bool(block_pin > 0 and isinstance(router, RPCRouter) and router.last_multicall_transport_failed())
                return res_c, t_fail
            with concurrent.futures.ThreadPoolExecutor(max_workers=min(24, len(_mc_chunks))) as ex_mq:
                for _chunk_res, _chunk_fail in ex_mq.map(_run_chunk, _mc_chunks):
                    q_out.extend(_chunk_res)
                    if _chunk_fail:
                        rpc_balance_incomplete = True
        else:
            for _ch_s in _mc_chunks:
                q_out.extend(router.multicall3(c, _ch_s, block_pin=block_pin, chunk_size=_mc_chunk_sz))
                if block_pin > 0 and isinstance(router, RPCRouter) and router.last_multicall_transport_failed():
                    rpc_balance_incomplete = True
        if block_pin > 0 and (len(q_out) < len(q_list) or not any(ok for ok, _ in q_out)):
            try:
                rebuilt_mc: List[Tuple[bool, bytes]] = list(q_out) + [(False, b"")] * max(0, len(q_list) - len(q_out))
                fb_offsets = list(range(0, len(q_list), 64))

                def _run_fb_slice(fb_off: int) -> Tuple[int, List[Any]]:
                    fb_slice = q_list[fb_off : fb_off + 64]
                    fb_calls = [
                        ("eth_call", [{"to": _checksum(t_a), "data": "0x" + bytes(cd).hex()}, btag])
                        for t_a, cd in fb_slice
                    ]
                    return fb_off, router.batch_call(
                        c,
                        fb_calls,
                        block_pin=block_pin,
                        need_archive=True,
                        raise_on_all_failed=True,
                    )

                fb_results = _map_chunks_live(router, _run_fb_slice, fb_offsets, max_workers=16)
                for fb_off, fb_res in fb_results:
                    exp_fb_len = min(64, len(q_list) - fb_off)
                    if len(fb_res) < exp_fb_len or any(r_fb is None for r_fb in fb_res):
                        rpc_balance_incomplete = True
                    for rel_fb, r_fb in enumerate(fb_res):
                        idx_fb = fb_off + rel_fb
                        if idx_fb < len(rebuilt_mc) and isinstance(r_fb, str) and r_fb.startswith("0x") and len(r_fb) > 2:
                            rebuilt_mc[idx_fb] = (True, _hex_to_bytes(r_fb))
                q_out = rebuilt_mc
            except Exception:
                rpc_balance_incomplete = True
        return q_out

    owner_bals: Dict[Tuple[str, str], int] = {}
    pending_allows: List[Tuple[str, str, str, int]] = []
    pending_ext_allows: List[Tuple[str, str, str, int]] = []
    has_unpriced_token_exposure = has_unpriced_native_exposure

    def _tok_amount_hi_usd_dec(tn: str, amt: int) -> Tuple[Decimal, Decimal]:
        if block_pin > 0 and tn != wnative and tn not in dec_map:
            return _DEC_ZERO, _DEC_ZERO
        dec_t = dec_map.get(tn, 18)
        u_p_d = price_dec_map.get(tn, _to_dec(price_map.get(tn, 0)))
        u_p_hi_d = price_max_dec_map.get(tn, _to_dec(price_max_map.get(tn, u_p_d)))
        return (Decimal(amt) / (Decimal(10) ** dec_t)) * u_p_hi_d, u_p_d

    mc_meta: List[Tuple[str, str, str]] = []
    mc_out: List[Tuple[bool, bytes]] = []
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("audit_cancelled")
    if _is_live_lazy_s2:
        bal_out = _exec_mc_queries(bal_queries)
        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("audit_cancelled")
        positive_bal_pairs: Set[Tuple[str, str]] = set()
        positive_toks: Set[str] = set()
        for (_kind_b, actor_b, t_norm_b), (ok_b, rdata_b) in zip(bal_meta, bal_out):
            if ok_b and len(rdata_b) >= 32 and int.from_bytes(rdata_b[:32], "big") > 0:
                positive_bal_pairs.add((actor_b, t_norm_b))
                positive_toks.add(t_norm_b)
        allow_queries, allow_meta = _build_allow_queries(positive_bal_pairs)
        allow_out = _exec_mc_queries(allow_queries)
        mc_meta = bal_meta + allow_meta
        mc_out = bal_out + allow_out
        if positive_toks:
            held_p_targets = sorted(positive_toks | ({_wn_bc} if _wn_bc else set()))
            held_p_max: Dict[str, Decimal] = {}
            held_p_dec: Dict[str, Decimal] = {}
            held_p_max_dec: Dict[str, Decimal] = {}
            held_meta_incomplete: List[bool] = [False]
            h_dec_m, h_price_m = _resolve_token_metadata_batch(
                router,
                c,
                held_p_targets,
                block_pin,
                np_min_dec,
                upper_prices_out=held_p_max,
                native_price_max_usd=np_max_dec,
                prices_dec_out=held_p_dec,
                upper_prices_dec_out=held_p_max_dec,
                skip_dex_probe=False,
                rpc_incomplete_out=held_meta_incomplete,
            )
            if held_meta_incomplete[0]:
                rpc_balance_incomplete = True
            dec_map.update(h_dec_m)
            price_map.update(h_price_m)
            price_max_map.update(held_p_max)
            price_dec_map.update(held_p_dec)
            price_max_dec_map.update(held_p_max_dec)
            eff_price_dec_map.update({k: _to_dec(v) for k, v in h_price_m.items()})
            eff_price_dec_map.update(held_p_dec)
    else:
        allow_queries, allow_meta = _build_allow_queries(None)
        mc_queries = bal_queries + allow_queries
        mc_meta = bal_meta + allow_meta
        if mc_queries:
            mc_out = _exec_mc_queries(mc_queries)

    p2_block_ts_cache: Optional[int] = None
    if mc_meta and mc_out:
        for (kind, actor, t_norm), (ok, rdata) in zip(mc_meta, mc_out):
            if not ok or len(rdata) < 32:
                continue
            raw_amt = int.from_bytes(rdata[:32], "big")
            if raw_amt <= 0:
                continue
            if kind == "bal":
                exposures[actor].token_balances[t_norm] = raw_amt
                t_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, raw_amt)
                tok_dec_map[actor][t_norm] = t_d
                exposures[actor].token_usd[t_norm] = t_d
                exposures[actor].token_usd_dec[t_norm] = format(t_d, "f")
                owner_bals[(actor, t_norm)] = raw_amt
                if u_price_d <= _DEC_ZERO:
                    has_unpriced_token_exposure = True
            elif kind == "ow_bal":
                owner_bals[(actor, t_norm)] = raw_amt
            elif kind.startswith("allow:"):
                spender = kind.split(":", 1)[1]
                pending_allows.append((spender, actor, t_norm, raw_amt))
            elif kind.startswith("p2_allow:"):
                if len(rdata) < 64:
                    continue
                p2_amt = raw_amt & _ADDR_MASK_160
                p2_exp = int.from_bytes(rdata[32:64], "big") & ((1 << 48) - 1)
                if p2_amt <= 0:
                    continue
                if p2_exp > 0 and block_pin > 0:
                    if p2_block_ts_cache is None:
                        p2_block_ts_cache = _fetch_block_timestamp(router, c, block_pin)
                    if p2_block_ts_cache > 0 and p2_exp < p2_block_ts_cache:
                        continue
                spender = kind.split(":", 1)[1]
                pending_allows.append((spender, actor, t_norm, p2_amt))
            elif kind.startswith("ext_allow:"):
                ext_sp = kind.split(":", 1)[1]
                pending_ext_allows.append((ext_sp, actor, t_norm, raw_amt))

    owner_effective_raw: Dict[Tuple[str, str], int] = {}
    for a_k, exp_v in exposures.items():
        for t_k, amt_v in exp_v.token_balances.items():
            if amt_v > 0:
                owner_effective_raw[(a_k, t_k)] = max(owner_effective_raw.get((a_k, t_k), 0), amt_v)

    # Deduplicate (spender, ow, t_norm) across ERC-20 approve & Permit2 so shared owner balance is never double-counted
    merged_allows: Dict[Tuple[str, str, str], int] = {}
    for spender, ow, t_norm, allow_amt in pending_allows:
        ak = (spender, ow, t_norm)
        if allow_amt > merged_allows.get(ak, 0):
            merged_allows[ak] = allow_amt

    active_approved_owners: List[str] = []
    seen_active_owners: Set[str] = set()
    for (spender, ow, t_norm), allow_amt in merged_allows.items():
        eff_amt = min(allow_amt, owner_bals.get((ow, t_norm), 0))
        if eff_amt > 0 and spender in exposures:
            al_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, eff_amt)
            allow_dec_map[spender] = allow_dec_map.get(spender, _DEC_ZERO) + al_d
            exposures[spender].allowance_usd = allow_dec_map[spender]
            exposures[spender].allowance_usd_dec = format(allow_dec_map[spender], "f")
            owner_effective_raw[(ow, t_norm)] = max(owner_effective_raw.get((ow, t_norm), 0), eff_amt)
            if ow not in all_addr_set:
                _append_unique(active_approved_owners, seen_active_owners, ow)
            if u_price_d <= _DEC_ZERO:
                has_unpriced_token_exposure = True

    held_tok_raw: Dict[str, int] = {}
    for (_, t_k), raw_v in owner_effective_raw.items():
        if raw_v > 0:
            held_tok_raw[t_k] = held_tok_raw.get(t_k, 0) + raw_v

    total_onchain_dec = _DEC_ZERO
    native_total_dec = _DEC_ZERO
    native_total_hi_dec = _DEC_ZERO
    nat_scale_hi = (
        (np_max_dec / np_min_dec)
        if (np_min_dec > _DEC_ZERO and np_max_dec > np_min_dec)
        else Decimal("1")
    )
    for a, exp in exposures.items():
        if exp.native_wei > 0 and np_max_dec <= _DEC_ZERO:
            has_unpriced_token_exposure = True
        nat_a_d = native_dec_map.get(a, _DEC_ZERO)
        native_total_dec += (Decimal(exp.native_wei) / wei_18_dec) * np_min_dec if np_min_dec > _DEC_ZERO else nat_a_d
        native_total_hi_dec += nat_a_d
        exp_tot_dec = (
            nat_a_d
            + sum(tok_dec_map.get(a, {}).values(), _DEC_ZERO)
            + allow_dec_map.get(a, _DEC_ZERO)
        )
        exp.total_usd = exp_tot_dec
        exp.total_usd_dec = format(exp_tot_dec, "f")
        total_onchain_dec += exp_tot_dec

    # 아웃바운드 승인된 외부 스펜더 노출 기록(프로토콜 금고 보유분 중복 합산 없이 allowance_usd만 별도 노출)
    for ext_sp, ow_v, t_norm, allow_amt in pending_ext_allows:
        eff_amt = min(allow_amt, owner_bals.get((ow_v, t_norm), 0))
        if eff_amt > 0 and ext_sp not in all_addr_set:
            al_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, eff_amt)
            if u_price_d <= _DEC_ZERO:
                has_unpriced_token_exposure = True
            if al_d > _DEC_ZERO:
                ext_exp = exposures.get(ext_sp)
                if ext_exp is None:
                    ext_exp = VaultExposure(address=ext_sp)
                    exposures[ext_sp] = ext_exp
                prev_ext_dec = _to_dec(ext_exp.allowance_usd_dec or ext_exp.allowance_usd)
                new_ext_dec = prev_ext_dec + al_d
                ext_exp.allowance_usd = new_ext_dec
                ext_exp.allowance_usd_dec = format(new_ext_dec, "f")
                ext_exp.total_usd = new_ext_dec
                ext_exp.total_usd_dec = format(new_ext_dec, "f")

    realizable_tokens_dec = _DEC_ZERO
    realizable_tokens_hi_dec = _DEC_ZERO
    verified_exit_pools: Dict[str, Dict[str, Any]] = {}
    stables_set_bt = {_norm_addr(x) for x in stables if _norm_addr(x)}
    all_tokens_dex_verified = bool(
        block_pin > 0 and held_tok_raw and not has_unpriced_token_exposure and not rpc_balance_incomplete
    )
    def _build_verified_exit_pool_entry(
        dex_res: Dict[str, Any],
        held_raw_amt: int,
        is_paused: bool = False,
    ) -> Dict[str, Any]:
        real_d = _to_dec(dex_res.get("realizable_usd_dec") or dex_res.get("realizable_usd") or 0)
        entry: Dict[str, Any] = {
            "pool": str(dex_res.get("best_pool_address") or ""),
            "quote_token": str(dex_res.get("best_quote_token") or ""),
            "dex_kind": str(dex_res.get("best_dex_kind") or ""),
            "v3_fee": int(dex_res.get("v3_fee") or 0),
            "curve_i": int(dex_res.get("curve_i") or 0),
            "curve_j": int(dex_res.get("curve_j") or 0),
            "curve_underlying": bool(dex_res.get("curve_underlying")),
            "solidly_stable": bool(dex_res.get("solidly_stable")),
            "held_raw": str(held_raw_amt),
            "realizable_usd": real_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
            "realizable_usd_dec": format(real_d, "f"),
            "dex_depth_usd": _to_dec(dex_res.get("dex_depth_usd_dec") or dex_res.get("dex_depth_usd") or 0).quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
            "paused": bool(is_paused),
        }
        if dex_res.get("best_other_token"):
            entry["lp_other_token"] = str(dex_res.get("best_other_token") or "")
        if dex_res.get("redeem_target"):
            entry["redeem_target"] = str(dex_res.get("redeem_target") or "")
        if isinstance(dex_res.get("underlying_exit"), dict) and dex_res["underlying_exit"].get("pool"):
            entry["underlying_exit"] = dict(dex_res["underlying_exit"])
        return entry

    ordered_held_toks = sorted(held_tok_raw.items())
    held_dex_specs: List[Tuple[str, int, int, Decimal]] = [
        (t_n, t_r, dec_map.get(t_n, 18), eff_price_dec_map.get(t_n, _DEC_ZERO))
        for t_n, t_r in ordered_held_toks
        if block_pin > 0 and not (t_n == wnative and np_max_dec > _DEC_ZERO)
        and (t_n in dec_map or t_n == wnative)
        and eff_price_dec_map.get(t_n, _DEC_ZERO) > _DEC_ZERO
    ]
    if len(held_dex_specs) > 200:
        held_dex_specs.sort(
            key=lambda s: (Decimal(s[1]) / (Decimal(10) ** s[2])) * s[3] if s[3] > _DEC_ZERO else _DEC_ZERO,
            reverse=True,
        )
        held_dex_specs = held_dex_specs[:200]
    held_dex_map = _parallel_dex_liquidity_probes(
        router,
        c,
        block_pin,
        np_min_dec,
        eff_price_dec_map,
        held_dex_specs,
        default_on_error={"exit_liquid": False, "realizable_usd": _DEC_ZERO},
    )
    for t_norm, tot_raw in ordered_held_toks:
        dec_t = dec_map.get(t_norm, 18)
        if t_norm == wnative and np_max_dec > _DEC_ZERO:
            eff_wn_lo_d = np_min_dec if np_min_dec > _DEC_ZERO else np_max_dec
            tok_real_d = (Decimal(tot_raw) / (Decimal(10) ** dec_t)) * eff_wn_lo_d
            tok_real_hi_d = (Decimal(tot_raw) / (Decimal(10) ** dec_t)) * np_max_dec
            realizable_tokens_dec += tok_real_d
            realizable_tokens_hi_dec += tok_real_hi_d
            verified_exit_pools[t_norm] = {
                "pool": _checksum(wnative),
                "quote_token": "native",
                "dex_kind": "unwrap_native",
                "held_raw": str(tot_raw),
                "realizable_usd": tok_real_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
                "realizable_usd_dec": format(tok_real_d, "f"),
                "dex_depth_usd": tok_real_hi_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
                "paused": False,
            }
            continue
        if block_pin <= 0:
            nom_d, _ = _tok_amount_hi_usd_dec(t_norm, tot_raw)
            realizable_tokens_dec += nom_d
            realizable_tokens_hi_dec += nom_d
            all_tokens_dex_verified = False
            continue
        dex_q = held_dex_map.get(t_norm) or {"exit_liquid": False, "realizable_usd": _DEC_ZERO}
        if bool(dex_q.get("rpc_incomplete")):
            all_tokens_dex_verified = False
        if dex_q.get("paused"):
            verified_exit_pools[t_norm] = {
                "pool": "",
                "quote_token": "",
                "dex_kind": "paused_token",
                "held_raw": str(tot_raw),
                "realizable_usd": _DEC_ZERO,
                "realizable_usd_dec": "0",
                "dex_depth_usd": _DEC_ZERO,
                "paused": True,
            }
        elif dex_q.get("best_pool_address") or (t_norm in stables_set_bt and dex_q.get("exit_liquid")):
            has_best_pool = bool(dex_q.get("best_pool_address"))
            tok_real_d = _to_dec(dex_q.get("realizable_usd_dec") or dex_q.get("realizable_usd") or 0)
            realizable_tokens_dec += tok_real_d
            nom_hi_d, _ = _tok_amount_hi_usd_dec(t_norm, tot_raw)
            if has_best_pool:
                nom_lo_d = (Decimal(tot_raw) / (Decimal(10) ** dec_t)) * eff_price_dec_map.get(t_norm, _DEC_ZERO)
                tok_real_hi_d = tok_real_d
                if nom_hi_d > nom_lo_d > _DEC_ZERO:
                    tok_real_hi_d = max(tok_real_hi_d, min(nom_hi_d, tok_real_d * (nom_hi_d / nom_lo_d)))
                _best_qt_raw = str(dex_q.get("best_quote_token") or "").strip().lower()
                _best_qt_norm = _norm_addr(_best_qt_raw) or _best_qt_raw
                if nat_scale_hi > Decimal("1") and _best_qt_norm in (wnative, "native"):
                    tok_real_hi_d = max(tok_real_hi_d, tok_real_d * nat_scale_hi)
                realizable_tokens_hi_dec += tok_real_hi_d
                exit_entry = _build_verified_exit_pool_entry(dex_q, tot_raw, is_paused=False)
            else:
                realizable_tokens_hi_dec += max(tok_real_d, nom_hi_d)
                exit_entry = {
                    "pool": "",
                    "quote_token": _checksum(t_norm),
                    "dex_kind": "stablecoin_cap",
                    "held_raw": str(tot_raw),
                    "realizable_usd": tok_real_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
                    "realizable_usd_dec": format(tok_real_d, "f"),
                    "dex_depth_usd": _to_dec(dex_q.get("dex_depth_usd_dec") or dex_q.get("dex_depth_usd") or 0).quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN),
                    "paused": False,
                }
            verified_exit_pools[t_norm] = exit_entry
        else:
            all_tokens_dex_verified = False

    if block_pin > 0 and verified_exit_pools:
        bench_hop_set = _harness_benchmark_set(c) | stables_set_bt
        if wnative:
            bench_hop_set.add(wnative)
        hop_frontier: List[str] = []
        hop_seen: Set[str] = set()
        for ep_v in verified_exit_pools.values():
            if not isinstance(ep_v, dict) or bool(ep_v.get("paused")):
                continue
            und_h = ep_v.get("underlying_exit") if isinstance(ep_v.get("underlying_exit"), dict) else None
            for q_raw in (
                ep_v.get("quote_token"),
                ep_v.get("lp_other_token"),
                ep_v.get("other_token"),
                und_h.get("quote_token") if und_h else "",
                und_h.get("lp_other_token") if und_h else "",
            ):
                qn = _norm_addr(str(q_raw or ""))
                if qn and qn not in bench_hop_set and qn not in verified_exit_pools and qn not in hop_seen:
                    hop_seen.add(qn)
                    hop_frontier.append(qn)
        if hop_frontier:
            hop_targets = hop_frontier[:8]
            hop_meta_incomplete: List[bool] = [False]
            hop_dec_map, hop_p_map = _resolve_token_metadata_batch(
                router,
                c,
                hop_targets,
                block_pin,
                native_price_usd=np_min_dec,
                prices_dec_out=eff_price_dec_map,
                rpc_incomplete_out=hop_meta_incomplete,
            )
            if hop_meta_incomplete[0]:
                rpc_balance_incomplete = True
                all_tokens_dex_verified = False
            for h_tok, h_dec in hop_dec_map.items():
                dec_map.setdefault(h_tok, int(h_dec))
            for h_tok, h_pf in hop_p_map.items():
                price_map.setdefault(h_tok, _to_dec(h_pf))
            hop_specs: List[Tuple[str, int, int, Decimal]] = [
                (
                    h_tok,
                    10 ** max(0, min(int(dec_map.get(h_tok, 18)), 77)),
                    max(0, min(int(dec_map.get(h_tok, 18)), 77)),
                    eff_price_dec_map.get(h_tok, _DEC_ZERO),
                )
                for h_tok in hop_targets
            ]
            hop_dex_map = _parallel_dex_liquidity_probes(
                router,
                c,
                block_pin,
                np_min_dec,
                eff_price_dec_map,
                hop_specs,
                default_on_error={},
            )
            for h_tok, unit_raw_h, _, _ in hop_specs:
                dex_h = hop_dex_map.get(h_tok) or {}
                if isinstance(dex_h, dict) and bool(dex_h.get("rpc_incomplete")):
                    all_tokens_dex_verified = False
                if isinstance(dex_h, dict) and dex_h.get("best_pool_address"):
                    verified_exit_pools[h_tok] = _build_verified_exit_pool_entry(
                        dex_h, unit_raw_h, is_paused=bool(dex_h.get("paused"))
                    )
        for t_chk, raw_chk in held_tok_raw.items():
            if raw_chk <= 0 or t_chk in bench_hop_set:
                continue
            ep_c = verified_exit_pools.get(t_chk)
            if not isinstance(ep_c, dict) or bool(ep_c.get("paused")) or not ep_c.get("pool"):
                continue
            dk_c = str(ep_c.get("dex_kind") or "")
            und_c = ep_c.get("underlying_exit") if isinstance(ep_c.get("underlying_exit"), dict) else None
            eff_qt_c = _norm_addr(str((und_c.get("quote_token") if und_c else "") or ep_c.get("quote_token") or ""))
            if eff_qt_c and eff_qt_c not in bench_hop_set:
                ep_h2 = verified_exit_pools.get(eff_qt_c)
                h2_ok = isinstance(ep_h2, dict) and not bool(ep_h2.get("paused")) and bool(ep_h2.get("pool"))
                if dk_c == "lp_token":
                    lp_oth_c = _norm_addr(str(ep_c.get("lp_other_token") or ""))
                    ep_lp2 = verified_exit_pools.get(lp_oth_c) if lp_oth_c else None
                    lp2_ok = (lp_oth_c in bench_hop_set) or (
                        isinstance(ep_lp2, dict) and not bool(ep_lp2.get("paused")) and bool(ep_lp2.get("pool"))
                    )
                    h2_ok = h2_ok or lp2_ok
                if not h2_ok:
                    all_tokens_dex_verified = False

    realizable_extractable_dec = max(_DEC_ZERO, native_total_dec + realizable_tokens_dec)
    realizable_upper_dec = max(realizable_extractable_dec, native_total_hi_dec + realizable_tokens_hi_dec)
    realizable_extractable_dec_str = format(realizable_extractable_dec, "f")

    max_extractable_dec = max(total_onchain_dec, max(_DEC_ZERO, _to_dec(protocol_tvl_hint_usd)))
    gas_wei = fetch_gas_price_wei(router, c, block_pin) if block_pin > 0 else (2_000_000_000 if c == "ethereum" else 100_000_000)
    min_gas_dec = (Decimal(gas_wei * 21_000) / wei_18_dec) * np_min_dec
    total_onchain_dec_str = format(total_onchain_dec, "f")
    max_extractable_dec_str = format(max_extractable_dec, "f")
    min_gas_dec_str = format(min_gas_dec, "f")

    has_any_code = False
    has_dynamic_reachability = False
    has_view_selector_logic = False
    has_unresolved_delegation = False
    for r in resolutions.values():
        if r.unresolved_delegation:
            has_unresolved_delegation = True
        if r.proxy_kind == "eip7702":
            has_any_code = True
            has_dynamic_reachability = True
        for chx in _res_facet_codes_hex(r):
            eb = _hex_to_bytes(chx)
            if len(eb) > 0:
                has_any_code = True
                dis_eb = _disassemble(eb)
                if _has_dynamic_or_external_call_capability(dis_eb):
                    has_dynamic_reachability = True
                if any(nm == "RETURN" for _, nm, _ in dis_eb) and any(
                    nm == "PUSH4" and len(imm) == 4 and imm != b"\xff\xff\xff\xff" for _, nm, imm in dis_eb
                ):
                    has_view_selector_logic = True

    price_dec_str_map: Dict[str, str] = {
        k: format(v, "f") for k, v in eff_price_dec_map.items()
    }

    def _make_closure_result(
        early_safe: bool,
        early_reason: str,
        max_usd: Decimal = max_extractable_dec,
        max_usd_dec_s: str = max_extractable_dec_str,
        dyn_reach: bool = False,
    ) -> TrustClosureResult:
        return TrustClosureResult(
            chain=c,
            block_pin=block_pin,
            seed_addresses=clean_seeds,
            all_addresses=all_addrs,
            resolutions=resolutions,
            vault_exposures=exposures,
            max_extractable_usd=max_usd,
            min_gas_usd=min_gas_dec,
            early_exit_safe=early_safe,
            early_exit_reason=early_reason,
            token_decimals=dec_map,
            token_prices_usd=price_map,
            has_dynamic_external_reachability=dyn_reach,
            approved_owners=active_approved_owners,
            max_extractable_usd_dec=max_usd_dec_s,
            min_gas_usd_dec=min_gas_dec_str,
            realizable_extractable_usd=realizable_extractable_dec,
            realizable_extractable_usd_dec=realizable_extractable_dec_str,
            verified_exit_pools=verified_exit_pools,
            has_unpriced_token_exposure=has_unpriced_token_exposure,
            rpc_balance_incomplete=rpc_balance_incomplete,
            closure_truncated=closure_truncated,
            token_prices_usd_dec=price_dec_str_map,
        )

    if (
        not has_any_code
        and not has_unresolved_delegation
        and total_onchain_dec < PROFIT_FLOOR_DEC
        and not has_unpriced_token_exposure
        and not rpc_balance_incomplete
    ):
        return _make_closure_result(
            True,
            "E1_ALL_TARGETS_EMPTY_CODE",
            max_usd=total_onchain_dec,
            max_usd_dec_s=total_onchain_dec_str,
        )

    v4_pool_mgr_set = {_norm_addr(m_a) for m_a in UNISWAP_V4_POOL_MANAGERS.get(c, ()) if _norm_addr(m_a)}
    has_v4_pool_mgr = bool(v4_pool_mgr_set and any(a in v4_pool_mgr_set for a in all_addrs))
    e1_below_nominal = (max_extractable_dec - min_gas_dec) < PROFIT_FLOOR_DEC
    e1_below_realizable = bool(
        all_tokens_dex_verified
        and not has_v4_pool_mgr
        and _to_dec(protocol_tvl_hint_usd) <= _DEC_ZERO
        and (realizable_upper_dec - min_gas_dec) < PROFIT_FLOOR_DEC
    )
    if (
        (e1_below_nominal or e1_below_realizable)
        and not has_dynamic_reachability
        and not has_unresolved_delegation
        and not has_unpriced_token_exposure
        and not rpc_balance_incomplete
        and not has_view_selector_logic
        and not closure_truncated
    ):
        e1_tag = (
            f"E1_PURE_STATIC_BELOW_MIN_USD({max_extractable_dec:.2f}<{MIN_PROFIT_USD})"
            if e1_below_nominal
            else f"E1_REALIZABLE_BELOW_MIN_USD({realizable_extractable_dec:.2f}<{MIN_PROFIT_USD})"
        )
        return _make_closure_result(True, e1_tag)

    return _make_closure_result(False, "", dyn_reach=has_dynamic_reachability)


# ═══════════════════════════════════════════════════════════════════════════
# §5. 개념 기반 바이트코드 CFG, E2(Value/State Sink), E3(Caller-Dominator),
#     4대 상태 채널 슬라이서 및 불연속 경계 솔버 (Discontinuity Solver)
# ═══════════════════════════════════════════════════════════════════════════

VALUE_SINK_SELECTORS: Set[str] = {
    TRANSFER_SEL,                    # transfer(address,uint256)
    TRANSFER_FROM_SEL,               # transferFrom(address,address,uint256)
    APPROVE_SEL,                     # approve(address,uint256)
    "0x2e1a7d4d",                    # withdraw(uint256)
    "0xb460af94",                    # withdraw(uint256,address,address) - ERC4626
    ERC4626_REDEEM_SEL,              # redeem(uint256,address,address) - ERC4626
    COMPOUND_REDEEM_UNDERLYING_SEL,  # redeemUnderlying(uint256) - Compound
    COMPOUND_REDEEM_SEL,             # redeem(uint256) - Compound
    "0xc5ebeaec",                    # borrow(uint256)
    "0x40c10f19",                    # mint(address,uint256)
    "0x6a627842",                    # mint(address)
    V2_BURN_SEL,                     # burn(address)
    V2_SWAP_SEL,                     # swap(uint256,uint256,address,bytes) - UniV2
    V3_SWAP_SEL,                     # swap(address,bool,int256,uint160,bytes) - UniV3
    "0xbc25cf77",                    # skim(address)
    V3_FLASH_SEL,                    # flash(address,uint256,uint256,bytes) - UniV3
    "0xab9c4b5d",                    # flashLoan(...) - Aave v2/v3
    ERC3156_FLASH_LOAN_SEL,          # flashLoan(address,address,uint256,bytes) - ERC-3156
}

# Computed hex for intent / AA / module-batch sinks via _selector() to guarantee 0 manual selector drift
for _intent_sig in (
    "handleOps((address,uint256,bytes,bytes,uint256,uint256,uint256,uint256,uint256,bytes,bytes)[],address)",
    "handleOps((address,uint256,bytes,bytes,bytes32,uint256,bytes32,bytes,bytes)[],address)",
    "executeBatch((uint8,address,uint256,bytes)[])",
    "executeBatch((address,uint256,bytes)[])",
    "fill((bytes32,address,uint256,uint256,uint256,address),bytes)",
    "executeIntent(bytes,bytes,bytes32,bytes)",
    # ERC-777 hook callbacks (token-side sends/receives -> reentrancy surface, latest SOTA top-paid vectors)
    "tokensToSend(address,address,address,uint256,bytes,bytes)",
    "tokensReceived(address,address,address,uint256,bytes,bytes,bytes)",
    # ERC-1820 registry hook resolution (setInterface/getInterface/interfaceHash)
    "setInterfaceForAddress(address,bytes4,address)",
    "getInterfaceForAddress(address,bytes4)",
    "interfaceHash(string)",
    # ERC-1363 transferAndCall hook sinks (onTransferReceived callback)
    "transferAndCall(address,uint256,bytes)",
    "transferAndCall(address,uint256)",
    "transferFromAndCall(address,address,uint256,bytes)",
    "transferFromAndCall(address,address,uint256)",
    # ERC-7821 minimal batch executor execute(bytes32,bytes) - EIP-7702 delegation sink distinct from ERC-7579 executeBatch
    "execute(bytes32,bytes)",
    # Uniswap V4 PoolManager.unlock(bytes) - hook unlock callback gateway (take/settle/balanceDelta coupling)
    "unlock(bytes)",
    # ERC-7579 single execute(address,uint256,bytes) - EIP-7702 delegation single-call sink distinct from executeBatch
    "execute(address,uint256,bytes)",
    # CowSwap GPv2 settlement sink settle() - intent settlement entry with solver-signed orders
    "settle()",
    # DEX reserve accounting sink (deflationary/reflection burn + sync() reserve-skew vector)
    "sync()",
    # ERC-7540 asynchronous vault request/claim/cancel sinks (RWA/LRT async vault surface)
    "requestDeposit(uint256,address,address)",
    "requestRedeem(uint256,address,address)",
    "deposit(uint256,address,address)",
    "mint(uint256,address,address)",
    "cancelDepositRequest(uint256,address)",
    "cancelRedeemRequest(uint256,address)",
    "claimCancelDepositRequest(uint256,address,address)",
    "claimCancelRedeemRequest(uint256,address,address)",
    # Uniswap V4 hook & flash-accounting sinks (beforeSwap/afterSwap/liquidity hooks, take/settleFor/donate)
    "beforeSwap(address,(address,address,uint24,int24,address),(bool,int256,uint160),bytes)",
    "afterSwap(address,(address,address,uint24,int24,address),(bool,int256,uint160),int256,bytes)",
    "beforeAddLiquidity(address,(address,address,uint24,int24,address),(int24,int24,int256,bytes32),bytes)",
    "afterAddLiquidity(address,(address,address,uint24,int24,address),(int24,int24,int256,bytes32),int256,int256,bytes)",
    "beforeRemoveLiquidity(address,(address,address,uint24,int24,address),(int24,int24,int256,bytes32),bytes)",
    "afterRemoveLiquidity(address,(address,address,uint24,int24,address),(int24,int24,int256,bytes32),int256,int256,bytes)",
    "take(address,address,uint256)",
    "settleFor(address)",
    "donate((address,address,uint24,int24,address),uint256,uint256,bytes)",
    # ERC-7683 cross-chain intent solver sinks (open/openFor/fill)
    "open((uint32,bytes32,bytes))",
    "openFor((address,address,uint256,uint32,uint32,bytes32,bytes),bytes,bytes)",
    "fill(bytes32,bytes,bytes)",
):
    VALUE_SINK_SELECTORS.add(_selector(_intent_sig).lower())


@dataclass
class ValueSinkScanResult:
    has_s1_native_call: bool = False
    has_s2_token_call: bool = False
    has_s3_delegatecall: bool = False
    has_s4_selfdestruct: bool = False
    has_s5_state_mutation: bool = False
    all_branches_revert: bool = False
    sink_pcs: List[int] = field(default_factory=list)
    sink_kinds: List[str] = field(default_factory=list)
    early_exit_safe: bool = False
    early_exit_reason: str = ""


def quick_scan_value_sinks(code: bytes, cancun_active: bool = True) -> ValueSinkScanResult:
    """
    E2 조기 종료: 1-패스 선형 스캔으로 물리적 Value/State Sink 존재 여부 및 전수 REVERT 판정.
    - S1(CALL), S2(Token/Vault CALL), S3(DELEGATECALL/CALLCODE), S4(SELFDESTRUCT - EIP-6780 이후에도 ETH 강제 전송 수행),
      S5(SSTORE/TSTORE/CREATE/CREATE2 - 영속·트랜지언트 상태 변조 및 컨트랙트 배포 포함).
    """
    if not code:
        return ValueSinkScanResult(
            all_branches_revert=True,
            early_exit_safe=False,
            early_exit_reason="E2_EMPTY_BYTECODE",
        )
    if _eip7702_delegate(code):
        return ValueSinkScanResult(
            has_s5_state_mutation=True,
            all_branches_revert=False,
            sink_pcs=[0],
            sink_kinds=["S5_EIP7702_DELEGATION_REPLAY_RISK"],
            early_exit_safe=False,
            early_exit_reason="",
        )
    dis = _disassemble(code)
    if not dis:
        return ValueSinkScanResult(
            all_branches_revert=False,
            early_exit_safe=False,
            early_exit_reason="E2_EMPTY_DISASSEMBLY",
        )

    has_return_or_stop = any(nm in ("STOP", "RETURN", "SELFDESTRUCT") or nm.startswith("OP_") for _, nm, _ in dis)
    falloff_halts_normally = dis[-1][1] not in ("REVERT", "INVALID", "JUMP", "RETURN", "STOP", "SELFDESTRUCT")
    if not has_return_or_stop and not falloff_halts_normally:
        return ValueSinkScanResult(
            all_branches_revert=True,
            early_exit_safe=True,
            early_exit_reason="E2_ALL_BRANCHES_REVERT_OR_INVALID",
        )

    s1 = False
    s2 = False
    s3 = False
    s4 = False
    s5 = False
    sink_pcs: List[int] = []
    sink_kinds: Set[str] = set()

    pushed_sels: Set[str] = set()
    for _, nm, imm in dis:
        if nm == "PUSH4" and len(imm) == 4:
            pushed_sels.add("0x" + imm.hex())
        elif nm == "PUSH32" and len(imm) == 32 and imm[4:] == b"\x00" * 28:
            pushed_sels.add("0x" + imm[:4].hex())

    for idx, (pc, nm, _) in enumerate(dis):
        if nm == "CALL":
            window_back = dis[max(0, idx - 12) : idx]
            s1 = True
            sink_pcs.append(pc)
            sink_kinds.add("S1_NATIVE_OR_EXTERNAL_CALL")
            if pushed_sels & VALUE_SINK_SELECTORS or any(w[1] in ("MSTORE", "CALLDATACOPY", "MCOPY") for w in window_back):
                s2 = True
                sink_kinds.add("S2_TOKEN_OR_VAULT_CALL")
        elif nm in ("DELEGATECALL", "CALLCODE"):
            s3 = True
            sink_pcs.append(pc)
            sink_kinds.add("S3_DELEGATECALL")
        elif nm == "SELFDESTRUCT":
            s4 = True
            sink_pcs.append(pc)
            sink_kinds.add("S4_SELFDESTRUCT" if cancun_active else "S4_SELFDESTRUCT_PRE_EIP6780")
        elif nm in ("SSTORE", "TSTORE", "CREATE", "CREATE2"):
            s5 = True
            sink_pcs.append(pc)
            sink_kinds.add("S5_STATE_OR_CREATE_SINK")

    if not (s1 or s2 or s3 or s4 or s5):
        if any(nm.startswith("OP_") or nm in ("STATICCALL", "JUMP", "JUMPI") for _, nm, _ in dis):
            cfg_unmod = disassemble_and_build_cfg(code)
            root_reach: Set[int] = set()
            if 0 in cfg_unmod.blocks:
                q_r = [0]
                while q_r:
                    cur_pc = q_r.pop()
                    if cur_pc in root_reach or cur_pc not in cfg_unmod.blocks:
                        continue
                    root_reach.add(cur_pc)
                    for s_pc in cfg_unmod.blocks[cur_pc].succs:
                        if s_pc not in root_reach:
                            q_r.append(s_pc)
            has_reach_unmod = any(
                ep.reaches_unresolved_jump
                or any(
                    cfg_unmod.blocks[b_pc].has_unmodeled_op or cfg_unmod.blocks[b_pc].has_dynamic_staticcall
                    for b_pc in ep.reachable_blocks
                    if b_pc in cfg_unmod.blocks
                )
                for ep in cfg_unmod.entries.values()
            ) or any(
                cfg_unmod.blocks[b_pc].has_unresolved_jump
                or cfg_unmod.blocks[b_pc].has_unmodeled_op
                or cfg_unmod.blocks[b_pc].has_dynamic_staticcall
                for b_pc in root_reach
            )
            if has_reach_unmod:
                return ValueSinkScanResult(
                    has_s1_native_call=False,
                    has_s2_token_call=False,
                    has_s3_delegatecall=False,
                    has_s4_selfdestruct=False,
                    has_s5_state_mutation=True,
                    all_branches_revert=False,
                    sink_pcs=[
                        pc
                        for pc, nm, _ in dis
                        if nm.startswith("OP_") or nm in ("STATICCALL", "JUMP", "JUMPI")
                    ],
                    sink_kinds=["S5_REACHABLE_UNMODELED_OR_DYNAMIC_TARGET"],
                    early_exit_safe=False,
                    early_exit_reason="",
                )
        return ValueSinkScanResult(
            has_s1_native_call=False,
            has_s2_token_call=False,
            has_s3_delegatecall=False,
            has_s4_selfdestruct=False,
            has_s5_state_mutation=False,
            all_branches_revert=False,
            sink_pcs=[],
            sink_kinds=[],
            early_exit_safe=True,
            early_exit_reason="E2_ZERO_PHYSICAL_VALUE_SINKS",
        )

    return ValueSinkScanResult(
        has_s1_native_call=s1,
        has_s2_token_call=s2,
        has_s3_delegatecall=s3,
        has_s4_selfdestruct=s4,
        has_s5_state_mutation=s5,
        all_branches_revert=False,
        sink_pcs=sink_pcs,
        sink_kinds=sorted(sink_kinds),
        early_exit_safe=False,
        early_exit_reason="",
    )


@dataclass
class BasicBlock:
    start_pc: int
    end_pc: int
    insns: List[Tuple[int, str, bytes]] = field(default_factory=list)
    succs: List[int] = field(default_factory=list)
    preds: List[int] = field(default_factory=list)
    has_caller_eq: bool = False
    caller_gate_const: str = ""
    caller_gate_slot: Optional[int] = None
    caller_gate_shift: int = 0
    authorized_succ_pc: Optional[int] = None
    unauthorized_succ_pc: Optional[int] = None
    has_sstore: bool = False
    has_arbitrary_sstore: bool = False
    has_keccak_sstore: bool = False
    sstore_slots: List[int] = field(default_factory=list)
    sstore_map_bases: List[int] = field(default_factory=list)
    sstore_lock_vals: List[Tuple[int, int]] = field(default_factory=list)
    has_nonconst_sstore: bool = False
    has_sload: bool = False
    sload_slots: List[int] = field(default_factory=list)
    sload_map_bases: List[int] = field(default_factory=list)
    has_tstore: bool = False
    has_tload: bool = False
    has_value_sink: bool = False
    has_external_call: bool = False
    has_call_before_sstore: bool = False
    has_unresolved_jump: bool = False
    has_unmodeled_op: bool = False
    has_dynamic_staticcall: bool = False
    has_untrusted_delegatecall: bool = False
    pushed_jumpdests: List[int] = field(default_factory=list)
    has_revert: bool = False
    has_return: bool = False
    has_caller_map_eq: bool = False
    caller_map_auth_pc: Optional[int] = None
    has_time_cond: bool = False
    time_auth_pc: Optional[int] = None
    time_guarded_slots: Set[int] = field(default_factory=set)
    has_sig_precompile: bool = False
    has_ecrecover: bool = False
    has_sig_cond: bool = False
    has_sig_domain_binding: bool = False
    sig_auth_pc: Optional[int] = None
    has_calldata_auth_eq: bool = False
    has_eoa_only_gate: bool = False
    has_gas_stipend_oog_risk: bool = False
    has_callvalue_read: bool = False
    has_nonpayable_guard: bool = False
    has_delegatecall: bool = False
    has_arith_div: bool = False
    has_erc2771_suffix_read: bool = False
    has_arbitrary_call: bool = False
    has_dynamic_nonstorage_call: bool = False


@dataclass
class EntryPointCFG:
    selector: str
    entry_pc: int
    reachable_blocks: Set[int] = field(default_factory=set)
    reaches_value_sink: bool = False
    reaches_sstore: bool = False
