    read_map_slots: Set[int] = field(default_factory=set)
    caller_dominated: bool = False
    has_caller_map_guard: bool = False
    dominator_guard_addr: str = ""
    dominator_guard_slot: Optional[int] = None
    dominator_guard_shift: int = 0
    has_time_gate: bool = False
    has_time_bypass: bool = False
