def slice_four_channel_causal_chains(
    target_address: str,
    cfg: CFGModel,
    open_selectors: List[str],
    max_slices: int = 96,
    abi_list: Optional[Sequence[Any]] = None,
    peer_dep_targets: Optional[Sequence[Any]] = None,
    vault_token_amounts: Optional[Sequence[int]] = None,
) -> List[CausalSlice]:
    """
    4대 물리적 상태 채널(CH_STORAGE, CH_TRANSIENT, CH_BALANCE, CH_MIDFRAME) 인과 슬라이서:
    - 1-leg 전수 + 2-leg 대각쌍 + 자금우선 3·4-leg + 오라클/잔액 dep->consumer 순서쌍 + depth-2 콜백 프로브
    """
    t_norm = _norm_addr(target_address)
    witnesses = solve_discontinuity_boundaries(cfg.disassembly, vault_token_amounts=vault_token_amounts)
    abi_map = _extract_abi_inputs_map(abi_list or [])
    abi_name_map = _extract_abi_param_names_map(abi_list or [])
    abi_readonly_sels: Set[str] = set()
    for _ai in (abi_list or ()):
        if isinstance(_ai, dict) and _ai.get("type") == "function" and _ai.get("stateMutability") in ("view", "pure"):
            _an = str(_ai.get("name") or "")
            if _an:
                _ains = [_format_abi_param_type(x) for x in (_ai.get("inputs") or ()) if isinstance(x, dict)]
                abi_readonly_sels.add(_selector(f"{_an}({','.join(_ains)})").lower())
    cfg_inf_map = {str(k).lower(): list(v) for k, v in (getattr(cfg, "inferred_abi_by_sel", None) or {}).items() if v}
    priority_slices: List[CausalSlice] = []
    slices: List[CausalSlice] = []
    sel_abi_cache: Dict[str, Tuple[bool, List[str], bool]] = {}

    open_eps = [cfg.entries[s] for s in open_selectors if s in cfg.entries]
    if not open_eps and open_selectors:
        open_set = set(open_selectors)
        open_eps = [ep for k, ep in cfg.entries.items() if k.split("@", 1)[0] in open_set]
    if not open_eps and cfg.entries:
        open_eps = list(cfg.entries.values())[:8]

    def _is_pure_readonly_ep(ep_x: Any) -> bool:
        sl_x = str(ep_x.selector or "").lower()
        return (
            (sl_x in _PURE_READONLY_ERC_SELECTORS or sl_x in abi_readonly_sels)
            and not ep_x.reaches_value_sink
            and not ep_x.reaches_sstore
            and not ep_x.reaches_unresolved_jump
            and not ep_x.reaches_dynamic_staticcall
        )

    writers = [ep for ep in open_eps if (ep.reaches_sstore or ep.reaches_unresolved_jump) and not _is_pure_readonly_ep(ep)]
    sinks = [
        ep
        for ep in open_eps
        if (ep.reaches_value_sink or ep.reaches_sstore or ep.reaches_unresolved_jump or ep.reaches_dynamic_staticcall)
        and not _is_pure_readonly_ep(ep)
    ]

    def _sel_abi_flags(sel_s: str, extra_complex: bool = False) -> Tuple[bool, List[str], bool]:
        base_f = sel_abi_cache.get(sel_s)
        if base_f is None:
            sel_low = sel_s.lower()
            verified = bool(abi_map) and (sel_low in abi_map) and (sel_low != "fallback")
            in_types = abi_map.get(sel_low, [])
            base_complex = _abi_requires_agent_reasoning(in_types) or (not verified)
            base_f = (verified, in_types, base_complex)
            sel_abi_cache[sel_s] = base_f
        return base_f[0], base_f[1], (base_f[2] or extra_complex)

    def _sel_extra_meta(sels: Sequence[str]) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
        names_out: Dict[str, List[str]] = {}
        inf_out: Dict[str, List[str]] = {}
        for s_m in sels:
            sl_m = s_m.lower()
            if sl_m != "fallback":
                if sl_m in abi_name_map:
                    names_out[s_m] = list(abi_name_map[sl_m])
                elif sl_m in cfg_inf_map:
                    inf_out[s_m] = list(cfg_inf_map[sl_m])
        return names_out, inf_out

    for sk in sinks:
        sel_low_sk = sk.selector.lower()
        dyn_sc_only = sk.reaches_dynamic_staticcall and not (sk.reaches_value_sink or sk.reaches_sstore)
        v4_hook_cb = (sel_low_sk in _UNIV4_HOOK_CALLBACK_SELECTORS) and (not sk.caller_dominated)
        flash_swap_cb = (
            (sel_low_sk in _FLASH_OR_SWAP_CALLBACK_SELECTORS)
            and (not sk.caller_dominated)
            and (not sk.has_caller_map_guard)
        )
        erc7540_async = (sel_low_sk in _ERC7540_ASYNC_VAULT_SELECTORS) and (not sk.caller_dominated)
        erc7579_mod_exec = (sel_low_sk in _ERC7579_7821_MODULAR_EXEC_SELECTORS) and (not sk.caller_dominated)
        risk_specs = (
            (
                bool(sk.has_unguarded_low_slot_init),
                "eip7702_init_ordering_or_slot_collision",
                "Open entry with unguarded low-slot init (EIP-7702 init ordering / storage slot collision risk)",
                "Unguarded low-slot initializer (EIP-7702 init ordering / slot collision) requires targeted verification",
            ),
            (
                v4_hook_cb,
                "unguarded_v4_hook_callback_risk",
                "Unguarded Uniswap v4 hook / singleton callback reachable without PoolManager caller dominance",
                "Unguarded Uniswap v4 hook / unlockCallback requires direct callback verification",
            ),
            (
                flash_swap_cb,
                "unguarded_flash_or_swap_callback_risk",
                "Unguarded DEX swap/flash-loan callback reachable without pool/lender caller dominance",
                "Unguarded flash/swap callback (V2/V3/Aave/Balancer/Morpho/ERC-3156) requires direct callback verification",
            ),
            (
                erc7579_mod_exec,
                "erc7579_7821_modular_exec_risk",
                "Unguarded ERC-7579/7821 modular smart-account batch/exec entrypoint reachable without caller dominance",
                "Unguarded ERC-7579/7821 modular account execution requires module/batch context synthesis",
            ),
            (
                erc7540_async,
                "erc7540_async_vault_risk",
                "Open ERC-7540 async vault request/cancel/claim entrypoint reachable without caller dominance",
                "ERC-7540 async vault request/claim state-transition requires epoch/cancellation invariant synthesis",
            ),
            (
                bool(sk.has_erc2771_multicall_spoof),
                "erc2771_multicall_suffix_risk",
                "Open entry with ERC-2771 suffix read combined with DELEGATECALL multicall (caller suffix forwarding risk)",
                "ERC-2771 + multicall self-delegatecall context handling requires 20-byte suffix verification",
            ),
            (
                bool(sk.has_arbitrary_call),
                "arbitrary_call_target_risk",
                "Open entry with calldata-controlled arbitrary external CALL target (approval exposure / router call risk)",
                "Calldata-tainted arbitrary external CALL target requires transferFrom / call-forwarding synthesis",
            ),
            (
                bool(sk.has_multicall_msg_value_reuse),
                "multicall_msg_value_reuse_risk",
                "Open entry with CALLVALUE reuse across loop/multi-delegatecall (multicall msg.value reuse risk)",
                "Multicall CALLVALUE (msg.value) reuse across batched calls requires targeted synthesis",
            ),
            (
                bool(sk.has_loop_rounding_drift),
                "loop_rounding_drift_risk",
                "Open entry with arithmetic DIV/SDIV inside state-mutating loop (repeated rounding-drift risk)",
                "Repeated arithmetic rounding-drift loop requires precision-boundary synthesis",
            ),
            (
                bool(sk.has_gas_stipend_oog_risk),
                "eip8037_8038_gas_stipend_oog_risk",
                "Open entry with fixed gas stipend / gasleft() / MODEXP boundary (EIP-7823/7883/8037/8038 OOG risk)",
                "Fixed gas stipend / gasleft() / MODEXP OOG path (EIP-7823/7883/8037/8038) requires gas-boundary synthesis",
            ),
            (
                bool(sk.has_eoa_only_gate),
                "eoa_only_gate_eip7702_delegatable",
                "Open entry with EIP-7702 delegatable onlyEOA gate (CALLER==ORIGIN / EXTCODESIZE)",
                "EIP-7702 delegatable onlyEOA gate (CALLER==ORIGIN / EXTCODESIZE) requires delegated/EOA verification",
            ),
            (
                bool(sk.has_unchecked_sig_verify),
                "unchecked_sig_verify_risk",
                "Open entry invoking ecrecover/P256VERIFY without dominating signer verification (unchecked signature / replay risk)",
                "Unchecked ecrecover/P256VERIFY return validation or missing replay protection requires invalid/replayed sig verification",
            ),
            (
                bool(sk.has_weak_sig_domain_risk),
                "weak_sig_domain_or_replay_risk",
                "Signature-guarded entry lacks domain binding (CHAINID/ADDRESS/EIP-712) or nonce SSTORE (cross-chain/contract replay risk)",
                "Signature guard without EIP-712/CHAINID/ADDRESS domain binding or replay SSTORE requires replay synthesis",
            ),
        )
        sk_diag: Dict[str, Any] = {diag_k: True for flag_v, diag_k, _, _ in risk_specs if flag_v}
        has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector, dyn_sc_only or bool(sk_diag))
        sk_names, sk_inf = _sel_extra_meta([sk.selector])
        sk_rationale = "Direct open entry reaching physical value, state, or dynamic staticcall sink"
        sk_undec = (
            "Dynamic STATICCALL view/verifier callback synthesis required"
            if dyn_sc_only
            else (
                "Unverified selector or fallback calldata synthesis required"
                if not has_verified_sel
                else ("Complex struct/bytes calldata synthesis required" if complex_abi else "")
            )
        )
        for _flag_s, _dk_s, _rat_s, _und_s in risk_specs:
            if _flag_s:
                sk_rationale = _rat_s
                sk_undec = _und_s
                break
        (priority_slices if sk_diag else slices).append(
            CausalSlice(
                slice_id=f"ch_storage_1leg_{t_norm[-6:]}_{sk.selector}",
                target_address=t_norm,
                channel="CH_MIDFRAME" if (dyn_sc_only or v4_hook_cb or flash_swap_cb) else "CH_STORAGE",
                legs=[sk.selector],
                shared_slots=sorted(sk.read_slots & sk.written_slots)[:8],
                shared_map_slots=sorted(sk.read_map_slots & sk.written_map_slots)[:8],
                witness_candidates=witnesses[:14],
                repeat_counts=[1, 2, 16] if sk.has_loop_rounding_drift else [1, 2],
                rationale=sk_rationale,
                leg_targets=[t_norm],
                abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                abi_param_names_by_sel=sk_names,
                inferred_abi_by_sel=sk_inf,
                prescreen_diagnostics=sk_diag,
                needs_agent_synthesis=complex_abi,
                undecided_reason=sk_undec,
            )
        )
        if sk.reaches_sstore and sk.reaches_value_sink:
            slices.append(
                CausalSlice(
                    slice_id=f"ch_storage_self3leg_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_STORAGE",
                    legs=[sk.selector, sk.selector, sk.selector],
                    shared_slots=sorted(sk.read_slots | sk.written_slots)[:8],
                    shared_map_slots=sorted(sk.read_map_slots | sk.written_map_slots)[:8],
                    witness_candidates=witnesses[:10],
                    repeat_counts=[1, 2],
                    rationale="3-leg repeated state accumulation and settlement on coupled SSTORE+Sink entry",
                    leg_targets=[t_norm, t_norm, t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    abi_param_names_by_sel=sk_names,
                    inferred_abi_by_sel=sk_inf,
                    needs_agent_synthesis=complex_abi,
                    undecided_reason="Unverified selector or complex ABI in 3-leg accumulation" if complex_abi else "",
                )
            )

    has_transient = any(bb.has_tstore or bb.has_tload for bb in cfg.blocks.values())
    if has_transient and sinks:
        tstore_eps = [
            ep for ep in open_eps
            if any(b_pc in cfg.blocks and cfg.blocks[b_pc].has_tstore for b_pc in ep.reachable_blocks)
        ]
        tload_eps = [
            ep for ep in sinks
            if any(b_pc in cfg.blocks and cfg.blocks[b_pc].has_tload for b_pc in ep.reachable_blocks)
        ]
        t_cross_added = 0
        for tw in tstore_eps[:4]:
            for tr in tload_eps[:4]:
                if tw.selector == tr.selector or t_cross_added >= 4:
                    continue
                t_abi = {
                    s: abi_map[s.lower()]
                    for s in (tw.selector, tr.selector)
                    if s.lower() in abi_map and s.lower() != "fallback"
                }
                t_names, t_inf = _sel_extra_meta((tw.selector, tr.selector))
                t_complex = (len(t_abi) < 2) or any(_abi_requires_agent_reasoning(v) for v in t_abi.values())
                priority_slices.append(
                    CausalSlice(
                        slice_id=f"ch_transient_x_{t_norm[-6:]}_{tw.selector}_{tr.selector}",
                        target_address=t_norm,
                        channel="CH_TRANSIENT",
                        legs=[tw.selector, tr.selector],
                        shared_slots=sorted(tw.written_slots & tr.read_slots)[:8],
                        witness_candidates=witnesses[:10],
                        repeat_counts=[1, 2],
                        rationale="Cross-entry EIP-1153 transient storage (TSTORE -> TLOAD) same-tx residue coupling",
                        leg_targets=[t_norm, t_norm],
                        abi_inputs_by_sel=t_abi,
                        abi_param_names_by_sel=t_names,
                        inferred_abi_by_sel=t_inf,
                        needs_agent_synthesis=t_complex,
                        undecided_reason="Cross-entry EIP-1153 transient residue unverified or complex ABI" if t_complex else "",
                    )
                )
                t_cross_added += 1
        for sk in sinks[:4]:
            has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector)
            sk_names_t, sk_inf_t = _sel_extra_meta([sk.selector])
            priority_slices.append(
                CausalSlice(
                    slice_id=f"ch_transient_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_TRANSIENT",
                    legs=[sk.selector, sk.selector],
                    shared_slots=[],
                    witness_candidates=witnesses[:10],
                    repeat_counts=[1, 2],
                    rationale="Same-transaction transient storage (TSTORE/TLOAD) multi-call coupling",
                    leg_targets=[t_norm, t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    abi_param_names_by_sel=sk_names_t,
                    inferred_abi_by_sel=sk_inf_t,
                    needs_agent_synthesis=complex_abi,
                    undecided_reason="EIP-1153 transient storage unverified or complex ABI" if complex_abi else "",
                )
            )

    has_div = any(nm in ("DIV", "SDIV") for _, nm, _ in cfg.disassembly)
    has_ext_read = any(nm in ("STATICCALL", "SELFBALANCE", "BALANCE") for _, nm, _ in cfg.disassembly)
    has_spot_amm_read = has_ext_read and any(
        (nm == "PUSH4" and imm in (b"\x09\x02\xf1\xac", b"\x38\x50\xc7\xbd"))
        or (
            nm == "PUSH32"
            and len(imm) == 32
            and imm[:4] in (b"\x09\x02\xf1\xac", b"\x38\x50\xc7\xbd")
            and imm[4:] == b"\x00" * 28
        )
        for _, nm, imm in cfg.disassembly
    )
    if (has_div or has_spot_amm_read) and has_ext_read and sinks:
        for sk in sinks[:4]:
            spot_coupled_sk = bool(has_spot_amm_read and (sk.reaches_sstore or sk.reaches_value_sink))
            has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector, extra_complex=spot_coupled_sk)
            sk_names_b, sk_inf_b = _sel_extra_meta([sk.selector])
            bal_diag = {"spot_amm_oracle_coupling_risk": True} if spot_coupled_sk else {}
            (priority_slices if spot_coupled_sk else slices).append(
                CausalSlice(
                    slice_id=f"ch_balance_skew_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_BALANCE",
                    legs=[sk.selector],
                    shared_slots=sorted(sk.read_slots)[:4],
                    shared_map_slots=sorted(sk.read_map_slots)[:4],
                    witness_candidates=witnesses[:14],
                    repeat_counts=[1, 2, 16],
                    rationale=(
                        "Spot AMM reserve/slot0 read coupled with state mutation or value sink (fail-open price-coupling surface)"
                        if spot_coupled_sk
                        else "External balance/reserve read coupled with integer division rounding boundary"
                    ),
                    leg_targets=[t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    abi_param_names_by_sel=sk_names_b,
                    inferred_abi_by_sel=sk_inf_b,
                    prescreen_diagnostics=bal_diag,
                    needs_agent_synthesis=complex_abi,
                    undecided_reason=(
                        "Spot AMM reserve/slot0 oracle coupling requires fail-open invariant audit"
                        if spot_coupled_sk
                        else ("Spot reserve/exchange-rate dependency with unverified or complex ABI" if complex_abi else "")
                    ),
                )
            )
            for dep_item in (peer_dep_targets or [])[:4]:
                if isinstance(dep_item, (tuple, list)) and len(dep_item) >= 2:
                    dep_addr, dep_sel = str(dep_item[0]), str(dep_item[1])
                    dep_abi_in = list(dep_item[2]) if len(dep_item) >= 3 and isinstance(dep_item[2], (list, tuple)) else []
                else:
                    dep_addr, dep_sel = str(dep_item), sk.selector
                    dep_abi_in = []
                dn = _norm_addr(dep_addr)
                if dn and dn != t_norm:
                    dep_abi_map: Dict[str, List[str]] = {}
                    if has_verified_sel:
                        dep_abi_map[sk.selector] = in_t
                    if dep_abi_in:
                        dep_abi_map[dep_sel] = dep_abi_in
                    slices.append(
                        CausalSlice(
                            slice_id=f"ch_balance_dep_{dn[-4:]}_{dep_sel}_{t_norm[-4:]}_{sk.selector}",
                            target_address=t_norm,
                            channel="CH_BALANCE",
                            legs=[dep_sel, sk.selector],
                            shared_slots=sorted(sk.read_slots)[:4],
                            shared_map_slots=sorted(sk.read_map_slots)[:4],
                            witness_candidates=witnesses[:12],
                            repeat_counts=[1, 2],
                            rationale="Cross-contract oracle/balance dependency -> consumer ordered pair",
                            leg_targets=[dn, t_norm],
                            abi_inputs_by_sel=dep_abi_map,
                            abi_param_names_by_sel=sk_names_b,
                            inferred_abi_by_sel=sk_inf_b,
                            needs_agent_synthesis=True,
                            undecided_reason="Cross-contract dep->consumer invariant coupling",
                        )
                    )

    # 3-B. 볼트(ERC-4626/7540) · 렌딩(Compound/VToken) · 스테이킹 보상(stake->claim->withdraw) 보존 불변식 멀티레그 슬라이스
    for _cp_tag, _cp_dep_sels, _cp_mid_sels, _cp_red_sels, _cp_nlegs, _cp_ws, _cp_rat, _cp_undec in _CONSERVATION_PAIR_SPECS:
        _open_dep_eps = [ep for ep in open_eps if ep.selector.lower() in _cp_dep_sels]
        _open_red_eps = [ep for ep in open_eps if ep.selector.lower() in _cp_red_sels]
        if not (_open_dep_eps and _open_red_eps):
            continue
        _open_mid_eps = [ep for ep in open_eps if ep.selector.lower() in _cp_mid_sels] if _cp_mid_sels else []
        if _cp_mid_sels and not _open_mid_eps:
            continue
        _v_dep = _open_dep_eps[0]
        _v_mid = _open_mid_eps[0] if _open_mid_eps else None
        _v_red = _open_red_eps[0]
        _v_sel_tuple = (_v_dep.selector, _v_mid.selector, _v_red.selector) if _v_mid is not None else (_v_dep.selector, _v_red.selector)
        _v_abi = {
            s: abi_map[s.lower()]
            for s in _v_sel_tuple
            if s.lower() in abi_map
        }
        _v_names, _v_inf = _sel_extra_meta(_v_sel_tuple)
        _vault_donation_risk = bool(_cp_tag == "vault4626" and has_div and has_ext_read)
        _v_complex = (
            _vault_donation_risk
            or (len(_v_abi) < len(set(_v_sel_tuple)))
            or any(_abi_requires_agent_reasoning(v) for v in _v_abi.values())
        )
        if _v_mid is not None:
            _cp_legs = [_v_dep.selector, _v_mid.selector, _v_red.selector]
        else:
            _cp_legs = [_v_dep.selector, _v_dep.selector, _v_red.selector] if _cp_nlegs == 3 else [_v_dep.selector, _v_red.selector]
        _cp_w_slots = _v_dep.written_slots | (_v_mid.written_slots if _v_mid is not None else set()) | _v_red.read_slots
        _cp_m_slots = _v_dep.written_map_slots | (_v_mid.written_map_slots if _v_mid is not None else set()) | _v_red.read_map_slots
        priority_slices.append(
            CausalSlice(
                slice_id=f"ch_balance_{_cp_tag}_{t_norm[-6:]}_{_v_dep.selector}_{_v_red.selector}",
                target_address=t_norm,
                channel="CH_BALANCE",
                legs=_cp_legs,
                shared_slots=sorted(_cp_w_slots)[:8],
                shared_map_slots=sorted(_cp_m_slots)[:8],
                witness_candidates=list(_cp_ws),
                repeat_counts=[1, 2, 16] if _cp_tag in ("vault4626", "staking_reward") else [1, 2],
                rationale=_cp_rat,
                leg_targets=[t_norm] * len(_cp_legs),
                abi_inputs_by_sel=_v_abi,
                abi_param_names_by_sel=_v_names,
                inferred_abi_by_sel=_v_inf,
                prescreen_diagnostics={"erc4626_share_inflation_donation_risk": True} if _vault_donation_risk else {},
                needs_agent_synthesis=_v_complex,
                undecided_reason=_cp_undec if _v_complex else "",
            )
        )

    # 4. CH_MIDFRAME: 상태 변경 외부 CALL(STATICCALL 제외)과 SSTORE/TSTORE가 결합된 진입점의 깊이-2 리엔트런시/읽기전용 리엔트런시/콜백 프로브
    midframe_sels: List[str] = []
    cbs_post_writes: Dict[str, Tuple[Set[int], Set[int], bool, bool, bool, bool, bool]] = {}
    for sk in sinks:
        has_ext_call_in_ep = False
        has_state_write_in_ep = sk.reaches_sstore
        call_pcs_ep: List[int] = []
        intra_cbs_pcs: List[int] = []
        for b_pc in sk.reachable_blocks:
            bb = cfg.blocks.get(b_pc)
            if not bb:
                continue
            if bb.has_external_call:
                has_ext_call_in_ep = True
                call_pcs_ep.append(b_pc)
            if bb.has_sstore or bb.has_tstore:
                has_state_write_in_ep = True
            if bb.has_call_before_sstore:
                intra_cbs_pcs.append(b_pc)
        post_blocks: Set[int] = set(intra_cbs_pcs)
        pre_call_reach: Set[int] = set()
        if call_pcs_ep:
            call_set_ep: Set[int] = set(call_pcs_ep)
            pre_call_excl: Set[int] = call_set_ep - post_blocks
            if sk.entry_pc in sk.reachable_blocks:
                q_pre: deque[int] = deque([sk.entry_pc])
                pre_call_reach.add(sk.entry_pc)
                while q_pre:
                    p_cur = q_pre.popleft()
                    if p_cur in call_set_ep:
                        continue
                    pb_c = cfg.blocks.get(p_cur)
                    if not pb_c:
                        continue
                    for p_sc in pb_c.succs:
                        if p_sc in sk.reachable_blocks and p_sc not in pre_call_reach:
                            pre_call_reach.add(p_sc)
                            q_pre.append(p_sc)
            q_post: deque[int] = deque()
            for cp_pc in call_pcs_ep:
                cb_blk = cfg.blocks.get(cp_pc)
                if cb_blk:
                    for sc_pc in cb_blk.succs:
                        if sc_pc in sk.reachable_blocks and sc_pc not in post_blocks and sc_pc not in pre_call_excl:
                            post_blocks.add(sc_pc)
                            q_post.append(sc_pc)
            while q_post:
                cur_p = q_post.popleft()
                cur_b = cfg.blocks.get(cur_p)
                if not cur_b:
                    continue
                is_ind_ret = len(cur_b.succs) > 1 and bool(cur_b.insns) and cur_b.insns[-1][1] == "JUMP"
                for sc_pc in cur_b.succs:
                    if sc_pc in sk.reachable_blocks and sc_pc not in post_blocks and sc_pc not in pre_call_excl:
                        if is_ind_ret and sc_pc in pre_call_reach:
                            continue
                        post_blocks.add(sc_pc)
                        q_post.append(sc_pc)
        post_slots: Set[int] = set()
        post_maps: Set[int] = set()
        post_rmw_slots: Set[int] = set()
        post_rmw_maps: Set[int] = set()
        post_lock_tags: Dict[int, Set[int]] = {}
        post_dyn = post_tstore = has_post_sstore = post_nonconst = False
        for pb_pc in post_blocks:
            pb_blk = cfg.blocks.get(pb_pc)
            if not pb_blk:
                continue
            if pb_blk.sload_slots:
                post_rmw_slots.update(pb_blk.sload_slots)
            if pb_blk.sload_map_bases:
                post_rmw_maps.update(pb_blk.sload_map_bases)
            if not (pb_blk.has_sstore or pb_blk.has_tstore):
                continue
            if pb_blk.has_sstore:
                has_post_sstore = True
            if pb_blk.has_nonconst_sstore:
                post_nonconst = True
            for l_sl, l_tag in pb_blk.sstore_lock_vals:
                post_lock_tags.setdefault(l_sl, set()).add(l_tag)
            post_slots.update(pb_blk.sstore_slots)
            post_maps.update(pb_blk.sstore_map_bases)
            if pb_blk.has_arbitrary_sstore or (pb_blk.has_keccak_sstore and not pb_blk.sstore_map_bases):
                post_dyn = True
            if pb_blk.has_tstore:
                post_tstore = True
        if post_dyn:
            post_slots.update(post_rmw_slots)
            post_maps.update(post_rmw_maps)
        has_pre_tguard = (
            bool(pre_call_reach)
            and any((b_pt := cfg.blocks.get(p_pt)) is not None and b_pt.has_tload for p_pt in pre_call_reach)
            and any((b_pt := cfg.blocks.get(p_pt)) is not None and b_pt.has_tstore for p_pt in pre_call_reach)
        )
        has_pre_pmutex = False
        if (
            has_post_sstore
            and not post_tstore
            and not intra_cbs_pcs
            and not post_maps
            and not post_dyn
            and not post_nonconst
            and len(post_slots) == 1
            and pre_call_reach
        ):
            m_sl = next(iter(post_slots))
            p_utags = post_lock_tags.get(m_sl, set())
            if p_utags:
                pre_sl_seen = False
                pre_ltags: Set[int] = set()
                for p_pm in pre_call_reach:
                    b_pm = cfg.blocks.get(p_pm)
                    if not b_pm:
                        continue
                    if m_sl in b_pm.sload_slots:
                        pre_sl_seen = True
                    for l_sl, l_tag in b_pm.sstore_lock_vals:
                        if l_sl == m_sl:
                            pre_ltags.add(l_tag)
                if pre_sl_seen and pre_ltags and all(
                    (u_t == 0 and 1 in pre_ltags)
                    or (u_t == 1 and 2 in pre_ltags)
                    or (u_t in (4, 0, 1) and 3 in pre_ltags)
                    or (u_t >= 2000 and (u_t - 1000) in pre_ltags)
                    for u_t in p_utags
                ):
                    has_pre_pmutex = True
        if has_post_sstore or post_tstore:
            midframe_sels.append(sk.selector)
            prev_w = cbs_post_writes.get(sk.selector)
            if prev_w is None:
                cbs_post_writes[sk.selector] = (post_slots, post_maps, post_dyn, post_tstore, has_post_sstore, has_pre_tguard, has_pre_pmutex)
            else:
                cbs_post_writes[sk.selector] = (
                    prev_w[0] | post_slots,
                    prev_w[1] | post_maps,
                    prev_w[2] or post_dyn,
                    prev_w[3] or post_tstore,
                    prev_w[4] or has_post_sstore,
                    prev_w[5] and has_pre_tguard,
                    prev_w[6] and has_pre_pmutex,
                )
        elif has_ext_call_in_ep and (has_state_write_in_ep or len(writers) > 0):
            midframe_sels.append(sk.selector)
    ro_view_eps: List[Tuple[str, EntryPointCFG, bool]] = [
        (
            sel_v,
            ep_v,
            any(
                (blk_v := cfg.blocks.get(bp_v)) is not None and blk_v.has_tload
                for bp_v in ep_v.reachable_blocks
            ),
        )
        for sel_v, ep_v in sorted(cfg.entries.items())
        if sel_v.lower() in _READONLY_PRICE_VIEW_SELECTORS
    ]
    midframe_ranked: List[Tuple[bool, bool, str, List[str], Set[int]]] = []
    for msel in sorted(set(midframe_sels)):
        post_info = cbs_post_writes.get(msel)
        matched_ro_views: List[str] = []
        matched_ro_slots: Set[int] = set()
        is_cbs = False
        if post_info is not None:
            p_slots, p_maps, p_dyn, p_tstore, p_has_sstore, p_pre_tguard, p_pre_pmutex = post_info
            for sel_v, ep_v, v_tload in ro_view_eps:
                sh_sl = p_slots & ep_v.read_slots
                sh_mp = p_maps & ep_v.read_map_slots
                v_unres = not ep_v.read_slots and not ep_v.read_map_slots
                if sh_sl or sh_mp or (p_dyn and v_unres) or (p_tstore and v_tload):
                    matched_ro_views.append(sel_v)
                    matched_ro_slots.update(sh_sl)
            is_benign_tunlock = (not p_has_sstore) and p_tstore and p_pre_tguard and (not matched_ro_views)
            is_benign_punlock = p_pre_pmutex and (not matched_ro_views)
            is_cbs = not (is_benign_tunlock or is_benign_punlock)
        midframe_ranked.append((not bool(matched_ro_views), not is_cbs, msel, matched_ro_views, matched_ro_slots))
    midframe_ranked.sort(key=lambda r: (r[0], r[1], r[2]))
    midframe_crit_slices: List[CausalSlice] = []
    mf_cross_cnt = 0
    for not_ro, not_cbs, msel, matched_ro_views, matched_ro_slots in midframe_ranked[:6]:
        is_ro_reent = not not_ro
        is_cbs = not not_cbs
        has_verified_msel, in_t, complex_abi = _sel_abi_flags(msel, is_cbs)
        ms_names, ms_inf = _sel_extra_meta([msel])
        ms_diag: Dict[str, Any] = {}
        if is_cbs:
            ms_diag["call_before_sstore_reentrancy_risk"] = True
        if is_ro_reent:
            ms_diag["read_only_reentrancy_risk"] = True
            ms_diag["readonly_view_selectors"] = matched_ro_views[:6]
            if matched_ro_slots:
                ms_diag["readonly_stale_slots"] = sorted(matched_ro_slots)[:8]
        (midframe_crit_slices if (is_cbs or is_ro_reent) else slices).append(
            CausalSlice(
                slice_id=f"ch_midframe_{t_norm[-6:]}_{msel}",
                target_address=t_norm,
                channel="CH_MIDFRAME",
                legs=[msel],
                shared_slots=sorted(matched_ro_slots)[:8],
                witness_candidates=witnesses[:10],
                repeat_counts=[1, 2],
                rationale=(
                    "External CALL before SSTORE/TSTORE with exposed accounting/price views reading stale post-CALL slots (read-only & cross-contract reentrancy risk)"
                    if is_ro_reent
                    else (
                        "External CALL before SSTORE/TSTORE (CEI violation / mid-frame reentrancy callback window)"
                        if is_cbs
                        else "State-modifying external CALL coupled with state mutation (depth-2 callback window)"
                    )
                ),
                leg_targets=[t_norm],
                abi_inputs_by_sel={msel: in_t} if has_verified_msel else {},
                abi_param_names_by_sel=ms_names,
                inferred_abi_by_sel=ms_inf,
                prescreen_diagnostics=ms_diag,
                needs_agent_synthesis=complex_abi,
                undecided_reason=(
                    "Mid-frame CALL-before-SSTORE read-only/callback reentrancy requires caller callback verification"
                    if is_cbs
                    else ("Mid-frame callback with unverified or complex ABI" if complex_abi else "")
                ),
            )
        )
        if (is_cbs or is_ro_reent) and mf_cross_cnt < 3:
            p_info_x = cbs_post_writes.get(msel)
            p_sl_x = p_info_x[0] if p_info_x is not None else set()
            p_mp_x = p_info_x[1] if p_info_x is not None else set()
            alt_cands = [
                a_ep
                for a_ep in sinks
                if a_ep.selector != msel
                and (bool(p_sl_x & a_ep.read_slots) or bool(p_mp_x & a_ep.read_map_slots) or a_ep.reaches_value_sink)
            ]
            alt_cands.sort(
                key=lambda a_ep: (
                    not bool((p_sl_x & a_ep.read_slots) or (p_mp_x & a_ep.read_map_slots)),
                    not a_ep.reaches_value_sink,
                    a_ep.selector,
                )
            )
            if alt_cands:
                alt_ep = alt_cands[0]
                x_abi = {
                    s_x: abi_map[s_x.lower()]
                    for s_x in (msel, alt_ep.selector)
                    if s_x.lower() in abi_map and s_x.lower() != "fallback"
                }
                x_names, x_inf = _sel_extra_meta((msel, alt_ep.selector))
                x_complex = (len(x_abi) < 2) or any(_abi_requires_agent_reasoning(v) for v in x_abi.values())
                midframe_crit_slices.append(
                    CausalSlice(
                        slice_id=f"ch_midframe_x_{t_norm[-6:]}_{msel}_{alt_ep.selector}",
                        target_address=t_norm,
                        channel="CH_MIDFRAME",
                        legs=[msel, alt_ep.selector],
                        shared_slots=sorted((p_sl_x & alt_ep.read_slots) | matched_ro_slots)[:8],
                        shared_map_slots=sorted(p_mp_x & alt_ep.read_map_slots)[:8],
                        witness_candidates=witnesses[:10],
                        repeat_counts=[1, 2],
                        rationale="Cross-function mid-frame callback reentrancy (CALL-before-SSTORE into alternate sink)",
                        leg_targets=[t_norm, t_norm],
                        abi_inputs_by_sel=x_abi,
                        abi_param_names_by_sel=x_names,
                        inferred_abi_by_sel=x_inf,
                        prescreen_diagnostics={**ms_diag, "cross_function_reentrancy_probe": True},
                        needs_agent_synthesis=x_complex,
                        undecided_reason="Cross-function mid-frame reentrancy callback synthesis" if x_complex else "",
                    )
                )
                mf_cross_cnt += 1
        if (is_cbs or is_ro_reent) and peer_dep_targets:
            peer_mf_added = 0
            for p_item in peer_dep_targets[:4]:
                if peer_mf_added >= 2:
                    break
                if isinstance(p_item, (tuple, list)) and len(p_item) >= 2:
                    p_addr, p_sel = str(p_item[0]), str(p_item[1])
                    p_abi_in = list(p_item[2]) if len(p_item) >= 3 and isinstance(p_item[2], (list, tuple)) else []
                else:
                    p_addr, p_sel, p_abi_in = str(p_item), msel, []
                pn = _norm_addr(p_addr)
                if not pn or pn == t_norm or not p_sel:
                    continue
                p_abi_map: Dict[str, List[str]] = {}
                if has_verified_msel:
                    p_abi_map[msel] = in_t
                if p_abi_in:
                    p_abi_map[p_sel] = p_abi_in
                p_complex = (len(p_abi_map) < 2) or any(_abi_requires_agent_reasoning(v) for v in p_abi_map.values())
                midframe_crit_slices.append(
                    CausalSlice(
                        slice_id=f"ch_midframe_peer_{t_norm[-6:]}_{msel}_{pn[-4:]}_{p_sel}",
                        target_address=t_norm,
                        channel="CH_MIDFRAME",
                        legs=[msel, p_sel],
                        shared_slots=sorted(matched_ro_slots)[:8],
                        witness_candidates=witnesses[:10],
                        repeat_counts=[1, 2],
                        rationale="Cross-contract read-only reentrancy (pool CALL-before-SSTORE callback into peer consumer)",
                        leg_targets=[t_norm, pn],
                        abi_inputs_by_sel=p_abi_map,
                        abi_param_names_by_sel=ms_names,
                        inferred_abi_by_sel=ms_inf,
                        prescreen_diagnostics={**ms_diag, "cross_contract_ro_reentrancy_probe": True},
                        needs_agent_synthesis=p_complex,
                        undecided_reason="Cross-contract read-only reentrancy callback synthesis" if p_complex else "",
                    )
                )
                peer_mf_added += 1
    if midframe_crit_slices:
        priority_slices[:0] = midframe_crit_slices

    # 4-B. 동일 블록 가드 상태 변경 -> 특권 싱크 2-레그 페어링 (미보호 초기화/가드 슬롯 덮어쓰기 -> caller_dominated 싱크)
    priv_sinks_tk = [
        ep_p
        for ep_p in cfg.entries.values()
        if ep_p.caller_dominated
        and (ep_p.reaches_value_sink or ep_p.reaches_sstore)
        and not _is_pure_readonly_ep(ep_p)
    ]
    priv_sinks_tk.sort(key=lambda ep_p: (not ep_p.reaches_value_sink, ep_p.selector))
    guard_override_slices: List[CausalSlice] = []
    seen_tk_pairs: Set[Tuple[str, str]] = set()
    for wr_tk in writers:
        if len(guard_override_slices) >= 4:
            break
        for ps_tk in priv_sinks_tk:
            if len(guard_override_slices) >= 4:
                break
            if wr_tk.selector == ps_tk.selector or (wr_tk.selector, ps_tk.selector) in seen_tk_pairs:
                continue
            slot_hit = ps_tk.dominator_guard_slot is not None and ps_tk.dominator_guard_slot in wr_tk.written_slots
            if not (slot_hit or wr_tk.reaches_arbitrary_sstore or (wr_tk.has_unguarded_low_slot_init and ps_tk.reaches_value_sink)):
                continue
            seen_tk_pairs.add((wr_tk.selector, ps_tk.selector))
            tk_abi = {
                s_k: abi_map[s_k.lower()]
                for s_k in (wr_tk.selector, ps_tk.selector)
                if s_k.lower() in abi_map and s_k.lower() != "fallback"
            }
            tk_names, tk_inf = _sel_extra_meta((wr_tk.selector, ps_tk.selector))
            tk_complex = (len(tk_abi) < 2) or any(_abi_requires_agent_reasoning(v) for v in tk_abi.values())
            tk_slots = [ps_tk.dominator_guard_slot] if ps_tk.dominator_guard_slot is not None else sorted(wr_tk.written_slots)[:4]
            guard_override_slices.append(
                CausalSlice(
                    slice_id=f"ch_guard_override_{t_norm[-6:]}_{wr_tk.selector}_{ps_tk.selector}",
                    target_address=t_norm,
                    channel="CH_STORAGE",
                    legs=[wr_tk.selector, ps_tk.selector],
                    shared_slots=tk_slots,
                    witness_candidates=witnesses[:12],
                    repeat_counts=[1, 2],
                    rationale="Same-block guard-state override (open guard-slot write / unguarded init -> privileged sink)",
                    leg_targets=[t_norm, t_norm],
                    abi_inputs_by_sel=tk_abi,
                    abi_param_names_by_sel=tk_names,
                    inferred_abi_by_sel=tk_inf,
                    prescreen_diagnostics={"privileged_guard_override_risk": True},
                    needs_agent_synthesis=tk_complex,
                    undecided_reason="Guard-override-to-privileged-sink 2-tx verification" if tk_complex else "",
                )
            )
    if guard_override_slices:
        priority_slices[:0] = guard_override_slices

    # 2. CH_STORAGE 2/3/4-leg 교차 쌍: 대형 컨트랙트(>=45 셀렉터)에서도 2/3/4-leg 쌍이 기아되지 않도록 최소 예산을 선점하고
    #    구체적 슬롯/매핑 결합쌍을 우선 배치한다.
    reserved_pairs = min(24, max_slices // 3) if (writers and sinks and len(sinks) >= 2) else 0
    single_cap = max(16, max_slices - len(priority_slices) - reserved_pairs)
    kept_singles = slices[:single_cap]
    pair_budget = max(reserved_pairs, max_slices - len(priority_slices) - len(kept_singles))
    coupled_pair_slices: List[CausalSlice] = []
    uncoupled_pair_slices: List[CausalSlice] = []
    if pair_budget > 0:
        for wr in writers:
            if len(coupled_pair_slices) >= pair_budget:
                break
            wr_w_slots = wr.written_slots
            wr_w_maps = wr.written_map_slots
            wr_no_slots = not wr_w_slots and not wr_w_maps
            wr2 = next((w for w in writers if w.selector != wr.selector), wr) if len(writers) >= 2 else None
            for sk in sinks:
                if len(coupled_pair_slices) >= pair_budget:
                    break
                if wr.selector == sk.selector:
                    continue
                sh_sc_set = wr_w_slots & sk.read_slots
                sh_mp_set = wr_w_maps & sk.read_map_slots
                no_concrete_slots = wr_no_slots and not sk.read_slots and not sk.read_map_slots
                if sh_sc_set or sh_mp_set or no_concrete_slots:
                    dst_bucket = coupled_pair_slices if (sh_sc_set or sh_mp_set) else uncoupled_pair_slices
                    if dst_bucket is uncoupled_pair_slices and len(uncoupled_pair_slices) >= pair_budget:
                        continue
                    shared_scalar = sorted(sh_sc_set)[:8] if sh_sc_set else []
                    shared_maps = sorted(sh_mp_set)[:8] if sh_mp_set else []
                    sel_abi = {
                        s: abi_map[s.lower()]
                        for s in (wr.selector, sk.selector)
                        if s.lower() in abi_map and s.lower() != "fallback"
                    }
                    pair_names, pair_inf = _sel_extra_meta((wr.selector, sk.selector))
                    pair_verified = len(sel_abi) == 2
                    complex_pair = (not pair_verified) or any(_abi_requires_agent_reasoning(v) for v in sel_abi.values())
                    dst_bucket.append(
                        CausalSlice(
                            slice_id=f"ch_storage_2leg_{t_norm[-6:]}_{wr.selector}_{sk.selector}",
                            target_address=t_norm,
                            channel="CH_STORAGE",
                            legs=[wr.selector, sk.selector],
                            shared_slots=shared_scalar,
                            shared_map_slots=shared_maps,
                            witness_candidates=witnesses[:14],
                            repeat_counts=[1, 2, 5],
                            rationale="State writer SSTORE coupling into value sink SLOAD",
                            leg_targets=[t_norm, t_norm],
                            abi_inputs_by_sel=sel_abi,
                            abi_param_names_by_sel=pair_names,
                            inferred_abi_by_sel=pair_inf,
                            needs_agent_synthesis=complex_pair,
                            undecided_reason="Multi-leg unverified or complex ABI state transition" if complex_pair else "",
                        )
                    )
                    if len(dst_bucket) >= pair_budget:
                        continue
                    dst_bucket.append(
                        CausalSlice(
                            slice_id=f"ch_storage_3leg_{t_norm[-6:]}_{wr.selector}_{sk.selector}_{wr.selector}",
                            target_address=t_norm,
                            channel="CH_STORAGE",
                            legs=[wr.selector, sk.selector, wr.selector],
                            shared_slots=shared_scalar,
                            shared_map_slots=shared_maps,
                            witness_candidates=witnesses[:10],
                            repeat_counts=[1, 2],
                            rationale="3-leg symmetric state transition and unwind sequence",
                            leg_targets=[t_norm, t_norm, t_norm],
                            abi_inputs_by_sel=sel_abi,
                            abi_param_names_by_sel=pair_names,
                            inferred_abi_by_sel=pair_inf,
                            needs_agent_synthesis=complex_pair,
                            undecided_reason="3-leg unverified or complex ABI state transition" if complex_pair else "",
                        )
                    )
                    if wr2 is not None and len(dst_bucket) < pair_budget:
                        sel_abi_4 = {
                            s: abi_map[s.lower()]
                            for s in (wr.selector, wr2.selector, sk.selector)
                            if s.lower() in abi_map and s.lower() != "fallback"
                        }
                        names_4, inf_4 = _sel_extra_meta((wr.selector, wr2.selector, sk.selector))
                        complex_4 = (len(sel_abi_4) < 3) or any(_abi_requires_agent_reasoning(v) for v in sel_abi_4.values())
                        dst_bucket.append(
                            CausalSlice(
                                slice_id=f"ch_storage_4leg_{t_norm[-6:]}_{wr.selector}_{wr2.selector}_{sk.selector}_{wr.selector}",
                                target_address=t_norm,
                                channel="CH_STORAGE",
                                legs=[wr.selector, wr2.selector, sk.selector, wr.selector],
                                shared_slots=shared_scalar,
                                shared_map_slots=shared_maps,
                                witness_candidates=witnesses[:8],
                                repeat_counts=[1, 2],
                                rationale="4-leg capital-prioritized setup-mutate-extract-unwind sequence",
                                leg_targets=[t_norm, t_norm, t_norm, t_norm],
                                abi_inputs_by_sel=sel_abi_4,
                                abi_param_names_by_sel=names_4,
                                inferred_abi_by_sel=inf_4,
                                needs_agent_synthesis=complex_4,
                                undecided_reason="4-leg multi-state unverified or complex ABI boundary" if complex_4 else "",
                            )
                        )

    pair_slices = (coupled_pair_slices + uncoupled_pair_slices)[:pair_budget]
    return (priority_slices + pair_slices[:reserved_pairs] + kept_singles + pair_slices[reserved_pairs:])[:max_slices]


def _build_approval_arbcall_slices(
    open_target_cfgs: Sequence[Tuple[str, Any, Any, Sequence[str]]],
    verified_sources: Mapping[str, Mapping[str, Any]],
    closure: TrustClosureResult,
    token_addrs: Sequence[str],
    caller_addr: str,
    *,
    max_slices: int = 12,
) -> List[CausalSlice]:
    """
    승인-포워딩 보존 불변식 프로브:
    폐포 내 활성 ERC-20 및 Permit2 승인 보유 오너와 개방형 임의 호출(address, [uint256,] bytes) 진입점이
    동시에 존재할 때, 로컬 포크에서 비인가 transferFrom 포워딩 차단 여부를 결정론적으로 검증한다.
    """
    owners = [_norm_addr(a) for a in (closure.approved_owners or ()) if _norm_addr(a)]
    caller_n = _norm_addr(caller_addr)
    if not owners or not caller_n or not token_addrs:
        return []
    tok_probe = [_norm_addr(t) for t in token_addrs if _norm_addr(t)][:3]
    if not tok_probe:
        return []
    permit2_n = _norm_addr(PERMIT2_ADDR)
    u160_max = (1 << 160) - 1
    out: List[CausalSlice] = []
    seen_ids: Set[str] = set()
    for addr, f_map_o, _cfg_o, open_sels_o in open_target_cfgs[:12]:
        t_norm = _norm_addr(addr)
        if not t_norm:
            continue
        open_set = {s.lower() for s in open_sels_o if s}
        merged_abi: List[Any] = []
        p_abi = verified_sources.get(addr, {}).get("abi") or []
        if isinstance(p_abi, list):
            merged_abi.extend(p_abi)
        for f_addr in (f_map_o or ()):
            f_abi = verified_sources.get(_norm_addr(str(f_addr)), {}).get("abi") or []
            if isinstance(f_abi, list):
                merged_abi.extend(f_abi)
        if not merged_abi:
            continue
        abi_map = _extract_abi_inputs_map(merged_abi)
        for sel_l in sorted(open_set):
            in_ts = [t.strip() for t in (abi_map.get(sel_l) or ())]
            if in_ts not in (
                ["address", "bytes"],
                ["address", "uint256", "bytes"],
                ["address", "bytes", "uint256"],
                ["bytes", "address"],
            ):
                continue
            def _append_fwd(tag_f: str, dst_f: str, inner_sel: str, inner_ts: List[str], inner_vs: List[Any], rat_f: str, suf: str, ch_f: str, w_f: int) -> bool:
                try:
                    inner_cd = bytes.fromhex(encode_calldata(inner_sel, inner_ts, inner_vs)[2:])
                    if in_ts == ["address", "bytes"]:
                        outer_vals: List[Any] = [dst_f, inner_cd]
                    elif in_ts == ["address", "uint256", "bytes"]:
                        outer_vals = [dst_f, 0, inner_cd]
                    elif in_ts == ["address", "bytes", "uint256"]:
                        outer_vals = [dst_f, inner_cd, 0]
                    else:
                        outer_vals = [inner_cd, dst_f]
                    outer_hex = encode_calldata(sel_l, in_ts, outer_vals)[2:]
                except Exception:
                    return False
                if not (8 <= len(outer_hex) <= 4096 and (len(outer_hex) % 2) == 0):
                    return False
                sid = f"ch_approval_{tag_f}_{t_norm[-6:]}_{sel_l}_{suf}"
                if sid in seen_ids:
                    return False
                seen_ids.add(sid)
                out.append(
                    CausalSlice(
                        slice_id=sid,
                        target_address=t_norm,
                        channel=ch_f,
                        legs=[sel_l],
                        witness_candidates=[w_f],
                        repeat_counts=[1],
                        rationale=rat_f,
                        leg_targets=[t_norm],
                        abi_inputs_by_sel={sel_l: in_ts},
                        needs_agent_synthesis=False,
                        preencoded_calldata_hex=[outer_hex],
                    )
                )
                return len(out) >= max_slices

            for tok_a in tok_probe[:2]:
                _raw_dec_t = closure.token_decimals.get(tok_a)
                dec_t = max(0, min(77, int(18 if _raw_dec_t is None else _raw_dec_t)))
                probe_amt = max(1, 10 ** min(dec_t, 6))
                for ow_a in owners[:2]:
                    if _append_fwd("erc20", tok_a, TRANSFER_FROM_SEL, ["address", "address", "uint256"], [ow_a, caller_n, probe_amt], "Arbitrary-call ERC-20 allowance forwarding conservation check", f"{tok_a[-4:]}_{ow_a[-4:]}", "CH_BALANCE", probe_amt):
                        return out
                    if _append_fwd("permit2", permit2_n, PERMIT2_TRANSFER_FROM_SEL, ["address", "address", "uint160", "address"], [ow_a, caller_n, min(probe_amt, u160_max), tok_a], "Arbitrary-call Permit2 allowance forwarding conservation check", f"{tok_a[-4:]}_{ow_a[-4:]}", "CH_BALANCE", probe_amt):
                        return out
            nft_targets = [
                _norm_addr(a_nf)
                for a_nf, _, cfg_nf, _ in open_target_cfgs[:8]
                if _norm_addr(a_nf)
                and cfg_nf is not None
                and (ERC721_OWNER_OF_SEL.lower() in cfg_nf.entries or ERC721_IS_APPROVED_FOR_ALL_SEL.lower() in cfg_nf.entries)
            ][:2]
            for nft_a in nft_targets:
                for ow_a in owners[:1]:
                    if _append_fwd("erc721", nft_a, ERC721_TRANSFER_FROM_SEL, ["address", "address", "uint256"], [ow_a, caller_n, 1], "Arbitrary-call ERC-721 operator approval forwarding check", f"{nft_a[-4:]}_{ow_a[-4:]}", "CH_MIDFRAME", 1):
                        return out
                    if _append_fwd("erc1155", nft_a, ERC1155_SAFE_TRANSFER_FROM_SEL, ["address", "address", "uint256", "uint256", "bytes"], [ow_a, caller_n, 1, 1, b""], "Arbitrary-call ERC-1155 operator approval forwarding check", f"{nft_a[-4:]}_{ow_a[-4:]}", "CH_MIDFRAME", 1):
                        return out
    return out

