@functools.lru_cache(maxsize=32)
def _strip_solidity_comments_preserve_strings(src: str) -> str:
    """문자열 리터럴("...", '...') 내부의 //, /* 를 건드리지 않고 Solidity 주석만 정확히 제거한다."""
    if not src or ("/" not in src):
        return src

    def _repl(m: re.Match[str]) -> str:
        tok = m.group(0)
        ch0 = tok[0]
        if ch0 in ('"', "'"):
            return tok
        if tok.startswith("/*"):
            nl = tok.count("\n")
            return "\n" * nl if nl else " "
        return ""

    return _SOL_COMMENT_OR_STR_RE.sub(_repl, src)


@functools.lru_cache(maxsize=32)
def _strip_quoted_strings_cached(src: str) -> str:
    if not src or ('"' not in src and "'" not in src):
        return src
    return _SOL_QUOTED_STR_RE.sub('""', src)


