        "\n"
        "    function swapUniV4(address pm, address tokIn, address tokOut, uint256 amtIn, uint24 fee, int24 tickSpacing, address hooks, address to) external {\n"
        "        uint256 outBalBefore = _tBal(tokOut, to);\n"
        "        uint256 inBefore = _tBal(tokIn, address(this));\n"
        "        _tTransferFrom(tokIn, msg.sender, address(this), amtIn);\n"
        "        uint256 gotIn = _tBal(tokIn, address(this));\n"
        "        gotIn = gotIn > inBefore ? (gotIn - inBefore) : 0;\n"
        '        require(gotIn > 0 && gotIn <= uint256(type(int256).max), "V4IN");\n'
        "        _cbPool = pm;\n"
        "        _cbPayer = msg.sender;\n"
        "        _cbToken = tokIn;\n"
        f"        (bool okU, ) = pm.call(abi.encodeWithSelector({UNLOCK_BYTES_SEL}, abi.encode(UniV4SwapData(tokIn, tokOut, gotIn, fee, tickSpacing, hooks, to))));\n"
        "        _cbPool = address(0);\n"
        "        _cbPayer = address(0);\n"
        "        _cbToken = address(0);\n"
        "        uint256 remIn = _tBal(tokIn, address(this));\n"
        "        if (remIn > inBefore) { _tTransfer(tokIn, msg.sender, remIn - inBefore); }\n"
        '        require(okU && _tBal(tokOut, to) > outBalBefore, "V4S");\n'
        "    }\n"
        "\n"
        "    function unlockCallback(bytes calldata data) external returns (bytes memory) {\n"
        '        require(msg.sender == _cbPool && _cbPool != address(0), "CBP");\n'
        "        UniV4SwapData memory u = abi.decode(data, (UniV4SwapData));\n"
        "        bool z2o = u.tokIn < u.tokOut;\n"
        "        int256 delta;\n"
        "        {\n"
        "            bytes memory swapCd = abi.encodeWithSelector(\n"
        f"                {UNIV4_SWAP_SEL},\n"
        "                z2o ? u.tokIn : u.tokOut,\n"
        "                z2o ? u.tokOut : u.tokIn,\n"
        "                u.fee,\n"
        "                u.ts,\n"
        "                u.hooks,\n"
        "                z2o,\n"
        "                -int256(u.amtIn),\n"
        "                z2o ? uint160(4295128740) : uint160(1461446703485210103287273052203988822378723970341),\n"
        '                bytes("")\n'
        "            );\n"
        "            (bool okSw, bytes memory rSw) = msg.sender.call(swapCd);\n"
        '            require(okSw && rSw.length >= 32, "V4SW");\n'
        "            delta = abi.decode(rSw, (int256));\n"
        "        }\n"
        "        int128 dIn = z2o ? int128(delta >> 128) : int128(delta);\n"
        "        int128 dOut = z2o ? int128(delta) : int128(delta >> 128);\n"
        "        if (dIn < 0) {\n"
        "            uint256 payAmt = uint256(-int256(dIn));\n"
        f"            (bool okSy, ) = msg.sender.call(abi.encodeWithSelector({UNIV4_SYNC_SEL}, u.tokIn));\n"
        '            require(okSy, "V4Y");\n'
        "            _tTransfer(u.tokIn, msg.sender, payAmt);\n"
        f"            (bool okSt, ) = msg.sender.call(abi.encodeWithSelector({UNIV4_SETTLE_SEL}));\n"
        '            require(okSt, "V4ST");\n'
        "        }\n"
        "        if (dOut > 0) {\n"
        f"            (bool okTk, ) = msg.sender.call(abi.encodeWithSelector({UNIV4_TAKE_SEL}, u.tokOut, u.to, uint256(int256(dOut))));\n"
        '            require(okTk, "V4TK");\n'
        "        }\n"
        '        return "";\n'
        "    }\n"
        "\n"
        "    function swapBalancerV3(address vault, address pool, address tokIn, address tokOut, uint256 amtIn, address to) external {\n"
        "        uint256 outBalBefore = _tBal(tokOut, to);\n"
        "        uint256 inBefore = _tBal(tokIn, address(this));\n"
        "        _tTransferFrom(tokIn, msg.sender, address(this), amtIn);\n"
        "        uint256 gotIn = _tBal(tokIn, address(this));\n"
        "        gotIn = gotIn > inBefore ? (gotIn - inBefore) : 0;\n"
        '        require(gotIn > 0, "B3IN");\n'
        "        _cbPool = vault;\n"
        "        _cbPayer = msg.sender;\n"
        "        _cbToken = tokIn;\n"
        "        bytes memory cb = abi.encodeWithSelector(this.onBalV3SwapUnlock.selector, pool, tokIn, tokOut, gotIn, to);\n"
        f"        (bool okU, ) = vault.call(abi.encodeWithSelector({UNLOCK_BYTES_SEL}, cb));\n"
        "        _cbPool = address(0);\n"
        "        _cbPayer = address(0);\n"
        "        _cbToken = address(0);\n"
        "        uint256 remIn = _tBal(tokIn, address(this));\n"
        "        if (remIn > inBefore) { _tTransfer(tokIn, msg.sender, remIn - inBefore); }\n"
        '        require(okU && _tBal(tokOut, to) > outBalBefore, "B3S");\n'
        "    }\n"
        "\n"
        "    function onBalV3SwapUnlock(address pool, address tokIn, address tokOut, uint256 amtIn, address to) external {\n"
        '        require(msg.sender == _cbPool && _cbPool != address(0), "CBP");\n'
        '        BalV3SwapParams memory sp = BalV3SwapParams(0, pool, tokIn, tokOut, amtIn, uint256(1), bytes(""));\n'
        f"        (bool okSw, bytes memory rSw) = msg.sender.call(abi.encodeWithSelector({BALANCER_V3_SWAP_SEL}, sp));\n"
        '        require(okSw && rSw.length >= 96, "B3SW");\n'
        "        (, uint256 usedIn, uint256 gotOut) = abi.decode(rSw, (uint256, uint256, uint256));\n"
        '        require(usedIn > 0 && gotOut > 0, "B3Z");\n'
        "        _tTransfer(tokIn, msg.sender, usedIn);\n"
        f"        (bool okSet, ) = msg.sender.call(abi.encodeWithSelector({BALANCER_V3_SETTLE_SEL}, tokIn, usedIn));\n"
        '        require(okSet, "B3ST");\n'
        f"        (bool okSnd, ) = msg.sender.call(abi.encodeWithSelector({BALANCER_V3_SEND_TO_SEL}, tokOut, to, gotOut));\n"
        '        require(okSnd, "B3SD");\n'
        "    }\n"
        "\n"
        "    function unwindV2LP(address pool, uint256 amtIn, address to) external {\n"
        "        _tTransferFrom(pool, msg.sender, pool, amtIn);\n"
        f'        (bool okB, ) = pool.call(abi.encodeWithSelector({V2_BURN_SEL}, to));\n'
