_SOL_SNAP_DECL_PREFIX_RE: re.Pattern[str] = re.compile(r"\b(?:ConservationSnap|NftSnap)\s+(?:memory|storage|calldata)\s+$")


@functools.lru_cache(maxsize=32)
def _extract_sol_fn_entries_cached(sol_src: str) -> Tuple[Tuple[str, str, str], ...]:
    out: List[Tuple[str, str, str]] = []
    for m in _SOL_FN_SIG_BRACE_RE.finditer(sol_src):
        close_idx = _scan_matched_delim(sol_src, m.end() - 1, "{", "}")
        if close_idx > m.end() - 1:
            out.append((m.group(1), sol_src[m.end() : close_idx], sol_src[m.start() : close_idx + 1]))
    return tuple(out)


def _extract_sol_fn_entries(sol_src: str) -> List[Tuple[str, str, str]]:
    """주석이 제거된 Solidity 본문에서 `(함수명, 함수내부본문, 시그니처포함전체함수)` 목록을 추출한다."""
    return list(_extract_sol_fn_entries_cached(sol_src))


_CANON_VAULT_LOOP_HEAD_RE: re.Pattern[str] = re.compile(
    r"address\[(\d+)\]memoryvaults=_vaultTable\(\);for\(uint256vIdx=0;vIdx<\1;vIdx\+\+\)"
)
_CANON_WIDX_DECL_RE: re.Pattern[str] = re.compile(r"uint256wIdx=(\d+);")


@functools.lru_cache(maxsize=64)
def _compiled_canon_caller_tok_re(caller_tok: str) -> re.Pattern[str]:
    return re.compile(rf"(?<![0-9A-Za-z_]){re.escape(caller_tok)}(?![0-9A-Za-z_])")


@functools.lru_cache(maxsize=64)
def _compiled_canon_ac_regexes(asset_count: int) -> Tuple[re.Pattern[str], re.Pattern[str]]:
    ac_s = str(asset_count)
    return (
        re.compile(rf"\baddress\[{ac_s}\]"),
        re.compile(rf"\buint256\[{ac_s}\](?=memory(?:liqCredit|liqDebited|zCredit|zDebited|b|s|totalB))"),
    )


@functools.lru_cache(maxsize=256)
def _normalize_canon_sol_fn(fn_nm: str, raw_fn_src: str, caller_tok: str, asset_count: int) -> str:
    s = "".join(raw_fn_src.split())
    if caller_tok and caller_tok in s:
        s = _compiled_canon_caller_tok_re(caller_tok).sub("__CALLER__", s)
    if fn_nm == "_verifyPostCommitSettlement":
        s = _CANON_VAULT_LOOP_HEAD_RE.sub("address[VC]memoryvaults=_vaultTable();for(uint256vIdx=0;vIdx<VC;vIdx++)", s)
    if asset_count > 0:
        ac_s = str(asset_count)
        addr_tok = f"address[{ac_s}]"
        uint_tok = f"uint256[{ac_s}]"
        if addr_tok in s or uint_tok in s:
            addr_ac_re, uint_ac_re = _compiled_canon_ac_regexes(asset_count)
            if addr_tok in s:
                s = addr_ac_re.sub("address[AC]", s)
            if uint_tok in s:
                s = uint_ac_re.sub("uint256[AC]", s)
        s = s.replace(f"tokSlot>={ac_s}", "tokSlot>=AC").replace(f"quoteSlot>={ac_s}", "quoteSlot>=AC")
        s = s.replace(f"i<{ac_s};i++", "i<AC;i++")
    if fn_nm == "_assertConservationLiq":
        s = _CANON_WIDX_DECL_RE.sub("uint256wIdx=WIDX;", s)
    return s


@functools.lru_cache(maxsize=1)
def _canonical_harness_fn_specs() -> Dict[str, FrozenSet[str]]:
    specs: Dict[str, Set[str]] = {}
    dummy_caller = "ZERO_STATE_CALLER"
    canon_addrs = [_checksum("0x" + b * 20) for b in ("a1", "a2", "a3", "a4")]
    sample_route = {
        canon_addrs[1]: {
            "pool": canon_addrs[2],
            "quote_token": WRAPPED_NATIVE_BY_CHAIN["ethereum"],
            "dex_kind": "v2",
            "paused": False,
        }
    }
    for w_idx, toks, routes in (
        (0, [canon_addrs[1]], None),
        (1, [canon_addrs[1], WRAPPED_NATIVE_BY_CHAIN["ethereum"]], sample_route),
    ):
        ctx = _prepare_conservation_harness_context(
            "canon_spec",
            "ethereum",
            canon_addrs[3],
            canon_addrs[0],
            toks,
            vault_addresses=[canon_addrs[0]],
            exit_routes=routes,
        )
        # Keep explicit w_idx test coverage regardless of WNATIVE presence
        ctx["wnative_slot_idx"] = w_idx
        ac_n = int(ctx["asset_count"])
        rendered = _render_conservation_contract_body(
            ctx,
            "Verify_CANON",
            dummy_caller,
            include_bridge_helper=True,
            caller_const_decl=True,
        )
        clean_r = _strip_solidity_comments_preserve_strings(rendered)
        for fn_nm, _, fn_full in _extract_sol_fn_entries(clean_r):
            if fn_nm in _CANONICAL_FIXED_BODY_FNS:
                specs.setdefault(fn_nm, set()).add(
                    _normalize_canon_sol_fn(fn_nm, fn_full, dummy_caller, ac_n)
                )
    return {k: frozenset(v) for k, v in specs.items()}


@functools.lru_cache(maxsize=128)
def _compiled_sol_fn_call_alt_re(fn_names: Tuple[str, ...]) -> re.Pattern[str]:
    return re.compile(r"\b(?:" + "|".join(re.escape(n) for n in fn_names) + r")\s*\(")


def _extract_sol_loop_bodies(fn_body: str) -> List[str]:
    """함수 본문 내 `for`/`while`/`do` 반복문 블록 본문을 추출한다."""
    loops: List[str] = []
    n = len(fn_body)
    pos = 0
    while pos < n:
        m = _SOL_LOOP_HEAD_RE.search(fn_body, pos)
        if not m:
            break
        if m.group(2):
            open_b = m.end() - 1
            close_b = _scan_matched_delim(fn_body, open_b, "{", "}")
            if close_b > open_b:
                loops.append(fn_body[open_b + 1 : close_b])
                pos = close_b + 1
            else:
                pos = m.end()
        else:
            close_p = _scan_matched_delim(fn_body, m.end() - 1, "(", ")")
            if close_p < 0:
                pos = m.end()
                continue
            j = close_p + 1
            while j < n and fn_body[j].isspace():
                j += 1
            if j < n and fn_body[j] == "{":
                close_b = _scan_matched_delim(fn_body, j, "{", "}")
                if close_b > j:
                    loops.append(fn_body[j + 1 : close_b])
                    pos = close_b + 1
                    continue
            pos = j
    return loops


