def _extract_sol_harness_const_addrs(sol_code: str) -> Tuple[Dict[int, str], Dict[int, str]]:
    """Solidity 테스트 소스에서 선언된 `(VAULT_idx -> norm_addr, TOK_idx -> norm_addr)` 맵을 추출한다."""
    clean_c = _strip_hex_underscores_preserve_strings(_strip_solidity_comments_preserve_strings(sol_code or ""))
    v_map: Dict[int, str] = {}
    t_map: Dict[int, str] = {}
    for c_id, c_rhs_raw in _SOL_CONST_ADDR_DECL_RE.findall(clean_c):
        c_rhs = _unwrap_sol_addr_expr(c_rhs_raw)
        if not _SOL_FULL_HEX_ADDR_RE.fullmatch(c_rhs):
            continue
        na = f"0x{int(c_rhs, 16):040x}"
        if c_id.startswith("VAULT_") and c_id[6:].isdigit():
            v_map[int(c_id[6:])] = na
        elif c_id.startswith("TOK_") and c_id[4:].isdigit():
            t_map[int(c_id[4:])] = na
    return v_map, t_map


