def _extract_sol_file_level_src(clean_src: str) -> str:
    """컨트랙트·라이브러리·인터페이스 블록 바깥의 최상위(파일 수준) Solidity 코드를 추출한다."""
    if not clean_src:
        return ""
    out_parts: List[str] = []
    pos = 0
    n_s = len(clean_src)
    for m_td in _SOL_ANY_TOP_DECL_RE.finditer(clean_src):
        if m_td.start() < pos:
            continue
        out_parts.append(clean_src[pos : m_td.start()])
        b_open = m_td.end() - 1
        b_close = _scan_matched_delim(clean_src, b_open, "{", "}")
        pos = (b_close + 1) if b_close >= 0 else n_s
    if pos < n_s:
        out_parts.append(clean_src[pos:])
    return "\n".join(out_parts)


@functools.lru_cache(maxsize=128)
def _verify_agent_harness_accounting_integrity_cached(
    sol_code: str,
    allowed_caller: str,
    allowed_target_addrs: Tuple[str, ...],
    chain: str,
) -> Tuple[bool, Tuple[str, ...]]:
    clean = _strip_hex_underscores_preserve_strings(_strip_solidity_comments_preserve_strings(sol_code or ""))
    violations: List[str] = []

    def _has_state_ident(expr_s: str) -> bool:
        no_hex = _SOL_HEX_LITERAL_RE.sub("0", expr_s)
        return any(
            tok.lower() not in _SOL_UNITS_LOWER and not _SOL_PRIM_TYPE_RE.fullmatch(tok)
            for tok in _SOL_IDENT_TOKEN_RE.findall(no_hex)
        )

    def _has_literal_boost(expr_s: str) -> bool:
        raw_e = expr_s or ""
        stripped = _BRACKET_SPAN_RE.sub(" ", raw_e) if "[" in raw_e else raw_e
        if _SOL_LITERAL_BOOST_RE.search(stripped):
            return True
        if _SOL_SCI_OR_UNIT_LIT_RE.search(stripped):
            return True
        has_hex_e = ("0x" in stripped or "0X" in stripped)
        if has_hex_e and _SOL_INT_CAST_HEX_ADDR_RE.search(stripped):
            return True
        # Ignore 40-hex EVM addresses (e.g. `address(0x...).balance`, `_verifyPostCommitSettlement(asset, 0x..., amt)`)
        # before unwrapping casts and scanning numeric literals/boosts/operators.
        no_addr_hex = _SOL_HEX_ADDR40_TOKEN_RE.sub(" ", stripped) if has_hex_e else stripped
        if _SOL_FORB_ACCT_OP_RE.search(no_addr_hex):
            return True
        if "(" in no_addr_hex or ")" in no_addr_hex:
            unwrapped = _SOL_CAST_PREFIX_RE.sub("(", no_addr_hex)
            flat_expr = _SOL_PAREN_CHARS_RE.sub(" ", unwrapped)
            if _SOL_LITERAL_BOOST_RE.search(unwrapped) or _SOL_LITERAL_BOOST_RE.search(flat_expr):
                return True
        for m_lit in _SOL_DEC_OR_HEX_LIT_RE.finditer(no_addr_hex):
            tok_l = m_lit.group(0).replace("_", "").lower()
            try:
                if "e" in tok_l and not tok_l.startswith("0x"):
                    base_s, exp_s = tok_l.split("e", 1)
                    if int(base_s or "0") > 0 and int(exp_s) >= 0:
                        return True
                else:
                    l_val = int(tok_l, 16) if tok_l.startswith("0x") else int(tok_l, 10)
                    if l_val >= 1:
                        return True
            except ValueError:
                continue
        return False

    # Reject Yul log0..log4 in inline assembly (could emit forged ConservationGain topic0 bytes).
    for asm_body in _extract_assembly_blocks(clean):
        if _SOL_ASM_LOG_RE.search(asm_body):
            violations.append("FORBIDDEN_ASSEMBLY_LOG_EMISSION")

    # Reject ConservationGain declarations or emits outside test/harness contracts (including file-level free functions/events).
    file_level_src = _extract_sol_file_level_src(clean)
    if file_level_src:
        if _SOL_CONSERVATION_EVENT_EMIT_RE.search(file_level_src):
            violations.append("FORBIDDEN_FILE_LEVEL_CONSERVATION_EMITTER")
        for fl_nm, fl_b, _ in _extract_sol_fn_entries(file_level_src):
            if fl_nm in _CANONICAL_ALL_PROTECTED_FNS:
                violations.append(f"FORBIDDEN_FILE_LEVEL_CANONICAL_FN:{fl_nm}")
            if _SOL_ASM_KW_RE.search(fl_b) or _SOL_ASSERT_OR_EMIT_CALL_RE.search(fl_b):
                violations.append(f"FORBIDDEN_FILE_LEVEL_CONSERVATION_FN:{fl_nm}")

    test_contract_bodies: List[str] = []
    seen_tc_bodies: Set[int] = set()
    for c_nm, (_c_kd, _, bodies) in _parse_solidity_contract_closures(clean, include_library=True).items():
        is_test_c = (
            _c_kd == "library"
            or c_nm.startswith(("Verify_", "AgentVerify_"))
            or any(_SOL_TEST_FN_RE.search(b) is not None for b in bodies)
        )
        if not is_test_c and bodies:
            own_b = bodies[0]
            if _SOL_CONSERVATION_EVENT_EMIT_RE.search(own_b):
                violations.append(f"FORBIDDEN_NON_HARNESS_CONSERVATION_EMITTER:{c_nm}")
        elif is_test_c:
            for b_tc in bodies:
                if id(b_tc) not in seen_tc_bodies:
                    seen_tc_bodies.add(id(b_tc))
                    test_contract_bodies.append(b_tc)

    harness_scope_src = "\n".join(test_contract_bodies) if test_contract_bodies else clean

    fn_entries = _extract_sol_fn_entries(harness_scope_src)
    fn_list = [(fn_nm, fn_b) for fn_nm, fn_b, _ in fn_entries]

    # Canonical harness helper & skeleton constant integrity: forbid tampering/duplicating ZERO_STATE_CALLER / TARGET / VAULT_* / TOK_*
    norm_allowed_caller = _norm_addr(allowed_caller)
    norm_allowed_targets: Set[str] = {
        na for raw_t in (allowed_target_addrs or ()) if (na := _norm_addr(str(raw_t)))
    }
    forb_const_addrs: Set[str] = {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        CREATE2_DEPLOYER_ADDR,
        ZERO_ADDRESS,
        SETTLEMENT_SINK_ADDR,
    }
    zsc_decl_addrs: List[str] = []
    target_decl_addrs: List[str] = []
    vault_const_map: Dict[int, str] = {}
    seen_vault_const_addrs: Set[str] = set()
    tok_const_map: Dict[int, str] = {}
    seen_tok_const_addrs: Set[str] = set()
    for c_id, c_rhs_raw in _SOL_CONST_ADDR_DECL_RE.findall(harness_scope_src):
        c_rhs = _unwrap_sol_addr_expr(c_rhs_raw)
        is_hex_a = _SOL_FULL_HEX_ADDR_RE.fullmatch(c_rhs) is not None
        na_c = f"0x{int(c_rhs, 16):040x}" if is_hex_a else ""
        if c_id == "ZERO_STATE_CALLER":
            zsc_decl_addrs.append(na_c)
            if (
                not na_c
                or na_c in forb_const_addrs
                or len(zsc_decl_addrs) > 1
                or (norm_allowed_caller and na_c != norm_allowed_caller)
            ):
                violations.append("FORBIDDEN_TAMPERED_ZERO_STATE_CALLER_CONST")
        elif c_id == "TARGET":
            target_decl_addrs.append(na_c)
            if (
                not na_c
                or na_c in forb_const_addrs
                or len(target_decl_addrs) > 1
                or (norm_allowed_targets and na_c not in norm_allowed_targets)
            ):
                violations.append("FORBIDDEN_TAMPERED_TARGET_CONST")
        elif c_id.startswith(("VAULT_", "TOK_")):
            is_vault_c = c_id.startswith("VAULT_")
            idx_part = c_id[6:] if is_vault_c else c_id[4:]
            if idx_part.isdigit():
                c_idx = int(idx_part)
                c_map = vault_const_map if is_vault_c else tok_const_map
                c_seen = seen_vault_const_addrs if is_vault_c else seen_tok_const_addrs
                if (
                    not na_c
                    or (na_c in forb_const_addrs and (na_c != CREATE2_DEPLOYER_ADDR or na_c not in norm_allowed_targets))
                    or c_idx in c_map
                    or na_c in c_seen
                ):
                    v_tag = "FORBIDDEN_DUPLICATE_OR_INVALID_VAULT_CONST" if is_vault_c else "FORBIDDEN_DUPLICATE_OR_INVALID_TOK_CONST"
                    violations.append(f"{v_tag}:{c_id}")
                else:
                    c_map[c_idx] = na_c
                    c_seen.add(na_c)

    zsc_assigns = _SOL_ZERO_CALLER_ASSIGN_RE.findall(harness_scope_src)
    if zsc_assigns and (
        not zsc_decl_addrs
        or not zsc_decl_addrs[0]
        or zsc_decl_addrs[0] in forb_const_addrs
        or len(zsc_assigns) > len(zsc_decl_addrs)
    ):
        violations.append("FORBIDDEN_TAMPERED_ZERO_STATE_CALLER_CONST")
    eff_caller_for_disjoint = norm_allowed_caller or (zsc_decl_addrs[0] if zsc_decl_addrs else "")
    zsc_pk_decls: List[int] = []
    for u_id, u_rhs_raw in _SOL_CONST_UINT_DECL_RE.findall(harness_scope_src):
        if u_id != "ZERO_STATE_CALLER_PK":
            continue
        u_rhs = _unwrap_sol_addr_expr(u_rhs_raw)
        pk_v = int(u_rhs, 16) if _SOL_FULL_HEX_UINT256_RE.fullmatch(u_rhs) else -1
        zsc_pk_decls.append(pk_v)
        if (
            pk_v <= 0
            or len(zsc_pk_decls) > 1
            or (eff_caller_for_disjoint and _secp256k1_privkey_to_eth_addr(pk_v) != eff_caller_for_disjoint)
        ):
            violations.append("FORBIDDEN_TAMPERED_ZERO_STATE_CALLER_PK_CONST")
    if eff_caller_for_disjoint and eff_caller_for_disjoint in seen_vault_const_addrs:
        violations.append("FORBIDDEN_CALLER_IN_VAULT_CONST")

    det_caller_tok = ""
    if zsc_decl_addrs and zsc_decl_addrs[0]:
        det_caller_tok = "ZERO_STATE_CALLER"
    else:
        _skip_det_addrs = ("0x0000000000000000000000000000000000000000", "0x0000000000000000000000000000000000099999")
        for pat_dc in (_SOL_VERIFY_PRANK_CALLER_RE, _SOL_VERIFY_POST_SETTLE_HEX_RE):
            for _, fn_b_dc, _ in fn_entries:
                m_dc = pat_dc.search(fn_b_dc)
                if m_dc and _norm_addr(m_dc.group(1)) not in _skip_det_addrs:
                    det_caller_tok = m_dc.group(1)
                    break
            if det_caller_tok:
                break
    det_ac = 0
    m_snap = _SOL_SNAP_STRUCT_RE.search(harness_scope_src)
    if m_snap:
        snap_compact = _WS_COLLAPSE_RE.sub("", m_snap.group(1))
        m_snap_ok = _SOL_SNAP_COMPACT_RE.fullmatch(snap_compact)
        if not m_snap_ok or not (m_snap_ok.group(1) == m_snap_ok.group(2) == m_snap_ok.group(3)):
            violations.append("FORBIDDEN_TAMPERED_CONSERVATION_SNAP_STRUCT")
        else:
            det_ac = int(m_snap_ok.group(1))
    m_nft_snap = _SOL_NFT_SNAP_STRUCT_RE.search(harness_scope_src)
    if m_nft_snap and not _SOL_NFT_SNAP_COMPACT_RE.fullmatch(_WS_COLLAPSE_RE.sub("", m_nft_snap.group(1))):
        violations.append("FORBIDDEN_TAMPERED_NFT_SNAP_STRUCT")

    det_vc = -1
    det_tok_cnt = -1
    for fn_nm_pre, fn_b_pre, _ in fn_entries:
        if fn_nm_pre == "_vaultTable":
            vt_pairs_pre = [(int(m.group(1)), int(m.group(2))) for m in _SOL_VAULT_SLOT_PAIR_RE.finditer(_WS_COLLAPSE_RE.sub("", fn_b_pre))]
            if vt_pairs_pre:
                det_vc = len(vt_pairs_pre)
        elif fn_nm_pre == "_assetTable":
            at_pairs_pre = [(int(m.group(1)), int(m.group(2))) for m in _SOL_ASSET_SLOT_PAIR_RE.finditer(_WS_COLLAPSE_RE.sub("", fn_b_pre))]
            det_tok_cnt = len(at_pairs_pre)

    canon_router_norm_set: FrozenSet[str] = _norm_addr_frozenset_cached(tuple(_CANONICAL_DEX_ROUTERS))
    canon_specs = _canonical_harness_fn_specs()
    fn_name_counts: Dict[str, int] = {}
    verified_fixed_canon_fns: Set[str] = set()
    has_take_snap = False
    snap_w_tok_idx: Optional[int] = None
    det_liq_widx: Optional[int] = None
    for fn_nm_c, fn_b_c, fn_full_c in fn_entries:
        if fn_nm_c in _CANONICAL_ALL_PROTECTED_FNS:
            fn_name_counts[fn_nm_c] = fn_name_counts.get(fn_nm_c, 0) + 1
            if fn_name_counts[fn_nm_c] > 1:
                violations.append(f"FORBIDDEN_DUPLICATE_CANONICAL_FN:{fn_nm_c}")
                verified_fixed_canon_fns.discard(fn_nm_c)
            if fn_nm_c in _CANONICAL_FIXED_BODY_FNS:
                eff_ac = det_ac
                if eff_ac <= 0:
                    m_ac_sig = _SOL_ASSETS_ARRAY_LEN_RE.search(fn_full_c)
                    eff_ac = int(m_ac_sig.group(1)) if m_ac_sig else 0
                norm_candidate = _normalize_canon_sol_fn(fn_nm_c, fn_full_c, det_caller_tok, eff_ac)
                allowed_norms = canon_specs.get(fn_nm_c, frozenset())
                fixed_ok = True
                if norm_candidate not in allowed_norms:
                    violations.append(f"FORBIDDEN_TAMPERED_CANONICAL_FN:{fn_nm_c}")
                    fixed_ok = False
                elif fn_nm_c == "_verifyPostCommitSettlement" and det_vc > 0:
                    m_vp_vc = _CANON_VAULT_LOOP_HEAD_RE.search(_WS_COLLAPSE_RE.sub("", fn_full_c))
                    if m_vp_vc is None or int(m_vp_vc.group(1)) != det_vc:
                        violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_verifyPostCommitSettlement")
                        fixed_ok = False
                elif fn_nm_c == "_assertConservationLiq":
                    m_widx = _CANON_WIDX_DECL_RE.search(_WS_COLLAPSE_RE.sub("", fn_b_c))
                    if m_widx is None:
                        violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_assertConservationLiq")
                        fixed_ok = False
                    else:
                        det_liq_widx = int(m_widx.group(1))
                if fixed_ok and fn_name_counts[fn_nm_c] == 1:
                    verified_fixed_canon_fns.add(fn_nm_c)
            elif fn_nm_c == "_assetTable":
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                at_pairs = [(int(m.group(1)), int(m.group(2))) for m in _SOL_ASSET_SLOT_PAIR_RE.finditer(b_cmp)]
                m_at_ret = _SOL_TABLE_RET_LEN_RE.search(fn_full_c)
                at_ret_len = int(m_at_ret.group(1)) if m_at_ret else (1 + len(at_pairs))
                if (
                    not _SOL_CANON_ASSET_TABLE_BODY_RE.fullmatch(b_cmp)
                    or at_pairs != [(i + 1, i) for i in range(len(at_pairs))]
                    or at_ret_len != (1 + len(at_pairs))
                    or (det_ac > 0 and det_ac != (1 + len(at_pairs)))
                    or (tok_const_map and (len(tok_const_map) != len(at_pairs) or any(i not in tok_const_map for i in range(len(at_pairs)))))
                ):
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_assetTable")
            elif fn_nm_c == "_vaultTable":
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                vt_pairs = [(int(m.group(1)), int(m.group(2))) for m in _SOL_VAULT_SLOT_PAIR_RE.finditer(b_cmp)]
                m_vt_ret = _SOL_TABLE_RET_LEN_RE.search(fn_full_c)
                vt_ret_len = int(m_vt_ret.group(1)) if m_vt_ret else len(vt_pairs)
                if (
                    not _SOL_CANON_VAULT_TABLE_BODY_RE.fullmatch(b_cmp)
                    or not vt_pairs
                    or [p[0] for p in vt_pairs] != list(range(len(vt_pairs)))
                    or len({p[1] for p in vt_pairs}) != len(vt_pairs)
                    or vt_ret_len != len(vt_pairs)
                    or (vault_const_map and any(p[1] not in vault_const_map for p in vt_pairs))
                ):
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_vaultTable")
            elif fn_nm_c in ("_snapshotBalances", "_snapshotSupplies"):
                is_bal_snap = fn_nm_c == "_snapshotBalances"
                pair_re = _SOL_SNAP_BAL_PAIR_RE if is_bal_snap else _SOL_SNAP_SUP_PAIR_RE
                body_re = _SOL_CANON_SNAP_BALS_BODY_RE if is_bal_snap else _SOL_CANON_SNAP_SUPPLIES_BODY_RE
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                snap_pairs = [(int(m.group(1)), int(m.group(2))) for m in pair_re.finditer(b_cmp)]
                if (
                    not body_re.fullmatch(b_cmp)
                    or snap_pairs != [(i + 1, i) for i in range(len(snap_pairs))]
                    or (det_tok_cnt >= 0 and len(snap_pairs) != det_tok_cnt)
                    or (det_ac > 0 and (1 + len(snap_pairs)) != det_ac)
                ):
                    violations.append(f"FORBIDDEN_TAMPERED_CANONICAL_FN:{fn_nm_c}")
            elif fn_nm_c == "_snapshotAllVaultBalances":
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                m_svh = _SOL_SNAP_VBAL_HEAD_RE.match(b_cmp)
                sv_pairs = [(int(m.group(1)), int(m.group(2)), int(m.group(3))) for m in _SOL_SNAP_VBAL_PAIR_RE.finditer(b_cmp)]
                if (
                    not _SOL_CANON_SNAP_VAULT_BALS_BODY_RE.fullmatch(b_cmp)
                    or m_svh is None
                    or int(m_svh.group(1)) != int(m_svh.group(2))
                    or int(m_svh.group(1)) <= 0
                    or (det_vc > 0 and int(m_svh.group(1)) != det_vc)
                    or sv_pairs != [(i + 1, i + 1, i) for i in range(len(sv_pairs))]
                    or (det_tok_cnt >= 0 and len(sv_pairs) != det_tok_cnt)
                    or (det_ac > 0 and (1 + len(sv_pairs)) != det_ac)
                ):
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_snapshotAllVaultBalances")
            elif fn_nm_c == "_hasResidualSpenderAllowance":
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                m_rsh = _SOL_RESIDUAL_ROUTER_HEAD_TAIL_RE.fullmatch(b_cmp)
                r_items = (
                    [(int(m.group(1)), _norm_addr(m.group(2))) for m in _SOL_RESIDUAL_ROUTER_ITEM_RE.finditer(m_rsh.group(2))]
                    if m_rsh is not None
                    else []
                )
                if (
                    not _SOL_CANON_RESIDUAL_SPENDER_BODY_RE.fullmatch(b_cmp)
                    or m_rsh is None
                    or int(m_rsh.group(1)) != int(m_rsh.group(3))
                    or int(m_rsh.group(1)) != len(r_items)
                    or [p[0] for p in r_items] != list(range(len(r_items)))
                    or not canon_router_norm_set.issubset({p[1] for p in r_items})
                ):
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_hasResidualSpenderAllowance")
            elif fn_nm_c == "_takeSnap":
                has_take_snap = True
                b_cmp = _WS_COLLAPSE_RE.sub("", fn_b_c)
                if not _SOL_CANON_TAKE_SNAP_BODY_RE.fullmatch(b_cmp):
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
                else:
                    m_sn_w = _SOL_TAKE_SNAP_WNATIVE_RE.search(b_cmp)
                    snap_w_tok_idx = int(m_sn_w.group(1)) if m_sn_w else None
            elif fn_nm_c == "_tryLiquidateGains":
                liq_bad = bool(_SOL_FORBIDDEN_LIQ_TOKEN_RE.search(fn_b_c))
                if not liq_bad and "liqCredit[" in fn_b_c:
                    if "_satAdd(" not in fn_b_c or "liqDebited[" not in fn_b_c:
                        liq_bad = True
                    else:
                        lc_matches = list(_SOL_LIQ_CREDIT_ASSIGN_RE.finditer(_SOL_QUOTED_STR_RE.sub('""', fn_b_c)))
                        if not lc_matches:
                            liq_bad = True
                        for m_lc in lc_matches:
                            lc_slot = _WS_COLLAPSE_RE.sub("", m_lc.group(1))
                            lc_op = m_lc.group(2)
                            lc_rhs = m_lc.group(3).strip()
                            if lc_op != "=" or _has_literal_boost(lc_rhs):
                                liq_bad = True
                                break
                            m_sat = _SOL_LIQ_CREDIT_SAFE_SATADD_RE.fullmatch(lc_rhs)
                            if (
                                m_sat is None
                                or _WS_COLLAPSE_RE.sub("", m_sat.group(1)) != lc_slot
                                or m_sat.group(2) in ("snapBefore", "snapMid")
                                or (m_sat.group(3) is not None and m_sat.group(3) in ("snapBefore", "snapMid"))
                            ):
                                liq_bad = True
                                break
                if liq_bad:
                    violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_tryLiquidateGains")
        elif _SOL_SHADOW_ZERO_CALLER_DECL_RE.search(_strip_quoted_strings_cached(fn_full_c)):
            violations.append(f"FORBIDDEN_SHADOW_ZERO_STATE_CALLER:{fn_nm_c}")

    norm_chain_w = _norm_chain(chain) if chain else ""
    exp_wnat_addr = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(norm_chain_w, "")) if norm_chain_w else ""
    if snap_w_tok_idx is not None:
        if tok_const_map:
            sn_addr = tok_const_map.get(snap_w_tok_idx, "")
            if (
                not sn_addr
                or sn_addr not in _ALL_WRAPPED_NATIVE_LOWER
                or (exp_wnat_addr and sn_addr != exp_wnat_addr)
            ):
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
        elif snap_w_tok_idx > 0:
            violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
    if det_liq_widx is not None:
        if det_liq_widx > 0:
            w_slot_zero = det_liq_widx - 1
            w_addr_c = tok_const_map.get(w_slot_zero, "") if tok_const_map else ""
            w_valid_tok = (
                (
                    w_slot_zero in tok_const_map
                    and w_addr_c in _ALL_WRAPPED_NATIVE_LOWER
                    and (not exp_wnat_addr or w_addr_c == exp_wnat_addr)
                )
                if tok_const_map
                else (det_tok_cnt < 0 or det_liq_widx <= det_tok_cnt)
            )
            if not w_valid_tok:
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_assertConservationLiq")
            if has_take_snap and snap_w_tok_idx != w_slot_zero:
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_assertConservationLiq")
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
        else:
            if snap_w_tok_idx is not None:
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
            elif exp_wnat_addr and tok_const_map and exp_wnat_addr in tok_const_map.values():
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_assertConservationLiq")
                violations.append("FORBIDDEN_TAMPERED_CANONICAL_FN:_takeSnap")
    # modifier 본문은 `function` 시그니처 정규식에 잡히지 않으므로, 테스트 하네스 내 modifier 선언(사전·사후 상태 변조 및 보존 이벤트 은닉)을 전면 금지한다.
    if "modifier" in harness_scope_src:
        for mod_m in _SOL_MODIFIER_SIG_BRACE_RE.finditer(_strip_quoted_strings_cached(harness_scope_src)):
            violations.append(f"FORBIDDEN_MODIFIER_IN_HARNESS:{mod_m.group(1)}")
    conserv_helpers: Set[str] = {
        fn_nm
        for fn_nm, fn_b in fn_list
        if fn_nm not in _CANONICAL_HARNESS_FN_NAMES
        and not fn_nm.startswith("test")
        and (_SOL_EMIT_CG_RE.search(fn_b) is not None or _SOL_ASSERT_OR_EMIT_CALL_RE.search(fn_b) is not None)
    }
    changed_h = True
    while changed_h and conserv_helpers:
        changed_h = False
        h_pat = _compiled_sol_fn_call_alt_re(tuple(sorted(conserv_helpers)))
        for fn_nm, fn_b in fn_list:
            if (
                fn_nm not in _CANONICAL_HARNESS_FN_NAMES
                and fn_nm not in conserv_helpers
                and not fn_nm.startswith("test")
                and h_pat.search(fn_b) is not None
            ):
                conserv_helpers.add(fn_nm)
                changed_h = True
    h_call_pat = _compiled_sol_fn_call_alt_re(tuple(sorted(conserv_helpers))) if conserv_helpers else None

    for fn_nm, fn_b in fn_list:
        if fn_nm in _CANONICAL_HARNESS_FN_NAMES:
            if fn_nm in ("_verifyPostCommitSettlement", "_bridgeLiquidatedGain", "_bridgeLiquidatedNftGain", "_bridgeAtomicTargetExit") and _SOL_EMIT_CG_RE.search(fn_b):
                violations.append(f"FORBIDDEN_DIRECT_EMIT_IN_CANONICAL_HELPER:{fn_nm}")
            continue
        direct_assert_calls = len(_SOL_ASSERT_OR_EMIT_CALL_RE.findall(fn_b))
        helper_assert_calls = len(h_call_pat.findall(fn_b)) if h_call_pat is not None else 0
        if (direct_assert_calls + helper_assert_calls) > 1:
            violations.append(f"FORBIDDEN_MULTI_CONSERVATION_CALL:{fn_nm}")
        for lp_b in _extract_sol_loop_bodies(fn_b):
            if (
                _SOL_EMIT_CG_RE.search(lp_b) is not None
                or _SOL_ASSERT_OR_EMIT_CALL_RE.search(lp_b) is not None
                or (h_call_pat is not None and h_call_pat.search(lp_b) is not None)
            ):
                violations.append(f"FORBIDDEN_LOOP_CONSERVATION_EMISSION:{fn_nm}")
                break
        emitted_assets_in_fn: Set[str] = set()
        for m_fn_cg in _SOL_EMIT_CG_RE.finditer(_strip_quoted_strings_cached(fn_b)):
            parts_cg = _split_top_level_csv(m_fn_cg.group(1), open_chars="(", close_chars=")", strict=False)
            if len(parts_cg) == 5:
                asset_key = _WS_COLLAPSE_RE.sub("", parts_cg[1]).lower()
                if asset_key in emitted_assets_in_fn:
                    violations.append(f"FORBIDDEN_DUPLICATE_ASSET_CONSERVATION_EMIT:{fn_nm}:{asset_key[:24]}")
                    break
                emitted_assets_in_fn.add(asset_key)

    # Build non-canonical code scope by removing verified fixed-body canonical helpers
    # from harness_scope_src so legitimate canonical helpers pass untouched while top-level
    # constants, Yul `:=`, tuple destructuring, and multi-hop fake variables are blocked.
    non_canon_src = harness_scope_src
    non_canon_user_src = harness_scope_src
    non_canon_fn_bodies: Dict[str, List[str]] = {}
    if fn_entries:
        for fn_nm_nc, fn_b_nc, fn_full_nc in fn_entries:
            if fn_nm_nc in verified_fixed_canon_fns and fn_full_nc:
                non_canon_src = non_canon_src.replace(fn_full_nc, " ", 1)
            if fn_nm_nc in _CANONICAL_ALL_PROTECTED_FNS and fn_full_nc:
                non_canon_user_src = non_canon_user_src.replace(fn_full_nc, " ", 1)
            if fn_nm_nc not in _CANONICAL_ALL_PROTECTED_FNS:
                fn_b_ns = _strip_quoted_strings_cached(fn_b_nc)
                non_canon_fn_bodies.setdefault(fn_nm_nc, []).append(fn_b_ns)
                brace_pos = fn_full_nc.find("{")
                if brace_pos > 0 and ("ConservationSnap" in fn_full_nc[:brace_pos] or "NftSnap" in fn_full_nc[:brace_pos]):
                    violations.append(f"FORBIDDEN_NON_CANON_SNAP_FN:{fn_nm_nc}")
                m_ac_fn = _SOL_ASSERT_CONS_CALL_RE.search(fn_b_ns)
                if m_ac_fn is not None:
                    snap_hits = list(_SOL_TAKE_SNAP_CALL_RE.finditer(fn_b_ns[: m_ac_fn.start()]))
                    if snap_hits and _SOL_ASM_KW_RE.search(fn_b_ns[snap_hits[-1].end() : m_ac_fn.start()]):
                        violations.append(f"FORBIDDEN_POST_SNAP_ASSEMBLY:{fn_nm_nc}")

    if _SOL_GAS_SCALE_TAMPER_RE.search(non_canon_src):
        violations.append("FORBIDDEN_GAS_SCALING_TAMPER")

    _allowed_member_calls = frozenset({
        "balanceOf", "totalSupply", "allowance", "decimals",
        "encode", "encodePacked", "encodeWithSelector", "encodeWithSignature", "encodeCall", "decode",
    })

    # 문자열 리터럴 내부 `;`·`=`·`:=`·`++`로 인한 대입 RHS 절단 우회를 차단한 뒤 단일 O(N) 색인 구축
    non_canon_no_str = _strip_quoted_strings_cached(non_canon_src)
    user_no_str = _strip_quoted_strings_cached(non_canon_user_src)
    yul_assigned_idents: Set[str] = (
        set(_SOL_ALL_YUL_ASSIGN_RE.findall(non_canon_no_str)) if ":=" in non_canon_no_str else set()
    )
    def _collect_tuple_lhs_idents(s_src: str) -> Set[str]:
        if "=" not in s_src or "(" not in s_src:
            return set()
        return {t for m_tp in _SOL_ALL_TUPLE_LHS_RE.finditer(s_src) for t in _SOL_IDENT_TOKEN_RE.findall(m_tp.group(1))}

    tuple_assigned_idents: Set[str] = _collect_tuple_lhs_idents(non_canon_no_str)
    incdec_idents: Set[str] = (
        {g1 or g2 for g1, g2 in _SOL_ALL_INCDEC_RE.findall(non_canon_no_str)}
        if ("++" in non_canon_no_str or "--" in non_canon_no_str)
        else set()
    )
    assigns_by_ident_non_canon = _index_sol_assignments(non_canon_no_str)
    assigns_by_ident_clean: Dict[str, List[Tuple[str, str]]] = assigns_by_ident_non_canon
    canonical_cg_rhs: Set[str] = set()
    canonical_vl_rhs: Set[str] = set()

    # ConservationSnap / liqCredit / liqDebited 직접 변조·생성자 위조·assembly mstore 우회 차단
    if _SOL_SNAP_FIELD_WRITE_RE.search(user_no_str):
        violations.append("FORBIDDEN_CONSERVATION_SNAP_MUTATION")
    if _SOL_LIQ_ARR_WRITE_RE.search(user_no_str):
        violations.append("FORBIDDEN_LIQ_ARRAY_MUTATION")
    if _SOL_SNAP_CTOR_RE.search(user_no_str):
        violations.append("FORBIDDEN_FORGED_CONSERVATION_SNAP")
    has_canon_assert_fn = (
        "_assertConservationLiq" in verified_fixed_canon_fns
        or "_assertConservation" in verified_fixed_canon_fns
    )
    if _SOL_DIRECT_USER_CONSERVATION_EMIT_RE.search(user_no_str) or (
        has_canon_assert_fn and _SOL_EMIT_CG_RE.search(user_no_str) is not None
    ):
        violations.append("FORBIDDEN_DIRECT_CONSERVATION_EVENT_EMISSION")
    user_assigns = (
        assigns_by_ident_non_canon
        if user_no_str == non_canon_no_str
        else _index_sol_assignments(user_no_str)
    )
    user_indexed_writes: Set[str] = set(_SOL_INDEXED_WRITE_IDENT_RE.findall(user_no_str))
    user_snap_vars: Set[str] = set(_SOL_SNAP_DECL_RE.findall(user_no_str))
    verified_snap_vars: Set[str] = set()
    verified_snap_vars_by_fn: Dict[int, Set[str]] = {}
    user_nft_snap_vars: Set[str] = set(_SOL_NFT_SNAP_DECL_RE.findall(user_no_str))
    verified_nft_snap_vars: Set[str] = set()
    verified_nft_snap_vars_by_fn: Dict[int, Set[str]] = {}
    if file_level_src:
        for fl_nm_nc, fl_b_nc, _ in _extract_sol_fn_entries(file_level_src):
            if fl_nm_nc not in _CANONICAL_ALL_PROTECTED_FNS:
                non_canon_fn_bodies.setdefault(fl_nm_nc, []).append(_strip_quoted_strings_cached(fl_b_nc))
    # Top-level (state variable) ConservationSnap / NftSnap declarations outside functions are forbidden.
    top_outside_fn_src = non_canon_user_src
    for _, _, fn_full_top in fn_entries:
        if fn_full_top:
            top_outside_fn_src = top_outside_fn_src.replace(fn_full_top, " ", 1)
    top_outside_fn_src = _strip_quoted_strings_cached(top_outside_fn_src)
    for sv_top in _SOL_SNAP_DECL_RE.findall(top_outside_fn_src):
        violations.append(f"FORBIDDEN_TAMPERED_SNAP_INIT:{sv_top}")
    for nv_top in _SOL_NFT_SNAP_DECL_RE.findall(top_outside_fn_src):
        violations.append(f"FORBIDDEN_TAMPERED_NFT_SNAP_INIT:{nv_top}")
    for fn_bodies_sv in non_canon_fn_bodies.values():
        for fn_b_sv in fn_bodies_sv:
            fn_sv_decls = list(dict.fromkeys(_SOL_SNAP_DECL_RE.findall(fn_b_sv)))
            fn_nv_decls = list(dict.fromkeys(_SOL_NFT_SNAP_DECL_RE.findall(fn_b_sv)))
            if not fn_sv_decls and not fn_nv_decls:
                continue
            fn_as_sv = _index_sol_assignments(fn_b_sv)
            fn_tup_sv = _collect_tuple_lhs_idents(fn_b_sv)
            fn_yul_sv = set(_SOL_ALL_YUL_ASSIGN_RE.findall(fn_b_sv)) if ":=" in fn_b_sv else set()
            ok_sv_local: Set[str] = set()
            for sv_nm in fn_sv_decls:
                sv_pairs = fn_as_sv.get(sv_nm, ())
                sv_valid = False
                if len(sv_pairs) == 1 and sv_pairs[0][0] == "=":
                    sv_rhs = sv_pairs[0][1].strip()
                    if sv_rhs.startswith("_takeSnap(") and sv_rhs.endswith(")"):
                        sv_arg = _unwrap_sol_addr_expr(sv_rhs[len("_takeSnap(") : -1].strip())
                        if sv_arg == "ZERO_STATE_CALLER":
                            sv_valid = True
                        elif _SOL_FULL_HEX_ADDR_RE.fullmatch(sv_arg):
                            sv_norm = f"0x{int(sv_arg, 16):040x}"
                            sv_valid = (sv_norm not in forb_const_addrs) and (not norm_allowed_caller or sv_norm == norm_allowed_caller)
                if not sv_valid or sv_nm in fn_tup_sv or sv_nm in fn_yul_sv:
                    violations.append(f"FORBIDDEN_TAMPERED_SNAP_INIT:{sv_nm}")
                else:
                    ok_sv_local.add(sv_nm)
                    verified_snap_vars.add(sv_nm)
            verified_snap_vars_by_fn[id(fn_b_sv)] = ok_sv_local
            ok_nv_local: Set[str] = set()
            for nv_nm in fn_nv_decls:
                nv_pairs = fn_as_sv.get(nv_nm, ())
                nv_valid = (
                    len(nv_pairs) == 1
                    and nv_pairs[0][0] == "="
                    and nv_pairs[0][1].strip().startswith("_takeNftSnap(")
                    and nv_pairs[0][1].strip().endswith(")")
                    and nv_nm not in fn_tup_sv
                    and nv_nm not in fn_yul_sv
                )
                if not nv_valid:
                    violations.append(f"FORBIDDEN_TAMPERED_NFT_SNAP_INIT:{nv_nm}")
                else:
                    ok_nv_local.add(nv_nm)
                    verified_nft_snap_vars.add(nv_nm)
            verified_nft_snap_vars_by_fn[id(fn_b_sv)] = ok_nv_local
    _non_action_bare_kw = frozenset({
        "if", "for", "while", "catch", "return", "require", "assert", "revert", "emit",
        "gasleft", "address", "payable", "type", "keccak256", "sha256", "ripemd160",
    })
    _clean_no_str_ro = _strip_quoted_strings_cached(clean)
    _castable_types_ro: Set[str] = set()
    _ro_fn_cands: Set[str] = set()
    _mut_fn_names: Set[str] = set()
    _ro_scan_blocks: List[str] = [_strip_quoted_strings_cached(file_level_src)] if file_level_src else []
    _pos_td_ro = 0
    for _m_td_ro in _SOL_TOP_DECL_NAMED_RE.finditer(_clean_no_str_ro):
        if _m_td_ro.start() < _pos_td_ro:
            continue
        _td_nm = _m_td_ro.group(1)
        _td_end = _scan_matched_delim(_clean_no_str_ro, _m_td_ro.end() - 1, "{", "}")
        if _td_end <= _m_td_ro.end() - 1:
            continue
        _pos_td_ro = _td_end + 1
        _td_body = _clean_no_str_ro[_m_td_ro.end() : _td_end]
        _is_vm_like = (_td_nm == "Vm") or (
            "interface" in _m_td_ro.group(0) and _SOL_VM_CHEAT_DECL_RE.search(_td_body) is not None
        )
        if _is_vm_like:
            continue
        _castable_types_ro.add(_td_nm)
        _ro_scan_blocks.append(_td_body)
    for _blk_ro in _ro_scan_blocks:
        for _m_fn_ro in _SOL_FN_SIG_HEAD_RE.finditer(_blk_ro):
            _fn_ro_nm = _m_fn_ro.group(1)
            _fn_ro_cp = _scan_matched_delim(_blk_ro, _m_fn_ro.end() - 1, "(", ")")
            if _fn_ro_cp <= _m_fn_ro.end() - 1:
                continue
            _rest_ro = _blk_ro[_fn_ro_cp + 1 :]
            _m_term_ro = _SOL_FN_HDR_TERM_RE.search(_rest_ro)
            _hdr_ro = _rest_ro[: _m_term_ro.start()] if _m_term_ro else _rest_ro
            _hdr_pre_ret = _SOL_RETURNS_KW_RE.split(_hdr_ro, maxsplit=1)[0]
            _hdr_words = set(_SOL_IDENT_WORD_RE.findall(_hdr_pre_ret))
            if "view" in _hdr_words or "pure" in _hdr_words:
                _ro_fn_cands.add(_fn_ro_nm)
            else:
                _mut_fn_names.add(_fn_ro_nm)
    _unambiguous_ro_fns: FrozenSet[str] = frozenset(_ro_fn_cands - _mut_fn_names)
    _castable_types_ro -= (_ro_fn_cands | _mut_fn_names)

    def _has_action_call(seg: str) -> bool:
        if not seg:
            return False
        if _SOL_NEW_KW_RE.search(seg):
            return True
        if "{" in seg:
            for m_co in _SOL_CALL_OPTS_RE.finditer(seg):
                co_q = m_co.group("qual")
                co_fn = m_co.group("fn")
                co_opts = m_co.group("opts") or ""
                if (
                    co_q == "vm"
                    or co_fn not in _unambiguous_ro_fns
                    or _SOL_VALUE_OPT_KEY_RE.search(co_opts) is not None
                ):
                    return True
        for m_ac_h in _SOL_HELPER_CALL_HEAD_RE.finditer(seg):
            q_h = m_ac_h.group("qual")
            f_h = m_ac_h.group("fn")
            if q_h is not None:
                if (
                    q_h == "abi"
                    or f_h == "staticcall"
                    or (q_h in ("bytes", "string") and f_h == "concat")
                    or (q_h == "vm" and f_h in ("stopPrank", "recordLogs", "assume"))
                    or (q_h != "vm" and f_h in _unambiguous_ro_fns)
                ):
                    continue
                return True
            if (
                f_h not in _CANONICAL_ALL_PROTECTED_FNS
                and f_h not in _non_action_bare_kw
                and f_h not in _unambiguous_ro_fns
                and f_h not in _castable_types_ro
                and _SOL_PRIM_TYPE_RE.fullmatch(f_h) is None
            ):
                return True
        return False

    for fn_nm_so, fn_bodies_so in non_canon_fn_bodies.items():
        for fn_b_so in fn_bodies_so:
            if (
                "_assertConservation" not in fn_b_so
                and "_tryLiquidateGains" not in fn_b_so
                and "_bridgeLiquidatedGain" not in fn_b_so
                and "_bridgeLiquidatedNftGain" not in fn_b_so
                and "_bridgeAtomicTargetExit" not in fn_b_so
            ):
                continue
            fn_ns_so = _strip_quoted_strings_cached(fn_b_so)
            local_snap_pos: Dict[str, Tuple[int, int]] = {}
            for m_sd in _SOL_SNAP_DECL_RE.finditer(fn_ns_so):
                sv_l = m_sd.group(1)
                if sv_l in local_snap_pos:
                    violations.append(f"FORBIDDEN_DUPLICATE_SNAP_DECL:{fn_nm_so}:{sv_l}")
                else:
                    s_end_sd = fn_ns_so.find(";", m_sd.end())
                    local_snap_pos[sv_l] = (m_sd.start(), (s_end_sd + 1) if s_end_sd >= 0 else m_sd.end())
            local_nft_snap_pos: Dict[str, Tuple[int, int]] = {}
            for m_nd in _SOL_NFT_SNAP_DECL_RE.finditer(fn_ns_so):
                nv_l = m_nd.group(1)
                if nv_l in local_nft_snap_pos:
                    violations.append(f"FORBIDDEN_DUPLICATE_NFT_SNAP_DECL:{fn_nm_so}:{nv_l}")
                else:
                    s_end_nd = fn_ns_so.find(";", m_nd.end())
                    local_nft_snap_pos[nv_l] = (m_nd.start(), (s_end_nd + 1) if s_end_nd >= 0 else m_nd.end())
            tryliq_lhs_by_call: Dict[int, Tuple[str, str]] = {}
            for m_tl_l in _SOL_CANON_TRY_LIQ_TUPLE_RE.finditer(fn_ns_so):
                call_idx_tl = fn_ns_so.find("_tryLiquidateGains", m_tl_l.start())
                if call_idx_tl >= 0:
                    tryliq_lhs_by_call[call_idx_tl] = (m_tl_l.group(2), m_tl_l.group(4))
            tryliq_calls_fn: List[Tuple[int, int, str, str, str, str]] = []
            bridge_calls_fn: List[Tuple[str, int, int, str, str, List[str]]] = []
            assert_calls_fn: List[Tuple[str, int, int, str, str, List[str]]] = []
            for m_sc in _SOL_CANON_SNAP_CALL_HEAD_RE.finditer(fn_ns_so):
                sc_close = _scan_matched_delim(fn_ns_so, m_sc.end() - 1, "(", ")")
                if sc_close <= m_sc.end() - 1:
                    continue
                sc_head = m_sc.group(0).split("(", 1)[0].strip()
                sc_args = _split_top_level_csv(
                    fn_ns_so[m_sc.end() : sc_close], open_chars="([", close_chars=")]", strict=False
                )
                if sc_head in ("_assertConservationLiq", "_assertConservation"):
                    if len(sc_args) < 3:
                        continue
                    s_first, s_second = sc_args[1].strip(), sc_args[2].strip()
                    assert_calls_fn.append((sc_head, m_sc.start(), sc_close + 1, s_first, s_second, sc_args))
                else:
                    if len(sc_args) < 2:
                        continue
                    s_first, s_second = sc_args[0].strip(), sc_args[1].strip()
                    if sc_head == "_tryLiquidateGains":
                        tl_lc, tl_ld = tryliq_lhs_by_call.get(m_sc.start(), ("", ""))
                        tryliq_calls_fn.append((m_sc.start(), sc_close + 1, s_first, s_second, tl_lc, tl_ld))
                    elif sc_head in ("_bridgeLiquidatedGain", "_bridgeLiquidatedNftGain", "_bridgeAtomicTargetExit"):
                        bridge_calls_fn.append((sc_head, m_sc.start(), sc_close + 1, s_first, s_second, sc_args))
                        if sc_head == "_bridgeLiquidatedNftGain":
                            if len(sc_args) != 8:
                                violations.append(f"FORBIDDEN_MALFORMED_NFT_BRIDGE_CALL:{fn_nm_so}")
                            else:
                                n1_a, n2_a = sc_args[2].strip(), sc_args[3].strip()
                                ok_nv_l = verified_nft_snap_vars_by_fn.get(id(fn_b_so), set())
                                pn1 = local_nft_snap_pos.get(n1_a, (-1, -1))[0]
                                pn2 = local_nft_snap_pos.get(n2_a, (-1, -1))[0]
                                if pn1 < 0 or pn2 < 0 or not (pn1 < pn2 < m_sc.start()) or n1_a not in ok_nv_l or n2_a not in ok_nv_l:
                                    violations.append(f"FORBIDDEN_REVERSED_NFT_SNAP_ORDER:{fn_nm_so}")
                        elif sc_head == "_bridgeAtomicTargetExit" and len(sc_args) != 10:
                            violations.append(f"FORBIDDEN_MALFORMED_ATOMIC_EXIT_CALL:{fn_nm_so}")
                p1 = local_snap_pos.get(s_first, (-1, -1))[0]
                p2 = local_snap_pos.get(s_second, (-1, -1))[0]
                if p1 < 0 or p2 < 0 or not (p1 < p2 < m_sc.start()):
                    violations.append(f"FORBIDDEN_REVERSED_SNAP_ORDER:{fn_nm_so}:{sc_head}")
            if len(tryliq_calls_fn) > 1:
                violations.append(f"FORBIDDEN_MULTIPLE_TRY_LIQ_CALLS:{fn_nm_so}")
            if (tryliq_calls_fn or bridge_calls_fn) and not any(ac[0] == "_assertConservationLiq" for ac in assert_calls_fn):
                violations.append(f"FORBIDDEN_UNBOUND_LIQ_CALL:{fn_nm_so}")
            last_liq_end = max([c[1] for c in tryliq_calls_fn] + [c[2] for c in bridge_calls_fn], default=-1)
            local_assign_spans: Dict[str, List[Tuple[str, str, int, int]]] = {}
            if assert_calls_fn:
                for m_la in _SOL_ALL_ASSIGN_HEAD_RE.finditer(fn_ns_so):
                    s_end_la = fn_ns_so.find(";", m_la.end())
                    if s_end_la >= 0:
                        local_assign_spans.setdefault(m_la.group(1), []).append(
                            (m_la.group(2), fn_ns_so[m_la.end() : s_end_la].strip(), m_la.start(), s_end_la + 1)
                        )
            for sc_head, ac_s, _ac_e, s_b, s_a, ac_args in assert_calls_fn:
                pb_s, pb_e = local_snap_pos.get(s_b, (-1, -1))
                pa_s, _pa_e = local_snap_pos.get(s_a, (-1, -1))
                if pb_s < 0 or pa_s < 0:
                    continue
                if _has_action_call(fn_ns_so[:pb_s]):
                    violations.append(f"FORBIDDEN_ACTION_BEFORE_SNAP_BEFORE:{fn_nm_so}")
                if last_liq_end >= 0:
                    if pa_s <= last_liq_end:
                        violations.append(f"FORBIDDEN_SNAP_AFTER_BEFORE_LIQ:{fn_nm_so}")
                    for _, _, tl_b, _tl_m, tl_lc, tl_ld in tryliq_calls_fn:
                        if tl_b != s_b:
                            violations.append(f"FORBIDDEN_LIQ_SNAP_MISMATCH:{fn_nm_so}")
                        if sc_head == "_assertConservationLiq" and len(ac_args) >= 5 and tl_lc and tl_ld:
                            if (ac_args[3].strip(), ac_args[4].strip()) != (tl_lc, tl_ld):
                                violations.append(f"FORBIDDEN_LIQ_VAR_MISMATCH:{fn_nm_so}")
                    for br_head, _, _, br_b, _br_m, br_args in bridge_calls_fn:
                        if br_b != s_b:
                            violations.append(f"FORBIDDEN_LIQ_SNAP_MISMATCH:{fn_nm_so}")
                        if sc_head == "_assertConservationLiq" and len(ac_args) >= 5 and len(br_args) >= 8:
                            lc_pos, ld_pos = (4, 5) if br_head == "_bridgeLiquidatedNftGain" else (2, 3)
                            if (br_args[lc_pos].strip(), br_args[ld_pos].strip()) != (ac_args[3].strip(), ac_args[4].strip()):
                                violations.append(f"FORBIDDEN_LIQ_VAR_MISMATCH:{fn_nm_so}")
                gas_idx_l = 5 if sc_head == "_assertConservationLiq" else 3
                if len(ac_args) <= gas_idx_l:
                    continue
                gas_arg_l = ac_args[gas_idx_l].strip()
                if _SOL_SIMPLE_IDENT_RE.fullmatch(gas_arg_l) is not None:
                    g_entries = local_assign_spans.get(gas_arg_l, ())
                    eq_entries = [e for e in g_entries if e[0] == "="]
                    if len(eq_entries) > 1:
                        violations.append(f"FORBIDDEN_GAS_ORDER_TAMPER:{fn_nm_so}")
                        continue
                    if not eq_entries:
                        continue
                    _, g_rhs0, ge_s, ge_e = eq_entries[0]
                    gs_refs = [r for r in _SOL_GAS_SUB_LHS_RE.findall(g_rhs0) if r != gas_arg_l]
                    gs_starts = [
                        e_gs[2]
                        for r_gs in gs_refs
                        for e_gs in local_assign_spans.get(r_gs, ())
                        if e_gs[0] == "="
                    ]
                    if not gs_starts or min(gs_starts) >= ge_s or ge_e > ac_s:
                        violations.append(f"FORBIDDEN_GAS_ORDER_TAMPER:{fn_nm_so}")
                        continue
                    p_gs_s = min(gs_starts)
                    if p_gs_s > pb_e and _has_action_call(fn_ns_so[pb_e:p_gs_s]):
                        violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
                    p_lgs_for_nft: int = -1
                    if ge_e < pa_s:
                        add_entries = [e for e in g_entries if e[0] == "+=" and ge_e <= e[2] < ac_s]
                        if not add_entries:
                            if _has_action_call(fn_ns_so[ge_e:pa_s]):
                                violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
                        else:
                            _, l_rhs_add, gadd_s, gadd_e = add_entries[0]
                            if _SOL_SIMPLE_IDENT_RE.fullmatch(l_rhs_add) is not None:
                                lgu_eqs = [e for e in local_assign_spans.get(l_rhs_add, ()) if e[0] == "=" and ge_e <= e[2] < gadd_s]
                                if not lgu_eqs:
                                    violations.append(f"FORBIDDEN_GAS_ORDER_TAMPER:{fn_nm_so}")
                                    continue
                                _, lgu_rhs, lgu_s, lgu_e = lgu_eqs[0]
                            else:
                                lgu_rhs, lgu_s, lgu_e = l_rhs_add, gadd_s, gadd_e
                            lgs_refs = [r for r in _SOL_GAS_SUB_LHS_RE.findall(lgu_rhs) if r != l_rhs_add]
                            lgs_spans = [
                                (e_lg[2], e_lg[3])
                                for r_lg in lgs_refs
                                for e_lg in local_assign_spans.get(r_lg, ())
                                if e_lg[0] == "=" and ge_e <= e_lg[2] < lgu_s
                            ]
                            if not lgs_spans:
                                violations.append(f"FORBIDDEN_GAS_ORDER_TAMPER:{fn_nm_so}")
                                continue
                            p_lgs_s, p_lgs_e = min(lgs_spans, key=lambda sp: sp[0])
                            p_lgs_for_nft = p_lgs_s
                            if _has_action_call(fn_ns_so[ge_e:p_lgs_s]):
                                violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
                            elif _has_action_call(fn_ns_so[p_lgs_e:lgu_s]):
                                has_real_bridge = any(
                                    br_h in ("_bridgeLiquidatedGain", "_bridgeLiquidatedNftGain")
                                    and p_lgs_e <= br_s and br_e <= lgu_s and len(br_args) >= 8 and br_args[7].strip() not in ("0", "0x0")
                                    for br_h, br_s, br_e, _, _, br_args in bridge_calls_fn
                                )
                                gas_add_uncond = gadd_s >= lgu_e and _SOL_COND_GATE_RE.search(fn_ns_so[lgu_e:gadd_s]) is None
                                if not has_real_bridge or not gas_add_uncond:
                                    violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
                            if lgu_e < pa_s and _has_action_call(fn_ns_so[lgu_e:pa_s]):
                                violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
                    for br_head, br_s, _br_e, _, _, br_args in bridge_calls_fn:
                        if br_head == "_bridgeLiquidatedNftGain" and len(br_args) == 8:
                            pn1_s = local_nft_snap_pos.get(br_args[2].strip(), (-1, -1))[0]
                            pn2_s = local_nft_snap_pos.get(br_args[3].strip(), (-1, -1))[0]
                            nft_mid_upper = p_lgs_for_nft if p_lgs_for_nft >= 0 else br_s
                            if not (0 <= pn1_s < p_gs_s and ge_e <= pn2_s < nft_mid_upper):
                                violations.append(f"FORBIDDEN_NFT_SNAP_OUTSIDE_PHASE:{fn_nm_so}")
                else:
                    gs_refs = _SOL_GAS_SUB_LHS_RE.findall(gas_arg_l)
                    gs_starts = [
                        e_gs[2]
                        for r_gs in gs_refs
                        for e_gs in local_assign_spans.get(r_gs, ())
                        if e_gs[0] == "="
                    ]
                    if gs_starts and min(gs_starts) > pb_e and _has_action_call(fn_ns_so[pb_e : min(gs_starts)]):
                        violations.append(f"FORBIDDEN_ACTION_OUTSIDE_GAS_WINDOW:{fn_nm_so}")
    if has_canon_assert_fn or "_assertConservation" in user_no_str:
        for fn_nm_t, fn_bodies_t in non_canon_fn_bodies.items():
            if fn_nm_t.startswith("test") and any("_assertConservation" not in fb_t for fb_t in fn_bodies_t):
                violations.append(f"FORBIDDEN_UNASSERTED_TEST_FN:{fn_nm_t}")

    def _is_valid_gas_rhs(expr_s: str, *, allow_simple_ident: bool = False) -> bool:
        e = expr_s.strip()
        if not e or _SOL_CG_LITERAL_EXPR_RE.fullmatch(e) is not None or _SOL_GAS_EXPR_DOWNSCALE_RE.search(e) is not None:
            return False
        if any(
            fn_c != "gasleft" and _SOL_GAS_UINT_CAST_RE.fullmatch(fn_c) is None
            for fn_c in _SOL_GAS_CALL_IDENT_RE.findall(e)
        ):
            return False
        if "?" in e:
            cond_g, rest_g = e.split("?", 1)
            if ":" not in rest_g or "?" in rest_g:
                return False
            t_br, f_br = rest_g.split(":", 1)
            if ":" in f_br or _SOL_GAS_TERNARY_LIT_CMP_RE.search(cond_g) is not None:
                return False
            if ">" in cond_g and "<" not in cond_g:
                return t_br.count("-") == 1
            if "<" in cond_g and ">" not in cond_g:
                return f_br.count("-") == 1
            return False
        if allow_simple_ident and _SOL_SIMPLE_IDENT_RE.fullmatch(e) is not None:
            return True
        return e.count("-") == 1

    def _strip_canon_try_liq_tuples(src_s: str) -> str:
        if "_tryLiquidateGains" not in src_s or fn_name_counts.get("_tryLiquidateGains", 0) != 1:
            return src_s

        def _repl_tl(m_tl: re.Match[str]) -> str:
            ac1, cid1, ac2, cid2, s1_a, s2_a = m_tl.groups()
            if (
                ac1 == ac2
                and (det_ac <= 0 or int(ac1) == det_ac)
                and cid1 != cid2
                and s1_a in verified_snap_vars
                and s2_a in verified_snap_vars
                and s1_a != s2_a
            ):
                return ";"
            return m_tl.group(0)

        return _SOL_CANON_TRY_LIQ_TUPLE_RE.sub(_repl_tl, src_s)

    user_no_canon_tryliq = _strip_canon_try_liq_tuples(user_no_str)
    liq_tuple_assigned_idents: Set[str] = (
        _collect_tuple_lhs_idents(_strip_canon_try_liq_tuples(non_canon_no_str))
        if user_no_canon_tryliq != user_no_str
        else tuple_assigned_idents
    )

    user_liq_arg_vars: Set[str] = set()
    all_gas_start_refs: Set[str] = set()
    for m_ac in _SOL_ASSERT_CONS_CALL_RE.finditer(user_no_str):
        is_liq_call = m_ac.group(1) == "_assertConservationLiq"
        ac_close = _scan_matched_delim(user_no_str, m_ac.end() - 1, "(", ")")
        if ac_close <= m_ac.end() - 1:
            violations.append("FORBIDDEN_MALFORMED_CONSERVATION_CALL")
            continue
        ac_args = _split_top_level_csv(user_no_str[m_ac.end() : ac_close], open_chars="([", close_chars=")]", strict=False)
        exp_arity = 6 if is_liq_call else 4
        if len(ac_args) != exp_arity:
            violations.append("FORBIDDEN_MALFORMED_CONSERVATION_CALL")
            continue
        b_snap_arg, a_snap_arg = ac_args[1].strip(), ac_args[2].strip()
        if b_snap_arg not in verified_snap_vars or a_snap_arg not in verified_snap_vars or b_snap_arg == a_snap_arg:
            violations.append("FORBIDDEN_UNVERIFIED_SNAP_ARG")
        if is_liq_call:
            for la_raw in (ac_args[3].strip(), ac_args[4].strip()):
                if (
                    _SOL_SIMPLE_IDENT_RE.fullmatch(la_raw) is None
                    or la_raw in user_assigns
                    or la_raw in user_indexed_writes
                    or la_raw in liq_tuple_assigned_idents
                    or la_raw in yul_assigned_idents
                ):
                    violations.append(f"FORBIDDEN_LIQ_ARRAY_MUTATION:{la_raw[:24]}")
                else:
                    user_liq_arg_vars.add(la_raw)
        gas_arg = ac_args[5 if is_liq_call else 3].strip()
        all_gas_start_refs.update(("gasStart", "liqGasStart"))
        if _SOL_SIMPLE_IDENT_RE.fullmatch(gas_arg) is not None:
            g_pairs = user_assigns.get(gas_arg, ())
            gas_ok = bool(
                g_pairs
                and gas_arg not in tuple_assigned_idents
                and gas_arg not in yul_assigned_idents
                and any(("gasleft" in g_rhs or "gasStart" in g_rhs or "gasUsed" in g_rhs) for _, g_rhs in g_pairs)
            )
            if gas_ok:
                for g_op, g_rhs in g_pairs:
                    g_rhs_s = g_rhs.strip()
                    if g_op not in ("=", "+=") or not _is_valid_gas_rhs(g_rhs_s, allow_simple_ident=(g_op == "+=")):
                        gas_ok = False
                        break
                    all_gas_start_refs.update(_SOL_GAS_SUB_LHS_RE.findall(g_rhs_s))
                    if g_op == "+=" and _SOL_SIMPLE_IDENT_RE.fullmatch(g_rhs_s) is not None:
                        sub_gp = user_assigns.get(g_rhs_s, ())
                        if not sub_gp or any(
                            so not in ("=", "+=") or not _is_valid_gas_rhs(sr, allow_simple_ident=(so == "+="))
                            for so, sr in sub_gp
                        ):
                            gas_ok = False
                            break
                        for _, sr in sub_gp:
                            all_gas_start_refs.update(_SOL_GAS_SUB_LHS_RE.findall(sr))
            if not gas_ok:
                violations.append("FORBIDDEN_GAS_SCALING_TAMPER")
        elif "gasleft" not in gas_arg or not _is_valid_gas_rhs(gas_arg):
            violations.append("FORBIDDEN_GAS_SCALING_TAMPER")
        else:
            all_gas_start_refs.update(_SOL_GAS_SUB_LHS_RE.findall(gas_arg))
    if all_gas_start_refs:
        for fn_bodies_gs in non_canon_fn_bodies.values():
            for fn_b_gs in fn_bodies_gs:
                if not any(gs_k in fn_b_gs for gs_k in all_gas_start_refs):
                    continue
                fn_as_gs = _index_sol_assignments(fn_b_gs)
                for gs_nm in all_gas_start_refs:
                    gs_pairs = fn_as_gs.get(gs_nm, ())
                    if gs_pairs and (
                        len(gs_pairs) > 1
                        or gs_nm in tuple_assigned_idents
                        or gs_nm in yul_assigned_idents
                        or any(go_s != "=" or gr_s.strip() != "gasleft()" for go_s, gr_s in gs_pairs)
                    ):
                        violations.append("FORBIDDEN_GAS_SCALING_TAMPER")
                        break
    for fn_nm_so_chk, fn_bodies_so_chk in non_canon_fn_bodies.items():
        for fn_b_so_chk in fn_bodies_so_chk:
            if "_assertConservation" not in fn_b_so_chk:
                continue
            local_ok_sv = verified_snap_vars_by_fn.get(id(fn_b_so_chk), set())
            for m_ac_l in _SOL_ASSERT_CONS_CALL_RE.finditer(fn_b_so_chk):
                ac_cl_l = _scan_matched_delim(fn_b_so_chk, m_ac_l.end() - 1, "(", ")")
                if ac_cl_l <= m_ac_l.end() - 1:
                    continue
                ac_al = _split_top_level_csv(fn_b_so_chk[m_ac_l.end() : ac_cl_l], open_chars="([", close_chars=")]", strict=False)
                if len(ac_al) >= 3:
                    b_al, a_al = ac_al[1].strip(), ac_al[2].strip()
                    if b_al not in local_ok_sv or a_al not in local_ok_sv or b_al == a_al:
                        violations.append(f"FORBIDDEN_UNVERIFIED_SNAP_ARG:{fn_nm_so_chk}")
    if "delete" in user_no_str:
        prot_del_idents = (
            {"liqCredit", "liqDebited", "gasStart", "gasUsed", "liqGasStart", "liqGasUsed"}
            | user_snap_vars
            | user_nft_snap_vars
            | user_liq_arg_vars
            | all_gas_start_refs
        )
        for del_id in _SOL_DELETE_IDENT_RE.findall(user_no_str):
            if del_id in prot_del_idents:
                violations.append(f"FORBIDDEN_CONSERVATION_DELETE_TAMPER:{del_id}")
    if user_snap_vars and _SOL_ASM_KW_RE.search(user_no_str):
        violations.append("FORBIDDEN_ASSEMBLY_IN_CONSERVATION_HARNESS")
    prot_asm_idents = _PROTECTED_SNAP_ASM_IDENTS | user_snap_vars | user_nft_snap_vars | user_liq_arg_vars
    for asm_u in _extract_assembly_blocks(user_no_str):
        if any(tok_au in prot_asm_idents for tok_au in _SOL_IDENT_TOKEN_RE.findall(asm_u)):
            violations.append("FORBIDDEN_ASSEMBLY_SNAP_OR_GAS_TAMPER")
    # 정식 보존 함수 단순 식별자 인자 외 스코프에서 ConservationSnap·NftSnap·배열 필드·liq 배열 포인터 에일리어싱/참조 전달 원천 차단
    if user_snap_vars or user_nft_snap_vars or user_liq_arg_vars or "liqCredit" in user_no_canon_tryliq or "liqDebited" in user_no_canon_tryliq:
        masked_parts: List[str] = []
        pos_m = 0
        for m_cc in _SOL_CANON_SNAP_CALL_HEAD_RE.finditer(user_no_canon_tryliq):
            if m_cc.start() < pos_m:
                continue
            cc_end = _scan_matched_delim(user_no_canon_tryliq, m_cc.end() - 1, "(", ")")
            if cc_end > m_cc.end() - 1:
                masked_parts.append(user_no_canon_tryliq[pos_m : m_cc.end()])
                kept_args = [
                    "0" if _SOL_SIMPLE_IDENT_RE.fullmatch(a.strip()) else a
                    for a in _split_top_level_csv(user_no_canon_tryliq[m_cc.end() : cc_end], open_chars="([", close_chars=")]", strict=False)
                ]
                masked_parts.append(",".join(kept_args) + ")")
                pos_m = cc_end + 1
        masked_parts.append(user_no_canon_tryliq[pos_m:])
        user_no_canon_calls = "".join(masked_parts)
        for m_bsa in _SOL_BARE_SNAP_ARR_FIELD_RE.finditer(user_no_canon_calls):
            pre_bsa = user_no_canon_calls[max(0, m_bsa.start() - 64) : m_bsa.start()].rstrip()
            m_owner_bsa = re.search(r"([A-Za-z_][A-Za-z0-9_]*)$", pre_bsa)
            if not (m_owner_bsa and m_owner_bsa.group(1) in user_nft_snap_vars):
                violations.append("FORBIDDEN_SNAP_ARRAY_ALIAS")
                break
        for alias_id, allow_next_ch, decl_re, decl_end_ch, v_prefix in (
            *(
                (la_id, "[", _SOL_MEM_DECL_PREFIX_RE, ";", "FORBIDDEN_LIQ_ARRAY_ALIAS")
                for la_id in sorted({"liqCredit", "liqDebited"} | user_liq_arg_vars)
            ),
            *(
                (sv_id, ".", _SOL_SNAP_DECL_PREFIX_RE, "", "FORBIDDEN_SNAP_VAR_ALIAS")
                for sv_id in sorted(user_snap_vars)
            ),
            *(
                (nv_id, ".", _SOL_SNAP_DECL_PREFIX_RE, "", "FORBIDDEN_NFT_SNAP_VAR_ALIAS")
                for nv_id in sorted(user_nft_snap_vars)
            ),
        ):
            if alias_id not in user_no_canon_calls:
                continue
            for m_al in _compiled_sol_ident_ref_re(alias_id).finditer(user_no_canon_calls):
                tail_al = user_no_canon_calls[m_al.end() :].lstrip()
                head_al = user_no_canon_calls[max(0, m_al.start() - 48) : m_al.start()]
                is_decl = bool(decl_re.search(head_al)) and (not decl_end_ch or tail_al.startswith(decl_end_ch))
                if not tail_al.startswith(allow_next_ch) and not is_decl:
                    violations.append(f"{v_prefix}:{alias_id}")
                    break

    def _collect_dep_idents(expr_s: str, skip_ident: str = "") -> List[str]:
        out_deps: List[str] = []
        no_hex_r = _SOL_HEX_LITERAL_RE.sub("0", expr_s or "")
        for tok_dep in _SOL_IDENT_TOKEN_RE.findall(no_hex_r):
            tl_dep = tok_dep.lower()
            if (
                tok_dep != skip_ident
                and tl_dep not in _SOL_UNITS_LOWER
                and not _SOL_PRIM_TYPE_RE.fullmatch(tok_dep)
                and tok_dep not in _CANONICAL_ALL_PROTECTED_FNS
                and tok_dep not in ("address", "payable", "balance", "balanceOf", "totalSupply", "allowance", "decimals", "abi", "type", "tx", "block", "gasleft", "return", "if", "else", "true", "false", "TARGET", "ZERO_STATE_CALLER")
                and not tok_dep.startswith(("VAULT_", "TOK_"))
                and tok_dep not in non_canon_fn_bodies
            ):
                out_deps.append(tok_dep)
        return list(dict.fromkeys(out_deps))

    def _check_expr_helpers(
        v_label: str,
        expr_s: str,
        _hdepth: int = 0,
        _hseen: Optional[Set[str]] = None,
        _iseed: Optional[Set[str]] = None,
    ) -> None:
        if _hseen is None:
            _hseen = set()
        if _iseed is None:
            _iseed = set()
        for m_hc in _SOL_HELPER_CALL_HEAD_RE.finditer(expr_s or ""):
            qual_h = m_hc.group("qual")
            fn_h = m_hc.group("fn")
            if qual_h is not None:
                if fn_h in _allowed_member_calls:
                    continue
                if fn_h not in non_canon_fn_bodies:
                    violations.append(f"FORBIDDEN_EXTERNAL_MEMBER_CALL_{v_label}:{fn_h}")
                    continue
            if (
                fn_h in _CANONICAL_ALL_PROTECTED_FNS
                or _SOL_PRIM_TYPE_RE.fullmatch(fn_h)
                or fn_h in ("address", "payable", "type")
                or fn_h in _hseen
                or fn_h not in non_canon_fn_bodies
            ):
                continue
            if _hdepth >= 2:
                violations.append(f"FORBIDDEN_DEEP_HELPER_IN_{v_label}:{fn_h}")
                continue
            _hseen.add(fn_h)
            for hb in non_canon_fn_bodies[fn_h]:
                if ":=" in hb or _SOL_ASM_OR_UNCHECKED_KW_RE.search(hb) or _has_literal_boost(hb):
                    violations.append(f"FORBIDDEN_HELPER_BOOST_OR_ASM_{v_label}:{fn_h}")
                ret_matches = list(_SOL_HELPER_RET_STMT_RE.finditer(hb))
                if not ret_matches:
                    violations.append(f"FORBIDDEN_IMPLICIT_RETURN_HELPER_{v_label}:{fn_h}")
                for m_ret in ret_matches:
                    ret_e = m_ret.group(1).strip()
                    if _SOL_CG_LITERAL_EXPR_RE.fullmatch(ret_e) or not _has_state_ident(ret_e) or _has_literal_boost(ret_e):
                        violations.append(f"FORBIDDEN_HELPER_LITERAL_RETURN_{v_label}:{fn_h}")
                for r_dep in _collect_dep_idents(hb):
                    _check_ident_assigns(v_label, r_dep, 1, _iseed, _hseen, _hdepth + 1)
                _check_expr_helpers(v_label, hb, _hdepth + 1, _hseen, _iseed)

    def _check_ident_assigns(
        v_label: str,
        ident: str,
        _depth: int = 0,
        _seen: Optional[Set[str]] = None,
        _hseen: Optional[Set[str]] = None,
        _hdepth: int = 0,
    ) -> None:
        if _seen is None:
            _seen = set()
        if _hseen is None:
            _hseen = set()
        if ident in _seen:
            return
        if _depth > 2:
            violations.append(f"FORBIDDEN_DEEP_VAR_CHAIN_{v_label}:{ident}")
            return
        _seen.add(ident)
        if ident in yul_assigned_idents:
            violations.append(f"FORBIDDEN_YUL_ASSIGN_{v_label}_VAR:{ident}")
        if ident in tuple_assigned_idents:
            violations.append(f"FORBIDDEN_TUPLE_ASSIGN_{v_label}_VAR:{ident}")
        if ident in incdec_idents:
            violations.append(f"FORBIDDEN_INCDEC_ASSIGN_{v_label}_VAR:{ident}")

        assign_pairs = (assigns_by_ident_clean if _depth == 0 else assigns_by_ident_non_canon).get(ident, ())
        if _depth == 0 and not assign_pairs:
            violations.append(f"UNBOUND_{v_label}_VAR:{ident}")
            return
        dep_idents: List[str] = []
        for op_s, rhs in assign_pairs:
            rhs_s = rhs.strip()
            if op_s != "=":
                self_ref = _compiled_sol_ident_ref_re(ident).search(rhs_s) is not None
                if (
                    op_s not in ("+=", "-=")
                    or self_ref
                    or (op_s == "+=" and "-" not in rhs_s)
                    or _SOL_CG_LITERAL_EXPR_RE.fullmatch(rhs_s)
                    or not _has_state_ident(rhs_s)
                    or _has_literal_boost(rhs_s)
                ):
                    violations.append(f"FORBIDDEN_COMPOUND_ASSIGN_{v_label}_VAR:{ident}")
                continue
            if _depth >= 1 and _SOL_PURE_ADDR_REF_RHS_RE.fullmatch(rhs_s) and not _SOL_INT_CAST_HEAD_RE.search(rhs_s):
                continue
            if _SOL_CG_LITERAL_EXPR_RE.fullmatch(rhs_s):
                violations.append(f"LITERAL_{v_label}_VAR_ASSIGN:{ident}")
            elif not _has_state_ident(rhs_s):
                violations.append(f"CONSTANT_{v_label}_VAR_ASSIGN:{ident}")
            elif _has_literal_boost(rhs_s):
                violations.append(f"LITERAL_BOOST_{v_label}_VAR_ASSIGN:{ident}")
            elif _depth == 0:
                canon_ok = False
                rhs_compact = _WS_COLLAPSE_RE.sub("", rhs_s)
                if v_label == "CALLER_GAIN":
                    canon_ok = (
                        "_verifyPostCommitSettlement" in rhs_s
                        or (
                            canonical_wnat_helper
                            and (
                                (ident == "wDelta" and any(c in rhs_s for c in canonical_cg_rhs))
                                or (ident == "combNatGain" and rhs_compact == "_satAdd(effNatG,_scaleToWei(effWG,wDec))")
                                or (ident == "effWG" and rhs_compact == "wSettled<rawWG?wSettled:rawWG")
                            )
                        )
                    )
                else:
                    canon_ok = (
                        (ident == "conservedLoss" and canonical_emit_helper and rhs_compact in ("vLoss+sInc", "_satAdd(vLoss,sInc)"))
                        or (ident == "eqLoss" and canonical_wnat_helper and rhs_compact in ("wL+wSWei+liqCredWei", "_satAdd(_satAdd(wL,wSWei),liqCredWei)"))
                    )
                if "-" not in rhs_s and not canon_ok:
                    violations.append(f"UNCOMPUTED_{v_label}_VAR_ASSIGN:{ident}")
            if _SOL_ZERO_SUB_RE.search(rhs_s):
                violations.append(f"TRIVIAL_ZERO_SUB_{v_label}_VAR_ASSIGN:{ident}")
            if v_label == "CALLER_GAIN" and _SOL_VAULT_REF_IN_CG_RE.search(rhs_s):
                violations.append(f"VAULT_STATE_IN_CALLER_GAIN_VAR_ASSIGN:{ident}")
            _check_expr_helpers(v_label, rhs_s, _hdepth, _hseen, _seen)
            dep_idents.extend(_collect_dep_idents(rhs_s, skip_ident=ident))
        for dep_id in dict.fromkeys(dep_idents):
            _check_ident_assigns(v_label, dep_id, _depth + 1, _seen, _hseen, _hdepth)

    non_canon_cg_emits = (
        list(_SOL_EMIT_CG_RE.finditer(non_canon_no_str))
        if "ConservationGain" in non_canon_no_str
        else []
    )
    if non_canon_cg_emits:
        canonical_emit_helper = _SOL_CANON_EMIT_ASSET_GAIN_FN_RE.search(clean) is not None
        canonical_wnat_helper = (
            _SOL_CANON_EMIT_SINGLE_WGAIN_FN_RE.search(clean) is not None
            and _SOL_CANON_WEQLOSS_FN_RE.search(clean) is not None
        )
        if canonical_emit_helper:
            canonical_cg_rhs.add("_verifyPostCommitSettlement(asset")
            canonical_vl_rhs.update({"vLoss + sInc", "_satAdd(vLoss, sInc)"})
        if canonical_wnat_helper:
            canonical_cg_rhs.update({"wArgs[2]", "_scaleToWei(wArgs[2], wDec)", "wMeta[0]", "_satAdd(effNatG, _scaleToWei(effWG, wDec))", "wSettled"})
            canonical_vl_rhs.update({"wL + wSWei + liqCredWei", "_satAdd(_satAdd(wL, wSWei), liqCredWei)"})
        clean_no_str_ai = _strip_quoted_strings_cached(clean)
        assigns_by_ident_clean = (
            assigns_by_ident_non_canon
            if clean_no_str_ai == non_canon_no_str
            else _index_sol_assignments(clean_no_str_ai)
        )
    for m in non_canon_cg_emits:
        parts = _split_top_level_csv(m.group(1), open_chars="(", close_chars=")", strict=False)
        if len(parts) != 5:
            violations.append("MALFORMED_CONSERVATION_GAIN_EMIT_ARITY")
            continue
        cg_expr = parts[2].strip()
        vl_expr = parts[3].strip()
        gas_expr = parts[4].strip()
        for expr_chk, tag_chk in ((cg_expr, "CALLER_GAIN"), (vl_expr, "VAULT_LOSS")):
            if _SOL_CG_LITERAL_EXPR_RE.fullmatch(expr_chk):
                violations.append(f"LITERAL_{tag_chk}_FORBIDDEN:{expr_chk[:32]}")
            elif not _has_state_ident(expr_chk):
                violations.append(f"CONSTANT_{tag_chk}_EXPR_FORBIDDEN:{expr_chk[:32]}")
            elif _has_literal_boost(expr_chk):
                violations.append(f"LITERAL_BOOST_{tag_chk}_FORBIDDEN:{expr_chk[:32]}")
            if _SOL_ZERO_SUB_RE.search(expr_chk):
                violations.append(f"TRIVIAL_ZERO_SUB_{tag_chk}_FORBIDDEN:{expr_chk[:32]}")
        if _SOL_VAULT_REF_IN_CG_RE.search(cg_expr):
            violations.append(f"VAULT_STATE_IN_CALLER_GAIN_FORBIDDEN:{cg_expr[:32]}")
        if not (gas_expr == "gasUsed" and (canonical_emit_helper or canonical_wnat_helper)):
            if _SOL_SIMPLE_IDENT_RE.fullmatch(gas_expr) is not None:
                gp_emit = assigns_by_ident_non_canon.get(gas_expr, ())
                if (
                    not gp_emit
                    or gas_expr in tuple_assigned_idents
                    or gas_expr in yul_assigned_idents
                    or not any(("gasleft" in gr or "gasStart" in gr or "gasUsed" in gr) for _, gr in gp_emit)
                    or any(go not in ("=", "+=") or not _is_valid_gas_rhs(gr.strip(), allow_simple_ident=(go == "+=")) for go, gr in gp_emit)
                ):
                    violations.append(f"FORBIDDEN_GAS_EMIT_TAMPER:{gas_expr[:32]}")
            elif "gasleft" not in gas_expr or not _is_valid_gas_rhs(gas_expr):
                violations.append(f"FORBIDDEN_GAS_EMIT_TAMPER:{gas_expr[:32]}")

        cg_is_ident = _SOL_SIMPLE_IDENT_RE.fullmatch(cg_expr) is not None
        vl_is_ident = _SOL_SIMPLE_IDENT_RE.fullmatch(vl_expr) is not None
        cg_canon = cg_expr in ("settledGain", "wDelta") and (
            (cg_expr == "settledGain" and canonical_emit_helper)
            or (cg_expr == "wDelta" and canonical_wnat_helper)
        )
        if cg_expr in ("combNatGain", "effWG") and canonical_wnat_helper:
            cg_canon = True
        vl_canon = (
            (vl_expr == "conservedLoss" and canonical_emit_helper)
            or (vl_expr in ("eqLoss", "_scaleFromWei(eqLoss, wDec)") and canonical_wnat_helper)
        )
        if vl_expr in ("rawSubLoss", "rawSingleSubLoss") and canonical_wnat_helper:
            vl_canon = True
        if "-" not in cg_expr and not cg_is_ident and not cg_canon and "_verifyPostCommitSettlement" not in cg_expr:
            violations.append(f"UNCOMPUTED_CALLER_GAIN_EXPR:{cg_expr[:32]}")
        if "-" not in vl_expr and not vl_is_ident and not vl_canon:
            violations.append(f"UNCOMPUTED_VAULT_LOSS_EXPR:{vl_expr[:32]}")
        _check_expr_helpers("CALLER_GAIN", cg_expr)
        _check_expr_helpers("VAULT_LOSS", vl_expr)
        if cg_is_ident:
            _check_ident_assigns("CALLER_GAIN", cg_expr)
        else:
            for cg_dep in _collect_dep_idents(cg_expr):
                _check_ident_assigns("CALLER_GAIN", cg_dep, 1)
        if vl_is_ident:
            _check_ident_assigns("VAULT_LOSS", vl_expr)
        elif vl_expr == "_scaleFromWei(eqLoss, wDec)" and canonical_wnat_helper:
            _check_ident_assigns("VAULT_LOSS", "eqLoss")
        else:
            for vl_dep in _collect_dep_idents(vl_expr):
                _check_ident_assigns("VAULT_LOSS", vl_dep, 1)
    dedup = tuple(dict.fromkeys(violations))
    return (len(dedup) == 0), dedup


def verify_agent_harness_accounting_integrity(
    sol_code: str,
    *,
    allowed_caller: str = "",
    allowed_target_addrs: Optional[Sequence[str]] = None,
    chain: str = "",
) -> Tuple[bool, List[str]]:
    """
    에이전트가 제출한 `test_{cid}.t.sol` 소스 코드에서 `emit ConservationGain(...)` 위변조(상수 리터럴 주입,
    복합 대입 변조, 비테스트 서브컨트랙트 이벤트 위조, 사전/사후 잔고 차감 생략, `VAULT_*`/`TOK_*` 중복·슬롯 치환,
    가스 스케일 변조, 다중/반복문 emit)를 정적 검증한다.
    """
    ok, dedup = _verify_agent_harness_accounting_integrity_cached(
        str(sol_code or ""),
        str(allowed_caller or ""),
        tuple(str(a) for a in (allowed_target_addrs or ())),
        str(chain or ""),
    )
    return ok, list(dedup)


_SOLC_AST_YUL_RAW_LOGS: FrozenSet[str] = frozenset({"log0", "log1", "log2", "log3", "log4"})
_SOLC_AST_BASE_VM_TYPES: FrozenSet[str] = frozenset({
    "contract Vm",
    "contract IHevm",
    "contract Hevm",
    "contract StdCheats",
})
_SOLC_AST_FORB_DEL_IMPLS: FrozenSet[int] = frozenset({
    int(HEVM_ADDRESS_LOWER, 16),
    int(FOUNDRY_CONSOLE_ADDR, 16),
    int(FOUNDRY_TEST_CONTRACT, 16),
    int(FOUNDRY_DEFAULT_SENDER, 16),
    int(CREATE2_DEPLOYER_ADDR, 16),
})
_SOLC_AST_BRANCH_NODES: FrozenSet[str] = frozenset({
    "IfStatement",
    "ForStatement",
    "WhileStatement",
    "DoWhileStatement",
    "TryStatement",
    "Conditional",
})
_SOLC_AST_GAS_VAR_NAMES: FrozenSet[str] = frozenset({
    "gasStart",
    "gasUsed",
    "liqGasStart",
    "liqGasUsed",
})


def _minimal_solc_subproc_env() -> Dict[str, str]:
    sys_root = Path(sys.executable).resolve().drive or "C:"
    win_dir = f"{sys_root}\\Windows"
    sys32_dir = f"{win_dir}\\System32"
    foundry_dir = str((SCRIPT_DIR / "tools" / "foundry").resolve())
    return {
        "SYSTEMROOT": win_dir,
        "WINDIR": win_dir,
        "SystemDrive": sys_root,
        "PATH": os.pathsep.join([foundry_dir, sys32_dir, win_dir]),
        "PATHEXT": ".COM;.EXE;.BAT;.CMD",
        "NO_COLOR": "1",
    }


def _strip_solc_type_loc(type_str: str) -> str:
    s = str(type_str or "").strip()
    for suf in (" storage ref", " storage pointer", " memory", " calldata", " storage"):
        if s.endswith(suf):
            s = s[: -len(suf)].strip()
    return s


def _ast_parse_int_lit(raw_val: Any) -> Optional[int]:
    if isinstance(raw_val, int):
        return raw_val
    s = str(raw_val or "").strip().replace("_", "")
    if not s:
        return None
    try:
        return int(s, 16) if s.lower().startswith("0x") else int(s, 10)
    except ValueError:
        return None


def _ast_all_root_decl_ids(node: Any, _depth: int = 0) -> Set[int]:
    if _depth > 64 or not isinstance(node, dict):
        return set()
    cur = _ast_unwrap_parens(node)
    if not isinstance(cur, dict):
        return set()
    nt = cur.get("nodeType")
    if nt == "Identifier":
        ref_id = cur.get("referencedDeclaration")
        return {int(ref_id)} if isinstance(ref_id, int) else set()
    if nt == "IndexAccess":
        return _ast_all_root_decl_ids(cur.get("baseExpression"), _depth + 1)
    if nt == "MemberAccess":
        return _ast_all_root_decl_ids(cur.get("expression"), _depth + 1)
    if nt == "TupleExpression":
        out_ids: Set[int] = set()
        for comp in (cur.get("components") or ()):
            if isinstance(comp, dict):
                out_ids |= _ast_all_root_decl_ids(comp, _depth + 1)
        return out_ids
    return set()


_SOLC_AST_CANON_PROT_CONSUMERS: FrozenSet[str] = frozenset({
    "_takeSnap",
    "_takeNftSnap",
    "_tryLiquidateGains",
    "_bridgeLiquidatedGain",
    "_bridgeLiquidatedNftGain",
    "_bridgeAtomicTargetExit",
    "_assertConservation",
    "_assertConservationLiq",
})


def _ast_unwrap_parens(node: Any) -> Any:
    cur = node
    for _ in range(64):
        if not isinstance(cur, dict):
            return cur
        if cur.get("nodeType") == "TupleExpression":
            comps = cur.get("components") or []
            if len(comps) == 1 and isinstance(comps[0], dict):
                cur = comps[0]
                continue
        return cur
    return cur


def _ast_is_gasleft_call(node: Any) -> bool:
    u = _ast_unwrap_parens(node)
    if not isinstance(u, dict) or u.get("nodeType") != "FunctionCall":
        return False
    ex = u.get("expression") or {}
    return bool(
        ex.get("nodeType") == "Identifier"
        and ex.get("name") == "gasleft"
        and len(u.get("arguments") or ()) == 0
    )


def _ast_is_gas_ident(node: Any, expected_name: str, gas_ids: Set[int]) -> bool:
    u = _ast_unwrap_parens(node)
    if not isinstance(u, dict) or u.get("nodeType") != "Identifier":
        return False
    ref_id = u.get("referencedDeclaration")
    return bool(str(u.get("name") or "") == expected_name and isinstance(ref_id, int) and int(ref_id) in gas_ids)


def _ast_is_valid_gas_diff(node: Any, start_name: str, gas_ids: Set[int]) -> bool:
    u = _ast_unwrap_parens(node)
    if not isinstance(u, dict) or u.get("nodeType") != "BinaryOperation" or u.get("operator") != "-":
        return False
    return bool(
        _ast_is_gas_ident(u.get("leftExpression"), start_name, gas_ids)
        and _ast_is_gasleft_call(u.get("rightExpression"))
    )


def _ast_is_valid_gas_used_init(init_v: Any, start_name: str, gas_ids: Set[int]) -> bool:
    u = _ast_unwrap_parens(init_v)
    if not isinstance(u, dict):
        return False
    if _ast_is_valid_gas_diff(u, start_name, gas_ids):
        return True
    if u.get("nodeType") == "Conditional":
        cond = _ast_unwrap_parens(u.get("condition"))
        t_ex = u.get("trueExpression")
        f_ex = _ast_unwrap_parens(u.get("falseExpression"))
        cond_ok = bool(
            isinstance(cond, dict)
            and cond.get("nodeType") == "BinaryOperation"
            and cond.get("operator") in (">", ">=")
            and _ast_is_gas_ident(cond.get("leftExpression"), start_name, gas_ids)
            and _ast_is_gasleft_call(cond.get("rightExpression"))
        )
        false_ok = bool(
            isinstance(f_ex, dict)
            and f_ex.get("nodeType") == "Literal"
            and _ast_parse_int_lit(f_ex.get("value")) is not None
        )
        return cond_ok and _ast_is_valid_gas_diff(t_ex, start_name, gas_ids) and false_ok
    return False


def _verify_solidity_formal_ast_cached(
    sol_code: str,
    allowed_caller: str,
    forbid_inline_fork: bool,
    strict_agent_accounting: bool,
) -> Tuple[bool, Tuple[str, ...]]:
    """
    로컬 `solc.exe --standard-json` 공식 컴파일러 AST(`outputSelection: ast`, `evmVersion: prague`) 기반 형식 불변식 검증기.
    임시 파일 없이 stdin/stdout 파이프로 컴파일러 타입 해석 결과를 직접 검사하여:
    - `using Lib for Vm` / 별칭·래핑 인터페이스·헬퍼·라이브러리 내부 VM 치트코드 우회, 상수·함수 내 SSA 로컬 상수 폴딩 기반 비정식 HEVM 주소 실체화
    - `solc` 비정상 실행/타임아웃/빈 AST 출력에 대한 Fail-Closed 거부
    - 헬퍼 컨트랙트 포함 전체 파일의 Yul `log0..log4`/`extcodehash`·`Conservation*` 직접 발행
    - 하네스 내부 `assembly`/`modifier`/`constructor`/`receive`/`fallback`/`address(this)`/비상수 상태 초기화
    - 엄격 회계(`strict_agent_accounting`) 시 선언 ID 기반 `ConservationSnap`/`NftSnap`/`liqCredit`/`liqDebited`/가스 변수의
      `delete`·직접/다중 튜플 대입·배열/구조체 메모리 참조 별칭 탈출·`gasUsed` 대수식 위조·구조체 생성자 위조 및 분기·루프 내부 `_assertConservation*` 은닉을 원천 차단한다.
    """
    if not sol_code:
        return True, ()
    if not SOLC_BIN.is_file():
        return False, ("ast_solc_binary_missing",)
    std_in = {
        "language": "Solidity",
        "sources": {"Verify.sol": {"content": sol_code}},
        "settings": {"evmVersion": "prague", "outputSelection": {"*": {"": ["ast"]}}},
    }
    try:
        with _SOLC_AST_SEM:
            cp = _run_subproc_tree_safe(
                [str(SOLC_BIN), "--standard-json"],
                cwd=str(SCRIPT_DIR),
                env=_minimal_solc_subproc_env(),
                timeout_sec=25.0,
                decode_text=True,
                input_bytes=json.dumps(std_in).encode("utf-8"),
            )
        out_doc = json.loads(cp.stdout or "{}")
    except Exception:
        return False, ("ast_solc_exec_failed",)
    src_entry = (out_doc.get("sources") or {}).get("Verify.sol") if isinstance(out_doc, dict) else None
    ast_root = src_entry.get("ast") if isinstance(src_entry, dict) else None
    if not isinstance(ast_root, dict):
        has_compile_err = False
        if isinstance(out_doc, dict):
            for err_item in (out_doc.get("errors") or ()):
                if not isinstance(err_item, dict):
                    continue
                err_msg_l = str(err_item.get("formattedMessage") or err_item.get("message") or "").lower()
                if "requires different compiler version" in err_msg_l:
                    return False, ("ast_disallowed_solc_version_mismatch",)
                if "import callback" in err_msg_l or ("source " in err_msg_l and "not found" in err_msg_l):
                    return False, ("ast_disallowed_external_import",)
                if str(err_item.get("severity") or "").lower() == "error":
                    has_compile_err = True
        return (True, ()) if has_compile_err else (False, ("ast_solc_empty_ast",))

    violations: List[str] = []
    norm_c0 = _norm_addr(allowed_caller) if allowed_caller else ""
    norm_c0_int: Optional[int] = int(norm_c0, 16) if norm_c0 else None

    const_int_by_id: Dict[int, int] = {}
    const_bytes_by_id: Dict[int, bytes] = {}
    vm_type_strings: Set[str] = set(_SOLC_AST_BASE_VM_TYPES)
    vm_contract_names: Set[str] = {"Vm", "IHevm", "Hevm", "StdCheats"}
    has_vm_type_in_file = False

    def _is_hevm_int(iv: Optional[int]) -> bool:
        return iv is not None and (iv & _ADDR_MASK_160) == _HEVM_ADDR_INT

    def _solc_bytes_n(ts_s: str) -> Optional[int]:
        if ts_s.startswith("bytes") and ts_s[5:].isdigit():
            nb = int(ts_s[5:])
            if 1 <= nb <= 32:
                return nb
        return None

    def _solc_type_bitwidth(ts_s: str) -> int:
        nb = _solc_bytes_n(ts_s)
        if nb is not None:
            return 8 * nb
        if ts_s in ("address", "address payable"):
            return 160
        if ts_s.startswith("uint") and ts_s[4:].isdigit():
            bw = int(ts_s[4:])
            if 8 <= bw <= 256:
                return bw
        return 256

    def _ast_extract_bytes(
        expr: Any,
        _depth: int = 0,
        *,
        loc_ints: Optional[Dict[int, int]] = None,
        loc_bytes: Optional[Dict[int, bytes]] = None,
    ) -> Optional[bytes]:
        if _depth > 24 or not isinstance(expr, dict):
            return None
        nt = expr.get("nodeType")
        if nt == "Literal":
            lk = str(expr.get("kind") or "")
            if lk in ("string", "unicodeString", "hexString"):
                hv = expr.get("hexValue")
                if isinstance(hv, str) and (len(hv) % 2 == 0):
                    try:
                        return bytes.fromhex(hv)
                    except ValueError:
                        pass
                val_s = expr.get("value")
                if isinstance(val_s, str):
                    return val_s.encode("utf-8")
            return None
        if nt == "Identifier":
            ref_id = expr.get("referencedDeclaration")
            if isinstance(ref_id, int):
                if loc_bytes and ref_id in loc_bytes:
                    return loc_bytes[ref_id]
                if ref_id in const_bytes_by_id:
                    return const_bytes_by_id[ref_id]
                ts_id = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
                iv_id = (
                    loc_ints[ref_id]
                    if (loc_ints and ref_id in loc_ints)
                    else const_int_by_id.get(ref_id)
                )
                if iv_id is not None and iv_id >= 0:
                    if ts_id in ("address", "address payable"):
                        return (iv_id & _ADDR_MASK_160).to_bytes(20, "big")
                    if ts_id.startswith("uint") and ts_id[4:].isdigit():
                        bw_i = int(ts_id[4:])
                        if 8 <= bw_i <= 256 and bw_i % 8 == 0:
                            return (iv_id & ((1 << bw_i) - 1)).to_bytes(bw_i // 8, "big")
                    if ts_id.startswith("bytes") and ts_id[5:].isdigit():
                        nb_i = int(ts_id[5:])
                        if 1 <= nb_i <= 32:
                            return (iv_id & ((1 << (8 * nb_i)) - 1)).to_bytes(nb_i, "big")
            return None
        if nt == "TupleExpression":
            comps = expr.get("components") or []
            return _ast_extract_bytes(comps[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes) if len(comps) == 1 else None
        if nt == "FunctionCall" and expr.get("kind") == "typeConversion":
            args_tc = expr.get("arguments") or []
            if len(args_tc) != 1:
                return None
            ts_tc = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
            if ts_tc in ("bytes", "string"):
                return _ast_extract_bytes(args_tc[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
            if ts_tc in ("address", "address payable"):
                iv_a = _resolve_ast_int(args_tc[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if iv_a is not None and iv_a >= 0:
                    return (iv_a & _ADDR_MASK_160).to_bytes(20, "big")
                return None
            if ts_tc.startswith("uint") and ts_tc[4:].isdigit():
                bw_u = int(ts_tc[4:])
                if 8 <= bw_u <= 256 and bw_u % 8 == 0:
                    iv_u = _resolve_ast_int(args_tc[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                    if iv_u is not None and iv_u >= 0:
                        return (iv_u & ((1 << bw_u) - 1)).to_bytes(bw_u // 8, "big")
                return None
            if ts_tc.startswith("bytes") and ts_tc[5:].isdigit():
                n_b = int(ts_tc[5:])
                if 1 <= n_b <= 32:
                    raw_sub = _ast_extract_bytes(args_tc[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                    if raw_sub is not None:
                        return raw_sub[:n_b].ljust(n_b, b"\x00")
                    iv_sub = _resolve_ast_int(args_tc[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                    if iv_sub is not None and iv_sub >= 0:
                        return (iv_sub & ((1 << (8 * n_b)) - 1)).to_bytes(n_b, "big")
            return None
        if nt == "FunctionCall" and expr.get("kind") == "functionCall":
            ex_f = expr.get("expression") or {}
            args_f = expr.get("arguments") or []
            if ex_f.get("nodeType") == "MemberAccess":
                m_f = str(ex_f.get("memberName") or "")
                recv_f = ex_f.get("expression") or {}
                is_pack = (
                    m_f == "encodePacked"
                    and recv_f.get("nodeType") == "Identifier"
                    and recv_f.get("name") == "abi"
                )
                is_abi_enc = (
                    m_f == "encode"
                    and recv_f.get("nodeType") == "Identifier"
                    and recv_f.get("name") == "abi"
                )
                is_concat = (
                    m_f == "concat"
                    and recv_f.get("nodeType") == "ElementaryTypeNameExpression"
                    and str((recv_f.get("typeName") or {}).get("name") or "") in ("bytes", "string")
                )
                if is_pack or is_concat:
                    parts: List[bytes] = []
                    for a_f in args_f:
                        pb = _ast_extract_bytes(a_f, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                        if pb is None:
                            return None
                        parts.append(pb)
                    return b"".join(parts)
                if is_abi_enc and args_f:
                    enc_words: List[bytes] = []
                    for a_f in args_f:
                        a_ts = _strip_solc_type_loc((a_f.get("typeDescriptions") or {}).get("typeString") or "") if isinstance(a_f, dict) else ""
                        if a_ts.startswith("bytes") and a_ts[5:].isdigit():
                            nb_e = int(a_ts[5:])
                            pb_e = _ast_extract_bytes(a_f, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                            if pb_e is not None and 1 <= nb_e <= 32:
                                enc_words.append(pb_e[:nb_e].ljust(32, b"\x00"))
                                continue
                        iv_e = _resolve_ast_int(a_f, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                        if iv_e is None or iv_e < 0:
                            return None
                        enc_words.append((iv_e & _UINT256_MAX).to_bytes(32, "big"))
                    return b"".join(enc_words)
        if nt in ("BinaryOperation", "UnaryOperation"):
            ts_op_b = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
            nb_op = _solc_bytes_n(ts_op_b)
            if nb_op is not None:
                iv_op = _resolve_ast_int(expr, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if iv_op is not None and iv_op >= 0:
                    return (iv_op & ((1 << (8 * nb_op)) - 1)).to_bytes(nb_op, "big")
        return None

    def _resolve_ast_int(
        expr: Any,
        _depth: int = 0,
        *,
        loc_ints: Optional[Dict[int, int]] = None,
        loc_bytes: Optional[Dict[int, bytes]] = None,
    ) -> Optional[int]:
        if _depth > 24 or not isinstance(expr, dict):
            return None
        nt = expr.get("nodeType")
        if nt == "Literal":
            if str(expr.get("kind") or "") == "hexString":
                hv_i = str(expr.get("hexValue") or "").strip()
                if hv_i and len(hv_i) % 2 == 0 and len(hv_i) <= 64:
                    try:
                        return int(hv_i, 16)
                    except ValueError:
                        return None
                return None
            return _ast_parse_int_lit(expr.get("value"))
        if nt == "Identifier":
            ref_id = expr.get("referencedDeclaration")
            if isinstance(ref_id, int):
                if loc_ints and ref_id in loc_ints:
                    return loc_ints[ref_id]
                if ref_id in const_int_by_id:
                    return const_int_by_id[ref_id]
            return None
        if nt == "FunctionCall" and expr.get("kind") == "typeConversion":
            args_tc = expr.get("arguments") or []
            if len(args_tc) != 1:
                return None
            ts_tc = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
            arg0 = args_tc[0]
            arg_ts = (
                _strip_solc_type_loc((arg0.get("typeDescriptions") or {}).get("typeString") or "")
                if isinstance(arg0, dict)
                else ""
            )
            dst_nb = _solc_bytes_n(ts_tc)
            if dst_nb is not None:
                is_raw_bytes_arg = (
                    arg_ts in ("bytes", "string")
                    or arg_ts.startswith("literal_string")
                    or (isinstance(arg0, dict) and arg0.get("nodeType") == "Literal" and str(arg0.get("kind") or "") in ("string", "unicodeString", "hexString"))
                )
                if is_raw_bytes_arg:
                    raw_b_tc = _ast_extract_bytes(arg0, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                    if raw_b_tc is not None:
                        return int.from_bytes(raw_b_tc[:dst_nb].ljust(dst_nb, b"\x00"), "big")
                iv_b_tc = _resolve_ast_int(arg0, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if iv_b_tc is None:
                    raw_b_tc = _ast_extract_bytes(arg0, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                    if raw_b_tc is None:
                        return None
                    return int.from_bytes(raw_b_tc[:dst_nb].ljust(dst_nb, b"\x00"), "big")
                src_nb = _solc_bytes_n(arg_ts)
                dst_mask = (1 << (8 * dst_nb)) - 1
                if src_nb is not None:
                    if dst_nb > src_nb:
                        return (iv_b_tc << (8 * (dst_nb - src_nb))) & dst_mask
                    if dst_nb < src_nb:
                        return (iv_b_tc >> (8 * (src_nb - dst_nb))) & dst_mask
                return iv_b_tc & dst_mask
            iv_tc = _resolve_ast_int(arg0, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
            if iv_tc is None:
                raw_tc = _ast_extract_bytes(arg0, _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if raw_tc is None:
                    return None
                if ts_tc in ("address", "address payable", "uint160") and len(raw_tc) <= 32:
                    return int.from_bytes(raw_tc, "big") & _ADDR_MASK_160
                if ts_tc.startswith("uint") and ts_tc[4:].isdigit() and len(raw_tc) <= 32:
                    bw_r = int(ts_tc[4:])
                    if 8 <= bw_r <= 256:
                        return int.from_bytes(raw_tc, "big") & ((1 << bw_r) - 1)
                return None
            if ts_tc in ("address", "address payable", "uint160"):
                return iv_tc & _ADDR_MASK_160
            if ts_tc.startswith("uint") and ts_tc[4:].isdigit():
                bw = int(ts_tc[4:])
                if 8 <= bw <= 256:
                    return iv_tc & ((1 << bw) - 1)
            return iv_tc
        if nt == "FunctionCall" and expr.get("kind") == "functionCall":
            ex_k = expr.get("expression") or {}
            args_k = expr.get("arguments") or []
            if (
                ex_k.get("nodeType") == "Identifier"
                and ex_k.get("name") == "keccak256"
                and len(args_k) == 1
            ):
                raw_b = _ast_extract_bytes(args_k[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if raw_b is not None:
                    return int.from_bytes(_keccak256(raw_b), "big")
            if (
                ex_k.get("nodeType") == "MemberAccess"
                and str(ex_k.get("memberName") or "") == "decode"
                and (ex_k.get("expression") or {}).get("nodeType") == "Identifier"
                and (ex_k.get("expression") or {}).get("name") == "abi"
                and len(args_k) == 2
            ):
                raw_d = _ast_extract_bytes(args_k[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
                if raw_d is not None and len(raw_d) == 32:
                    return int.from_bytes(raw_d, "big")
        if nt == "TupleExpression":
            comps = expr.get("components") or []
            return _resolve_ast_int(comps[0], _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes) if len(comps) == 1 else None
        if nt == "UnaryOperation":
            sub_v = _resolve_ast_int(expr.get("subExpression"), _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
            if sub_v is None:
                return None
            op_u = expr.get("operator")
            ts_u = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
            mask_u = (1 << _solc_type_bitwidth(ts_u)) - 1
            if op_u == "~":
                return (~sub_v) & mask_u
            if op_u == "-":
                return -sub_v
            return None
        if nt == "BinaryOperation":
            lv = _resolve_ast_int(expr.get("leftExpression"), _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
            rv = _resolve_ast_int(expr.get("rightExpression"), _depth + 1, loc_ints=loc_ints, loc_bytes=loc_bytes)
            if lv is None or rv is None:
                return None
            op_b = expr.get("operator")
            ts_b = _strip_solc_type_loc((expr.get("typeDescriptions") or {}).get("typeString") or "")
            mask_b = (1 << _solc_type_bitwidth(ts_b)) - 1
            if op_b == "+":
                return (lv + rv) & mask_b
            if op_b == "-":
                return (lv - rv) & mask_b
            if op_b == "*":
                return (lv * rv) & mask_b
            if op_b == "/" and lv >= 0 and rv > 0:
                return (lv // rv) & mask_b
            if op_b == "%" and lv >= 0 and rv > 0:
                return (lv % rv) & mask_b
            if op_b == "**" and lv >= 0 and 0 <= rv <= 256:
                return pow(lv, rv, mask_b + 1)
            if op_b == "^":
                return (lv ^ rv) & mask_b
            if op_b == "|":
                return (lv | rv) & mask_b
            if op_b == "&":
                return (lv & rv) & mask_b
            if op_b == "<<" and 0 <= rv <= 256:
                return (lv << rv) & mask_b
            if op_b == ">>" and 0 <= rv <= 256:
                return (lv & mask_b) >> rv
        return None

    # Pre-pass: collect constant scalars/bytes & all contract/interface types instantiated from HEVM_ADDRESS
    const_var_nodes: List[Dict[str, Any]] = []
    type_conv_nodes: List[Dict[str, Any]] = []

    def _prepass(nd: Any) -> None:
        nonlocal has_vm_type_in_file
        if isinstance(nd, dict):
            nt = nd.get("nodeType")
            if nt == "ContractDefinition":
                cn_p = str(nd.get("name") or "")
                if cn_p in vm_contract_names:
                    has_vm_type_in_file = True
                    vm_type_strings.add(f"contract {cn_p}")
            elif nt == "VariableDeclaration" and bool(nd.get("constant")) and isinstance(nd.get("value"), dict):
                const_var_nodes.append(nd)
            elif nt == "FunctionCall" and nd.get("kind") == "typeConversion":
                type_conv_nodes.append(nd)
            for v in nd.values():
                if isinstance(v, (dict, list)):
                    _prepass(v)
        elif isinstance(nd, list):
            for it in nd:
                if isinstance(it, (dict, list)):
                    _prepass(it)

    _prepass(ast_root)
    for _ in range(24):
        progressed = False
        for cv in const_var_nodes:
            cid_v = cv.get("id")
            if isinstance(cid_v, int):
                if cid_v not in const_bytes_by_id:
                    bv = _ast_extract_bytes(cv.get("value"))
                    if bv is not None:
                        const_bytes_by_id[cid_v] = bv
                        progressed = True
                if cid_v not in const_int_by_id:
                    iv = _resolve_ast_int(cv.get("value"))
                    if iv is not None:
                        const_int_by_id[cid_v] = iv
                        progressed = True
        if not progressed:
            break
    for tc in type_conv_nodes:
        tc_args = tc.get("arguments") or []
        if len(tc_args) == 1 and _is_hevm_int(_resolve_ast_int(tc_args[0])):
            ts_tc = _strip_solc_type_loc((tc.get("typeDescriptions") or {}).get("typeString") or "")
            if ts_tc.startswith("contract "):
                vm_type_strings.add(ts_tc)
                vm_contract_names.add(ts_tc[len("contract ") :].strip())
                has_vm_type_in_file = True

    def _is_vm_type(ts_raw: str) -> bool:
        ts_c = _strip_solc_type_loc(ts_raw)
        if ts_c in vm_type_strings:
            return True
        if ts_c.startswith("type(") and ts_c.endswith(")"):
            return ts_c[5:-1].strip() in vm_type_strings
        return False

    def _is_snap_type(ts_raw: str, struct_suffix: str) -> bool:
        ts_c = _strip_solc_type_loc(ts_raw)
        return ts_c.endswith(f".{struct_suffix}") or ts_c == f"struct {struct_suffix}"

    def _check_yul_ast(y_nd: Any, in_harness: bool) -> None:
        if isinstance(y_nd, dict):
            ynt = y_nd.get("nodeType")
            if ynt == "YulFunctionCall":
                yfn = str((y_nd.get("functionName") or {}).get("name") or "")
                if yfn in _SOLC_AST_YUL_RAW_LOGS:
                    violations.append(f"ast_disallowed_yul_raw_log:{yfn}")
                elif yfn == "extcodehash":
                    violations.append("ast_disallowed_yul_extcodehash")
                elif in_harness and yfn in ("selfbalance", "address"):
                    violations.append("ast_disallowed_harness_self_ref")
            elif ynt == "YulLiteral":
                yv = _ast_parse_int_lit(y_nd.get("value"))
                if yv is not None and (yv & _ADDR_MASK_160) == _HEVM_ADDR_INT:
                    violations.append("ast_disallowed_yul_hevm_addr")
            for v in y_nd.values():
                if isinstance(v, (dict, list)):
                    _check_yul_ast(v, in_harness)
        elif isinstance(y_nd, list):
            for it in y_nd:
                if isinstance(it, (dict, list)):
                    _check_yul_ast(it, in_harness)

    def _check_using_directive(u_nd: Dict[str, Any]) -> None:
        tn = u_nd.get("typeName")
        if tn is None:
            if has_vm_type_in_file:
                violations.append("ast_disallowed_using_for_vm")
            return
        if isinstance(tn, dict):
            ts_u = _strip_solc_type_loc((tn.get("typeDescriptions") or {}).get("typeString") or "")
            nm_u = str(tn.get("name") or (tn.get("pathNode") or {}).get("name") or "")
            if _is_vm_type(ts_u) or nm_u in vm_contract_names:
                violations.append("ast_disallowed_using_for_vm")

    def _ast_expr_escapes_protected_ref(expr: Any, prot_ref_ids: Set[int], _depth: int = 0) -> bool:
        if not prot_ref_ids or not isinstance(expr, dict):
            return False
        if _depth > 32:
            return True
        u = _ast_unwrap_parens(expr)
        if not isinstance(u, dict):
            return False
        u_nt = u.get("nodeType")
        if u_nt == "TupleExpression":
            return any(
                _ast_expr_escapes_protected_ref(c_it, prot_ref_ids, _depth + 1)
                for c_it in (u.get("components") or ())
                if isinstance(c_it, dict)
            )
        if u_nt == "Conditional":
            return _ast_expr_escapes_protected_ref(u.get("trueExpression"), prot_ref_ids, _depth + 1) or _ast_expr_escapes_protected_ref(
                u.get("falseExpression"), prot_ref_ids, _depth + 1
            )
        if u_nt == "FunctionCall" and u.get("kind") == "typeConversion":
            return any(
                _ast_expr_escapes_protected_ref(a_it, prot_ref_ids, _depth + 1)
                for a_it in (u.get("arguments") or ())
                if isinstance(a_it, dict)
            )
        r_ids = _ast_all_root_decl_ids(u)
        if not (r_ids & prot_ref_ids):
            return False
        u_ts = _strip_solc_type_loc((u.get("typeDescriptions") or {}).get("typeString") or "")
        return bool(
            ("[" in u_ts)
            or _is_snap_type(u_ts, "ConservationSnap")
            or _is_snap_type(u_ts, "NftSnap")
        )

    _hevm_hex40 = HEVM_ADDRESS_LOWER[2:]
    _hevm_bytes20 = bytes.fromhex(_hevm_hex40)

    def _collect_fn_ssa_consts(fn_nd: Any) -> Tuple[Dict[int, int], Dict[int, bytes]]:
        mutated_ids: Set[int] = set()
        ssa_decls: List[Tuple[int, Dict[str, Any]]] = []
        uninit_decl_ids: Set[int] = set()
        single_assign_rhs: Dict[int, Dict[str, Any]] = {}
        assign_counts: Dict[int, int] = {}

        def _scan_ssa(sub: Any) -> None:
            if isinstance(sub, dict):
                s_nt = sub.get("nodeType")
                if s_nt == "Assignment":
                    lhs_s = _ast_unwrap_parens(sub.get("leftHandSide"))
                    rhs_s = _ast_unwrap_parens(sub.get("rightHandSide"))
                    op_s = str(sub.get("operator") or "")
                    # Ignore no-op self-assignment `x = x;` so it cannot defeat SSA folding
                    if (
                        op_s == "="
                        and isinstance(lhs_s, dict)
                        and isinstance(rhs_s, dict)
                        and lhs_s.get("nodeType") == "Identifier"
                        and rhs_s.get("nodeType") == "Identifier"
                        and isinstance(lhs_s.get("referencedDeclaration"), int)
                        and lhs_s.get("referencedDeclaration") == rhs_s.get("referencedDeclaration")
                    ):
                        pass
                    elif (
                        op_s == "="
                        and isinstance(lhs_s, dict)
                        and lhs_s.get("nodeType") == "Identifier"
                        and isinstance(lhs_s.get("referencedDeclaration"), int)
                        and isinstance(rhs_s, dict)
                    ):
                        lid = int(lhs_s["referencedDeclaration"])
                        assign_counts[lid] = assign_counts.get(lid, 0) + 1
                        if assign_counts[lid] == 1:
                            single_assign_rhs[lid] = rhs_s
                        else:
                            mutated_ids.add(lid)
                    else:
                        mutated_ids.update(_ast_all_root_decl_ids(sub.get("leftHandSide")))
                elif s_nt == "UnaryOperation" and str(sub.get("operator") or "") in ("++", "--", "delete"):
                    mutated_ids.update(_ast_all_root_decl_ids(sub.get("subExpression")))
                elif s_nt == "VariableDeclarationStatement":
                    decls_s = [d for d in (sub.get("declarations") or ()) if isinstance(d, dict)]
                    init_s = sub.get("initialValue")
                    if len(decls_s) == 1 and isinstance(decls_s[0].get("id"), int):
                        did_s = int(decls_s[0]["id"])
                        if isinstance(init_s, dict):
                            ssa_decls.append((did_s, init_s))
                        else:
                            uninit_decl_ids.add(did_s)
                for v_s in sub.values():
                    if isinstance(v_s, (dict, list)):
                        _scan_ssa(v_s)
            elif isinstance(sub, list):
                for it_s in sub:
                    if isinstance(it_s, (dict, list)):
                        _scan_ssa(it_s)

        _scan_ssa(fn_nd)
        for did_a, cnt_a in assign_counts.items():
            if cnt_a == 1 and did_a in uninit_decl_ids and did_a not in mutated_ids:
                ssa_decls.append((did_a, single_assign_rhs[did_a]))
            elif cnt_a >= 1 and did_a not in uninit_decl_ids:
                mutated_ids.add(did_a)
        loc_i: Dict[int, int] = {}
        loc_b: Dict[int, bytes] = {}
        for _ in range(24):
            prog = False
            for did, init_n in ssa_decls:
                if did in mutated_ids:
                    continue
                if did not in loc_b:
                    bv = _ast_extract_bytes(init_n, loc_ints=loc_i, loc_bytes=loc_b)
                    if bv is not None:
                        loc_b[did] = bv
                        prog = True
                if did not in loc_i:
                    iv = _resolve_ast_int(init_n, loc_ints=loc_i, loc_bytes=loc_b)
                    if iv is not None:
                        loc_i[did] = iv
                        prog = True
            if not prog:
                break
        return loc_i, loc_b

    _non_action_bare_ast = frozenset({
        "gasleft", "keccak256", "sha256", "ripemd160", "ecrecover", "addmod", "mulmod",
        "require", "assert", "revert", "type", "payable",
    }) | _CANONICAL_ALL_PROTECTED_FNS

    def _ast_is_readonly_fn_type(ts: str) -> bool:
        if not ts.startswith("function ("):
            return False
        depth_p = 0
        close_idx = -1
        for idx_p in range(len("function "), len(ts)):
            ch_p = ts[idx_p]
            if ch_p == "(":
                depth_p += 1
            elif ch_p == ")":
                depth_p -= 1
                if depth_p == 0:
                    close_idx = idx_p
                    break
        if close_idx < 0:
            return False
        tail_mut = ts[close_idx + 1 :].split(" returns ", 1)[0]
        mut_toks = tail_mut.split()
        return ("view" in mut_toks) or ("pure" in mut_toks)

    def _ast_stmt_has_external_action(node: Any, _depth: int = 0) -> bool:
        if _depth > 64:
            return True
        if isinstance(node, list):
            return any(_ast_stmt_has_external_action(it, _depth + 1) for it in node if isinstance(it, (dict, list)))
        if not isinstance(node, dict):
            return False
        s_nt = node.get("nodeType")
        if s_nt == "NewExpression":
            return True
        if s_nt == "FunctionCall" and str(node.get("kind") or "") == "functionCall":
            ex_a = node.get("expression") or {}
            has_value_opt = False
            while isinstance(ex_a, dict) and ex_a.get("nodeType") == "FunctionCallOptions":
                if "value" in (ex_a.get("names") or ()):
                    has_value_opt = True
                ex_a = ex_a.get("expression") or {}
            if has_value_opt:
                return True
            ex_ts = str((ex_a.get("typeDescriptions") or {}).get("typeString") or "")
            # EVM compiles view/pure calls to STATICCALL (or pure local execution): zero state mutation possible.
            is_readonly_fn_type = _ast_is_readonly_fn_type(ex_ts)
            if ex_a.get("nodeType") == "MemberAccess":
                m_a = str(ex_a.get("memberName") or "")
                rv_a = ex_a.get("expression") or {}
                rv_nm = str(rv_a.get("name") or "") if rv_a.get("nodeType") == "Identifier" else ""
                rv_ts = str((rv_a.get("typeDescriptions") or {}).get("typeString") or "")
                if (
                    rv_nm == "abi"
                    or m_a == "staticcall"
                    or (rv_nm == "vm" and m_a in ("stopPrank", "recordLogs", "assume"))
                    or (rv_a.get("nodeType") == "ElementaryTypeNameExpression" and m_a == "concat")
                    or (is_readonly_fn_type and not _is_vm_type(rv_ts))
                ):
                    pass
                else:
                    return True
            elif ex_a.get("nodeType") == "Identifier":
                fn_a = str(ex_a.get("name") or "")
                if fn_a and fn_a not in _non_action_bare_ast and not is_readonly_fn_type:
                    return True
            elif not is_readonly_fn_type:
                return True
        return any(
            _ast_stmt_has_external_action(v, _depth + 1)
            for v in node.values()
            if isinstance(v, (dict, list))
        )

    def _ast_stmt_declares_var_name(stmt: Any, var_name: str) -> bool:
        if not isinstance(stmt, dict) or stmt.get("nodeType") != "VariableDeclarationStatement":
            return False
        return any(
            isinstance(d, dict) and str(d.get("name") or "") == var_name
            for d in (stmt.get("declarations") or ())
        )

    def _ast_contains_gas_liq_add(node: Any, _depth: int = 0) -> bool:
        if _depth > 64:
            return False
        if isinstance(node, list):
            return any(_ast_contains_gas_liq_add(it, _depth + 1) for it in node if isinstance(it, (dict, list)))
        if not isinstance(node, dict):
            return False
        if node.get("nodeType") == "Assignment" and str(node.get("operator") or "") == "+=":
            lh = node.get("leftHandSide") or {}
            rh = node.get("rightHandSide") or {}
            if (
                lh.get("nodeType") == "Identifier"
                and str(lh.get("name") or "") == "gasUsed"
                and rh.get("nodeType") == "Identifier"
                and str(rh.get("name") or "") == "liqGasUsed"
            ):
                return True
        return any(
            _ast_contains_gas_liq_add(v, _depth + 1)
            for v in node.values()
            if isinstance(v, (dict, list))
        )

    def _walk_expr_and_stmts(
        nd: Any,
        *,
        c_kind: str,
        c_name: str,
        is_harness: bool,
        fn_name: str,
        state_var_ids: FrozenSet[int],
        snap_ids: Set[int],
        nft_snap_ids: Set[int],
        liq_arr_ids: Set[int],
        gas_ids: Set[int],
        loc_ints: Dict[int, int],
        loc_bytes: Dict[int, bytes],
        in_branch: bool,
        assert_counts: List[int],
    ) -> None:
        if isinstance(nd, list):
            for it in nd:
                if isinstance(it, (dict, list)):
                    _walk_expr_and_stmts(
                        it,
                        c_kind=c_kind,
                        c_name=c_name,
                        is_harness=is_harness,
                        fn_name=fn_name,
                        state_var_ids=state_var_ids,
                        snap_ids=snap_ids,
                        nft_snap_ids=nft_snap_ids,
                        liq_arr_ids=liq_arr_ids,
                        gas_ids=gas_ids,
                        loc_ints=loc_ints,
                        loc_bytes=loc_bytes,
                        in_branch=in_branch,
                        assert_counts=assert_counts,
                    )
            return
        if not isinstance(nd, dict):
            return
        nt = nd.get("nodeType")
        if nt == "InlineAssembly":
            if is_harness or not c_kind:
                violations.append(
                    "ast_disallowed_harness_assembly" if is_harness else f"ast_disallowed_file_level_fn:{fn_name}"
                )
            _check_yul_ast(nd.get("AST"), is_harness)
            return
        if nt == "MemberAccess" and str(nd.get("memberName") or "") == "codehash":
            violations.append("ast_disallowed_codehash")
        elif nt == "NewExpression":
            tn_new = nd.get("typeName") or {}
            nm_new = str(tn_new.get("name") or (tn_new.get("pathNode") or {}).get("name") or "")
            if nm_new.startswith(("Verify_", "AgentVerify_")):
                violations.append(f"ast_disallowed_harness_instantiation:{nm_new}")
        elif nt == "EmitStatement":
            ec = nd.get("eventCall") or {}
            ex_e = ec.get("expression") or {}
            ev_nm = str(ex_e.get("name") or ex_e.get("memberName") or "")
            if ev_nm.startswith("Conservation"):
                if not c_kind:
                    violations.append(f"ast_disallowed_file_level_fn:{fn_name}")
                elif (not is_harness) or c_kind == "library":
                    violations.append(f"ast_disallowed_helper_conservation_emit:{ev_nm}")
                elif strict_agent_accounting and fn_name not in _CANONICAL_HARNESS_FN_NAMES:
                    violations.append(f"ast_disallowed_direct_conservation_emit:{ev_nm}")
        elif nt == "VariableDeclaration":
            vd_ts = str((nd.get("typeDescriptions") or {}).get("typeString") or "")
            vd_nm = str(nd.get("name") or "")
            vd_id = nd.get("id")
            is_canon_vm = bool(
                _is_vm_type(vd_ts)
                and is_harness
                and c_kind == "contract"
                and isinstance(vd_id, int)
                and vd_id in state_var_ids
                and bool(nd.get("constant"))
                and vd_nm == "vm"
                and _is_hevm_int(_resolve_ast_int(nd.get("value"), loc_ints=loc_ints, loc_bytes=loc_bytes))
            )
            if is_canon_vm:
                return
            if _is_vm_type(vd_ts):
                violations.append(f"ast_disallowed_vm_alias:{vd_nm or 'anon'}")
        elif nt == "FunctionCall":
            fc_kind = str(nd.get("kind") or "")
            fc_expr = nd.get("expression") or {}
            fc_args = nd.get("arguments") or []
            fc_ts = str((nd.get("typeDescriptions") or {}).get("typeString") or "")
            if fc_kind == "typeConversion":
                if is_harness and len(fc_args) == 1 and isinstance(fc_args[0], dict):
                    if fc_args[0].get("nodeType") == "Identifier" and fc_args[0].get("name") == "this":
                        violations.append("ast_disallowed_harness_self_ref")
            elif fc_kind == "structConstructorCall" and strict_agent_accounting and is_harness and fn_name not in _CANONICAL_ALL_PROTECTED_FNS:
                if _is_snap_type(fc_ts, "ConservationSnap") or _is_snap_type(fc_ts, "NftSnap"):
                    violations.append("ast_forged_snap_struct_ctor")
            elif fc_kind == "functionCall":
                if fc_expr.get("nodeType") == "MemberAccess":
                    recv = fc_expr.get("expression") or {}
                    recv_ts = str((recv.get("typeDescriptions") or {}).get("typeString") or "")
                    m_nm = str(fc_expr.get("memberName") or "")
                    if recv.get("nodeType") == "Identifier" and str(recv.get("name") or "") in ("console", "console2"):
                        violations.append("ast_disallowed_console_call")
                    if _is_vm_type(recv_ts) or _is_hevm_int(_resolve_ast_int(recv, loc_ints=loc_ints, loc_bytes=loc_bytes)):
                        if not c_kind:
                            violations.append(f"ast_disallowed_file_level_fn:{fn_name}")
                        elif (not is_harness) or c_kind == "library":
                            violations.append(f"ast_disallowed_vm_in_helper:{c_name}:{m_nm}")
                        elif m_nm in ("call", "staticcall", "delegatecall", "callcode"):
                            violations.append(f"ast_disallowed_lowlevel_vm_call:{m_nm}")
                        elif forbid_inline_fork and m_nm in _INLINE_FORK_CALLS:
                            violations.append(f"ast_disallowed_inline_fork:{m_nm}")
                        elif m_nm not in ALLOWED_VM_CALLS:
                            violations.append(f"ast_disallowed_vm_call:{m_nm}")
                        elif m_nm in ("prank", "startPrank"):
                            if forbid_inline_fork and len(fc_args) != 2:
                                violations.append("ast_disallowed_single_arg_prank")
                            if norm_c0_int is not None:
                                for a_p in fc_args:
                                    if _resolve_ast_int(a_p, loc_ints=loc_ints, loc_bytes=loc_bytes) != norm_c0_int:
                                        violations.append("ast_disallowed_prank_caller")
                                        break
                        elif m_nm == "signAndAttachDelegation":
                            if len(fc_args) != 2:
                                violations.append("ast_disallowed_delegation_arity")
                            elif norm_c0:
                                impl_i = _resolve_ast_int(fc_args[0], loc_ints=loc_ints, loc_bytes=loc_bytes)
                                if impl_i is not None and impl_i in _SOLC_AST_FORB_DEL_IMPLS:
                                    violations.append("ast_disallowed_delegation_impl")
                                pk_i = _resolve_ast_int(fc_args[1], loc_ints=loc_ints, loc_bytes=loc_bytes)
                                if pk_i is None or pk_i <= 0 or _secp256k1_privkey_to_eth_addr(pk_i) != norm_c0:
                                    violations.append("ast_disallowed_delegation_authority")
                elif fc_expr.get("nodeType") == "Identifier":
                    callee_nm = str(fc_expr.get("name") or "")
                    if callee_nm == "selfdestruct":
                        violations.append("ast_disallowed_selfdestruct")
                    if (
                        strict_agent_accounting
                        and is_harness
                        and fn_name not in _CANONICAL_ALL_PROTECTED_FNS
                        and callee_nm in ("_assertConservation", "_assertConservationLiq")
                    ):
                        assert_counts[1 if in_branch else 0] += 1

        if nt == "Literal" and str(nd.get("kind") or "") == "hexString":
            hv_l = str(nd.get("hexValue") or "").lower()
            h_pos = hv_l.find(_hevm_hex40)
            if h_pos >= 0 and (h_pos % 2 == 0):
                violations.append("ast_disallowed_hevm_addr_ref")
        if nt == "FunctionCall":
            ext_b_chk = _ast_extract_bytes(nd, loc_ints=loc_ints, loc_bytes=loc_bytes)
            if ext_b_chk is not None and _hevm_bytes20 in ext_b_chk:
                violations.append("ast_disallowed_hevm_addr_ref")
        if nt in ("Literal", "BinaryOperation", "UnaryOperation", "FunctionCall") and _is_hevm_int(
            _resolve_ast_int(nd, loc_ints=loc_ints, loc_bytes=loc_bytes)
        ):
            violations.append("ast_disallowed_hevm_addr_ref")

        if strict_agent_accounting and is_harness and c_kind == "contract" and fn_name not in _CANONICAL_ALL_PROTECTED_FNS:
            prot_ref_ids = snap_ids | nft_snap_ids | liq_arr_ids
            if nt == "VariableDeclarationStatement":
                init_v = nd.get("initialValue")
                decls_v = [d for d in (nd.get("declarations") or ()) if isinstance(d, dict)]
                has_non_prot_decl = False
                for decl_v in decls_v:
                    d_id = decl_v.get("id")
                    d_nm = str(decl_v.get("name") or "")
                    if isinstance(d_id, int) and d_id in snap_ids:
                        ok_sn = False
                        if isinstance(init_v, dict) and init_v.get("nodeType") == "FunctionCall":
                            ie = init_v.get("expression") or {}
                            ia = init_v.get("arguments") or []
                            if ie.get("nodeType") == "Identifier" and ie.get("name") == "_takeSnap" and len(ia) == 1:
                                ok_sn = (norm_c0_int is None) or (
                                    _resolve_ast_int(ia[0], loc_ints=loc_ints, loc_bytes=loc_bytes) == norm_c0_int
                                )
                        if not ok_sn:
                            violations.append(f"ast_tampered_snap_init:{d_nm}")
                    elif isinstance(d_id, int) and d_id in nft_snap_ids:
                        ok_nsn = (
                            isinstance(init_v, dict)
                            and init_v.get("nodeType") == "FunctionCall"
                            and (init_v.get("expression") or {}).get("nodeType") == "Identifier"
                            and (init_v.get("expression") or {}).get("name") == "_takeNftSnap"
                        )
                        if not ok_nsn:
                            violations.append(f"ast_tampered_nft_snap_init:{d_nm}")
                    elif isinstance(d_id, int) and d_id in gas_ids:
                        if d_nm in ("gasStart", "liqGasStart"):
                            ok_gas_init = bool(len(decls_v) == 1 and _ast_is_gasleft_call(init_v))
                        else:
                            exp_start = "gasStart" if d_nm == "gasUsed" else "liqGasStart"
                            ok_gas_init = bool(
                                len(decls_v) == 1 and _ast_is_valid_gas_used_init(init_v, exp_start, gas_ids)
                            )
                        if not ok_gas_init:
                            violations.append(f"ast_tampered_gas_init:{d_nm}")
                    elif not (isinstance(d_id, int) and d_id in prot_ref_ids):
                        has_non_prot_decl = True
                if has_non_prot_decl and init_v is not None and _ast_expr_escapes_protected_ref(init_v, prot_ref_ids):
                    violations.append("ast_forbidden_protected_ref_escape")
            elif nt == "UnaryOperation":
                u_op = str(nd.get("operator") or "")
                r_ids = _ast_all_root_decl_ids(nd.get("subExpression"))
                if r_ids:
                    prot_ids = prot_ref_ids | gas_ids
                    if u_op == "delete" and (r_ids & prot_ids):
                        violations.append("ast_forbidden_delete_protected")
                    elif u_op in ("++", "--") and (r_ids & prot_ids):
                        violations.append("ast_forbidden_snap_or_liq_mutation")
            elif nt == "Assignment":
                lhs_a = nd.get("leftHandSide")
                rhs_a = nd.get("rightHandSide")
                if _ast_expr_escapes_protected_ref(rhs_a, prot_ref_ids):
                    violations.append("ast_forbidden_protected_ref_escape")
                r_ids = _ast_all_root_decl_ids(lhs_a)
                if r_ids:
                    if r_ids & (snap_ids | nft_snap_ids):
                        violations.append("ast_forbidden_snap_mutation")
                    if r_ids & liq_arr_ids:
                        violations.append("ast_forbidden_liq_array_mutation")
                    if r_ids & gas_ids:
                        is_canon_liq_add = bool(
                            str(nd.get("operator") or "") == "+="
                            and isinstance(lhs_a, dict)
                            and lhs_a.get("nodeType") == "Identifier"
                            and str(lhs_a.get("name") or "") == "gasUsed"
                            and isinstance(rhs_a, dict)
                            and rhs_a.get("nodeType") == "Identifier"
                            and str(rhs_a.get("name") or "") == "liqGasUsed"
                            and isinstance(rhs_a.get("referencedDeclaration"), int)
                            and int(rhs_a["referencedDeclaration"]) in gas_ids
                        )
                        if not is_canon_liq_add:
                            violations.append("ast_forbidden_gas_mutation")
            elif nt == "Return":
                if _ast_expr_escapes_protected_ref(nd.get("expression"), prot_ref_ids):
                    violations.append("ast_forbidden_protected_ref_escape")
            elif nt == "FunctionCall" and str(nd.get("kind") or "") == "functionCall":
                fc_e_p = nd.get("expression") or {}
                is_canon_consumer = bool(
                    fc_e_p.get("nodeType") == "Identifier"
                    and str(fc_e_p.get("name") or "") in _SOLC_AST_CANON_PROT_CONSUMERS
                )
                if not is_canon_consumer:
                    if any(_ast_expr_escapes_protected_ref(a_p, prot_ref_ids) for a_p in (nd.get("arguments") or ())):
                        violations.append("ast_forbidden_protected_ref_escape")
                    elif fc_e_p.get("nodeType") == "MemberAccess" and _ast_expr_escapes_protected_ref(
                        fc_e_p.get("expression"), prot_ref_ids
                    ):
                        violations.append("ast_forbidden_protected_ref_escape")

        next_branch = in_branch or (nt in _SOLC_AST_BRANCH_NODES)
        for v in nd.values():
            if isinstance(v, (dict, list)):
                _walk_expr_and_stmts(
                    v,
                    c_kind=c_kind,
                    c_name=c_name,
                    is_harness=is_harness,
                    fn_name=fn_name,
                    state_var_ids=state_var_ids,
                    snap_ids=snap_ids,
                    nft_snap_ids=nft_snap_ids,
                    liq_arr_ids=liq_arr_ids,
                    gas_ids=gas_ids,
                    loc_ints=loc_ints,
                    loc_bytes=loc_bytes,
                    in_branch=next_branch,
                    assert_counts=assert_counts,
                )

    def _collect_fn_var_ids(
        fn_nd: Any,
        snap_ids: Set[int],
        nft_snap_ids: Set[int],
        liq_arr_ids: Set[int],
        gas_ids: Set[int],
        gas_name_counts: Optional[Dict[str, int]] = None,
    ) -> None:
        if isinstance(fn_nd, dict):
            if fn_nd.get("nodeType") == "VariableDeclaration" and isinstance(fn_nd.get("id"), int):
                vid = int(fn_nd["id"])
                vnm = str(fn_nd.get("name") or "")
                vts = str((fn_nd.get("typeDescriptions") or {}).get("typeString") or "")
                if _is_snap_type(vts, "ConservationSnap"):
                    snap_ids.add(vid)
                elif _is_snap_type(vts, "NftSnap"):
                    nft_snap_ids.add(vid)
                if vnm in ("liqCredit", "liqDebited"):
                    liq_arr_ids.add(vid)
                if vnm in _SOLC_AST_GAS_VAR_NAMES:
                    gas_ids.add(vid)
                    if gas_name_counts is not None:
                        gas_name_counts[vnm] = gas_name_counts.get(vnm, 0) + 1
            for v in fn_nd.values():
                if isinstance(v, (dict, list)):
                    _collect_fn_var_ids(v, snap_ids, nft_snap_ids, liq_arr_ids, gas_ids, gas_name_counts)
        elif isinstance(fn_nd, list):
            for it in fn_nd:
                if isinstance(it, (dict, list)):
                    _collect_fn_var_ids(it, snap_ids, nft_snap_ids, liq_arr_ids, gas_ids, gas_name_counts)

    # Pre-compute harness and assert-fn status across non-interface inheritance chains (`linearizedBaseContracts`)
    non_iface_contracts_by_id: Dict[int, Dict[str, Any]] = {}
    direct_assert_fn_ids: Set[int] = set()
    direct_harness_ids: Set[int] = set()
    for _c_nd in (ast_root.get("nodes") or ()):
        if not isinstance(_c_nd, dict) or _c_nd.get("nodeType") != "ContractDefinition":
            continue
        _ck0 = str(_c_nd.get("contractKind") or "")
        if _ck0 == "interface":
            continue
        _cid0 = _c_nd.get("id")
        if not isinstance(_cid0, int):
            continue
        non_iface_contracts_by_id[_cid0] = _c_nd
        _cn0 = str(_c_nd.get("name") or "")
        _cnodes0 = [x for x in (_c_nd.get("nodes") or ()) if isinstance(x, dict)]
        _hpt0 = any(
            x.get("nodeType") == "FunctionDefinition"
            and str(x.get("name") or "").startswith("test")
            and str(x.get("visibility") or "") in ("public", "external")
            for x in _cnodes0
        )
        _haf0 = any(
            x.get("nodeType") == "FunctionDefinition"
            and str(x.get("name") or "") in ("_assertConservation", "_assertConservationLiq")
            for x in _cnodes0
        )
        if _haf0:
            direct_assert_fn_ids.add(_cid0)
        if _ck0 == "library" or _cn0.startswith(("Verify_", "AgentVerify_")) or _hpt0:
            direct_harness_ids.add(_cid0)
    effective_harness_ids: Set[int] = set(direct_harness_ids)
    effective_assert_fn_ids: Set[int] = set(direct_assert_fn_ids)
    for _cid0, _c_nd in non_iface_contracts_by_id.items():
        _lin0 = [
            int(bid)
            for bid in (_c_nd.get("linearizedBaseContracts") or ())
            if isinstance(bid, int) and int(bid) in non_iface_contracts_by_id
        ]
        if any(bid in direct_assert_fn_ids for bid in _lin0):
            effective_assert_fn_ids.add(_cid0)
        if _cid0 in direct_harness_ids or any(bid in direct_harness_ids for bid in _lin0):
            effective_harness_ids.add(_cid0)
            effective_harness_ids.update(_lin0)

    for top_nd in (ast_root.get("nodes") or ()):
        if not isinstance(top_nd, dict):
            continue
        t_nt = top_nd.get("nodeType")
        if t_nt == "ImportDirective":
            violations.append("ast_disallowed_external_import")
        elif t_nt == "UsingForDirective":
            _check_using_directive(top_nd)
        elif t_nt == "FunctionDefinition":
            fl_nm = str(top_nd.get("name") or "")
            fl_li, fl_lb = _collect_fn_ssa_consts(top_nd)
            _walk_expr_and_stmts(
                top_nd,
                c_kind="",
                c_name="",
                is_harness=False,
                fn_name=fl_nm,
                state_var_ids=frozenset(),
                snap_ids=set(),
                nft_snap_ids=set(),
                liq_arr_ids=set(),
                gas_ids=set(),
                loc_ints=fl_li,
                loc_bytes=fl_lb,
                in_branch=False,
                assert_counts=[0, 0],
            )
        elif t_nt == "ContractDefinition":
            ck = str(top_nd.get("contractKind") or "")
            cn = str(top_nd.get("name") or "")
            c_nodes = [x for x in (top_nd.get("nodes") or ()) if isinstance(x, dict)]
            if ck == "interface":
                continue
            cid_top = top_nd.get("id")
            has_pub_test = any(
                x.get("nodeType") == "FunctionDefinition"
                and str(x.get("name") or "").startswith("test")
                and str(x.get("visibility") or "") in ("public", "external")
                for x in c_nodes
            )
            has_assert_fn = bool(
                any(
                    x.get("nodeType") == "FunctionDefinition"
                    and str(x.get("name") or "") in ("_assertConservation", "_assertConservationLiq")
                    for x in c_nodes
                )
                or (isinstance(cid_top, int) and cid_top in effective_assert_fn_ids)
            )
            is_h = bool(
                ck == "library"
                or cn.startswith(("Verify_", "AgentVerify_"))
                or has_pub_test
                or (isinstance(cid_top, int) and cid_top in effective_harness_ids)
            )
            if strict_agent_accounting and is_h and ck == "contract" and (top_nd.get("baseContracts") or ()):
                violations.append(f"ast_disallowed_harness_inheritance:{cn}")
            st_var_ids = frozenset(
                int(x["id"]) for x in c_nodes if x.get("nodeType") == "VariableDeclaration" and isinstance(x.get("id"), int)
            )
            st_snap_ids: Set[int] = set()
            st_nft_ids: Set[int] = set()
            st_liq_ids: Set[int] = set()
            st_gas_ids: Set[int] = set()
            for cn_item in c_nodes:
                i_nt = cn_item.get("nodeType")
                if i_nt == "UsingForDirective":
                    _check_using_directive(cn_item)
                elif i_nt == "ModifierDefinition" and is_h:
                    violations.append(f"ast_disallowed_harness_modifier:{cn_item.get('name') or ''}")
                elif i_nt == "VariableDeclaration":
                    v_id = cn_item.get("id")
                    v_nm = str(cn_item.get("name") or "")
                    v_ts = str((cn_item.get("typeDescriptions") or {}).get("typeString") or "")
                    if is_h and cn_item.get("value") is not None and not bool(cn_item.get("constant")):
                        violations.append(f"ast_disallowed_harness_state_init:{v_nm}")
                    if strict_agent_accounting and is_h and isinstance(v_id, int):
                        if _is_snap_type(v_ts, "ConservationSnap") or _is_snap_type(v_ts, "NftSnap"):
                            violations.append(f"ast_forbidden_state_snap_var:{v_nm}")
                            (st_snap_ids if _is_snap_type(v_ts, "ConservationSnap") else st_nft_ids).add(int(v_id))
                        if v_nm in ("liqCredit", "liqDebited"):
                            st_liq_ids.add(int(v_id))
                        if v_nm in _SOLC_AST_GAS_VAR_NAMES:
                            st_gas_ids.add(int(v_id))
                    _walk_expr_and_stmts(
                        cn_item,
                        c_kind=ck,
                        c_name=cn,
                        is_harness=is_h,
                        fn_name="",
                        state_var_ids=st_var_ids,
                        snap_ids=st_snap_ids,
                        nft_snap_ids=st_nft_ids,
                        liq_arr_ids=st_liq_ids,
                        gas_ids=st_gas_ids,
                        loc_ints={},
                        loc_bytes={},
                        in_branch=False,
                        assert_counts=[0, 0],
                    )
                elif i_nt == "FunctionDefinition":
                    f_nm = str(cn_item.get("name") or "")
                    f_kind = str(cn_item.get("kind") or "function")
                    f_vis = str(cn_item.get("visibility") or "")
                    f_params = (cn_item.get("parameters") or {}).get("parameters") or []
                    if ck == "contract" and f_vis in ("public", "external"):
                        if f_nm == "setUp":
                            violations.append("ast_disallowed_setup_fn")
                        elif f_nm.lower().startswith("invariant"):
                            violations.append("ast_disallowed_invariant_fn")
                        elif f_nm.lower().startswith("testfail"):
                            violations.append("ast_disallowed_testfail_fn")
                        elif f_nm.startswith("test") and len(f_params) > 0:
                            violations.append(f"ast_disallowed_parameterized_test:{f_nm}")
                    if is_h:
                        if f_kind == "constructor":
                            violations.append("ast_disallowed_harness_constructor")
                        elif ck != "library" and f_kind in ("receive", "fallback"):
                            violations.append("ast_disallowed_harness_callback")
                    loc_snap = set(st_snap_ids)
                    loc_nft = set(st_nft_ids)
                    loc_liq = set(st_liq_ids)
                    loc_gas = set(st_gas_ids)
                    gas_nm_counts: Dict[str, int] = {}
                    if strict_agent_accounting and is_h and ck == "contract" and f_nm not in _CANONICAL_ALL_PROTECTED_FNS:
                        _collect_fn_var_ids(cn_item, loc_snap, loc_nft, loc_liq, loc_gas, gas_nm_counts)
                        for g_nm_dup, g_cnt_dup in gas_nm_counts.items():
                            if g_cnt_dup > 1:
                                violations.append(f"ast_disallowed_gas_var_shadow:{f_nm}:{g_nm_dup}")
                    fn_li, fn_lb = _collect_fn_ssa_consts(cn_item)
                    a_cnts = [0, 0]
                    _walk_expr_and_stmts(
                        cn_item,
                        c_kind=ck,
                        c_name=cn,
                        is_harness=is_h,
                        fn_name=f_nm,
                        state_var_ids=st_var_ids,
                        snap_ids=loc_snap,
                        nft_snap_ids=loc_nft,
                        liq_arr_ids=loc_liq,
                        gas_ids=loc_gas,
                        loc_ints=fn_li,
                        loc_bytes=fn_lb,
                        in_branch=False,
                        assert_counts=a_cnts,
                    )
                    if strict_agent_accounting and is_h and ck == "contract" and f_nm not in _CANONICAL_ALL_PROTECTED_FNS:
                        if a_cnts[1] > 0:
                            violations.append(f"ast_conditional_or_loop_assert_conservation:{f_nm}")
                        if a_cnts[0] > 1:
                            violations.append(f"ast_multi_assert_conservation:{f_nm}")
                        if (
                            has_assert_fn
                            and f_nm.startswith("test")
                            and f_vis in ("public", "external")
                            and str(cn_item.get("stateMutability") or "") not in ("view", "pure")
                        ):
                            if a_cnts[0] == 0 and a_cnts[1] == 0:
                                violations.append(f"ast_missing_top_level_assert_conservation:{f_nm}")
                            top_stmts = ((cn_item.get("body") or {}).get("statements") or ())
                            idx_gs = next((i_s for i_s, st in enumerate(top_stmts) if _ast_stmt_declares_var_name(st, "gasStart")), -1)
                            idx_gu = next((i_s for i_s, st in enumerate(top_stmts) if _ast_stmt_declares_var_name(st, "gasUsed")), -1)
                            idx_lgs = next((i_s for i_s, st in enumerate(top_stmts) if _ast_stmt_declares_var_name(st, "liqGasStart")), -1)
                            idx_lgu = next((i_s for i_s, st in enumerate(top_stmts) if _ast_contains_gas_liq_add(st)), -1)
                            if idx_gs < 0 or idx_gu < 0 or idx_gu <= idx_gs:
                                violations.append(f"ast_gas_window_order_invalid:{f_nm}")
                            else:
                                if any(_ast_stmt_has_external_action(st) for st in top_stmts[:idx_gs]):
                                    violations.append(f"ast_action_outside_gas_window:{f_nm}")
                                if idx_lgs < 0:
                                    if idx_lgu >= 0:
                                        violations.append(f"ast_gas_window_order_invalid:{f_nm}")
                                    if any(_ast_stmt_has_external_action(st) for st in top_stmts[idx_gu + 1 :]):
                                        violations.append(f"ast_action_outside_gas_window:{f_nm}")
                                else:
                                    if idx_lgs <= idx_gu or idx_lgu < 0 or idx_lgu <= idx_lgs:
                                        violations.append(f"ast_gas_window_order_invalid:{f_nm}")
                                    else:
                                        if any(_ast_stmt_has_external_action(st) for st in top_stmts[idx_gu + 1 : idx_lgs]):
                                            violations.append(f"ast_action_outside_gas_window:{f_nm}")
                                        if any(_ast_stmt_has_external_action(st) for st in top_stmts[idx_lgu + 1 :]):
                                            violations.append(f"ast_action_outside_gas_window:{f_nm}")

    dedup = tuple(dict.fromkeys(violations))
    return (len(dedup) == 0), dedup


_SOLC_AST_NONCACHEABLE_ERRORS: FrozenSet[str] = frozenset({
    "ast_solc_binary_missing",
    "ast_solc_exec_failed",
    "ast_solc_empty_ast",
})
_SOLC_AST_CACHE: Dict[Tuple[str, str, bool, bool], Tuple[bool, Tuple[str, ...]]] = {}
_SOLC_AST_CACHE_LOCK = threading.Lock()
_SOLC_AST_INFLIGHT: Dict[Tuple[str, str, bool, bool], threading.Event] = {}
_SOLC_AST_SEM = threading.BoundedSemaphore(2)


def verify_solidity_formal_ast(
    sol_code: str,
    *,
    allowed_caller: str = "",
    forbid_inline_fork: bool = False,
    strict_agent_accounting: bool = False,
) -> Tuple[bool, List[str]]:
    """`solc.exe --standard-json` 컴파일러 AST 기반 형식 불변식 검증의 외부 진입점(싱글플라이트+동시성 제한+일시 오류 비캐시)."""
    code_s = str(sol_code or "")
    if not code_s:
        return True, []
    if not SOLC_BIN.is_file():
        return False, ["ast_solc_binary_missing"]
    cache_key = (code_s, str(allowed_caller or ""), bool(forbid_inline_fork), bool(strict_agent_accounting))
    while True:
        with _SOLC_AST_CACHE_LOCK:
            hit = _SOLC_AST_CACHE.get(cache_key)
            if hit is not None:
                return hit[0], list(hit[1])
            ev_wait = _SOLC_AST_INFLIGHT.get(cache_key)
            if ev_wait is None:
                ev_own = threading.Event()
                _SOLC_AST_INFLIGHT[cache_key] = ev_own
                break
        ev_wait.wait(timeout=30.0)
    try:
        ok, viols = _verify_solidity_formal_ast_cached(*cache_key)
        if not any(v in _SOLC_AST_NONCACHEABLE_ERRORS for v in viols):
            with _SOLC_AST_CACHE_LOCK:
                if len(_SOLC_AST_CACHE) >= 256:
                    _SOLC_AST_CACHE.pop(next(iter(_SOLC_AST_CACHE)), None)
                _SOLC_AST_CACHE[cache_key] = (ok, viols)
        return ok, list(viols)
    finally:
        with _SOLC_AST_CACHE_LOCK:
            _SOLC_AST_INFLIGHT.pop(cache_key, None)
        ev_own.set()


def _parse_json_dict_lines(text: str) -> List[Dict[str, Any]]:
    out_objs: List[Dict[str, Any]] = []
    for line in (text or "").splitlines():
        ls = line.strip()
        if not ls.startswith("{"):
            continue
        try:
            obj = json.loads(ls)
        except _PARSE_DATA_EXC:
            continue
        if isinstance(obj, dict):
            out_objs.append(obj)
    return out_objs


def _parse_forge_json_gains(
    stdout_text: str,
    *,
    parsed_objs: Optional[Sequence[Dict[str, Any]]] = None,
    nft_gains_out: Optional[List[Dict[str, Any]]] = None,
) -> Tuple[int, int, List[Dict[str, Any]]]:
    """
    forge test --json 출력에서 decoded_logs 및 raw logs(CONSERVATION_GAIN_TOPIC0 / CONSERVATION_SUPPLY_MINT_TOPIC0 / CONSERVATION_NFT_GAIN_TOPIC0)를 모두 파싱하여
    (passed, failed, structured_gains) 반환.
    """
    passed = 0
    failed = 0
    gains: List[Dict[str, Any]] = []
    seen_keys: Set[Tuple[str, int, str, int]] = set()
    seen_nft_keys: Set[Tuple[str, int, str, int, bool]] = set()
    minted_pairs: Set[Tuple[str, int, str]] = set()
    minted_wnative_slices: Set[Tuple[str, int]] = set()
    bridges_by_test: Dict[str, List[Dict[str, Any]]] = {}
    nft_bridges_by_test: Dict[str, List[Dict[str, Any]]] = {}
    atomic_exits_by_test: Dict[str, List[Dict[str, Any]]] = {}
    topic0_target = CONSERVATION_GAIN_TOPIC0.lower()
    mint_topic0_target = CONSERVATION_SUPPLY_MINT_TOPIC0.lower()
    bridge_topic0_target = CONSERVATION_BRIDGE_TOPIC0.lower()
    nft_bridge_topic0_target = CONSERVATION_NFT_BRIDGE_TOPIC0.lower()
    atomic_exit_topic0_target = CONSERVATION_ATOMIC_EXIT_TOPIC0.lower()
    nft_topic0_target = CONSERVATION_NFT_GAIN_TOPIC0.lower()
    zero_addr = "0x0000000000000000000000000000000000000000"

    def _to_asset_key(raw_addr: Any) -> str:
        na = _norm_addr(raw_addr)
        return "native" if (not na or na == zero_addr) else na

    def _record_gain(t_str: str, s_idx: int, asset_key: str, c_gain: int, v_loss: int, g_used: int) -> None:
        dedup_k = (t_str, s_idx, asset_key, c_gain)
        if dedup_k not in seen_keys:
            seen_keys.add(dedup_k)
            gains.append(
                {
                    "test": t_str,
                    "slice_idx": s_idx,
                    "asset": asset_key,
                    "caller_gain": c_gain,
                    "vault_loss": v_loss,
                    "gas_used": g_used,
                    "supply_mint": (t_str, s_idx, asset_key) in minted_pairs,
                }
            )

    objs_iter = parsed_objs if parsed_objs is not None else _parse_json_dict_lines(stdout_text)
    for obj in objs_iter:
        for _, suite_val in obj.items():
            if not isinstance(suite_val, dict) or "test_results" not in suite_val:
                continue
            for tname, tres in (suite_val.get("test_results") or {}).items():
                if not isinstance(tres, dict):
                    continue
                t_str = str(tname)
                if str(tres.get("status") or "") == "Success":
                    passed += 1
                else:
                    failed += 1
                    continue
                raw_logs_val = tres.get("logs")
                spoofed_log_keys: Set[Tuple[str, int, str]] = set()
                for rlog in (raw_logs_val or []):
                    if not isinstance(rlog, dict):
                        continue
                    inner = rlog.get("log") if isinstance(rlog.get("log"), dict) else rlog
                    emitter_addr = _norm_addr(inner.get("address") or rlog.get("address") or "")
                    emitter_ok = (emitter_addr == FOUNDRY_TEST_CONTRACT)
                    topics = inner.get("topics") or []
                    data_hex = str(inner.get("data") or "")
                    if topics and str(topics[0]).lower() == mint_topic0_target and len(data_hex) >= 2 + 64 * 3:
                        try:
                            m_s_idx, m_asset_addr, m_sinc = abi_decode(
                                ["uint256", "address", "uint256"], data_hex
                            )
                            m_key = _to_asset_key(m_asset_addr)
                            if not emitter_ok:
                                spoofed_log_keys.add(("mint", int(m_s_idx), m_key))
                                continue
                            if int(m_sinc) > 0:
                                minted_pairs.add((t_str, int(m_s_idx), m_key))
                                if m_key == "native" or m_key in _ALL_WRAPPED_NATIVE_LOWER:
                                    minted_wnative_slices.add((t_str, int(m_s_idx)))
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                    if topics and str(topics[0]).lower() == topic0_target and len(data_hex) >= 2 + 64 * 5:
                        try:
                            s_idx, asset_addr, c_gain, v_loss, g_used = abi_decode(
                                ["uint256", "address", "uint256", "uint256", "uint256"], data_hex
                            )
                            a_key = _to_asset_key(asset_addr)
                            if not emitter_ok:
                                spoofed_log_keys.add(("gain", int(s_idx), a_key))
                                continue
                            _record_gain(t_str, int(s_idx), a_key, int(c_gain), int(v_loss), int(g_used))
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                    if topics and str(topics[0]).lower() == bridge_topic0_target and len(data_hex) >= 2 + 64 * 4:
                        try:
                            b_tok_addr, b_spent, b_q_addr, b_bought = abi_decode(
                                ["address", "uint256", "address", "uint256"], data_hex
                            )
                            if not emitter_ok:
                                continue
                            bridges_by_test.setdefault(t_str, []).append(
                                {
                                    "tok_asset": _to_asset_key(b_tok_addr),
                                    "tok_spent": int(b_spent),
                                    "quote_asset": _to_asset_key(b_q_addr),
                                    "quote_bought": int(b_bought),
                                }
                            )
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                    if topics and str(topics[0]).lower() == nft_bridge_topic0_target and len(data_hex) >= 2 + 64 * 6:
                        try:
                            nb_nft, nb_tid, nb_spent, nb_1155, nb_q_addr, nb_qb = abi_decode(
                                ["address", "uint256", "uint256", "bool", "address", "uint256"], data_hex
                            )
                            if not emitter_ok:
                                continue
                            nft_bridges_by_test.setdefault(t_str, []).append(
                                {
                                    "nft": _norm_addr(nb_nft),
                                    "token_id": str(int(nb_tid)),
                                    "nft_spent": int(nb_spent),
                                    "is_1155": bool(nb_1155),
                                    "quote_asset": _to_asset_key(nb_q_addr),
                                    "quote_bought": int(nb_qb),
                                }
                            )
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                    if topics and str(topics[0]).lower() == atomic_exit_topic0_target and len(data_hex) >= 2 + 64 * 6:
                        try:
                            ae_asset, ae_tid, ae_is_nft, ae_is_1155, ae_q_addr, ae_q_amt = abi_decode(
                                ["address", "uint256", "bool", "bool", "address", "uint256"], data_hex
                            )
                            if not emitter_ok:
                                continue
                            atomic_exits_by_test.setdefault(t_str, []).append(
                                {
                                    "origin_asset": _norm_addr(ae_asset),
                                    "token_id": str(int(ae_tid)),
                                    "is_nft": bool(ae_is_nft),
                                    "is_1155": bool(ae_is_1155),
                                    "quote_asset": _to_asset_key(ae_q_addr),
                                    "quote_amt": int(ae_q_amt),
                                }
                            )
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                    if nft_gains_out is not None and topics and str(topics[0]).lower() == nft_topic0_target and len(data_hex) >= 2 + 64 * 5:
                        try:
                            n_sidx, n_addr, n_id, n_amt, n_is1155 = abi_decode(
                                ["uint256", "address", "uint256", "uint256", "bool"], data_hex
                            )
                            n_norm = _norm_addr(n_addr)
                            if not emitter_ok or not n_norm or int(n_amt) <= 0:
                                continue
                            nk = (t_str, int(n_sidx), n_norm, int(n_id), bool(n_is1155))
                            if nk not in seen_nft_keys:
                                seen_nft_keys.add(nk)
                                nft_gains_out.append(
                                    {
                                        "test": t_str,
                                        "slice_idx": int(n_sidx),
                                        "nft_contract": n_norm,
                                        "token_id": str(int(n_id)),
                                        "amount": int(n_amt),
                                        "standard": "ERC1155" if bool(n_is1155) else "ERC721",
                                    }
                                )
                        except (ABIError, ValueError, TypeError, IndexError):
                            pass
                if raw_logs_val is None:
                    for dlog in tres.get("decoded_logs") or []:
                        d_str = str(dlog)
                        if "ConservationAtomicExit" in d_str:
                            no_br_ae = _BRACKET_SPAN_RE.sub(" ", d_str)
                            ae_addrs = _ANY_ADDR_RE.findall(no_br_ae)
                            ae_bools = re.findall(r"\b(true|false)\b", no_br_ae.lower())
                            ae_nums = [int(x) for x in _UINT_TOKEN_RE.findall(_ANY_ADDR_RE.sub(" ", no_br_ae))]
                            if len(ae_addrs) >= 2 and len(ae_nums) >= 2:
                                atomic_exits_by_test.setdefault(t_str, []).append(
                                    {
                                        "origin_asset": _norm_addr(ae_addrs[0]),
                                        "token_id": str(int(ae_nums[0])),
                                        "is_nft": (ae_bools[0] == "true") if len(ae_bools) >= 1 else False,
                                        "is_1155": (ae_bools[1] == "true") if len(ae_bools) >= 2 else False,
                                        "quote_asset": _to_asset_key(ae_addrs[1]),
                                        "quote_amt": int(ae_nums[-1]),
                                    }
                                )
                            continue
                        if "ConservationNftBridge" in d_str:
                            no_br_nb = _BRACKET_SPAN_RE.sub(" ", d_str)
                            nb_addrs = _ANY_ADDR_RE.findall(no_br_nb)
                            nb_nums = [int(x) for x in _UINT_TOKEN_RE.findall(_ANY_ADDR_RE.sub(" ", no_br_nb))]
                            if len(nb_addrs) >= 2 and len(nb_nums) >= 3:
                                nft_bridges_by_test.setdefault(t_str, []).append(
                                    {
                                        "nft": _norm_addr(nb_addrs[0]),
                                        "token_id": str(int(nb_nums[0])),
                                        "nft_spent": int(nb_nums[1]),
                                        "is_1155": "true" in no_br_nb.lower(),
                                        "quote_asset": _to_asset_key(nb_addrs[1]),
                                        "quote_bought": int(nb_nums[-1]),
                                    }
                                )
                            continue
                        if "ConservationBridge" in d_str:
                            no_br_b = _BRACKET_SPAN_RE.sub(" ", d_str)
                            b_addrs = _ANY_ADDR_RE.findall(no_br_b)
                            b_nums = [int(x) for x in _UINT_TOKEN_RE.findall(_ANY_ADDR_RE.sub(" ", no_br_b))]
                            if len(b_addrs) >= 2 and len(b_nums) >= 2:
                                bridges_by_test.setdefault(t_str, []).append(
                                    {
                                        "tok_asset": _to_asset_key(b_addrs[0]),
                                        "tok_spent": int(b_nums[0]),
                                        "quote_asset": _to_asset_key(b_addrs[1]),
                                        "quote_bought": int(b_nums[1]),
                                    }
                                )
                            continue
                        is_mint_log = "ConservationSupplyMint" in d_str
                        if not is_mint_log and "ConservationGain" not in d_str:
                            continue
                        no_brackets = _BRACKET_SPAN_RE.sub(" ", d_str)
                        addr_m = _ANY_ADDR_RE.search(no_brackets)
                        asset_key = _to_asset_key(addr_m.group(0) if addr_m else "")
                        nums = [int(x) for x in _UINT_TOKEN_RE.findall(_ANY_ADDR_RE.sub(" ", no_brackets))]
                        if is_mint_log:
                            if len(nums) >= 2 and nums[1] > 0 and ("mint", nums[0], asset_key) not in spoofed_log_keys:
                                minted_pairs.add((t_str, nums[0], asset_key))
                                if asset_key == "native" or asset_key in _ALL_WRAPPED_NATIVE_LOWER:
                                    minted_wnative_slices.add((t_str, nums[0]))
                        elif len(nums) >= 4 and ("gain", nums[0], asset_key) not in spoofed_log_keys:
                            _record_gain(t_str, nums[0], asset_key, nums[1], nums[2], nums[3])
    if minted_pairs or minted_wnative_slices or bridges_by_test or nft_bridges_by_test or atomic_exits_by_test:
        for g_item in gains:
            t_k = str(g_item.get("test") or "")
            s_k = int(g_item.get("slice_idx") or 0)
            a_k = str(g_item.get("asset") or "")
            if (t_k, s_k, a_k) in minted_pairs or (a_k == "native" and (t_k, s_k) in minted_wnative_slices):
                g_item["supply_mint"] = True
            if t_k in bridges_by_test:
                g_item["bridge_events"] = list(bridges_by_test[t_k])
            if t_k in nft_bridges_by_test:
                g_item["nft_bridge_events"] = list(nft_bridges_by_test[t_k])
            if t_k in atomic_exits_by_test:
                g_item["atomic_exit_events"] = list(atomic_exits_by_test[t_k])
    return passed, failed, gains


def _is_valid_hevm_prank_calldata(
    data_hex: str,
    *,
    forbid_inline_fork: bool = False,
    allowed_caller: str = "",
) -> bool:
    """Decode HEVM `prank`/`startPrank` calldata at trace level and verify 2-arg/origin/caller isolation."""
    ds = (data_hex or "").strip().lower()
    if not ds.startswith("0x") or len(ds) < 10:
        return False
    sel = ds[:10]
    body = ds[10:]
    norm_allowed = _norm_addr(allowed_caller)
    banned_addrs = {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        "0x0000000000000000000000000000000000000000",
    }

    def _valid_word_addr(word64: str) -> str:
        if len(word64) != 64:
            return ""
        try:
            if int(word64[:24], 16) != 0:
                return ""
        except ValueError:
            return ""
        addr_c = "0x" + word64[24:]
        if addr_c in banned_addrs or not _is_non_precompile_addr(addr_c):
            return ""
        if norm_allowed and addr_c != norm_allowed:
            return ""
        return addr_c

    if sel in _SINGLE_ARG_PRANK_SELECTORS:
        if forbid_inline_fork:
            return False
        if len(body) < 64:
            return False
        return bool(_valid_word_addr(body[:64]))
    if sel in _TWO_ARG_PRANK_SELECTORS:
        if len(body) < 128:
            return False
        a0 = _valid_word_addr(body[:64])
        a1 = _valid_word_addr(body[64:128])
        return bool(a0 and a1 and a0 == a1)
    return True


def _is_valid_hevm_self_delegation_calldata(data_hex: str, *, allowed_caller: str = "") -> bool:
    """Decode HEVM `signAndAttachDelegation(address,uint256)` calldata and verify secp256k1 key binds strictly to `allowed_caller`."""
    ds = (data_hex or "").strip().lower()
    if not ds.startswith("0x") or len(ds) != 138 or ds[:10] != _SELF_DELEGATE_VM_SEL:
        return False
    norm_allowed = _norm_addr(allowed_caller)
    if not norm_allowed:
        return False
    body = ds[10:]
    try:
        if int(body[:24], 16) != 0:
            return False
        impl_addr = "0x" + body[24:64]
        pk_int = int(body[64:128], 16)
    except ValueError:
        return False
    if impl_addr in {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        CREATE2_DEPLOYER_ADDR,
    }:
        return False
    return _secp256k1_privkey_to_eth_addr(pk_int) == norm_allowed


_ALLOWED_HARNESS_STATICCALL_SELECTORS: FrozenSet[str] = frozenset({
    BALANCE_OF_SEL.lower(),  # balanceOf(address)
    TOTAL_SUPPLY_SEL.lower(),  # totalSupply()
    ALLOWANCE_SEL.lower(),  # allowance(address,address)
    DECIMALS_SEL.lower(),  # decimals()
    ERC721_OWNER_OF_SEL.lower(),  # ownerOf(uint256)
    ERC1155_BALANCE_OF_SEL.lower(),  # balanceOf(address,uint256)
})
_ALLOWED_HARNESS_AUTO_LIQ_SELECTOR_HEX_LEN: Dict[str, int] = {
    APPROVE_SEL.lower(): 138,  # approve(address,uint256)
    _selector("swapV2(address,address,address,uint256,address)"): 330,
    _selector("swapSolidly(address,address,address,uint256,address)"): 330,
    _selector("swapV3(address,address,address,uint256,address)"): 330,
    _selector("swapUniV4(address,address,address,uint256,uint24,int24,address,address)"): 522,
    _selector("swapBalancerV3(address,address,address,address,uint256,address)"): 394,
    _selector("swapCurve(address,address,address,uint256,int128,int128,bool,address)"): 522,
    _selector("unwindV2LP(address,uint256,address)"): 202,
    ERC4626_REDEEM_SEL.lower(): 202,  # redeem(uint256,address,address)
    AAVE_WITHDRAW_SEL.lower(): 202,  # withdraw(address,uint256,address)
    COMPOUND_REDEEM_SEL.lower(): 74,  # redeem(uint256)
}


def _build_arena_children_map(arena_list: Sequence[Any]) -> Tuple[Dict[int, List[int]], List[int]]:
    """Execution 트레이스 아레나에서 `(children_map, root_indices)` 트리 인덱스를 일관되게 구축한다."""
    if not arena_list:
        return {}, []
    first_node = arena_list[0]
    has_explicit_children = isinstance(first_node, dict) and isinstance(first_node.get("children"), list)
    children_map: Dict[int, List[int]] = {}
    root_indices: List[int] = [0]
    if has_explicit_children:
        children_sets: Dict[int, Set[int]] = {}
        n_arena = len(arena_list)
        for idx_c, nd_c in enumerate(arena_list):
            if isinstance(nd_c, dict):
                ch_raw = nd_c.get("children")
                if ch_raw:
                    ch_list = [ch_i for ch_i in ch_raw if isinstance(ch_i, int)]
                    children_map[idx_c] = ch_list
                    children_sets[idx_c] = set(ch_list)
                else:
                    children_map[idx_c] = []
                    children_sets[idx_c] = set()
        # Partial-trace union: forge --json arenas sometimes list only one child explicitly while `parent`
        # fields encode the full fork (e.g. create + call both parented to root). Union parent edges in O(N).
        _parent_roots: List[int] = []
        for idx_c, nd_c in enumerate(arena_list):
            if not isinstance(nd_c, dict):
                continue
            par_i = nd_c.get("parent")
            if isinstance(par_i, int) and 0 <= par_i < n_arena and par_i != idx_c:
                cset = children_sets.get(par_i)
                if cset is None:
                    children_map[par_i] = [idx_c]
                    children_sets[par_i] = {idx_c}
                elif idx_c not in cset:
                    cset.add(idx_c)
                    children_map[par_i].append(idx_c)
            else:
                _parent_roots.append(idx_c)
        # Roots: explicit [0] plus any parent-orphaned nodes not reachable from 0 via union.
        _reachable: Set[int] = set()
        _stk: List[int] = [0]
        while _stk:
            _cur = _stk.pop()
            if _cur in _reachable or _cur < 0 or _cur >= len(arena_list):
                continue
            _reachable.add(_cur)
            for _ch in children_map.get(_cur, ()):
                if _ch not in _reachable:
                    _stk.append(_ch)
        for _pr in _parent_roots:
            if _pr not in _reachable:
                root_indices.append(_pr)
        root_indices = list(dict.fromkeys(root_indices))
    else:
        root_indices = []
        for idx_c, nd_c in enumerate(arena_list):
            if not isinstance(nd_c, dict):
                continue
            par_i = nd_c.get("parent")
            if isinstance(par_i, int) and 0 <= par_i < len(arena_list) and par_i != idx_c:
                children_map.setdefault(par_i, []).append(idx_c)
            else:
                root_indices.append(idx_c)
        if not root_indices and isinstance(first_node, dict):
            root_indices = [0]
    return children_map, root_indices


def _is_disallowed_harness_staticcall_data(frame_obj: Mapping[str, Any]) -> bool:
    raw_sc = str(frame_obj.get("data") or frame_obj.get("input") or frame_obj.get("calldata") or "").strip().lower()
    return raw_sc.startswith("0x") and len(raw_sc) >= 2 and (
        len(raw_sc) < 10 or raw_sc[:10] not in _ALLOWED_HARNESS_STATICCALL_SELECTORS
    )


def _valid_unvisited_arena_node(
    arena_list: Sequence[Any], idx_n: int, visited: Set[int]
) -> Optional[Dict[str, Any]]:
    if idx_n < 0 or idx_n >= len(arena_list) or idx_n in visited:
        return None
    nd = arena_list[idx_n]
    if not isinstance(nd, dict):
        return None
    visited.add(idx_n)
    return nd


def _push_nested_containers(stk: List[Any], node: Any) -> None:
    children = node.values() if isinstance(node, dict) else (node if isinstance(node, list) else ())
    for ch in children:
        if isinstance(ch, (dict, list)):
            stk.append(ch)


def _scan_trace_tree_for_disallowed_hevm(
    obj: Any,
    forbid_inline_fork: bool = False,
    allowed_caller: str = "",
    *,
    forbid_top_level_revert: bool = False,
) -> bool:
    """인메모리 JSON 트레이스 트리 전체를 순회하며 HEVM_ADDRESS 비허용 치트코드/프랭크 인자 및 하네스 집합(H) 무프랭크 호출·가치 주입·최상위 revert 은폐를 구조적으로 탐지."""
    eff_allowed = (
        (ALLOWED_VM_SELECTORS - _INLINE_FORK_SELECTORS - _SINGLE_ARG_PRANK_SELECTORS)
        if forbid_inline_fork
        else ALLOWED_VM_SELECTORS
    )
    default_sender = FOUNDRY_DEFAULT_SENDER
    test_contract_addr = FOUNDRY_TEST_CONTRACT
    forbid_targets = {
        default_sender,
        CREATE2_DEPLOYER_ADDR,
    }
    console_addr = FOUNDRY_CONSOLE_ADDR
    sink_addr = SETTLEMENT_SINK_ADDR
    sink_suffix = SETTLEMENT_SINK_ADDR[2:]
    harness_callers = {
        test_contract_addr,
        default_sender,
        "",
    }

    def _is_disallowed_unpranked_create_call(
        is_rev_f: bool, in_unpranked: bool, kind_f: str, target_f: str
    ) -> bool:
        return (
            not is_rev_f
            and in_unpranked
            and (
                kind_f in ("call", "delegatecall", "callcode")
                or (forbid_inline_fork and kind_f == "staticcall")
            )
            and target_f not in (HEVM_ADDRESS_LOWER, console_addr, "")
        )

    def _is_disallowed_top_revert(tr_d: Dict[str, Any], kind_v: str, target_v: str, caller_v: str) -> bool:
        if not forbid_top_level_revert:
            return False
        if target_v in (HEVM_ADDRESS_LOWER, console_addr, test_contract_addr, sink_addr, ""):
            return False
        if kind_v in ("delegatecall", "callcode"):
            return True
        if kind_v == "staticcall" and caller_v in harness_callers:
            return False
        raw_cd = str(tr_d.get("data") or tr_d.get("input") or tr_d.get("calldata") or "").strip().lower()
        if raw_cd.startswith(TRANSFER_SEL.lower()) and len(raw_cd) == 138 and sink_suffix in raw_cd[:74]:
            return False
        if len(raw_cd) >= 10 and _ALLOWED_HARNESS_AUTO_LIQ_SELECTOR_HEX_LEN.get(raw_cd[:10]) == len(raw_cd):
            return False
        return True

    def _arena_has_prefunded_caller_transfer(arena_list: List[Any]) -> bool:
        if not arena_list:
            return False
        bal: Dict[str, int] = {}
        caller_dom: Set[str] = set()
        created_in_dom: Set[str] = set()
        sd_native_unlocked: bool = False
        sd_credit_pool: int = 0
        first_nd = arena_list[0] if isinstance(arena_list[0], dict) else {}
        first_tr = first_nd.get("trace") if isinstance(first_nd.get("trace"), dict) else first_nd
        root_test_addr = str(first_tr.get("address") or first_tr.get("to") or test_contract_addr).strip().lower()
        harness_roots = {test_contract_addr, root_test_addr} - {""}
        children_map, root_indices = _build_arena_children_map(arena_list)

        visited_nodes: Set[int] = set()

        def _extract_trace_frame_fields(frame_d: Mapping[str, Any]) -> Tuple[str, str, str, int, Any, bool]:
            return (
                str(frame_d.get("kind") or frame_d.get("call_type") or "").strip().lower(),
                str(frame_d.get("caller") or frame_d.get("from") or "").strip().lower(),
                str(frame_d.get("address") or frame_d.get("to") or "").strip().lower(),
                _hex_to_int(frame_d.get("value")),
                frame_d.get("depth"),
                _is_trace_frame_reverted(frame_d),
            )

        def _walk_node(idx_n: int, parent_target: str, in_unpranked_create: bool = False) -> bool:
            nonlocal sd_native_unlocked, sd_credit_pool
            nd = _valid_unvisited_arena_node(arena_list, idx_n, visited_nodes)
            if nd is None:
                return False
            tr = nd.get("trace") if isinstance(nd.get("trace"), dict) else nd
            if not isinstance(tr, dict):
                return False
            ch_list = children_map.get(idx_n, [])
            kind_l, caller_l, target_l, val_w, depth_n, is_rev = _extract_trace_frame_fields(tr)
            if target_l == HEVM_ADDRESS_LOWER and (
                (depth_n is not None and int(depth_n) >= 2)
                or parent_target not in ("", *harness_roots)
            ):
                return True
            if (
                is_rev
                and (depth_n == 1 or (depth_n is None and parent_target in harness_roots))
                and _is_disallowed_top_revert(tr, kind_l, target_l, caller_l)
            ):
                return True
            if is_rev and not ch_list:
                return False
            bal_snap: Optional[Dict[str, int]] = None
            dom_snap: Optional[Set[str]] = None
            created_snap: Optional[Set[str]] = None
            sd_snap = sd_native_unlocked
            sd_pool_snap = sd_credit_pool
            if is_rev:
                bal_snap = dict(bal)
                dom_snap = set(caller_dom)
                created_snap = set(created_in_dom)
            if (
                not is_rev
                and caller_l == test_contract_addr
                and kind_l in ("call", "delegatecall", "callcode")
                and target_l not in (HEVM_ADDRESS_LOWER, console_addr, test_contract_addr, "")
            ):
                return True
            if (
                forbid_inline_fork
                and not is_rev
                and caller_l in harness_roots
                and kind_l in ("create", "create2")
            ):
                return True
            if (
                forbid_inline_fork
                and not is_rev
                and caller_l == test_contract_addr
                and kind_l == "staticcall"
                and target_l not in (HEVM_ADDRESS_LOWER, console_addr, test_contract_addr, "")
                and _is_disallowed_harness_staticcall_data(tr)
            ):
                return True
            if _is_disallowed_unpranked_create_call(is_rev, in_unpranked_create, kind_l, target_l):
                return True
            child_unpranked_create = (
                in_unpranked_create
                or (kind_l in ("create", "create2") and caller_l in harness_roots)
            )
            if (
                (parent_target in harness_roots or depth_n == 1 or bool(nd.get("is_prank_caller")))
                and caller_l not in (*harness_roots, default_sender, "")
                and target_l not in (HEVM_ADDRESS_LOWER, console_addr)
            ):
                caller_dom.add(caller_l)
            if kind_l in ("create", "create2") and (caller_l in caller_dom or caller_l in harness_roots) and target_l:
                caller_dom.add(target_l)
                created_in_dom.add(target_l)
            if val_w > 0 and kind_l not in ("delegatecall", "callcode", "staticcall"):
                if caller_l in harness_roots:
                    return True
                if caller_l in caller_dom:
                    if not sd_native_unlocked:
                        cur_bal = bal.get(caller_l, 0)
                        if cur_bal + sd_credit_pool < val_w:
                            return True
                        if cur_bal >= val_w:
                            bal[caller_l] = cur_bal - val_w
                        else:
                            sd_credit_pool -= (val_w - cur_bal)
                            bal[caller_l] = 0
                    elif bal.get(caller_l, 0) >= val_w:
                        bal[caller_l] = bal.get(caller_l, 0) - val_w
                if target_l in caller_dom and target_l != HEVM_ADDRESS_LOWER:
                    bal[target_l] = bal.get(target_l, 0) + val_w
            for ch_i in ch_list:
                if _walk_node(ch_i, target_l, child_unpranked_create):
                    return True
            status_l = str(tr.get("status") or "").strip().lower()
            is_sd_frame = (
                not is_rev
                and (
                    status_l == "selfdestruct"
                    or kind_l == "selfdestruct"
                    or bool(tr.get("selfdestruct_refund_target"))
                )
                and not in_unpranked_create
                and caller_l not in harness_roots
                and target_l not in harness_roots
            )
            if is_sd_frame:
                sd_ref = str(tr.get("selfdestruct_refund_target") or "").strip().lower()
                sd_raw_val = tr.get("selfdestruct_transferred_value")
                if sd_raw_val is not None:
                    sd_v = _hex_to_int(sd_raw_val)
                    if sd_v > 0:
                        if sd_ref and sd_ref in caller_dom:
                            bal[sd_ref] = bal.get(sd_ref, 0) + sd_v
                        elif not sd_ref:
                            sd_credit_pool += sd_v
                elif target_l in created_in_dom:
                    sd_created_bal = bal.pop(target_l, 0)
                    if sd_created_bal > 0:
                        if sd_ref and sd_ref in caller_dom:
                            bal[sd_ref] = bal.get(sd_ref, 0) + sd_created_bal
                        else:
                            sd_credit_pool += sd_created_bal
                elif sd_ref and sd_ref not in caller_dom:
                    pass
                elif val_w > 0:
                    if sd_ref and sd_ref in caller_dom:
                        bal[sd_ref] = bal.get(sd_ref, 0) + val_w
                    else:
                        sd_credit_pool += val_w
                elif sd_ref in caller_dom:
                    sd_native_unlocked = True
            if is_rev and bal_snap is not None and dom_snap is not None and created_snap is not None:
                bal.clear()
                bal.update(bal_snap)
                caller_dom.clear()
                caller_dom.update(dom_snap)
                created_in_dom.clear()
                created_in_dom.update(created_snap)
                sd_native_unlocked = sd_snap
                sd_credit_pool = sd_pool_snap
            return False

        for r_idx in root_indices:
            if _walk_node(r_idx, "", False):
                return True
        return False

    stack: List[Tuple[Any, bool]] = [(obj, False)]
    while stack:
        cur, in_unpranked_create = stack.pop()
        if isinstance(cur, dict):
            if isinstance(cur.get("arena"), list) and _arena_has_prefunded_caller_transfer(cur["arena"]):
                return True
            addr = str(cur.get("address") or cur.get("to") or "").lower()
            child_unpranked_create = in_unpranked_create
            if "topics" not in cur:
                if addr == HEVM_ADDRESS_LOWER and any(
                    k in cur for k in ("data", "input", "calldata", "kind", "call_type", "caller", "from", "value")
                ):
                    kind_hevm = str(cur.get("kind") or cur.get("call_type") or "").strip().lower()
                    hevm_depth = cur.get("depth")
                    hevm_caller = str(cur.get("caller") or cur.get("from") or "").strip().lower()
                    if (
                        _hex_to_int(cur.get("value")) > 0
                        or kind_hevm in ("delegatecall", "callcode")
                        or (hevm_depth is not None and int(hevm_depth) >= 2)
                        or hevm_caller not in ("", test_contract_addr, default_sender)
                    ):
                        return True
                    data_s = str(cur.get("data") or cur.get("input") or cur.get("calldata") or "").strip().lower()
                    if not data_s.startswith("0x") or len(data_s) < 10 or data_s[:10] not in eff_allowed:
                        return True
                    if (
                        data_s[:10] in (_SINGLE_ARG_PRANK_SELECTORS | _TWO_ARG_PRANK_SELECTORS)
                        and not _is_valid_hevm_prank_calldata(
                            data_s,
                            forbid_inline_fork=forbid_inline_fork,
                            allowed_caller=allowed_caller,
                        )
                    ):
                        return True
                    if data_s[:10] == _SELF_DELEGATE_VM_SEL and not _is_valid_hevm_self_delegation_calldata(
                        data_s, allowed_caller=allowed_caller
                    ):
                        return True
                if addr in forbid_targets:
                    return True
                kind_s = str(cur.get("kind") or cur.get("call_type") or "").strip().lower()
                caller_s = str(cur.get("caller") or cur.get("from") or "").strip().lower()
                val_i, depth_v, is_rev_cur = _hex_to_int(cur.get("value")), cur.get("depth"), _is_trace_frame_reverted(cur)
                if (
                    is_rev_cur
                    and depth_v is not None
                    and int(depth_v) == 1
                    and _is_disallowed_top_revert(cur, kind_s, addr, caller_s)
                ):
                    return True
                is_root_test_entry = (
                    addr == test_contract_addr
                    and caller_s in (default_sender, "")
                    and (depth_v is None or int(depth_v) == 0)
                    and val_i == 0
                )
                if addr == test_contract_addr and not is_root_test_entry:
                    return True
                if addr == console_addr:
                    if caller_s in harness_callers or val_i > 0 or kind_s not in ("staticcall",):
                        return True
                if caller_s == test_contract_addr:
                    if val_i > 0:
                        return True
                    if forbid_inline_fork and not is_rev_cur and kind_s in ("create", "create2"):
                        return True
                    if (
                        kind_s in ("call", "delegatecall", "callcode")
                        and addr not in (HEVM_ADDRESS_LOWER, console_addr, test_contract_addr, "")
                    ):
                        return True
                    if (
                        forbid_inline_fork
                        and not is_rev_cur
                        and kind_s == "staticcall"
                        and addr not in (HEVM_ADDRESS_LOWER, console_addr, test_contract_addr, "")
                        and _is_disallowed_harness_staticcall_data(cur)
                    ):
                        return True
                if _is_disallowed_unpranked_create_call(is_rev_cur, in_unpranked_create, kind_s, addr):
                    return True
                child_unpranked_create = (
                    in_unpranked_create
                    or (kind_s in ("create", "create2") and caller_s == test_contract_addr)
                )
                if "caller_balance_before" in cur and val_i > _hex_to_int(cur.get("caller_balance_before")):
                    return True
            for v in cur.values():
                if isinstance(v, (dict, list)):
                    stack.append((v, child_unpranked_create))
        elif isinstance(cur, list):
            for it in cur:
                if isinstance(it, (dict, list)):
                    stack.append((it, in_unpranked_create))
    return False


class CounterfactualCausalityResult(tuple):
    """`(causal_ok, causal_reason)` 2-튜플 언패킹과 `bool(...)` 평가를 동시에 지원하는 반사실 인과 검증 결과."""

    def __new__(cls, ok: bool, reason: str = "") -> "CounterfactualCausalityResult":
        return super().__new__(cls, (bool(ok), str(reason)))

    def __bool__(self) -> bool:
        return bool(self[0])

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, bool):
            return bool(self[0]) is other
        return super().__eq__(other)


_TRACE_HEVM_DATA_RE: re.Pattern[str] = re.compile(
    rf'"address"\s*:\s*"{HEVM_ADDRESS_LOWER}"[^{{}}]*?"data"\s*:\s*"0x([0-9a-f]*)'
)
_TRACE_JSON_ADDR_OR_TO_RE: re.Pattern[str] = re.compile(r'"(?:address|to)"\s*:\s*"(0x[0-9a-f]{40})"')


_SOL_ALL_YUL_ASSIGN_RE: re.Pattern[str] = re.compile(
    r"(?<![A-Za-z0-9_.])\b([A-Za-z_][A-Za-z0-9_]*)\b\s*:="
)
_SOL_ALL_TUPLE_LHS_RE: re.Pattern[str] = re.compile(r"\(([^;{}()]*)\)\s*=(?![=>])")
_SOL_ALL_INCDEC_RE: re.Pattern[str] = re.compile(
    r"\b([A-Za-z_][A-Za-z0-9_]*)\b\s*(?:\+\+|--)|(?:\+\+|--)\s*\b([A-Za-z_][A-Za-z0-9_]*)\b"
)
_SOL_ALL_ASSIGN_HEAD_RE: re.Pattern[str] = re.compile(
    r"(?<![A-Za-z0-9_.])\b([A-Za-z_][A-Za-z0-9_]*)\b\s*((?:\+|-|\*|/|%|&|\||\^|<<|>>)?=)(?![=>])"
)


def _index_sol_assignments(src_txt: str) -> Dict[str, List[Tuple[str, str]]]:
    """Solidity 소스의 모든 변수 대입(`ident op rhs;`)을 단일 O(N) 스캔으로 식별자별 색인화한다."""
    out_idx: Dict[str, List[Tuple[str, str]]] = {}
    for m_a in _SOL_ALL_ASSIGN_HEAD_RE.finditer(src_txt):
        semi_pos = src_txt.find(";", m_a.end())
        if semi_pos < 0:
            continue
        rhs_raw = src_txt[m_a.end() : semi_pos]
        if not rhs_raw:
            continue
        rhs_s = rhs_raw.lstrip()
        out_idx.setdefault(m_a.group(1), []).append((m_a.group(2), rhs_s if rhs_s else rhs_raw))
    return out_idx


@functools.lru_cache(maxsize=256)
def _compiled_sol_ident_ref_re(ident: str) -> re.Pattern[str]:
    return re.compile(rf"(?<![A-Za-z0-9_.])\b{re.escape(ident)}\b")


@functools.lru_cache(maxsize=128)
def _compiled_addr_alt_re(keys: Tuple[str, ...]) -> re.Pattern[str]:
    pats = [
        ("0[xX]" + "_?".join(re.escape(ch) for ch in k[2:]))
        if k.lower().startswith("0x") and len(k) == 42
        else re.escape(k)
        for k in keys
    ]
    return re.compile("(?:" + "|".join(pats) + r")(?![0-9a-fA-F_])", re.IGNORECASE)


@functools.lru_cache(maxsize=256)
def _compiled_sol_fn_decl_re(fn_name: str) -> re.Pattern[str]:
    clean_fn = str(fn_name or "").split("(", 1)[0].strip()
    return re.compile(rf"\bfunction\s+{re.escape(clean_fn)}\b")


def _lookup_per_test(pt_map: Mapping[str, Any], test_name: str) -> Any:
    if not isinstance(pt_map, Mapping) or not test_name:
        return None
    if "::" in test_name:
        rel_p, raw_t = test_name.split("::", 1)
        rel_norm = rel_p.replace("\\", "/").lstrip("./")
        clean_t = raw_t.split("(", 1)[0].strip()
        if rel_norm and clean_t:
            for sc_cand in (f"{rel_norm}::{raw_t}", f"{rel_norm}::{clean_t}", f"{rel_norm}::{clean_t}()"):
                if sc_cand in pt_map:
                    return pt_map[sc_cand]
            has_scoped_keys = False
            for k_pt, v_pt in pt_map.items():
                ks = str(k_pt)
                if "::" in ks:
                    has_scoped_keys = True
                    kr, kt = ks.split("::", 1)
                    if kr.replace("\\", "/").lstrip("./") == rel_norm and kt.split("(", 1)[0].strip() == clean_t:
                        return v_pt
            if has_scoped_keys:
                return None
        test_name = raw_t
    if test_name in pt_map:
        return pt_map[test_name]
    clean_t = test_name.split("(", 1)[0].strip()
    if clean_t in pt_map:
        return pt_map[clean_t]
    paren_t = f"{clean_t}()"
    if paren_t in pt_map:
        return pt_map[paren_t]
    for k_pt, v_pt in pt_map.items():
        ks = str(k_pt)
        if "::" not in ks and ks.split("(", 1)[0].strip() == clean_t:
            return v_pt
    return None


def _list_sibling_sol_relpaths(ws: Optional[Path], rel_test_path: str) -> List[str]:
    if ws is None:
        return []
    test_dir = ws / "test"
    if not test_dir.is_dir():
        return []
    target_rel = str(rel_test_path).replace("\\", "/").lstrip("./")
    siblings: List[str] = []
    for p in sorted(test_dir.rglob("*.sol")):
        try:
            rel_p = p.relative_to(ws).as_posix()
        except ValueError:
            continue
        if rel_p != target_rel:
            siblings.append(rel_p)
    return siblings


_FORK_STATE_BY_NUMBER_CHAINS: FrozenSet[str] = frozenset({"rootstock"})
_BLOCKHASH_STATE_ERR_MARKERS: Tuple[str, ...] = (
    "error code -32603",
    "http error 500",
    "temporary internal error",
    "internal server error",
    "blockhash",
    "block hash",
)


def _requires_fork_state_by_number(chain: str = "", fork_url: str = "") -> bool:
    c_n = _norm_chain(chain) if chain else ""
    u_l = str(fork_url or "").lower()
    return bool(
        c_n in _FORK_STATE_BY_NUMBER_CHAINS
        or "rsk.co" in u_l
        or "rootstock" in u_l
    )


def _build_forge_test_cmd(
    rel_test_path: str,
    *,
    fork_url: str = "",
    fork_block: int = 0,
    always_fork: bool = False,
    gas_price_wei: int = 0,
    match_test: str = "",
    verbosity: str = "-vv",
    ws: Optional[Path] = None,
    state_by_number: bool = False,
) -> List[str]:
    norm_rel = str(rel_test_path).replace("\\", "/").lstrip("./")
    cmd = [
        str(FORGE_BIN),
        "test",
        "--offline",
        "--no-storage-caching",
        "--threads",
        str(_BG_SUBPROC_THREADS),
        "--match-path",
        norm_rel,
    ]
    for sib_rel in _list_sibling_sol_relpaths(ws, norm_rel):
        cmd.extend(["--skip", sib_rel])
    if always_fork or (fork_block > 0 and fork_url):
        cmd.extend(["--fork-url", fork_url, "--fork-block-number", str(int(fork_block))])
        if state_by_number:
            cmd.append("--fork-state-by-number")
    if gas_price_wei > 0:
        cmd.extend(["--gas-price", str(int(gas_price_wei))])
    if match_test:
        clean_t = match_test.split("(")[0].strip()
        if clean_t:
            cmd.extend(["--match-test", f"^{re.escape(clean_t)}(?:\\(|$)"])
    cmd.extend([verbosity, "--json"])
    return cmd


def _run_forge_subproc(ws: Path, cmd: List[str], timeout_sec: int) -> subprocess.CompletedProcess[str]:
    with _FORGE_SUBPROC_SEM:
        return _run_subproc_tree_safe(
            cmd,
            cwd=str(ws),
            env=_isolated_subproc_env(ws),
            timeout_sec=timeout_sec,
            decode_text=True,
        )


def _clamp_observed_calldata_bytes(z_b: int, nz_b: int) -> int:
    tot = z_b + nz_b
    return max(64, tot) if tot > 0 else 0


def _count_hex_zero_nonzero_bytes(raw_hex: str) -> Tuple[int, int]:
    s = (raw_hex or "").strip()
    if not s.startswith(("0x", "0X")):
        return 0, 0
    hex_body = s[2:]
    if not hex_body or len(hex_body) % 2 != 0:
        return 0, 0
    try:
        raw_bytes = bytes.fromhex(hex_body)
    except ValueError:
        return 0, 0
    z_cnt = raw_bytes.count(0)
    return z_cnt, len(raw_bytes) - z_cnt


def _trace_top_metric_applies(trace_summary: Mapping[str, Any], pt_map: Any, test_name: str) -> bool:
    if not test_name or not (isinstance(pt_map, Mapping) and pt_map):
        return True
    win_raw = str(trace_summary.get("winning_test") or "")
    if "::" in test_name:
        t_rel, t_bare = test_name.split("::", 1)
        t_rel_n = t_rel.replace("\\", "/").lstrip("./")
        clean_t = t_bare.split("(", 1)[0].strip()
        if not clean_t:
            return True
        if "::" in win_raw:
            w_rel, w_bare = win_raw.split("::", 1)
            return w_rel.replace("\\", "/").lstrip("./") == t_rel_n and w_bare.split("(", 1)[0].strip() == clean_t
        if t_rel_n and any("::" in str(k) for k in pt_map):
            w_rel_top = str(trace_summary.get("winning_rel_test_path") or "").replace("\\", "/").lstrip("./")
            return bool(w_rel_top and w_rel_top == t_rel_n and win_raw.split("(", 1)[0].strip() == clean_t)
    else:
        clean_t = test_name.split("(", 1)[0].strip()
        if not clean_t:
            return True
    clean_win = win_raw.split("::", 1)[-1].split("(", 1)[0].strip()
    return clean_win == clean_t


def _record_per_test_trace_metrics(
    target_dict: Dict[str, Any],
    test_fn: str,
    obs_gas: int,
    obs_cd: int,
    obs_z: int,
    obs_nz: int,
    obs_max_tx_gas: int = 0,
    obs_tx_cnt: int = 0,
    obs_block_gas: int = 0,
    obs_max_tx_block_gas: int = 0,
) -> None:
    if not test_fn:
        return
    for val_i, map_k in (
        (obs_gas, "per_test_observed_gas_used"),
        (obs_max_tx_gas, "per_test_observed_max_tx_gas"),
        (obs_tx_cnt, "per_test_observed_tx_count"),
        (obs_block_gas, "per_test_observed_block_gas_used"),
        (obs_max_tx_block_gas, "per_test_observed_max_tx_block_gas"),
        (obs_cd, "per_test_observed_calldata_bytes"),
    ):
        if val_i > 0:
            pt_m = dict(target_dict.get(map_k) or {})
            pt_m[test_fn] = val_i
            target_dict[map_k] = pt_m
    if (obs_z + obs_nz) > 0:
        pt_st = dict(target_dict.get("per_test_observed_calldata_stats") or {})
        pt_st[test_fn] = {"zero_bytes": obs_z, "nonzero_bytes": obs_nz}
        target_dict["per_test_observed_calldata_stats"] = pt_st


def _is_trace_frame_reverted(tr: Mapping[str, Any]) -> bool:
    if tr.get("success") is False or tr.get("reverted") is True:
        return True
    if tr.get("success") is True and tr.get("reverted") is not True:
        return False
    st_s = str(tr.get("status") or tr.get("error") or "").strip().lower()
    return bool(st_s and st_s not in ("success", "ok", "none", "0x1", "1", "true", "return", "stop", "selfdestruct"))


def _extract_trace_observed_calldata_stats(
    out_txt: str,
    allowed_caller: str = "",
    match_test: str = "",
    *,
    parsed_objs: Optional[Sequence[Dict[str, Any]]] = None,
) -> Tuple[int, int]:
    """`-vvvv --json` 트레이스 아레나에서 외부 CALL/CREATE 트랜잭션의 (0바이트 수, 비0바이트 수)를 추출한다."""
    out = out_txt or ""
    if parsed_objs is None and not out.strip():
        return 0, 0
    caller_target = _norm_addr(allowed_caller).lower() if allowed_caller else ""
    clean_match = match_test.split("(", 1)[0].strip() if match_test else ""
    sink_addr_l = "0x0000000000000000000000000000000000099999"
    sink_suffix = "0000000000000000000000000000000000099999"
    harness_addrs = {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        sink_addr_l,
    }
    matched_z = 0
    matched_nz = 0
    fallback_z = 0
    fallback_nz = 0

    def _inspect_frame(tr: Dict[str, Any]) -> None:
        nonlocal matched_z, matched_nz, fallback_z, fallback_nz
        if "topics" in tr:
            return
        depth_v = tr.get("depth")
        if depth_v is not None and int(depth_v) != 1:
            return
        kind_l = str(tr.get("kind") or tr.get("call_type") or "").strip().lower()
        if kind_l in ("delegatecall", "callcode"):
            return
        to_l = _norm_addr(str(tr.get("address") or tr.get("to") or "")).lower()
        from_l = _norm_addr(str(tr.get("caller") or tr.get("from") or "")).lower()
        if to_l in harness_addrs:
            return
        raw_d = str(tr.get("data") or tr.get("input") or tr.get("calldata") or "").strip()
        if not raw_d.startswith(("0x", "0X")):
            return
        hex_body = raw_d[2:]
        if not hex_body or len(hex_body) % 2 != 0:
            return
        hex_l = hex_body.lower()
        if hex_l.startswith("a9059cbb") and len(hex_l) >= 72 and sink_suffix in hex_l[:72]:
            return
        if kind_l == "staticcall":
            if not (caller_target and from_l == caller_target):
                return
            if hex_l.startswith(BALANCE_OF_SEL[2:]) and len(hex_l) == 72 and int(tr.get("gas_used") or 0) < 50_000:
                return
        elif kind_l not in ("call", "create", "create2", ""):
            return
        z_cnt, nz_cnt = _count_hex_zero_nonzero_bytes(raw_d)
        if (z_cnt + nz_cnt) <= 0:
            return
        if _is_trace_frame_reverted(tr) and int(tr.get("gas_used") or 0) < 100_000 and (z_cnt + nz_cnt) <= 164:
            return
        is_create_tx = kind_l in ("create", "create2")
        if caller_target and (
            from_l == caller_target
            or (
                is_create_tx
                and (depth_v == 1 or (depth_v is None and from_l in {FOUNDRY_TEST_CONTRACT, FOUNDRY_DEFAULT_SENDER}))
            )
        ):
            matched_z += z_cnt
            matched_nz += nz_cnt
        elif depth_v == 1 or (depth_v is None and ((from_l and from_l not in harness_addrs) or is_create_tx)):
            fallback_z += z_cnt
            fallback_nz += nz_cnt

    def _walk_trace_node(root_node: Any) -> None:
        stk: List[Any] = [root_node]

        def _push_non_deploy_traces(traces_seq: Sequence[Any]) -> None:
            for tr_it in traces_seq:
                if isinstance(tr_it, list) and len(tr_it) >= 2:
                    if str(tr_it[0] or "").strip().lower() in ("deployment", "setup"):
                        continue
                    if isinstance(tr_it[1], (dict, list)):
                        stk.append(tr_it[1])
                elif isinstance(tr_it, (dict, list)):
                    stk.append(tr_it)

        def _push_other_containers(mapping: Dict[str, Any], skip_key: str) -> None:
            for k_tr, v_tr in mapping.items():
                if k_tr != skip_key and isinstance(v_tr, (dict, list)):
                    stk.append(v_tr)

        while stk:
            cur = stk.pop()
            if isinstance(cur, dict):
                if isinstance(cur.get("test_results"), dict):
                    for tname, tres in cur["test_results"].items():
                        if not isinstance(tres, dict):
                            continue
                        if clean_match and str(tname).split("(", 1)[0].strip() != clean_match:
                            continue
                        t_st = str(tres.get("status") or "").strip()
                        if t_st and t_st != "Success":
                            continue
                        _push_non_deploy_traces(tres.get("traces") or ())
                    _push_other_containers(cur, "test_results")
                    continue
                if isinstance(cur.get("traces"), list):
                    _push_non_deploy_traces(cur["traces"])
                    _push_other_containers(cur, "traces")
                    continue
                if isinstance(cur.get("arena"), list):
                    for nd in cur["arena"]:
                        if not isinstance(nd, dict):
                            continue
                        tr = nd.get("trace") if isinstance(nd.get("trace"), dict) else nd
                        if isinstance(tr, dict):
                            _inspect_frame(tr)
                    _push_other_containers(cur, "arena")
                    continue
                if (
                    "topics" not in cur
                    and any(k in cur for k in ("data", "input", "calldata"))
                    and any(k in cur for k in ("kind", "call_type", "caller", "from", "address", "to"))
                ):
                    _inspect_frame(cur)
                _push_nested_containers(stk, cur)
            elif isinstance(cur, list):
                _push_nested_containers(stk, cur)

    objs_iter = parsed_objs if parsed_objs is not None else _parse_json_dict_lines(out)
    for j_obj in objs_iter:
        _walk_trace_node(j_obj)

    if (matched_z + matched_nz) > 0:
        eff_z, eff_nz = matched_z, matched_nz
    else:
        eff_z, eff_nz = fallback_z, fallback_nz
    tot = eff_z + eff_nz
    if tot <= 0:
        return 0, 0
    return eff_z, eff_nz


def _compute_calldata_floor_gas(
    chain: str,
    zero_bytes: int,
    nonzero_bytes: int,
    base_intrinsic_gas: int,
    create_base: int = 0,
    *,
    offline_mode: bool = False,
) -> Tuple[int, bool]:
    """
    활성 하드포크 콜데이터 가스 하한을 순수 정수로 단일 산출한다:
    - Glamsterdam (`_GLAMSTERDAM_EVM_CHAINS`): EIP-7976 균일 하한 `21_000 + 64 * (z + nz)` (`TOTAL_COST_FLOOR_PER_TOKEN = 16`, `floor_tokens = 4 * (z + nz)`), 기존 EIP-7623 하한과의 최댓값으로 보수적 유지.
    - Prague/Osaka (`_PRAGUE_EVM_CHAINS | _OSAKA_EVM_CHAINS` 또는 오프라인 픽스처): EIP-7623 하한 `base + create_base + 10 * (z + 4 * nz)`.
    """
    c = _norm_chain(chain) if chain else ""
    z = max(0, int(zero_bytes))
    nz = max(0, int(nonzero_bytes))
    tot = z + nz
    is_glam = bool(c and c in _GLAMSTERDAM_EVM_CHAINS)
    is_active = bool(offline_mode or is_glam or (c and c in (_OSAKA_EVM_CHAINS | _PRAGUE_EVM_CHAINS)))
    if not is_active:
        return base_intrinsic_gas + create_base, False
    if tot <= 0:
        return base_intrinsic_gas + create_base, True
    if is_glam:
        # EIP-7976 exact floor: 21_000 + TOTAL_COST_FLOOR_PER_TOKEN(16) * (4 * (z + nz)) = 21_000 + 64 * tot
        return base_intrinsic_gas + 64 * tot, True
    return base_intrinsic_gas + create_base + 10 * (z + 4 * nz), True


def _extract_trace_observed_gas_details(
    out_txt: str,
    allowed_caller: str = "",
    match_test: str = "",
    *,
    parsed_objs: Optional[Sequence[Dict[str, Any]]] = None,
    chain: str = "",
) -> Tuple[int, int, int, int, int]:
    """`-vvvv --json` Execution 트레이스 아레나에서 `(총 가스, 단일 EOA tx 최대 가스, EOA tx 수, EIP-7778 환불 미공제 총 블록 가스, 단일 tx 최대 블록 가스)`를 추출한다."""
    out = out_txt or ""
    if parsed_objs is None and '"arena"' not in out and '"Unit"' not in out:
        return 0, 0, 0, 0, 0
    caller_target = _norm_addr(allowed_caller)
    harness_skip = {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        "0x0000000000000000000000000000000000099999",
    }
    harness_root_set = {FOUNDRY_TEST_CONTRACT, FOUNDRY_DEFAULT_SENDER}
    sink_suffix = "0000000000000000000000000000000000099999"
    clean_match = match_test.split("(")[0].strip() if match_test else ""

    def _collect_arena_gas(arena_list: List[Any]) -> Tuple[int, int, int, int, int]:
        # [succ_g, succ_max_tx, succ_cnt, succ_blk_g, succ_max_tx_blk, all_g, all_blk_g]
        caller_b = [0, 0, 0, 0, 0, 0, 0]
        fb_b = [0, 0, 0, 0, 0, 0, 0]
        eip7702_auth_cnt = 0
        for nd in arena_list:
            if not isinstance(nd, dict):
                continue
            tr = nd.get("trace") if isinstance(nd.get("trace"), dict) else nd
            if not isinstance(tr, dict) or tr.get("depth") != 1:
                continue
            kind_l = str(tr.get("kind") or tr.get("call_type") or "").strip().lower()
            from_l = _norm_addr(tr.get("caller") or tr.get("from"))
            to_l = _norm_addr(tr.get("address") or tr.get("to"))
            raw_d_str = str(tr.get("data") or tr.get("input") or tr.get("calldata") or "").strip()
            data_l = raw_d_str.lower()
            if to_l == HEVM_ADDRESS_LOWER and data_l.startswith(_SELF_DELEGATE_VM_SEL) and not _is_trace_frame_reverted(tr):
                eip7702_auth_cnt += 1
                continue
            if to_l in harness_skip:
                continue
            if kind_l in ("delegatecall", "callcode"):
                continue
            if data_l.startswith(TRANSFER_SEL.lower()) and sink_suffix in data_l[:74]:
                continue
            g_val = int(tr.get("gas_used") or 0)
            if kind_l == "staticcall":
                if not (caller_target and from_l == caller_target):
                    continue
                if data_l.startswith(BALANCE_OF_SEL.lower()) and len(data_l) == 74 and g_val < 50_000:
                    continue
            tx_z, tx_nz = _count_hex_zero_nonzero_bytes(raw_d_str)
            if g_val <= 0 and (tx_z + tx_nz) == 0 and _hex_to_int(tr.get("value")) <= 0:
                continue
            is_create_tx = kind_l in ("create", "create2")
            tx_create_base = 32_000 if is_create_tx else 0
            tx_init_words = (2 * ((tx_z + tx_nz + 31) // 32)) if is_create_tx else 0
            tx_intrinsic = 21_000 + tx_create_base + tx_init_words + 4 * tx_z + 16 * tx_nz
            tx_floor, _ = _compute_calldata_floor_gas(
                chain, tx_z, tx_nz, 21_000, tx_create_base, offline_mode=(not bool(chain))
            )
            tx_gross = g_val if g_val >= tx_intrinsic else (tx_intrinsic + max(0, g_val))
            is_rev = _is_trace_frame_reverted(tr)
            if "gas_refund_counter" in tr:
                g_ref_cnt = 0 if is_rev else max(0, int(tr.get("gas_refund_counter") or 0))
                eff_ref = min(g_ref_cnt, tx_gross // 5)
                tx_full = max(tx_gross - eff_ref, tx_floor)
                tx_blk_full = max(tx_gross, tx_floor)
            else:
                g_ref_leg = 0 if is_rev else max(0, int(tr.get("gas_refund") or tr.get("gas_refunded") or tr.get("refund") or 0))
                tx_full = max(tx_gross, tx_floor)
                tx_blk_full = max(tx_gross + g_ref_leg, tx_floor)
            tx_peak = tx_full
            charge_even_if_rev = is_rev and (g_val >= 100_000 or (tx_z + tx_nz) > 164)
            is_caller_tx = bool(caller_target and (from_l == caller_target or (is_create_tx and from_l in harness_root_set)))
            is_fb_tx = (not is_caller_tx) and bool((from_l and from_l not in harness_root_set) or is_create_tx)
            if is_caller_tx or is_fb_tx:
                bkt = caller_b if is_caller_tx else fb_b
                bkt[5] += tx_full
                bkt[6] += tx_blk_full
                if (not is_rev) or charge_even_if_rev:
                    bkt[0] += tx_full
                    if tx_peak > bkt[1]:
                        bkt[1] = tx_peak
                    bkt[2] += 1
                    bkt[3] += tx_blk_full
                    if tx_blk_full > bkt[4]:
                        bkt[4] = tx_blk_full
        eip7702_auth_gas = 25_000 * eip7702_auth_cnt
        for b_ret in (caller_b, fb_b):
            if b_ret[0] > 0:
                return (
                    b_ret[0] + eip7702_auth_gas,
                    b_ret[1] + eip7702_auth_gas,
                    b_ret[2],
                    b_ret[3] + eip7702_auth_gas,
                    b_ret[4] + eip7702_auth_gas,
                )
        raw_all = (caller_b[5] if caller_b[5] > 0 else fb_b[5]) + (eip7702_auth_gas if (caller_b[5] > 0 or fb_b[5] > 0) else 0)
        raw_all_blk = (caller_b[6] if caller_b[5] > 0 else fb_b[6]) + (eip7702_auth_gas if (caller_b[5] > 0 or fb_b[5] > 0) else 0)
        return ((raw_all, raw_all, 1, max(raw_all, raw_all_blk), max(raw_all, raw_all_blk)) if raw_all > 0 else (0, 0, 0, 0, 0))

    best_gas = 0
    best_max_tx_gas = 0
    best_tx_cnt = 0
    best_blk_gas = 0
    best_max_tx_blk = 0
    objs_iter = parsed_objs if parsed_objs is not None else _parse_json_dict_lines(out)
    for arena_it in _iter_exec_trace_arenas(objs_iter, clean_match):
        cand_g, cand_max_tx, cand_cnt, cand_blk_g, cand_max_tx_blk = _collect_arena_gas(arena_it)
        if cand_g > best_gas or (cand_g == best_gas and cand_blk_g > best_blk_gas):
            best_gas = cand_g
            best_max_tx_gas = cand_max_tx
            best_tx_cnt = max(1, cand_cnt)
            best_blk_gas = cand_blk_g
            best_max_tx_blk = cand_max_tx_blk
    return best_gas, best_max_tx_gas, best_tx_cnt, best_blk_gas, best_max_tx_blk


def _resolve_trace_int_metric(
    trace_summary: Mapping[str, Any],
    per_test_key: str,
    top_key: str,
    test_name: str = "",
) -> int:
    val = 0
    pt_map = trace_summary.get(per_test_key)
    if isinstance(pt_map, Mapping) and test_name:
        val = int(_lookup_per_test(pt_map, test_name) or 0)
    if val <= 0 and _trace_top_metric_applies(trace_summary, pt_map, test_name):
        val = int(trace_summary.get(top_key) or 0)
    return val


def _resolve_trace_int_pair(
    trace_summary: Optional[Mapping[str, Any]],
    pt_k1: str,
    top_k1: str,
    pt_k2: str,
    top_k2: str,
    test_name: str = "",
    *,
    min2: int = 0,
) -> Tuple[int, int]:
    if not isinstance(trace_summary, Mapping):
        return 0, min2
    v1 = _resolve_trace_int_metric(trace_summary, pt_k1, top_k1, test_name)
    v2 = _resolve_trace_int_metric(trace_summary, pt_k2, top_k2, test_name)
    return max(0, v1), max(min2, v2)


def _resolve_effective_block_gas_profile(
    trace_summary: Optional[Mapping[str, Any]],
    test_name: str = "",
) -> Tuple[int, int]:
    """Trace 요약에서 EIP-7778 환불 미공제 `(총 블록 가스, 단일 tx 최대 블록 가스)`를 추출한다."""
    return _resolve_trace_int_pair(
        trace_summary,
        "per_test_observed_block_gas_used",
        "observed_block_gas_used",
        "per_test_observed_max_tx_block_gas",
        "observed_max_tx_block_gas",
        test_name,
    )


def _resolve_effective_tx_gas_profile(
    trace_summary: Optional[Mapping[str, Any]],
    test_name: str = "",
) -> Tuple[int, int]:
    """Trace 요약에서 `(단일 트랜잭션 최대 가스, 트랜잭션 수)`를 추출하고 미존재 시 `(0, 1)`을 반환한다."""
    return _resolve_trace_int_pair(
        trace_summary,
        "per_test_observed_max_tx_gas",
        "observed_max_tx_gas",
        "per_test_observed_tx_count",
        "observed_tx_count",
        test_name,
        min2=1,
    )


def _resolve_effective_gas_and_intrinsic_flag(
    trace_summary: Optional[Mapping[str, Any]],
    reported_gas_used: int,
    test_name: str = "",
) -> Tuple[int, bool]:
    """Trace 실측 가스(`observed_gas_used`, 내재·콜데이터 포함)와 하네스 보고 가스 중 최댓값 및 내재 가스 기포함 여부를 반환한다."""
    base_g = max(0, int(reported_gas_used or 0))
    if not isinstance(trace_summary, Mapping):
        return base_g, False
    obs_g = _resolve_trace_int_metric(trace_summary, "per_test_observed_gas_used", "observed_gas_used", test_name)
    return max(base_g, obs_g), (obs_g > 0)


def _detect_disallowed_hevm_in_trace_output(
    out_txt: str,
    *,
    forbid_inline_fork: bool,
    target_addr: str = "",
    target_addrs: Optional[Sequence[str]] = None,
    allowed_caller: str = "",
    parsed_objs: Optional[Sequence[Dict[str, Any]]] = None,
    out_lower: Optional[str] = None,
    forbid_top_level_revert: bool = False,
    require_nonreverted_target_call: bool = False,
) -> Tuple[bool, bool, int]:
    """`-vvvv --json` 트레이스 출력에서 비허용 HEVM/하네스 호출, 대상 컨트랙트 실호출 여부 및 트레이스 노드 수를 구조적으로 추출한다."""
    eff_allowed = (
        (ALLOWED_VM_SELECTORS - _INLINE_FORK_SELECTORS - _SINGLE_ARG_PRANK_SELECTORS)
        if forbid_inline_fork
        else ALLOWED_VM_SELECTORS
    )
    out = out_txt or ""
    out_l = out_lower if out_lower is not None else out.lower()
    disallowed_in_trace = False
    t_norm_set: Set[str] = {
        na for x in ([target_addr] + list(target_addrs or ())) if (na := _norm_addr(str(x)))
    }
    saw_call_frames = False
    target_called_struct = False
    objs_iter = parsed_objs if parsed_objs is not None else _parse_json_dict_lines(out)
    for j_obj in objs_iter:
        if _scan_trace_tree_for_disallowed_hevm(
            j_obj,
            forbid_inline_fork=forbid_inline_fork,
            allowed_caller=allowed_caller,
            forbid_top_level_revert=forbid_top_level_revert,
        ):
            disallowed_in_trace = True
        if t_norm_set and not target_called_struct:
            stk_tr: List[Any] = [j_obj]
            while stk_tr:
                c_tr = stk_tr.pop()
                if isinstance(c_tr, dict):
                    if "topics" not in c_tr and any(
                        k in c_tr for k in ("kind", "call_type", "caller", "from", "data", "input")
                    ):
                        saw_call_frames = True
                        c_caller = _norm_addr(c_tr.get("caller") or c_tr.get("from"))
                        c_kind = str(c_tr.get("kind") or c_tr.get("call_type") or "").strip().lower()
                        is_harness_staticcall = (
                            c_kind == "staticcall"
                            and c_caller in {FOUNDRY_TEST_CONTRACT, FOUNDRY_DEFAULT_SENDER}
                        )
                        if (
                            not is_harness_staticcall
                            and (not require_nonreverted_target_call or not _is_trace_frame_reverted(c_tr))
                            and _norm_addr(c_tr.get("address") or c_tr.get("to")) in t_norm_set
                        ):
                            target_called_struct = True
                            break
                    _push_nested_containers(stk_tr, c_tr)
                elif isinstance(c_tr, list):
                    _push_nested_containers(stk_tr, c_tr)
    if not disallowed_in_trace and HEVM_ADDRESS_LOWER in out_l:
        for m in _TRACE_HEVM_DATA_RE.finditer(out_l):
            hex_body = m.group(1)
            if len(hex_body) < 8 or ("0x" + hex_body[:8]) not in eff_allowed:
                disallowed_in_trace = True
                break
            sel_m = "0x" + hex_body[:8]
            if (
                sel_m in (_SINGLE_ARG_PRANK_SELECTORS | _TWO_ARG_PRANK_SELECTORS)
                and not _is_valid_hevm_prank_calldata(
                    "0x" + hex_body,
                    forbid_inline_fork=forbid_inline_fork,
                    allowed_caller=allowed_caller,
                )
            ):
                disallowed_in_trace = True
                break
            if sel_m == _SELF_DELEGATE_VM_SEL and not _is_valid_hevm_self_delegation_calldata(
                "0x" + hex_body, allowed_caller=allowed_caller
            ):
                disallowed_in_trace = True
                break
    target_called = (
        target_called_struct
        if saw_call_frames
        else bool(
            t_norm_set
            and any(m.group(1) in t_norm_set for m in _TRACE_JSON_ADDR_OR_TO_RE.finditer(out_l))
        )
    )
    return disallowed_in_trace, target_called, out.count('"kind":')


def _iter_exec_trace_arenas(
    parsed_objs: Iterable[Dict[str, Any]],
    clean_match: str = "",
) -> Iterator[List[Any]]:
    """JSON 트레이스 객체 시퀀스에서 Deployment/Setup을 제외한 실행 아레나 리스트를 순차 생성한다."""
    def _yield_traces(traces_seq: Sequence[Any]) -> Iterator[List[Any]]:
        for tr_it in traces_seq:
            if isinstance(tr_it, list) and len(tr_it) >= 2:
                if str(tr_it[0] or "").strip().lower() in ("deployment", "setup"):
                    continue
                if isinstance(tr_it[1], dict) and isinstance(tr_it[1].get("arena"), list):
                    yield tr_it[1]["arena"]
            elif isinstance(tr_it, dict) and isinstance(tr_it.get("arena"), list):
                yield tr_it["arena"]

    for j_obj in parsed_objs:
        if not isinstance(j_obj, dict):
            continue
        suite_cands: List[Dict[str, Any]] = []
        if isinstance(j_obj.get("test_results"), dict):
            suite_cands.append(j_obj)
        for sv in j_obj.values():
            if isinstance(sv, dict) and isinstance(sv.get("test_results"), dict):
                suite_cands.append(sv)
        if suite_cands:
            for sv in suite_cands:
                for tname, tres in (sv.get("test_results") or {}).items():
                    if not isinstance(tres, dict):
                        continue
                    if clean_match and str(tname).split("(", 1)[0].strip() != clean_match:
                        continue
                    yield from _yield_traces(tres.get("traces") or ())
        elif isinstance(j_obj.get("traces"), list):
            yield from _yield_traces(j_obj["traces"])
        elif isinstance(j_obj.get("arena"), list):
            yield j_obj["arena"]


def _base_caller_side_addrs(allowed_caller: str = "") -> Set[str]:
    return {
        na
        for raw_c in (allowed_caller, FOUNDRY_TEST_CONTRACT, FOUNDRY_DEFAULT_SENDER)
        if (na := _norm_addr(str(raw_c or "")))
    }


def _build_arena_caller_graph(
    arena_list: List[Any],
    base_caller_side: Set[str],
) -> Tuple[Set[str], Dict[int, List[int]], List[int]]:
    """아레나의 호출자·전이적 CREATE 계약 집합과 `(children_map, root_indices)` 트리를 단일 선형 경로로 구축한다."""
    caller_side = set(base_caller_side)
    first_tr = arena_list[0].get("trace") if isinstance(arena_list[0].get("trace"), dict) else arena_list[0]
    root_addr = _norm_addr(first_tr.get("address") or first_tr.get("to")) if isinstance(first_tr, dict) else ""
    if root_addr:
        caller_side.add(root_addr)
    children_map, roots = _build_arena_children_map(arena_list)
    create_edges: List[Tuple[str, str]] = []
    for nd_i in arena_list:
        if not isinstance(nd_i, dict):
            continue
        tr_i = nd_i.get("trace") if isinstance(nd_i.get("trace"), dict) else nd_i
        if not isinstance(tr_i, dict) or _is_trace_frame_reverted(tr_i):
            continue
        k_i = str(tr_i.get("kind") or tr_i.get("call_type") or "").strip().lower()
        if k_i in ("create", "create2"):
            fr_i = _norm_addr(tr_i.get("caller") or tr_i.get("from"))
            to_i = _norm_addr(tr_i.get("address") or tr_i.get("to"))
            if fr_i and to_i:
                create_edges.append((fr_i, to_i))
    changed = bool(create_edges)
    while changed:
        changed = False
        for fr_i, to_i in create_edges:
            if fr_i in caller_side and to_i not in caller_side:
                caller_side.add(to_i)
                changed = True
    return caller_side, children_map, roots


def _modexp_input_exceeds_eip7823(raw_cd: Any) -> bool:
    """EIP-7823(Osaka/Fusaka+): MODEXP(0x05) 입력 헤더 `(base_len, exp_len, mod_len)`이 1024바이트를 초과하는지 판정한다."""
    if not isinstance(raw_cd, str):
        return False
    hx = raw_cd.strip().lower().removeprefix("0x")
    if not hx:
        return False
    try:
        raw_b = bytes.fromhex(hx[:192])
    except ValueError:
        return False
    padded = raw_b.ljust(96, b"\x00")
    b_len = int.from_bytes(padded[0:32], "big")
    e_len = int.from_bytes(padded[32:64], "big")
    m_len = int.from_bytes(padded[64:96], "big")
    return max(b_len, e_len, m_len) > EIP7823_MODEXP_MAX_LEN


def _extract_arena_node_asset_transfers(
    nd_n: Dict[str, Any],
    tr_n: Dict[str, Any],
    kind_n: str,
    fr_n: str,
    addr_n: str,
) -> List[Tuple[str, str, str, str, str, int]]:
    """트레이스 아레나 단일 비리버트 프레임의 네이티브 ETH·ERC-20·ERC-721·ERC-1155 자산 전이를 추출한다."""
    out_t: List[Tuple[str, str, str, str, str, int]] = []
    if kind_n in ("call", "create", "create2", "selfdestruct") and fr_n and addr_n:
        raw_v = tr_n.get("value")
        val_i = 0
        if isinstance(raw_v, int):
            val_i = raw_v
        elif isinstance(raw_v, str) and raw_v.strip():
            s_v = raw_v.strip()
            try:
                val_i = int(s_v, 16) if s_v.startswith(("0x", "0X")) else int(s_v)
            except ValueError:
                val_i = 0
        if val_i > 0:
            out_t.append(("native", "native", "0", fr_n, addr_n, val_i))
    raw_logs = nd_n.get("logs")
    if not raw_logs:
        return out_t
    xfer_t0 = TRANSFER_TOPIC0.lower()
    t1155_s_t0 = ERC1155_TRANSFER_SINGLE_TOPIC0.lower()
    t1155_b_t0 = ERC1155_TRANSFER_BATCH_TOPIC0.lower()
    wdep_t0 = WETH_DEPOSIT_TOPIC0.lower()
    wwdr_t0 = WETH_WITHDRAWAL_TOPIC0.lower()
    for lg in raw_logs:
        if not isinstance(lg, dict):
            continue
        raw_lg = lg.get("raw_log") if isinstance(lg.get("raw_log"), dict) else lg
        topics = raw_lg.get("topics") or []
        if not topics:
            continue
        t0 = str(topics[0]).lower()
        emitter = _norm_addr(lg.get("address") or raw_lg.get("address") or addr_n or "")
        if not emitter:
            continue
        data_hx = str(raw_lg.get("data") or "")
        if t0 == xfer_t0:
            if len(topics) >= 4:
                try:
                    f_a = _norm_addr("0x" + str(topics[1])[-40:])
                    t_a = _norm_addr("0x" + str(topics[2])[-40:])
                    tid_i = int(str(topics[3]), 16)
                    out_t.append(("erc721", emitter, str(tid_i), f_a, t_a, 1))
                except (ValueError, TypeError, IndexError):
                    pass
            elif len(topics) == 3 and len(data_hx) >= 66:
                try:
                    f_a = _norm_addr("0x" + str(topics[1])[-40:])
                    t_a = _norm_addr("0x" + str(topics[2])[-40:])
                    amt_i = int(data_hx[2:66], 16)
                    if amt_i > 0:
                        out_t.append(("erc20", emitter, "0", f_a, t_a, amt_i))
                except (ValueError, TypeError, IndexError):
                    pass
        elif t0 == wwdr_t0 and len(topics) >= 2 and len(data_hx) >= 66:
            try:
                src_w = _norm_addr("0x" + str(topics[1])[-40:])
                wad_w = int(data_hx[2:66], 16)
                if src_w and wad_w > 0:
                    out_t.append(("erc20", emitter, "0", src_w, ZERO_ADDRESS, wad_w))
            except (ValueError, TypeError, IndexError):
                pass
        elif t0 == wdep_t0 and len(topics) >= 2 and len(data_hx) >= 66:
            try:
                dst_w = _norm_addr("0x" + str(topics[1])[-40:])
                wad_w = int(data_hx[2:66], 16)
                if dst_w and wad_w > 0:
                    out_t.append(("erc20", emitter, "0", ZERO_ADDRESS, dst_w, wad_w))
            except (ValueError, TypeError, IndexError):
                pass
        elif t0 == t1155_s_t0 and len(topics) >= 4 and len(data_hx) >= 130:
            try:
                f_a = _norm_addr("0x" + str(topics[2])[-40:])
                t_a = _norm_addr("0x" + str(topics[3])[-40:])
                tid_i = int(data_hx[2:66], 16)
                amt_i = int(data_hx[66:130], 16)
                if amt_i > 0:
                    out_t.append(("erc1155", emitter, str(tid_i), f_a, t_a, amt_i))
            except (ValueError, TypeError, IndexError):
                pass
        elif t0 == t1155_b_t0 and len(topics) >= 4 and len(data_hx) >= 130:
            try:
                f_a = _norm_addr("0x" + str(topics[2])[-40:])
                t_a = _norm_addr("0x" + str(topics[3])[-40:])
                ids_b, amts_b = abi_decode(["uint256[]", "uint256[]"], data_hx)
                for id_b, amt_b in zip(ids_b, amts_b):
                    if int(amt_b) > 0:
                        out_t.append(("erc1155", emitter, str(int(id_b)), f_a, t_a, int(amt_b)))
            except (ABIError, ValueError, TypeError, IndexError):
                pass
    return out_t


def _analyze_exec_trace_arenas(
    parsed_objs: Sequence[Dict[str, Any]],
    t_norm_set: Set[str],
    allowed_caller: str = "",
    match_test: str = "",
) -> Tuple[List[str], bool, bool, bool, int, int, bool, List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]], bool, List[str]]:
    """
    Execution 트레이스 아레나를 단일 패스로 순회해
    `(target_coupled_addrs, saw_arena, causal_called, eip7823_modexp_exceeded, eip8037_creates, eip8037_code_bytes, fixed_stipend_call, atomic_exit_subtrees, trace_origin_inflows, uncoupled_third_party_outflows, caller_outflows_to_addrs, target_nonview_call, target_called_sels)`를
    동시 추출한다(중복 아레나 트리 구축 제거).
    """
    if not parsed_objs:
        return [], False, False, False, 0, 0, False, [], [], [], [], False, []
    clean_match = match_test.split("(", 1)[0].strip() if match_test else ""
    base_caller_side = _base_caller_side_addrs(allowed_caller)
    skip_addrs: Set[str] = {
        HEVM_ADDRESS_LOWER,
        FOUNDRY_CONSOLE_ADDR,
        FOUNDRY_TEST_CONTRACT,
        FOUNDRY_DEFAULT_SENDER,
        SETTLEMENT_SINK_ADDR,
        "",
    }
    coupled: Set[str] = set()
    saw_arena = False
    causal_called = False
    target_nonview_call = False
    target_called_sels: Set[str] = set()
    eip7823_exceeded = False
    eip8037_creates = 0
    eip8037_code_bytes = 0
    fixed_stipend_call = False
    atomic_exit_subtrees: List[Dict[str, Any]] = []
    origin_inflows_agg: Dict[Tuple[str, str, str, str], int] = {}
    caller_outflows_agg: Dict[Tuple[str, str], int] = {}
    uncoupled_3p_outflows: List[Dict[str, Any]] = []

    def _scan_arena(arena_list: List[Any]) -> None:
        nonlocal saw_arena, causal_called, target_nonview_call, eip7823_exceeded, eip8037_creates, eip8037_code_bytes, fixed_stipend_call
        if not arena_list or not isinstance(arena_list[0], dict):
            return
        saw_arena = True
        caller_side, children_map, roots = _build_arena_caller_graph(arena_list, base_caller_side)
        visited: Set[int] = set()
        arena_net_flow: Dict[Tuple[str, str], int] = {}
        uncomp_b_cands: List[Dict[str, Any]] = []

        def _dfs(
            idx_n: int,
            anc_has_target: bool,
            in_caller_static: bool,
            cur_boundary: Optional[Dict[str, Any]],
            parent_boundary: Optional[Dict[str, Any]],
        ) -> bool:
            nonlocal causal_called, target_nonview_call, eip7823_exceeded, eip8037_creates, eip8037_code_bytes, fixed_stipend_call
            nd_n = _valid_unvisited_arena_node(arena_list, idx_n, visited)
            if nd_n is None:
                return False
            tr_n = nd_n.get("trace") if isinstance(nd_n.get("trace"), dict) else nd_n
            if not isinstance(tr_n, dict):
                return False
            kind_n = str(tr_n.get("kind") or tr_n.get("call_type") or "").strip().lower()
            fr_n = _norm_addr(tr_n.get("caller") or tr_n.get("from"))
            addr_n = _norm_addr(tr_n.get("address") or tr_n.get("to"))
            in_caller_side_pre = bool(addr_n and addr_n in caller_side)
            cur_caller_static_pre = in_caller_static or (kind_n == "staticcall" and fr_n in caller_side)
            if (
                t_norm_set
                and not in_caller_side_pre
                and addr_n in t_norm_set
                and kind_n != "staticcall"
                and not cur_caller_static_pre
            ):
                cd_raw_t = str(tr_n.get("data") or tr_n.get("input") or tr_n.get("calldata") or "").strip().lower().removeprefix("0x")
                if len(cd_raw_t) >= 8:
                    sel_t = "0x" + cd_raw_t[:8]
                    if sel_t not in _PURE_READONLY_TRACE_SELECTORS and sel_t not in _DUMMY_PROBE_SELECTORS:
                        target_nonview_call = True
                        target_called_sels.add(sel_t)
                else:
                    target_called_sels.add("fallback")
                    if _hex_to_int(tr_n.get("value")) > 0:
                        target_nonview_call = True
            if not fixed_stipend_call and kind_n == "call" and addr_n and addr_n not in skip_addrs and _is_non_precompile_addr(addr_n):
                gl_v = tr_n.get("gas_limit")
                if isinstance(gl_v, int) and 0 < gl_v <= 10_000:
                    fixed_stipend_call = True
            if _is_trace_frame_reverted(tr_n):
                return False
            if kind_n in ("create", "create2"):
                eip8037_creates += 1
                out_hx = str(tr_n.get("output") or "").strip().removeprefix("0x")
                if len(out_hx) >= 2:
                    eip8037_code_bytes += len(out_hx) // 2
            if not eip7823_exceeded and addr_n == _MODEXP_PRECOMPILE_ADDR:
                if _modexp_input_exceeds_eip7823(tr_n.get("data") or tr_n.get("input") or tr_n.get("calldata")):
                    eip7823_exceeded = True
            in_caller_side = bool(addr_n and addr_n in caller_side)
            cur_caller_static = in_caller_static or (kind_n == "staticcall" and fr_n in caller_side)
            is_t = bool(t_norm_set) and (not in_caller_side) and (addr_n in t_norm_set)
            if is_t and not cur_caller_static:
                causal_called = True

            # 원자적 거래상대방 경계(maximal non-caller_side connected component) 추적
            started_here = False
            if in_caller_side:
                next_cur_b: Optional[Dict[str, Any]] = None
                next_par_b: Optional[Dict[str, Any]] = cur_boundary if cur_boundary is not None else parent_boundary
                active_b: Optional[Dict[str, Any]] = None
            else:
                if cur_boundary is None:
                    active_b = {
                        "direct_addrs": set(),
                        "outflows": {},
                        "direct_inflows": {},
                        "inflow_sources": [],
                        "cb_candidates": [],
                        "has_target": False,
                    }
                    started_here = True
                else:
                    active_b = cur_boundary
                if addr_n and addr_n not in skip_addrs:
                    active_b["direct_addrs"].add(addr_n)
                if is_t or anc_has_target:
                    active_b["has_target"] = True
                next_cur_b = active_b
                next_par_b = parent_boundary

            node_xfers = _extract_arena_node_asset_transfers(nd_n, tr_n, kind_n, fr_n, addr_n)
            for k_t, ast_t, tid_t, f_t, t_t, amt_t in node_xfers:
                if amt_t <= 0 or f_t == SETTLEMENT_SINK_ADDR or t_t == SETTLEMENT_SINK_ADDR:
                    continue
                if k_t in ("native", "erc20"):
                    if f_t not in caller_side:
                        arena_net_flow[(f_t, ast_t)] = arena_net_flow.get((f_t, ast_t), 0) - amt_t
                    if t_t not in caller_side:
                        arena_net_flow[(t_t, ast_t)] = arena_net_flow.get((t_t, ast_t), 0) + amt_t
                if t_t in caller_side and f_t not in caller_side:
                    ok_k = (k_t, ast_t, tid_t, f_t)
                    origin_inflows_agg[ok_k] = origin_inflows_agg.get(ok_k, 0) + amt_t
                    inflow_b = (
                        active_b
                        if active_b is not None
                        else (cur_boundary if (in_caller_side and k_t == "native" and f_t == fr_n and t_t == addr_n) else None)
                    )
                    if inflow_b is not None and k_t in ("native", "erc20"):
                        inflow_b["direct_inflows"][ast_t] = inflow_b["direct_inflows"].get(ast_t, 0) + amt_t
                        inflow_b["inflow_sources"].append((f_t, ast_t, amt_t))
                elif f_t in caller_side and t_t not in caller_side:
                    if k_t in ("native", "erc20"):
                        caller_outflows_agg[(ast_t, t_t)] = caller_outflows_agg.get((ast_t, t_t), 0) + amt_t
                    if active_b is not None:
                        ok_out = f"{k_t}|{ast_t}|{tid_t}"
                        active_b["outflows"][ok_out] = active_b["outflows"].get(ok_out, 0) + amt_t
                    if parent_boundary is not None and k_t == "erc20":
                        parent_boundary["cb_candidates"].append((k_t, ast_t, tid_t, t_t, amt_t))

            child_anc_t = False if in_caller_side else (anc_has_target or is_t)
            desc_has_t = False
            for ch_idx in children_map.get(idx_n, ()):
                if _dfs(ch_idx, child_anc_t, cur_caller_static, next_cur_b, next_par_b):
                    desc_has_t = True
            if active_b is not None and desc_has_t:
                active_b["has_target"] = True
            if started_here and active_b is not None:
                d_addrs = active_b["direct_addrs"]
                for k_c, ast_c, tid_c, to_c, amt_c in active_b["cb_candidates"]:
                    if to_c in d_addrs:
                        ok_cb = f"{k_c}|{ast_c}|{tid_c}"
                        active_b["outflows"][ok_cb] = active_b["outflows"].get(ok_cb, 0) + amt_c
                if active_b["outflows"] and active_b["direct_inflows"]:
                    same_ast_out: Dict[str, int] = {}
                    for ok_k_s, ok_amt_s in active_b["outflows"].items():
                        if ok_k_s.startswith(("native|", "erc20|")):
                            parts_ok_s = ok_k_s.split("|", 2)
                            if len(parts_ok_s) == 3:
                                same_ast_out[parts_ok_s[1]] = same_ast_out.get(parts_ok_s[1], 0) + int(ok_amt_s)
                    net_direct_in: Dict[str, int] = {}
                    for ast_in_k, amt_in_v in active_b["direct_inflows"].items():
                        net_v_i = int(amt_in_v) - same_ast_out.get(ast_in_k, 0)
                        if net_v_i > 0:
                            net_direct_in[ast_in_k] = net_v_i
                    if net_direct_in:
                        atomic_exit_subtrees.append(
                            {
                                "outflows": dict(active_b["outflows"]),
                                "direct_inflows": net_direct_in,
                            }
                        )
                if not active_b["has_target"] and active_b["inflow_sources"]:
                    out_assets_distinct: Set[str] = {
                        ok_k.split("|", 2)[1] for ok_k in active_b["outflows"].keys() if "|" in ok_k
                    }
                    has_nft_out = any(
                        ok_k.startswith(("erc721|", "erc1155|")) for ok_k in active_b["outflows"].keys()
                    )
                    uncomp_src_rows = [
                        (f_s, ast_s, amt_s)
                        for f_s, ast_s, amt_s in active_b["inflow_sources"]
                        if not has_nft_out and not any(oa != ast_s for oa in out_assets_distinct)
                    ]
                    if uncomp_src_rows:
                        uncomp_b_cands.append(
                            {
                                "direct_addrs": sorted(d_addrs),
                                "inflow_sources": uncomp_src_rows,
                            }
                        )
            if t_norm_set and addr_n and addr_n not in skip_addrs and not in_caller_side and (anc_has_target or desc_has_t or is_t):
                coupled.add(addr_n)
            return False if in_caller_side else (is_t or desc_has_t)

        for r_i in roots:
            _dfs(r_i, False, False, None, None)

        for ub in uncomp_b_cands:
            b_addrs_l = ub["direct_addrs"]
            b_addrs_set = set(b_addrs_l)
            for f_s, ast_s, amt_s in ub["inflow_sources"]:
                if arena_net_flow.get((f_s, ast_s), 0) < 0:
                    b_group = b_addrs_set | {f_s}
                    if sum(arena_net_flow.get((ba, ast_s), 0) for ba in b_group) < 0:
                        uncoupled_3p_outflows.append(
                            {"from": f_s, "asset": ast_s, "amount": amt_s, "boundary_addrs": b_addrs_l}
                        )

    for arena_it in _iter_exec_trace_arenas(parsed_objs, clean_match):
        _scan_arena(arena_it)
    origin_list: List[Dict[str, Any]] = [
        {"kind": k_o, "asset": a_o, "token_id": tid_o, "from": f_o, "amount": amt_o}
        for (k_o, a_o, tid_o, f_o), amt_o in origin_inflows_agg.items()
        if amt_o > 0
    ]
    caller_out_list: List[Dict[str, Any]] = [
        {"asset": a_c, "to": t_c, "amount": amt_c}
        for (a_c, t_c), amt_c in caller_outflows_agg.items()
        if amt_c > 0
    ]
    return (
        sorted(coupled),
        saw_arena,
        causal_called,
        eip7823_exceeded,
        eip8037_creates,
        eip8037_code_bytes,
        fixed_stipend_call,
        atomic_exit_subtrees,
        origin_list,
        uncoupled_3p_outflows,
        caller_out_list,
        target_nonview_call,
        sorted(target_called_sels),
    )


def _collect_trace_replay_metrics(
    out_txt: str,
    *,
    forbid_inline_fork: bool,
    target_addr: str = "",
    target_addrs: Optional[Sequence[str]] = None,
    allowed_caller: str = "",
    match_test: str = "",
    parsed_objs: Optional[Sequence[Dict[str, Any]]] = None,
    forbid_top_level_revert: bool = False,
    require_nonreverted_target_call: bool = False,
    chain: str = "",
) -> Tuple[Dict[str, Any], str]:
    out = out_txt or ""
    out_l = out.lower()
    objs = list(parsed_objs) if parsed_objs is not None else _parse_json_dict_lines(out)
    disallowed_in_trace, target_called, trace_nodes = _detect_disallowed_hevm_in_trace_output(
        out,
        forbid_inline_fork=forbid_inline_fork,
        target_addr=target_addr,
        target_addrs=target_addrs,
        allowed_caller=allowed_caller,
        parsed_objs=objs,
        out_lower=out_l,
        forbid_top_level_revert=forbid_top_level_revert,
        require_nonreverted_target_call=require_nonreverted_target_call,
    )
    obs_z, obs_nz = _extract_trace_observed_calldata_stats(
        out, allowed_caller=allowed_caller, match_test=match_test, parsed_objs=objs
    )
    obs_cd = _clamp_observed_calldata_bytes(obs_z, obs_nz)
    obs_gas, obs_max_tx_gas, obs_tx_cnt, obs_blk_gas, obs_max_tx_blk_gas = _extract_trace_observed_gas_details(
        out, allowed_caller=allowed_caller, match_test=match_test, parsed_objs=objs, chain=chain
    )
    t_norm_coupled: Set[str] = {
        na for x in ([target_addr] + list(target_addrs or ())) if (na := _norm_addr(str(x)))
    }
    (
        coupled_addrs,
        saw_c_arena,
        causal_t_called,
        eip7823_modexp_exceeded,
        eip8037_creates,
        eip8037_code_bytes,
        fixed_stipend_call,
        atomic_exit_subtrees,
        trace_origin_inflows,
        uncoupled_third_party_outflows,
        caller_outflows_to_addrs,
        target_nonview_called,
        target_called_sels,
    ) = _analyze_exec_trace_arenas(
        objs, t_norm_coupled, allowed_caller=allowed_caller, match_test=match_test
    )
    metrics: Dict[str, Any] = {
        "disallowed_cheatcode_in_trace": disallowed_in_trace,
        "target_called_in_trace": target_called,
        "target_causal_called_in_trace": (
            causal_t_called if (saw_c_arena and bool(t_norm_coupled)) else bool(target_called)
        ),
        "target_nonview_call_in_trace": (
            bool(target_nonview_called) if (saw_c_arena and bool(t_norm_coupled)) else bool(target_called)
        ),
        "target_called_selectors_in_trace": target_called_sels,
        "saw_exec_arena": bool(saw_c_arena),
        "eip7823_modexp_bound_exceeded": eip7823_modexp_exceeded,
        "eip8037_state_creates": eip8037_creates,
        "eip8037_code_bytes": eip8037_code_bytes,
        "fixed_stipend_call_detected": fixed_stipend_call,
        "trace_nodes_observed": trace_nodes,
        "observed_calldata_bytes": obs_cd,
        "observed_calldata_zero_bytes": obs_z,
        "observed_calldata_nonzero_bytes": obs_nz,
        "observed_gas_used": obs_gas,
        "observed_max_tx_gas": obs_max_tx_gas,
        "observed_tx_count": obs_tx_cnt,
        "observed_block_gas_used": obs_blk_gas,
        "observed_max_tx_block_gas": obs_max_tx_blk_gas,
        "target_coupled_addrs": coupled_addrs,
        "atomic_exit_subtrees": atomic_exit_subtrees,
        "trace_origin_inflows": trace_origin_inflows,
        "uncoupled_third_party_outflows": uncoupled_third_party_outflows,
        "caller_outflows_to_addrs": caller_outflows_to_addrs,
    }
    return metrics, out_l


def _run_single_replay_trace_summary(
    ws: Path,
    rel_test_path: str,
    test_name: str,
    timeout_sec: int = 35,
    fork_url: str = "",
    fork_block: int = 0,
    forbid_inline_fork: bool = False,
    target_addr: str = "",
    gas_price_wei: int = 0,
    offline: bool = False,
    target_addrs: Optional[Sequence[str]] = None,
    allowed_caller: str = "",
    *,
    forbid_top_level_revert: bool = False,
    require_nonreverted_target_call: bool = False,
    state_by_number: bool = False,
    chain: str = "",
) -> Dict[str, Any]:
    """
    단일 테스트에 대해 1회 리플레이(-vvvv --json)를 메모리에서 수행하여
    원시 전문 저장 없이 요약 메트릭, 대상 컨트랙트 실호출 여부 및 HEVM/하네스 트레이스 무결성을 추출한다.
    """
    eff_sbn = bool(state_by_number or (not offline and _requires_fork_state_by_number(chain, fork_url)))
    cmd = _build_forge_test_cmd(
        rel_test_path,
        fork_url="" if offline else fork_url,
        fork_block=fork_block,
        gas_price_wei=gas_price_wei,
        match_test=test_name,
        verbosity="-vvvv",
        ws=ws,
        state_by_number=eff_sbn,
    )
    try:
        proc = _run_forge_subproc(ws, cmd, timeout_sec)
        out = proc.stdout or ""
        metrics, out_l = _collect_trace_replay_metrics(
            out,
            forbid_inline_fork=forbid_inline_fork,
            target_addr=target_addr,
            target_addrs=target_addrs,
            allowed_caller=allowed_caller,
            match_test=test_name,
            forbid_top_level_revert=forbid_top_level_revert,
            require_nonreverted_target_call=require_nonreverted_target_call,
            chain=chain,
        )
        return {
            "replay_executed": proc.returncode == 0,
            "winning_test": test_name,
            **metrics,
            "conservation_event_verified": ("ConservationGain" in out or CONSERVATION_GAIN_TOPIC0[2:].lower() in out_l),
        }
    except Exception as exc:
        return {
            "replay_executed": False,
            "winning_test": test_name,
            "target_called_in_trace": False,
            "fallback_reason": str(exc)[:160],
            "disallowed_cheatcode_in_trace": False,
        }


_REAL_REPLAY_TRACE_FN = _run_single_replay_trace_summary


def _filter_objs_for_test(parsed_objs: Sequence[Dict[str, Any]], test_name: str) -> List[Dict[str, Any]]:
    clean_match = test_name.split("(", 1)[0].strip() if test_name else ""
    if not clean_match:
        return list(parsed_objs)
    filtered: List[Dict[str, Any]] = []
    for j_obj in parsed_objs:
        if not isinstance(j_obj, dict):
            continue
        if isinstance(j_obj.get("test_results"), dict):
            matched_tr = {
                tk: tv for tk, tv in j_obj["test_results"].items()
                if str(tk).split("(", 1)[0].strip() == clean_match
            }
            if matched_tr:
                cp = dict(j_obj)
                cp["test_results"] = matched_tr
                filtered.append(cp)
            continue
        new_obj: Dict[str, Any] = {}
        for sk, sv in j_obj.items():
            if isinstance(sv, dict) and isinstance(sv.get("test_results"), dict):
                matched_tr = {
                    tk: tv for tk, tv in sv["test_results"].items()
                    if str(tk).split("(", 1)[0].strip() == clean_match
                }
                if matched_tr:
                    cp_sv = dict(sv)
                    cp_sv["test_results"] = matched_tr
                    new_obj[sk] = cp_sv
        if new_obj:
            filtered.append(new_obj)
    return filtered


def replay_compiled_test_at_live_head(
    ws: Path,
    rel_test_path: str,
    rpc_url: str,
    live_head_block: int,
    match_test: str = "",
    timeout_sec: int = 60,
    gas_price_wei: int = 0,
    target_addr: str = "",
    target_addrs: Optional[Sequence[str]] = None,
    allowed_caller: str = "",
    chain: str = "",
) -> ForgeRunOutcome:
    """
    아티팩트 캐시 재사용(`--offline`, 무재컴파일) 최신 헤드($B_{\\text{head}}$) 리플레이 검증기:
    기준 블록($B_0$)에서 컴파일된 아티팩트를 재컴파일 없이 최신 쿼럼 헤드 블록에서 그대로 재실행하여 생존성을 확인한다.
    """
    rel_p_lh = Path(rel_test_path)
    if rel_p_lh.is_absolute() or ".." in rel_p_lh.parts:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=1,
            error_reason=f"LIVE_HEAD_INVALID_TEST_PATH:{rel_test_path}",
        )
    if (ws / "out" / rel_p_lh.name).is_dir():
        ok_out_lh, viol_out_lh = _scan_compiled_out_dir_allowlist(
            ws / "out",
            rel_p_lh.name,
            forbid_inline_fork=True,
            evm_version=_target_foundry_evm_version({chain: rpc_url}) if chain else "",
            require_artifacts=True,
        )
        if not ok_out_lh:
            return ForgeRunOutcome(
                executed=True,
                passed_tests=0,
                failed_tests=1,
                conservation_gains=[],
                error_reason=f"CHEATCODE_ARTIFACT_VIOLATION_AT_LIVE_HEAD:{','.join(viol_out_lh)}",
            )
    sbn_lh = _requires_fork_state_by_number(chain, rpc_url)
    cmd = _build_forge_test_cmd(
        rel_test_path,
        fork_url=rpc_url,
        fork_block=live_head_block,
        always_fork=True,
        gas_price_wei=gas_price_wei,
        match_test=match_test,
        verbosity="-vvvv",
        ws=ws,
        state_by_number=sbn_lh,
    )
    try:
        proc = _run_forge_subproc(ws, cmd, timeout_sec)
        if not sbn_lh and proc.returncode != 0 and "test_results" not in (proc.stdout or ""):
            if _text_has_any_marker(f"{proc.stderr or ''}\n{proc.stdout or ''}", _BLOCKHASH_STATE_ERR_MARKERS):
                cmd_retry = _build_forge_test_cmd(
                    rel_test_path,
                    fork_url=rpc_url,
                    fork_block=live_head_block,
                    always_fork=True,
                    gas_price_wei=gas_price_wei,
                    match_test=match_test,
                    verbosity="-vvvv",
                    ws=ws,
                    state_by_number=True,
                )
                proc = _run_forge_subproc(ws, cmd_retry, timeout_sec)
    except Exception as exc:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            error_reason=f"LIVE_HEAD_REPLAY_ERROR:{exc}",
        )
    out_txt = proc.stdout or ""
    parsed_lh_objs = _parse_json_dict_lines(out_txt)
    passed, failed, gains = _parse_forge_json_gains(out_txt, parsed_objs=parsed_lh_objs)
    err_combined_lh = f"{out_txt}\n{proc.stderr or ''}".lower()
    if (passed == 0 and failed == 0) or (
        passed == 0
        and _text_has_any_marker(err_combined_lh, _FORGE_RPC_FAIL_MARKERS)
        and "revert" not in err_combined_lh
    ):
        err_snip = (proc.stderr or out_txt or f"rc={proc.returncode}").strip()[:240]
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            raw_stdout=out_txt[:8000],
            raw_stderr=(proc.stderr or "")[:4000],
            error_reason=f"LIVE_HEAD_REPLAY_ERROR:{err_snip}",
        )
    lh_is_agent_test = Path(rel_test_path).name.lower().startswith("test_")
    lh_trace_sum, _ = _collect_trace_replay_metrics(
        out_txt,
        forbid_inline_fork=True,
        target_addr=target_addr,
        target_addrs=target_addrs,
        allowed_caller=allowed_caller,
        match_test=match_test,
        parsed_objs=parsed_lh_objs,
        forbid_top_level_revert=lh_is_agent_test,
        require_nonreverted_target_call=True,
        chain=chain,
    )
    disallowed_in_trace = bool(lh_trace_sum["disallowed_cheatcode_in_trace"])
    if match_test:
        lh_trace_sum["winning_test"] = match_test
        _record_per_test_trace_metrics(
            lh_trace_sum,
            match_test,
            int(lh_trace_sum["observed_gas_used"]),
            int(lh_trace_sum["observed_calldata_bytes"]),
            int(lh_trace_sum["observed_calldata_zero_bytes"]),
            int(lh_trace_sum["observed_calldata_nonzero_bytes"]),
            int(lh_trace_sum.get("observed_max_tx_gas") or 0),
            int(lh_trace_sum.get("observed_tx_count") or 0),
            int(lh_trace_sum.get("observed_block_gas_used") or 0),
            int(lh_trace_sum.get("observed_max_tx_block_gas") or 0),
        )
    if disallowed_in_trace:
        return ForgeRunOutcome(
            executed=True,
            passed_tests=0,
            failed_tests=max(1, passed + failed),
            conservation_gains=[],
            raw_stdout=out_txt[:8000],
            raw_stderr=(proc.stderr or "")[:4000],
            trace_summary=lh_trace_sum,
            error_reason="CHEATCODE_TRACE_VIOLATION_AT_LIVE_HEAD",
        )
    return ForgeRunOutcome(
        executed=(proc.returncode == 0 or passed > 0 or failed > 0),
        passed_tests=passed,
        failed_tests=failed,
        conservation_gains=gains,
        raw_stdout=out_txt[:8000],
        raw_stderr=(proc.stderr or "")[:4000],
        trace_summary=lh_trace_sum,
        error_reason="" if (proc.returncode == 0 and passed > 0 and failed == 0) else "LIVE_HEAD_REPLAY_FAILED",
    )


_CF_CONST_ADDR_RE: re.Pattern[str] = re.compile(
    r"(address\s+(?:(?:public|private|internal)\s+)*constant\s+(?:(?:public|private|internal)\s+)*TARGET\s*=\s*)(?:payable\s*\(\s*)?(?:address\s*\(\s*)?(?:uint160\s*\(\s*)?0[xX][0-9a-fA-F_]+(?:\s*\))*"
)
_CF_CODE_LEN_RE: re.Pattern[str] = re.compile(
    r"(?:\b(?:address\s*\(\s*)?(?:TARGET|0[xX]0{35}\d{5})(?:\s*\))?)\s*\.\s*code\s*\.\s*length\b"
)


def _mask_solidity_comments_same_len(src: str) -> str:
    """Replace comments and string literal interiors with spaces while keeping exact character indices 1:1."""
    out = list(src)
    n = len(out)
    i = 0
    while i < n:
        ch = out[i]
        nxt = out[i + 1] if (i + 1) < n else ""
        if ch == "/" and nxt == "/":
            out[i : i + 2] = (" ", " ")
            i += 2
            while i < n and out[i] != "\n":
                out[i] = " "
                i += 1
            continue
        if ch == "/" and nxt == "*":
            out[i : i + 2] = (" ", " ")
            i += 2
            while i < n:
                if out[i] == "*" and (i + 1) < n and out[i + 1] == "/":
                    out[i : i + 2] = (" ", " ")
                    i += 2
                    break
                if out[i] != "\n":
                    out[i] = " "
                i += 1
            continue
        if ch in ('"', "'"):
            q = ch
            i += 1
            while i < n:
                if out[i] == "\\":
                    if out[i] != "\n":
                        out[i] = " "
                    i += 1
                    if i < n and out[i] != "\n":
                        out[i] = " "
                    i += 1
                    continue
                if out[i] == q:
                    i += 1
                    break
                if out[i] != "\n":
                    out[i] = " "
                i += 1
            continue
        i += 1
    return "".join(out)


def verify_counterfactual_target_causality(
    ws: Path,
    rel_test_path: str,
    sol_code: str,
    target_addr: str,
    winning_test: str = "",
    fork_url: str = "",
    fork_block: int = 0,
    gas_price_wei: int = 0,
    timeout_sec: int = 45,
    match_test: str = "",
    offline: bool = False,
    closure_addrs: Optional[Sequence[str]] = None,
    preserve_addrs: Optional[Sequence[str]] = None,
    chain: str = "",
) -> CounterfactualCausalityResult:
    """
    인과성 반사실 검증(Counterfactual Target Causality Verification):
    테스트 컨트랙트에서 `TARGET` 및 대상 클로저(`target_addr`, `closure_addrs`)를 빈 무코드 주소로 치환했을 때에도
    `ConservationGain`이 그대로 발생하면, 대상 프로토콜과 무관한 외부 차익거래/더미 호출로 판정하여 기각(`False`)한다.
    단 `preserve_addrs`(외부 승인 계정 잔고 등)는 치환 대상에서 제외하여 오탐을 차단하며,
    예외 발생 시 Fail-Open 원칙에 따라 `False`를 반환한다.
    """
    t_norm = _norm_addr(target_addr)
    if not t_norm or not FORGE_BIN.exists():
        return CounterfactualCausalityResult(False, "COUNTERFACTUAL_MISSING_TARGET_OR_FORGE")
    noop_chk = "0x0000000000000000000000000000000000099998"
    mutated = sol_code
    preserve_set = {_norm_addr(x) for x in (preserve_addrs or []) if _norm_addr(x)} - {t_norm}
    all_targets = [t_norm] + [
        nx for x in (closure_addrs or []) if (nx := _norm_addr(x)) and nx not in preserve_set
    ]
    stub_addrs: List[str] = [noop_chk]
    seen_stubs: Set[str] = {noop_chk}
    for orig_a in all_targets:
        _append_unique(stub_addrs, seen_stubs, orig_a)
    repl_map: Dict[str, str] = {}
    for idx_t, addr_item in enumerate(dict.fromkeys(all_targets)):
        repl_addr = f"0x00000000000000000000000000000000000{max(10000, 99998 - idx_t):05d}"
        _append_unique(stub_addrs, seen_stubs, repl_addr)
        repl_map[addr_item.lower()] = repl_addr
    def _sub_unmasked_sol(src_s: str, pat: re.Pattern[str], repl_arg: Any) -> str:
        masked_s = _mask_solidity_comments_same_len(src_s)
        pieces: List[str] = []
        last_i = 0
        for m_u in pat.finditer(masked_s):
            pieces.append(src_s[last_i : m_u.start()])
            pieces.append(repl_arg(m_u) if callable(repl_arg) else m_u.expand(repl_arg))
            last_i = m_u.end()
        if not pieces:
            return src_s
        pieces.append(src_s[last_i:])
        return "".join(pieces)

    if repl_map:
        target_alt_re = _compiled_addr_alt_re(tuple(repl_map.keys()))
        mutated = _sub_unmasked_sol(
            mutated,
            target_alt_re,
            lambda m_a: repl_map[m_a.group(0).replace("_", "").lower()],
        )
    mutated = _sub_unmasked_sol(mutated, _CF_CONST_ADDR_RE, rf"\g<1>{noop_chk}")
    mutated = _sub_unmasked_sol(mutated, _CF_CODE_LEN_RE, "uint256(4096)")
    if mutated == sol_code:
        return CounterfactualCausalityResult(False, "COUNTERFACTUAL_TARGET_NOT_REFERENCED")
    masked_mutated = _mask_solidity_comments_same_len(mutated)
    if not _SOL_SETUP_FN_RE.search(masked_mutated):
        etch_stmts = " ".join(
            f"(bool _cfOk{i_s},) = address({HEVM_ADDRESS}).call(abi.encodeWithSelector({HEVM_ETCH_SEL}, address({_checksum(sa)}), _cfNoop)); _cfOk{i_s};"
            for i_s, sa in enumerate(stub_addrs)
        )
        setup_inj = f'\n    function setUp() public {{ bytes memory _cfNoop = hex"6101006000f3"; {etch_stmts} }}\n'
        inj_positions = [
            b_pos_cf
            for ck_cf, b_pos_cf, bodies_cf in _parse_solidity_contract_closures(masked_mutated, include_library=False).values()
            if ck_cf == "contract" and any(_SOL_TEST_FN_RE.search(bd_cf) is not None for bd_cf in bodies_cf)
        ]
        if not inj_positions:
            return CounterfactualCausalityResult(False, "COUNTERFACTUAL_SETUP_INJECTION_FAILED")
        for pos_cf in sorted(inj_positions, reverse=True):
            mutated = mutated[: pos_cf + 1] + setup_inj + mutated[pos_cf + 1 :]
    cf_stem = _safe_solidity_ident(Path(rel_test_path or "probe").stem.replace(".t", ""))
    cf_rel = f"test/_CounterfactualCausalityProbe_{cf_stem}.t.sol"
    cf_path = ws / cf_rel
    eff_test = match_test or winning_test
    try:
        cf_path.write_text(mutated, encoding="utf-8")
        use_sbn_cf = bool(not offline and _requires_fork_state_by_number(chain, fork_url))
        cmd = _build_forge_test_cmd(
            cf_rel,
            fork_url="" if offline else fork_url,
            fork_block=fork_block,
            gas_price_wei=gas_price_wei,
            match_test=eff_test,
            ws=ws,
            state_by_number=use_sbn_cf,
        )
        proc = _run_forge_subproc(ws, cmd, timeout_sec)
        if (
            not offline
            and fork_url
            and fork_block > 0
            and not use_sbn_cf
            and proc.returncode != 0
            and _text_has_any_marker(f"{proc.stderr or ''}\n{proc.stdout or ''}", _BLOCKHASH_STATE_ERR_MARKERS)
        ):
            cmd_retry_cf = _build_forge_test_cmd(
                cf_rel,
                fork_url=fork_url,
                fork_block=fork_block,
                gas_price_wei=gas_price_wei,
                match_test=eff_test,
                ws=ws,
                state_by_number=True,
            )
            proc = _run_forge_subproc(ws, cmd_retry_cf, timeout_sec)
        out_cf = proc.stdout or ""
        if "test_results" not in out_cf:
            return CounterfactualCausalityResult(False, "COUNTERFACTUAL_COMPILE_OR_EXEC_FAILED")
        cf_passed, cf_failed, cf_gains = _parse_forge_json_gains(out_cf)
        if (cf_passed + cf_failed) <= 0:
            # 변이 테스트가 단 1건도 실행되지 않았다면 "이득 0"은 인과성 증거가 될 수 없다(필터 불일치/컴파일 후 미실행).
            return CounterfactualCausalityResult(False, "COUNTERFACTUAL_MUTANT_NOT_EXECUTED")
        total_cf_gain = sum(
            int(g.get("caller_gain") or 0)
            for g in cf_gains
            if int(g.get("caller_gain") or 0) > 0
        )
        if total_cf_gain == 0:
            if cf_passed == 0 and cf_failed > 0:
                # 변이체가 실패했더라도 포크 RPC 장애(429/타임아웃/백엔드 오류)로 인한 실패라면 인과성 증명이 아니다.
                cf_err_txt = f"{out_cf}\n{proc.stderr or ''}".lower()
                if "revert" not in cf_err_txt and _text_has_any_marker(cf_err_txt, _FORGE_RPC_FAIL_MARKERS):
                    return CounterfactualCausalityResult(False, "COUNTERFACTUAL_MUTANT_NOT_EXECUTED:RPC_BACKEND_ERROR")
            return CounterfactualCausalityResult(True, "OK")
        return CounterfactualCausalityResult(False, "COUNTERFACTUAL_NON_CAUSAL_GAIN_PERSISTED")
    except Exception as exc:
        return CounterfactualCausalityResult(False, f"COUNTERFACTUAL_PROBE_ERROR:{exc}")
    finally:
        try:
            cf_path.unlink(missing_ok=True)
            shutil.rmtree(ws / "out" / Path(cf_rel).name, ignore_errors=True)
        except OSError:
            pass


def _decode_rpc_revert_reason(err_obj: Any) -> str:
    """JSON-RPC 에러/Revert 페이로드(Error(string), Panic(uint256), 4B CustomError)를 진단용 문자열로 디코딩."""
    if err_obj is None:
        return ""
    msg = ""
    raw_hex = ""
    if isinstance(err_obj, dict):
        msg = str(err_obj.get("message") or "")
        data_val = err_obj.get("data")
        if isinstance(data_val, str) and data_val.startswith("0x"):
            raw_hex = data_val
        elif isinstance(data_val, dict):
            d_inner = data_val.get("data") or data_val.get("result")
            if isinstance(d_inner, str) and d_inner.startswith("0x"):
                raw_hex = d_inner
            if not msg and data_val.get("message"):
                msg = str(data_val.get("message") or "")
    else:
        msg = str(err_obj)
    if not raw_hex and "0x" in msg:
        for tok in msg.split():
            tok_c = tok.strip(",:;\"'()[]{}")
            if tok_c.startswith("0x") and len(tok_c) >= 10:
                raw_hex = tok_c
                break
    if raw_hex:
        try:
            raw_b = _hex_to_bytes(raw_hex)
            if len(raw_b) >= 4:
                err_sel = "0x" + raw_b[:4].hex().lower()
                if err_sel == "0x08c379a0" and len(raw_b) >= 68:
                    dec_s = abi_decode(["string"], raw_b[4:])
                    if dec_s and isinstance(dec_s[0], str) and dec_s[0]:
                        return f"Revert:{dec_s[0][:120]}"
                elif err_sel == "0x4e487b71" and len(raw_b) >= 36:
                    p_code = int.from_bytes(raw_b[4:36], "big")
                    return f"Panic:0x{p_code:02x}"
                return f"CustomError:{err_sel}"
        except _PARSE_DATA_EXC:
            pass
    return msg[:140] if msg else ""


def _encode_prescreen_leg_calldata_variants(
    sl: CausalSlice,
    c_chk: str,
    *,
    token_addrs: Sequence[str] = (),
) -> List[Tuple[Optional[int], str]]:
    """
    1-leg 슬라이스에 대해 `_render_leg_invocation_solidity`와 동일한 역할 인식 ABI/추론 시그니처 +
    `witness_candidates[:3]` 조합의 `(witness_val, calldata_hex)` 목록을 생성한다.
    """
    if len(sl.legs) != 1:
        return []
    raw_sel = sl.legs[0]
    if not raw_sel.startswith("0x") or len(raw_sel) != 10:
        return []
    sel = raw_sel.lower()
    ver_types = sl.abi_inputs_by_sel.get(raw_sel) or sl.abi_inputs_by_sel.get(sel) or []
    inf_types = sl.inferred_abi_by_sel.get(raw_sel) or sl.inferred_abi_by_sel.get(sel) or []
    abi_types = ver_types if ver_types else inf_types
    param_names = (
        sl.abi_param_names_by_sel.get(raw_sel) or sl.abi_param_names_by_sel.get(sel) or []
        if ver_types
        else []
    )
    tok_chk = [_checksum(t) for t in token_addrs if _norm_addr(t)]
    leg_t = sl.leg_targets[0] if sl.leg_targets and _norm_addr(sl.leg_targets[0]) else sl.target_address
    v_chk = _checksum(leg_t) if _norm_addr(leg_t) else ""
    w_candidates: List[int] = [int(w) for w in (sl.witness_candidates[:3] if sl.witness_candidates else [1])]
    variants: List[Tuple[Optional[int], str]] = []
    seen_cd: Set[str] = set()

    def _push(w_val: Optional[int], cd: str) -> None:
        cd_l = cd.lower()
        if cd_l not in seen_cd:
            seen_cd.add(cd_l)
            variants.append((w_val, cd_l))

    if abi_types and _is_mechanical_renderable_abi(abi_types):
        needs_w = False
        probe_specs: List[Tuple[int, List[str], List[Any]]] = []
        for w_idx, w_raw in enumerate(w_candidates):
            enc_types: List[str] = []
            vals: List[Any] = []
            tok_cur = 0
            any_w_in_sig = False
            for p_idx, raw_t in enumerate(abi_types):
                ts = raw_t.strip()
                p_name = param_names[p_idx] if p_idx < len(param_names) else ""
                if _is_scalar_primitive_abi(ts):
                    _, (et, pv), uw, tok_cur = _build_abi_scalar_value_spec(
                        ts, p_name, c_chk, v_chk, tok_chk, "w", w_raw, tok_cur
                    )
                    enc_types.append(et)
                    vals.append(pv)
                    if uw:
                        any_w_in_sig = True
                elif _is_static_flat_tuple(ts):
                    sub_ts = [s.strip() for s in _split_top_level_csv(ts[1:-1])]
                    tup_vals: List[Any] = []
                    for st_s in sub_ts:
                        _, (_, pv_s), uw_s, tok_cur = _build_abi_scalar_value_spec(
                            st_s, p_name, c_chk, v_chk, tok_chk, "w", w_raw, tok_cur
                        )
                        tup_vals.append(pv_s)
                        if uw_s:
                            any_w_in_sig = True
                    enc_types.append(ts)
                    vals.append(tup_vals)
                elif ts.endswith("]"):
                    base_s, dim_s = _split_abi_array_suffix(ts)
                    b_t = base_s.strip()
                    _, (_, pv_a), uw_a, tok_cur = _build_abi_scalar_value_spec(
                        b_t, p_name, c_chk, v_chk, tok_chk, "w", w_raw, tok_cur
                    )
                    if uw_a:
                        any_w_in_sig = True
                    enc_types.append(ts)
                    vals.append([pv_a] * (int(dim_s) if dim_s else 1))
            if w_idx == 0:
                needs_w = any_w_in_sig
            probe_specs.append((w_raw, enc_types, vals))
            if not needs_w:
                break
        for w_raw, enc_types, vals in probe_specs:
            try:
                _push(w_raw if needs_w else None, encode_calldata(sel, enc_types, vals))
            except ABIError:
                pass
        if variants and ver_types:
            return variants

    _push(None, sel)
    for w_raw in w_candidates:
        w_u256 = int(w_raw) & _UINT256_MAX
        for sig_types, sig_vals in (
            (["uint256"], [w_u256]),
            (["address", "uint256"], [c_chk, w_u256]),
            (["uint256", "address", "address"], [w_u256, c_chk, c_chk]),
        ):
            try:
                _push(w_raw, encode_calldata(sel, sig_types, sig_vals))
            except ABIError:
                pass
    return variants


def prescreen_eth_call_batch(
    router: RPCRouter,
    chain: str,
    block_pin: int,
    caller: str,
    slices: List[CausalSlice],
    token_addrs: Optional[Sequence[str]] = None,
    *,
    max_probe_slices: int = 192,
    max_calls: int = 256,
) -> List[CausalSlice]:
    """
    1-leg 슬라이스(상위 max_probe_slices개)에 대해 역할 인식 매개변수·witness 변형 포함한 빠른 eth_call 배치 프리스크린을 수행하여
    실제 응답 슬라이스를 최우선 순위 + 히트 witness[0]으로 승격하고, Revert 사유 진단을 기록하며 명백한 상수 REVERT를 후순위로 배치.
    """
    if not slices:
        return []
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    c_chk = _checksum(caller)
    toks = list(token_addrs or ())
    probe_limit = max(48, int(max_probe_slices))
    call_budget = max(128, int(max_calls))

    active_indices: Set[int] = set()
    first_hit_witness: Dict[int, Tuple[int, int]] = {}
    slice_diag: Dict[int, Dict[str, Any]] = {}
    if block_pin > 0:
        eligible: List[Tuple[int, str, List[Tuple[Optional[int], str]]]] = []
        for idx, sl in enumerate(slices[:probe_limit]):
            variants = _encode_prescreen_leg_calldata_variants(sl, c_chk, token_addrs=toks)
            if not variants:
                continue
            first_to = (
                _checksum(sl.leg_targets[0])
                if (sl.leg_targets and _norm_addr(sl.leg_targets[0]))
                else _checksum(sl.target_address)
            )
            eligible.append((idx, first_to, variants))

        calls: List[Tuple[str, List[Any]]] = []
        meta_map: List[Tuple[int, int, Optional[int]]] = []
        tier = 0
        while eligible and len(calls) < call_budget:
            added_in_tier = False
            for idx, first_to, variants in eligible:
                if tier < len(variants):
                    w_cand, cd_hex = variants[tier]
                    calls.append(
                        (
                            "eth_call",
                            [{"from": c_chk, "to": first_to, "data": cd_hex}, btag],
                        )
                    )
                    meta_map.append((idx, tier, w_cand))
                    added_in_tier = True
                    if len(calls) >= call_budget:
                        break
            if not added_in_tier:
                break
            tier += 1

        if calls:
            res = router.batch_call(c, calls, block_pin=block_pin, need_archive=True)
            get_errs = router.get_last_batch_errors if hasattr(router, "get_last_batch_errors") else None
            batch_errs = get_errs() if callable(get_errs) else {}
            probed_cnts: Dict[int, int] = {}
            revert_reasons: Dict[int, str] = {}
            for call_i, ((slice_i, tier_i, w_cand), r) in enumerate(zip(meta_map, res)):
                probed_cnts[slice_i] = probed_cnts.get(slice_i, 0) + 1
                if isinstance(r, str) and r.startswith("0x"):
                    active_indices.add(slice_i)
                    slice_diag[slice_i] = {
                        "status": "active",
                        "hit_witness": str(w_cand) if w_cand is not None else "",
                        "ret_prefix": str(r)[:34],
                        "probed_count": probed_cnts[slice_i],
                    }
                    if w_cand is not None:
                        prev = first_hit_witness.get(slice_i)
                        if prev is None or tier_i < prev[0]:
                            first_hit_witness[slice_i] = (tier_i, int(w_cand))
                elif slice_i not in revert_reasons and call_i in batch_errs:
                    dec_rev = _decode_rpc_revert_reason(batch_errs[call_i])
                    if dec_rev:
                        revert_reasons[slice_i] = dec_rev
            for s_i, p_cnt in probed_cnts.items():
                if s_i not in active_indices:
                    d_ent: Dict[str, Any] = {"status": "reverted", "probed_count": p_cnt}
                    if s_i in revert_reasons:
                        d_ent["revert_reason"] = revert_reasons[s_i]
                    slice_diag[s_i] = d_ent

    def _with_diag(s_idx: int, sl_obj: CausalSlice) -> CausalSlice:
        diag_d = slice_diag.get(s_idx)
        hit_info = first_hit_witness.get(s_idx)
        new_ws = sl_obj.witness_candidates
        if hit_info is not None:
            hit_w = hit_info[1]
            existing_ws = [int(w) for w in (sl_obj.witness_candidates or [])]
            new_ws = [hit_w] + [w for w in existing_ws if w != hit_w]
        if diag_d is not None or new_ws is not sl_obj.witness_candidates:
            merged_diag = (
                {**(sl_obj.prescreen_diagnostics or {}), **diag_d}
                if diag_d is not None
                else sl_obj.prescreen_diagnostics
            )
            return dataclasses.replace(
                sl_obj,
                witness_candidates=new_ws,
                prescreen_diagnostics=merged_diag,
            )
        return sl_obj

    if not active_indices:
        ordered = [_with_diag(i, s) for i, s in enumerate(slices)]
    else:
        confirmed_active = [_with_diag(i, s) for i, s in enumerate(slices) if i in active_indices]
        active_main = [s for s in confirmed_active if not _is_trivial_approval_slice(s)]
        active_trivial = [s for s in confirmed_active if _is_trivial_approval_slice(s)]
        other_prioritized = [
            _with_diag(i, s)
            for i, s in enumerate(slices)
            if i not in active_indices and (len(s.legs) > 1 or s.needs_agent_synthesis)
        ]
        fallback = [
            _with_diag(i, s)
            for i, s in enumerate(slices)
            if i not in active_indices and len(s.legs) == 1 and not s.needs_agent_synthesis
        ]
        ordered = active_main + other_prioritized + active_trivial + fallback

    if len(ordered) > 48:
        head = ordered[:48]
        tail = ordered[48:]
        tail_agent = [s for s in tail if s.needs_agent_synthesis]
        tail_mech = [s for s in tail if not s.needs_agent_synthesis]
        if tail_agent:
            kept_agent = [s for s in head if s.needs_agent_synthesis]
            kept_mech = [s for s in head if not s.needs_agent_synthesis]
            all_agent = kept_agent + tail_agent
            non_triv_agent = [s for s in all_agent if not _is_trivial_approval_slice(s)]
            triv_agent = [s for s in all_agent if _is_trivial_approval_slice(s)]
            reordered = non_triv_agent + kept_mech + triv_agent + tail_mech
            return reordered
    return ordered


def execute_forge_test_file(
    ws: Path,
    rel_test_path: str,
    sol_code: str,
    timeout_sec: int = 75,
    allowed_caller: str = "",
    fork_url: str = "",
    fork_block: int = 0,
    forbid_inline_fork: bool = False,
    verify_trace_always: bool = False,
    target_addr: str = "",
    gas_price_wei: int = 0,
    offline: bool = False,
    strict_agent_accounting: bool = False,
    target_addrs: Optional[Sequence[str]] = None,
    chain: str = "",
) -> ForgeRunOutcome:
    """주어진 Foundry 워크스페이스 내 단일 .t.sol 파일에 대해 화이트리스트 검증(소스+바이트코드+트레이스), 실행(-vv --json) 및 1회 리플레이 수행."""
    ok_allow, violations = verify_cheatcode_allowlist(
        sol_code,
        allowed_caller=allowed_caller,
        forbid_inline_fork=forbid_inline_fork,
    )
    if not ok_allow:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            error_reason=f"CHEATCODE_ALLOWLIST_VIOLATION:{','.join(violations)}",
        )
    if forbid_inline_fork or strict_agent_accounting:
        ok_ast, ast_violations = verify_solidity_formal_ast(
            sol_code,
            allowed_caller=allowed_caller,
            forbid_inline_fork=forbid_inline_fork,
            strict_agent_accounting=strict_agent_accounting,
        )
        if not ok_ast:
            return ForgeRunOutcome(
                executed=False,
                passed_tests=0,
                failed_tests=0,
                error_reason=f"CHEATCODE_FORMAL_AST_VIOLATION:{','.join(ast_violations)}",
            )
    if strict_agent_accounting:
        ok_acct, acct_violations = verify_agent_harness_accounting_integrity(
            sol_code,
            allowed_caller=allowed_caller,
            allowed_target_addrs=([target_addr] + list(target_addrs or [])),
            chain=chain,
        )
        if not ok_acct:
            return ForgeRunOutcome(
                executed=False,
                passed_tests=0,
                failed_tests=0,
                error_reason=f"CHEATCODE_ACCOUNTING_VIOLATION:{','.join(acct_violations)}",
            )

    used_sbn = _requires_fork_state_by_number(chain, fork_url)
    single_pass_vvvv = bool(
        verify_trace_always
        and fork_block > 0
        and not offline
        and globals().get("_run_single_replay_trace_summary") is _REAL_REPLAY_TRACE_FN
    )
    eff_verb = "-vvvv" if single_pass_vvvv else "-vv"
    cmd = _build_forge_test_cmd(
        rel_test_path,
        fork_url=fork_url,
        fork_block=fork_block,
        gas_price_wei=gas_price_wei,
        verbosity=eff_verb,
        ws=ws,
        state_by_number=used_sbn,
    )
    try:
        proc = _run_forge_subproc(ws, cmd, timeout_sec)
        if not used_sbn and fork_block > 0 and fork_url and proc.returncode != 0 and "test_results" not in (proc.stdout or ""):
            if _text_has_any_marker(f"{proc.stderr or ''}\n{proc.stdout or ''}", _BLOCKHASH_STATE_ERR_MARKERS):
                used_sbn = True
                cmd_sbn = _build_forge_test_cmd(
                    rel_test_path,
                    fork_url=fork_url,
                    fork_block=fork_block,
                    gas_price_wei=gas_price_wei,
                    verbosity=eff_verb,
                    ws=ws,
                    state_by_number=True,
                )
                proc = _run_forge_subproc(ws, cmd_sbn, timeout_sec)
    except subprocess.TimeoutExpired:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            error_reason="FORGE_TIMEOUT",
        )
    except Exception as exc:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            error_reason=f"FORGE_EXEC_ERROR:{exc}",
        )

    sol_filename = Path(rel_test_path).name
    ok_bc, bc_violations = _scan_compiled_out_dir_allowlist(
        ws / "out",
        sol_filename,
        forbid_inline_fork=forbid_inline_fork,
        evm_version=_target_foundry_evm_version({chain: fork_url}) if chain else "",
        require_artifacts=(proc.returncode == 0),
    )
    if not ok_bc:
        return ForgeRunOutcome(
            executed=False,
            passed_tests=0,
            failed_tests=0,
            error_reason=f"BYTECODE_CHEATCODE_VIOLATION:{','.join(bc_violations)}",
        )

    raw_stdout_str = proc.stdout or ""
    objs_1 = _parse_json_dict_lines(raw_stdout_str)
    nft_gains_1: List[Dict[str, Any]] = []
    passed, failed, gains = _parse_forge_json_gains(raw_stdout_str, parsed_objs=objs_1, nft_gains_out=nft_gains_1)
    trace_sum: Dict[str, Any] = {}
    per_test_trace: Dict[str, Dict[str, Any]] = {}
    has_target_constraint = bool(_norm_addr(target_addr) or [a for a in (target_addrs or []) if _norm_addr(a)])

    def _run_trace_guard(test_fn: str, *, has_gain: bool = False) -> Optional[ForgeRunOutcome]:
        nonlocal trace_sum
        cur_sum: Optional[Dict[str, Any]] = None
        if single_pass_vvvv and proc.returncode == 0 and objs_1:
            clean_fn_sp = test_fn.split("(", 1)[0].strip()
            sub_objs_sp = _filter_objs_for_test(objs_1, test_fn)
            if sub_objs_sp and any(_iter_exec_trace_arenas(sub_objs_sp, clean_fn_sp)):
                metrics_sp, sub_out_l = _collect_trace_replay_metrics(
                    "",
                    forbid_inline_fork=forbid_inline_fork,
                    target_addr=target_addr,
                    target_addrs=target_addrs,
                    allowed_caller=allowed_caller,
                    match_test=test_fn,
                    parsed_objs=sub_objs_sp,
                    forbid_top_level_revert=bool(strict_agent_accounting and forbid_inline_fork and has_gain),
                    require_nonreverted_target_call=has_gain,
                    chain=chain,
                )
                cur_sum = {
                    "replay_executed": True,
                    "winning_test": test_fn,
                    **metrics_sp,
                    "conservation_event_verified": bool(
                        has_gain
                        or "conservationgain" in sub_out_l
                        or CONSERVATION_GAIN_TOPIC0[2:].lower() in sub_out_l
                    ),
                }
        if cur_sum is None:
            cur_sum = _run_single_replay_trace_summary(
                ws,
                rel_test_path,
                test_fn,
                timeout_sec=max(35, int(timeout_sec)),
                fork_url=fork_url,
                fork_block=fork_block,
                forbid_inline_fork=forbid_inline_fork,
                target_addr=target_addr,
                gas_price_wei=gas_price_wei,
                offline=(offline or fork_block <= 0),
                target_addrs=target_addrs,
                allowed_caller=allowed_caller,
                forbid_top_level_revert=bool(strict_agent_accounting and forbid_inline_fork and has_gain),
                require_nonreverted_target_call=has_gain,
                state_by_number=used_sbn,
                chain=chain,
            )
        per_test_trace[test_fn] = dict(cur_sum)
        cur_obs_cd, cur_obs_z, cur_obs_nz, cur_obs_gas, cur_obs_max_tx, cur_obs_tx_cnt, cur_obs_blk_gas, cur_obs_max_tx_blk = (
            int(cur_sum.get(k_o) or 0)
            for k_o in (
                "observed_calldata_bytes",
                "observed_calldata_zero_bytes",
                "observed_calldata_nonzero_bytes",
                "observed_gas_used",
                "observed_max_tx_gas",
                "observed_tx_count",
                "observed_block_gas_used",
                "observed_max_tx_block_gas",
            )
        )
        cur_8037_creates = int(cur_sum.get("eip8037_state_creates") or 0)
        cur_8037_bytes = int(cur_sum.get("eip8037_code_bytes") or 0)
        if not trace_sum:
            trace_sum = dict(cur_sum)
        else:
            trace_sum["replay_executed"] = bool(trace_sum.get("replay_executed", False) or cur_sum.get("replay_executed", False))
            trace_sum["target_called_in_trace"] = bool(trace_sum.get("target_called_in_trace", False) or cur_sum.get("target_called_in_trace", False))
            trace_sum["target_causal_called_in_trace"] = bool(
                trace_sum.get("target_causal_called_in_trace", False)
                or cur_sum.get("target_causal_called_in_trace", False)
            )
            trace_sum["target_nonview_call_in_trace"] = bool(
                trace_sum.get("target_nonview_call_in_trace", False)
                or cur_sum.get("target_nonview_call_in_trace", False)
            )
            trace_sum["disallowed_cheatcode_in_trace"] = bool(
                trace_sum.get("disallowed_cheatcode_in_trace", False) or cur_sum.get("disallowed_cheatcode_in_trace", False)
            )
            trace_sum["eip7823_modexp_bound_exceeded"] = bool(
                trace_sum.get("eip7823_modexp_bound_exceeded", False) or cur_sum.get("eip7823_modexp_bound_exceeded", False)
            )
            trace_sum["fixed_stipend_call_detected"] = bool(
                trace_sum.get("fixed_stipend_call_detected", False) or cur_sum.get("fixed_stipend_call_detected", False)
            )
            for _mk_i, _mv_i in (
                ("observed_gas_used", cur_obs_gas),
                ("observed_max_tx_gas", cur_obs_max_tx),
                ("observed_tx_count", cur_obs_tx_cnt),
                ("observed_block_gas_used", cur_obs_blk_gas),
                ("observed_max_tx_block_gas", cur_obs_max_tx_blk),
                ("eip8037_state_creates", cur_8037_creates),
                ("eip8037_code_bytes", cur_8037_bytes),
            ):
                if _mv_i > int(trace_sum.get(_mk_i) or 0):
                    trace_sum[_mk_i] = _mv_i
            if cur_obs_cd > int(trace_sum.get("observed_calldata_bytes") or 0):
                trace_sum["observed_calldata_bytes"] = cur_obs_cd
                trace_sum["observed_calldata_zero_bytes"] = cur_obs_z
                trace_sum["observed_calldata_nonzero_bytes"] = cur_obs_nz
            for merge_k in ("called_targets", "target_coupled_addrs", "target_called_selectors_in_trace"):
                if cur_sum.get(merge_k):
                    trace_sum[merge_k] = list(
                        dict.fromkeys(list(trace_sum.get(merge_k) or []) + list(cur_sum.get(merge_k) or []))
                    )
        pt_coupled_map = dict(trace_sum.get("per_test_target_coupled_addrs") or {})
        pt_coupled_map[test_fn] = list(cur_sum.get("target_coupled_addrs") or [])
        trace_sum["per_test_target_coupled_addrs"] = pt_coupled_map
        pt_saw_map = dict(trace_sum.get("per_test_saw_exec_arena") or {})
        pt_saw_map[test_fn] = bool(cur_sum.get("saw_exec_arena", False))
        trace_sum["per_test_saw_exec_arena"] = pt_saw_map
        if cur_sum.get("saw_exec_arena"):
            trace_sum["saw_exec_arena"] = True
        pt_sub_map = dict(trace_sum.get("per_test_atomic_exit_subtrees") or {})
        pt_sub_map[test_fn] = list(cur_sum.get("atomic_exit_subtrees") or [])
        trace_sum["per_test_atomic_exit_subtrees"] = pt_sub_map
        pt_ori_map = dict(trace_sum.get("per_test_trace_origin_inflows") or {})
        pt_ori_map[test_fn] = list(cur_sum.get("trace_origin_inflows") or [])
        trace_sum["per_test_trace_origin_inflows"] = pt_ori_map
        pt_3p_map = dict(trace_sum.get("per_test_uncoupled_third_party_outflows") or {})
        pt_3p_map[test_fn] = list(cur_sum.get("uncoupled_third_party_outflows") or [])
        trace_sum["per_test_uncoupled_third_party_outflows"] = pt_3p_map
        pt_co_map = dict(trace_sum.get("per_test_caller_outflows_to_addrs") or {})
        pt_co_map[test_fn] = list(cur_sum.get("caller_outflows_to_addrs") or [])
        trace_sum["per_test_caller_outflows_to_addrs"] = pt_co_map
        pt_modexp_map = dict(trace_sum.get("per_test_eip7823_modexp_bound_exceeded") or {})
        pt_modexp_map[test_fn] = bool(cur_sum.get("eip7823_modexp_bound_exceeded", False))
        trace_sum["per_test_eip7823_modexp_bound_exceeded"] = pt_modexp_map
        pt_8037_cr_map = dict(trace_sum.get("per_test_eip8037_state_creates") or {})
        pt_8037_cr_map[test_fn] = cur_8037_creates
        trace_sum["per_test_eip8037_state_creates"] = pt_8037_cr_map
        pt_8037_cb_map = dict(trace_sum.get("per_test_eip8037_code_bytes") or {})
        pt_8037_cb_map[test_fn] = cur_8037_bytes
        trace_sum["per_test_eip8037_code_bytes"] = pt_8037_cb_map
        _record_per_test_trace_metrics(
            trace_sum,
            test_fn,
            cur_obs_gas,
            cur_obs_cd,
            cur_obs_z,
            cur_obs_nz,
            cur_obs_max_tx,
            cur_obs_tx_cnt,
            cur_obs_blk_gas,
            cur_obs_max_tx_blk,
        )
        if cur_sum.get("disallowed_cheatcode_in_trace"):
            return ForgeRunOutcome(
                executed=False,
                passed_tests=0,
                failed_tests=0,
                error_reason="TRACE_CHEATCODE_VIOLATION",
            )
        return None

    if gains:
        seen_t_names: List[str] = [
            tn for tn in dict.fromkeys(str(g.get("test") or "").strip() for g in gains) if tn
        ]
        for t_name in seen_t_names:
            viol_out = _run_trace_guard(t_name, has_gain=True)
            if viol_out is not None:
                return viol_out
        if seen_t_names and not trace_sum.get("replay_executed", False):
            return ForgeRunOutcome(
                executed=False,
                passed_tests=0,
                failed_tests=0,
                error_reason="TRACE_REPLAY_UNVERIFIED",
            )
        if seen_t_names and has_target_constraint:
            valid_gain_tests = {
                tn
                for tn in seen_t_names
                if bool(per_test_trace.get(tn, {}).get("replay_executed", False))
                and bool(per_test_trace.get(tn, {}).get("target_called_in_trace", False))
                and bool(per_test_trace.get(tn, {}).get("target_causal_called_in_trace", True))
            }
            gains = [g for g in gains if str(g.get("test") or "").strip() in valid_gain_tests]
            trace_sum["target_called_in_trace"] = bool(valid_gain_tests)
            trace_sum["target_causal_called_in_trace"] = bool(valid_gain_tests)
            for pt_key in (
                "per_test_observed_gas_used",
                "per_test_observed_max_tx_gas",
                "per_test_observed_tx_count",
                "per_test_observed_block_gas_used",
                "per_test_observed_max_tx_block_gas",
                "per_test_observed_calldata_bytes",
                "per_test_observed_calldata_stats",
                "per_test_target_coupled_addrs",
                "per_test_saw_exec_arena",
                "per_test_atomic_exit_subtrees",
                "per_test_trace_origin_inflows",
                "per_test_uncoupled_third_party_outflows",
                "per_test_caller_outflows_to_addrs",
                "per_test_eip7823_modexp_bound_exceeded",
                "per_test_eip8037_state_creates",
                "per_test_eip8037_code_bytes",
            ):
                pt_dict = trace_sum.get(pt_key)
                if isinstance(pt_dict, dict):
                    trace_sum[pt_key] = {k: v for k, v in pt_dict.items() if k in valid_gain_tests}
        if gains:
            best_by_test: Dict[str, int] = {}
            for g in gains:
                tn = str(g.get("test") or "").strip()
                if not tn:
                    continue
                con_v = min(int(g.get("caller_gain") or 0), int(g.get("vault_loss") or 0))
                if tn not in best_by_test or con_v > best_by_test[tn]:
                    best_by_test[tn] = con_v
            win_t = ""
            if best_by_test:
                win_t = max(sorted(best_by_test.keys()), key=lambda tn: best_by_test[tn])
            if win_t:
                trace_sum["winning_test"] = win_t
                win_pt = per_test_trace.get(win_t, {})
                trace_sum["target_coupled_addrs"] = list(win_pt.get("target_coupled_addrs") or [])
                trace_sum["saw_exec_arena"] = bool(win_pt.get("saw_exec_arena", False))
                trace_sum["atomic_exit_subtrees"] = list(win_pt.get("atomic_exit_subtrees") or [])
                trace_sum["trace_origin_inflows"] = list(win_pt.get("trace_origin_inflows") or [])
                trace_sum["uncoupled_third_party_outflows"] = list(win_pt.get("uncoupled_third_party_outflows") or [])
                trace_sum["caller_outflows_to_addrs"] = list(win_pt.get("caller_outflows_to_addrs") or [])
                trace_sum["target_causal_called_in_trace"] = bool(win_pt.get("target_causal_called_in_trace", True))
                win_obs_gas = int(win_pt.get("observed_gas_used") or 0)
                win_obs_cd = int(win_pt.get("observed_calldata_bytes") or 0)
                win_obs_z = int(win_pt.get("observed_calldata_zero_bytes") or 0)
                win_obs_nz = int(win_pt.get("observed_calldata_nonzero_bytes") or 0)
                trace_sum["observed_gas_used"] = win_obs_gas
                trace_sum["observed_max_tx_gas"] = int(win_pt.get("observed_max_tx_gas") or 0)
                trace_sum["observed_tx_count"] = int(win_pt.get("observed_tx_count") or 0)
                trace_sum["observed_block_gas_used"] = int(win_pt.get("observed_block_gas_used") or 0)
                trace_sum["observed_max_tx_block_gas"] = int(win_pt.get("observed_max_tx_block_gas") or 0)
                trace_sum["eip8037_state_creates"] = int(win_pt.get("eip8037_state_creates") or 0)
                trace_sum["eip8037_code_bytes"] = int(win_pt.get("eip8037_code_bytes") or 0)
                trace_sum["observed_calldata_bytes"] = win_obs_cd
                if (win_obs_z + win_obs_nz) > 0:
                    trace_sum["observed_calldata_zero_bytes"] = win_obs_z
                    trace_sum["observed_calldata_nonzero_bytes"] = win_obs_nz
                else:
                    trace_sum.pop("observed_calldata_zero_bytes", None)
                    trace_sum.pop("observed_calldata_nonzero_bytes", None)
    elif verify_trace_always and passed > 0 and failed == 0:
        clean_sol_fn = _strip_solidity_comments_preserve_strings(sol_code)
        fn_matches = [m.group(1) for m in _SOL_TEST_FN_RE.finditer(clean_sol_fn)]
        target_fns = fn_matches or ["test"]
        for fn_name in target_fns:
            viol_out = _run_trace_guard(fn_name)
            if viol_out is not None:
                return viol_out
        if target_fns and not all(per_test_trace.get(fn, {}).get("replay_executed", False) for fn in target_fns):
            return ForgeRunOutcome(
                executed=False,
                passed_tests=0,
                failed_tests=0,
                error_reason="TRACE_REPLAY_UNVERIFIED",
            )

    err_reason_out = ""
    rpc_fork_corrupt = False
    if not (proc.returncode == 0 or passed > 0):
        err_blob = f"{proc.stderr or ''}\n{proc.stdout or ''}".strip()
        is_rpc_fork_fail = (
            _is_auth_denied_rpc_error(err_blob)
            or _classify_rpc_error(err_blob) in ("quota", "wrong_chain")
            or _text_has_any_marker(err_blob, _FORGE_RPC_FAIL_MARKERS)
        )
        if passed == 0 and failed > 0 and is_rpc_fork_fail:
            rpc_fork_corrupt = True
            err_reason_out = f"FORGE_NONZERO_EXIT:{' '.join(err_blob.split())[:200]}"
        elif passed == 0 and failed == 0 and is_rpc_fork_fail:
            err_reason_out = f"FORGE_NONZERO_EXIT:{' '.join(err_blob.split())[:200]}"
        else:
            err_reason_out = f"FORGE_COMPILE_OR_EXEC_ERROR:{' '.join(err_blob.split())[:220]}" if (passed == 0 and failed == 0 and err_blob) else "FORGE_NONZERO_EXIT"

    return ForgeRunOutcome(
        executed=(not rpc_fork_corrupt and (proc.returncode == 0 or passed > 0 or failed > 0)),
        passed_tests=passed,
        failed_tests=failed,
        conservation_gains=gains,
        nft_gains=nft_gains_1,
        trace_summary=trace_sum,
        raw_stdout=(proc.stdout or "")[:8000],
        raw_stderr=(proc.stderr or "")[:4000],
        error_reason=err_reason_out,
    )


