def _eval_archive_probe_resp(obj: Any) -> bool:
    """Return True if an eth_call archive probe succeeded (or executed & reverted)."""
    if not isinstance(obj, dict):
        return False
    if obj.get("error"):
        err_obj = obj["error"]
        err_msg = str((err_obj.get("message") if isinstance(err_obj, dict) else err_obj) or "").lower()
        return "revert" in err_msg
    res_v = obj.get("result")
    return isinstance(res_v, str) and res_v.startswith("0x")


def _merge_observed_calldata_stats(merged_trace: Dict[str, Any], ts_c: Mapping[str, Any]) -> None:
    merged_trace["observed_calldata_bytes"] = int(ts_c["observed_calldata_bytes"])
    if int(ts_c.get("observed_calldata_zero_bytes", -1)) >= 0 and int(ts_c.get("observed_calldata_nonzero_bytes", -1)) >= 0:
        merged_trace["observed_calldata_zero_bytes"] = int(ts_c["observed_calldata_zero_bytes"])
        merged_trace["observed_calldata_nonzero_bytes"] = int(ts_c["observed_calldata_nonzero_bytes"])


def _is_nonzero_nonce_eoa(router: Optional[RPCRouter], chain: str, addr: str, block_pin: int) -> bool:
    if router is None or block_pin <= 0:
        return False
    try:
        txc_raw = router.call(
            chain,
            "eth_getTransactionCount",
            [_checksum(addr), hex(block_pin)],
            block_pin=block_pin,
            need_archive=True,
        )
        return isinstance(txc_raw, str) and txc_raw.startswith("0x") and len(txc_raw) > 2 and int(txc_raw, 16) > 0
    except Exception:
        return False


_FORK_PROXY_CACHE_DIR: Path = CACHE_DIR / "_fork_rpc"
_SOL_TOK_CONST_ADDR_RE: re.Pattern[str] = re.compile(r"\baddress\s+constant\s+TOK_\d+\s*=\s*(0x[0-9a-fA-F]{40})\b")
_SOL_VAULT_CONST_ADDR_RE: re.Pattern[str] = re.compile(r"\baddress\s+constant\s+VAULT_\d+\s*=\s*(0x[0-9a-fA-F]{40})\b")


def _shared_fork_rpc_cache_path(chain: str, block_pin: int) -> Optional[Path]:
    c_n = _norm_chain(chain)
    bp = int(block_pin or 0)
    if not c_n or bp <= 0:
        return None
    return _FORK_PROXY_CACHE_DIR / f"{c_n}_{bp}.json"


def _extract_sol_harness_addrs(sol_code: str) -> Tuple[List[str], List[str]]:
    if not sol_code:
        return [], []
    toks = list(dict.fromkeys(a.lower() for a in _SOL_TOK_CONST_ADDR_RE.findall(sol_code)))
    vaults = list(dict.fromkeys(a.lower() for a in _SOL_VAULT_CONST_ADDR_RE.findall(sol_code)))
    return toks, vaults


