# §7. 가치 보존 회계(Conservation of Value), 실시간 원화(KRW) 정산,
#     pins.json 무결성 봉인 및 E4 에이전트 위임 경계 (poc_requests / verdicts)
# ═══════════════════════════════════════════════════════════════════════════


def _http_get_json_with_fallback(router: Optional[Any], url: str, timeout: float = 8.0) -> Any:
    http_get_fn = getattr(router, "http_get_json", None) if router is not None else None
    if callable(http_get_fn):
        return http_get_fn(url, timeout=timeout)
    req = urllib.request.Request(url, headers={"User-Agent": "DefiAuditEngine/1.0"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8", errors="replace"))


@_with_decimal_prec_100
def _fetch_usd_krw_rate_dec(
    store: Optional[SQLiteStore] = None,
    allow_offline_fixture: bool = False,
    router: Optional[RPCRouter] = None,
    session_id: str = "",
) -> Tuple[Decimal, str]:
    """
    세션 단일 봉인 실시간 USD/KRW 고정밀 Decimal 환율 조회:
    - 감사 세션 개시 시 다중 원천(Frankfurter / Open ER API)을 교차 조회하여 `engine_meta('session_usd_krw')` 및 세션 스코프 키에 봉인.
    - 오프라인 모의 실행(`allow_offline_fixture=True` 또는 `store is None`)에서만 합성 픽스처(`1400`)를 허용하며,
      실전 런타임에서 환율 미확정 시 `(0, 'unavailable')`을 반환하여 임의 상수 폴백 없이 `미검증 차단` 처리한다.
    """
    sid = str(session_id or "").strip().lower()
    allow_cached_fixture = bool(
        allow_offline_fixture or (router is not None and not _is_live_real_router(router))
    )

    def _seal_session_fx(rate_d: Decimal, src_val: str) -> None:
        if store is None:
            return
        now_str = f"{time.time():.3f}"
        rate_str = format(rate_d, "f")
        store.put_engine_meta("session_usd_krw", rate_str)
        store.put_engine_meta("session_usd_krw_source", src_val)
        store.put_engine_meta("session_usd_krw_boot", BOOT_ID)
        store.put_engine_meta("session_usd_krw_at", now_str)
        if sid:
            store.put_engine_meta(f"session_usd_krw:{sid}", rate_str)
            store.put_engine_meta(f"session_usd_krw_source:{sid}", src_val)
            store.put_engine_meta(f"session_usd_krw_at:{sid}", now_str)

    if store is not None:
        if sid:
            s_val = store.get_engine_meta(f"session_usd_krw:{sid}", "")
            s_src = store.get_engine_meta(f"session_usd_krw_source:{sid}", "sealed:session")
            if s_val and (allow_cached_fixture or not str(s_src).startswith("fixture:")):
                try:
                    sv_d = _to_dec(s_val)
                    if Decimal("500") < sv_d < Decimal("5000"):
                        return sv_d, s_src
                except _PARSE_DATA_EXC:
                    pass
        sealed_val = store.get_engine_meta("session_usd_krw", "")
        sealed_src = store.get_engine_meta("session_usd_krw_source", "sealed:session")
        sealed_boot = store.get_engine_meta("session_usd_krw_boot", "")
        sealed_at_raw = store.get_engine_meta("session_usd_krw_at", "")
        if sealed_val and sealed_boot == BOOT_ID and sealed_at_raw and (allow_cached_fixture or not str(sealed_src).startswith("fixture:")):
            try:
                sv_d = _to_dec(sealed_val)
                sat_d = _to_dec(sealed_at_raw)
                if Decimal("500") < sv_d < Decimal("5000") and _DEC_ZERO <= (_to_dec(int(time.time())) - sat_d) <= Decimal("3600"):
                    return sv_d, sealed_src
            except ValueError:
                pass
        cached = store.get_price_dec("FX:USD_KRW", max_age_sec=3600) or store.get_price_dec("fx:USD_KRW", max_age_sec=3600)
        if cached is not None:
            cached_d = cached[0]
            if Decimal("500") < cached_d < Decimal("5000") and (
                allow_cached_fixture or not str(cached[1] or "").startswith("fixture:")
            ):
                _seal_session_fx(cached_d, cached[1])
                return cached_d, cached[1]

    if not allow_offline_fixture and store is not None:
        fx_urls = (
            "https://api.frankfurter.dev/v1/latest?base=USD&symbols=KRW",
            "https://open.er-api.com/v6/latest/USD",
            "https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/usd.json",
        )

        def _fetch_one_fx(url_fx: str) -> Decimal:
            try:
                data = _http_get_json_with_fallback(router, url_fx, timeout=8)
                if not isinstance(data, dict):
                    return _DEC_ZERO
                r_obj = data.get("rates")
                if isinstance(r_obj, dict) and "KRW" in r_obj:
                    krw_d = _to_dec(r_obj.get("KRW", 0))
                else:
                    usd_obj = data.get("usd")
                    krw_d = _to_dec(usd_obj.get("krw", 0)) if isinstance(usd_obj, dict) else _DEC_ZERO
                return krw_d if Decimal("500") < krw_d < Decimal("5000") else _DEC_ZERO
            except Exception:
                return _DEC_ZERO

        rates: List[Decimal] = [
            r_d
            for r_d in _parallel_map_list(
                _fetch_one_fx,
                fx_urls,
                max_workers=3,
                parallel=(router is None or _is_live_real_router(router)),
            )
            if r_d > _DEC_ZERO
        ]
        if len(rates) >= 2:
            rates.sort()
            if (rates[-1] - rates[0]) / rates[0] > Decimal("0.08"):
                return _DEC_ZERO, "unavailable:fx_divergence"
            cons_krw_d = rates[0]
            src_tag = "observed:multi_source"
            store.put_price("FX:USD_KRW", cons_krw_d, src_tag)
            _seal_session_fx(cons_krw_d, src_tag)
            return cons_krw_d, src_tag
        if len(rates) == 1:
            return _DEC_ZERO, "unavailable:single_source_fx_fail_open"
        return _DEC_ZERO, "unavailable"

    return _to_dec(FALLBACK_USD_KRW), "fixture:offline_1400"


@_with_decimal_prec_100
def _fetch_token_price_usd_dec(
    store: Optional[SQLiteStore],
    chain: str,
    token_addr: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
    _allow_live_xcheck: bool = True,
) -> Tuple[Decimal, str]:
    """DeFiLlama Coins API + 온체인 기준 블록 고정밀 Decimal 단가 조회 (라이브 감사 시 하드코딩 상수 폴백 금지)."""
    c = _norm_chain(chain)
    t_norm = _norm_addr(token_addr)
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    if not t_norm or t_norm == "0x0000000000000000000000000000000000000000" or (wnative and t_norm == wnative) or t_norm in alias_set:
        p_nat_d = _estimate_native_price_dec(c, router=router, block_pin=block_pin, allow_offline_fixture=allow_offline_fixture)
        return p_nat_d, ("derived:native_live" if p_nat_d > _DEC_ZERO else "unavailable:native_price")
    live_xcheck_ctx = bool(_allow_live_xcheck and block_pin > 0 and not allow_offline_fixture and _is_live_real_router(router))
    cache_prefix = "TOKEN" if _allow_live_xcheck else "TOKEN_REF"
    cache_key = f"{cache_prefix}:{c}:{t_norm}:{int(block_pin)}" if block_pin > 0 else f"{cache_prefix}:{c}:{t_norm}"
    if store is not None:
        cached = store.get_price_dec(cache_key, max_age_sec=1800)
        if cached is not None and cached[0] > _DEC_ZERO:
            c_src = str(cached[1] or "")
            live_router_pin = bool(block_pin > 0 and not allow_offline_fixture and _is_live_real_router(router))
            if (not live_router_pin) or (
                not c_src.startswith("fixture:")
                and ((not _allow_live_xcheck) or c_src == "onchain:llama_dex_xcheck")
            ):
                return cached[0], cached[1]
    if live_xcheck_ctx:
        nat_p_lo_d = _estimate_native_price_dec(c, router=router, block_pin=block_pin, allow_offline_fixture=False)
        if nat_p_lo_d > _DEC_ZERO and router is not None:
            p_dec_x: Dict[str, Decimal] = {}
            _resolve_token_metadata_batch(
                router, c, [t_norm], block_pin, native_price_usd=nat_p_lo_d, prices_dec_out=p_dec_x
            )
            x_price_d = p_dec_x.get(t_norm, _DEC_ZERO)
            if x_price_d > _DEC_ZERO:
                if store is not None:
                    store.put_price(cache_key, x_price_d, "onchain:llama_dex_xcheck")
                return x_price_d, "onchain:llama_dex_xcheck"
        return _DEC_ZERO, "unavailable:single_source_or_uncorroborated"
    blk_ts = _fetch_block_timestamp(router, c, block_pin)
    l_pref = _llama_chain_prefix(c)
    urls = (
        (
            f"https://coins.llama.fi/prices/historical/{blk_ts}/{l_pref}:{t_norm}",
            f"https://coins.llama.fi/prices/current/{l_pref}:{t_norm}",
        )
        if blk_ts > 1_500_000_000
        else (f"https://coins.llama.fi/prices/current/{l_pref}:{t_norm}",)
    )
    for url in urls:
        try:
            data = _http_get_json_with_fallback(router, url, timeout=8)
            coins_d = data.get("coins") if isinstance(data, dict) else {}
            coin_obj = (coins_d.get(f"{l_pref}:{t_norm}") or coins_d.get(f"{c}:{t_norm}") or {}) if isinstance(coins_d, dict) else {}
            price_d = _to_dec(coin_obj.get("price", 0))
            if price_d > _DEC_ZERO:
                src_tag = "observed:defillama_coins_historical" if "/historical/" in url else "observed:defillama_coins"
                if store is not None:
                    store.put_price(cache_key, price_d, src_tag)
                return price_d, src_tag
        except Exception:
            continue
    if allow_offline_fixture and t_norm in _norm_chain_stables_set(c):
        return Decimal("1"), "fixture:chain_stable_peg"
    return _DEC_ZERO, "unavailable:unconfirmed_token"


