def _merge_len_intervals(bounds: Sequence[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not bounds:
        return []
    ordered = sorted((max(64, int(lo)), max(64, int(hi))) for lo, hi in bounds)
    merged: List[Tuple[int, int]] = [ordered[0]]
    for lo, hi in ordered[1:]:
        p_lo, p_hi = merged[-1]
        if lo <= p_hi + 64:
            merged[-1] = (p_lo, max(p_hi, hi))
        else:
            merged.append((lo, hi))
    return merged


_BALLPARK_NATIVE_USD_BY_CHAIN: Dict[str, Decimal] = {
    "bsc": Decimal("600"),
    "opbnb": Decimal("600"),
    "avalanche": Decimal("25"),
    "polygon": Decimal("0.4"),
    "fantom": Decimal("0.5"),
    "sonic": Decimal("0.5"),
    "gnosis": Decimal("1"),
    "celo": Decimal("0.6"),
    "mantle": Decimal("0.8"),
    "cronos": Decimal("0.1"),
    "kaia": Decimal("0.15"),
    "sei": Decimal("0.3"),
    "berachain": Decimal("4"),
    "hyperevm": Decimal("20"),
    "monad": Decimal("1"),
}


def _clone_fund_rank_boost(hint_usd_d: Decimal) -> Decimal:
    """보유 자금 추정치(USD, Decimal)에 기반한 단조 증가형 Priority-1 랭크 가산점 계산."""
    if not hint_usd_d.is_finite() or hint_usd_d <= _DEC_ZERO:
        return _DEC_ZERO
    return min(Decimal("500000"), hint_usd_d) + (Decimal("1") + hint_usd_d).ln()


@_with_decimal_prec_100
def _probe_clone_liquid_balance_hints(
    router: Optional[RPCRouter],
    chain_addrs: Sequence[Tuple[str, str]],
) -> Dict[Tuple[str, str], Decimal]:
    """
    Mode B 클론 후보들의 온체인 네이티브/WNATIVE/주요 스테이블코인 잔고 규모(USD 근사치)를
    체인당 최대 2회 배치 RPC(eth_getBalance + Multicall3.balanceOf)로 스냅샷하여 자금 보유 클론 우선 정렬에 활용.
    """
    if router is None or not chain_addrs:
        return {}
    is_mock = (
        type(router).call is not RPCRouter.call
        or "call" in router.__dict__
        or type(router).batch_call is not RPCRouter.batch_call
        or "batch_call" in router.__dict__
    )
    if getattr(socket.getaddrinfo, "__name__", "") == "_guarded_getaddrinfo" and not is_mock:
        return {}
    by_chain: Dict[str, List[str]] = {}
    seen_by_chain: Dict[str, Set[str]] = {}
    for ch, ad in chain_addrs:
        c_nm = _norm_chain(ch)
        na = _norm_addr(ad)
        if not c_nm or not na:
            continue
        lst = by_chain.setdefault(c_nm, [])
        seen_c = seen_by_chain.setdefault(c_nm, set())
        if len(lst) < 192 and na not in seen_c:
            seen_c.add(na)
            lst.append(na)
    bal_sel = bytes.fromhex(BALANCE_OF_SEL[2:])
    dec_sel = bytes.fromhex(DECIMALS_SEL[2:])

    @_with_decimal_prec_100
    def _probe_chain_entry(item_ca: Tuple[str, List[str]]) -> Dict[Tuple[str, str], Decimal]:
        c_nm, addrs = item_ca
        loc_dec: Dict[Tuple[str, str], Decimal] = {}
        try:
            wn = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c_nm) or "")
            stables = [
                na for s in (CHAIN_STABLES.get(c_nm) or ())[:4]
                if (na := _norm_addr(s)) and na != wn
            ]
            seen_t_probe: Set[str] = ({wn} if wn else set()) | set(stables)
            bluechips = [
                na for b in (CHAIN_BLUECHIPS.get(c_nm) or ())[:2]
                if (na := _norm_addr(b)) and na not in seen_t_probe
            ]
            btc_bluechips: Set[str] = {
                _norm_addr(x)
                for x in (
                    "0x2260fac5e5542a773aa44fbcfedf7c193bc2c599",  # WBTC (Ethereum/Pulse)
                    "0xcbb7c0000ab88b473b1f5afd9ef808440eed33bf",  # cbBTC (Base)
                    "0x2f2a2543b76a4166549f7aab2e75bef0aefc5b0f",  # WBTC (Arbitrum)
                    "0x0555e30da8f98308edb960aa94c0db47230d2b9c",  # WBTC OFT
                    "0x152b9d0fdc40c096757f570a51e494bd4b943e50",  # BTC.b (Avalanche)
                    "0x03c7054bcb39f7b2e5b2c7acb37583e32d70cfa3",  # WBTC (BOB/Worldchain)
                    "0xd221812de1bd094f35587ee8e174b07b6167d9af",  # WBTC (Celo)
                    "0x062e66477faf219f25d27dced647bf57c3107d52",  # WBTC (Cronos)
                    "0x321162cd933e2be498cd2267a90534a804051b11",  # WBTC (Fantom)
                    "0x8e5bbbb09ed1ebde8674cda39a0c169401db4252",  # WBTC (Gnosis)
                    "0x3aab2285ddcddad8edf438c1bab47e1a9d05a9b4",  # WBTC (Linea)
                    "0xa5b55ab1daf0f8e1efc0eb1931a957fd89b918f4",  # WBTC (Metis)
                    "0x3c1bca5a656e69edcd0d4e36bebb3fcdaca60cf1",  # WBTC (Scroll)
                    "0x927b51f251480a681271180da4de28d44ec4afb8",  # cbBTC (Unichain)
                    "0xbbeb516fb02a01611cbbe0453fe3c580d7281011",  # WBTC (zkSync)
                )
            }
            eth_bluechips: Set[str] = {
                _norm_addr(x)
                for x in (
                    "0x7f39c581f595b53c5cb19bd0b3f8da6c935e2ca0",  # wstETH (Ethereum)
                    "0x49d5c2bdffac6ce2bfdb6640f4f80f226bc10bab",  # WETH.e (Avalanche)
                    "0x2f6f07cdcf3588944bf4c42ac74ff24bf56e7590",  # WETH OFT (Berachain/Rootstock)
                    "0x66803fb87abd4aac3cbb3fad7c3aa01f6f3fb207",  # WETH (Celo)
                    "0xe44fd7fcb2b1581822d0c862b68222998a0c299a",  # WETH (Cronos)
                    "0x74b23882a30290451a17c44f4f05243b6b58c76d",  # WETH (Fantom)
                    "0x6a023ccd1ff6f2045c3309768ead9e68f978f6e1",  # WETH (Gnosis)
                    "0xb5bedd42000b71fdde22d3ee8a79bd49a568fc8f",  # wstETH (Linea)
                    "0x1bf74c010e6320bab11e2e5a532b5ac15e0b8aa6",  # weETH (Linea)
                    "0x0dc808adce2099a9f62aa87d9670745aba741746",  # WETH (Manta)
                    "0x2fe3ad97a60eb7c79a976fc18bb5ffd07dd94ba5",  # STONE (Manta)
                    "0xdeaddeaddeaddeaddeaddeaddeaddeaddead1111",  # WETH (Mantle)
                    "0x420000000000000000000000000000000000000a",  # WETH (Metis)
                    "0x7ceb23fd6bc0add59e62ac25578270cff1b9f619",  # WETH (Polygon)
                    "0x02dcdd04e3f455d838cd1249292c58f3b79e3c3c",  # WETH (PulseChain)
                    "0xc99a6a985ed2cac1ef41640596c5a5f9f4e19ef5",  # WETH (Ronin)
                    "0xf610a9dfb7c89644979b4a0f27063e9e7d7cda32",  # wstETH (Scroll)
                    "0x01f0a31698c4d065659b9bdc21b3610292a1c506",  # weETH (Scroll)
                    "0x50c42deacd8fc9773493ed674b675be577f2634b",  # WETH (Sonic)
                    "0xc02fe7317d4eb8753a02c35fe019786854a92001",  # wstETH (Unichain)
                    "0x5a77f1443d16ee5761d310e38b62f77f726bc71c",  # WETH (XLayer)
                    "0x703b52f2b28febcb60e1372858af5b18849fe867",  # wstETH (zkSync)
                )
            }
            native_usd_unit_d = (
                Decimal("85000")
                if (c_nm in _BTC_NATIVE_CHAINS or c_nm in ("rsk", "bsquared", "bevm", "ailayer", "btr"))
                else (
                    Decimal("2500")
                    if c_nm in NATIVE_ETH_CHAINS
                    else _BALLPARK_NATIVE_USD_BY_CHAIN.get(c_nm, Decimal("1"))
                )
            )
            non_wn_toks = stables + bluechips
            toks = ([wn] if wn else []) + non_wn_toks
            dec_map: Dict[str, int] = {wn: 18} if wn else {}
            native_chunks = [addrs[i : i + 48] for i in range(0, len(addrs), 48)]
            mc_calls: List[Tuple[str, bytes]] = []
            if toks:
                mc_calls = [(tk_d, dec_sel) for tk_d in non_wn_toks]
                for a in addrs:
                    pad_a = abi_encode(["address"], [_checksum(a)])
                    for tok in toks:
                        mc_calls.append((tok, bal_sel + pad_a))

            def _run_native_part(_: int) -> List[Tuple[List[str], List[Any]]]:
                def _nat_chunk(ch_a: List[str]) -> Tuple[List[str], List[Any]]:
                    return ch_a, router.batch_call(
                        c_nm,
                        [("eth_getBalance", [_checksum(a), "latest"]) for a in ch_a],
                        block_pin=0,
                        timeout=6.0,
                    )

                return _map_chunks_live(router, _nat_chunk, native_chunks, max_workers=4)

            def _run_mc_part(_: int) -> List[Tuple[bool, bytes]]:
                return router.multicall3(c_nm, mc_calls, block_pin=0, chunk_size=120) if mc_calls else []

            if mc_calls and not is_mock:
                part_results = _parallel_map_list(
                    lambda fn_p: fn_p(0), [_run_native_part, _run_mc_part], max_workers=2, parallel=True
                )
                native_parts, mc_res = part_results[0], part_results[1]
            else:
                native_parts = _run_native_part(0)
                mc_res = _run_mc_part(0)

            for ch_a, res_c in native_parts:
                for a, raw_bal in zip(ch_a, res_c or ()):
                    if isinstance(raw_bal, str) and raw_bal.startswith("0x"):
                        wei = _hex_to_int(raw_bal)
                        if wei > 0:
                            nat_est_d = (Decimal(wei) / (Decimal(10) ** 18)) * native_usd_unit_d
                            loc_dec[(c_nm, a)] = loc_dec.get((c_nm, a), _DEC_ZERO) + nat_est_d
            if toks and len(mc_res) == len(mc_calls):
                idx = 0
                for tk_d in non_wn_toks:
                    ok_d, raw_d = mc_res[idx]
                    idx += 1
                    if ok_d and len(raw_d) >= 32:
                        dv = int.from_bytes(raw_d[:32], "big")
                        dec_map[tk_d] = dv if 0 <= dv <= 24 else (8 if tk_d in btc_bluechips else (18 if c_nm == "bsc" or tk_d in bluechips else 6))
                    else:
                        dec_map[tk_d] = 8 if tk_d in btc_bluechips else (18 if c_nm == "bsc" or tk_d in bluechips else 6)
                for a in addrs:
                    for tok in toks:
                        ok_b, raw_b = mc_res[idx]
                        idx += 1
                        if not ok_b or len(raw_b) < 32:
                            continue
                        amt_raw = int.from_bytes(raw_b[:32], "big")
                        if amt_raw <= 0:
                            continue
                        dec_t = dec_map.get(tok, 18)
                        human_amt_d = Decimal(amt_raw) / (Decimal(10) ** dec_t)
                        unit_px_d = (
                            native_usd_unit_d
                            if tok == wn
                            else (
                                Decimal("85000")
                                if tok in btc_bluechips
                                else (Decimal("2500") if tok in eth_bluechips else Decimal("1"))
                            )
                        )
                        usd_est_d = human_amt_d * unit_px_d
                        if usd_est_d > _DEC_ZERO:
                            loc_dec[(c_nm, a)] = loc_dec.get((c_nm, a), _DEC_ZERO) + usd_est_d
        except _RECOVERABLE_IO_EXC:
            pass
        return loc_dec

    return _parallel_map_merge_dicts(
        _probe_chain_entry, list(by_chain.items()), max_workers=12, parallel=(not is_mock)
    )


_PAUSED_VIEW_SEL_BYTES: bytes = bytes.fromhex("5c975abb")


def _probe_paused_flags_batch(
    router: Optional[RPCRouter],
    chain_addrs: Sequence[Tuple[str, str]],
) -> Set[Tuple[str, str]]:
    """
    Mode B 후보 컨트랙트/프록시의 `paused()` (`0x5c975abb`) 상태를 체인당 1회 `Multicall3`로 일괄 확인하여
    라이브 동결(`paused == true`) 상태인 대상을 큐 적재 단계에서 사전 강등한다.
    """
    if router is None or not chain_addrs:
        return set()
    is_mock = (
        type(router).multicall3 is not RPCRouter.multicall3
        or "multicall3" in router.__dict__
    )
    if getattr(socket.getaddrinfo, "__name__", "") == "_guarded_getaddrinfo" and not is_mock:
        return set()
    by_chain: Dict[str, List[str]] = {}
    for ch, ad in chain_addrs:
        c_nm = _norm_chain(ch)
        na = _norm_addr(ad)
        if c_nm and na and na not in by_chain.setdefault(c_nm, []) and len(by_chain[c_nm]) < 96:
            by_chain[c_nm].append(na)
    def _probe_paused_chain(entry: Tuple[str, List[str]]) -> Set[Tuple[str, str]]:
        c_nm, addrs = entry
        loc_paused: Set[Tuple[str, str]] = set()
        if not addrs:
            return loc_paused
        try:
            calls = [(_checksum(a), _PAUSED_VIEW_SEL_BYTES) for a in addrs]
            res = router.multicall3(c_nm, calls, block_pin=0, chunk_size=120)
            if len(res) != len(addrs):
                return loc_paused
            for a, (ok, raw) in zip(addrs, res):
                if ok and len(raw) >= 32 and int.from_bytes(raw[:32], "big") == 1:
                    loc_paused.add((c_nm, a))
        except _RECOVERABLE_IO_EXC:
            pass
        return loc_paused

    paused_set: Set[Tuple[str, str]] = set()
    for part_p in _parallel_map_list(
        _probe_paused_chain, list(by_chain.items()), max_workers=12, parallel=(not is_mock)
    ):
        paused_set.update(part_p)
    return paused_set


def _probe_clone_balances_and_paused(
    router: Optional[RPCRouter],
    chain_addrs: Sequence[Tuple[str, str]],
) -> Tuple[Dict[Tuple[str, str], Decimal], Set[Tuple[str, str]]]:
    """독립된 유동 잔고 힌트 프로브와 paused() 상태 프로브를 2-워커 스레드풀로 동시 실행한다."""
    if router is None or not chain_addrs:
        return {}, set()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fut_bal = pool.submit(_probe_clone_liquid_balance_hints, router, chain_addrs)
        fut_psd = pool.submit(_probe_paused_flags_batch, router, chain_addrs)
        return fut_bal.result(), fut_psd.result()


def _collect_impl_proxies_for_chains(
    store: SQLiteStore,
    impl_addrs_by_chain: Dict[str, Sequence[str]],
) -> Tuple[Dict[Tuple[str, str], Set[str]], List[Tuple[str, str]]]:
    """
    체인별 구현체 주소 목록에 연결된 모든 프록시를 수집한다:
    - SQLite(`store.find_proxies_by_impl`)
    - 고속 클론 테이블(`_find_fast_clone_proxies_by_impl`)
    - 로컬 Sourcify V2 Parquet(`search_sourcify_v2_proxies_for_impls`)
    """
    proxies_by_impl: Dict[Tuple[str, str], Set[str]] = {}
    proxy_pairs: List[Tuple[str, str]] = []
    proxy_pair_seen: Set[Tuple[str, str]] = set()

    def _record(c_n: str, ni: str, p_addr: str) -> None:
        if not c_n or not ni or not p_addr or p_addr == ni:
            return
        proxies_by_impl.setdefault((c_n, ni), set()).add(p_addr)
        pk = (c_n, p_addr)
        if pk not in proxy_pair_seen:
            proxy_pair_seen.add(pk)
            proxy_pairs.append(pk)

    cleaned_by_chain: Dict[str, Tuple[int, List[str], Set[str], str]] = {}
    for raw_c, raw_impls in impl_addrs_by_chain.items():
        c_p = _norm_chain(str(raw_c))
        uniq_impls = list(dict.fromkeys(_norm_addr(str(a)) for a in raw_impls if _norm_addr(str(a))))
        if not c_p or not uniq_impls:
            continue
        cid_p = CHAIN_IDS.get(c_p, 0)
        impl_set_c = set(uniq_impls)
        sole_impl = uniq_impls[0] if len(uniq_impls) == 1 else ""
        cleaned_by_chain[c_p] = (cid_p, uniq_impls, impl_set_c, sole_impl)

        for prow in store.find_proxies_by_impl(uniq_impls, chain_id=(cid_p or None)):
            p_addr = _norm_addr(str(prow.get("address") or ""))
            p_cid = int(prow.get("chain_id") or cid_p or 0)
            p_chain = _norm_chain(CHAIN_BY_ID.get(p_cid, c_p) if p_cid else c_p)
            if not p_addr or p_chain != c_p:
                continue
            for imp_a in (prow.get("impl_addrs") or []):
                ni = _norm_addr(str(imp_a))
                if ni in impl_set_c:
                    _record(c_p, ni, p_addr)

    def _record_ext_rows(
        rows: Sequence[Mapping[str, Any]],
        fixed_chain: str = "",
        fixed_cid: int = 0,
    ) -> None:
        for erow in rows:
            p_addr = _norm_addr(str(erow.get("proxy_address") or erow.get("address") or ""))
            ni = _norm_addr(str(erow.get("impl_address") or ""))
            p_cid = int(erow.get("chain_id") or fixed_cid or 0)
            p_chain = _norm_chain(
                str(erow.get("chain") or (CHAIN_BY_ID.get(p_cid, fixed_chain) if p_cid else fixed_chain))
            )
            if fixed_chain and p_chain != fixed_chain:
                continue
            entry_c = cleaned_by_chain.get(p_chain)
            if entry_c is not None and p_addr:
                _, _, impl_set_c, sole_impl = entry_c
                if ni in impl_set_c:
                    _record(p_chain, ni, p_addr)
                elif not ni and sole_impl:
                    _record(p_chain, sole_impl, p_addr)

    if len(cleaned_by_chain) == 1:
        c_p, (cid_p, uniq_impls, _impl_set_c, _sole_impl) = next(iter(cleaned_by_chain.items()))
        row_limit = min(128, max(32, len(uniq_impls) * 4))
        ext_rows: List[Dict[str, Any]] = []
        if cid_p > 0:
            try:
                ext_rows.extend(_find_fast_clone_proxies_by_impl(uniq_impls, chain_id=cid_p, limit=row_limit))
            except _RECOVERABLE_IO_EXC:
                pass
        try:
            ext_rows.extend(
                search_sourcify_v2_proxies_for_impls(uniq_impls, chain_id=cid_p, limit=row_limit)
                if cid_p > 0
                else _find_fast_clone_proxies_by_impl(uniq_impls, chain_id=None, limit=row_limit)
            )
        except _RECOVERABLE_IO_EXC:
            pass
        _record_ext_rows(ext_rows, fixed_chain=c_p, fixed_cid=cid_p)
    elif len(cleaned_by_chain) >= 2:
        # Single cross-chain C++ RE2 DFA pass + fast clone sidecar lookup
        all_uniq_impls = list(dict.fromkeys(ia for _, u_list, _, _ in cleaned_by_chain.values() for ia in u_list))
        tot_limit = min(256, max(64, len(all_uniq_impls) * 4))
        ext_rows_all: List[Dict[str, Any]] = []
        try:
            ext_rows_all.extend(_find_fast_clone_proxies_by_impl(all_uniq_impls, chain_id=None, limit=tot_limit))
        except _RECOVERABLE_IO_EXC:
            pass
        try:
            ext_rows_all.extend(search_sourcify_v2_proxies_for_impls(all_uniq_impls, chain_id=None, limit=tot_limit))
        except _RECOVERABLE_IO_EXC:
            pass
        _record_ext_rows(ext_rows_all)

    return proxies_by_impl, proxy_pairs


def _persist_queue_and_meta_batch(
    store: SQLiteStore,
    batch_items: Sequence[Tuple[Any, ...]],
    meta_items: Sequence[Tuple[str, Dict[str, Any]]],
) -> int:
    if meta_items:
        store.put_proto_meta_batch(meta_items)
    if not batch_items:
        return 0
    inserted_cnt = store.upsert_queue_items_batch(batch_items)
    _sync_sealed_receipts_for_batch(store, batch_items)
    return inserted_cnt


def _enqueue_mode_b_sourcify_matches(
    store: SQLiteStore,
    raw_matches: Sequence[Dict[str, Any]],
    router: Optional[RPCRouter] = None,
) -> int:
    """Mode B 297개 원천 사건 대비 Sourcify 매치 클론을 Priority=1 최우선으로 큐에 등록(미패치 오픈싱크 보존 + 자금 보유 클론 우선 정렬)."""
    if not raw_matches:
        return 0
    cand_slugs: List[str] = []
    prepared_all: List[Tuple[str, str, str, Dict[str, Any]]] = []
    for m in raw_matches:
        c_slug = _norm_chain(str(m.get("chain") or ""))
        addr = _norm_addr(str(m.get("address") or ""))
        case_idx = int(m.get("case_idx", 0))
        if not c_slug or not addr:
            continue
        mslug = _norm_slug(f"modeb-match-{c_slug}-{case_idx:03d}-{addr[2:8]}{addr[-6:]}")
        prepared_all.append((mslug, c_slug, addr, m))
    if not prepared_all:
        return 0
    # Widen pre-balance candidate pool per (case_idx, chain) to 64 (prioritizing unpatched open sinks!)
    # BEFORE querying Multicall3 balances, so funded unpatched clones are never evicted by higher-overlap $0/patched forks.
    if len(prepared_all) > 64:
        prepared_all.sort(
            key=lambda t: (
                -(_to_dec(t[3].get("score") or 0) * Decimal(1000) + _to_dec(t[3].get("patch_rank_delta") or 0)),
                -_to_dec(t[3].get("score") or 0),
                t[1],
                t[2],
            )
        )
        per_cc_cnt: Dict[Tuple[int, str], int] = {}
        prepared: List[Tuple[str, str, str, Dict[str, Any]]] = []
        for item_p in prepared_all:
            cc_k = (int(item_p[3].get("case_idx", 0)), item_p[1])
            if per_cc_cnt.get(cc_k, 0) >= 64:
                continue
            per_cc_cnt[cc_k] = per_cc_cnt.get(cc_k, 0) + 1
            prepared.append(item_p)
            cand_slugs.append(item_p[0])
    else:
        prepared = prepared_all
        cand_slugs = [t[0] for t in prepared]
    existing = store.list_existing_slugs(cand_slugs)
    probe_pairs: List[Tuple[str, str]] = [
        (c_slug, addr)
        for mslug, c_slug, addr, _ in prepared
        if mslug not in existing
    ]
    probe_set: Set[Tuple[str, str]] = set(probe_pairs)
    proxies_by_impl: Dict[Tuple[str, str], Set[str]] = {}
    if probe_pairs:
        pending_by_chain: Dict[str, List[str]] = {}
        for c_p, a_p in probe_pairs:
            pending_by_chain.setdefault(c_p, []).append(a_p)
        if len(probe_pairs) <= 16:
            proxies_by_impl, coll_proxy_pairs = _collect_impl_proxies_for_chains(store, pending_by_chain)
            for pk in coll_proxy_pairs:
                if pk not in probe_set:
                    probe_set.add(pk)
                    probe_pairs.append(pk)
        else:
            # Large cursor batch (>16 candidates): use fast deterministic clone-hash + SQLite proxy index (~0.8s)
            def _register_proxy_probe_pair(p_ch_i: str, ni_i: str, p_ad_i: str) -> None:
                proxies_by_impl.setdefault((p_ch_i, ni_i), set()).add(p_ad_i)
                if (p_ch_i, p_ad_i) not in probe_set:
                    probe_set.add((p_ch_i, p_ad_i))
                    probe_pairs.append((p_ch_i, p_ad_i))

            all_p_impls = list(dict.fromkeys(a_p for _, a_p in probe_pairs))
            for prow in store.find_proxies_by_impl(all_p_impls, chain_id=None):
                p_ad = _norm_addr(str(prow.get("address") or ""))
                p_ch = _norm_chain(CHAIN_BY_ID.get(int(prow.get("chain_id") or 0), ""))
                if p_ad and p_ch in pending_by_chain:
                    for imp_a in (prow.get("impl_addrs") or ()):
                        ni = _norm_addr(str(imp_a))
                        if ni and ni != p_ad:
                            _register_proxy_probe_pair(p_ch, ni, p_ad)
            try:
                for erow in _find_fast_clone_proxies_by_impl(all_p_impls[:192], chain_id=None, limit=128):
                    p_ad = _norm_addr(str(erow.get("proxy_address") or erow.get("address") or ""))
                    ni = _norm_addr(str(erow.get("impl_address") or ""))
                    p_ch = _norm_chain(str(erow.get("chain") or CHAIN_BY_ID.get(int(erow.get("chain_id") or 0), "")))
                    if p_ad and ni and p_ad != ni and p_ch in pending_by_chain:
                        _register_proxy_probe_pair(p_ch, ni, p_ad)
            except _RECOVERABLE_IO_EXC:
                pass
    bal_hints, paused_pairs = _probe_clone_balances_and_paused(router, probe_pairs)
    chains_with_pos_hints: Set[str] = {ch_h for (ch_h, _), v_h in bal_hints.items() if _to_dec(v_h) > _DEC_ZERO}
    ranked_rows: List[Tuple[Decimal, Tuple[int, str], Tuple[Any, ...], Tuple[str, Dict[str, Any]]]] = []
    seen_slugs: Set[str] = set(existing)
    min_tvl_d = _to_dec(MIN_TVL_USD)
    for mslug, c_slug, addr, m in prepared:
        if mslug in seen_slugs:
            continue
        seen_slugs.add(mslug)
        score_d = _to_dec(m.get("score") or 0)
        patch_delta_d = Decimal(int(m.get("patch_rank_delta") or 0))
        assoc_proxies = sorted(proxies_by_impl.get((c_slug, addr), ()))
        is_paused_flag = (c_slug, addr) in paused_pairs or any((c_slug, pa) in paused_pairs for pa in assoc_proxies)
        hint_usd_d = _to_dec(bal_hints.get((c_slug, addr), _DEC_ZERO)) + sum(
            (_to_dec(bal_hints.get((c_slug, pa), _DEC_ZERO)) for pa in assoc_proxies),
            _DEC_ZERO,
        )
        if hint_usd_d >= PROFIT_FLOOR_DEC and not is_paused_flag and m.get("vuln_preserved") is not False:
            q_prio = 0
            base_rank_d = Decimal("4500000")
        elif hint_usd_d >= PROFIT_FLOOR_DEC:
            q_prio = 2
            base_rank_d = Decimal("2200000") if not is_paused_flag else Decimal("1600000")
        elif hint_usd_d > _DEC_ZERO:
            q_prio = 2
            base_rank_d = Decimal("1000000")
        elif c_slug in chains_with_pos_hints:
            q_prio = 2
            base_rank_d = Decimal("600000")
        else:
            q_prio = 2
            base_rank_d = Decimal("1000000")
        if is_paused_flag:
            base_rank_d = max(Decimal("100000"), base_rank_d - Decimal("600000"))
        s_rank_d = base_rank_d + (score_d * Decimal("1000")) + patch_delta_d + _clone_fund_rank_boost(hint_usd_d)
        q_item = (mslug, q_prio, c_slug, min_tvl_d, [addr], "B", str(m.get("principle") or ""), s_rank_d)
        m_meta: Dict[str, Any] = {
            "mode_b_source_slug": str(m.get("seed_slug") or ""),
            "mode_b_source_addrs": list(m.get("seed_addrs") or []),
            "mode_b_source_chain": str(m.get("seed_chain") or c_slug),
            "mode_b_similarity": format(score_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN), "f"),
            "mode_b_seed_hashes": list(m.get("seed_hashes") or []),
            "mode_b_match_type": str(m.get("match_type") or "sourcify_cursor"),
            "matched_from": "sourcify_cursor",
        }
        if is_paused_flag:
            m_meta["mode_b_paused"] = True
        if "vuln_preserved" in m:
            m_meta["mode_b_vuln_preserved"] = bool(m["vuln_preserved"])
        if m.get("patch_kind"):
            m_meta["mode_b_patch_kind"] = str(m["patch_kind"])
        if assoc_proxies:
            m_meta["mode_b_proxy_addrs"] = assoc_proxies[:32]
        if hint_usd_d > _DEC_ZERO:
            m_meta["mode_b_hint_usd"] = hint_usd_d.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
        ranked_rows.append((s_rank_d, (int(m.get("case_idx", 0)), c_slug), q_item, (mslug, m_meta)))
    if not ranked_rows:
        return 0
    ranked_rows.sort(key=lambda x: (-x[0], x[2][2], x[2][0]))
    final_cc_cnt: Dict[Tuple[int, str], int] = {}
    batch_items: List[Tuple[Any, ...]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []
    for _, cc_k, q_item, m_pair in ranked_rows:
        if final_cc_cnt.get(cc_k, 0) >= 24:
            continue
        final_cc_cnt[cc_k] = final_cc_cnt.get(cc_k, 0) + 1
        batch_items.append(q_item)
        meta_items.append(m_pair)
    if not batch_items:
        return 0
    return _persist_queue_and_meta_batch(store, batch_items, meta_items)


def _has_sourcify_corpus_files(p_root: Path) -> bool:
    if not p_root.is_dir():
        return False
    try:
        if (
            (p_root / ".download_in_progress").exists()
            or next(p_root.glob("*/*.part"), None) is not None
            or next(p_root.glob("*.part"), None) is not None
        ):
            return False
        return (
            next(p_root.glob("*/*.parquet"), None) is not None
            or next(p_root.glob("*.parquet"), None) is not None
            or next(p_root.glob("*.jsonl"), None) is not None
            or next(p_root.glob("*/*.jsonl"), None) is not None
        )
    except OSError:
        return False


def _merge_idx_ranges(ranges: Sequence[Sequence[int]]) -> List[List[int]]:
    valid = sorted(
        ([int(r[0]), int(r[1])] for r in ranges if isinstance(r, (list, tuple)) and len(r) == 2 and int(r[1]) > int(r[0]) >= 0),
        key=lambda x: (x[0], x[1]),
    )
    if not valid:
        return []
    merged: List[List[int]] = [valid[0]]
    for lo, hi in valid[1:]:
        if lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])
    return merged


def _claim_next_slice_range(
    done_ranges: List[List[int]],
    inflight_map: Dict[str, float],
    total_cnt: int,
    step: int,
    now_ts: float,
    lease_sec: float = 60.0,
) -> Optional[Tuple[int, int]]:
    if total_cnt <= 0:
        return None

    def _safe_exp_ts(val: Any) -> float:
        try:
            fv = float(val or 0.0)
            return fv if math.isfinite(fv) else 0.0
        except (TypeError, ValueError):
            return 0.0

    expired_keys = [k for k, exp_v in list(inflight_map.items()) if _safe_exp_ts(exp_v) <= now_ts]
    for ek in expired_keys:
        inflight_map.pop(ek, None)
    inf_ranges: List[List[int]] = []
    for k in inflight_map:
        parts = str(k).split(":", 1)
        if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
            inf_ranges.append([int(parts[0]), int(parts[1])])
    blocked = _merge_idx_ranges([*done_ranges, *inf_ranges])
    if not blocked:
        pos, next_lo = 0, total_cnt
    elif blocked[0][0] > 0:
        pos, next_lo = 0, blocked[0][0]
    else:
        pos = blocked[0][1]
        next_lo = blocked[1][0] if len(blocked) > 1 else total_cnt
    if pos >= total_cnt:
        return None
    end_pos = min(total_cnt, next_lo, pos + max(1, int(step)))
    if end_pos <= pos:
        return None
    inflight_map[f"{pos}:{end_pos}"] = now_ts + float(lease_sec)
    return pos, end_pos


def _started_sourcify_cursor_phase_or_empty(raw_cursor: str) -> str:
    if not raw_cursor:
        return ""
    try:
        doc_c = json.loads(raw_cursor)
        if not isinstance(doc_c, dict):
            return ""
        ph = str(doc_c.get("phase") or "")
        if ph in ("exact_hash", "sig_slices", "code_slices"):
            return ph
        if ph == "seed_harvest" and int(doc_c.get("seed_cursor") or 0) > 0:
            return ph
    except _PARSE_DATA_EXC:
        pass
    return ""


def _get_mode_b_sourcify_cursor_phase(
    store: SQLiteStore,
    parquet_root: Optional[Path] = None,
) -> str:
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    raw_c = store.get_engine_meta("mode_b_sourcify_cursor_v1")
    if not _has_sourcify_corpus_files(p_root):
        started_ph = _started_sourcify_cursor_phase_or_empty(raw_c)
        return started_ph if (started_ph and store.list_mode_b_primary_items()) else "exhausted"
    if not store.list_mode_b_primary_items():
        return "exhausted"
    if raw_c:
        try:
            doc_c = json.loads(raw_c)
            if isinstance(doc_c, dict) and doc_c.get("phase"):
                return str(doc_c["phase"])
        except _PARSE_DATA_EXC:
            pass
    return "seed_harvest"


_MODEB_PRECOMP_LOCK = threading.Lock()
_MODEB_PRECOMP_CACHE: Dict[
    str,
    Tuple[List[Dict[str, Any]], Dict[int, Set[bytes]], Dict[int, Set[bytes]], List[Tuple[int, int]]],
] = {}


def _build_seed_len_intervals(pv_seq: Sequence[Mapping[str, Any]]) -> List[Tuple[int, int]]:
    return _merge_len_intervals(
        [
            (
                max(56 if pv.get("fn_loci") else 64, int(pv["len_clean"] * MIN_SIZE_RATIO)),
                max(((int(pv["len_clean"]) * 100) // 8) + 256, 24576 if pv.get("fn_loci") else 0),
            )
            for pv in pv_seq
        ]
    )


def _get_precomputed_mode_b_seeds(
    seed_variants: Sequence[Mapping[str, Any]],
) -> Tuple[List[Dict[str, Any]], Set[bytes], Set[bytes], List[Tuple[int, int]]]:
    h = hashlib.sha256()
    for v in seed_variants:
        h.update(
            f"{v.get('case_idx', 0)}|{v.get('slug', '')}|{v.get('chain', '')}|{v.get('addr', '')}|"
            f"{','.join(str(x) for x in (v.get('addrs') or ()))}|"
            f"{','.join(str(x) for x in (v.get('disp_sels') or ()))}|"
            f"{','.join(str(x) for x in (v.get('key_identifiers') or ()))}|"
            f"{','.join(str(x) for x in (v.get('hashes') or ()))}|"
            f"{v.get('principle', '')}|{v.get('clean_hex', '')}\n".encode("utf-8")
        )
    ck = h.hexdigest()
    with _MODEB_PRECOMP_LOCK:
        hit = _MODEB_PRECOMP_CACHE.get(ck)
        if hit is not None:
            return hit
    precomp_variants: List[Dict[str, Any]] = []
    for v in seed_variants:
        c_bytes = _hex_to_bytes(v.get("clean_hex") or "")
        if len(c_bytes) < 64:
            continue
        k_ids = tuple(str(x) for x in (v.get("key_identifiers") or ()) if x)
        precomp_variants.append(
            {
                **dict(v),
                **_precompute_bytecode_grams(c_bytes, key_identifiers=k_ids),
                "disp_set": set(v.get("disp_sels") or ()),
            }
        )
    pv_union_clean, pv_union_masked = _build_seed_gram_unions(precomp_variants)
    len_intervals = _build_seed_len_intervals(precomp_variants)
    bundle = (precomp_variants, pv_union_clean, pv_union_masked, len_intervals)
    with _MODEB_PRECOMP_LOCK:
        if len(_MODEB_PRECOMP_CACHE) >= 4:
            _MODEB_PRECOMP_CACHE.pop(next(iter(_MODEB_PRECOMP_CACHE)))
        _MODEB_PRECOMP_CACHE[ck] = bundle
    return bundle


def _advance_mode_b_sourcify_cursor(
    router: Optional[RPCRouter],
    store: SQLiteStore,
    parquet_root: Optional[Path] = None,
    max_wall_sec: float = 4.5,
    batch_code_files: int = 12,
) -> Dict[str, Any]:
    """
    컨트랙트.md(Mode B 297개 사건) × 로컬 Sourcify v2(138.5 GiB Parquet + 사이드카) 다중 세션 병렬 샤딩 파티션 커서:
    - engine_meta('mode_b_sourcify_cursor_v1') 상태를 따라 seed_harvest -> exact_hash -> sig_slices -> code_slices -> exhausted 순으로 재개 가능 전진.
    - sig_slices(2단계 지연 실체화: `compiled_contracts` 고유 템플릿 선검증) 및
      code_slices(DuckDB C++ RE2 멀티앵커·CWIA 사전필터 + 합격 해시 지연 반조인)로 6,000만 행 전체 조인 타임아웃을 0건으로 제거한다.
    """
    t0 = time.monotonic()
    max_wall_sec = max(4.5, float(max_wall_sec))  # 호출자 예산 존중: 커서는 호출 단위로 제한 전진하고 다음 호출에 재개
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR

    @contextlib.contextmanager
    def _cursor_meta_lock() -> Iterator[None]:
        if not store._is_memory:
            lpath = _store_cache_dir(store) / "_modeb_cursor_meta.lock"
            lpath.parent.mkdir(parents=True, exist_ok=True)
            with _exclusive_file_lock(lpath):
                yield
        else:
            with store._lock:
                yield

    @contextlib.contextmanager
    def _serial_phase_try_lock() -> Iterator[bool]:
        if not store._is_memory:
            spath = _store_cache_dir(store) / "_modeb_serial"
            spath.parent.mkdir(parents=True, exist_ok=True)
            with _try_slug_lock(spath) as acq_s:
                yield acq_s
        else:
            yield True

    def _load_cursor_dict() -> Dict[str, Any]:
        cur_d = _load_json_dict_meta(store, "mode_b_sourcify_cursor_v1")
        cur_d.setdefault("phase", "seed_harvest")
        cur_d.setdefault("seed_cursor", 0)
        cur_d.setdefault("hash_offset", 0)
        cur_d.setdefault("sig_file_idx", 0)
        cur_d.setdefault("sig_step", 32)
        cur_d.setdefault("code_file_idx", 0)
        cur_d.setdefault("code_step", max(1, int(batch_code_files)))
        cur_d.setdefault("sidecar_done", False)
        cur_d.setdefault("matched_count", 0)
        cur_d.setdefault("enqueued_count", 0)
        s_done = _merge_idx_ranges(cur_d.get("sig_done_ranges") or ([] if int(cur_d["sig_file_idx"]) <= 0 else [[0, int(cur_d["sig_file_idx"])]]))
        c_done = _merge_idx_ranges(cur_d.get("code_done_ranges") or ([] if int(cur_d["code_file_idx"]) <= 0 else [[0, int(cur_d["code_file_idx"])]]))
        cur_d["sig_done_ranges"] = s_done
        cur_d["code_done_ranges"] = c_done
        cur_d["sig_inflight"] = dict(cur_d.get("sig_inflight") or {}) if isinstance(cur_d.get("sig_inflight"), dict) else {}
        cur_d["code_inflight"] = dict(cur_d.get("code_inflight") or {}) if isinstance(cur_d.get("code_inflight"), dict) else {}
        return cur_d

    def _save_cursor_dict(cur_d: Dict[str, Any]) -> None:
        try:
            store.put_engine_meta("mode_b_sourcify_cursor_v1", json.dumps(cur_d, ensure_ascii=False))
        except _RECOVERABLE_IO_EXC:
            pass

    with _cursor_meta_lock():
        cursor = _load_cursor_dict()
        cursor.setdefault("harvested_addr_keys", [])

    def _save_cursor() -> None:
        _save_cursor_dict(cursor)

    if not _has_sourcify_corpus_files(p_root):
        if cursor["phase"] == "exhausted":
            return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}
        started_cur_ph = (
            str(cursor["phase"])
            if (
                cursor["phase"] in ("exact_hash", "sig_slices", "code_slices")
                or (cursor["phase"] == "seed_harvest" and int(cursor.get("seed_cursor") or 0) > 0)
            )
            and bool(store.list_mode_b_primary_items())
            else "exhausted"
        )
        return {"phase": started_cur_ph, "enqueued": 0, "matched": 0, "timed_out": False}

    def _load_seed_variants() -> List[Dict[str, Any]]:
        def _parse_variants_json(raw_txt: str) -> Optional[List[Dict[str, Any]]]:
            try:
                d_obj = json.loads(raw_txt)
                if isinstance(d_obj, dict) and isinstance(d_obj.get("variants"), list):
                    return list(d_obj["variants"])
            except _PARSE_DATA_EXC:
                pass
            return None

        if not store._is_memory:
            cand_paths = [_store_cache_dir(store) / "mode_b_seed_index_v1.json"]
            if _store_cache_dir(store).resolve() == CACHE_DIR.resolve():
                cand_paths.append(ARTIFACT_ROOT / "_relay_seed_index.json")
            for cpath in cand_paths:
                if cpath.is_file():
                    try:
                        parsed_v = _parse_variants_json(cpath.read_text(encoding="utf-8"))
                        if parsed_v is not None:
                            return parsed_v
                    except _RECOVERABLE_IO_EXC:
                        pass
        raw_m = store.get_engine_meta("mode_b_seed_index_v1")
        if raw_m:
            parsed_m = _parse_variants_json(raw_m)
            if parsed_m is not None:
                return parsed_m
        return []

    def _save_seed_variants(variants_list: List[Dict[str, Any]]) -> None:
        for sv_item in variants_list:
            if not isinstance(sv_item, dict):
                continue
            for sv_k in ("principle", "principle_summary"):
                if isinstance(sv_item.get(sv_k), str) and sv_item[sv_k]:
                    sv_item[sv_k] = _neutralize_agent_prose(sv_item[sv_k])
        payload = {"variants": variants_list}
        if not store._is_memory:
            cdir_s = _store_cache_dir(store)
            _write_json_atomic(cdir_s / "mode_b_seed_index_v1.json", payload, compact=True)
            if cdir_s.resolve() == CACHE_DIR.resolve():
                _write_json_atomic(ARTIFACT_ROOT / "_relay_seed_index.json", payload, compact=True)
        else:
            store.put_engine_meta("mode_b_seed_index_v1", json.dumps(payload, ensure_ascii=True))

    modeb_items = store.list_mode_b_primary_items()
    if not modeb_items:
        return {"phase": cursor["phase"], "enqueued": 0, "matched": 0, "timed_out": False}

    seed_variants = _load_seed_variants()
    harvested_pre_set: Set[str] = {str(x).lower() for x in (cursor.get("harvested_addr_keys") or ())}
    for sv_p in seed_variants:
        sc_p = _norm_chain(sv_p.get("chain") or "")
        for raw_va in [sv_p.get("addr"), *(sv_p.get("addrs") or ())]:
            nva = _norm_addr(str(raw_va or ""))
            if sc_p and nva:
                harvested_pre_set.add(f"{sc_p}:{nva}")
    first_unharvested_idx: Optional[int] = None
    for idx_mb, it_mb in enumerate(modeb_items):
        cm_mb = _norm_chain(it_mb.get("chain") or "")
        if not cm_mb:
            continue
        for ra_mb in (it_mb.get("addresses") or ()):
            na_mb = _norm_addr(str(ra_mb or ""))
            if na_mb and f"{cm_mb}:{na_mb}" not in harvested_pre_set:
                first_unharvested_idx = idx_mb
                break
        if first_unharvested_idx is not None:
            break

    def _seed_var_uid(v_obj: Mapping[str, Any]) -> str:
        return f"{v_obj.get('slug', '')}:{hashlib.sha256(str(v_obj.get('clean_hex') or '').encode('ascii')).hexdigest()[:32]}"

    if first_unharvested_idx is not None:
        with _cursor_meta_lock():
            cursor = _load_cursor_dict()
            cursor.setdefault("harvested_addr_keys", [])
            if cursor["phase"] != "seed_harvest":
                cursor["prev_phase_before_delta"] = str(cursor["phase"])
                cursor["phase"] = "seed_harvest"
                cursor["seed_cursor"] = first_unharvested_idx
            else:
                cursor["seed_cursor"] = min(int(cursor.get("seed_cursor") or 0), first_unharvested_idx)
            _save_cursor()
    elif cursor["phase"] == "exhausted" and not cursor.get("pending_delta_var_keys"):
        return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}
    elif not seed_variants and cursor["phase"] in ("exact_hash", "sig_slices", "code_slices"):
        with _cursor_meta_lock():
            cursor["phase"] = "seed_harvest"
            cursor["seed_cursor"] = 0
            _save_cursor()
    seed_addr_keys: Set[Tuple[int, str]] = {
        (CHAIN_IDS.get(_norm_chain(it["chain"]), 0), na)
        for it in modeb_items
        for a in (it.get("addresses") or ())
        if (na := _norm_addr(a))
    }

    enqueued_now = 0
    matched_now = 0
    timed_out_flag = False

    def _collect_variant_from_bytes(
        case_idx: int,
        it: Dict[str, Any],
        addr: str,
        raw_b: bytes,
        *,
        key_ids: Sequence[str] = (),
        extra_impls: Sequence[str] = (),
    ) -> Optional[Dict[str, Any]]:
        clean_b = _strip_cbor_bytes(raw_b)
        if len(clean_b) < 64:
            return None
        sels: Set[str] = set()
        dis_sb = _disassemble(clean_b)
        for idx_d, (_, nm, imm) in enumerate(dis_sb):
            if nm == "PUSH4" and len(imm) == 4 and imm not in (b"\x00\x00\x00\x00", b"\xff\xff\xff\xff", b"\x4e\x48\x7b\x71", b"\x08\xc3\x79\xa0"):
                sh_l = imm.hex().lower()
                if sh_l not in _COMMON_BOILERPLATE_SELECTORS and any(
                    dis_sb[j][1] in ("EQ", "SUB", "XOR", "GT", "LT")
                    for j in range(idx_d + 1, min(len(dis_sb), idx_d + 4))
                ):
                    sels.add(sh_l)
        if not sels:
            for _, nm, imm in dis_sb:
                if nm == "PUSH4" and len(imm) == 4 and imm not in (b"\x00\x00\x00\x00", b"\xff\xff\xff\xff", b"\x4e\x48\x7b\x71", b"\x08\xc3\x79\xa0"):
                    sh_l = imm.hex().lower()
                    if sh_l not in _COMMON_BOILERPLATE_SELECTORS:
                        sels.add(sh_l)
        hashes = sorted(
            {
                hashlib.sha256(raw_b).hexdigest().lower(),
                _keccak256(raw_b).hex().lower(),
                hashlib.sha256(clean_b).hexdigest().lower(),
                _keccak256(clean_b).hex().lower(),
            }
        )
        impl_list = list(dict.fromkeys(na for x in [addr, *(it.get("addresses") or ()), *extra_impls] if (na := _norm_addr(str(x or "")))))
        return {
            "case_idx": case_idx,
            "slug": str(it["slug"]),
            "chain": _norm_chain(it["chain"]),
            "addr": addr,
            "addrs": list(it.get("addresses") or ()),
            "impl_addrs": impl_list[:16],
            "key_identifiers": [str(k) for k in key_ids[:16] if str(k).strip()],
            "principle": str(it.get("principle_summary") or "")[:400],
            "clean_hex": clean_b.hex(),
            "len_clean": len(clean_b),
            "hashes": hashes,
            "disp_sels": sorted(sels)[:16],
        }

    # Phase 1: Mode B 원천 시드 바이트코드 증분 수집 (로컬 Sourcify 우선 + 범용 프록시 껍데기 배제 + 과거 구현체/파괴전 복원)
    if cursor["phase"] == "seed_harvest":
        with _serial_phase_try_lock() as acq_s:
            if acq_s:
                sc_idx = int(cursor["seed_cursor"])
                len_before_sv = len(seed_variants)
                newly_attempted_keys: List[str] = []
                seen_var_keys: Set[Tuple[str, str]] = {
                    (
                        str(v["slug"]),
                        hashlib.sha256(str(v.get("clean_hex") or "").encode("ascii")).hexdigest()[:32],
                    )
                    for v in seed_variants
                }

                def _add_seed_var(
                    c_i: int,
                    it_v: Dict[str, Any],
                    ad_v: str,
                    code_b_v: bytes,
                    *,
                    key_ids: Sequence[str] = (),
                    extra_impls: Sequence[str] = (),
                ) -> bool:
                    var = _collect_variant_from_bytes(c_i, it_v, ad_v, code_b_v, key_ids=key_ids, extra_impls=extra_impls)
                    if not var:
                        return False
                    vk = (
                        str(var["slug"]),
                        hashlib.sha256(str(var["clean_hex"]).encode("ascii")).hexdigest()[:32],
                    )
                    if vk in seen_var_keys:
                        return False
                    seen_var_keys.add(vk)
                    seed_variants.append(var)
                    return True

                seed_rpc_retries: Dict[str, int] = (
                    dict(cursor.get("seed_rpc_retries") or {})
                    if isinstance(cursor.get("seed_rpc_retries"), dict)
                    else {}
                )
                _sf_fc_sh, _ = _unpack_sourcify_v2_meta(p_root)
                _bulk_code_parquet = (
                    int(_sf_fc_sh.get("code", 0)) > 32
                    and router is not None
                    and _query_local_sourcify_deployment_hints is _ORIG_QUERY_LOCAL_SOURCIFY_HINTS_FN
                )
                while sc_idx < len(modeb_items) and (time.monotonic() - t0) < max_wall_sec:
                    chunk = modeb_items[sc_idx : sc_idx + 4]
                    by_chain: Dict[str, List[str]] = {}
                    for it in chunk:
                        cm_it = _norm_chain(it["chain"])
                        cid_c = CHAIN_IDS.get(cm_it, 0)
                        if cid_c > 0:
                            for a in (it.get("addresses") or ()):
                                na = _norm_addr(a)
                                if na and f"{cm_it}:{na}" not in harvested_pre_set:
                                    by_chain.setdefault(cm_it, []).append(na)
                    local_codes_by_ca: Dict[Tuple[str, str], bytes] = {}
                    if _bulk_code_parquet:
                        # 436개 대용량 code/*.parquet 매 청크 풀스캔 타임아웃 방지: 사이드카 즉시 조회 + 라이브/아카이브 RPC 우선(~0.8s)
                        for c_nm_s, addr_grp_s in by_chain.items():
                            cid_s = CHAIN_IDS.get(c_nm_s, 0)
                            if cid_s <= 0:
                                continue
                            clean_s = set(addr_grp_s)
                            for sc_cid, sc_item in _iter_sourcify_sidecar_items(p_root, cid_s):
                                if int(sc_cid) != int(cid_s):
                                    continue
                                sa_s = _norm_addr(sc_item.get("address"))
                                if sa_s in clean_s and (c_nm_s, sa_s) not in local_codes_by_ca:
                                    chex_s = str(sc_item.get("runtime_code_hex") or sc_item.get("code_hex") or "").replace("0x", "").strip()
                                    if chex_s:
                                        try:
                                            bc_sc = bytes.fromhex(chex_s)
                                            if len(bc_sc) >= 64:
                                                local_codes_by_ca[(c_nm_s, sa_s)] = bc_sc
                                        except ValueError:
                                            pass
                    else:
                        rem_ddb_t = min(6.0, max(2.5, max_wall_sec - (time.monotonic() - t0)))
                        local_codes_by_ca = _query_local_sourcify_original_bytecodes_batch(
                            by_chain, parquet_root=p_root, timeout_sec=rem_ddb_t
                        )
                    for rel_i, it in enumerate(chunk):
                        if rel_i > 0 and (time.monotonic() - t0) >= max_wall_sec:
                            break
                        case_idx = sc_idx
                        c_nm = _norm_chain(it["chain"])
                        sl_it = str(it.get("slug") or "")
                        p_meta_it = store.get_proto_meta(sl_it)
                        it_key_ids = list(p_meta_it.get("key_identifiers") or ()) if isinstance(p_meta_it, dict) else []
                        addrs = [_norm_addr(a) for a in (it.get("addresses") or ()) if _norm_addr(a)]
                        missing_rpc: List[str] = []
                        proxy_local_addrs: Set[str] = set()
                        completed_item_addrs: List[str] = []
                        for ad in addrs:
                            if f"{c_nm}:{ad}" in harvested_pre_set:
                                continue
                            cb = local_codes_by_ca.get((c_nm, ad))
                            if cb:
                                is_pure_shell = _is_pure_proxy_shell_bytecode(cb)
                                if not is_pure_shell:
                                    _add_seed_var(case_idx, it, ad, cb, key_ids=it_key_ids)
                                if router is not None and (is_pure_shell or _is_delegatecall_or_thin_proxy(cb)):
                                    proxy_local_addrs.add(ad)
                                    missing_rpc.append(ad)
                                else:
                                    completed_item_addrs.append(ad)
                            elif router is not None:
                                missing_rpc.append(ad)
                            else:
                                completed_item_addrs.append(ad)
                        item_rpc_incomplete = False
                        if missing_rpc and router is not None:
                            if rel_i > 0 and (time.monotonic() - t0) >= max_wall_sec:
                                item_rpc_incomplete = True
                            else:
                                try:
                                    p_meta = p_meta_it if isinstance(p_meta_it, dict) else {}
                                    blks: List[int] = []
                                    for raw_b in (p_meta.get("block_numbers") or ()):
                                        try:
                                            b_i = int(raw_b)
                                        except (TypeError, ValueError):
                                            b_i = 0
                                        if b_i > 1:
                                            blks.append(b_i)
                                    blk_h = (min(blks) - 1) if blks else 0
                                    eff_hi = blk_h
                                    if eff_hi <= 1:
                                        try:
                                            _, qh = router.get_quorum_head_block(c_nm)
                                            eff_hi = int(qh or 0)
                                        except Exception:
                                            eff_hi = 0
                                    hint_cap = max(eff_hi, max(blks) if blks else 0)
                                    hint_blocks = _extract_mode_b_hint_blocks(router, c_nm, p_meta, hint_cap)
                                    if hint_blocks:
                                        eff_hi = max(eff_hi, max(hint_blocks))
                                        if blk_h <= 0:
                                            blk_h = hint_blocks[0]
                                    target_addrs = list(dict.fromkeys(missing_rpc[:16]))
                                    res_map = _resolve_proxy_and_delegates(
                                        router, c_nm, target_addrs, blk_h, raise_on_rpc_failure=True
                                    )
                                    for ad_idx, ad_m in enumerate(target_addrs):
                                        # Guarantee forward progress on at least 1 address for rel_i==0 so cursor never stalls at sc_idx
                                        if (rel_i > 0 or ad_idx > 0) and (time.monotonic() - t0) >= max_wall_sec:
                                            item_rpc_incomplete = True
                                            break
                                        pr_m = res_map.get(ad_m)
                                        got_for_ad = False
                                        raw_is_proxy = ad_m in proxy_local_addrs
                                        if pr_m is not None:
                                            res_impl_list = list(pr_m.impl_addresses or ())
                                            facet_pairs = list(
                                                (pr_m.impl_codes_hex or ({ad_m: pr_m.effective_code_hex} if pr_m.effective_code_hex else {})).items()
                                            )
                                            for fac_a, chx in facet_pairs:
                                                rb = _hex_to_bytes(chx)
                                                if not rb or len(rb) < 64:
                                                    continue
                                                if _is_pure_proxy_shell_bytecode(rb) and (
                                                    (_norm_addr(fac_a) == ad_m and res_impl_list)
                                                    or bool(_eip1167_impl(rb))
                                                ):
                                                    continue
                                                got_for_ad = True
                                                _add_seed_var(case_idx, it, ad_m, rb, key_ids=it_key_ids, extra_impls=res_impl_list)
                                            raw_b_m = _hex_to_bytes(pr_m.raw_code_hex)
                                            if pr_m.proxy_kind != "none" or (
                                                bool(raw_b_m)
                                                and any(
                                                    nm == "DELEGATECALL"
                                                    for _, nm, _ in _disassemble(_strip_cbor_bytes(raw_b_m))
                                                )
                                            ):
                                                raw_is_proxy = True
                                        need_hist_rec = (
                                            eff_hi > 1
                                            and (time.monotonic() - t0) < max_wall_sec
                                            and ((not got_for_ad) or raw_is_proxy)
                                        )
                                        if need_hist_rec:
                                            def _accept_recovered_seed(rb_cand: bytes) -> bool:
                                                if rb_cand and len(rb_cand) >= 64 and not _is_pure_proxy_shell_bytecode(rb_cand):
                                                    _add_seed_var(case_idx, it, ad_m, rb_cand, key_ids=it_key_ids)
                                                    return True
                                                return False

                                            if raw_is_proxy and (time.monotonic() - t0) < max_wall_sec:
                                                for hist_rb in _recover_historical_proxy_impl_bytecodes(
                                                    router, c_nm, ad_m, eff_hi, hint_blocks=hint_blocks
                                                ):
                                                    if _accept_recovered_seed(hist_rb):
                                                        got_for_ad = True
                                            if not got_for_ad and (time.monotonic() - t0) < max_wall_sec:
                                                hist_bisect = _recover_historical_bytecode_bisect(
                                                    router, c_nm, ad_m, eff_hi, hint_blocks=hint_blocks
                                                )
                                                if _accept_recovered_seed(_hex_to_bytes(hist_bisect)):
                                                    got_for_ad = True
                                        completed_item_addrs.append(ad_m)
                                except Exception:
                                    retry_n = int(seed_rpc_retries.get(sl_it, 0)) + 1
                                    seed_rpc_retries[sl_it] = retry_n
                                    if retry_n < 2:
                                        item_rpc_incomplete = True
                                    else:
                                        completed_item_addrs.extend(missing_rpc)
                        for ad_ok in completed_item_addrs:
                            if c_nm and ad_ok:
                                k_ok = f"{c_nm}:{ad_ok}"
                                if k_ok not in harvested_pre_set:
                                    harvested_pre_set.add(k_ok)
                                    newly_attempted_keys.append(k_ok)
                        if item_rpc_incomplete:
                            break
                        seed_rpc_retries.pop(sl_it, None)
                        for ad_done in addrs:
                            if c_nm and ad_done:
                                k_dn = f"{c_nm}:{ad_done}"
                                if k_dn not in harvested_pre_set:
                                    harvested_pre_set.add(k_dn)
                                    newly_attempted_keys.append(k_dn)
                        sc_idx += 1
                _save_seed_variants(seed_variants)
                new_delta_vks = [_seed_var_uid(v_new) for v_new in seed_variants[len_before_sv:]]
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    cursor["seed_rpc_retries"] = seed_rpc_retries
                    prev_hk = list(cursor.get("harvested_addr_keys") or [])
                    prev_hk_set = {str(x).lower() for x in prev_hk}
                    for nk in newly_attempted_keys:
                        if nk not in prev_hk_set:
                            prev_hk_set.add(nk)
                            prev_hk.append(nk)
                    cursor["harvested_addr_keys"] = prev_hk
                    prev_ph_saved = str(cursor.get("prev_phase_before_delta") or "")
                    had_prior_progress = bool(
                        cursor.get("sig_done_ranges")
                        or cursor.get("code_done_ranges")
                        or cursor.get("sidecar_done")
                        or int(cursor.get("hash_offset") or 0) > 0
                        or prev_ph_saved in ("sig_slices", "code_slices", "exhausted")
                    )
                    if had_prior_progress:
                        # Delta-only seed recovery: NEVER wipe completed sig_done_ranges / code_done_ranges!
                        if new_delta_vks:
                            merged_pend = list(
                                dict.fromkeys([*(str(x) for x in (cursor.get("pending_delta_var_keys") or ()) if x), *new_delta_vks])
                            )
                            cursor["pending_delta_var_keys"] = merged_pend
                            cursor["delta_exact_sig_done"] = False
                            cursor["delta_code_idx"] = 0
                        cursor["seed_cursor"] = sc_idx
                        if sc_idx >= len(modeb_items):
                            cursor.pop("prev_phase_before_delta", None)
                            if cursor.get("pending_delta_var_keys") and prev_ph_saved == "exhausted":
                                cursor["phase"] = "code_slices"
                            elif prev_ph_saved in ("exact_hash", "sig_slices", "code_slices", "exhausted"):
                                cursor["phase"] = prev_ph_saved if seed_variants else "exhausted"
                            elif cursor.get("code_done_ranges"):
                                cursor["phase"] = "code_slices"
                            elif cursor.get("sig_done_ranges"):
                                cursor["phase"] = "sig_slices"
                            else:
                                cursor["phase"] = "exact_hash" if seed_variants else "exhausted"
                    else:
                        cursor["seed_cursor"] = sc_idx
                        if sc_idx >= len(modeb_items):
                            cursor.pop("prev_phase_before_delta", None)
                            cursor["phase"] = "exact_hash" if seed_variants else "exhausted"
                    _save_cursor()
            else:
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
        if cursor["phase"] in ("seed_harvest", "exhausted") or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": 0, "matched": 0, "timed_out": False}
        if not seed_variants:
            seed_variants = _load_seed_variants()

    if not seed_variants:
        with _cursor_meta_lock():
            cursor = _load_cursor_dict()
            cursor["phase"] = "exhausted"
            _save_cursor()
        return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}

    f_counts, c_types, _d_cols, ct_cols, chain_filter, addr_proj = _unpack_sourcify_base_schema(p_root, None)
    has_base_parquet = int(f_counts.get("contract_deployments", 0)) > 0 and int(f_counts.get("contracts", 0)) > 0
    vc_cols = c_types.get("verified_contracts") or {}
    cc_cols = c_types.get("compiled_contracts") or {}
    ccs_sig_cols = c_types.get("compiled_contracts_signatures") or {}
    cd_cols = c_types.get("code") or {}
    rch_type = ct_cols.get("runtime_code_hash", "")
    usable_cid_list = ", ".join(str(cid) for cid in sorted(CHAIN_BY_ID.keys()) if _usable_chain(CHAIN_BY_ID[cid]))
    ddb_q_timeout = min(90.0, max(25.0, max_wall_sec * 1.5))

    def _make_mode_b_match_entry(
        v_rec: Mapping[str, Any],
        c_slug_m: str,
        addr_m: str,
        score_m: Union[Decimal, int, str],
        match_type_m: str,
        *,
        patch_rank_delta: int = 0,
        vuln_preserved: Optional[bool] = None,
        patch_kind: str = "",
    ) -> Dict[str, Any]:
        ent: Dict[str, Any] = {
            "case_idx": v_rec["case_idx"],
            "seed_slug": v_rec["slug"],
            "seed_addrs": v_rec["addrs"],
            "seed_chain": v_rec["chain"],
            "seed_hashes": v_rec["hashes"],
            "principle": v_rec["principle"],
            "chain": c_slug_m,
            "address": addr_m,
            "score": _to_dec(score_m),
            "match_type": match_type_m,
            "patch_rank_delta": int(patch_rank_delta),
        }
        if vuln_preserved is not None:
            ent["vuln_preserved"] = bool(vuln_preserved)
        if patch_kind:
            ent["patch_kind"] = patch_kind
        return ent

    def _extract_non_seed_sourcify_row(row_obj: Mapping[str, Any]) -> Optional[Tuple[int, str, str]]:
        parsed_r = _parse_usable_sourcify_row(row_obj)
        if parsed_r is None or (parsed_r[0], parsed_r[2]) in seed_addr_keys:
            return None
        return parsed_r

    def _index_variant_impl_addrs(v_list: Sequence[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        imp_m: Dict[str, Dict[str, Any]] = {}
        for v_i in v_list:
            for raw_ia in (v_i.get("impl_addrs") or v_i.get("addrs") or ()):
                nia = _norm_addr(str(raw_ia or ""))
                if nia:
                    imp_m.setdefault(nia, v_i)
        return imp_m

    def _decode_hex_code_map(raw_hex_map: Mapping[str, str]) -> Dict[str, bytes]:
        out_b: Dict[str, bytes] = {}
        for ch_v, chex_v in raw_hex_map.items():
            try:
                out_b[ch_v] = bytes.fromhex(chex_v)
            except _PARSE_DATA_EXC:
                pass
        return out_b

    def _append_winning_dep_matches(
        dst: List[Dict[str, Any]],
        dep_rows: Sequence[Mapping[str, Any]],
        key_col: str,
        win_map: Mapping[str, Tuple[Dict[str, Any], Decimal, str, int, bool, str]],
        *,
        lower_key: bool = False,
    ) -> None:
        for dr_x in dep_rows:
            parsed_dx = _extract_non_seed_sourcify_row(dr_x)
            k_raw = str(dr_x.get(key_col) or "")
            w_hit = win_map.get(k_raw.lower() if lower_key else k_raw)
            if parsed_dx is not None and w_hit is not None:
                dst.append(
                    _make_mode_b_match_entry(
                        w_hit[0],
                        parsed_dx[1],
                        parsed_dx[2],
                        w_hit[1],
                        w_hit[2],
                        patch_rank_delta=w_hit[3],
                        vuln_preserved=w_hit[4],
                        patch_kind=w_hit[5],
                    )
                )

    def _pop_cursor_inflight(prefix_k: str, rng_k: Tuple[int, int]) -> Dict[str, Any]:
        nonlocal cursor
        cursor = _load_cursor_dict()
        inf_m = dict(cursor.get(f"{prefix_k}_inflight") or {})
        inf_m.pop(f"{rng_k[0]}:{rng_k[1]}", None)
        cursor[f"{prefix_k}_inflight"] = inf_m
        return inf_m

    def _release_timed_out_slice(prefix_k: str, rng_k: Tuple[int, int]) -> Dict[str, Any]:
        nonlocal cursor
        with _cursor_meta_lock():
            _pop_cursor_inflight(prefix_k, rng_k)
            cursor[f"{prefix_k}_step"] = max(1, (rng_k[1] - rng_k[0]) // 2)
            _save_cursor()
        return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}

    def _commit_completed_slice(
        prefix_k: str,
        file_idx_key: str,
        rng_k: Tuple[int, int],
        total_cnt: int,
        cur_phase_k: str,
        next_phase_k: str,
        extra_done_ok: bool,
        add_matched: int,
        add_enqueued: int,
    ) -> None:
        nonlocal cursor
        with _cursor_meta_lock():
            inf_m = _pop_cursor_inflight(prefix_k, rng_k)
            done_r = _merge_idx_ranges([*(cursor.get(f"{prefix_k}_done_ranges") or ()), [rng_k[0], rng_k[1]]])
            cursor[f"{prefix_k}_done_ranges"] = done_r
            cursor[file_idx_key] = done_r[0][1] if (done_r and done_r[0][0] == 0) else 0
            cursor["matched_count"] = int(cursor["matched_count"]) + add_matched
            cursor["enqueued_count"] = int(cursor["enqueued_count"]) + add_enqueued
            if (
                cursor["phase"] == cur_phase_k
                and len(done_r) == 1
                and done_r[0] == [0, total_cnt]
                and not inf_m
                and extra_done_ok
            ):
                cursor["phase"] = next_phase_k
            _save_cursor()

    def _commit_exact_hash_progress(new_h_off: int, advance_sig: bool) -> None:
        nonlocal cursor
        with _cursor_meta_lock():
            cursor = _load_cursor_dict()
            cursor["hash_offset"] = new_h_off
            if advance_sig:
                cursor["phase"] = "sig_slices"
            cursor["matched_count"] = int(cursor["matched_count"]) + matched_now
            cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enqueued_now
            _save_cursor()

    def _run_exact_hash_for_variants(
        var_list: Sequence[Dict[str, Any]],
        start_off: int,
        progress_cb: Optional[Any],
    ) -> Tuple[int, bool]:
        nonlocal matched_now, enqueued_now
        if not (has_base_parquet and DUCKDB_BIN.is_file()):
            return 0, True
        hash_to_variants: Dict[str, Tuple[Dict[str, Any], Decimal, str]] = {}
        for v in var_list:
            for h in v.get("hashes") or ():
                hash_to_variants.setdefault(h, (v, Decimal("1"), "exact_hash"))
        impl_addr_to_v = _index_variant_impl_addrs(var_list)
        if impl_addr_to_v:
            _, clone_h2i = _compute_clone_hash_to_impl_map(list(impl_addr_to_v.keys()))
            for ch_cl, imp_a in clone_h2i.items():
                v_imp = impl_addr_to_v.get(imp_a)
                if v_imp is not None:
                    hash_to_variants.setdefault(ch_cl, (v_imp, Decimal("0.99"), "clone_hash"))
        all_hashes = sorted(hash_to_variants.keys())
        h_off = max(0, int(start_off))
        while h_off < len(all_hashes) and (time.monotonic() - t0) < max_wall_sec:
            h_chunk = all_hashes[h_off : h_off + 360]
            rch_pred, rch_proj_expr = _sql_rch_in_and_proj(rch_type, h_chunk)
            rch_sel = f"{rch_proj_expr} AS rch_hex"
            rows = _run_duckdb_cli_json(
                f"""
                SELECT
                    CAST(d.chain_id AS BIGINT) AS cid,
                    {addr_proj} AS addr_hex,
                    {rch_sel}
                FROM contracts ct
                JOIN contract_deployments d ON d.contract_id = ct.id
                WHERE {rch_pred}
                  {chain_filter}
                """,
                parquet_root=p_root,
                timeout_sec=ddb_q_timeout,
            )
            if rows is None:
                if progress_cb is not None:
                    progress_cb(h_off, False)
                return h_off, False
            batch_m: List[Dict[str, Any]] = []
            for er in rows:
                parsed_er = _extract_non_seed_sourcify_row(er)
                if parsed_er is None:
                    continue
                _, c_slug, addr_n = parsed_er
                v_hit = hash_to_variants.get(str(er.get("rch_hex") or "").lower())
                if v_hit is None:
                    continue
                matched_now += 1
                m_tp_h = v_hit[2]
                batch_m.append(
                    _make_mode_b_match_entry(
                        v_hit[0],
                        c_slug,
                        addr_n,
                        v_hit[1],
                        m_tp_h,
                        patch_rank_delta=350,
                        vuln_preserved=True,
                        patch_kind=("clone_live_delegate" if m_tp_h == "clone_hash" else "exact_unpatched"),
                    )
                )
            enqueued_now += _enqueue_mode_b_sourcify_matches(store, batch_m, router=router)
            h_off += len(h_chunk)
        if progress_cb is not None:
            progress_cb(h_off, h_off >= len(all_hashes))
        return h_off, (h_off >= len(all_hashes))

    # Phase 2: Exact runtime_code_hash + 11종 최소 프록시(EIP-1167 / Solady PUSH0 / Vyper / EIP-7702) 클론 해시 일괄 스캔
    if cursor["phase"] == "exact_hash":
        with _serial_phase_try_lock() as acq_e:
            if acq_e:
                if has_base_parquet and DUCKDB_BIN.is_file():
                    _, ok_eh = _run_exact_hash_for_variants(
                        seed_variants, int(cursor["hash_offset"]), _commit_exact_hash_progress
                    )
                    if not ok_eh:
                        timed_out_flag = True
                        return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                else:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        cursor["phase"] = "code_slices"
                        _save_cursor()
            else:
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
        if cursor["phase"] in ("exact_hash", "exhausted") or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

    # 사전 계산된 메모리 인덱스 구축 및 O(1) 재사용 캐시 조회 (sig_slices / code_slices 공용)
    precomp_variants, pv_union_clean, pv_union_masked, len_intervals = _get_precomputed_mode_b_seeds(seed_variants)
    has_sig_tables = all(
        int(f_counts.get(tbl, 0)) > 0
        for tbl in ("signatures", "compiled_contracts_signatures", "verified_contracts")
    )
    ccs_files = sorted((p_root / "compiled_contracts_signatures").glob("*.parquet"))
    code_files = sorted((p_root / "code").glob("*.parquet"))
    vc_comp_col, vc_dep_col, ccs_sig_comp_col = _unpack_sourcify_vc_ccs_cols(vc_cols, ccs_sig_cols)
    _, rch_hex_proj = _sql_rch_in_and_proj(rch_type, ())
    use_late_mat = int(f_counts.get("verified_contracts", 0)) > 4 and int(f_counts.get("compiled_contracts", 0)) > 0
    idx_cache_dir = None if store._is_memory else _store_cache_dir(store)
    is_blob_code = "BLOB" in cd_cols.get("code", "BLOB")
    usable_rch_path: Optional[Path] = None
    usable_comp_path: Optional[Path] = None
    seed_src_cache: Dict[str, Dict[str, str]] = {}

    def _ensure_usable_indices() -> None:
        nonlocal usable_rch_path, usable_comp_path
        if usable_rch_path is None and idx_cache_dir is not None:
            usable_rch_path = _ensure_usable_chain_rch_index(
                p_root, idx_cache_dir, f_counts, rch_type, cd_cols.get("code_hash", ""), usable_cid_list
            )
        if usable_comp_path is None and idx_cache_dir is not None and usable_rch_path is not None:
            usable_comp_path = _ensure_usable_chain_comp_index(
                p_root, idx_cache_dir, f_counts, cc_cols, usable_rch_path
            )

    def _get_seed_sources(pv_obj: Mapping[str, Any]) -> Dict[str, str]:
        slug_k = str(pv_obj.get("slug") or "")
        if slug_k in seed_src_cache:
            return seed_src_cache[slug_k]
        s_map: Dict[str, str] = {}
        scid = CHAIN_IDS.get(_norm_chain(str(pv_obj.get("chain") or "")), 0)
        if scid > 0 and has_sig_tables:
            for sa in [pv_obj.get("addr"), *(pv_obj.get("addrs") or ())][:2]:
                na_s = _norm_addr(str(sa or ""))
                if not na_s:
                    continue
                try:
                    loc_v = _query_local_sourcify_verified(scid, na_s, parquet_root=p_root)
                    if isinstance(loc_v, dict) and loc_v.get("verified") and isinstance(loc_v.get("sources"), dict):
                        s_map = dict(loc_v["sources"])
                        break
                except _RECOVERABLE_IO_EXC:
                    pass
        seed_src_cache[slug_k] = s_map
        return s_map

    fuzzy_sig_cache: Dict[str, Dict[str, Set[str]]] = {}

    def _scan_sig_slice_for_pvs(
        ccs_slice: Sequence[Path],
        pv_sub: Sequence[Dict[str, Any]],
    ) -> Optional[List[Dict[str, Any]]]:
        if not (has_base_parquet and has_sig_tables and ccs_slice and pv_sub and DUCKDB_BIN.is_file()):
            return []
        if use_late_mat:
            _ensure_usable_indices()
        if use_late_mat and "global" not in fuzzy_sig_cache and int(f_counts.get("signatures", 0)) > 0:
            all_d_sels = sorted({sh for pv in pv_sub for sh in pv["disp_set"]})[:64]
            all_k_ids = list(dict.fromkeys(str(k) for pv in pv_sub for k in (pv.get("key_identifiers") or ())))[:24]
            fuzzy_sig_cache["global"] = _expand_seed_fuzzy_sig_hashes(p_root, all_d_sels, all_k_ids)
        fmap = fuzzy_sig_cache.get("global") or {}

        sel_df: Dict[str, int] = {}
        for pv in pv_sub:
            for sh in pv["disp_set"] | set(pv.get("err_sels4") or ()):
                sel_df[sh] = sel_df.get(sh, 0) + 1
        sel_to_v_idxs: Dict[str, List[int]] = {}
        topic_to_v_idxs: Dict[str, List[int]] = {}
        pv_sig_sets: List[Set[str]] = []
        pv_topic_sets: List[Set[str]] = []
        for idx_v, pv in enumerate(pv_sub):
            prio_s = set(pv.get("prio_sels") or ())
            combined_s = set(pv["disp_set"]) | set(pv.get("err_sels4") or ())
            pv_sig_sets.append(set(combined_s))
            ordered_sels = sorted(
                combined_s,
                key=lambda sh: (0 if sh in prio_s else 1, sel_df.get(sh, 1), sh),
            )
            for sh in ordered_sels[:8]:
                sel_to_v_idxs.setdefault(sh, []).append(idx_v)
            # Attach fuzzy stem alternates so renamed verified forks get recalled cleanly!
            for ki in (pv.get("key_identifiers") or ())[:4]:
                head_ki = str(ki).split("(", 1)[0].rsplit(".", 1)[-1].lower()
                for st_k, sh_set in fmap.items():
                    if st_k in head_ki:
                        for f_sh in sorted(sh_set)[:4]:
                            sel_to_v_idxs.setdefault(f_sh, []).append(idx_v)
                            pv_sig_sets[-1].add(f_sh)
            t_set = {str(t).lower().removeprefix("0x") for t in (pv.get("event_topics32") or ()) if t}
            pv_topic_sets.append(t_set)
            for t32 in sorted(t_set):
                topic_to_v_idxs.setdefault(t32, []).append(idx_v)
        chosen_sels = sorted(sel_to_v_idxs.keys())
        chosen_topics32 = sorted(topic_to_v_idxs.keys())
        if not chosen_sels and not chosen_topics32:
            return []
        sel_blob_in = ", ".join(f"unhex({_sql_quote_str(sh)})" for sh in chosen_sels) if chosen_sels else "NULL"
        min_sels_sql = 1 if (len(chosen_sels) <= 1 or bool(chosen_topics32) or any(len(pv["disp_set"]) <= 1 for pv in pv_sub)) else 2

        def _match_best_pv_by_sels(hit_sels: Set[str]) -> Tuple[Optional[Dict[str, Any]], Decimal]:
            best_pv_l: Optional[Dict[str, Any]] = None
            best_sc_l = _DEC_ZERO
            cand_v_idxs: Set[int] = set()
            for hs in sorted(hit_sels):
                for iv in sel_to_v_idxs.get(hs, ()):
                    cand_v_idxs.add(iv)
                for iv in topic_to_v_idxs.get(hs, ()):
                    cand_v_idxs.add(iv)
            for iv in sorted(cand_v_idxs):
                pv_i = pv_sub[iv]
                s_sels = pv_sig_sets[iv]
                t_hits = len(hit_sels & pv_topic_sets[iv])
                inter = len(hit_sels & s_sels)
                req_cnt = 1 if len(s_sels) <= 1 else max(2, (len(s_sels) * 45) // 100)
                if inter >= req_cnt or t_hits >= 1:
                    sc_s = max(
                        min(Decimal("0.99"), Decimal(inter) / Decimal(max(1, len(s_sels)))) if inter >= req_cnt else _DEC_ZERO,
                        Decimal("0.45") if t_hits >= 1 else _DEC_ZERO,
                    )
                    if sc_s > best_sc_l:
                        best_sc_l = sc_s
                        best_pv_l = pv_i
            return best_pv_l, best_sc_l

        out_sig_m: List[Dict[str, Any]] = []
        sig32_blob_flag = "BLOB" in ccs_sig_cols.get("signature_hash_32", "BLOB")
        if use_late_mat:
            comp_rows = _query_sourcify_sig_comp_ids(
                p_root,
                sel_blob_in=sel_blob_in,
                min_match_cnt=min_sels_sql,
                ccs_sig_comp_col=ccs_sig_comp_col,
                timeout_sec=ddb_q_timeout,
                include_m_sels=True,
                table_files={"compiled_contracts_signatures": list(ccs_slice)},
                limit_comps=1024,
                event_topics32=chosen_topics32[:128],
                usable_comp_path=usable_comp_path,
                sig32_blob_col_blob=sig32_blob_flag,
            )
            if comp_rows is None:
                return None
            cand_comp_by_case: Dict[int, List[Tuple[str, Dict[str, Any], Decimal]]] = {}
            for cr_s in comp_rows:
                cid_s = str(cr_s.get("comp_id_str") or "").strip()
                if not cid_s:
                    continue
                hit_sels = {x.strip().lower() for x in str(cr_s.get("m_sels") or "").split(",") if x.strip()}
                bpv_s, bsc_s = _match_best_pv_by_sels(hit_sels)
                if bpv_s is not None and bsc_s >= CONTAINMENT_MIN:
                    cand_comp_by_case.setdefault(int(bpv_s.get("case_idx") or 0), []).append((cid_s, bpv_s, bsc_s))
            # Round-robin across seeds so every seed gets fair representation up to 512 compiled templates
            cand_comp_map: Dict[str, Tuple[Dict[str, Any], Decimal]] = {}
            rr_queues: List[deque[Tuple[str, Dict[str, Any], Decimal]]] = [
                deque(v_q) for _, v_q in sorted(cand_comp_by_case.items()) if v_q
            ]
            while rr_queues and len(cand_comp_map) < 512:
                next_queues: List[deque[Tuple[str, Dict[str, Any], Decimal]]] = []
                for q_c in rr_queues:
                    if len(cand_comp_map) >= 512:
                        break
                    cid_s, bpv_s, bsc_s = q_c.popleft()
                    cand_comp_map[cid_s] = (bpv_s, bsc_s)
                    if q_c:
                        next_queues.append(q_c)
                rr_queues = next_queues
            if cand_comp_map:
                cc_meta_map = _fetch_sourcify_compiled_rch_map(
                    p_root, cc_cols, list(cand_comp_map.keys()), timeout_sec=ddb_q_timeout, usable_comp_path=usable_comp_path
                )
                needed_rchs_lm = sorted({
                    m_v["rch_hex"] for m_v in cc_meta_map.values() if _HEX64_RE.fullmatch(m_v.get("rch_hex") or "")
                })
                code_by_hash_lm: Dict[str, bytes] = {}
                if needed_rchs_lm and int(f_counts.get("code", 0)) > 0:
                    code_by_hash_lm = _decode_hex_code_map(
                        _fetch_sourcify_code_hex_by_hashes(
                            p_root, cd_cols, needed_rchs_lm, timeout_sec=ddb_q_timeout
                        )
                    )
                winning_comps: Dict[str, Tuple[Dict[str, Any], Decimal, str, int, bool, str]] = {}
                src_check_cids: List[str] = []
                scored_clean_by_cid: Dict[str, bytes] = {}
                for cid_s, (pv_c, sel_sc_c) in cand_comp_map.items():
                    rh_c = (cc_meta_map.get(cid_s) or {}).get("rch_hex") or ""
                    if rh_c and rh_c in code_by_hash_lm:
                        c_clean = _strip_cbor_bytes(code_by_hash_lm[rh_c])
                        if not c_clean:
                            continue
                        _, fin_sc = _score_cand_clean_against_seed_pool(
                            c_clean, [pv_c], pv_c["clean_grams"], pv_c["combined_aux_grams"], CONTAINMENT_MIN
                        )
                        if fin_sc >= CONTAINMENT_MIN:
                            pd_s, vp_s, pk_s = _assess_candidate_patch_delta(pv_c, c_clean, fin_sc)
                            winning_comps[cid_s] = (pv_c, fin_sc, "exact" if fin_sc >= Decimal("0.99") else "ngram", pd_s, vp_s, pk_s)
                            if vp_s and fin_sc < Decimal("0.995"):
                                src_check_cids.append(cid_s)
                                scored_clean_by_cid[cid_s] = c_clean
                    elif int(f_counts.get("code", 0)) == 0 and sel_sc_c >= CONTAINMENT_MIN:
                        winning_comps[cid_s] = (pv_c, sel_sc_c, "selector_containment", 0, True, "selector_only")
                # Cross-check verified Solidity/Vyper source diff for logic/math/oracle patches when seed source exists
                if src_check_cids and int(f_counts.get("compiled_contracts_sources", 0)) > 0:
                    seeds_with_src = {
                        cid_s: _get_seed_sources(winning_comps[cid_s][0])
                        for cid_s in src_check_cids[:16]
                    }
                    active_cids = [cid_s for cid_s, s_m in seeds_with_src.items() if s_m]
                    if active_cids:
                        cand_src_map = _fetch_sourcify_sources_by_comp_ids(p_root, f_counts, c_types, active_cids)
                        for cid_s in active_cids:
                            cs = cand_src_map.get(cid_s)
                            if cs:
                                w_e = winning_comps[cid_s]
                                pd_sr, vp_sr, pk_sr = _assess_candidate_patch_delta(
                                    w_e[0],
                                    scored_clean_by_cid[cid_s],
                                    w_e[1],
                                    seed_sources=seeds_with_src[cid_s],
                                    cand_sources=cs,
                                    key_identifiers=w_e[0].get("key_identifiers") or (),
                                )
                                if not vp_sr:
                                    winning_comps[cid_s] = (w_e[0], w_e[1], w_e[2], pd_sr, vp_sr, pk_sr)
                if winning_comps:
                    dep_rows_lm = _resolve_sourcify_comp_ids_deployments(
                        p_root,
                        comp_ids=list(winning_comps.keys()),
                        vc_cols=vc_cols,
                        vc_comp_col=vc_comp_col,
                        vc_dep_col=vc_dep_col,
                        addr_proj=addr_proj,
                        rch_hex_proj=rch_hex_proj,
                        chain_filter=chain_filter,
                        include_contracts_rch=False,
                        timeout_sec=ddb_q_timeout,
                    )
                    if dep_rows_lm is None:
                        return None
                    _append_winning_dep_matches(out_sig_m, dep_rows_lm, "comp_id_str", winning_comps)
        else:
            sig_rows = _query_sourcify_sig_matches(
                p_root,
                sel_blob_in=sel_blob_in,
                min_match_cnt=min_sels_sql,
                ccs_sig_comp_col=ccs_sig_comp_col,
                vc_comp_col=vc_comp_col,
                vc_dep_col=vc_dep_col,
                addr_proj=addr_proj,
                rch_hex_proj=rch_hex_proj,
                chain_filter=chain_filter,
                timeout_sec=ddb_q_timeout,
                include_m_sels=True,
                table_files={"compiled_contracts_signatures": list(ccs_slice)},
            )
            if sig_rows is None:
                return None
            cand_hits: List[Tuple[int, str, str, str, Dict[str, Any], Decimal]] = []
            needed_rchs: Set[str] = set()
            for sr in sig_rows:
                parsed_sr = _extract_non_seed_sourcify_row(sr)
                if parsed_sr is None:
                    continue
                cid_v, c_slug, addr_n = parsed_sr
                rch_k = str(sr.get("rch_hex") or "").lower()
                hit_sels = {x.strip().lower() for x in str(sr.get("m_sels") or "").split(",") if x.strip()}
                best_pv, best_sc = _match_best_pv_by_sels(hit_sels)
                if best_pv is not None:
                    cand_hits.append((cid_v, c_slug, addr_n, rch_k, best_pv, best_sc))
                    if _HEX64_RE.fullmatch(rch_k):
                        needed_rchs.add(rch_k)
            code_by_hash: Dict[str, bytes] = {}
            if needed_rchs and int(f_counts.get("code", 0)) > 0:
                sorted_rchs = sorted(needed_rchs)
                for r_off in range(0, len(sorted_rchs), 192):
                    code_by_hash.update(
                        _decode_hex_code_map(
                            _fetch_sourcify_code_hex_by_hashes(
                                p_root, cd_cols, sorted_rchs[r_off : r_off + 192], timeout_sec=15.0
                            )
                        )
                    )
            for cid_v, c_slug, addr_n, rch_k, pv, sel_sc in cand_hits:
                fin_score = sel_sc
                m_type = "selector_containment"
                pd_s, vp_s, pk_s = 0, True, "selector_only"
                if rch_k in code_by_hash:
                    cb = code_by_hash[rch_k]
                    c_clean = _strip_cbor_bytes(cb)
                    if not c_clean:
                        continue
                    c_masked = _normalize_bytecode_immediates(c_clean)
                    fin_score = _score_clean_against_seed_variant(
                        pv, c_clean, c_masked, _extract_grams_clean(c_clean), _extract_grams_clean(c_masked) if c_masked else set()
                    )
                    if fin_score < CONTAINMENT_MIN:
                        continue
                    m_type = "exact" if fin_score >= Decimal("0.99") else "ngram"
                    pd_s, vp_s, pk_s = _assess_candidate_patch_delta(pv, c_clean, fin_score)
                elif int(f_counts.get("code", 0)) > 0 or sel_sc < CONTAINMENT_MIN:
                    continue
                out_sig_m.append(
                    _make_mode_b_match_entry(
                        pv,
                        c_slug,
                        addr_n,
                        fin_score,
                        m_type,
                        patch_rank_delta=pd_s,
                        vuln_preserved=vp_s,
                        patch_kind=pk_s,
                    )
                )
        return out_sig_m

    def _build_code_scan_bundle(pv_sub: Sequence[Dict[str, Any]]) -> Tuple[Dict[str, Dict[str, Any]], List[str], List[Tuple[int, int]]]:
        imp_map = _index_variant_impl_addrs(pv_sub)
        anchor_grps = (
            _build_seed_re2_anchor_groups(pv_sub, extra_impl_hexes=list(imp_map.keys()), max_pats_per_group=520)
            if len(code_files) > 8
            else []
        )
        l_ints = len_intervals if pv_sub is precomp_variants else _build_seed_len_intervals(pv_sub)
        return imp_map, anchor_grps, l_ints

    def _score_cand_bytes_against_bundle(
        cb: bytes,
        pv_sub: Sequence[Dict[str, Any]],
        u_clean_b: Set[bytes],
        u_mask_b: Set[bytes],
        imp_map: Mapping[str, Dict[str, Any]],
    ) -> Tuple[Optional[Dict[str, Any]], Decimal, str, int, bool, str]:
        if 23 <= len(cb) <= 8192 and imp_map:
            cwia_imp = _eip1167_impl(cb) or _eip7702_delegate(cb)
            if cwia_imp and cwia_imp in imp_map:
                return imp_map[cwia_imp], Decimal("0.98"), "cwia_clone", 350, True, "clone_live_delegate"
        c_clean = _strip_cbor_bytes(cb)
        if len(c_clean) < 56:
            return None, _DEC_ZERO, "", 0, True, "too_short"
        bpv_x, bsc_x = _score_cand_clean_against_seed_pool(
            c_clean, pv_sub, u_clean_b, u_mask_b, CONTAINMENT_MIN
        )
        if bpv_x is None or bsc_x < CONTAINMENT_MIN:
            return None, _DEC_ZERO, "", 0, True, "below_min"
        pd_x, vp_x, pk_x = _assess_candidate_patch_delta(bpv_x, c_clean, bsc_x)
        return bpv_x, bsc_x, ("exact" if bsc_x >= Decimal("0.99") else "ngram"), pd_x, vp_x, pk_x

    def _scan_sidecar_for_pvs(
        pv_sub: Sequence[Dict[str, Any]],
        u_clean_b: Set[bytes],
        u_mask_b: Set[bytes],
        imp_map: Mapping[str, Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        sc_hits: List[Dict[str, Any]] = []
        for sc_cid, sc_item in _iter_sourcify_sidecar_items(p_root):
            c_slug = CHAIN_BY_ID.get(sc_cid, "")
            addr_n = _norm_addr(sc_item.get("address"))
            if not (c_slug and _usable_chain(c_slug) and addr_n) or (sc_cid, addr_n) in seed_addr_keys:
                continue
            chex = str(sc_item.get("runtime_code_hex") or sc_item.get("code_hex") or "").replace("0x", "").strip()
            if not chex:
                continue
            try:
                cb = bytes.fromhex(chex)
            except Exception:
                continue
            bpv, bsc, m_tp_sc, pd_sc, vp_sc, pk_sc = _score_cand_bytes_against_bundle(
                cb, pv_sub, u_clean_b, u_mask_b, imp_map
            )
            if bpv is not None and bsc >= CONTAINMENT_MIN:
                sc_hits.append(
                    _make_mode_b_match_entry(
                        bpv, c_slug, addr_n, bsc, m_tp_sc, patch_rank_delta=pd_sc, vuln_preserved=vp_sc, patch_kind=pk_sc
                    )
                )
        return sc_hits

    def _scan_code_slice_for_pvs(
        c_slice: Sequence[Path],
        pv_sub: Sequence[Dict[str, Any]],
        u_clean_b: Set[bytes],
        u_mask_b: Set[bytes],
        imp_map: Mapping[str, Dict[str, Any]],
        anchor_grps: Sequence[str],
        l_ints: Sequence[Tuple[int, int]],
    ) -> Optional[List[Dict[str, Any]]]:
        if not (has_base_parquet and c_slice and pv_sub and DUCKDB_BIN.is_file()):
            return []
        base_len_sql = (
            " OR ".join(f"(octet_length(cd.code) BETWEEN {int(lo)} AND {int(hi)})" for lo, hi in l_ints)
            if is_blob_code and l_ints
            else ("octet_length(cd.code) >= 56" if is_blob_code else "length(cd.code) >= 112")
        )
        len_sql_with_clones = (
            f"((octet_length(cd.code) BETWEEN 23 AND 1024) OR {base_len_sql})"
            if (is_blob_code and imp_map)
            else base_len_sql
        )
        join_ch_cond = (
            "ct.runtime_code_hash = cd.code_hash"
            if "BLOB" in rch_type and "BLOB" in cd_cols.get("code_hash", "")
            else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '')) = lower(replace(CAST(cd.code_hash AS VARCHAR), '0x', ''))"
        )
        code_hex_expr = "lower(hex(cd.code))" if is_blob_code else "lower(replace(CAST(cd.code AS VARCHAR), '0x', ''))"
        ch_code_expr = (
            "lower(hex(cd.code_hash))"
            if "BLOB" in cd_cols.get("code_hash", "BLOB")
            else "lower(replace(CAST(cd.code_hash AS VARCHAR), '0x', ''))"
        )
        out_code_m: List[Dict[str, Any]] = []

        def _safe_score_code_hex(code_hex_s: str) -> Tuple[Optional[Dict[str, Any]], Decimal, str, int, bool, str]:
            try:
                cb_loc = bytes.fromhex(code_hex_s)
                return _score_cand_bytes_against_bundle(cb_loc, pv_sub, u_clean_b, u_mask_b, imp_map)
            except Exception:
                return None, _DEC_ZERO, "", 0, True, ""

        if len(code_files) > 8 and anchor_grps:
            _ensure_usable_indices()
            semi_join_sql = (
                f"\nSEMI JOIN read_parquet({_sql_quote_str(usable_rch_path.resolve().as_posix())}) u ON cd.code_hash = u.rch_blob"
                if (usable_rch_path is not None and usable_rch_path.is_file())
                else ""
            )
            winning_ch_map: Dict[str, Tuple[Dict[str, Any], Decimal, str, int, bool, str]] = {}
            for grp_off in range(0, len(anchor_grps), 4):
                grp_batch = anchor_grps[grp_off : grp_off + 4]
                if len(grp_batch) == 1:
                    hit_expr_sql = f"regexp_extract(code_hex, {_sql_quote_str(grp_batch[0])})"
                else:
                    coal_args = ", ".join(
                        f"NULLIF(regexp_extract(code_hex, {_sql_quote_str(gp)}), '')"
                        for gp in grp_batch
                    )
                    hit_expr_sql = f"COALESCE({coal_args}, '')"
                sub_file_step = max(2, len(c_slice) // max(1, len(grp_batch))) if len(grp_batch) > 1 else len(c_slice)
                for cf_off in range(0, len(c_slice), sub_file_step):
                    c_sub_slice = list(c_slice[cf_off : cf_off + sub_file_step])
                    raw_c_rows = _run_duckdb_cli_json(
                        f"""
                        WITH base_cd AS (
                            SELECT
                                {ch_code_expr} AS ch_hex,
                                {code_hex_expr} AS code_hex
                            FROM code cd{semi_join_sql}
                            WHERE cd.code IS NOT NULL
                              AND ({len_sql_with_clones})
                        ),
                        matched_cd AS (
                            SELECT
                                ch_hex,
                                code_hex,
                                {hit_expr_sql} AS hit_anchor
                            FROM base_cd
                        )
                        SELECT ch_hex, code_hex
                        FROM matched_cd
                        WHERE hit_anchor != ''
                        QUALIFY row_number() OVER (
                            PARTITION BY CASE
                                WHEN left(hit_anchor, 2) IN ('47', '31', '5c', 'f5', '42', '09') AND length(hit_anchor) <= 26 THEN left(hit_anchor, 2)
                                WHEN left(hit_anchor, 2) = '73' AND length(hit_anchor) > 42 THEN left(hit_anchor, 42)
                                ELSE hit_anchor
                            END
                            ORDER BY ch_hex
                        ) <= 32
                        LIMIT 4096
                        """,
                        parquet_root=p_root,
                        timeout_sec=ddb_q_timeout,
                        scratch_root=idx_cache_dir,
                        table_files={"code": c_sub_slice},
                    )
                    if raw_c_rows is None:
                        return None
                    for cr in raw_c_rows:
                        ch_h = str(cr.get("ch_hex") or "").strip().lower()
                        if not _HEX64_RE.fullmatch(ch_h) or ch_h in winning_ch_map:
                            continue
                        bpv, bsc, m_tp_c, pd_c, vp_c, pk_c = _safe_score_code_hex(str(cr.get("code_hex") or ""))
                        if bpv is not None and bsc >= CONTAINMENT_MIN:
                            winning_ch_map[ch_h] = (bpv, bsc, m_tp_c, pd_c, vp_c, pk_c)
            if winning_ch_map:
                win_hashes = sorted(winning_ch_map.keys())
                for w_off in range(0, len(win_hashes), 128):
                    w_chk = win_hashes[w_off : w_off + 128]
                    w_pred, w_proj = _sql_rch_in_and_proj(rch_type, w_chk)
                    dep_rows_c = _run_duckdb_cli_json(
                        f"""
                        SELECT
                            CAST(d.chain_id AS BIGINT) AS cid,
                            {addr_proj} AS addr_hex,
                            {w_proj} AS rch_hex
                        FROM contracts ct
                        JOIN contract_deployments d ON d.contract_id = ct.id
                        WHERE {w_pred}
                          AND CAST(d.chain_id AS BIGINT) IN ({usable_cid_list})
                          {chain_filter}
                        QUALIFY row_number() OVER (PARTITION BY {w_proj}, d.chain_id ORDER BY d.id DESC) <= 12
                        LIMIT 2048
                        """,
                        parquet_root=p_root,
                        timeout_sec=ddb_q_timeout,
                        scratch_root=idx_cache_dir,
                    )
                    if dep_rows_c is None:
                        return None
                    _append_winning_dep_matches(
                        out_code_m, dep_rows_c, "rch_hex", winning_ch_map, lower_key=True
                    )
        else:
            c_rows = _run_duckdb_cli_json(
                f"""
                SELECT
                    {ch_code_expr} AS ch_hex,
                    ANY_VALUE({code_hex_expr}) AS code_hex,
                    string_agg(DISTINCT (CAST(d.chain_id AS VARCHAR) || ':' || ({addr_proj})), ',') AS deps
                FROM code cd
                JOIN contracts ct ON {join_ch_cond}
                JOIN contract_deployments d ON d.contract_id = ct.id
                WHERE ({len_sql_with_clones})
                  AND CAST(d.chain_id AS BIGINT) IN ({usable_cid_list})
                  {chain_filter}
                GROUP BY ch_hex
                """,
                parquet_root=p_root,
                timeout_sec=ddb_q_timeout,
                scratch_root=idx_cache_dir,
                table_files={"code": list(c_slice)},
            )
            if c_rows is None:
                return None
            for cr in c_rows:
                dep_list = [
                    dp for dp in _unpack_grouped_dep_pairs(cr.get("deps"))
                    if (dp[0], dp[2]) not in seed_addr_keys
                ]
                if not dep_list:
                    continue
                bpv, bsc, m_tp_c, pd_c, vp_c, pk_c = _safe_score_code_hex(str(cr.get("code_hex") or ""))
                if bpv is not None and bsc >= CONTAINMENT_MIN:
                    for _, c_slug, addr_n in dep_list:
                        out_code_m.append(
                            _make_mode_b_match_entry(
                                bpv,
                                c_slug,
                                addr_n,
                                bsc,
                                m_tp_c,
                                patch_rank_delta=pd_c,
                                vuln_preserved=vp_c,
                                patch_kind=pk_c,
                            )
                        )
        return out_code_m

    # 증분(Delta) 시드 전용 고속 캐치업 스캔: 기존 sig_done_ranges / code_done_ranges 를 절대 초기화하지 않고
    # 이미 통과한 슬라이스 구간에 대해서만 신규 시드 변형분만 추가 스캔한 뒤 원래 커서 지점에서 이어간다.
    pending_delta_list = [str(x) for x in (cursor.get("pending_delta_var_keys") or ()) if str(x)]
    if pending_delta_list and cursor["phase"] in ("sig_slices", "code_slices", "exhausted"):
        pending_delta_set = set(pending_delta_list)
        delta_pvs = [pv for pv in precomp_variants if _seed_var_uid(pv) in pending_delta_set]
        if not delta_pvs:
            with _cursor_meta_lock():
                cursor = _load_cursor_dict()
                cursor.pop("pending_delta_var_keys", None)
                cursor.pop("delta_exact_sig_done", None)
                cursor.pop("delta_sig_idx", None)
                cursor.pop("delta_code_idx", None)
                _save_cursor()
        else:
            with _serial_phase_try_lock() as acq_d:
                if acq_d:
                    delta_imp_map, delta_anchors, delta_len_ints = _build_code_scan_bundle(delta_pvs)
                    delta_u_clean, delta_u_mask = _build_seed_gram_unions(delta_pvs)
                    if not bool(cursor.get("delta_exact_sig_done")):
                        if has_base_parquet and DUCKDB_BIN.is_file():
                            _, ok_de = _run_exact_hash_for_variants(delta_pvs, 0, None)
                            if not ok_de:
                                return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                        if bool(cursor.get("sidecar_done")):
                            sc_delta = _scan_sidecar_for_pvs(delta_pvs, delta_u_clean, delta_u_mask, delta_imp_map)
                            matched_now += len(sc_delta)
                            enqueued_now += _enqueue_mode_b_sourcify_matches(store, sc_delta, router=router)
                        done_sig_file_idxs = [
                            i for lo, hi in (cursor.get("sig_done_ranges") or ())
                            for i in range(max(0, int(lo)), min(len(ccs_files), int(hi)))
                        ]
                        d_sig_off = int(cursor.get("delta_sig_idx") or 0)
                        d_sig_step = max(1, int(cursor.get("sig_step") or 32))
                        while d_sig_off < len(done_sig_file_idxs) and (time.monotonic() - t0) < max_wall_sec:
                            sub_ccs = [ccs_files[idx_f] for idx_f in done_sig_file_idxs[d_sig_off : d_sig_off + d_sig_step]]
                            ds_hits = _scan_sig_slice_for_pvs(sub_ccs, delta_pvs)
                            if ds_hits is None:
                                with _cursor_meta_lock():
                                    cursor = _load_cursor_dict()
                                    cursor["delta_sig_idx"] = d_sig_off
                                    _save_cursor()
                                return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                            matched_now += len(ds_hits)
                            enqueued_now += _enqueue_mode_b_sourcify_matches(store, ds_hits, router=router)
                            d_sig_off += len(sub_ccs)
                        with _cursor_meta_lock():
                            cursor = _load_cursor_dict()
                            cursor["delta_sig_idx"] = d_sig_off
                            cursor["delta_exact_sig_done"] = d_sig_off >= len(done_sig_file_idxs)
                            cursor["matched_count"] = int(cursor["matched_count"]) + matched_now
                            cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enqueued_now
                            _save_cursor()
                        if not bool(cursor.get("delta_exact_sig_done")) or (time.monotonic() - t0) >= max_wall_sec:
                            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

                    done_code_file_idxs = [
                        i for lo, hi in (cursor.get("code_done_ranges") or ())
                        for i in range(max(0, int(lo)), min(len(code_files), int(hi)))
                    ]
                    d_code_off = int(cursor.get("delta_code_idx") or 0)
                    d_code_step = max(1, int(cursor.get("code_step") or batch_code_files))
                    d_c_matched = 0
                    d_c_enq = 0
                    while d_code_off < len(done_code_file_idxs) and (time.monotonic() - t0) < max_wall_sec:
                        sub_cf = [code_files[idx_c] for idx_c in done_code_file_idxs[d_code_off : d_code_off + d_code_step]]
                        dc_hits = _scan_code_slice_for_pvs(
                            sub_cf, delta_pvs, delta_u_clean, delta_u_mask, delta_imp_map, delta_anchors, delta_len_ints
                        )
                        if dc_hits is None:
                            with _cursor_meta_lock():
                                cursor = _load_cursor_dict()
                                cursor["delta_code_idx"] = d_code_off
                                cursor["matched_count"] = int(cursor["matched_count"]) + d_c_matched
                                cursor["enqueued_count"] = int(cursor["enqueued_count"]) + d_c_enq
                                _save_cursor()
                            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                        d_c_matched += len(dc_hits)
                        matched_now += len(dc_hits)
                        enq_dc = _enqueue_mode_b_sourcify_matches(store, dc_hits, router=router)
                        d_c_enq += enq_dc
                        enqueued_now += enq_dc
                        d_code_off += len(sub_cf)
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        cursor["delta_code_idx"] = d_code_off
                        cursor["matched_count"] = int(cursor["matched_count"]) + d_c_matched
                        cursor["enqueued_count"] = int(cursor["enqueued_count"]) + d_c_enq
                        if d_code_off >= len(done_code_file_idxs):
                            cursor.pop("pending_delta_var_keys", None)
                            cursor.pop("delta_exact_sig_done", None)
                            cursor.pop("delta_sig_idx", None)
                            cursor.pop("delta_code_idx", None)
                        _save_cursor()
                    if cursor.get("pending_delta_var_keys") or (time.monotonic() - t0) >= max_wall_sec:
                        return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

    # Phase 3: 함수·에러·이벤트 시그니처 파티션 병렬 샤딩 슬라이스 (2단계 지연 실체화로 6,000만 행 조인 타임아웃 제거)
    if cursor["phase"] == "sig_slices":
        if has_base_parquet and has_sig_tables and ccs_files and DUCKDB_BIN.is_file():
            while (time.monotonic() - t0) < max_wall_sec:
                claimed_sig: Optional[Tuple[int, int]] = None
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    if cursor["phase"] == "sig_slices":
                        s_done = _merge_idx_ranges(cursor.get("sig_done_ranges") or ())
                        s_inf = dict(cursor.get("sig_inflight") or {})
                        sig_step = max(1, int(cursor.get("sig_step") or 32))
                        claimed_sig = _claim_next_slice_range(
                            s_done,
                            s_inf,
                            len(ccs_files),
                            sig_step,
                            time.time(),
                            lease_sec=45.0,
                        )
                        cursor["sig_done_ranges"] = s_done
                        cursor["sig_inflight"] = s_inf
                        if claimed_sig is None and len(s_done) == 1 and s_done[0] == [0, len(ccs_files)] and not s_inf:
                            cursor["phase"] = "code_slices"
                        _save_cursor()
                if claimed_sig is None:
                    break
                ccs_slice = ccs_files[claimed_sig[0] : claimed_sig[1]]
                batch_sig_m = _scan_sig_slice_for_pvs(ccs_slice, precomp_variants)
                if batch_sig_m is None:
                    timed_out_flag = True
                    return _release_timed_out_slice("sig", claimed_sig)
                matched_now += len(batch_sig_m)
                enq_s = _enqueue_mode_b_sourcify_matches(store, batch_sig_m, router=router)
                enqueued_now += enq_s
                _commit_completed_slice(
                    "sig", "sig_file_idx", claimed_sig, len(ccs_files), "sig_slices", "code_slices", True, len(batch_sig_m), enq_s
                )
        else:
            with _cursor_meta_lock():
                cursor = _load_cursor_dict()
                if cursor["phase"] == "sig_slices":
                    cursor["phase"] = "code_slices"
                    _save_cursor()
        if cursor["phase"] != "code_slices" or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

    # Phase 4: code/*.parquet 병렬 샤딩 (생존 체인 BLOB SEMI JOIN + 멀티-DFA RE2 샤딩 + 패치 차분 랭킹) + 사이드카 전수 스캔
    if cursor["phase"] == "code_slices":
        impl_to_variant_c, re2_anchor_groups, eff_len_ints = _build_code_scan_bundle(precomp_variants)

        if not bool(cursor.get("sidecar_done")):
            with _serial_phase_try_lock() as acq_sc:
                if acq_sc:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        need_sc = not bool(cursor.get("sidecar_done"))
                    if need_sc:
                        sidecar_m = _scan_sidecar_for_pvs(
                            precomp_variants, pv_union_clean, pv_union_masked, impl_to_variant_c
                        )
                        matched_now += len(sidecar_m)
                        enq_sc = _enqueue_mode_b_sourcify_matches(store, sidecar_m, router=router)
                        enqueued_now += enq_sc
                        with _cursor_meta_lock():
                            cursor = _load_cursor_dict()
                            cursor["sidecar_done"] = True
                            cursor["matched_count"] = int(cursor["matched_count"]) + len(sidecar_m)
                            cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enq_sc
                            _save_cursor()
                else:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()

        if has_base_parquet and code_files and DUCKDB_BIN.is_file():
            while (time.monotonic() - t0) < max_wall_sec:
                claimed_code: Optional[Tuple[int, int]] = None
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    if cursor["phase"] == "code_slices":
                        c_done = _merge_idx_ranges(cursor.get("code_done_ranges") or ())
                        c_inf = dict(cursor.get("code_inflight") or {})
                        code_step = max(1, int(cursor.get("code_step") or batch_code_files))
                        claimed_code = _claim_next_slice_range(
                            c_done,
                            c_inf,
                            len(code_files),
                            code_step,
                            time.time(),
                            lease_sec=45.0,
                        )
                        cursor["code_done_ranges"] = c_done
                        cursor["code_inflight"] = c_inf
                        if (
                            claimed_code is None
                            and len(c_done) == 1
                            and c_done[0] == [0, len(code_files)]
                            and not c_inf
                            and bool(cursor.get("sidecar_done"))
                        ):
                            cursor["phase"] = "exhausted"
                        _save_cursor()
                if claimed_code is None:
                    break
                c_slice = code_files[claimed_code[0] : claimed_code[1]]
                batch_code_m = _scan_code_slice_for_pvs(
                    c_slice,
                    precomp_variants,
                    pv_union_clean,
                    pv_union_masked,
                    impl_to_variant_c,
                    re2_anchor_groups,
                    eff_len_ints,
                )
                if batch_code_m is None:
                    timed_out_flag = True
                    return _release_timed_out_slice("code", claimed_code)
                matched_now += len(batch_code_m)
                enq_c = _enqueue_mode_b_sourcify_matches(store, batch_code_m, router=router)
                enqueued_now += enq_c
                _commit_completed_slice(
                    "code",
                    "code_file_idx",
                    claimed_code,
                    len(code_files),
                    "code_slices",
                    "exhausted",
                    bool(cursor.get("sidecar_done")),
                    len(batch_code_m),
                    enq_c,
                )
        else:
            with _cursor_meta_lock():
                cursor = _load_cursor_dict()
                if cursor["phase"] == "code_slices" and bool(cursor.get("sidecar_done")):
                    cursor["phase"] = "exhausted"
                    _save_cursor()

    return {
        "phase": cursor["phase"],
        "enqueued": enqueued_now,
        "matched": matched_now,
        "timed_out": timed_out_flag,
    }


_HIGH_ROI_EMERGING_CHAINS: FrozenSet[str] = frozenset(
    {
        "base",
        "bsc",
        "arbitrum",
        "optimism",
        "sonic",
        "hyperevm",
        "berachain",
        "unichain",
        "katana",
        "plasma",
        "linea",
        "scroll",
        "blast",
        "mode",
        "mantle",
    }
)


@_with_decimal_prec_100
def _compute_mode_a_roi_priority_and_rank(
    tvl_d: Decimal,
    chain: str,
    *,
    listed_at: Any = None,
    audits_raw: Any = None,
    change_7d: Any = None,
    has_seed_addrs: bool = False,
    now_ts: Optional[int] = None,
) -> Tuple[int, Decimal]:
    """
    Mode A 전수 대상($100k+)의 단위 시간당 결함 발견 ROI 우선순위·정렬 점수 산출 (순수 Decimal/int):
    - Priority 1: 중소형 스윗스팟 ($100k ~ $30M) — 온체인 시드 보유(무인 즉시 검증) 최우선 · 최신 등재(listedAt)·무/단일 감사·7일 TVL 급증·신흥 체인 순
    - Priority 2: 중대형 ($30M ~ $500M)
    - Priority 4: 초대형 블루칩 ($500M+) — 전수 완수를 위해 유지하되 후순위 배치
    """
    if tvl_d <= Decimal("30000000"):
        prio = 1
    elif tvl_d <= Decimal("500000000"):
        prio = 2
    else:
        prio = 4

    rank_d = Decimal("3000000") if has_seed_addrs else _DEC_ZERO
    eff_now = int(now_ts) if now_ts is not None else int(time.time())
    try:
        l_ts = int(_to_dec(listed_at)) if listed_at not in (None, "", False) else 0
    except Exception:
        l_ts = 0
    if l_ts > 1_000_000_000 and eff_now >= l_ts:
        age_days = (eff_now - l_ts) // 86400
        if age_days <= 30:
            rank_d += Decimal("1200000")
        elif age_days <= 90:
            rank_d += Decimal("800000")
        elif age_days <= 180:
            rank_d += Decimal("450000")
        elif age_days <= 365:
            rank_d += Decimal("200000")

    aud_s = str(audits_raw if audits_raw is not None else "").strip().lower()
    if aud_s in ("", "0", "none", "false"):
        rank_d += Decimal("500000")
    elif aud_s == "1":
        rank_d += Decimal("200000")

    try:
        c7_d = _to_dec(change_7d) if change_7d not in (None, "", False) else _DEC_ZERO
        if c7_d.is_finite():
            if c7_d >= Decimal("50"):
                rank_d += Decimal("300000")
            elif c7_d >= Decimal("20"):
                rank_d += Decimal("150000")
    except _PARSE_DATA_EXC:
        pass

    if _norm_chain(chain) in _HIGH_ROI_EMERGING_CHAINS:
        rank_d += Decimal("150000")

    if Decimal("250000") <= tvl_d <= Decimal("15000000"):
        rank_d += Decimal("250000")

    tvl_tie = min(Decimal("100000"), max(_DEC_ZERO, tvl_d / Decimal("1000")))
    rank_d += tvl_tie.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    return prio, rank_d


def _collect_mode_a_seed_items() -> Tuple[
    List[Tuple[Any, ...]],
    List[Tuple[str, Dict[str, Any]]],
    bool,
]:
    """Mode A(Priority 2: _queue.json 캐시 또는 DeFiLlama 스팟 EVM TVL >= $100k 전수) 시드 목록 수집(무락 HTTP I/O 가능)."""
    batch_items: List[Tuple[Any, ...]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []

    _NON_SPOT_TVL_KEYS = {
        "borrowed",
        "staking",
        "vesting",
        "doublecounted",
        "govtokens",
    }
    _NON_SPOT_TVL_SUFFIXES = (
        "-borrowed",
        "-staking",
        "-vesting",
        "-doublecounted",
        "-govtokens",
    )

    min_tvl_dec = _to_dec(MIN_TVL_USD)

    def _extract_tvl_dec(val_raw: Any) -> Decimal:
        if isinstance(val_raw, (int, float, Decimal)) and not isinstance(val_raw, bool):
            d_v = _to_dec(val_raw)
            return d_v if d_v.is_finite() and d_v > _DEC_ZERO else _DEC_ZERO
        if isinstance(val_raw, str):
            d_s = _to_dec(val_raw.strip())
            return d_s if d_s.is_finite() and d_s > _DEC_ZERO else _DEC_ZERO
        if isinstance(val_raw, list) and val_raw:
            last_el = val_raw[-1]
            if isinstance(last_el, dict):
                return _extract_tvl_dec(
                    last_el.get("totalLiquidityUSD") if last_el.get("totalLiquidityUSD") is not None else last_el.get("tvl")
                )
            return _extract_tvl_dec(last_el)
        if isinstance(val_raw, dict):
            for k_tvl in ("tvl", "totalLiquidityUSD", "tvl_usd"):
                if k_tvl in val_raw and val_raw.get(k_tvl) is not None:
                    return _extract_tvl_dec(val_raw.get(k_tvl))
        return _DEC_ZERO

    # 1. 기존 audit_artifacts/_queue.json에 캐시된 시드가 있으면 우선 병합
    legacy_q = QUEUE_FILE_PATH
    if legacy_q.exists():
        try:
            qdata = _read_json(legacy_q, default={})
            items = qdata if isinstance(qdata, list) else qdata.get("items", qdata.get("queue", []))
            if isinstance(items, list):
                for it in items:
                    if not isinstance(it, dict):
                        continue
                    try:
                        slug = _norm_slug(it.get("slug") or it.get("name") or "")
                        chain = _norm_chain(str(it.get("chain") or "ethereum"))
                        tvl_d = _extract_tvl_dec(it.get("tvl_usd") if it.get("tvl_usd") is not None else it.get("tvl"))
                        addrs = it.get("addresses") or it.get("contracts") or []
                        if isinstance(addrs, str):
                            addrs = [na] if (na := _norm_addr(addrs)) else []
                        elif isinstance(addrs, list):
                            addrs = [na for x in addrs if (na := _norm_addr(str(x)))]
                        if slug and tvl_d >= min_tvl_dec and _usable_chain(chain):
                            l_prio, l_rank_d = _compute_mode_a_roi_priority_and_rank(
                                tvl_d,
                                chain,
                                listed_at=it.get("listedAt"),
                                audits_raw=it.get("audits"),
                                change_7d=it.get("change_7d"),
                                has_seed_addrs=bool(addrs),
                            )
                            batch_items.append((slug, l_prio, chain, tvl_d, addrs, "A", "", l_rank_d))
                            meta_dict = {
                                "url": str(it.get("url") or ""),
                                "docs": str(it.get("docs") or ""),
                                "gitbook": str(it.get("gitbook") or ""),
                                "github": it.get("github") if isinstance(it.get("github"), list) else ([str(it["github"])] if it.get("github") else []),
                                "module": str(it.get("module") or ""),
                            }
                            if any(meta_dict.values()):
                                meta_items.append((slug, meta_dict))
                    except Exception:
                        continue
        except _RECOVERABLE_IO_EXC:
            pass

    # 2. 실시간 DeFiLlama /protocols API 페치 시도 (Mode A: Priority 2, CEX/Chain만 제외, 스팟 EVM TVL >= $100k 전수 포함)
    if not batch_items:
        try:
            plist = _http_get_json_with_fallback(None, "https://api.llama.fi/protocols", timeout=15.0)
            if isinstance(plist, list):
                for p in plist:
                    if not isinstance(p, dict):
                        continue
                    try:
                        cat = str(p.get("category") or "").strip()
                        has_explicit_contracts = bool(
                            _norm_addr(str(p.get("address") or "").split(":", 1)[-1])
                            or (isinstance(p.get("addresses"), dict) and p.get("addresses"))
                            or (isinstance(p.get("contracts"), dict) and p.get("contracts"))
                        )
                        if cat == "CEX" or (cat == "Chain" and not has_explicit_contracts):
                            continue
                        slug = _norm_slug(p.get("slug") or p.get("name") or "")
                        if not slug:
                            continue

                        raw_addr = str(p.get("address") or "")
                        chain_str = str(p.get("chain") or "ethereum")
                        if ":" in raw_addr:
                            ch_part, ad_part = raw_addr.split(":", 1)
                            chain_str = ch_part
                            raw_addr = ad_part
                        c_norm = _norm_chain(chain_str)
                        a_norm = _norm_addr(raw_addr)
                        seed_list = [a_norm] if a_norm else []

                        ch_tvls = p.get("chainTvls")
                        spot_evm_by_chain: Dict[str, Decimal] = {}
                        has_explicit_spot_tvls = False
                        if isinstance(ch_tvls, dict):
                            for ch_k, ch_v in ch_tvls.items():
                                k_str = str(ch_k).strip()
                                k_low = k_str.lower()
                                if k_low in _NON_SPOT_TVL_KEYS or k_low.endswith(_NON_SPOT_TVL_SUFFIXES):
                                    continue
                                sub_c = _norm_chain(k_str)
                                if not sub_c or not (
                                    _usable_chain(sub_c)
                                    or sub_c in NON_EVM_CHAINS
                                    or any(kw in sub_c for kw in TESTNET_KWS)
                                ):
                                    continue
                                has_explicit_spot_tvls = True
                                sub_val_d = _extract_tvl_dec(ch_v)
                                if _usable_chain(sub_c) and sub_val_d > _DEC_ZERO:
                                    spot_evm_by_chain[sub_c] = spot_evm_by_chain.get(sub_c, _DEC_ZERO) + sub_val_d

                        raw_total_tvl_d = _extract_tvl_dec(p.get("tvl"))
                        raw_chains = p.get("chains")
                        fb_evm: List[str] = (
                            list(dict.fromkeys(nc for cx in raw_chains if _usable_chain(nc := _norm_chain(str(cx)))))
                            if isinstance(raw_chains, list)
                            else []
                        )
                        if not spot_evm_by_chain and not _usable_chain(c_norm):
                            if fb_evm:
                                c_norm = fb_evm[0]
                            elif has_explicit_contracts:
                                c_norm = "ethereum"
                        total_spot_evm_tvl_d = (
                            sum(spot_evm_by_chain.values(), _DEC_ZERO)
                            if spot_evm_by_chain
                            else (_DEC_ZERO if has_explicit_spot_tvls else (raw_total_tvl_d if _usable_chain(c_norm) else _DEC_ZERO))
                        )
                        if total_spot_evm_tvl_d < min_tvl_dec:
                            continue

                        gh_raw = p.get("github")
                        gh_list = [str(g).strip() for g in gh_raw if str(g).strip()] if isinstance(gh_raw, list) else ([str(gh_raw).strip()] if gh_raw else [])
                        p_meta = {
                            "url": str(p.get("url") or "").strip(),
                            "github": gh_list,
                            "module": str(p.get("module") or "").strip(),
                            "address": str(p.get("address") or "").strip(),
                        }
                        has_p_meta = any(p_meta.values())
                        if has_p_meta:
                            meta_items.append((slug, p_meta))

                        # 멀티체인 배포(spot_evm_by_chain) 중 스팟 TVL >= $100(MIN_PROFIT_USD) 체인 전수 큐 등록 (부속 체인 누락 차단)
                        addr_map_raw = p.get("addresses") if isinstance(p.get("addresses"), dict) else (
                            p.get("contracts") if isinstance(p.get("contracts"), dict) else {}
                        )
                        norm_addr_map: Dict[str, List[str]] = {}
                        for ak, av in addr_map_raw.items():
                            nak = _norm_chain(str(ak))
                            if not nak:
                                continue
                            if isinstance(av, str):
                                na = _norm_addr(av.split(":", 1)[-1])
                                if na:
                                    norm_addr_map.setdefault(nak, []).append(na)
                            elif isinstance(av, list):
                                for x in av:
                                    na = _norm_addr(str(x).split(":", 1)[-1])
                                    if na:
                                        norm_addr_map.setdefault(nak, []).append(na)

                        def _append_mode_a_subchain(sub_c: str, use_root_slug: bool, eff_tvl_d: Decimal) -> None:
                            sub_slug = slug if use_root_slug else _norm_slug(f"{slug}-{sub_c}")
                            sub_seeds = list(
                                dict.fromkeys(
                                    [*seed_list, *norm_addr_map.get(sub_c, [])]
                                    if (sub_c == c_norm and seed_list)
                                    else norm_addr_map.get(sub_c, [])
                                )
                            )
                            sub_prio, sub_rank_d = _compute_mode_a_roi_priority_and_rank(
                                eff_tvl_d,
                                sub_c,
                                listed_at=p.get("listedAt"),
                                audits_raw=p.get("audits"),
                                change_7d=p.get("change_7d"),
                                has_seed_addrs=bool(sub_seeds),
                            )
                            batch_items.append((sub_slug, sub_prio, sub_c, eff_tvl_d, sub_seeds, "A", "", sub_rank_d))
                            if sub_slug != slug and has_p_meta:
                                meta_items.append((sub_slug, dict(p_meta)))

                        eligible_evm_chains = [
                            (sc, st_d)
                            for sc, st_d in spot_evm_by_chain.items()
                            if _usable_chain(sc) and st_d >= PROFIT_FLOOR_DEC
                        ]
                        if eligible_evm_chains:
                            ordered_evm_chains: List[Tuple[str, Decimal]] = []
                            if _usable_chain(c_norm) and spot_evm_by_chain.get(c_norm, _DEC_ZERO) >= PROFIT_FLOOR_DEC:
                                ordered_evm_chains.append((c_norm, spot_evm_by_chain[c_norm]))
                            for sc, st_d in sorted(eligible_evm_chains, key=lambda x: (-x[1], x[0])):
                                if (sc != c_norm or not ordered_evm_chains) and all(prev_c != sc for prev_c, _ in ordered_evm_chains):
                                    ordered_evm_chains.append((sc, st_d))
                            for idx_c, (sub_c, sub_tvl_d) in enumerate(ordered_evm_chains):
                                use_root = idx_c == 0 and (sub_c == c_norm or c_norm not in spot_evm_by_chain)
                                eff_tvl_d = max(sub_tvl_d, total_spot_evm_tvl_d) if (idx_c == 0 and len(ordered_evm_chains) == 1) else sub_tvl_d
                                _append_mode_a_subchain(sub_c, use_root, eff_tvl_d)
                        elif _usable_chain(c_norm):
                            for idx_fb, sub_c in enumerate(dict.fromkeys([c_norm, *fb_evm])):
                                _append_mode_a_subchain(sub_c, idx_fb == 0, total_spot_evm_tvl_d)
                    except Exception:
                        continue
        except _RECOVERABLE_IO_EXC:
            pass

    any_mode_a_seeded = any(len(it) >= 6 and it[5] == "A" for it in batch_items)
    return batch_items, meta_items, any_mode_a_seeded


def _ensure_mode_a_seeded(store: SQLiteStore) -> int:
    """
    지연된 Mode A(DeFiLlama HTTP) 시드 적재를 전용 `mode_a_seed.lock` 단일-플라이트 락으로 직렬화해
    동시 세션의 중복 HTTP 페치를 차단하고, SQLite 배치 커밋 구간에만 `LOCK_FILE_PATH`를 짧게 점유한다.
    """
    if store.get_engine_meta("mode_a_seed_pending", "0") != "1":
        return 0
    if store._is_memory:
        seed_lock_ctx: Any = contextlib.nullcontext()
        q_lock_ctx: Any = contextlib.nullcontext()
    else:
        cdir_a = _store_cache_dir(store)
        seed_lock_ctx = _exclusive_file_lock(cdir_a / "mode_a_seed.lock")
        q_lock_path_a = (
            LOCK_FILE_PATH
            if cdir_a.resolve() == CACHE_DIR.resolve()
            else (cdir_a / "audit.lock")
        )
        q_lock_ctx = _exclusive_file_lock(q_lock_path_a)
    with seed_lock_ctx:
        if store.get_engine_meta("mode_a_seed_pending", "0") != "1":
            return 0
        a_items, a_meta, any_mode_a = _collect_mode_a_seed_items()
        with q_lock_ctx:
            if store.get_engine_meta("mode_a_seed_pending", "0") != "1":
                return 0
            if a_meta:
                store.put_proto_meta_batch(a_meta)
            inserted = store.upsert_queue_items_batch(a_items) if a_items else 0
            if a_items:
                _sync_sealed_receipts_for_batch(store, a_items)
            if any_mode_a:
                store.put_engine_meta("mode_a_seed_ok", "1")
                store.put_engine_meta("mode_a_seed_pending", "0")
            else:
                store.put_engine_meta("mode_a_seed_ok", "0")
                # Keep mode_a_seed_pending="1" so transient HTTP failures retry on the next run instead of permanently dropping Mode A.
            return inserted


_MODEB_ADDR12_SLUG_RE: re.Pattern[str] = re.compile(r"^modeb-([a-z0-9]+)-(\d+)-([0-9a-f]{12})$")
_MODEB_CLONE_SLUG_RE: re.Pattern[str] = re.compile(r"^modeb-clone-[a-z0-9]+-(\d+)-([0-9a-f]{12})-[0-9a-f]+$")
_MODEB_ZERO_SEED_SLUG_RE: re.Pattern[str] = re.compile(r"^modeb-([a-z0-9]+)-(\d+)-(.+)$")


def _build_and_seal_mode_b_corpus(store: SQLiteStore) -> Tuple[List[Tuple[Any, ...]], List[Tuple[str, Dict[str, Any]]]]:
    """
    컨트랙트.md 역사적 사례 전수 파싱, 0-시드 EVM 사례 큐잉 데이터 생성 및 corpus_md_partition_seal 무손실 봉인:
    - 기존 봉인(`corpus_md_partition_seal`) 및 `audit_queue(mode='B')`를 함께 참조해, 중간 삽입으로 인덱스가 이동했거나
      동일 프록시 주소를 공유하는 다회 사고(예: 1차·2차 별개 패싯)도 `(chain, addr12)` FIFO 매칭으로 기존 원천 슬러그와
      누적 파생 클론 슬러그 전량을 무손실 승계하여 중복 큐잉·진행 소실을 방지한다.
    """
    batch_items: List[Tuple[Any, ...]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []
    c_part = _parse_corpus_md_partition()
    evm_cases: List[HistoricalCaseSeed] = list(c_part.get("evm_cases") or [])
    pure_non_evm_cases: List[HistoricalCaseSeed] = list(c_part.get("pure_non_evm_cases") or [])
    total_headers = int(c_part.get("total_headers") or 0)
    store.put_engine_meta("corpus_md_total_headers", str(total_headers))
    store.put_engine_meta("corpus_md_evm_cases", str(len(evm_cases)))
    store.put_engine_meta("corpus_md_pure_non_evm_cases", str(len(pure_non_evm_cases)))

    # Preserve ALL existing primary slugs (FIFO per (chain, addr12)) & ALL accumulated derived clone slugs
    prev_primaries_by_ak: Dict[Tuple[str, str], List[Tuple[int, str]]] = {}
    prev_zero_by_ct: Dict[Tuple[str, str], List[Tuple[int, str]]] = {}
    prev_group_by_primary: Dict[str, List[str]] = {}
    prev_clones_by_idx_addr12: Dict[Tuple[str, str], List[str]] = {}
    prev_all_slugs: Set[str] = set()

    def _register_prev_primary(ps_item: str, group_items: Sequence[str] = ()) -> None:
        ps_norm = _norm_slug(ps_item)
        if not ps_norm:
            return
        prev_all_slugs.add(ps_norm)
        m_ak = _MODEB_ADDR12_SLUG_RE.match(ps_norm)
        if m_ak:
            ak_p = (m_ak.group(1), m_ak.group(3))
            idx_i = int(m_ak.group(2))
            lst_ak = prev_primaries_by_ak.setdefault(ak_p, [])
            if all(existing_s != ps_norm for _, existing_s in lst_ak):
                lst_ak.append((idx_i, ps_norm))
        else:
            m_cl = _MODEB_CLONE_SLUG_RE.match(ps_norm)
            if m_cl:
                cl_k = (m_cl.group(1), m_cl.group(2))
                cl_l = prev_clones_by_idx_addr12.setdefault(cl_k, [])
                if ps_norm not in cl_l:
                    cl_l.append(ps_norm)
                return
            m_zs = _MODEB_ZERO_SEED_SLUG_RE.match(ps_norm)
            if m_zs and not re.search(r"-\d+$", ps_norm):
                ct_p = (m_zs.group(1), m_zs.group(3))
                idx_z = int(m_zs.group(2))
                lst_z = prev_zero_by_ct.setdefault(ct_p, [])
                if all(existing_s != ps_norm for _, existing_s in lst_z):
                    lst_z.append((idx_z, ps_norm))
        if group_items:
            grp = prev_group_by_primary.setdefault(ps_norm, [])
            for g_s in group_items:
                gn = _norm_slug(g_s)
                if gn and gn not in grp:
                    grp.append(gn)

    raw_prev_seal = store.get_engine_meta("corpus_md_partition_seal", "")
    if raw_prev_seal:
        try:
            prev_seal_doc = json.loads(raw_prev_seal)
            prev_evm_map = prev_seal_doc.get("evm_case_slug_map") if isinstance(prev_seal_doc, dict) else None
            if isinstance(prev_evm_map, dict):
                for _pk, p_list in prev_evm_map.items():
                    if not isinstance(p_list, list):
                        continue
                    clean_pl = list(dict.fromkeys(_norm_slug(str(x)) for x in p_list if _norm_slug(str(x))))
                    if not clean_pl:
                        continue
                    prev_all_slugs.update(clean_pl)
                    for ps_item in clean_pl:
                        _register_prev_primary(ps_item, clean_pl)
        except _PARSE_DATA_EXC:
            pass

    # Also recover any existing Mode B primary/clone slugs directly from audit_queue (self-healing if prior seal lost a repeat case)
    try:
        with store._read_conn() as rc_mb:
            q_modeb_rows = rc_mb.execute("SELECT slug FROM audit_queue WHERE mode='B'").fetchall()
        for qr in q_modeb_rows:
            _register_prev_primary(str(qr["slug"] or ""))
    except _RECOVERABLE_IO_EXC:
        pass

    for ak_k in prev_primaries_by_ak:
        prev_primaries_by_ak[ak_k].sort(key=lambda t: t[0])
    for ct_k in prev_zero_by_ct:
        prev_zero_by_ct[ct_k].sort(key=lambda t: t[0])

    consumed_prev_primaries: Set[str] = set()

    def _collect_saved_group(primary_slug: str) -> List[str]:
        out_g: List[str] = list(prev_group_by_primary.get(primary_slug, ()))
        m_p = _MODEB_ADDR12_SLUG_RE.match(primary_slug)
        if m_p:
            for cl_s in prev_clones_by_idx_addr12.get((m_p.group(2), m_p.group(3)), ()):
                if cl_s not in out_g:
                    out_g.append(cl_s)
        return out_g

    seen_modeb_chain_addrs: Set[Tuple[str, Tuple[str, ...]]] = set()
    sig_to_primary_slug: Dict[Tuple[str, Tuple[str, ...]], str] = {}
    evm_case_slug_map: Dict[str, List[str]] = {}
    for idx, hc in enumerate(evm_cases):
        seeded_any = False
        case_slugs: List[str] = []
        default_hc_chain = hc.chains[0] if (hc.chains and hc.chains[0] in CHAIN_IDS) else "ethereum"
        case_candidates: List[Tuple[str, List[str]]] = []
        for ch_name, addr_list in hc.seed_addresses.items():
            c_norm = _norm_chain(ch_name)
            if c_norm not in CHAIN_IDS:
                c_norm = default_hc_chain
            addrs = list(dict.fromkeys(nx for x in addr_list if (nx := _norm_addr(x))))
            if not addrs:
                continue
            case_candidates.append((c_norm, addrs))
        for c_idx, (c_norm, addrs) in enumerate(case_candidates):
            sig_key = (c_norm, tuple(addrs))
            if sig_key in seen_modeb_chain_addrs and (seeded_any or c_idx < len(case_candidates) - 1):
                if sig_key in sig_to_primary_slug:
                    p_reuse = sig_to_primary_slug[sig_key]
                    case_slugs.append(p_reuse)
                    case_slugs.extend(_collect_saved_group(p_reuse))
                continue
            if sig_key in sig_to_primary_slug:
                seeded_any = True
                p_reuse = sig_to_primary_slug[sig_key]
                case_slugs.append(p_reuse)
                case_slugs.extend(_collect_saved_group(p_reuse))
                continue
            seen_modeb_chain_addrs.add(sig_key)
            seeded_any = True
            addr12 = f"{addrs[0][2:8]}{addrs[0][-6:]}"
            reused_slug = ""
            for _old_idx, cand_prev in prev_primaries_by_ak.get((c_norm, addr12), ()):
                if cand_prev not in consumed_prev_primaries:
                    reused_slug = cand_prev
                    consumed_prev_primaries.add(cand_prev)
                    break
            if reused_slug:
                h_slug = reused_slug
            else:
                h_slug = _norm_slug(f"modeb-{c_norm}-{idx:03d}-{addr12}")
                if h_slug in prev_all_slugs:
                    h_slug = _norm_slug(f"modeb-{c_norm}-{idx:03d}-{addr12}-n")
                prev_all_slugs.add(h_slug)
            sig_to_primary_slug[sig_key] = h_slug
            case_slugs.append(h_slug)
            if reused_slug:
                case_slugs.extend(_collect_saved_group(reused_slug))
            s_rank_d = Decimal("1500000") + Decimal(len(addrs) * 1000 + max(0, 500 - idx))
            clean_prin = _neutralize_agent_prose(hc.principle_summary)
            batch_items.append((h_slug, 3, c_norm, _to_dec(MIN_TVL_USD), addrs, "B", clean_prin, s_rank_d))
            if hc.title or hc.tx_hashes or hc.block_numbers or hc.key_identifiers:
                s_meta: Dict[str, Any] = {}
                if hc.title:
                    s_meta["title"] = hc.title
                if hc.tx_hashes:
                    s_meta["tx_hashes"] = list(hc.tx_hashes)
                if hc.block_numbers:
                    s_meta["block_numbers"] = list(hc.block_numbers)
                if hc.key_identifiers:
                    s_meta["key_identifiers"] = list(hc.key_identifiers[:16])
                meta_items.append((h_slug, s_meta))
        if not seeded_any:
            c_norm = default_hc_chain
            title_slug = _norm_slug(hc.title)[:24] or f"case-{idx:03d}"
            reused_z = ""
            for _old_z_idx, cand_z in prev_zero_by_ct.get((c_norm, title_slug), ()):
                if cand_z not in consumed_prev_primaries:
                    reused_z = cand_z
                    consumed_prev_primaries.add(cand_z)
                    break
            h_slug = reused_z if reused_z else _norm_slug(f"modeb-{c_norm}-{idx:03d}-{title_slug}")
            case_slugs.append(h_slug)
            if reused_z:
                case_slugs.extend(_collect_saved_group(reused_z))
            s_rank_d = Decimal("1400000") + Decimal((100 if hc.tx_hashes else 0) + max(0, 500 - idx))
            clean_prin = _neutralize_agent_prose(hc.principle_summary)
            batch_items.append((h_slug, 3, c_norm, _to_dec(MIN_TVL_USD), [], "B", clean_prin, s_rank_d))
            z_meta: Dict[str, Any] = {"title": hc.title, "mode_b_zero_seed": True}
            if hc.tx_hashes:
                z_meta["tx_hashes"] = list(hc.tx_hashes)
            if hc.block_numbers:
                z_meta["block_numbers"] = list(hc.block_numbers)
            if hc.key_identifiers:
                z_meta["key_identifiers"] = list(hc.key_identifiers[:16])
            meta_items.append((h_slug, z_meta))
        evm_case_slug_map[str(idx)] = list(dict.fromkeys(case_slugs))

    pure_non_evm_evidence = [{"case_idx": i, "chains": list(nc.chains)} for i, nc in enumerate(pure_non_evm_cases)]
    corpus_sha = str(
        c_part.get("corpus_sha256")
        or (_sha256_file(INCIDENT_CORPUS_PATH) if INCIDENT_CORPUS_PATH.is_file() else "")
    )
    store.put_engine_meta(
        "corpus_md_partition_seal",
        json.dumps(
            {
                "corpus_sha256": corpus_sha,
                "evm_case_slug_map": evm_case_slug_map,
                "pure_non_evm_evidence": pure_non_evm_evidence,
            },
            ensure_ascii=False,
        ),
    )
    return batch_items, meta_items


def _sync_mode_b_corpus_if_drifted(store: SQLiteStore) -> int:
    """
    기존 큐가 이미 존재하더라도 `컨트랙트.md`의 SHA-256이 변경(사건 추가·표현 중립화)되었으면
    누적 클론 매핑·기완료 상태를 100% 보존하면서 `corpus_md_partition_seal` 갱신, 신규 사건 적재,
    `audit_queue.principle_summary` 중립화 동기화를 원자적으로 수행한다.
    """
    if not INCIDENT_CORPUS_PATH.is_file():
        return 0
    live_sha = _sha256_file(INCIDENT_CORPUS_PATH)
    raw_seal = store.get_engine_meta("corpus_md_partition_seal", "")
    sealed_sha = ""
    if raw_seal:
        try:
            s_doc = json.loads(raw_seal)
            if isinstance(s_doc, dict):
                sealed_sha = str(s_doc.get("corpus_sha256") or "")
        except Exception:
            sealed_sha = ""
    if sealed_sha and sealed_sha == live_sha:
        return 0
    b_items, b_meta = _build_and_seal_mode_b_corpus(store)
    inserted = _persist_queue_and_meta_batch(store, b_items, b_meta)
    # Neutralize any remaining historical non-neutral principle_summary rows (including cloned Mode B rows)
    with store._read_conn() as rc_ps:
        rows_ps = rc_ps.execute(
            "SELECT slug, principle_summary FROM audit_queue WHERE principle_summary != ''"
        ).fetchall()
    upd_ps: List[Tuple[str, str]] = []
    for r_ps in rows_ps:
        orig_ps = str(r_ps["principle_summary"] or "")
        clean_ps = _neutralize_agent_prose(orig_ps)
        if clean_ps != orig_ps:
            upd_ps.append((clean_ps, str(r_ps["slug"])))
    if upd_ps:
        with store._write_tx() as wc_ps:
            wc_ps.executemany(
                "UPDATE audit_queue SET principle_summary=? WHERE slug=?",
                upd_ps,
            )
    return inserted


def _append_case_clone_slugs_to_partition_seal(
    store: Optional[SQLiteStore],
    parent_slug: str,
    clone_slugs: Sequence[str],
) -> None:
    """Mode B 원천 사건(`parent_slug`)에서 파생된 타 체인 생존 클론 슬러그를 `corpus_md_partition_seal`의 사건 매핑에 추가 봉인한다."""
    if store is None or not clone_slugs:
        return
    p_norm = _norm_slug(parent_slug)
    clean_clones = list(dict.fromkeys(ns for raw_c in clone_slugs if (ns := _norm_slug(str(raw_c)))))
    if not p_norm or not clean_clones:
        return
    raw_seal = store.get_engine_meta("corpus_md_partition_seal", "")
    if not raw_seal:
        return
    try:
        seal_doc = json.loads(raw_seal)
        evm_map = seal_doc.get("evm_case_slug_map") if isinstance(seal_doc, dict) else None
        if not isinstance(evm_map, dict):
            return
        changed = False
        for c_idx, c_list in evm_map.items():
            if not isinstance(c_list, list):
                continue
            norm_list = [_norm_slug(str(x)) for x in c_list if _norm_slug(str(x))]
            if p_norm in norm_list:
                merged_list = list(dict.fromkeys([*norm_list, *clean_clones]))
                if merged_list != norm_list:
                    evm_map[c_idx] = merged_list
                    changed = True
        if changed:
            store.put_engine_meta("corpus_md_partition_seal", json.dumps(seal_doc, ensure_ascii=False))
    except _RECOVERABLE_IO_EXC:
        pass


def _seed_queue_from_existing_or_live(store: SQLiteStore, defer_mode_a: bool = False) -> int:
    """Mode B(Priority 1: 컨트랙트.md 전 사건 헤더 무손실 분할 및 유사 컨트랙트 탐색 최우선) 및 Mode A(Priority 2: 지연 적재 지원) 일괄 큐 적재."""
    counts = store.queue_counts()
    if sum(counts.values()) > 0:
        _sync_mode_b_corpus_if_drifted(store)
        return sum(store.queue_counts().values())

    batch_items: List[Tuple[Any, ...]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []

    if defer_mode_a:
        store.put_engine_meta("mode_a_seed_pending", "1")
    else:
        a_items, a_meta, any_mode_a_seeded = _collect_mode_a_seed_items()
        batch_items.extend(a_items)
        meta_items.extend(a_meta)
        store.put_engine_meta("mode_a_seed_ok", "1" if any_mode_a_seeded else "0")
        store.put_engine_meta("mode_a_seed_pending", "0")

    b_items, b_meta = _build_and_seal_mode_b_corpus(store)
    batch_items.extend(b_items)
    meta_items.extend(b_meta)

    return _persist_queue_and_meta_batch(store, batch_items, meta_items)


_GITBOOK_URL_RE: re.Pattern[str] = re.compile(r"https?://[a-zA-Z0-9_.-]+\.gitbook\.io(?:/[^\s\"'<>)]*)?", re.IGNORECASE)
_GITHUB_REPO_RE: re.Pattern[str] = re.compile(r"https?://github\.com/([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)", re.IGNORECASE)
_DOCS_LINK_RE: re.Pattern[str] = re.compile(
    r"https?://(?:docs\.[a-zA-Z0-9_.-]+|[a-zA-Z0-9_.-]+/(?:docs|contracts|deployments))(?:/[^\s\"'<>)]*)?",
    re.IGNORECASE,
)


_SOLC_RUNTIME_HEX_RE: re.Pattern[str] = re.compile(
    r"Binary of the runtime part:[ \t]*\r?\n([0-9a-fA-F]{32,})",
    re.MULTILINE,
)


def _extract_or_compile_recovered_mode_b_bytecodes(
    disc_doc: Optional[Mapping[str, Any]],
    pdir: Path,
) -> List[bytes]:
    """
    에이전트가 Web Search + Web Fetch(GitHub·사후분석·익스플로러)로 확보해 `discovered_addresses.json`에 제출한
    `recovered_bytecode_hex` 또는 `recovered_solidity_source`를 기계적으로 검증·오프라인 컴파일(`SOLC_BIN`)하여
    유효 런타임 바이트코드(`>= 16B`) 목록으로 반환한다(비실증 불리언 주장 단독 신뢰 금지).
    """
    if not isinstance(disc_doc, Mapping):
        return []
    out_bcs: List[bytes] = []
    seen_bcs: Set[bytes] = set()
    raw_hex_field = disc_doc.get("recovered_bytecode_hex")
    hex_items = raw_hex_field if isinstance(raw_hex_field, list) else ([raw_hex_field] if raw_hex_field else [])
    for hx in hex_items:
        if isinstance(hx, str) and hx.strip():
            rb = _hex_to_bytes(hx.strip())
            if len(rb) >= 16:
                _append_unique(out_bcs, seen_bcs, rb)
    raw_sol_field = disc_doc.get("recovered_solidity_source")
    if not out_bcs and raw_sol_field and SOLC_BIN.is_file():
        sol_map: Dict[str, str] = {}
        if isinstance(raw_sol_field, str) and raw_sol_field.strip():
            sol_map["Recovered.sol"] = raw_sol_field
        elif isinstance(raw_sol_field, Mapping):
            for k_fn, v_sc in raw_sol_field.items():
                raw_rel = str(k_fn).replace("\\", "/").strip("/")
                parts_rel = [pt for pt in raw_rel.split("/") if pt and pt != "."]
                if (
                    parts_rel
                    and ".." not in parts_rel
                    and not Path(raw_rel).is_absolute()
                    and parts_rel[-1].endswith(".sol")
                    and isinstance(v_sc, str)
                    and v_sc.strip()
                ):
                    sol_map["/".join(parts_rel)] = v_sc
        if sol_map:
            solc_dir = pdir / "_solc_recover"
            try:
                shutil.rmtree(solc_dir, ignore_errors=True)
                solc_dir.mkdir(parents=True, exist_ok=True)
                sol_paths: List[str] = []
                solc_base = solc_dir.resolve()
                for fn_s, sc_s in list(sol_map.items())[:12]:
                    sp = (solc_dir / fn_s).resolve()
                    if not sp.is_relative_to(solc_base):
                        continue
                    sp.parent.mkdir(parents=True, exist_ok=True)
                    sp.write_text(sc_s, encoding="utf-8")
                    sol_paths.append(fn_s)
                if sol_paths:
                    cp_s = _run_subproc_tree_safe(
                        [str(SOLC_BIN), "--optimize", "--bin-runtime", *sol_paths],
                        cwd=str(solc_dir),
                        env=_isolated_subproc_env(solc_dir),
                        timeout_sec=20.0,
                        decode_text=True,
                    )
                    out_s = str(cp_s.stdout or "")
                    if cp_s.returncode == 0 and out_s:
                        for m_rt in _SOLC_RUNTIME_HEX_RE.finditer(out_s):
                            rb_c = _hex_to_bytes(m_rt.group(1))
                            if len(rb_c) >= 16:
                                _append_unique(out_bcs, seen_bcs, rb_c)
            except _RECOVERABLE_IO_EXC:
                pass
            finally:
                shutil.rmtree(solc_dir, ignore_errors=True)
    return out_bcs


def _collect_local_skeleton_hits(
    store: SQLiteStore,
    bytecodes: Sequence[bytes],
    *,
    chain_id: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """로컬 SQLite contract_code 인덱스에서 골격 해시·4-gram 유사 후보를 일괄 수집하고 비정확 4-gram은 멀티그램 검증."""
    hits: List[Dict[str, Any]] = []
    for s_idx, rb in enumerate(bytecodes):
        sk = _skeleton_hash(rb)
        fg = _opcode_4grams(rb, cap=128)
        for sm in store.find_by_skeleton_or_grams(sk, fg, chain_id=chain_id):
            m_cid = int(sm.get("chain_id") or 0)
            m_ch = CHAIN_BY_ID.get(m_cid, "")
            if not m_ch:
                continue
            mt = str(sm.get("match_type") or "skeleton")
            sim_v = _to_dec(sm.get("similarity") or Decimal("0.85"))
            if mt != "skeleton":
                cand_b = _hex_to_bytes(str(sm.get("raw_code_hex") or ""))
                if len(cand_b) < 16:
                    continue
                mg_sc = compute_multigram_containment(rb, cand_b)
                if mg_sc < max(CONTAINMENT_MIN, Decimal("0.35")):
                    continue
                sim_v = _to_dec(mg_sc).quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN)
            hits.append(
                {
                    "chain_id": m_cid,
                    "chain": m_ch,
                    "address": sm.get("address", ""),
                    "match_type": mt,
                    "similarity": sim_v,
                    "seed_index": s_idx,
                }
            )
    return hits


def _collect_proxy_impl_hits(
    store: SQLiteStore,
    impl_addrs: Sequence[str],
    *,
    chain_id: Optional[int] = None,
    proxy_limit: Optional[int] = 64,
    include_seed_index: bool = False,
    parquet_impl_cap: int = 24,
) -> Tuple[List[Dict[str, Any]], bool]:
    """SQLite 및 Sourcify V2 Parquet에서 구현체 주소를 위임 참조하는 프록시·클론 후보 수집."""
    hits: List[Dict[str, Any]] = []
    for p_row in store.find_proxies_by_impl(impl_addrs, chain_id=chain_id):
        p_cid = int(p_row.get("chain_id") or 0)
        p_ch = CHAIN_BY_ID.get(p_cid, "")
        if p_ch and p_row.get("address"):
            item: Dict[str, Any] = {
                "chain_id": p_cid,
                "chain": p_ch,
                "address": p_row["address"],
                "match_type": "proxy_impl",
                "similarity": Decimal("0.95"),
            }
            if include_seed_index:
                item["seed_index"] = 0
            hits.append(item)
    parquet_ok = True
    pq_impls = list(impl_addrs)[: max(1, int(parquet_impl_cap))] if parquet_impl_cap > 0 else list(impl_addrs)
    try:
        for p_row in search_sourcify_v2_proxies_for_impls(pq_impls, chain_id=chain_id, limit=proxy_limit):
            if isinstance(p_row, dict):
                p_item = dict(p_row)
                p_item.setdefault("match_type", "proxy_impl")
                hits.append(p_item)
    except Exception:
        parquet_ok = False
    return hits, parquet_ok


def _sweep_recovered_mode_b_bytecodes(
    router: RPCRouter,
    store: SQLiteStore,
    slug: str,
    chain: str,
    block_pin: int,
    recovered_bcs: Sequence[bytes],
    principle_summary: str,
) -> Tuple[List[str], List[str], bool]:
    """
    원천 바이트코드 전량 확보 건(`recovered_bcs`)에 대해 로컬 Sourcify V2 Parquet + SQLite 골격/멀티그램 + 프록시 인덱스를
    전 생존 EVM 체인 대상으로 스윕하여 `(same_chain_live_addrs, enqueued_clone_slugs, sweep_complete)`를 반환한다.
    """
    cid_target = CHAIN_IDS.get(chain, 1)
    infra_target = _infra_addresses_for_chain(chain)
    sim_hits: List[Dict[str, Any]] = []
    has_corpus = _has_sourcify_corpus_files(SOURCIFY_PARQUET_DIR)
    sweep_complete = True
    rec_meta = (store.get_proto_meta(slug) or {}) if store is not None else {}
    rec_key_ids = [str(x) for x in (rec_meta.get("key_identifiers") or ()) if str(x)]
    try:
        for sc_it in search_sourcify_v2_similar_contracts(
            list(recovered_bcs),
            chain_id=None,
            limit=None,
            allow_bulk_parquet_scan=True,
            key_identifiers=rec_key_ids,
        ):
            if isinstance(sc_it, dict):
                sim_hits.append(sc_it)
    except Exception:
        sweep_complete = False
    try:
        sim_hits.extend(_collect_local_skeleton_hits(store, recovered_bcs, chain_id=None))
    except Exception:
        sweep_complete = False

    if not has_corpus and not sim_hits:
        try:
            with store._read_conn() as rc_idx:
                idx_cnt_row = rc_idx.execute("SELECT COUNT(*) FROM contract_code").fetchone()
                if not idx_cnt_row or int(idx_cnt_row[0] or 0) <= 0:
                    sweep_complete = False
        except Exception:
            sweep_complete = False

    matched_impls = list(
        dict.fromkeys(na for h in sim_hits if (na := _norm_addr(str(h.get("address") or ""))))
    )
    if matched_impls:
        try:
            p_hits, p_ok = _collect_proxy_impl_hits(
                store, matched_impls, chain_id=None, proxy_limit=64, include_seed_index=False
            )
            sim_hits.extend(p_hits)
            if not p_ok:
                sweep_complete = False
        except Exception:
            sweep_complete = False

    same_chain_cands: List[str] = []
    seen_same: Set[str] = set()
    cc_by_chain: Dict[str, List[str]] = {}
    seen_cc: Dict[str, Set[str]] = {}
    for h in sim_hits:
        m_cid = int(h.get("chain_id") or 0)
        m_ch = _norm_chain(str(h.get("chain") or CHAIN_BY_ID.get(m_cid, "")))
        m_ad = _norm_addr(str(h.get("address") or ""))
        if not m_ad or not _usable_chain(m_ch):
            continue
        if m_cid == cid_target or m_ch == chain:
            if m_ad not in infra_target:
                _append_unique(same_chain_cands, seen_same, m_ad)
        elif m_ad not in _infra_addresses_for_chain(m_ch):
            _append_unique(cc_by_chain.setdefault(m_ch, []), seen_cc.setdefault(m_ch, set()), m_ad)

    same_live, same_rpc_ok = (
        _filter_onchain_contract_addrs(router, chain, same_chain_cands, block_pin)
        if (same_chain_cands and block_pin > 0)
        else (same_chain_cands, True)
    )
    if same_chain_cands and block_pin > 0 and not same_rpc_ok:
        sweep_complete = False

    enq_clone_slugs: List[str] = []
    if cc_by_chain:
        rec_probe_pairs: List[Tuple[str, str]] = [
            (_norm_chain(c_ch), _norm_addr(a))
            for c_ch, c_addrs in cc_by_chain.items()
            for a in c_addrs[:8]
            if _norm_chain(c_ch) and _norm_addr(a)
        ]
        rec_bal_hints = (
            _probe_clone_liquid_balance_hints(router, rec_probe_pairs)
            if (router is not None and rec_probe_pairs)
            else {}
        )
        cc_sorted_items = sorted(cc_by_chain.items())
        def _filter_cc_chain(item_cc: Tuple[str, List[str]]) -> Tuple[str, List[str], List[str], bool]:
            c_ch_i, c_addrs_i = item_cc
            live_i, ok_i = (
                _filter_onchain_contract_addrs(router, c_ch_i, c_addrs_i[:16], 0, use_latest=True)
                if _is_live_real_router(router)
                else (c_addrs_i[:16], True)
            )
            return c_ch_i, c_addrs_i, live_i, ok_i

        cc_filtered_rows = _parallel_map_list(
            _filter_cc_chain,
            cc_sorted_items,
            max_workers=8,
            parallel=(_is_live_real_router(router) and len(cc_sorted_items) > 1),
        )
        clone_batch: List[Tuple[str, int, str, Decimal, Sequence[str], str, str, Decimal]] = []
        clone_meta: List[Tuple[str, Dict[str, Any]]] = []
        for c_ch, c_addrs, live_cc, cc_rpc_ok in cc_filtered_rows:
            if not cc_rpc_ok:
                sweep_complete = False
            eff_cc = live_cc if cc_rpc_ok else c_addrs[:16]
            if not eff_cc:
                continue
            c_ch_n = _norm_chain(c_ch)
            rec_fund_d = sum(
                (_to_dec(rec_bal_hints.get((c_ch_n, _norm_addr(a)), 0)) for a in eff_cc[:8]),
                _DEC_ZERO,
            )
            c_slug = _norm_slug(f"modeb-clone-{c_ch}-{slug[-16:]}-{eff_cc[0][2:8]}{eff_cc[0][-6:]}")
            rec_base_rank_d = Decimal("2000000") if rec_fund_d >= PROFIT_FLOOR_DEC else Decimal("1001000")
            c_rank_d = rec_base_rank_d + (Decimal(len(eff_cc)) * Decimal("10")) + _clone_fund_rank_boost(rec_fund_d)
            enq_clone_slugs.append(c_slug)
            clone_batch.append((c_slug, 1, c_ch, _to_dec(MIN_TVL_USD), eff_cc, "B", principle_summary, c_rank_d))
            rec_c_meta: Dict[str, Any] = {
                "mode_b_source_slug": slug,
                "mode_b_source_chain": chain,
                "mode_b_similarity": "0.9500",
                "matched_from": "recovered_source_clone",
            }
            if rec_fund_d > _DEC_ZERO:
                rec_c_meta["mode_b_hint_usd"] = rec_fund_d.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
            clone_meta.append((c_slug, rec_c_meta))
        if clone_batch:
            _persist_queue_and_meta_batch(store, clone_batch, clone_meta)
    return same_live, enq_clone_slugs, sweep_complete


def _extract_agent_discovered_addresses(disc_path: Path) -> Tuple[List[str], bool]:
    """
    에이전트가 웹 검색(Web Search) 및 웹 열람(Web Fetch) 도구로 수집·교차 검증하여 기록한
    `audit_artifacts/<slug>/discovered_addresses.json`에서 우선순위 순서대로 주소를 추출.
    반환값: (ordered_addresses, confirmed_no_onchain_contracts)
    """
    if not disc_path.is_file():
        return [], False
    doc = _read_json(disc_path, default=None)
    if doc is None:
        return [], False
    ordered: List[str] = []
    seen_ordered: Set[str] = set()

    def _add_raw_addrs(items: Sequence[Any]) -> None:
        for x in items:
            na = _norm_addr(str(x))
            if na and int(na, 16) > 0:
                _append_unique(ordered, seen_ordered, na)

    if isinstance(doc, list):
        _add_raw_addrs(doc)
        return ordered, (len(ordered) == 0)
    if isinstance(doc, dict):
        if (
            bool(doc.get("no_onchain_contracts", False))
            or bool(doc.get("confirmed_no_contracts", False))
            or bool(doc.get("pure_offchain_proven", False))
            or bool(doc.get("pure_non_evm_proven", False))
            or bool(doc.get("unrecoverable_blocked", False))
        ):
            return [], True
        for stage_key in (
            "official_docs",
            "docs",
            "gitbook",
            "github",
            "defillama_adapter",
            "defillama",
            "explorer",
            "incident_records",
            "addresses",
            "contracts",
        ):
            val = doc.get(stage_key)
            if isinstance(val, list):
                _add_raw_addrs(val)
            elif isinstance(val, str):
                for na in _extract_addresses_from_text(val):
                    if int(na, 16) > 0:
                        _append_unique(ordered, seen_ordered, na)
        return ordered, False
    return [], False


def _filter_onchain_contract_addrs(
    router: Optional[RPCRouter],
    chain: str,
    addrs: Sequence[str],
    block_pin: int,
    *,
    allow_historical_mode_b: bool = False,
    hint_blocks: Optional[Sequence[int]] = None,
    use_latest: bool = False,
) -> Tuple[List[str], bool]:
    """
    `block_pin > 0`(또는 `use_latest=True`)일 때 `eth_getCode` 배치 조회로 실제 컨트랙트 바이트코드가 존재하는 주소만 선별 반환한다.
    `allow_historical_mode_b=True`이면 현재 블록 코드가 `0x`인 자기소멸(SELFDESTRUCT) 대상 컨트랙트도
    과거 블록 아카이브 바이트코드 이력이 실증되면 보존한다(순수 EOA는 배제).
    """
    c = _norm_chain(chain)
    clean_addrs: List[str] = []
    seen_c: Set[str] = set()
    for raw_a in addrs:
        na = _norm_addr(str(raw_a))
        if na and _is_non_precompile_addr(na) and na not in seen_c:
            seen_c.add(na)
            clean_addrs.append(na)
    if not clean_addrs or (int(block_pin) <= 0 and not use_latest) or router is None:
        return clean_addrs, False
    btag = "latest" if use_latest else hex(int(block_pin))
    eff_bp = 0 if use_latest else int(block_pin)
    try:
        ca_chunks = [clean_addrs[off_ca : off_ca + 64] for off_ca in range(0, len(clean_addrs), 64)]

        def _fetch_code_chunk(chunk_ca: List[str]) -> Tuple[List[str], List[Any], bool]:
            res_ca = router.batch_call(
                c,
                [("eth_getCode", [_checksum(a), btag]) for a in chunk_ca],
                block_pin=eff_bp,
                need_archive=(not use_latest),
                raise_on_all_failed=True,
            )
            c_err = bool(
                len(res_ca) < len(chunk_ca)
                or (isinstance(router, RPCRouter) and router.last_batch_transport_failures() > 0)
                or any(not isinstance(x_c, str) or not x_c.startswith("0x") for x_c in res_ca)
            )
            return chunk_ca, res_ca, c_err

        had_partial_err = False
        verified_onchain: List[str] = []
        for chunk_ca, part_ca, c_err in _map_chunks_live(router, _fetch_code_chunk, ca_chunks, max_workers=8):
            if c_err:
                had_partial_err = True
            for idx_ca, a in enumerate(chunk_ca):
                rhex = part_ca[idx_ca] if idx_ca < len(part_ca) else None
                if not isinstance(rhex, str) or not rhex.startswith("0x"):
                    had_partial_err = True
                    verified_onchain.append(a)
                elif len(rhex) > 2:
                    verified_onchain.append(a)
                elif allow_historical_mode_b:
                    hist_cb = _recover_historical_bytecode_bisect(
                        router, c, a, int(block_pin), hint_blocks=hint_blocks
                    )
                    if len(hist_cb) >= 16:
                        verified_onchain.append(a)
        return verified_onchain, (not had_partial_err)
    except Exception:
        return clean_addrs, False


def _extract_mechanical_meta_addresses(
    meta: Mapping[str, Any],
    chain: str,
    is_root_slug: bool,
) -> List[str]:
    c = _norm_chain(chain)
    out: List[str] = []
    seen: Set[str] = set()
    raw_single = str(meta.get("address") or "").strip()
    if raw_single:
        if ":" in raw_single:
            ch_part, ad_part = raw_single.split(":", 1)
            if _norm_chain(ch_part) == c:
                na = _norm_addr(ad_part)
                if na and _is_non_precompile_addr(na):
                    _append_unique(out, seen, na)
        elif is_root_slug:
            na = _norm_addr(raw_single)
            if na and _is_non_precompile_addr(na):
                _append_unique(out, seen, na)
    for map_key in ("addresses", "contracts"):
        raw_map = meta.get(map_key)
        if not isinstance(raw_map, dict):
            continue
        for mk, mv in raw_map.items():
            if _norm_chain(str(mk)) != c:
                continue
            vals = mv if isinstance(mv, list) else [mv]
            for item_v in vals:
                na = _norm_addr(str(item_v).split(":", 1)[-1])
                if na and _is_non_precompile_addr(na):
                    _append_unique(out, seen, na)
    return out


_MODE_A_SOURCIFY_STOPWORDS: FrozenSet[str] = frozenset(
    {
        "protocol", "finance", "defi", "network", "labs", "dao", "swap", "vault", "vaults",
        "pool", "pools", "token", "chain", "bridge", "staking", "yield", "lending", "market",
        "exchange", "capital", "money", "crypto", "dex", "amm", "liquid", "stake", "farm",
        "core", "app", "global", "official", "v1", "v2", "v3", "v4",
        "ethereum", "arbitrum", "optimism", "polygon", "base", "bsc", "avalanche",
        "sonic", "unichain", "berachain", "hyperliquid", "hyperevm",
    }
)
_MODE_A_CORE_CONTRACT_HINTS: Tuple[str, ...] = (
    "vault", "pool", "router", "factory", "lending", "staking", "market", "controller",
    "manager", "treasury", "bridge", "exchange", "swap", "farm", "strategy", "escrow",
    "distributor", "comptroller", "clearing", "perpetual", "perp", "margin", "borrow",
)
_MODE_A_SOURCIFY_COLD_SEM: threading.BoundedSemaphore = threading.BoundedSemaphore(1)


def _lookup_mode_a_sourcify_contracts(
    base_slug: str,
    chain: str,
    meta: Mapping[str, Any],
    *,
    parquet_root: Optional[Path] = None,
    timeout_sec: float = 4.0,
) -> List[str]:
    """
    Mode A 0-주소 프로토콜을 외부 HTTP 스크래핑 없이 로컬 Sourcify v2 Parquet(DuckDB)의
    컨트랙트명·체인 배포 테이블로 즉시 보완해 LLM Web Search 왕복 없이 Stage 4로 직행시킨다.
    """
    c = _norm_chain(chain)
    cid = CHAIN_IDS.get(c, 0)
    p_root = parquet_root or SOURCIFY_PARQUET_DIR
    if cid <= 0 or not DUCKDB_BIN.is_file() or not _has_sourcify_corpus_files(p_root):
        return []
    raw_tokens: List[str] = []
    for raw_s in (base_slug, str(meta.get("name") or ""), str(meta.get("symbol") or "")):
        s_low = str(raw_s or "").strip().lower()
        if not s_low:
            continue
        compact = re.sub(r"[^a-z0-9]", "", s_low)
        if len(compact) >= 5 and compact not in _MODE_A_SOURCIFY_STOPWORDS and not compact.isdigit():
            raw_tokens.append(compact)
        for part in re.split(r"[^a-z0-9]+", s_low):
            if len(part) >= 5 and part not in _MODE_A_SOURCIFY_STOPWORDS and not part.isdigit():
                raw_tokens.append(part)
    stems = list(dict.fromkeys(raw_tokens))[:3]
    if not stems:
        return []
    try:
        f_counts, c_types, _d_cols, ct_cols, _cf, addr_proj = _unpack_sourcify_base_schema(p_root, cid)
    except Exception:
        return []
    cc_cols = c_types.get("compiled_contracts") or {}
    if (
        int(f_counts.get("compiled_contracts", 0)) <= 0
        or int(f_counts.get("contracts", 0)) <= 0
        or int(f_counts.get("contract_deployments", 0)) <= 0
        or "name" not in cc_cols
        or "runtime_code_hash" not in cc_cols
        or "runtime_code_hash" not in ct_cols
    ):
        return []
    like_preds: List[str] = []
    for st in stems:
        st_q = _sql_quote_str(f"{st}%")
        like_preds.append(f"cname_norm LIKE {st_q}")
    core_cond = " OR ".join(f"cname_norm LIKE {_sql_quote_str(f'%{h}%')}" for h in _MODE_A_CORE_CONTRACT_HINTS)
    where_name = " OR ".join(like_preds)
    ct_blob = "BLOB" in ct_cols.get("runtime_code_hash", "")
    cc_blob = "BLOB" in cc_cols.get("runtime_code_hash", "")
    cache_dir_sf = ARTIFACT_ROOT / "_cache"
    usable_comp_p = cache_dir_sf / "sourcify_usable_comp_v1.parquet"
    is_large_corpus = int(f_counts.get("compiled_contracts", 0)) > 4
    if parquet_root is None and ct_blob and is_large_corpus and not usable_comp_p.is_file():
        with _MODE_A_SOURCIFY_COLD_SEM:
            if not usable_comp_p.is_file():
                try:
                    cd_cols = c_types.get("code") or {}
                    usable_cids_sql = ", ".join(
                        str(cid_u) for ch_u, cid_u in sorted(CHAIN_IDS.items()) if _usable_chain(ch_u) and cid_u > 0
                    )
                    rch_p = _ensure_usable_chain_rch_index(
                        p_root,
                        cache_dir_sf,
                        f_counts,
                        ct_cols.get("runtime_code_hash", "BLOB"),
                        cd_cols.get("code_hash", ""),
                        usable_cids_sql,
                    )
                    if rch_p is not None:
                        _ensure_usable_chain_comp_index(p_root, cache_dir_sf, f_counts, cc_cols, rch_p)
                except _RECOVERABLE_IO_EXC:
                    pass
    use_fast_comp = usable_comp_p.is_file() and ct_blob and (parquet_root is None)
    if use_fast_comp:
        uc_q = _sql_quote_str(usable_comp_p.resolve().as_posix())
        comp_cte = (
            "SELECT DISTINCT rch_blob AS rch_key, lower(replace(CAST(cname AS VARCHAR), '_', '')) AS cname_norm "
            f"FROM read_parquet({uc_q}) WHERE cname IS NOT NULL"
        )
        join_on = "ct.runtime_code_hash = cmat.rch_key"
    else:
        cc_rch_e = "cc.runtime_code_hash" if (cc_blob and ct_blob) else (
            "lower(hex(cc.runtime_code_hash))" if cc_blob else "lower(replace(CAST(cc.runtime_code_hash AS VARCHAR), '0x', ''))"
        )
        ct_rch_e = "ct.runtime_code_hash" if (cc_blob and ct_blob) else (
            "lower(hex(ct.runtime_code_hash))" if ct_blob else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', ''))"
        )
        comp_cte = (
            f"SELECT DISTINCT {cc_rch_e} AS rch_key, lower(replace(CAST(cc.name AS VARCHAR), '_', '')) AS cname_norm "
            "FROM compiled_contracts cc WHERE cc.runtime_code_hash IS NOT NULL AND cc.name IS NOT NULL"
        )
        join_on = f"{ct_rch_e} = cmat.rch_key"
    sql = f"""
    WITH cmat AS (
        SELECT rch_key, cname_norm FROM ({comp_cte}) t
        WHERE ({where_name})
    )
    SELECT
        CAST(d.chain_id AS BIGINT) AS cid,
        {addr_proj} AS addr_hex,
        CASE WHEN ({core_cond}) THEN 1 ELSE 0 END AS is_core
    FROM cmat
    JOIN contracts ct ON {join_on}
    JOIN contract_deployments d ON d.contract_id = ct.id
    WHERE CAST(d.chain_id AS BIGINT) = {cid}
    ORDER BY is_core DESC
    LIMIT 24
    """
    if use_fast_comp or not is_large_corpus:
        rows = _run_duckdb_cli_json(sql, parquet_root=p_root, timeout_sec=timeout_sec)
    else:
        with _MODE_A_SOURCIFY_COLD_SEM:
            rows = _run_duckdb_cli_json(sql, parquet_root=p_root, timeout_sec=max(float(timeout_sec), 12.0))
    if not rows:
        return []
    infra_excl = set(_infra_addresses_for_chain(c))
    out: List[str] = []
    seen_out: Set[str] = set()
    for r in rows:
        parsed = _parse_usable_sourcify_row(r)
        if parsed is None:
            continue
        addr_n = parsed[2]
        if addr_n and _is_non_precompile_addr(addr_n) and addr_n not in infra_excl:
            _append_unique(out, seen_out, addr_n)
            if len(out) >= 16:
                break
    return out


def _resolve_protocol_addresses(
    router: RPCRouter,
    slug: str,
    chain: str,
    initial_addrs: Sequence[str],
    store: Optional[SQLiteStore] = None,
    block_pin: int = 0,
    fetch_text_fn: Optional[Callable[[str], str]] = None,
) -> List[str]:
    """
    온체인 기계적 시드·영수증 해석 + 런타임 에이전트(Web Search 도구 전용) 연동 주소 해석기:
      - 실전 런타임(`fetch_text_fn is None`)에서는 파이썬 직접 HTTP 웹 스크래핑을 일절 수행하지 않으며,
        0순위 `discovered_addresses.json`(에이전트 Web Search 도구 제출본 — 공식 Docs 1순위) -> 캐시 ->
        기계적 시드(`initial_addrs`·메타 주소·온체인 `tx_hashes` 영수증)만 온체인 `eth_getCode`로 검증한다.
        미식별 시 빈 리스트(`[]`)를 반환해 `address_request.json`으로 에이전트의 Web Search 도구에 위임한다.
      - 콜백 주입(`fetch_text_fn is not None`) 시 4단계 우선순위(`Docs -> GitBook -> GitHub -> DeFiLlama`)로 병합한다.
    """
    slug = _norm_slug(slug)
    c = _norm_chain(chain)
    st = store or getattr(router, "store", None)
    base_slug = _strip_chain_suffix_slug(slug)
    meta: Dict[str, Any] = st.get_proto_meta(slug) if st is not None else {}
    if not meta and st is not None and base_slug != slug:
        meta = st.get_proto_meta(base_slug)
    is_mode_b = (
        slug.startswith(("modeb-", "case-"))
        or bool(meta.get("mode_b_zero_seed"))
        or bool(meta.get("tx_hashes"))
    )
    hint_blocks = _extract_mode_b_hint_blocks(router, c, meta, block_pin) if (is_mode_b and block_pin > 0) else None
    cache_key = f"resolved_addrs_{c}"

    # 0순위: 에이전트가 Web Search 도구로 작성한 discovered_addresses.json 확인
    disc_file = ARTIFACT_ROOT / slug / "discovered_addresses.json"
    agent_addrs, agent_confirmed_none = _extract_agent_discovered_addresses(disc_file)
    if agent_confirmed_none:
        return []
    if agent_addrs and fetch_text_fn is None:
        merged_agent = list(
            dict.fromkeys(
                na
                for a in [*agent_addrs, *initial_addrs]
                if (na := _norm_addr(a)) and _is_non_precompile_addr(na)
            )
        )[:16]
        if block_pin <= 0:
            return merged_agent
        onchain_agent, onchain_agent_ok = _filter_onchain_contract_addrs(
            router,
            c,
            merged_agent,
            block_pin,
            allow_historical_mode_b=is_mode_b,
            hint_blocks=hint_blocks,
        )
        if onchain_agent:
            if st is not None and onchain_agent_ok:
                meta[cache_key] = list(onchain_agent)
                st.put_proto_meta_batch([(slug, meta)])
            return onchain_agent

    if fetch_text_fn is None and isinstance(meta.get(cache_key), list) and meta[cache_key]:
        cached_list = [nx for x in meta[cache_key] if (nx := _norm_addr(x))]
        if cached_list:
            return cached_list

    mech_seeds: List[str] = []
    seen_mech: Set[str] = set()
    for cand_a in [*agent_addrs, *initial_addrs]:
        na = _norm_addr(cand_a)
        if na and _is_non_precompile_addr(na):
            _append_unique(mech_seeds, seen_mech, na)
    for meta_a in _extract_mechanical_meta_addresses(meta, c, is_root_slug=(slug == base_slug)):
        _append_unique(mech_seeds, seen_mech, meta_a)

    ordered_candidates: List[str] = []
    seen_ordered_cands: Set[str] = set()

    if fetch_text_fn is not None:
        infra_excl = set() if is_mode_b else set(_infra_addresses_for_chain(c))
        llama_detail_text = ""
        if not meta.get("url") and not meta.get("github") and not meta.get("module"):
            for cand_slug in dict.fromkeys((base_slug, slug)):
                try:
                    raw_llama = fetch_text_fn(f"https://api.llama.fi/protocol/{urllib.parse.quote(cand_slug)}")
                    if raw_llama:
                        llama_detail_text = raw_llama
                        try:
                            pdoc = json.loads(raw_llama)
                            if isinstance(pdoc, dict):
                                gh_v = pdoc.get("github")
                                gh_l = [str(g).strip() for g in gh_v if str(g).strip()] if isinstance(gh_v, list) else ([str(gh_v).strip()] if gh_v else [])
                                meta = {
                                    **meta,
                                    "url": str(pdoc.get("url") or meta.get("url") or "").strip(),
                                    "github": gh_l or meta.get("github") or [],
                                    "module": str(pdoc.get("module") or meta.get("module") or "").strip(),
                                    "address": str(pdoc.get("address") or meta.get("address") or "").strip(),
                                }
                        except _PARSE_DATA_EXC:
                            pass
                        break
                except Exception:
                    continue

        def _harvest_from_callback(urls: Sequence[str], max_urls: int = 4, max_addrs: int = 16) -> Tuple[List[str], List[str]]:
            addrs_found: List[str] = []
            seen_found: Set[str] = set()
            texts_collected: List[str] = []
            for u in list(dict.fromkeys(filter(None, urls)))[:max_urls]:
                try:
                    txt = fetch_text_fn(u)
                except Exception:
                    continue
                if not txt:
                    continue
                texts_collected.append(txt)
                for ad in _extract_addresses_from_text(txt):
                    if _is_non_precompile_addr(ad) and ad not in infra_excl:
                        _append_unique(addrs_found, seen_found, ad)
                        if len(addrs_found) >= max_addrs:
                            break
                if len(addrs_found) >= max_addrs:
                    break
            return addrs_found, texts_collected

        stage1_addrs, stage1_texts = _harvest_from_callback(_stage1_official_doc_urls(meta), max_urls=6)
        discovered_gitbooks: List[str] = []
        seen_gitbooks: Set[str] = set()
        discovered_gh_repos: List[str] = []
        seen_gh_repos: Set[str] = set()

        def _harvest_gh_repos(txt_s: str) -> None:
            for gh_m in _GITHUB_REPO_RE.findall(txt_s):
                clean_repo = gh_m.strip("/").replace(".git", "")
                if clean_repo and not clean_repo.lower().startswith("defillama/"):
                    _append_unique(discovered_gh_repos, seen_gh_repos, clean_repo)

        for txt in [*stage1_texts, llama_detail_text]:
            if not txt:
                continue
            for gb_m in _GITBOOK_URL_RE.findall(txt):
                _append_unique(discovered_gitbooks, seen_gitbooks, gb_m.rstrip("/"))
            _harvest_gh_repos(txt)
            for doc_m in _DOCS_LINK_RE.findall(txt):
                if "gitbook.io" in doc_m.lower():
                    _append_unique(discovered_gitbooks, seen_gitbooks, doc_m.rstrip("/"))

        stage2_addrs, stage2_texts = _harvest_from_callback(
            _stage2_gitbook_urls(meta, base_slug, discovered_gitbooks, include_guessed_slug_host=True),
            max_urls=4,
        )
        for txt in stage2_texts:
            _harvest_gh_repos(txt)
        stage3_addrs, _ = _harvest_from_callback(
            _stage3_github_raw_urls(meta, base_slug, discovered_gh_repos),
            max_urls=4,
        )
        stage4_addrs, _ = _harvest_from_callback(
            _stage4_defillama_urls(meta, base_slug, include_llama_api=(not bool(llama_detail_text))),
            max_urls=3,
        )
        seen_stage4: Set[str] = set(stage4_addrs)
        if llama_detail_text:
            for ad in _extract_addresses_from_text(llama_detail_text):
                if _is_non_precompile_addr(ad) and ad not in infra_excl:
                    _append_unique(stage4_addrs, seen_stage4, ad)

        for cand_a in [*agent_addrs, *stage1_addrs, *stage2_addrs, *stage3_addrs, *stage4_addrs, *mech_seeds]:
            _append_unique(ordered_candidates, seen_ordered_cands, cand_a)
    else:
        for cand_a in mech_seeds:
            _append_unique(ordered_candidates, seen_ordered_cands, cand_a)

    if not ordered_candidates and block_pin > 0:
        tx_list = [
            str(th).strip().lower()
            for th in (meta.get("tx_hashes") or [])
            if isinstance(th, str) and _ANY_TX_HASH_RE.match(str(th).strip())
        ]
        if tx_list:
            try:
                tx_chunks = [tx_list[off_tx : off_tx + 32] for off_tx in range(0, len(tx_list), 32)]

                def _fetch_rcpt_chunk(chunk_tx: List[str]) -> List[Any]:
                    return router.batch_call(
                        c,
                        [("eth_getTransactionReceipt", [th]) for th in chunk_tx],
                        block_pin=0,
                        need_archive=True,
                    )

                rcpt_res: List[Any] = []
                for part_tx in _map_chunks_live(router, _fetch_rcpt_chunk, tx_chunks, max_workers=8):
                    rcpt_res.extend(part_tx)
                infra_set = _infra_addresses_for_chain(c)
                for rcpt in rcpt_res:
                    if not isinstance(rcpt, dict):
                        continue
                    sender_a = _norm_addr(rcpt.get("from"))
                    for cand_raw in (
                        rcpt.get("to"),
                        rcpt.get("contractAddress"),
                        *(lg.get("address") for lg in (rcpt.get("logs") or []) if isinstance(lg, dict)),
                    ):
                        ca = _norm_addr(cand_raw)
                        if ca and _is_non_precompile_addr(ca) and ca != sender_a and ca not in infra_set:
                            _append_unique(ordered_candidates, seen_ordered_cands, ca)
            except _RECOVERABLE_IO_EXC:
                pass
    if not ordered_candidates and not is_mode_b and fetch_text_fn is None:
        try:
            sf_addrs = _lookup_mode_a_sourcify_contracts(base_slug, c, meta)
        except Exception:
            sf_addrs = []
        if sf_addrs:
            if block_pin > 0 and len(sf_addrs) > 1 and _is_live_real_router(router):
                try:
                    sf_hints = _probe_clone_liquid_balance_hints(router, [(c, a) for a in sf_addrs])
                    funded_sf = [a for a in sf_addrs if _to_dec(sf_hints.get((c, a), _DEC_ZERO)) >= PROFIT_FLOOR_DEC]
                    if funded_sf:
                        sf_addrs = sorted(funded_sf, key=lambda a: -_to_dec(sf_hints.get((c, a), _DEC_ZERO)))
                except _RECOVERABLE_IO_EXC:
                    pass
            for ca_sf in sf_addrs:
                _append_unique(ordered_candidates, seen_ordered_cands, ca_sf)

    if not ordered_candidates:
        return []

    final_addrs_ok = True
    if block_pin > 0:
        final_addrs, final_addrs_ok = _filter_onchain_contract_addrs(
            router,
            c,
            ordered_candidates,
            block_pin,
            allow_historical_mode_b=is_mode_b,
            hint_blocks=hint_blocks,
        )
    else:
        final_addrs = ordered_candidates

    if st is not None and fetch_text_fn is None and block_pin > 0 and final_addrs and final_addrs_ok:
        meta[cache_key] = list(final_addrs)
        try:
            if not getattr(st, "_closed", False):
                st.put_proto_meta_batch([(slug, meta)])
        except sqlite3.Error:
            pass
    return list(final_addrs)


_TEST_CID_FILE_RE: re.Pattern[str] = re.compile(r"^test_(\d+)\.t\.sol$")
_POC_REQ_CID_FILE_RE: re.Pattern[str] = re.compile(r"^poc_request_(\d+)\.json$")
_VERDICT_CID_FILE_RE: re.Pattern[str] = re.compile(r"^verdict_(\d+)\.json$")
_SOL_CALL_INTERACTION_RE: re.Pattern[str] = re.compile(r"\.\s*(?:call|staticcall)\s*[\({]")


@contextlib.contextmanager
def _try_slug_lock(slug_dir: Path) -> Iterator[bool]:
    """병렬 터미널 세션 간 동일 슬러그 디렉토리 중복 실행 방지용 비차단(Non-blocking) 파일 락."""
    slug_dir.mkdir(parents=True, exist_ok=True)
    lock_file = slug_dir / ".slug.lock"
    try:
        with _exclusive_file_lock(lock_file, timeout_sec=0.2):
            yield True
    except TimeoutError:
        yield False


