                                    closure_addrs=vcid_closure_addrs,
                                    live_head_seed_addrs=lh_seeds,
                                    allowed_caller=vcid_caller,
                                    calldata_len=est_calldata_len,
                                    gas_price_wei=gas_price_w,
                                    acct_in=acct_cand,
